@Composable
fun ReorderableItem(
    modifier: Modifier = Modifier,
    content: @Composable ReorderableListItemScope.() -> Unit,
) {
    Box(
        modifier = modifier
            .onGloballyPositioned { cord ->
                state.itemIntervals[index] = when (orientation) {
                    Orientation.Vertical -> ItemInterval(
                        start = cord.positionInParent().y, size = cord.size.height
                    )

                    Orientation.Horizontal -> ItemInterval(
                        start = cord.positionInParent().x, size = cord.size.width
                    )
                }
            }
            .graphicsLayer {
                when (orientation) {
                    Orientation.Vertical -> translationY = state.itemOffsets[index].value

                    Orientation.Horizontal -> translationX = state.itemOffsets[index].value
                }

            }
            .zIndex(if (isAnimating) 1f else 0f),
    ) {
        ReorderableListItemScopeImpl(
            state = this@ReorderableListScope.state,
            index = this@ReorderableListScope.index
        ).content()
    }
}

@Composable
fun rememberScroller(
    scrollableState: ScrollableState,
    pixelAmount: Float,
    duration: Long = 100,
): Scroller {
    return rememberScroller(scrollableState, { pixelAmount }, duration)
}

@Composable
fun rememberScroller(
    scrollableState: ScrollableState,
    pixelPerSecond: Float,
): Scroller {
    val scope = rememberCoroutineScope()
    val pixelPerSecondUpdated = rememberUpdatedState(pixelPerSecond)

    return remember(scrollableState, scope) {
        Scroller(
            scrollableState,
            scope,
            pixelPerSecondProvider = { pixelPerSecondUpdated.value },
        )
    }
}

@Composable
fun rememberScroller(
    scrollableState: ScrollableState,
    pixelAmountProvider: () -> Float,
    duration: Long = 100,
): Scroller {
    val scope = rememberCoroutineScope()
    val pixelAmountProviderUpdated = rememberUpdatedState(pixelAmountProvider)
    val durationUpdated = rememberUpdatedState(duration)

    return remember(scrollableState, scope, duration) {
        Scroller(
            scrollableState,
            scope,
            pixelPerSecondProvider = {
                pixelAmountProviderUpdated.value() / (durationUpdated.value / 1000f)
            },
        )
    }
}

