class WearPairingHandler(
	private val serverSettings: () -> ServerSettings?,
	private val pairInstall: suspend (installId: String) -> CResult<ServerSettings>,
	private val responder: PairingResponder,
) {
	fun isSignedIn(): Boolean {
		val settings = serverSettings() ?: return false
		return settings.userId >= 0 && !settings.bearerToken.isNullOrBlank()
	}

	suspend fun approve(nodeId: String, request: PairRequest): PairResponse {
		val response = when {
			request.version != PairingProtocol.VERSION ->
				PairResponse.Error(request.requestId, PairErrorCode.Unsupported)

			!isSignedIn() ->
				PairResponse.Error(request.requestId, PairErrorCode.NotSignedIn)

			else -> {
				val result = pairInstall(request.installId)
				if (isSuccess(result)) {
					PairResponse.Success(request.requestId, result.data)
				} else {
					PairResponse.Error(request.requestId, PairErrorCode.ServerRejected)
				}
			}
		}
		send(nodeId, response)
		return response
	}

	suspend fun decline(nodeId: String, request: PairRequest): PairResponse {
		val response = PairResponse.Error(request.requestId, PairErrorCode.Declined)
		send(nodeId, response)
		return response
	}

	/**
	 * Replies to a request this phone could not read, so the watch stops waiting. The request id is
	 * unknown precisely because the payload could not be decoded, so this answers with a blank one,
	 * which the watch matches against whatever it has pending.
	 */
	suspend fun rejectUnreadable(nodeId: String) {
		send(nodeId, PairResponse.Error(requestId = "", code = PairErrorCode.Unsupported))
	}

	/** Replies when the confirmation cannot be shown, so the watch can tell the user what to do. */
	suspend fun reportUnavailable(nodeId: String, request: PairRequest) {
		send(nodeId, PairResponse.Error(request.requestId, PairErrorCode.PhoneUnavailable))
	}

	private suspend fun send(nodeId: String, response: PairResponse) {
		try {
			responder.respond(nodeId, response)
		} catch (e: CancellationException) {
			throw e
		} catch (@Suppress("TooGenericExceptionCaught") e: Exception) {
			// The watch may have gone out of range; it can retry from its own screen.
			Napier.w("Failed to reply to the watch", e)
		}
	}
}

suspend fun rejectUnreadable(nodeId: String) {
	send(nodeId, PairResponse.Error(requestId = "", code = PairErrorCode.Unsupported))
}

suspend fun reportUnavailable(nodeId: String, request: PairRequest) {
	send(nodeId, PairResponse.Error(request.requestId, PairErrorCode.PhoneUnavailable))
}

class WearPairingListenerService : WearableListenerService(), KoinComponent {

	private val handler: WearPairingHandler by inject()
	private val appScope: CoroutineScope by inject(named(APP_SCOPE))

	override fun onMessageReceived(event: MessageEvent) {
		if (event.path != PairingProtocol.REQUEST_PATH) return

		val request = PairingProtocol.decodeRequest(event.data)
		if (request == null) {
			appScope.launch { handler.rejectUnreadable(event.sourceNodeId) }
			return
		}

		val intent = WearPairingActivity.createIntent(this, event.sourceNodeId, event.data)
		val appVisible = ProcessLifecycleOwner.get().lifecycle.currentState.isAtLeast(Lifecycle.State.STARTED)
		if (appVisible) {
			startActivity(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
		} else if (!showNotification(intent, request.requestId)) {
			// Nothing can put the prompt in front of the user, so answer instead of leaving the
			// watch waiting on a confirmation that will never appear.
			appScope.launch { handler.reportUnavailable(event.sourceNodeId, request) }
		}
	}

	/** False when the prompt could not be raised, so the caller can answer the watch instead. */
	@SuppressLint("MissingPermission")
	private fun showNotification(intent: Intent, requestId: String): Boolean {
		if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&
			checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED
		) {
			Napier.w("Cannot show the watch pairing prompt: notification permission not granted")
			return false
		}

		val notificationId = WearPairingActivity.notificationId(requestId)
		val manager = NotificationManagerCompat.from(this)
		manager.createNotificationChannel(
			NotificationChannelCompat.Builder(CHANNEL_ID, NotificationManagerCompat.IMPORTANCE_HIGH)
				.setName(getString(R.string.wear_pairing_channel_name))
				.build()
		)

		val pendingIntent = PendingIntent.getActivity(
			this,
			notificationId,
			intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
			PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
		)
		val notification = NotificationCompat.Builder(this, CHANNEL_ID)
			.setSmallIcon(R.drawable.ic_launcher_monochrome)
			.setContentTitle(getString(R.string.wear_pairing_notification_title))
			.setContentText(getString(R.string.wear_pairing_notification_text))
			.setContentIntent(pendingIntent)
			.setAutoCancel(true)
			.setPriority(NotificationCompat.PRIORITY_HIGH)
			.build()
		return try {
			manager.notify(notificationId, notification)
			true
		} catch (@Suppress("SwallowedException") e: SecurityException) {
			Napier.w("Cannot show the watch pairing prompt", e)
			false
		}
	}

	private companion object {
		const val CHANNEL_ID = "wear_pairing"
	}
}

