private fun subtractBlocked(start: Int, end: Int, blockers: List<SourceRange>): List<SourceRange> {
	if (end <= start) return emptyList()
	if (blockers.isEmpty()) return listOf(SourceRange(start, end))
	val out = ArrayList<SourceRange>()
	var cursor = start
	for (b in blockers) {
		if (b.endExclusive <= cursor) continue
		if (b.start >= end) break
		if (b.start > cursor) out += SourceRange(cursor, minOf(b.start, end))
		cursor = maxOf(cursor, b.endExclusive)
		if (cursor >= end) break
	}
	if (cursor < end) out += SourceRange(cursor, end)
	return out
}

private fun boundaryScore(tokens: List<Token>, start: Int, len: Int): Int {
	var score = 0
	if (start == 0 || tokens[start - 1].text.endsWith('\n')) score++
	if (start + len == tokens.size || tokens[start + len - 1].text.endsWith('\n')) score++
	return score
}

internal data class Token(
	val text: String,
	val plainStart: Int,
) {
	val plainEnd: Int get() = plainStart + text.length
}

internal fun tokenize(text: String): List<Token> {
	if (text.isEmpty()) return emptyList()

	val tokens = ArrayList<Token>(text.length / 4)
	var i = 0
	while (i < text.length) {
		val start = i
		val c = text[i]
		when {
			c.isWhitespace() -> {
				while (i < text.length && text[i].isWhitespace()) i++
			}

			c.isLetterOrDigit() || c == '_' || c == '\'' -> {
				// `'` keeps contractions like "don't" as one token.
				while (i < text.length && (text[i].isLetterOrDigit() || text[i] == '_' || text[i] == '\'')) i++
			}

			else -> {
				// Punctuation / symbols: one char per token so each piece can change independently.
				i++
			}
		}
		tokens.add(Token(text = text.substring(start, i), plainStart = start))
	}
	return tokens
}

