object IdeaHasher {
	fun hash(idea: StoryIdea): String {
		val buf = ByteArray(4)
		val d = Algorithm.MurmurHash3_X64_128().createDigest()

		d.update(idea.id.id, buf)
		d.update(idea.created.epochSeconds, buf)
		d.update(idea.updated.epochSeconds, buf)

		if (idea.title != null) {
			d.update(1, buf)
			d.update(idea.title, buf)
		} else {
			d.update(0, buf)
		}

		d.update(idea.content, buf)

		if (idea.tags.isNotEmpty()) {
			d.update(idea.tags.size, buf)
			idea.tags.sorted().forEach { tag -> d.update(tag, buf) }
		}

		if (idea.promoted != null) {
			d.update(1, buf)
			d.update(idea.promoted.epochSeconds, buf)
		} else {
			d.update(0, buf)
		}

		if (idea.archived != null) {
			d.update(1, buf)
			d.update(idea.archived.epochSeconds, buf)
		} else {
			d.update(0, buf)
		}

		return d.digest().base64Url
	}
}

object ProjectDataHasher {
	fun hash(data: ProjectData): String {
		val buf = ByteArray(4)
		val d = Algorithm.MurmurHash3_X64_128().createDigest()

		if (data.authorName != null) {
			d.update(1, buf)
			d.update(data.authorName, buf)
		} else {
			d.update(0, buf)
		}

		if (data.theme != null) {
			d.update(1, buf)
			d.update(data.theme.primary, buf)
			d.update(data.theme.secondary, buf)
		} else {
			d.update(0, buf)
		}

		if (data.wordCountGoal != null) {
			d.update(1, buf)
			d.update(data.wordCountGoal.cadence.ordinal, buf)
			d.update(data.wordCountGoal.count, buf)
		} else {
			d.update(0, buf)
		}

		// No presence byte, unlike the fields above: an empty set must contribute zero bytes so
		// tag-less data keeps its pre-tags hash (stored lastSyncedHash baselines and server rows
		// were computed without this field). Sorted for a canonical order across devices; the
		// size prefix keeps ["ab"] and ["a","b"] distinct.
		if (data.tags.isNotEmpty()) {
			d.update(data.tags.size, buf)
			data.tags.sorted().forEach { tag -> d.update(tag, buf) }
		}

		// Zero bytes when null, same rule as tags: pre-language hashes must stay identical.
		// The -1 marker can never be a tags size and the length prefix bounds the string,
		// so a language block cannot be read as a continuation of the tags block
		// (tags=["x"] and language="x" must not collide).
		if (data.language != null) {
			d.update(-1, buf)
			d.update(data.language.length, buf)
			d.update(data.language, buf)
		}

		// Zero bytes at the default (true): pre-existing hashes must stay identical.
		// -2 marker: -1 is taken by the language block.
		if (!data.encyclopediaDictionary) {
			d.update(-2, buf)
		}

		// Zero bytes when empty, same rule as tags. -3 marker: -1 and -2 are taken. Each word
		// carries its length: update(String) writes bare char codes, so without it
		// {"a","bc"} and {"ab","c"} would collide.
		if (data.dictionaryWords.isNotEmpty()) {
			d.update(-3, buf)
			d.update(data.dictionaryWords.size, buf)
			data.dictionaryWords.sorted().forEach { word ->
				d.update(word.length, buf)
				d.update(word, buf)
			}
		}

		return d.digest().base64Url
	}
}

private object ProseParagraphProvider : TrimmingInlineHolderProvider() {
	override fun openTag(visitor: HtmlGenerator.HtmlGeneratingVisitor, text: String, node: ASTNode) {
		visitor.consumeTagOpen(node, "p")
	}

	override fun closeTag(visitor: HtmlGenerator.HtmlGeneratingVisitor, text: String, node: ASTNode) {
		visitor.consumeTagClose("p")
	}

	override fun processNode(
		visitor: HtmlGenerator.HtmlGeneratingVisitor,
		text: String,
		node: ASTNode,
	) {
		val children = childrenToRender(node)
		openTag(visitor, text, node)

		children.forEachIndexed { index, child ->
			when {
				// An edge newline would only open or close an empty paragraph.
				child.type == MarkdownTokenTypes.EOL -> {
					if (index != 0 && index != children.lastIndex) {
						closeTag(visitor, text, node)
						openTag(visitor, text, node)
					}
				}

				// The trailing spaces of a hard break are redundant: the newline itself breaks here.
				child.type == MarkdownTokenTypes.HARD_LINE_BREAK -> Unit

				child is LeafASTNode -> visitor.visitLeaf(child)
				else -> child.accept(visitor)
			}
		}

		closeTag(visitor, text, node)
	}
}

private class ProseContainerProvider(
	tag: String,
	private val keepBlankLines: Boolean,
) : SimpleTagProvider(tag) {
	override fun processNode(
		visitor: HtmlGenerator.HtmlGeneratingVisitor,
		text: String,
		node: ASTNode,
	) {
		openTag(visitor, text, node)

		var newlines = 0
		var afterParagraph = false
		for (child in node.children) {
			when (child.type) {
				MarkdownTokenTypes.EOL -> newlines++
				// A quote's own '>' markers sit between the lines they mark, and neither they nor
				// stray indentation say anything about how far apart two passages are.
				MarkdownTokenTypes.WHITE_SPACE, MarkdownTokenTypes.BLOCK_QUOTE -> Unit
				else -> {
					val isParagraph = child.type == MarkdownElementTypes.PARAGRAPH
					if (afterParagraph && isParagraph) {
						val blanks = (newlines - 1).coerceIn(0, ProseHtml.MAX_CONSECUTIVE_BREAKS)
						val breaks = when {
							keepBlankLines -> blanks
							blanks >= 2 -> 1
							else -> 0
						}
						repeat(breaks) { visitor.consumeHtml(BREAK) }
					}
					child.accept(visitor)
					afterParagraph = isParagraph
					newlines = 0
				}
			}
		}

		closeTag(visitor, text, node)
	}

	private companion object {
		const val BREAK = "<br />"
	}
}

fun countWords(text: String): Int {
	var count = 0
	var counted = false
	for (char in text) {
		if (char.isWhitespace()) {
			counted = false
		} else if (!counted && char.isLetterOrDigit()) {
			counted = true
			count++
		}
	}
	return count
}

object EmailValidator {
	// Simple email pattern that checks for basic format: something@something
	// The local part can't contain @, and domain must have at least one character
	// More comprehensive RFC 5322 regex is available but often overkill for user validation
	private val emailPattern = Regex("^[A-Za-z0-9+_.-]+@[^@]+$")

	/**
	 * Validates an email address format.
	 *
	 * @param email The email address to validate
	 * @return true if the email format is valid, false otherwise
	 */
	fun validate(email: String): Boolean {
		val trimmedInput = email.trim()
		return trimmedInput.isNotBlank() && emailPattern.matches(trimmedInput)
	}
}

fun validate(email: String): Boolean {
	val trimmedInput = email.trim()
	return trimmedInput.isNotBlank() && emailPattern.matches(trimmedInput)
}

object PasswordValidator {
	const val MIN_LENGTH = 8
	const val MAX_LENGTH = 64

	/**
	 * Validates a password and returns the first validation failure found,
	 * or [PasswordValidationResult.VALID] if all requirements are met.
	 *
	 * Current requirements:
	 * - Length between [MIN_LENGTH] and [MAX_LENGTH] characters
	 *
	 * Note: Additional requirements (uppercase, lowercase, number, special char)
	 * can be enabled by uncommenting the relevant checks below.
	 */
	fun validate(password: String): PasswordValidationResult {
		val trimmedInput = password.trim()
		return when {
			trimmedInput.length < MIN_LENGTH -> PasswordValidationResult.TOO_SHORT
			trimmedInput.length > MAX_LENGTH -> PasswordValidationResult.TOO_LONG
			// Uncomment to enable additional password requirements:
			// !trimmedInput.any { it.isUpperCase() } -> PasswordValidationResult.NO_UPPERCASE
			// !trimmedInput.any { it.isLowerCase() } -> PasswordValidationResult.NO_LOWERCASE
			// !trimmedInput.any { it.isDigit() } -> PasswordValidationResult.NO_NUMBER
			// !trimmedInput.any { !it.isLetterOrDigit() } -> PasswordValidationResult.NO_SPECIAL
			else -> PasswordValidationResult.VALID
		}
	}
}

