private fun tableFallback(block: ProseBlock.Table) {
	(listOf(block.header) + block.rows).forEach { row ->
		paragraph(style = null, numId = null) {
			row.forEachIndexed { index, cell ->
				if (index > 0) writer.w("r") { w("t") { text("\t") } }
				runs(cell)
			}
		}
	}
}

