internal fun argbHexToPdfColor(argb: String): PdfColor? {
	val hex = argb.trim().removePrefix("#")
	val rgb = when (hex.length) {
		6 -> hex
		8 -> hex.substring(2)
		else -> return null
	}
	val value = rgb.toIntOrNull(16) ?: return null
	return PdfColor(
		((value shr 16) and 0xFF) / 255f,
		((value shr 8) and 0xFF) / 255f,
		(value and 0xFF) / 255f,
	)
}

private fun themeColor(argb: String?): RtfColor? {
	val css = argb?.let(::argbHexToCssHex)?.removePrefix("#") ?: return null
	val value = css.toIntOrNull(16) ?: return null
	return RtfColor.fromRgb(value)
}

private fun renderMarkdownRtf(
	markdown: String,
	primary: RtfColor?,
	secondary: RtfColor?,
	keepBlankLines: Boolean,
): List<RtfBlock> {
	val blocks = mutableListOf<RtfBlock>()
	val parsed = parseProseMarkdown(markdown, keepBlankLines)
	parsed.forEachIndexed { index, block ->
		// Prose runs tight: the indent parts one line from the next, and the space a passage break
		// wants is a blank line the author actually typed. Space after is for leaving prose behind.
		val runsOn = parsed.getOrNull(index + 1)?.isProseLine == true
		val proseSpaceAfter = if (runsOn) 0 else PARAGRAPH_SPACE_AFTER
		when (block) {
			is ProseBlock.Paragraph -> blocks += bodyParagraph(block.spans, primary, proseSpaceAfter)
			ProseBlock.Blank -> blocks += bodyParagraph(emptyList(), primary, proseSpaceAfter)
			is ProseBlock.Heading -> blocks += headingParagraph(block, primary, secondary)
			is ProseBlock.Listing -> {
				val numbering = RtfListNumbering()
				block.items.forEach { blocks += listParagraph(it, numbering, primary) }
			}

			is ProseBlock.Quote -> block.paragraphs.forEach { blocks += quoteParagraph(it, primary) }
			is ProseBlock.CodeBlock -> codeBlockLines(block.code).forEach { blocks += codeParagraph(it) }
			ProseBlock.Rule -> blocks += ruleParagraph()
			is ProseBlock.Table -> blocks += tableParagraphs(block, primary)
		}
	}
	return blocks
}

