internal class DraftDuplicateIdHandler(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
) : DuplicateIdHandler(projectDef, fileSystem) {
	override val kind = DuplicateIdKind.Draft

	private val draftsDir
		get() = projectDir / SceneDatasource.SCENE_DIRECTORY / SceneDraftsDatasource.DRAFTS_DIR

	override val entityType = EntityType.SceneDraft

	override fun ids(): Set<Int> = files().mapTo(mutableSetOf()) { it.def.id }

	private fun files(): List<DraftFile> =
		fileSystem.listOrNull(draftsDir).orEmpty()
			.mapNotNull { dir -> dir.name.toIntOrNull()?.takeIf { it > 0 && fileSystem.metadata(dir).isDirectory }?.let { dir to it } }
			.flatMap { (dir, sceneId) ->
				fileSystem.list(dir)
					.mapNotNull { path ->
						SceneDraftsDatasource.parseDraftFileName(path.name)
							?.takeIf { it.sceneId == sceneId }
							?.let { DraftFile(path, it, SceneDraftsDatasource.DRAFT_FILENAME_PATTERN.matchEntire(path.name) == null) }
					}
					.sortedWith(compareBy({ it.def.draftTimestamp }, { it.legacy }))
			}

	override fun findDuplicates(): List<DuplicateIdSet> =
		files().toDuplicateSets({ it.def.id }) { copyOf(it.path, it.def.draftName, readBytes(it.path)) }

	private data class DraftFile(val path: Path, val def: DraftDef, val legacy: Boolean)

	override fun canonicalPath(copy: DuplicateCopy, id: Int): HPath {
		val def = SceneDraftsDatasource.parseDraftFileName(copy.path.name) ?: error("Not a draft: ${copy.path}")
		return (draftsDir / def.sceneId.toString() / SceneDraftsDatasource.getFilename(def.copy(id = id))).toHPath()
	}
}

internal class NoteDuplicateIdHandler(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
	private val toml: Toml,
) : DuplicateIdHandler(projectDef, fileSystem) {
	override val kind = DuplicateIdKind.Note

	private val notesDir get() = projectDir / NotesDatasource.NOTES_DIRECTORY

	override val entityType = EntityType.Note

	override fun ids(): Set<Int> = files().mapTo(mutableSetOf()) { (_, _, note) -> note.id }

	// The id is in the content, so every note is read.
	private fun files(): List<Triple<Path, ByteString, NoteContent>> =
		listRecursivelyOrEmpty(notesDir).filterNotePathsOkio()
			.mapNotNull { path ->
				val bytes = readBytes(path)
				toml.decodeOrNull<NoteContainer>(bytes)?.note?.let { note -> Triple(path, bytes, note) }
			}
			.toList()

	override fun findDuplicates(): List<DuplicateIdSet> =
		files().toDuplicateSets({ (_, _, note) -> note.id }) { (path, bytes, note) ->
			copyOf(path, firstLine(note.content), bytes, text = note.content)
		}

	override fun canonicalPath(copy: DuplicateCopy, id: Int): HPath =
		(notesDir / NotesDatasource.getNoteFilenameFromId(id)).toHPath()

	override fun claim(copy: DuplicateCopy, owner: DuplicateCopy, oldId: Int, newId: Int): Set<Int> {
		val note = toml.decodeOrNull<NoteContainer>(readBytes(copy.path.toOkioPath()))?.note
			?: error("Note no longer parses: ${copy.path}")
		val rewritten = note.takeIf { it.id != newId }?.let { toml.encodeToString(NoteContainer(it.copy(id = newId))) }
		rewriteOrMove(copy.path, canonicalPath(copy, newId), rewritten)
		return emptySet()
	}

	private fun firstLine(content: String): String =
		content.lineSequence().map { it.trim() }.firstOrNull { it.isNotEmpty() }?.take(NAME_LENGTH) ?: ""

	private companion object {
		const val NAME_LENGTH = 60
	}
}

private fun files(): List<Triple<Path, ByteString, NoteContent>> =
	listRecursivelyOrEmpty(notesDir).filterNotePathsOkio()
		.mapNotNull { path ->
			val bytes = readBytes(path)
			toml.decodeOrNull<NoteContainer>(bytes)?.note?.let { note -> Triple(path, bytes, note) }
		}

internal abstract class DuplicateIdHandler(
	protected val projectDef: ProjectDef,
	protected val fileSystem: FileSystem,
) {
	abstract val kind: DuplicateIdKind

	/** The synced entity type this store's ids belong to, or null when it holds no entities of its own. */
	open val entityType: EntityType? = null

	/** Every id this store holds, read from filenames where the format allows. */
	open fun ids(): Set<Int> = emptySet()

	/** Sets with copies ordered the way this store's read path picks them. */
	abstract fun findDuplicates(): List<DuplicateIdSet>

	/** Where [copy] belongs when it is the one file holding [id]. */
	abstract fun canonicalPath(copy: DuplicateCopy, id: Int): HPath

	/**
	 * Moves [copy] to its canonical path for [newId], rewriting any id stored in its content.
	 * Returns other ids whose synced state changed as a result.
	 */
	open fun claim(copy: DuplicateCopy, owner: DuplicateCopy, oldId: Int, newId: Int): Set<Int> {
		move(copy.path, canonicalPath(copy, newId))
		return emptySet()
	}

	open fun discard(copy: DuplicateCopy, owner: DuplicateCopy): Discarded {
		fileSystem.delete(copy.path.toOkioPath())
		return Discarded()
	}

	protected fun move(from: HPath, to: HPath) {
		if (from != to) fileSystem.atomicMove(from.toOkioPath(), to.toOkioPath())
	}

	/** Writes [rewritten] to [target] and drops [from], or just moves [from] when null. */
	protected fun rewriteOrMove(from: HPath, target: HPath, rewritten: String?) {
		if (rewritten == null) return move(from, target)
		fileSystem.write(target.toOkioPath()) { writeUtf8(rewritten) }
		if (target != from) fileSystem.delete(from.toOkioPath())
	}

	protected fun readBytes(path: Path): ByteString = fileSystem.read(path) { readByteString() }

	protected fun copyOf(
		path: Path,
		name: String,
		bytes: ByteString?,
		text: String = bytes?.utf8() ?: "",
		archived: Boolean = false,
	): DuplicateCopy {
		val metadata = fileSystem.metadataOrNull(path)
		return DuplicateCopy(
			path = path.toHPath(),
			relativePath = path.relativeTo(projectDir).segments.joinToString("/"),
			name = name,
			isGroup = bytes == null,
			archived = archived,
			sizeBytes = metadata?.size,
			modifiedAtMillis = metadata?.lastModifiedAtMillis,
			text = text,
			contentHash = bytes?.md5()?.hex(),
		)
	}

	/** Groups by the id in each filename first, so only files that share an id are read. */
	protected fun <T> List<T>.toDuplicateSets(idOf: (T) -> Int, copyOf: (T) -> DuplicateCopy): List<DuplicateIdSet> =
		groupBy(idOf)
			.filterValues { it.size > 1 }
			.map { (id, files) -> DuplicateIdSet(kind, id, files.map(copyOf)) }

	/** Lists without creating the directory, which the stores' own directory getters do. */
	protected fun listRecursivelyOrEmpty(dir: Path): Sequence<Path> =
		if (fileSystem.exists(dir)) fileSystem.listRecursively(dir) else emptySequence()

	protected val projectDir: Path get() = projectDef.path.toOkioPath()
}

open fun claim(copy: DuplicateCopy, owner: DuplicateCopy, oldId: Int, newId: Int): Set<Int> {
	move(copy.path, canonicalPath(copy, newId))
	return emptySet()
}

protected fun rewriteOrMove(from: HPath, target: HPath, rewritten: String?) {
	if (rewritten == null) return move(from, target)
	fileSystem.write(target.toOkioPath()) { writeUtf8(rewritten) }
	if (target != from) fileSystem.delete(from.toOkioPath())
}

protected fun <T> List<T>.toDuplicateSets(idOf: (T) -> Int, copyOf: (T) -> DuplicateCopy): List<DuplicateIdSet> =
	groupBy(idOf)
		.filterValues { it.size > 1 }

class DuplicateIdService(
	private val projectDef: ProjectDef,
	private val rationalizer: ProjectFileRationalizer,
	private val syncJournal: SyncJournal,
	private val backupRepository: ProjectBackupRepository,
) : ProjectScoped {
	override val projectScope = ProjectDefScope(projectDef)

	private val ioDispatcher by injectIoDispatcher()

	// Lazy: the open step runs before these stores load.
	private val idAllocator: IdAllocator by projectInject()
	private val sceneRepository: SceneRepository by projectInject()
	private val encyclopediaRepository: EncyclopediaRepository by projectInject()
	private val notesRepository: NotesRepository by projectInject()
	private val entitySynchronizers: EntitySynchronizers by projectInject()

	private val _unresolved = MutableStateFlow<List<DuplicateIdSet>>(emptyList())
	val unresolved: StateFlow<List<DuplicateIdSet>> = _unresolved

	private val mutex = Mutex()
	private var backedUp = false

	/**
	 * Must run before any store loads its files. A scan that fails (say a sync tool removed a file
	 * mid-scan) must not stop the project opening; sync re-scans before it runs.
	 */
	suspend fun rationalizeOnOpen() = withContext(ioDispatcher) {
		mutex.withLock {
			val resolution = try {
				rationalizer.resolveSafeDuplicates()
			} catch (e: IOException) {
				Napier.e("Duplicate id scan failed for ${projectDef.name}", e)
				return@withContext
			}
			resolution.markDirty.forEach { syncJournal.markEntityAsDirty(it) }
			if (resolution.remaining.isNotEmpty()) {
				Napier.w("${projectDef.name} has ${resolution.remaining.size} unresolved duplicate ids")
			}
			_unresolved.value = resolution.remaining
		}
	}

	/** Gives every extra holder of an id shared across types a fresh id. Needs the stores loaded. */
	suspend fun resolveCrossTypeIds() = withContext(ioDispatcher) {
		mutex.withLock { resolveCrossTypeIdsLocked() }
	}

	private suspend fun resolveCrossTypeIdsLocked() {
		// Re-id acts on whichever file a store reads for an id, so each store must hold one first.
		if (_unresolved.value.isNotEmpty()) return

		val collisions = try {
			rationalizer.findCrossTypeIds()
		} catch (e: IOException) {
			Napier.e("Cross-type id scan failed for ${projectDef.name}", e)
			return
		}
		if (collisions.isEmpty()) return

		// A store that fails here must not stop the project opening; sync stays blocked on what's left.
		for ((id, types) in collisions) {
			attempt("Renumbering id $id shared by $types") {
				types.forEach { entitySynchronizers[it].prepareForSync() }
				val keeper = keeperOf(id, types)
				for (type in types - keeper) {
					val newId = idAllocator.claimNextId()
					Napier.i("$type $id shares its id with $keeper $id; renumbering it to $newId")
					entitySynchronizers[type].reIdEntity(oldId = id, newId = newId)
				}
			}
		}
	}

	/** The item the server last confirmed for [id] keeps it; otherwise the most depended-on type. */
	private suspend fun keeperOf(id: Int, types: List<EntityType>): EntityType {
		val syncedHash = if (syncJournal.isServerSynchronized()) syncJournal.loadSyncData().syncedHashes[id] else null
		val serverMatch = syncedHash?.let { hash ->
			types.firstOrNull { type -> attempt("Hashing $type $id") { entitySynchronizers[type].getEntityHash(id) } == hash }
		}
		return serverMatch ?: types.minBy { CROSS_TYPE_PRECEDENCE.indexOf(it) }
	}

	@Suppress("TooGenericExceptionCaught")
	private suspend fun <T> attempt(what: String, block: suspend () -> T): T? =
		try {
			block()
		} catch (e: CancellationException) {
			throw e
		} catch (e: Exception) {
			Napier.e("$what failed for ${projectDef.name}", e)
			null
		}

	/** A fresh scan, so copies a file-sync tool delivered while the project was open count too. */
	suspend fun hasDuplicates(): Boolean = withContext(ioDispatcher) {
		rationalizer.hasDuplicates() || rationalizer.findCrossTypeIds().isNotEmpty()
	}

	suspend fun resolve(set: DuplicateIdSet, keep: Set<HPath>): ResolveResult = withContext(ioDispatcher) {
		mutex.withLock {
			val deletesSomething = set.copies.any { it.path !in keep }
			if (deletesSomething && !ensureBackup()) return@withContext ResolveResult.BackupFailed

			val result = try {
				rationalizer.resolve(set, keep) { idAllocator.claimNextId() }
					.forEach { syncJournal.markEntityAsDirty(it) }
				ResolveResult.Resolved
			} catch (e: StaleDuplicateIdSet) {
				Napier.w("Duplicate set changed before it was resolved", e)
				ResolveResult.Stale
			}

			_unresolved.value = rationalizer.findDuplicates()
			if (result == ResolveResult.Resolved) {
				reload(set.kind)
				resolveCrossTypeIdsLocked()
			}
			result
		}
	}

	private suspend fun ensureBackup(): Boolean {
		if (backedUp || !backupRepository.supportsBackup()) return true
		backedUp = backupRepository.createBackup(projectDef) != null
		return backedUp
	}

	private suspend fun reload(kind: DuplicateIdKind) {
		when (kind) {
			DuplicateIdKind.Entry, DuplicateIdKind.EntryImage -> encyclopediaRepository.loadEntries()
			DuplicateIdKind.Scene -> sceneRepository.reloadTreeFromDisk()
			DuplicateIdKind.Note -> notesRepository.loadNotes()
			DuplicateIdKind.Draft -> Unit
		}
	}

	private companion object {
		// Scenes own drafts, metadata and buffers by id, and scene metadata points at entries.
		val CROSS_TYPE_PRECEDENCE = listOf(
			EntityType.Scene,
			EntityType.EncyclopediaEntry,
			EntityType.TimelineEvent,
			EntityType.Note,
			EntityType.SceneDraft,
		)
	}

	enum class ResolveResult {
		Resolved,
		BackupFailed,
		Stale,
	}
}

suspend fun rationalizeOnOpen() = withContext(ioDispatcher) {
	mutex.withLock {
		val resolution = try {
			rationalizer.resolveSafeDuplicates()
		} catch (e: IOException) {
			Napier.e("Duplicate id scan failed for ${projectDef.name}", e)
			return@withContext
		}
		resolution.markDirty.forEach { syncJournal.markEntityAsDirty(it) }
		if (resolution.remaining.isNotEmpty()) {
			Napier.w("${projectDef.name} has ${resolution.remaining.size} unresolved duplicate ids")
		}
		_unresolved.value = resolution.remaining
	}
}

suspend fun resolveCrossTypeIds() = withContext(ioDispatcher) {
	mutex.withLock { resolveCrossTypeIdsLocked() }
}

private suspend fun keeperOf(id: Int, types: List<EntityType>): EntityType {
	val syncedHash = if (syncJournal.isServerSynchronized()) syncJournal.loadSyncData().syncedHashes[id] else null
	val serverMatch = syncedHash?.let { hash ->
		types.firstOrNull { type -> attempt("Hashing $type $id") { entitySynchronizers[type].getEntityHash(id) } == hash }
	}
	return serverMatch ?: types.minBy { CROSS_TYPE_PRECEDENCE.indexOf(it) }
}

suspend fun hasDuplicates(): Boolean = withContext(ioDispatcher) {
	rationalizer.hasDuplicates() || rationalizer.findCrossTypeIds().isNotEmpty()
}

data class DuplicateIdSet(
	val kind: DuplicateIdKind,
	val id: Int,
	val copies: List<DuplicateCopy>,
) {
	val inUse: DuplicateCopy get() = copies.first()

	/** Whether more than one copy may be kept, each extra one under a fresh id. */
	val canKeepSeveral: Boolean get() = kind != DuplicateIdKind.EntryImage
}

internal class EntryDuplicateIdHandler(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
	private val toml: Toml,
) : DuplicateIdHandler(projectDef, fileSystem) {
	override val kind = DuplicateIdKind.Entry

	private val images = EntryImageFiles(projectDef, fileSystem)

	override val entityType = SyncEntityType.EncyclopediaEntry

	override fun ids(): Set<Int> = files().mapTo(mutableSetOf()) { (_, def) -> def.id }

	private fun files(): List<Pair<Path, EntryDef>> =
		listRecursivelyOrEmpty(projectDir / EncyclopediaDatasource.ENCYCLOPEDIA_DIRECTORY)
			.filterEntryPathsOkio()
			.mapNotNull { path -> filenameDef(path.toHPath())?.let { path to it } }
			.toList()

	override fun findDuplicates(): List<DuplicateIdSet> =
		files().toDuplicateSets({ (_, def) -> def.id }) { (path, def) ->
			val bytes = readBytes(path)
			val content = toml.decodeOrNull<EntryContainer>(bytes)?.entry
			copyOf(
				path = path,
				name = content?.name ?: def.name,
				bytes = bytes,
				text = content?.text ?: bytes.utf8(),
			)
		}

	override fun canonicalPath(copy: DuplicateCopy, id: Int): HPath = canonicalPath(copy, read(copy), id)

	private fun canonicalPath(copy: DuplicateCopy, content: EntryContent?, id: Int): HPath {
		return if (content != null) {
			val dir = EncyclopediaDatasource.getTypeDirectory(projectDef, content.type, fileSystem).toOkioPath()
			dir / EncyclopediaDatasource.getEntryFilename(content.copy(id = id))
		} else {
			val def = requireFilenameDef(copy).copy(id = id)
			val dir = EncyclopediaDatasource.getTypeDirectory(projectDef, def.type, fileSystem).toOkioPath()
			dir / EncyclopediaDatasource.getEntryFilename(def)
		}.toHPath()
	}

	override fun claim(copy: DuplicateCopy, owner: DuplicateCopy, oldId: Int, newId: Int): Set<Int> {
		val content = read(copy)
		val rewritten = content?.takeIf { it.id != newId }?.let { toml.encodeToString(EntryContainer(it.copy(id = newId))) }
		rewriteOrMove(copy.path, canonicalPath(copy, content, newId), rewritten)

		// Images belong to (type, id): one of another type than the owner's leaves with its entry.
		val type = requireFilenameDef(copy).type
		if (newId != oldId && type != requireFilenameDef(owner).type) {
			images.move(type, oldId, newId)
		}
		return emptySet()
	}

	override fun discard(copy: DuplicateCopy, owner: DuplicateCopy): Discarded {
		fileSystem.delete(copy.path.toOkioPath())

		val def = requireFilenameDef(copy)
		if (def.type != requireFilenameDef(owner).type) {
			images.delete(def.type, def.id)
		}
		return Discarded()
	}

	private fun filenameDef(path: HPath): EntryDef? =
		try {
			EncyclopediaDatasource.getEntryDefFromFilename(path.name, projectDef)
		} catch (_: InvalidEntryFilename) {
			null
		}

	private fun requireFilenameDef(copy: DuplicateCopy): EntryDef =
		filenameDef(copy.path) ?: error("Not an entry filename: ${copy.path}")

	private fun read(copy: DuplicateCopy): EntryContent? =
		toml.decodeOrNull<EntryContainer>(readBytes(copy.path.toOkioPath()))?.entry
}

val type = requireFilenameDef(copy).type
if (newId != oldId && type != requireFilenameDef(owner).type) {
	images.move(type, oldId, newId)
}

internal class EntryImageDuplicateIdHandler(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
) : DuplicateIdHandler(projectDef, fileSystem) {
	override val kind = DuplicateIdKind.EntryImage

	private val images = EntryImageFiles(projectDef, fileSystem)

	override fun findDuplicates(): List<DuplicateIdSet> =
		EntryType.entries.flatMap { type ->
			images.all(type).toDuplicateSets({ it.id }) { image ->
				copyOf(image.path, image.path.name, readBytes(image.path), text = "")
			}
		}

	override fun canonicalPath(copy: DuplicateCopy, id: Int): HPath {
		val image = images.parse(copy.path.toOkioPath()) ?: error("Not an entry image: ${copy.path}")
		return images.canonicalPath(image.type, id, image.extension).toHPath()
	}
}

private val handlers: Map<DuplicateIdKind, DuplicateIdHandler> = listOf(
	EntryDuplicateIdHandler(projectDef, fileSystem, toml),
	EntryImageDuplicateIdHandler(projectDef, fileSystem),
	SceneDuplicateIdHandler(projectDef, fileSystem),
	DraftDuplicateIdHandler(projectDef, fileSystem),
	NoteDuplicateIdHandler(projectDef, fileSystem, toml),
).associateBy { it.kind }

fun findCrossTypeIds(): Map<Int, List<EntityType>> {
	val holders = mutableMapOf<Int, MutableList<EntityType>>()
	for (handler in handlers.values) {
		val type = handler.entityType ?: continue
		handler.ids().forEach { id -> holders.getOrPut(id) { mutableListOf() } += type }
	}
	timelineIds().forEach { id -> holders.getOrPut(id) { mutableListOf() } += EntityType.TimelineEvent }
	return holders.filterValues { it.size > 1 }
}

private fun timelineIds(): Set<Int> =
	TimeLineDatasource.loadTimeline(TimeLineDatasource.getTimelineFilePath(projectDef), fileSystem, toml)
		.events.mapTo(mutableSetOf()) { it.id }

fun isSafeToResolve(set: DuplicateIdSet): Boolean {
	val handler = handlers.getValue(set.kind)
	val sameContent = set.copies.all { it.isGroup } ||
		set.copies.map { it.contentHash }.let { hashes -> null !in hashes && hashes.distinct().size == 1 }
	return sameContent && set.copies.map { handler.canonicalPath(it, set.id) }.distinct().size == 1
}

fun resolveSafeDuplicates(): Resolution {
	val markDirty = mutableSetOf<Int>()
	val remaining = mutableListOf<DuplicateIdSet>()
	for (handler in handlers.values) {
		var passes = 0
		while (true) {
			val sets = handler.findDuplicates()
			val safe = sets.firstOrNull { isSafeToResolve(it) }
			if (safe == null || passes++ >= MAX_SAFE_PASSES) {
				remaining += sets
				break
			}
			Napier.i("Resolving identical copies of ${safe.kind} ${safe.id}: ${safe.copies.map { it.relativePath }}")
			markDirty += apply(safe, owner = safe.inUse, newIds = emptyMap())
		}
	}
	return Resolution(remaining, markDirty)
}

suspend fun resolve(set: DuplicateIdSet, keep: Set<HPath>, claimId: suspend () -> Int): Set<Int> {
	val keptCopies = set.copies.filter { it.path in keep }
	require(keptCopies.isNotEmpty()) { "At least one copy must be kept" }
	require(keptCopies.size == keep.size) { "Kept paths must be copies in the set" }
	require(set.canKeepSeveral || keptCopies.size == 1) { "Only one ${set.kind} copy can be kept" }

	if (set !in handlers.getValue(set.kind).findDuplicates()) throw StaleDuplicateIdSet(set)

	val owner = keptCopies.first()
	val newIds = keptCopies.drop(1).associate { it.path to claimId() }
	Napier.i("Resolving ${set.kind} ${set.id}: keeping ${owner.relativePath}, new ids $newIds")
	return apply(set, owner, newIds)
}

private fun HPath.remapped(moved: Map<HPath, HPath>): HPath {
	val path = toOkioPath()
	for ((from, to) in moved) {
		val fromPath = from.toOkioPath()
		if (path == fromPath) return to
		if (path.isWithin(fromPath)) return (to.toOkioPath() / path.relativeTo(fromPath)).toHPath()
	}
	return this
}

internal class SceneDuplicateIdHandler(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
) : DuplicateIdHandler(projectDef, fileSystem) {
	override val kind = DuplicateIdKind.Scene

	private val sceneDir get() = projectDir / SceneDatasource.SCENE_DIRECTORY
	private val archivedDir get() = sceneDir / SceneDatasource.ARCHIVED_DIRECTORY

	override val entityType = EntityType.Scene

	override fun ids(): Set<Int> = files().mapTo(mutableSetOf()) { (_, name) -> name.id }

	private fun files(): List<Pair<Path, SceneName>> {
		val active = listRecursivelyOrEmpty(sceneDir)
			.filter { path -> path.relativeTo(sceneDir).segments.none { it.startsWith(".") } }
			.mapNotNull { path -> parseActive(path)?.let { path to it } }
			.sortedBy { (path, _) -> path.name }
			.toList()

		val archived = fileSystem.listOrNull(archivedDir).orEmpty()
			.mapNotNull { path -> parseArchived(path)?.let { path to it } }
			.sortedBy { (path, _) -> path.name }

		return active + archived
	}

	override fun findDuplicates(): List<DuplicateIdSet> =
		files().toDuplicateSets({ (_, name) -> name.id }) { (path, name) ->
			val bytes = if (name.isGroup) null else readBytes(path)
			copyOf(path, name.displayName, bytes, archived = name.archived)
		}

	override fun canonicalPath(copy: DuplicateCopy, id: Int): HPath {
		val path = copy.path.toOkioPath()
		return if (copy.archived) {
			val name = parseArchived(path) ?: error("Not an archived scene: $path")
			archivedDir / SceneDatasource.buildArchivedSceneFileName(name.displayName, id)
		} else {
			val name = parseActive(path) ?: error("Not a scene: $path")
			path.parent!! / SceneDatasource.buildSceneFileName(name.order, name.displayName, id, name.isGroup)
		}.toHPath()
	}

	override fun claim(copy: DuplicateCopy, owner: DuplicateCopy, oldId: Int, newId: Int): Set<Int> {
		val target = canonicalPath(copy, newId)
		move(copy.path, target)
		// A re-id'd group's children now sit under a different parent id.
		return if (copy.isGroup && newId != oldId) {
			sceneIdsWithin(target.toOkioPath())
		} else {
			emptySet()
		}
	}

	/**
	 * A discarded group's children are kept: they move into the owner when it is an active group,
	 * otherwise up into the discarded group's own parent.
	 */
	override fun discard(copy: DuplicateCopy, owner: DuplicateCopy): Discarded {
		val path = copy.path.toOkioPath()
		// A group-named file holds no scenes.
		if (!copy.isGroup || !fileSystem.metadata(path).isDirectory) {
			fileSystem.delete(path)
			return Discarded()
		}

		val ownerPath = owner.path.toOkioPath()
		val intoOwner = owner.isGroup && !owner.archived && !ownerPath.isWithin(path) &&
			fileSystem.metadata(ownerPath).isDirectory
		val targetDir = if (intoOwner) ownerPath else path.parent!!
		var nextOrder = fileSystem.list(targetDir).count { parseActive(it) != null }
		val moved = mutableMapOf<HPath, HPath>()
		val dirty = mutableSetOf<Int>()

		val children = fileSystem.list(path).sortedBy { it.name }
		for (child in children) {
			val name = parseActive(child)
			val target = if (name != null) {
				generateSequence(nextOrder) { it + 1 }
					.map { order ->
						order to targetDir / SceneDatasource.buildSceneFileName(order.toString(), name.displayName, name.id, name.isGroup)
					}
					.first { (_, candidate) -> !fileSystem.exists(candidate) }
					.let { (order, candidate) -> nextOrder = order + 1; candidate }
			} else {
				targetDir / child.name
			}
			// Only a file Hammer doesn't read can collide; it goes with the discarded group.
			if (fileSystem.exists(target)) continue

			fileSystem.atomicMove(child, target)
			moved[child.toHPath()] = target.toHPath()
			if (name != null) dirty += name.id
			dirty += sceneIdsWithin(target)
		}

		fileSystem.deleteRecursively(path)
		return Discarded(markDirty = dirty, moved = moved)
	}

	private fun sceneIdsWithin(dir: Path): Set<Int> {
		if (!fileSystem.metadata(dir).isDirectory) return emptySet()
		return fileSystem.listRecursively(dir).mapNotNull { parseActive(it)?.id }.toSet()
	}

	// Like SceneDatasource, a name without the scene extension is a group.
	private data class SceneName(
		val order: String,
		val displayName: String,
		val id: Int,
		val isGroup: Boolean,
		val archived: Boolean,
	)

	private fun parseActive(path: Path): SceneName? {
		val match = SceneDatasource.SCENE_FILENAME_PATTERN.matchEntire(path.name)
			?: SceneDatasource.LEGACY_SCENE_FILENAME_PATTERN.matchEntire(path.name)
			?: return null
		val id = match.groupValues[3].toIntOrNull() ?: return null
		val isGroup = match.groupValues[4] != SceneDatasource.SCENE_FILENAME_EXTENSION
		return SceneName(match.groupValues[1], ProjectsRepository.decodeFromFilename(match.groupValues[2]), id, isGroup, false)
	}

	private fun parseArchived(path: Path): SceneName? {
		val match = SceneDatasource.ARCHIVED_SCENE_FILENAME_PATTERN.matchEntire(path.name)
			?: SceneDatasource.LEGACY_ARCHIVED_SCENE_FILENAME_PATTERN.matchEntire(path.name)
			?: return null
		val id = match.groupValues[2].toIntOrNull() ?: return null
		return SceneName("", ProjectsRepository.decodeFromFilename(match.groupValues[1]), id, isGroup = false, archived = true)
	}
}

override fun discard(copy: DuplicateCopy, owner: DuplicateCopy): Discarded {
	val path = copy.path.toOkioPath()
	// A group-named file holds no scenes.
	if (!copy.isGroup || !fileSystem.metadata(path).isDirectory) {
		fileSystem.delete(path)
		return Discarded()
	}

	val ownerPath = owner.path.toOkioPath()
	val intoOwner = owner.isGroup && !owner.archived && !ownerPath.isWithin(path) &&
		fileSystem.metadata(ownerPath).isDirectory
	val targetDir = if (intoOwner) ownerPath else path.parent!!
	var nextOrder = fileSystem.list(targetDir).count { parseActive(it) != null }
	val moved = mutableMapOf<HPath, HPath>()
	val dirty = mutableSetOf<Int>()

	val children = fileSystem.list(path).sortedBy { it.name }
	for (child in children) {
		val name = parseActive(child)
		val target = if (name != null) {
			generateSequence(nextOrder) { it + 1 }
				.map { order ->
					order to targetDir / SceneDatasource.buildSceneFileName(order.toString(), name.displayName, name.id, name.isGroup)
				}
				.first { (_, candidate) -> !fileSystem.exists(candidate) }
				.let { (order, candidate) -> nextOrder = order + 1; candidate }
		} else {
			targetDir / child.name
		}
		// Only a file Hammer doesn't read can collide; it goes with the discarded group.
		if (fileSystem.exists(target)) continue

		fileSystem.atomicMove(child, target)
		moved[child.toHPath()] = target.toHPath()
		if (name != null) dirty += name.id
		dirty += sceneIdsWithin(target)
	}

	fileSystem.deleteRecursively(path)
	return Discarded(markDirty = dirty, moved = moved)
}

private fun resolveEntryPath(id: Int, type: EntryType, name: String): Path {
	val dir = getTypeDirectory(type).toOkioPath()
	val current = dir / getEntryFilename(id, type, name)
	if (fileSystem.exists(current)) return current

	val legacy = dir / getLegacyEntryFilename(id, type, name)
	if (fileSystem.exists(legacy)) return legacy

	val misplaced = listEntryPaths().firstOrNull { it.name == current.name || it.name == legacy.name }
	if (misplaced != null) {
		Napier.w("Entry $id lives at $misplaced, not in its ${type.text} directory")
		return misplaced
	}
	return current
}

private fun resolveEntryImagePath(entryDef: EntryDef, fileExtension: String): Path? {
	val dir = getTypeDirectory(entryDef.type).toOkioPath()
	return entryImagePrefixes(entryDef)
		.map { prefix -> dir / "$prefix$fileExtension" }
		.firstOrNull { fileSystem.exists(it) }
}

fun findEntryImagePath(entryDef: EntryDef): HPath? {
	val dir = getTypeDirectory(entryDef.type).toOkioPath()
	val prefixes = entryImagePrefixes(entryDef)
	return fileSystem.list(dir)
		.firstOrNull { path ->
			prefixes.any { prefix ->
				path.name.startsWith(prefix) &&
					path.name.removePrefix(prefix).lowercase() in IMAGE_EXTENSIONS
			}
		}
		?.toHPath()
}

suspend fun loadEntriesImperative(): List<EntryDef> {
	val byId = LinkedHashMap<Int, Path>()
	for (path in listEntryPaths()) {
		val id = getEntryIdFromFilename(path.name)
		val existing = byId[id]
		if (existing == null) {
			byId[id] = path
		} else {
			Napier.e("Duplicate entry id $id on disk: keeping ${existing.name}, refusing ${path.name}")
		}
	}
	return byId.values.map { getEntryDef(it.toHPath()) }
}

