class IdeasDatasource(
	private val fileSystem: FileSystem,
	private val codec: StoryIdeaCodec,
	private val globalSettingsStore: GlobalSettingsStore,
) : KoinComponent {
	private val ioDispatcher = injectIoDispatcherNow()

	fun getIdeasDirectory(): HPath {
		val projectsDir = globalSettingsStore.globalSettings.projectsDirectory.toPath()
		val ideasDir = projectsDir / IDEAS_DIRECTORY
		if (!fileSystem.exists(ideasDir)) {
			fileSystem.createDirectories(ideasDir)
		}
		return ideasDir.toHPath()
	}

	fun getIdeaPath(id: IdeaId): HPath {
		val dir = getIdeasDirectory().toOkioPath()
		return (dir / getIdeaFilenameFromId(id)).toHPath()
	}

	suspend fun loadIdeas(): List<StoryIdea> = withContext(ioDispatcher) {
		val dir = getIdeasDirectory().toOkioPath()
		fileSystem.list(dir)
			.filter { IDEA_FILENAME_PATTERN.matches(it.name) }
			.mapNotNull { path -> loadIdeaOrNull(path) }
	}

	private fun loadIdeaOrNull(path: Path): StoryIdea? {
		val text = try {
			fileSystem.read(path) { readUtf8() }
		} catch (e: IOException) {
			Napier.e("Failed to read idea file: ${path.toHPath().path}", e)
			return null
		}
		return codec.decodeOrNull(text) { e ->
			Napier.e("Skipping malformed idea file: ${path.toHPath().path}", e)
		}
	}

	suspend fun createIdea(idea: StoryIdea) = withContext(ioDispatcher) {
		val path = getIdeaPath(idea.id).toOkioPath()
		fileSystem.write(path, mustCreate = true) {
			writeUtf8(codec.encode(idea))
		}
	}

	suspend fun updateIdea(idea: StoryIdea) = withContext(ioDispatcher) {
		val path = getIdeaPath(idea.id).toOkioPath()
		fileSystem.write(path, mustCreate = false) {
			writeUtf8(codec.encode(idea))
		}
	}

	suspend fun deleteIdea(id: IdeaId) = withContext(ioDispatcher) {
		val path = getIdeaPath(id).toOkioPath()
		fileSystem.delete(path, mustExist = false)
	}

	companion object {
		const val IDEAS_DIRECTORY = ".ideas"
		const val IDEAS_FILENAME_EXTENSION = ".md"
		val IDEA_FILENAME_PATTERN = Regex("""idea-([0-9a-fA-F\-]{36})\.md""")

		fun getIdeaFilenameFromId(id: IdeaId): String {
			return "idea-${id.id}$IDEAS_FILENAME_EXTENSION"
		}
	}
}

class IdeasRepository(
	private val ideasDatasource: IdeasDatasource,
	private val ideasSyncDatasource: IdeasSyncDatasource,
	private val clock: Clock,
) : KoinComponent {

	private val dispatcherDefault: CoroutineContext by inject(named(DISPATCHER_DEFAULT))
	private val ideasScope = CoroutineScope(dispatcherDefault)

	// Serializes disk-read + cache read-modify-write so a background reload can't clobber a
	// concurrent create/update/delete (both run on the multi-threaded default dispatcher).
	private val ideasLock = Mutex()
	private var _ideas = listOf<StoryIdea>()

	private val _ideasFlow = MutableSharedFlow<List<StoryIdea>>(
		extraBufferCapacity = 1,
		onBufferOverflow = BufferOverflow.DROP_OLDEST,
		replay = 1,
	)
	val ideasFlow: SharedFlow<List<StoryIdea>> = _ideasFlow

	// Without this a storage failure is indistinguishable from having no ideas
	private val _loadFailedFlow = MutableStateFlow(false)
	val loadFailedFlow: StateFlow<Boolean> = _loadFailedFlow

	init {
		loadIdeas()
	}

	fun loadIdeas(onLoaded: (() -> Unit)? = null) {
		ideasScope.launch {
			ideasLock.withLock {
				val ideas = try {
					ideasDatasource.loadIdeas()
				} catch (e: CancellationException) {
					throw e
				} catch (@Suppress("TooGenericExceptionCaught") e: Exception) {
					Napier.e("Failed to load ideas", e)
					null
				}
				updateIdeas(ideas ?: _ideas)
				_loadFailedFlow.value = ideas == null
			}
			onLoaded?.invoke()
		}
	}

	suspend fun getIdeaById(id: IdeaId): StoryIdea? = ideasFlow.first().find { it.id == id }

	suspend fun createIdea(
		content: String,
		title: String? = null,
		tags: Set<String> = emptySet(),
	): CResult<StoryIdea> {
		val result = validateIdea(content, tags)
		return if (result != IdeaError.NONE) {
			CResult.failure(InvalidIdea(result))
		} else {
			val now = clock.now()
			val idea = StoryIdea(
				id = IdeaId.randomUUID(),
				created = now,
				updated = now,
				title = cleanTitle(title),
				content = content,
				tags = cleanTags(tags),
			)
			ideasLock.withLock {
				ideasDatasource.createIdea(idea)
				updateIdeas(_ideas + idea)
			}
			CResult.success(idea)
		}
	}

	suspend fun updateIdea(idea: StoryIdea): CResult<StoryIdea> {
		val result = validateIdea(idea.content, idea.tags)
		return if (result != IdeaError.NONE) {
			CResult.failure(InvalidIdea(result))
		} else {
			val updated = idea.copy(
				updated = clock.now(),
				title = cleanTitle(idea.title),
				tags = cleanTags(idea.tags),
			)
			ideasLock.withLock {
				ideasDatasource.updateIdea(updated)
				updateIdeas(_ideas.map { if (it.id == updated.id) updated else it })
			}
			CResult.success(updated)
		}
	}

	suspend fun deleteIdea(id: IdeaId) {
		// Outbox entry first, so a crash between the two can only over-delete on the server
		// (idempotent) rather than resurrect the idea on the next sync.
		ideasSyncDatasource.recordPendingDelete(id)
		ideasLock.withLock {
			ideasDatasource.deleteIdea(id)
			updateIdeas(_ideas.filterNot { it.id == id })
		}
	}

	suspend fun archiveIdea(id: IdeaId): CResult<StoryIdea> {
		val idea = getIdeaById(id) ?: return CResult.failure(IllegalArgumentException("No idea for id: $id"))
		return updateIdea(idea.copy(archived = clock.now()))
	}

	suspend fun unarchiveIdea(id: IdeaId): CResult<StoryIdea> {
		val idea = getIdeaById(id) ?: return CResult.failure(IllegalArgumentException("No idea for id: $id"))
		return updateIdea(idea.copy(archived = null))
	}

	suspend fun markPromoted(id: IdeaId): CResult<StoryIdea> {
		val idea = getIdeaById(id) ?: return CResult.failure(IllegalArgumentException("No idea for id: $id"))
		return updateIdea(idea.copy(promoted = clock.now()))
	}

	fun validateIdea(content: String, tags: Set<String> = emptySet()): IdeaError {
		val trimmed = content.trim()
		return if (trimmed.length > StoryIdea.MAX_CONTENT_LENGTH) {
			IdeaError.TOO_LONG
		} else if (trimmed.isEmpty()) {
			IdeaError.EMPTY
		} else if (tags.any { it.length > MAX_TAG_SIZE }) {
			IdeaError.TAG_TOO_LONG
		} else {
			IdeaError.NONE
		}
	}

	private fun cleanTitle(title: String?): String? = title?.trim()?.ifEmpty { null }

	private suspend fun updateIdeas(ideas: List<StoryIdea>) {
		_ideas = ideas
		_ideasFlow.emit(ideas)
	}

	companion object {
		const val MAX_TAG_SIZE = 32
	}
}

