fun decode(text: String): StoryIdea {
	val newlineIndices = ArrayList<Int>()
	var searchFrom = 0
	while (true) {
		val idx = text.indexOf('\n', searchFrom)
		if (idx < 0) break
		newlineIndices.add(idx)
		searchFrom = idx + 1
	}

	fun lineAt(start: Int, endExclusive: Int) = text.substring(start, endExclusive).trimEnd('\r')

	// The first non-blank line must be the opening fence
	var lineStart = 0
	var lineIndex = 0
	var openFenceEnd = -1
	while (lineIndex <= newlineIndices.size) {
		val lineEnd = newlineIndices.getOrNull(lineIndex) ?: text.length
		val line = lineAt(lineStart, lineEnd)
		if (line.isNotBlank()) {
			if (line != FENCE) throw IdeaCodecException("Missing opening fence")
			openFenceEnd = lineEnd + 1
			break
		}
		lineStart = lineEnd + 1
		lineIndex++
	}
	if (openFenceEnd < 0 || openFenceEnd > text.length) {
		throw IdeaCodecException("Missing opening fence")
	}

	// Find the closing fence
	lineStart = openFenceEnd
	lineIndex++
	var blockEnd = -1
	var bodyStart = -1
	while (lineIndex <= newlineIndices.size) {
		val lineEnd = newlineIndices.getOrNull(lineIndex) ?: text.length
		if (lineAt(lineStart, lineEnd) == FENCE) {
			blockEnd = lineStart
			bodyStart = minOf(lineEnd + 1, text.length)
			break
		}
		lineStart = lineEnd + 1
		lineIndex++
	}
	if (blockEnd < 0) throw IdeaCodecException("Missing closing fence")

	val block = text.substring(openFenceEnd, blockEnd)
		.lines()
		.joinToString("\n") { it.trimEnd('\r') }

	// tomlkt does not funnel every decode failure through SerializationException: malformed
	// input can also throw IllegalArgumentException (numeric coercion, type-mismatch casts)
	// or IllegalStateException (parser errors such as a malformed date-time).
	val frontMatter = try {
		toml.decodeFromString(IdeaFrontMatter.serializer(), block)
	} catch (e: SerializationException) {
		throw IdeaCodecException("Malformed front matter", e)
	} catch (e: IllegalArgumentException) {
		throw IdeaCodecException("Malformed front matter", e)
	} catch (e: IllegalStateException) {
		throw IdeaCodecException("Malformed front matter", e)
	}

	// Skip the single blank separator line encode() writes
	var content = text.substring(bodyStart)
	if (content.startsWith("\r\n")) {
		content = content.substring(2)
	} else if (content.startsWith("\n")) {
		content = content.substring(1)
	}

	return StoryIdea(
		id = frontMatter.id,
		created = frontMatter.created,
		updated = frontMatter.updated,
		title = frontMatter.title,
		content = content,
		tags = frontMatter.tags,
		promoted = frontMatter.promoted,
		archived = frontMatter.archived,
	)
}

var lineStart = 0
var lineIndex = 0
var openFenceEnd = -1
while (lineIndex <= newlineIndices.size) {
	val lineEnd = newlineIndices.getOrNull(lineIndex) ?: text.length
	val line = lineAt(lineStart, lineEnd)
	if (line.isNotBlank()) {
		if (line != FENCE) throw IdeaCodecException("Missing opening fence")
		openFenceEnd = lineEnd + 1
		break
	}
	lineStart = lineEnd + 1
	lineIndex++
}

var content = text.substring(bodyStart)
if (content.startsWith("\r\n")) {
	content = content.substring(2)
}

internal sealed interface ImportToken {
	/**
	 * [title] is the sanitized name used when this heading opens a group/scene. [raw] is the original
	 * line, appended verbatim as body when the heading is deeper than the chosen scene level.
	 */
	data class Heading(val level: Int, val title: String, val raw: String) : ImportToken
	data class Body(val line: String) : ImportToken
}

private fun previewAuto(
	tokens: List<ImportToken>,
	wrapTopLevelInGroups: Boolean,
	fallbackName: String,
): ImportPreview {
	val headings = tokens.withIndex().filter { it.value is ImportToken.Heading }
	if (headings.isEmpty()) {
		return buildImportPreview(tokens, 1, wrapTopLevelInGroups, fallbackName)
	}

	val levels = headings.map { (it.value as ImportToken.Heading).level }
	val minLevel = levels.min()
	val firstHeading = headings.first().value as ImportToken.Heading
	val titleIndex = if (firstHeading.level == minLevel && levels.count { it == minLevel } == 1) {
		headings.first().index
	} else {
		null
	}

	val title = titleIndex?.let { (tokens[it] as ImportToken.Heading).title }
	val workingTokens = if (titleIndex != null) {
		tokens.filterIndexed { index, _ -> index != titleIndex }
	} else {
		tokens
	}

	val sceneLevel = workingTokens
		.filterIsInstance<ImportToken.Heading>()
		.groupingBy { it.level }
		.eachCount()
		.entries
		// Most headings wins (chapters outnumber parts); ties resolve to the shallower level.
		.sortedWith(compareByDescending<Map.Entry<Int, Int>> { it.value }.thenBy { it.key })
		.firstOrNull()?.key ?: 1

	return buildImportPreview(workingTokens, sceneLevel, wrapTopLevelInGroups, fallbackName)
		.copy(title = title)
}

private fun isSetextTitle(lines: List<String>, index: Int, underlineLevel: Int): Boolean {
	val line = lines[index]
	if (line.isBlank()) return false
	if (line.length - line.trimStart(' ').length > MAX_HEADING_INDENT) return false
	if (setextUnderlineLevel(line) != null) return false
	return underlineLevel == 1 || index == 0 || lines[index - 1].isBlank()
}

private fun isBoldOnlyLine(line: String): Boolean {
	val trimmed = line.trim()
	return BOLD_MARKERS.any { marker ->
		trimmed.length > marker.length * 2 &&
			trimmed.startsWith(marker) &&
			trimmed.endsWith(marker) &&
			trimmed.substring(marker.length, trimmed.length - marker.length).let {
				it.isNotBlank() && !it.contains(marker) && it.trim().split(WHITESPACE).size <= HEADING_MAX_WORDS
			}
	}
}

private fun plainText(line: String): String {
	var text = if (atxHeadingLevel(line) != null) line.trimStart(' ').trimStart('#').trim() else line.trim()
	for (marker in EMPHASIS_MARKERS) {
		while (text.length > marker.length * 2 && text.startsWith(marker) && text.endsWith(marker)) {
			text = text.substring(marker.length, text.length - marker.length).trim()
		}
	}
	return text
}

private fun headingLevelsByFormatting(paragraphs: List<RtfParagraph>): Map<RtfParagraph, Int> {
	val bodySize = bodyFontSize(paragraphs)
	val tierByHeading = paragraphs
		.filter { it.isHeading(bodySize) }
		.associateWith { it.tierKey(bodySize) }

	// Highest tier (largest font / lowest outline level) sorts first, capped at two levels.
	val tiers = tierByHeading.values.distinct().sorted()
	return tierByHeading.mapValues { (_, tier) -> tiers.indexOf(tier).coerceAtMost(1) + 1 }
}

private fun tokenize(
	paragraphs: List<RtfParagraph>,
	headingLevel: (RtfParagraph) -> Int?,
): List<ImportToken> = buildList {
	for (p in paragraphs) {
		val level = if (p.isBlank) null else headingLevel(p)
		when {
			p.isBlank -> add(ImportToken.Body(""))
			level != null -> add(headingToken(p, level))
			else -> addBody(p)
		}
	}
}

private class RtfParagraphCollector : com.darkrockstudios.libs.rtfparserkmp.parser.RtfListener {
	val paragraphs = mutableListOf<RtfParagraph>()

	private var currentDestination = Command.rtf
	private val destinationStack = ArrayDeque<Command>()

	private var bold = false
	private var italic = false
	private var fontSize: Int? = null
	private val formattingStack = ArrayDeque<Formatting>()

	private var outlineLevel: Int? = null

	private val markdown = StringBuilder()
	private val plain = StringBuilder()
	private val openMarkers = ArrayDeque<Marker>()
	private val sizeCounts = HashMap<Int, Int>()
	private var boldChars = 0
	private var totalChars = 0

	override fun processGroupStart() {
		destinationStack.addLast(currentDestination)
		formattingStack.addLast(Formatting(bold, italic, fontSize))
	}

	override fun processGroupEnd() {
		currentDestination = destinationStack.removeLast()
		val restored = formattingStack.removeLast()
		bold = restored.bold
		italic = restored.italic
		fontSize = restored.fontSize
		closeDisabledMarkers()
	}

	override fun processString(string: String) {
		if (!isBodyDestination()) return
		plain.append(string)
		appendMarkdown(string)
		for (ch in string) {
			if (ch.isWhitespace()) continue
			totalChars++
			if (bold) boldChars++
			fontSize?.let { sizeCounts[it] = (sizeCounts[it] ?: 0) + 1 }
		}
	}

	override fun processCommand(command: Command, parameter: Int, hasParameter: Boolean, optional: Boolean) {
		if (command.commandType == CommandType.Destination) {
			currentDestination = command
		}

		when (command) {
			Command.b -> setBold(!hasParameter || parameter != 0)
			Command.i -> setItalic(!hasParameter || parameter != 0)
			Command.fs -> if (hasParameter) fontSize = parameter
			Command.outlinelevelN -> outlineLevel = if (hasParameter) parameter else 0
			Command.plain -> {
				setBold(false)
				setItalic(false)
			}
			Command.pard -> outlineLevel = null
			Command.par, Command.row -> if (isBodyDestination()) endParagraph()
			Command.line -> if (isBodyDestination()) {
				closeEmphasis()
				markdown.append("  \n")
				plain.append('\n')
			}
			Command.tab, Command.cell -> if (isBodyDestination()) {
				markdown.append('\t')
				plain.append('\t')
			}
			else -> {}
		}
	}

	override fun processDocumentEnd() {
		endParagraph()
	}

	private fun endParagraph() {
		closeEmphasis()
		val md = escapeOrderedListMarkers(markdown.toString().trim())
		val text = plain.toString().trim()
		val dominantSize = sizeCounts.maxByOrNull { it.value }?.key
		val mostlyBold = totalChars > 0 && boldChars.toDouble() / totalChars >= BOLD_RATIO
		paragraphs.add(
			RtfParagraph(
				markdown = md,
				plainText = text,
				dominantFontSize = dominantSize,
				mostlyBold = mostlyBold,
				outlineLevel = outlineLevel,
			)
		)

		markdown.clear()
		plain.clear()
		openMarkers.clear()
		sizeCounts.clear()
		boldChars = 0
		totalChars = 0
	}

	private fun isBodyDestination(): Boolean =
		currentDestination == Command.rtf ||
			currentDestination == Command.pntext ||
			currentDestination == Command.fldrslt

	private fun setBold(value: Boolean) {
		if (value != bold) {
			bold = value
			if (!value) closeDisabledMarkers()
		}
	}

	private fun setItalic(value: Boolean) {
		if (value != italic) {
			italic = value
			if (!value) closeDisabledMarkers()
		}
	}

	private fun isActive(marker: Marker): Boolean = when (marker) {
		Marker.BOLD -> bold
		Marker.ITALIC -> italic
	}

	/**
	 * Opens pending emphasis at the first non-whitespace character, so a run's leading whitespace
	 * stays outside the delimiters and an all-whitespace run opens nothing.
	 */
	private fun appendMarkdown(text: String) {
		val firstVisible = text.indexOfFirst { !it.isWhitespace() }
		if (firstVisible < 0) {
			markdown.append(text)
			return
		}
		markdown.append(text.substring(0, firstVisible))
		openEmphasis()
		markdown.append(escape(text.substring(firstVisible)))
	}

	private fun openEmphasis() {
		if (bold && Marker.BOLD !in openMarkers) {
			markdown.append(Marker.BOLD.text)
			openMarkers.addLast(Marker.BOLD)
		}
		if (italic && Marker.ITALIC !in openMarkers) {
			markdown.append(Marker.ITALIC.text)
			openMarkers.addLast(Marker.ITALIC)
		}
	}

	/**
	 * Closes every marker down to the shallowest inactive one. Still-active markers come off the
	 * stack too and are reopened by [openEmphasis] at the next non-whitespace character.
	 */
	private fun closeDisabledMarkers() {
		val deepestDisabled = openMarkers.indexOfFirst { !isActive(it) }
		if (deepestDisabled < 0) return
		while (openMarkers.size > deepestDisabled) {
			closeMarker(openMarkers.removeLast())
		}
	}

	private fun closeEmphasis() {
		while (openMarkers.isNotEmpty()) {
			closeMarker(openMarkers.removeLast())
		}
	}

	/** Emits [marker] ahead of any trailing whitespace, keeping the delimiter against the text. */
	private fun closeMarker(marker: Marker) {
		markdown.insert(markdown.length - trailingWhitespaceLength(), marker.text)
	}

	private fun trailingWhitespaceLength(): Int =
		markdown.length - (markdown.indexOfLast { !it.isWhitespace() } + 1)

	/** Keeps an imported paragraph that starts with "1." from parsing as an ordered list. */
	private fun escapeOrderedListMarkers(text: String): String =
		text.replace(ORDERED_LIST_MARKER, "$1\\\\.")

	private fun escape(text: String): String {
		val out = StringBuilder(text.length)
		for (ch in text) {
			if (ch in MARKDOWN_SPECIAL) out.append('\\')
			out.append(ch)
		}
		return out.toString()
	}

	private class Formatting(val bold: Boolean, val italic: Boolean, val fontSize: Int?)

	private enum class Marker(val text: String) {
		BOLD("**"),
		ITALIC("*"),
	}

	private companion object {
		const val BOLD_RATIO = 0.8

		/** Mirrors `MARKDOWN_SPECIAL_CHARS` in ComposeTextEditor's Markdown escaper. */
		val MARKDOWN_SPECIAL = "\\`*_{}[]()<>#+-!|".toSet()
		val ORDERED_LIST_MARKER = Regex("^(\\d+)\\.", RegexOption.MULTILINE)
	}
}

private fun appendMarkdown(text: String) {
	val firstVisible = text.indexOfFirst { !it.isWhitespace() }
	if (firstVisible < 0) {
		markdown.append(text)
		return
	}
	markdown.append(text.substring(0, firstVisible))
	openEmphasis()
	markdown.append(escape(text.substring(firstVisible)))
}

private fun closeDisabledMarkers() {
	val deepestDisabled = openMarkers.indexOfFirst { !isActive(it) }
	if (deepestDisabled < 0) return
	while (openMarkers.size > deepestDisabled) {
		closeMarker(openMarkers.removeLast())
	}
}

private fun closeMarker(marker: Marker) {
	markdown.insert(markdown.length - trailingWhitespaceLength(), marker.text)
}

val oversizedScenes: List<PreviewItem.Scene>
	get() = buildList {
		items.forEach { item ->
			when (item) {
				is PreviewItem.Scene -> if (item.isOversized) add(item)
				is PreviewItem.Group -> item.scenes.filterTo(this) { it.isOversized }
			}
