class StoryImporterRegistry(importers: List<StoryImporter>) {
	private val byFormat: Map<ImportFormat, StoryImporter> = importers.associateBy { it.format }

	fun forFormat(format: ImportFormat): StoryImporter =
		byFormat[format] ?: error("No importer registered for format $format")

	fun formatForFileName(name: String): ImportFormat =
		when (name.substringAfterLast('.', "").lowercase()) {
			"rtf" -> ImportFormat.Rtf
			else -> ImportFormat.Markdown
		}

	fun forFileName(name: String): StoryImporter = forFormat(formatForFileName(name))
}

open class DataMigrator(
	private val globalSettingsStore: GlobalSettingsStore,
	private val projectsRepository: ProjectsRepository,
	private val projectMetadataDatasource: ProjectMetadataDatasource,
) {
	protected open val latestProjectDataVersion: Int = PROJECT_DATA_VERSION
	protected open fun getMigrators(): Map<Int, Migration> {
		val migrators = mutableMapOf<Int, Migration>()

		getKoin().get<Migration0_1>().addToMap(migrators)
		getKoin().get<Migration1_2>().addToMap(migrators)
		getKoin().get<Migration2_3>().addToMap(migrators)

		return migrators
	}

	// Order matters: MigrateInlineAuthTokens rewrites server.json tokenless and in doing so
	// drops legacy fields, so MigrateInstallIdToGlobal must read installId out of it first.
	protected open fun getGlobalMigrations(): List<GlobalMigration> = listOf(
		getKoin().get<MigrateInstallIdToGlobal>(),
		getKoin().get<MigrateInlineAuthTokens>(),
	)

	private fun getProjects(): List<ProjectData> {
		val projDir = globalSettingsStore.globalSettings.projectsDirectory.toPath()
		val projects = projectsRepository.getProjects(projDir.toHPath()).map { projDef ->
			val metadata = projectMetadataDatasource.loadMetadata(projDef)
			ProjectData(projDef, metadata)
		}
		return projects
	}

	suspend fun handleDataMigration() {
		runGlobalMigrations()

		if (checkIfMigrationNeeded()) {
			doMigration()
		} else {
			Napier.d("No projects need migration. Skipping.")
		}
	}

	private suspend fun runGlobalMigrations() {
		getGlobalMigrations().forEach { it.migrate() }
		// Global migrations may relocate legacy inline tokens into the store; refresh the
		// store's cached server settings so this session sees them.
		globalSettingsStore.reloadServerSettings()
	}

	fun checkIfMigrationNeeded(): Boolean {
		val projects = getProjects()
		return projects.any { projectData ->
			projectData.projectMetadata.info.dataVersion < latestProjectDataVersion
		}
	}

	private fun doMigration() {
		Napier.i("Migrating projects to version: $latestProjectDataVersion")
		val projects = getProjects()
		val migrators = getMigrators()

		projects.forEach { projectData ->
			migrateProject(projectData, migrators)
		}
	}

	private fun migrateProject(projectData: ProjectData, migrators: Map<Int, Migration>) {
		val projectDataVersion = projectData.projectMetadata.info.dataVersion
		if (projectDataVersion < latestProjectDataVersion) {
			for (version in projectDataVersion + 1..latestProjectDataVersion) {
				val migrator =
					migrators[version] ?: error("Migrator not found for data version: $version")
				Napier.i("Migrating project: '${projectData.projectDef.name}' From: $projectDataVersion To: $version")
				migrator.migrate(projectData.projectDef)

				// Mark that this version migration was successful
				projectMetadataDatasource.updateMetadata(projectData.projectDef) { metadata ->
					metadata.copy(
						info = metadata.info.copy(
							dataVersion = version
						)
					)
				}

				Napier.i("'${projectData.projectDef.name}' migration complete.")
			}
		}
	}
}

projectMetadataDatasource.updateMetadata(projectData.projectDef) { metadata ->
	metadata.copy(
		info = metadata.info.copy(
			dataVersion = version
		)
	)
}

interface GlobalMigration {
	suspend fun migrate()
}

@Suppress("TooGenericExceptionCaught")
override suspend fun migrate() {
	if (globalSettingsStore.globalSettings.installId != null) return

	val projectsDir = globalSettingsStore.globalSettings.projectsDirectory.toPath()
	val legacyPath = projectsDir / LEGACY_SERVER_FILE_NAME
	if (!fileSystem.exists(legacyPath)) return

	val legacyInstallId = try {
		val text = fileSystem.read(legacyPath) { readUtf8() }
		json.decodeFromString<ServerSettingsOld>(text).installId
	} catch (e: Exception) {
		Napier.w("Failed to read legacy server.json for installId migration", e)
		null
	} ?: return

	Napier.i("Migrating installId from server.json to GlobalSettings")
	globalSettingsStore.updateSettings { it.copy(installId = legacyInstallId) }
}

class Migration0_1(
	private val fileSystem: FileSystem,
	private val toml: Toml,
	private val json: Json,
) : Migration {
	override val toVersion: Int = 1
	override fun migrate(projectDef: ProjectDef) {
		Napier.i("Begin Migration0_1 for '${projectDef.name}'...")

		val path = TimeLineDatasource.getTimelineFilePath(projectDef)
		try {
			val timeline = loadJsonTimeline(
				hpath = path,
				fileSystem = fileSystem,
				json = json
			)

			if (timeline != null) {
				fileSystem.writeToml<TimeLineContainer>(path.toOkioPath(), toml, timeline)
			} else {
				Napier.i("No timeline content found for Migration0_1, skipping.")
			}
		} catch (e: FileNotFoundException) {
			Napier.i("No timeline found for Migration0_1, skipping.", e)
		} catch (e: SerializationException) {
			Napier.w("Failed to deserialize Timeline, it's likely it is already migrated", e)
		} catch (e: IllegalArgumentException) {
			Napier.w("Failed to deserialize Timeline, it's likely it is already migrated", e)
		}
	}

	private fun loadJsonTimeline(hpath: HPath, fileSystem: FileSystem, json: Json): TimeLineContainer? {
		val path = hpath.toOkioPath()
		return if (fileSystem.exists(path)) {
			fileSystem.read(path) {
				val timelineToml = readUtf8()
				if (timelineToml.isNotBlank()) {
					json.decodeFromString(timelineToml)
				} else {
					TimeLineContainer(emptyList())
				}
			}
		} else {
			null
		}
	}
}

class Migration1_2(
	private val fileSystem: FileSystem,
) : Migration {
	override val toVersion: Int = 2

	override fun migrate(projectDef: ProjectDef) {
		Napier.i("Begin Migration1_2 for '${projectDef.name}'...")

		val sceneDir = SceneDatasource.getSceneDirectory(projectDef, fileSystem).toOkioPath()
		if (!fileSystem.exists(sceneDir)) {
			Napier.i("No scenes directory for '${projectDef.name}', skipping Migration1_2.")
			return
		}

		var renamed = 0
		// Rename deepest paths first so renaming a parent dir doesn't invalidate
		// pending child paths.
		fileSystem.listRecursively(sceneDir)
			.filter { !it.isInBufferDirectory() }
			.toList()
			.sortedByDescending { it.segments.size }
			.forEach { path ->
				val newName = nextName(path.name) ?: return@forEach
				val target = path.parent?.div(newName) ?: return@forEach
				if (fileSystem.exists(target)) {
					Napier.w("Migration1_2: target already exists, skipping rename of $path")
					return@forEach
				}
				fileSystem.atomicMove(path, target)
				renamed++
			}

		Napier.i("Migration1_2 for '${projectDef.name}' complete — renamed $renamed file(s).")
	}

	/**
	 * Returns the new filename for [oldName] if it matches the legacy active or archived
	 * scene pattern, or null if it doesn't match (e.g. directory name, buffer file, or
	 * already-migrated file). The trailing `.md`/`.temp` suffix is preserved verbatim.
	 */
	private fun nextName(oldName: String): String? {
		SceneDatasource.LEGACY_SCENE_FILENAME_PATTERN.matchEntire(oldName)?.let { m ->
			val (order, name, id) = Triple(m.groupValues[1], m.groupValues[2], m.groupValues[3])
			val suffix = oldName.substringAfter("$order-$name-$id")
			return "$order~$name~$id$suffix"
		}
		SceneDatasource.LEGACY_ARCHIVED_SCENE_FILENAME_PATTERN.matchEntire(oldName)?.let { m ->
			val name = m.groupValues[1]
			val id = m.groupValues[2]
			val suffix = oldName.substringAfter("$name-$id")
			return "$name~$id$suffix"
		}
		return null
	}

	private fun Path.isInBufferDirectory(): Boolean {
		return toString().contains("${Path.DIRECTORY_SEPARATOR}${SceneDatasource.BUFFER_DIRECTORY}${Path.DIRECTORY_SEPARATOR}") ||
			parent?.name == SceneDatasource.BUFFER_DIRECTORY
	}
}

class Migration2_3(
	private val fileSystem: FileSystem,
) : Migration {
	override val toVersion: Int = 3

	override fun migrate(projectDef: ProjectDef) {
		Napier.i("Begin Migration2_3 for '${projectDef.name}'...")

		val renamed = migrateEncyclopedia(projectDef) + migrateDrafts(projectDef)

		Napier.i("Migration2_3 for '${projectDef.name}' complete, renamed $renamed file(s).")
	}

	private fun migrateEncyclopedia(projectDef: ProjectDef): Int {
		val projectDir = projectDef.path.toOkioPath()
		val encyclopediaDir = projectDir / EncyclopediaDatasource.ENCYCLOPEDIA_DIRECTORY
		if (!fileSystem.exists(encyclopediaDir)) {
			Napier.i("No encyclopedia directory for '${projectDef.name}', skipping.")
			return 0
		}

		return renameAll(encyclopediaDir) { name -> nextEntryName(name) }
	}

	private fun migrateDrafts(projectDef: ProjectDef): Int {
		val sceneDir = SceneDatasource.getSceneDirectory(projectDef, fileSystem).toOkioPath()
		val draftsDir = sceneDir / SceneDraftsDatasource.DRAFTS_DIR
		if (!fileSystem.exists(draftsDir)) {
			Napier.i("No drafts directory for '${projectDef.name}', skipping.")
			return 0
		}

		return renameAll(draftsDir) { name -> nextDraftName(name) }
	}

	private fun renameAll(root: Path, nextName: (String) -> String?): Int {
		var renamed = 0
		// Only files are renamed here, but walk deepest-first anyway so the traversal stays
		// correct if a future format nests names inside directory names.
		fileSystem.listRecursively(root)
			.toList()
			.sortedByDescending { it.segments.size }
			.forEach { path ->
				val newName = nextName(path.name) ?: return@forEach
				val target = path.parent?.div(newName) ?: return@forEach
				if (fileSystem.exists(target)) {
					Napier.w("Migration2_3: target already exists, skipping rename of $path")
					return@forEach
				}
				fileSystem.atomicMove(path, target)
				renamed++
			}
		return renamed
	}

	/**
	 * Returns the `~`-delimited name for [oldName] if it matches a legacy encyclopedia entry or
	 * entry image filename, or null if it doesn't match (e.g. a type directory, or a file already
	 * in the new format).
	 */
	private fun nextEntryName(oldName: String): String? {
		EncyclopediaDatasource.LEGACY_ENTRY_FILENAME_PATTERN.matchEntire(oldName)?.let { m ->
			val (type, id) = Pair(m.groupValues[1], m.groupValues[2])
			val name = canonicalName(m.groupValues[3]) ?: return null
			return "$type~$id~$name.toml"
		}
		EncyclopediaDatasource.LEGACY_ENTRY_IMAGE_FILENAME_PATTERN.matchEntire(oldName)?.let { m ->
			val (type, id, extension) = Triple(m.groupValues[1], m.groupValues[2], m.groupValues[3])
			return "$type~$id~image.$extension"
		}
		return null
	}

	/**
	 * Returns the `~`-delimited name for [oldName] if it matches the legacy draft filename, or
	 * null if it doesn't match (e.g. a per-scene directory, or an already-migrated file).
	 */
	private fun nextDraftName(oldName: String): String? {
		val m = SceneDraftsDatasource.LEGACY_DRAFT_FILENAME_PATTERN.matchEntire(oldName)
			?: return null
		val sceneId = m.groupValues[1]
		val draftId = m.groupValues[2]
		val name = canonicalName(m.groupValues[3]) ?: return null
		val timestamp = m.groupValues[4]
		return "$sceneId~$draftId~$name~$timestamp.md"
	}

	/**
	 * The name exactly as the datasources would write it today. Both encode the name, which strips
	 * a trailing `.`/space that the old, narrower rules let through; without this the migrated file
	 * would never match the path rebuilt from its own parsed name. Null when nothing legal is left,
	 * so the file is skipped rather than renamed to an unparseable one.
	 */
	private fun canonicalName(rawName: String): String? =
		ProjectsRepository.encodeForFilename(rawName).ifBlank { null }
}

