private fun backupKeysForProject(projectName: String): Set<String> = setOf(
	ProjectsRepository.encodeForFilename(projectName),
	legacyBackupName(projectName),
)

private fun backupDate(path: Path, encodedDate: String?): Instant {
	val modified = try {
		fileSystem.metadata(path).lastModifiedAtMillis
	} catch (_: IOException) {
		null
	}
	if (modified != null) return Instant.fromEpochMilliseconds(modified)

	return encodedDate?.let { parseBackupDate(it) } ?: Instant.fromEpochMilliseconds(0)
}

private fun swapIntoPlace(restored: Path, target: Path, displaced: Path) {
	val hadExisting = fileSystem.exists(target)
	if (hadExisting) {
		fileSystem.atomicMove(target, displaced)
	} else {
		target.parent?.let { fileSystem.createDirectories(it) }
	}

	try {
		fileSystem.atomicMove(restored, target)
	} catch (e: IOException) {
		if (hadExisting) fileSystem.atomicMove(displaced, target)
		throw e
	}
}

private fun archiveRoot(extracted: Path): Path {
	val onlyChild = fileSystem.list(extracted).singleOrNull() ?: return extracted
	return if (fileSystem.metadata(onlyChild).isDirectory) onlyChild else extracted
}

fun getBackedUpProjects(): List<ProjectDef> {
	val backupKeys = fileSystem.list(getBackupsDirectory().toOkioPath())
		.mapNotNull { FILE_NAME_PATTERN.matchEntire(it.name)?.groups?.get(1)?.value }
		.toSet()

	val projects = projectsRepository.getProjects()
	val existing = projects.filter { project ->
		backupKeysForProject(project.name).any { it in backupKeys }
	}

	val claimedKeys = projects.flatMap { backupKeysForProject(it.name) }.toSet()
	val missingNames = (backupKeys - claimedKeys)
		.map { ProjectsRepository.decodeFromFilename(it) }
		.filter { validateProjectName(it) }
		.distinct()

	// A legacy-named backup belongs to the project whose current name also has backups.
	val legacyAliases = missingNames
		.filter { legacyBackupName(it) != it }
		.map { legacyBackupName(it) }
		.toSet()
	val missing = missingNames
		.filterNot { it in legacyAliases }
		.map { projectsRepository.getProjectDefinition(it) }

	return existing + missing
}

class ProjectDataConflictBroker(
	val projectDef: ProjectDef,
) : ProjectScoped {

	override val projectScope = ProjectDefScope(projectDef)

	private val _conflicts = Channel<ProjectDataConflict>(Channel.BUFFERED)
	private val _resolutions = Channel<Resolution>(Channel.BUFFERED)

	val conflicts: ReceiveChannel<ProjectDataConflict> get() = _conflicts

	suspend fun reportConflict(conflict: ProjectDataConflict) = _conflicts.send(conflict)
	fun resolve(resolved: ProjectData) {
		_resolutions.trySend(Resolution.Resolved(resolved))
	}

	/**
	 * Abort an in-flight conflict, failing the sync instead of waiting for an interactive
	 * resolution. Used by flows without a resolver UI (bulk account sync), where a project-data
	 * conflict would otherwise hang the project forever in [awaitResolution]. Delivers an abort
	 * sentinel rather than closing the channels, so this project-scoped singleton stays reusable
	 * for any later sync in the same scope.
	 */
	fun abort() {
		_resolutions.trySend(Resolution.Aborted)
	}

	/**
	 * Suspends until the reported conflict is [resolve]d or [abort]ed. Throws
	 * [ProjectDataConflictUnresolvedException] on abort so the sync reports failure.
	 */
	suspend fun awaitResolution(): ProjectData {
		return when (val resolution = _resolutions.receive()) {
			is Resolution.Resolved -> resolution.data
			Resolution.Aborted -> throw ProjectDataConflictUnresolvedException()
		}
	}

	private sealed interface Resolution {
		data class Resolved(val data: ProjectData) : Resolution
		data object Aborted : Resolution
	}
}

fun abort() {
	_resolutions.trySend(Resolution.Aborted)
}

suspend fun awaitResolution(): ProjectData {
	return when (val resolution = _resolutions.receive()) {
		is Resolution.Resolved -> resolution.data
		Resolution.Aborted -> throw ProjectDataConflictUnresolvedException()
	}
}

class ProjectDataDatasource(
	private val fileSystem: FileSystem,
	private val toml: Toml,
	val projectDef: ProjectDef,
) : ProjectScoped {

	override val projectScope = ProjectDefScope(projectDef)
	private val dispatcherIo by injectIoDispatcher()

	fun getPath(): Path = projectDef.path.toOkioPath() / FILENAME

	suspend fun load(): StoredProjectData = withContext(dispatcherIo) {
		val path = getPath()
		if (!fileSystem.exists(path)) return@withContext StoredProjectData()
		fileSystem.readTomlOrNull<StoredProjectData>(path, toml) { e ->
			Napier.e("Failed to load project_data.toml: $path", e)
		} ?: StoredProjectData()
	}

	suspend fun save(stored: StoredProjectData): Unit = withContext(dispatcherIo) {
		saveStoredProjectData(projectDef, fileSystem, toml, stored)
	}

	companion object {
		const val FILENAME = "project_data.toml"
	}
}

suspend fun loadStoredProjectData(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
	toml: Toml,
): StoredProjectData = withContext(Dispatchers.IO) {
	readStoredProjectData(projectDef, fileSystem, toml)
}

fun readStoredProjectData(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
	toml: Toml,
): StoredProjectData {
	val path = projectDef.path.toOkioPath() / ProjectDataDatasource.FILENAME
	return fileSystem.readTomlOrNull<StoredProjectData>(path, toml) { e ->
		Napier.d("No project_data.toml at $path (${e.message})")
	} ?: StoredProjectData()
}

fun saveStoredProjectData(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
	toml: Toml,
	stored: StoredProjectData,
) {
	fileSystem.writeToml(projectDef.path.toOkioPath() / ProjectDataDatasource.FILENAME, toml, stored)
}

fun clearProjectDataSyncBaseline(
	projectDef: ProjectDef,
	fileSystem: FileSystem,
	toml: Toml,
) {
	if (!fileSystem.exists(projectDef.path.toOkioPath() / ProjectDataDatasource.FILENAME)) return
	val stored = readStoredProjectData(projectDef, fileSystem, toml)
	if (stored.lastSyncedHash == null) return
	saveStoredProjectData(projectDef, fileSystem, toml, stored.copy(lastSyncedHash = null))
}

suspend fun updateData(transform: (ProjectData) -> ProjectData) = mutex.withLock {
	val current = _state.value ?: datasource.load()
	val nextData = transform(current.data)
	if (nextData == current.data) return@withLock
	val next = current.copy(data = nextData)
	datasource.save(next)
	_state.value = next
	// Project data is part of the project-wide hash; invalidate so the probe re-syncs it.
	syncDataDatasource.invalidateProjectHash()
}

