suspend fun computeAutoReferencesForScene(
	sceneId: Int,
	sceneText: String,
	metadata: SceneMetadata?,
): List<EntrySuggestion> {
	val confirmed = metadata?.confirmedReferences.orEmpty()
	val dismissed = metadata?.dismissedReferences.orEmpty()

	val matchable = matchableEntries()
	if (matchable.isEmpty()) return emptyList()

	val hits = matcher.findMatches(sceneText, matchable)
	if (hits.isEmpty()) return emptyList()

	val firstHitByEntry = linkedMapOf<Int, EntrySuggestion>()
	for (hit in hits) {
		if (hit.entryId in confirmed) continue
		if (hit.entryId in dismissed) continue
		if (hit.entryId !in firstHitByEntry) {
			firstHitByEntry[hit.entryId] = EntrySuggestion(hit.entryId, hit.matchedText)
		}
	}
	return firstHitByEntry.values.toList()
}

suspend fun findScenesMatchingEntry(entryId: Int, names: List<String>): List<Int> {
	if (names.none { it.isNotBlank() }) return emptyList()
	val matchable = listOf(MatchableEntry(entryId, names))
	val results = mutableListOf<Int>()

	suspend fun consider(sceneItem: SceneItem) {
		val metadata = sceneMetadataRepository.loadSceneMetadata(sceneItem.id)
		if (entryId in metadata.confirmedReferences) return
		if (entryId in metadata.dismissedReferences) return
		val text = if (sceneItem.archived) {
			val scenePath = sceneEditorRepository
				.resolveScenePathFromFilesystemIncludingArchived(sceneItem.id) ?: return
			sceneEditorRepository.loadSceneMarkdownRaw(sceneItem, scenePath)
		} else {
			sceneEditorRepository.loadSceneMarkdownRaw(sceneItem)
		}
		val hits = matcher.findMatches(text, matchable)
		if (hits.isNotEmpty()) results.add(sceneItem.id)
	}

	val sceneTree = sceneEditorRepository.sceneTreeUpdates.first()
	sceneTree.root.forEach { node ->
		if (node.value.type == SceneItem.Type.Scene) {
			consider(node.value)
			yield()
		}
	}
	sceneEditorRepository.getArchivedScenes().forEach { archived ->
		consider(archived)
		yield()
	}
	return results
}

class SceneMetadataReferenceRemapper(
	private val sceneEditorRepository: SceneRepository,
	private val sceneMetadataDatasource: SceneMetadataDatasource,
	private val referenceIndexRepository: ReferenceIndexRepository,
) : ReferenceRemapper {
	override suspend fun remapEntryReferences(oldEntryId: Int, newEntryId: Int) {
		if (oldEntryId == newEntryId) return

		val sceneIds = collectAllSceneIds()
		var anyRewritten = false
		for (sceneId in sceneIds) {
			val metadata = sceneMetadataDatasource.loadMetadata(sceneId) ?: continue
			val rewritten = metadata.rewriteReferences(oldEntryId, newEntryId) ?: continue
			sceneMetadataDatasource.storeMetadata(rewritten, sceneId)
			anyRewritten = true
		}

		if (anyRewritten) referenceIndexRepository.markDirty()
	}

	private suspend fun collectAllSceneIds(): Set<Int> {
		val ids = mutableSetOf<Int>()
		val sceneTree = sceneEditorRepository.sceneTreeUpdates.first()
		sceneTree.root.forEach { node ->
			if (node.value.type == SceneItem.Type.Scene) ids.add(node.value.id)
		}
		sceneEditorRepository.getArchivedScenes().forEach { ids.add(it.id) }
		return ids
	}

	private fun SceneMetadata.rewriteReferences(oldId: Int, newId: Int): SceneMetadata? {
		val confirmedHasOld = oldId in confirmedReferences
		val dismissedHasOld = oldId in dismissedReferences
		if (!confirmedHasOld && !dismissedHasOld) return null

		return copy(
			confirmedReferences = if (confirmedHasOld) confirmedReferences - oldId + newId else confirmedReferences,
			dismissedReferences = if (dismissedHasOld) dismissedReferences - oldId + newId else dismissedReferences,
		)
	}
}

class ScrubInvalidReferencesUseCase(
	private val encyclopediaRepository: EncyclopediaRepository,
) {
	operator fun invoke(metadata: SceneMetadata): SceneMetadata {
		if (metadata.confirmedReferences.isEmpty() && metadata.dismissedReferences.isEmpty()) {
			return metadata
		}
		val newConfirmed = metadata.confirmedReferences
			.filterTo(HashSet()) { encyclopediaRepository.findEntryDef(it) != null }
		val newDismissed = metadata.dismissedReferences
			.filterTo(HashSet()) { encyclopediaRepository.findEntryDef(it) != null }
		return if (newConfirmed.size == metadata.confirmedReferences.size &&
			newDismissed.size == metadata.dismissedReferences.size
		) {
			metadata
		} else {
			metadata.copy(
				confirmedReferences = newConfirmed,
				dismissedReferences = newDismissed,
			)
		}
	}
}

