fun readSceneMarkdownInto(
	sceneItem: SceneItem,
	scenePath: HPath,
	sink: ScanBuffers,
): Int {
	if (sceneItem.type != SceneItem.Type.Scene) return 0
	val path = scenePath.toOkioPath()
	return try {
		val byteCount = fileSystem.metadata(path).size ?: return 0
		if (byteCount <= 0L || byteCount > Int.MAX_VALUE) return 0
		fileSystem.read(path) { readUtf8Into(sink, byteCount.toInt()) }
	} catch (e: IOException) {
		Napier.e("Failed to read Scene markdown (${sceneItem.name})")
		0
	}
}

fun buildSceneFileName(order: String, name: String, id: Int, isGroup: Boolean = false): String {
	val extension = if (isGroup) "" else SCENE_FILENAME_EXTENSION
	return "$order~${ProjectsRepository.encodeForFilename(name)}~$id$extension"
}

fun createArchivedSceneFile(sceneItem: SceneItem, content: String): HPath {
	val archiveDir = getArchivedDirectory().toOkioPath()
	val fileName = buildArchivedSceneFileName(sceneItem.name, sceneItem.id)
	val targetPath = archiveDir / fileName

	fileSystem.write(targetPath) {
		writeUtf8(content)
	}

	return targetPath.toHPath()
}

fun Collection<HPath>.validateScenePaths(): List<HPath> {
	val seen = LinkedHashMap<Int, HPath>()
	for (path in this) {
		val id = SceneDatasource.getSceneIdFromFilename(path.toOkioPath().name)
		val existing = seen[id]
		if (existing == null) {
			seen[id] = path
		} else {
			Napier.e("Duplicate scene id $id on disk: keeping ${existing.name}, refusing ${path.name}")
		}
	}
	return seen.values.toList()
}

