class StickyHeaderItemDecoration constructor(
        context: Context?,
        private val callback: Callback
) : RecyclerView.ItemDecoration() {

    private val textPaint = TextPaint()
    private val labelPadding: Int
    private val contentMargin: Int
    private val fontMetrics: Paint.FontMetrics

    init {
        val resource = context!!.resources

        textPaint.apply {
            typeface = ResourcesCompat.getFont(context, R.font.notosans_medium)
            isAntiAlias = true
            textSize = resource.getDimension(R.dimen.sticky_label_font_size)
            color = ContextCompat.getColor(context, R.color.primary)
            textAlign = Paint.Align.LEFT
        }

        fontMetrics = textPaint.fontMetrics

        labelPadding = resource.getDimensionPixelSize(R.dimen.sticky_label_padding)
        contentMargin = resource.getDimensionPixelSize(R.dimen.sticky_label_content_margin)
    }

    override fun getItemOffsets(outRect: Rect, view: View, parent: RecyclerView,
                                state: RecyclerView.State) {
        super.getItemOffsets(outRect, view, parent, state)

        val position = parent.getChildAdapterPosition(view)
        val groupId = callback.getGroupId(position)

        if (groupId < 0) {
            return
        }

        if (view.isLayoutDirectionRtl()) {
            outRect.right = contentMargin
        } else {
            outRect.left = contentMargin
        }
    }

    override fun onDraw(c: Canvas, parent: RecyclerView, state: RecyclerView.State) {
        super.onDraw(c, parent, state)

        val totalItemCount = state.itemCount
        val childCount = parent.childCount
        val lineHeight = textPaint.textSize + fontMetrics.descent
        var previousGroupId: Long
        var groupId: Long = -1

        for (i in 0 until childCount) {
            val view = parent.getChildAt(i)
            val position = parent.getChildAdapterPosition(view)

            previousGroupId = groupId
            groupId = callback.getGroupId(position)

            if (groupId < 0 || previousGroupId == groupId) continue

            val textLine = callback.getGroupFirstLine(position)
            if (TextUtils.isEmpty(textLine)) continue

            val textX = if (view.isLayoutDirectionRtl()) {
                labelPadding.toFloat() + view.width.toFloat()
            } else {
                labelPadding.toFloat()
            }

            val viewBottom = view.bottom + view.paddingBottom
            var textY = Math.max(view.height, viewBottom) - lineHeight
            if (position + 1 < totalItemCount) {
                val nextGroupId = callback.getGroupId(position + 1)
                if (nextGroupId != groupId && viewBottom < textY + lineHeight) {
                    textY = viewBottom - lineHeight
                }
            }
            c.drawText(textLine, textX, textY, textPaint)
        }
    }

    interface Callback {
        fun getGroupId(position: Int): Long
        fun getGroupFirstLine(position: Int): String?
    }
}

class Rotate : Transition {

    @Keep constructor() : super()
    @Keep constructor(context: Context, attrs: AttributeSet) : super(context, attrs)

    override fun getTransitionProperties(): Array<String> {
        return TRANSITION_PROPERTIES
    }

    override fun captureStartValues(transitionValues: TransitionValues) {
        captureValues(transitionValues)
    }

    override fun captureEndValues(transitionValues: TransitionValues) {
        captureValues(transitionValues)
    }

    override fun createAnimator(sceneRoot: ViewGroup, startValues: TransitionValues?,
                                endValues: TransitionValues?): Animator? {
        if (startValues == null || endValues == null) return null

        val startRotation = startValues.values[PROP_ROTATION] as Float
        val endRotation = endValues.values[PROP_ROTATION] as Float
        if (startRotation == endRotation) return null

        val view = endValues.view
        // ensure the pivot is set
        view.pivotX = view.width / 2f
        view.pivotY = view.height / 2f
        return ObjectAnimator.ofFloat(endValues.view, View.ROTATION, startRotation, endRotation)
    }

    private fun captureValues(transitionValues: TransitionValues) {
        val view = transitionValues.view
        if (view == null || view.width <= 0 || view.height <= 0) return
        transitionValues.values.put(PROP_ROTATION, view.rotation)
    }

    companion object {
        private const val PROP_ROTATION = "iosched:rotate:rotation"
        private val TRANSITION_PROPERTIES = arrayOf(PROP_ROTATION)
    }
}

class BottomBarBehavior(context: Context, attrs: AttributeSet) :
        CoordinatorLayout.Behavior<ConstraintLayout>(context, attrs) {

    private var defaultDependencyTop = -1

    override fun layoutDependsOn(parent: CoordinatorLayout?, bottomBar: ConstraintLayout?,
                                 dependency: View?): Boolean {
        return dependency is AppBarLayout
    }

    override fun onDependentViewChanged(parent: CoordinatorLayout, bottomBar: ConstraintLayout,
                                        dependency: View): Boolean {
        if (defaultDependencyTop == -1) {
            defaultDependencyTop = dependency.top
        }
        bottomBar.translationY = (-dependency.top + defaultDependencyTop).toFloat()
        return true
    }
}

open class BottomNavigationBehavior : CoordinatorLayout.Behavior<BottomNavigationView> {

    // for set behavior on programmatically
    @Keep constructor() : super()

    // for set behavior on XML
    @Keep constructor(context: Context, attrs: AttributeSet) : super(context, attrs)

    private var isSnackbarAppear: Boolean = false
    private var snackbar: Snackbar.SnackbarLayout? = null

    override fun layoutDependsOn(parent: CoordinatorLayout?, child: BottomNavigationView?,
                                 dependency: View?): Boolean {
        return dependency is Snackbar.SnackbarLayout
    }

    override fun onDependentViewChanged(parent: CoordinatorLayout?, child: BottomNavigationView?,
                                        dependency: View?): Boolean {
        if (dependency is Snackbar.SnackbarLayout) {
            if (isSnackbarAppear) return true
            isSnackbarAppear = true
            snackbar = dependency
            child?.let { updateSnackBarPaddingBottomByBottomNavigationView(it) }
            return true
        }
        return false
    }

    override fun onDependentViewRemoved(parent: CoordinatorLayout?, child: BottomNavigationView?,
                                        dependency: View?) {
        when (dependency) {
            is Snackbar.SnackbarLayout -> {
                isSnackbarAppear = false
                snackbar = null
            }
            else -> super.onDependentViewRemoved(parent, child, dependency)
        }
    }

    internal fun updateSnackBarPaddingBottomByBottomNavigationView(view: BottomNavigationView) {
        snackbar?.apply {
            val translateY = (view.height - view.translationY).toInt()
            setPaddingWithLayoutDirection(paddingStart, paddingTop, paddingEnd, translateY)
            requestLayout()
        }
    }
}

class BottomNavigationHideBehavior : BottomNavigationBehavior {
    @Keep constructor() : super()
    @Keep constructor(context: Context, attrs: AttributeSet) : super(context, attrs)

    private var isAnimation: Boolean = false
    private var isFlinging: Boolean = false
    private var needsShowBnv: Boolean = false
    private val animationListener = object : Animator.AnimatorListener {
        override fun onAnimationRepeat(animation: Animator?) {
        }

        override fun onAnimationEnd(animation: Animator?) {
            isAnimation = false
        }

        override fun onAnimationCancel(animation: Animator?) {
            isAnimation = false
        }

        override fun onAnimationStart(animation: Animator?) {
            isAnimation = true
        }
    }

    override fun onStartNestedScroll(coordinatorLayout: CoordinatorLayout,
                                     child: BottomNavigationView, directTargetChild: View,
                                     target: View, axes: Int, type: Int): Boolean {
        return axes == ViewCompat.SCROLL_AXIS_VERTICAL
    }

    override fun onNestedScroll(coordinatorLayout: CoordinatorLayout, child: BottomNavigationView,
                                target: View, dxConsumed: Int, dyConsumed: Int, dxUnconsumed: Int,
                                dyUnconsumed: Int, type: Int) {
        // skip scroll event via fling
        if (isFlinging && type == ViewCompat.TYPE_NON_TOUCH) return
        when {
        // positive value: finger's move = touch -> move up (contents are scrolled downward)
            dyConsumed > THRESHOLD_PX -> hideBottomNavigationView(child)
        // negative value: finger's move = touch -> move down (contents are scrolled upward)
            dyConsumed < THRESHOLD_PX -> showBottomNavigationView(child)
        // ignore case: user scrolls contents upward but contents are too short to scroll
            dyConsumed == 0 && dyUnconsumed < 0 -> needsShowBnv = true
            else -> Unit
        }
        super.onNestedScroll(coordinatorLayout, child, target, dxConsumed, dyConsumed,
                dxUnconsumed, dyUnconsumed, type)
    }

    override fun onNestedFling(coordinatorLayout: CoordinatorLayout, child: BottomNavigationView,
                               target: View, velocityX: Float, velocityY: Float,
                               consumed: Boolean): Boolean {
        isFlinging = true
        when {
            velocityY > 0 -> hideBottomNavigationView(child)
            velocityY < 0 -> showBottomNavigationView(child)
            else -> Unit
        }
        return super.onNestedFling(coordinatorLayout, child, target, velocityX, velocityY, consumed)
    }

    override fun onStopNestedScroll(coordinatorLayout: CoordinatorLayout,
                                    child: BottomNavigationView, target: View, type: Int) {
        if (type == ViewCompat.TYPE_NON_TOUCH) isFlinging = false
        if (needsShowBnv) {
            // user touches screen but contents are not scrolled
            // this happens like contents are shot enough which has no reason to scroll
            // on the situation, it is necessary for the user to show BNV
            showBottomNavigationView(child)
            needsShowBnv = false
        }
        super.onStopNestedScroll(coordinatorLayout, child, target, type)
    }

    private fun showBottomNavigationView(view: BottomNavigationView) {
        if (isAnimation) return
        view.animate().apply {
            translationY(0f)
            duration = DURATION_MILLIS
            setListener(animationListener)
            setUpdateListener { updateSnackBarPaddingBottomByBottomNavigationView(view) }
        }
    }

    private fun hideBottomNavigationView(view: BottomNavigationView) {
        if (isAnimation) return
        view.animate().apply {
            translationY(view.height.toFloat())
            duration = DURATION_MILLIS
            setListener(animationListener)
            setUpdateListener { updateSnackBarPaddingBottomByBottomNavigationView(view) }
        }
    }

    companion object {
        const val DURATION_MILLIS: Long = 150L
        const val THRESHOLD_PX: Int = 0
    }
}

class ContentWithBottomNavigationBehavior(context: Context, attrs: AttributeSet) :
        CoordinatorLayout.Behavior<ViewGroup>(context, attrs) {
    private var previousHeight: Float = 0f

    override fun onMeasureChild(parent: CoordinatorLayout, child: ViewGroup,
                                parentWidthMeasureSpec: Int, widthUsed: Int,
                                parentHeightMeasureSpec: Int, heightUsed: Int): Boolean {
        val bnv: BottomNavigationView = parent.getDependencies(child)
                .firstOrNull { it is BottomNavigationView } as? BottomNavigationView
        // this behavior specified for ViewGroup used with BottomNavigationView
                ?: return super.onMeasureChild(parent, child, parentWidthMeasureSpec,
                        widthUsed, parentHeightMeasureSpec, heightUsed)

        // avoid the content is overlapped by BottomNavigationView
        // compute content area size to fits to BNV upper line

        // compute CoordinatorLayout height
        val parentMeasureSpecHeight = View.MeasureSpec.getSize(parentHeightMeasureSpec)
        val availableHeight =
                if (parentMeasureSpecHeight == 0) parent.height else parentMeasureSpecHeight

        // compute BottomNavigationView height
        // translationY == 0 means BNV perfectly showed so content area fits to BNV upper line
        // otherwise BNV is going to hide and content area fits to CoordinatorLayout bottom line
        // if use BNV's just height we cannot scroll smoothly.
        val bnvHeight = if (bnv.translationY == 0f) bnv.height else 0

        val heightMeasureSpec = View.MeasureSpec.makeMeasureSpec(availableHeight - bnvHeight,
                View.MeasureSpec.EXACTLY)
        parent.onMeasureChild(child, parentWidthMeasureSpec, widthUsed,
                heightMeasureSpec, heightUsed)
        return true
    }

    override fun layoutDependsOn(parent: CoordinatorLayout?, child: ViewGroup?,
                                 dependency: View?): Boolean {
        return dependency is BottomNavigationView
    }

    override fun onDependentViewChanged(parent: CoordinatorLayout?, child: ViewGroup?,
                                        dependency: View?): Boolean {
        if (dependency is BottomNavigationView) {
            val height = dependency.height - dependency.translationY
            if (previousHeight != height) {
                child?.requestLayout()
                previousHeight = height
            }
            return true
        }
        return super.onDependentViewChanged(parent, child, dependency)
    }
}

class SpeakersSummaryLayout @JvmOverloads constructor(
        context: Context,
        attrs: AttributeSet? = null,
        defStyleAttr: Int = 0) : LinearLayout(context, attrs, defStyleAttr) {

    data class CustomAttributes(val textColor: Int)

    private val speakerList: ArrayList<Speaker> = ArrayList()
    private val speakerContainer: RecyclerView
    private val customAttributes: CustomAttributes
    private var speakerIdInDetail: String? = null

    private fun customAttributesFrom(context: Context, attrs: AttributeSet?): CustomAttributes {
        val defaultAttributes = CustomAttributes(
                textColor = Color.BLACK
        )

        return attrs?.let {
            val a: TypedArray = context.theme.obtainStyledAttributes(attrs,
                    R.styleable.SpeakersSummaryLayout, 0, 0)
            val textColor = a.getColor(R.styleable.SpeakersSummaryLayout_textColor,
                    defaultAttributes.textColor)
            a.recycle()

            return CustomAttributes(
                    textColor = textColor
            )
        } ?: defaultAttributes
    }

    init {
        customAttributes = customAttributesFrom(context, attrs)
        orientation = HORIZONTAL
        gravity = Gravity.CENTER_VERTICAL

        LayoutInflater.from(context).inflate(R.layout.view_speakers_summary_layout, this)
        speakerContainer = findViewById(R.id.speaker_container)

        speakerContainer.layoutManager = LinearLayoutManager(context)
        setSpeakers(speakerList)
    }

    /**
     * set Speaker's icons and names.
     *
     * Speakers can be set not only by setting this method explicitly,
     * but also by using data-binding like this:
     *
     *   <SpeakerSummaryLayout
     *     android:layout_width="wrap_content"
     *     android:layout_height="wrap_content"
     *     app:speakers="@{speakers}"
     *     />
     */
    fun setSpeakers(speakers: List<Speaker>?) {
        speakers ?: return
        if (speakerList == speakers) return
        speakerList.clear()
        speakerList.addAll(speakers)

        updateSpeakers()
    }

    fun setSpeakerIdInDetail(speakerId: String?) {
        speakerIdInDetail = speakerId
    }

    private fun updateSpeakers() {
        if (speakerList.isEmpty()) return

        val speakerAdapter = SpeakersAdapter(context, speakerList, customAttributes.textColor)
        speakerContainer.adapter = speakerAdapter

        speakerAdapter.onSpeakerClick = { view, speakerId ->
            if (speakerIdInDetail == null ||
                    (speakerIdInDetail != null && !speakerIdInDetail.equals(speakerId))) {
                val sharedElement = Pair(
                        view.findViewById<View>(R.id.speaker_image),
                        speakerId)
                SpeakerDetailActivity.start(
                        activity = context as AppCompatActivity,
                        sharedElement = sharedElement,
                        speakerId = speakerId)
            }
        }
    }
}

