private val PDF_DATE_PATTERN = Regex(
    """
        ^D:
        (\d{4}

private fun parseOffset(matchResult: MatchResult): ZoneOffset {
    val utRel = matchResult.groups[7]?.value
    val offsetHours = parseGroup(matchResult, 8, 0)
    val offsetMinutes = parseGroup(matchResult, 9, 0)

    if (utRel == null || utRel == "Z") {
        if (offsetHours != 0 || offsetMinutes != 0) {
            throw ParseException("UTC indicator 'Z' must not have a non-zero offset", 0)
        }
        return ZoneOffset.UTC
    }
    if (offsetMinutes > 59) {
        throw ParseException("Invalid UTC offset minutes", 0)
    }
    val magnitude = offsetHours * 100 + offsetMinutes
    if (utRel == "-") {
        if (magnitude > 1200) {
            throw ParseException("Invalid UTC offset", 0)
        }
        return ZoneOffset.ofHoursMinutes(-offsetHours, -offsetMinutes)
    }
    if (magnitude > 1400) {
        throw ParseException("Invalid UTC offset", 0)
    }
    return ZoneOffset.ofHoursMinutes(offsetHours, offsetMinutes)
}

@Throws(ParseException::class)
fun parseDate(date: String): String {
    // D: prefix is optional for PDF < v1.7; required for PDF v1.7+
    val input = if (date.startsWith("D:")) date else "D:$date"

    val matchResult = PDF_DATE_PATTERN.matchEntire(input)
        ?: throw ParseException("Invalid date format", 0)

    // java.time months are 1-based; an absent month or day defaults to 1, the
    // time fields to 0.
    val year = parseIntSafely(matchResult.groups[1]!!.value)
    val month = parseGroup(matchResult, 2, 1)
    val day = parseGroup(matchResult, 3, 1)
    val hours = parseGroup(matchResult, 4, 0)
    val minutes = parseGroup(matchResult, 5, 0)
    val seconds = parseGroup(matchResult, 6, 0)
    val offset = parseOffset(matchResult)

    // LocalDateTime.of validates the fields and rejects impossible dates such
    // as February 31; the offset then resolves it to a definite instant.
    val instant: Date = try {
        Date.from(LocalDateTime.of(year, month, day, hours, minutes, seconds).toInstant(offset))
    } catch (_: DateTimeException) {
        throw ParseException("Invalid date", 0)
    }

    // Rendered in the device's default time zone and locale.
    return DateFormat
        .getDateTimeInstance(DateFormat.DEFAULT, DateFormat.LONG)
        .format(instant)
}

public class TestPdfProvider extends ContentProvider {

    public static final String AUTHORITY = "app.grapheneos.pdfviewer.test.provider";

    @Override
    public boolean onCreate() {
        return true;
    }

    @Override
    public ParcelFileDescriptor openFile(Uri uri, @NonNull String mode) throws FileNotFoundException {
        String filename = uri.getLastPathSegment();
        if (filename == null) {
            throw new FileNotFoundException("URI must include a filename");
        }

        String failAfter = uri.getQueryParameter("failAfter");
        if (failAfter != null) {
            return openFailingPipe(filename, Integer.parseInt(failAfter));
        }

        File file = new File(getContext().getCacheDir(), filename);
        if (!file.exists()) {
            try {
                InputStream is = getContext().getAssets().open(filename);
                FileOutputStream os = new FileOutputStream(file);
                byte[] buffer = new byte[8192];
                int read;
                while ((read = is.read(buffer)) != -1) {
                    os.write(buffer, 0, read);
                }
                os.close();
                is.close();
            } catch (IOException e) {
                throw new FileNotFoundException(
                        "Failed to copy asset '" + filename + "': " + e.getMessage());
            }
        }

        return ParcelFileDescriptor.open(file, ParcelFileDescriptor.MODE_READ_ONLY);
    }

    private ParcelFileDescriptor openFailingPipe(final String filename, final int bytesBeforeFailure)
            throws FileNotFoundException {
        final ParcelFileDescriptor[] pipe;
        try {
            pipe = ParcelFileDescriptor.createReliablePipe();
        } catch (IOException e) {
            throw new FileNotFoundException("Failed to create pipe: " + e.getMessage());
        }
        final ParcelFileDescriptor readEnd = pipe[0];
        final ParcelFileDescriptor writeEnd = pipe[1];

        new Thread(() -> {
            try (InputStream in = getContext().getAssets().open(filename)) {
                FileOutputStream out = new FileOutputStream(writeEnd.getFileDescriptor());
                byte[] buffer = new byte[8192];
                int totalWritten = 0;
                while (totalWritten < bytesBeforeFailure) {
                    int toRead = Math.min(buffer.length, bytesBeforeFailure - totalWritten);
                    int read = in.read(buffer, 0, toRead);
                    if (read == -1) break;
                    out.write(buffer, 0, read);
                    totalWritten += read;
                }
                out.flush();
            } catch (IOException ignored) {}
            try {
                writeEnd.closeWithError("Simulated mid-read failure");
            } catch (IOException ignored) {}
        }, "TestPdfProvider-failing-pipe").start();

        return readEnd;
    }

    @Override
    public String getType(@NonNull Uri uri) {
        return "application/pdf";
    }

    @Override
    public Cursor query(Uri uri, String[] projection, String selection,
                        String[] selectionArgs, String sortOrder) {
        String assetName = uri.getLastPathSegment();
        if (assetName == null) return null;

        if (projection == null) {
            projection = new String[]{
                    OpenableColumns.DISPLAY_NAME,
                    OpenableColumns.SIZE
            };
        }

        MatrixCursor cursor = new MatrixCursor(projection, 1);
        Object[] row = new Object[projection.length];
        for (int i = 0; i < projection.length; i++) {
            if (OpenableColumns.DISPLAY_NAME.equals(projection[i])) {
                row[i] = assetName;
            } else if (OpenableColumns.SIZE.equals(projection[i])) {
                row[i] = null;
            }
        }
        cursor.addRow(row);
        return cursor;
    }

    @Override
    public Uri insert(@NonNull Uri uri, ContentValues values) { return null; }
    @Override
    public int delete(@NonNull Uri uri, String s, String[] a) { return 0; }
    @Override
    public int update(@NonNull Uri uri, ContentValues v, String s, String[] a) { return 0; }
}

