private class BufferExecutor : ExecutorService, Executor {
    val taskQueue = ArrayDeque<Task>()
    var activeTask: Task? = null

    // 加入一级队列时被记录，任务执行完成时被移除
    val flightTaskMap = ConcurrentHashMap<Int, FlightTaskInfo>()

    @Synchronized
    override fun execute(r: Runnable) {
        taskQueue.offer(
            Task(
                r, if (TheRouter.isDebug) {
                    checkTask()
                    getTrace(Thread.currentThread().stackTrace)
                } else {
                    ""
                }
            ) {
                if (TheRouter.isDebug) {
                    flightTaskMap.remove(r.hashCode())
                }
                scheduleNext()
            })
        //activeTask 不为空，表示一级队列已经满了，此刻任务应该被停留到二级队列等待调度
        if (activeTask == null) {
            scheduleNext()
        }
    }

    /**
     * 检查是否有频繁添加任务，或有轮询任务的情况
     */
    private fun checkTask() {
        flightTaskMap.values.forEach { v ->
            require(
                ((System.nanoTime() - v.createTime) / 1000L / 1_000_000L) < (KEEP_ALIVE_SECONDS),
                "ThreadPool",
                "执行该任务耗时过久，有可能是此任务耗时，或者当前线程池中其他任务都很耗时，请优化逻辑\n" +
                        "当前任务被创建时间为${v.createTime}此时时间为${System.nanoTime()}\n${v.trace}"
            )
        }
    }

    /**
     * 从二级队列调度任务，将任务放入一级队列，或直接交由线程池执行
     */
    @Synchronized
    private fun scheduleNext() {
        fun doNext() {
            //从二级队列中取任务
            if (taskQueue.poll().also { activeTask = it } != null) {
                activeTask?.let {
                    if (TheRouter.isDebug) {
                        flightTaskMap[it.r.hashCode()] = FlightTaskInfo(it.trace)
                    }
                }
                //将任务加入一级队列，或有可能直接被线程池执行(Executor内部逻辑)
                threadPoolExecutor.execute(activeTask)
                activeTask = null
            }
        }

        val isMainThread = Thread.currentThread() == Looper.getMainLooper().thread
        if (isMainThread) {
            doNext()
        } else {
            //线程池中正在执行的任务数
            val activeCount = threadPoolExecutor.activeCount
            //一级队列任务数
            val queueSize = threadPoolExecutor.queue.size

            //动态修改核心线程数，以适应不同场景的任务量
            when {
                taskQueue.size > MAX_QUEUE_SIZE * 100 -> {
                    threadPoolExecutor.corePoolSize = MAXIMUM_CORE_POOL_SIZE
                }

                taskQueue.size > MAX_QUEUE_SIZE * 10 -> {
                    threadPoolExecutor.corePoolSize = BIGGER_CORE_POOL_SIZE
                }

                else -> {
                    threadPoolExecutor.corePoolSize = CORE_POOL_SIZE
                }
            }

            //如果一级队列没有满，且当前正在执行的线程不超过核心线程数
            if (queueSize <= MAX_QUEUE_SIZE && activeCount < threadPoolExecutor.corePoolSize) {
                doNext()
            }
        }
    }

    @Synchronized
    override fun shutdown() {
        threadPoolExecutor.shutdown()
    }

    @Synchronized
    override fun shutdownNow(): List<Runnable> {
        return threadPoolExecutor.shutdownNow()
    }

    @Synchronized
    override fun isShutdown(): Boolean {
        return threadPoolExecutor.isShutdown
    }

    @Synchronized
    override fun isTerminated(): Boolean {
        return threadPoolExecutor.isTerminated
    }

    @Synchronized
    @Throws(InterruptedException::class)
    override fun awaitTermination(timeout: Long, unit: TimeUnit): Boolean {
        return threadPoolExecutor.awaitTermination(timeout, unit)
    }

    @Synchronized
    override fun <T> submit(task: Callable<T>): Future<T> {
        return threadPoolExecutor.submit(task)
    }

    @Synchronized
    override fun <T> submit(task: Runnable, result: T): Future<T> {
        return threadPoolExecutor.submit(task, result)
    }

    @Synchronized
    override fun submit(task: Runnable): Future<*> {
        return threadPoolExecutor.submit(task)
    }

    @Synchronized
    @Throws(InterruptedException::class)
    override fun <T> invokeAll(tasks: Collection<Callable<T>?>): List<Future<T>> {
        return threadPoolExecutor.invokeAll(tasks)
    }

    @Synchronized
    @Throws(InterruptedException::class)
    override fun <T> invokeAll(tasks: Collection<Callable<T>?>, timeout: Long, unit: TimeUnit): List<Future<T>> {
        return threadPoolExecutor.invokeAll(tasks, timeout, unit)
    }

    @Synchronized
    @Throws(ExecutionException::class, InterruptedException::class)
    override fun <T> invokeAny(tasks: Collection<Callable<T>?>): T {
        return threadPoolExecutor.invokeAny(tasks)
    }

    @Synchronized
    @Throws(ExecutionException::class, InterruptedException::class, TimeoutException::class)
    override fun <T> invokeAny(tasks: Collection<Callable<T>?>, timeout: Long, unit: TimeUnit): T {
        return threadPoolExecutor.invokeAny(tasks, timeout, unit)
    }
}

fun onVirtualTaskDoneListener(name: String) {
    virtualTasks.values.forEach {
        if (it.dependencies.contains(name)) {
            it.dependTaskStatusChanged()
        }
    }
}

fun getDepends(root: Task): Set<Task> {
    val set: MutableSet<Task> = HashSet()
    val dependencies = root.dependencies
    for (key in dependencies) {
        val task = tasks[key]
        // 不存在的Task，有可能是手误写错的，也可能是业务节点Task，全部构建为 VirtualFlowTask，等待手动触发
        if (task == null) {
            virtualTasks[key] = makeVirtualFlowTask(key)
        } else {
            set.add(task)
        }
    }
    return set
}

class VirtualFlowTask(taskName: String, dependsOn: String = "") : Task(true, taskName, dependsOn, null) {
    // 当前任务已经可以被执行，需等待依赖的Task是否执行完毕
    @Volatile
    private var ready = false

    /**
     * 依赖 Task 状态有变化后，需要重新查看当前Task是否可以执行了
     */
    fun dependTaskStatusChanged() {
        if (ready) {
            run()
        }
    }

    /**
     * 所有的依赖Task都已经执行完毕
     */
    private fun allReady(): Boolean {
        var allDependTaskReady = true
        dependencies.forEach {
            allDependTaskReady = allDependTaskReady && TheRouter.digraph.getVirtualTask(it).isDone()
        }
        return allDependTaskReady
    }

    @CallSuper
    override fun run() {
        ready = true
        if (state != DONE && allReady()) {
            debug("FlowTask", "Virtual Flow Task $taskName done")
            state = DONE
            TheRouter.digraph.schedule()
            TheRouter.digraph.onVirtualTaskDoneListener(taskName)
        }
    }
}

fun dependTaskStatusChanged() {
    if (ready) {
        run()
    }
}

class ClassWrapper<T>(private val clazz: Class<T>, vararg params: Any?) {
    var key: String? = null
    fun unWrapper(): Class<T> {
        return clazz
    }

    override fun equals(o: Any?): Boolean {
        return if (o is ClassWrapper<*>) {
            unWrapper() == o.unWrapper() && key == o.key
        } else {
            super.equals(o)
        }
    }

    override fun hashCode(): Int {
        return (unWrapper().hashCode().toString() + "" + (key ?: "").hashCode()).hashCode()
    }

    init {
        params.forEach {
            it?.let {
                key += it.toString()
            }
        }
    }
}

internal fun getAllDI(context: Context?) {
    if (context == null || inited >= 0) {
        return
    }
    inited = 0
    try {
        val info = context.packageManager.getApplicationInfo(context.packageName, 0)
        val path = info.sourceDir
        val dexfile = DexFile(path)
        val entries = dexfile.entries()
        while (entries.hasMoreElements()) {
            val name = entries.nextElement()
            if (name.startsWith("$PACKAGE.$PREFIX_SERVICE_PROVIDER") && !name.contains("\$")) {
                try {
                    val clazz = Class.forName(name)
                    if (Interceptor::class.java.isAssignableFrom(clazz) && Interceptor::class.java != clazz) {
                        serviceProviderIndex.add(clazz.newInstance() as Interceptor)
                    }
                } catch (e: Exception) {
                    debug("RouterInject", "create class error for $name") {
                        e.printStackTrace()
                    }
                }
            } else if (name.startsWith("$PACKAGE.$PREFIX_ROUTER_MAP") && !name.contains("\$")) {
                try {
                    val clazz = Class.forName(name)
                    if (IRouterMapAPT::class.java.isAssignableFrom(clazz) && IRouterMapAPT::class.java != clazz) {
                        routerMapIndex.add(clazz.newInstance() as IRouterMapAPT)
                    }
                } catch (e: Exception) {
                    debug("RouterInject", "create class error for $name") {
                        e.printStackTrace()
                    }
                }
            } else if (name.endsWith(SUFFIX_AUTOWIRED) && !name.contains("\$")) {
                try {
                    val aptClazz = Class.forName(name)
                    val clazz = Class.forName(name.replace(SUFFIX_AUTOWIRED, ""))
                    autowiredIndex[clazz] = aptClazz.getDeclaredMethod("autowiredInject", Object::class.java)
                } catch (e: Exception) {
                    debug("RouterInject", "create class error for $name") {
                        e.printStackTrace()
                    }
                }
            }
        }
        inited = 1
    } catch (e: Exception) {
        debug("RouterInject", "getAllDI error") {
            e.printStackTrace()
        }
    }
}

