class RegexpKeyedMap<V> : HashMap<String?, V?>() {

    /**
     * 缓存预编译的正则表达式Pattern对象
     * 使用WeakHashMap确保不会阻止垃圾回收，避免内存泄漏
     */
    private val compiledPatterns = WeakHashMap<String?, Pattern>()

    /**
     * 获取预编译的正则表达式，如果缓存中没有则编译并缓存
     * 目的：避免在每次get()调用时重复编译相同的正则表达式
     */
    private fun getCompiledPattern(regex: String?): Pattern? {
        return compiledPatterns.getOrPut(regex) {
            Pattern.compile(regex!!)
        }
    }

    override fun get(key: String?): V? {
        if (key == null) return null

        // 直接查找
        var result = super.get(key)
        if (result != null) {
            return result
        }
        var keyPath: String? = null
        val index = key.indexOf('?')
        if (index > 0) {
            keyPath = key.substring(0, index)
            result = super.get(keyPath)
            if (result != null) {
                return result
            }
        }

        // 找不到，则进行正则匹配
        // 优化：使用缓存的Pattern对象，避免重复编译
        for (regex in keys) {
            if (regex == null || !regex.contains("\\")) {
                continue
            }
            // 优化点：从缓存获取预编译的Pattern，而不是每次都调用Pattern.compile()
            val pattern = getCompiledPattern(regex)
            var m = pattern?.matcher(key)
            if (m?.find() == true) {
                result = super.get(regex)
                break
            }
            if (keyPath != null) {
                // 复用同一个matcher对象，避免重复创建
                m = pattern?.matcher(keyPath)
                if (m?.find() == true) {
                    result = super.get(regex)
                    break
                }
            }
        }
        return result
    }
}

@Keep
class RouteItem : Parcelable, Serializable {

    var path = ""
    var className = ""
    var action = ""
    var description = ""

    // 仅用于RouteMap.json文件被gson转换时存储，外部不可访问
    private var params = HashMap<String, String>()

    // extras存储运行期的路由表参数
    private var extras = Bundle()

    /**
     * 标记params是否已经合并到extras中
     * 优化：避免每次getExtras()都重复遍历合并params
     */
    private var paramsMerged = false

    constructor()

    constructor(p: Parcel) {
        path = p.readString() ?: ""
        className = p.readString() ?: ""
        action = p.readString() ?: ""
        description = p.readString() ?: ""
        val obj = p.readSerializable()
        params = if (obj is HashMap<*, *>) {
            obj as HashMap<String, String>
        } else {
            HashMap<String, String>()
        }
        extras = p.readBundle(ClassLoader.getSystemClassLoader()) ?: Bundle()
    }

    constructor(path: String, className: String, action: String, description: String) {
        this.path = path
        this.className = className
        this.action = action
        this.description = description
    }

    fun addParams(key: String, value: String) {
        extras.putString(key, value)
    }

    /**
     * 将Bundle参数合并到extras中
     * 优化：设置paramsMerged标记，避免后续getExtras()重复合并
     */
    internal fun addAll(bundle: Bundle?) = bundle?.let {
        extras.putAll(it)
        paramsMerged = true  // 标记已合并，后续getExtras()无需再遍历params
    }

    /**
     * 获取路由参数
     * 优化：增加paramsMerged检查，只有在需要时才遍历合并params，避免重复计算
     * 原因：每次路由跳转都会调用getExtras()，频繁遍历HashMap影响性能
     */
    fun getExtras(): Bundle {
        // 优化点：只在首次调用时合并params，后续直接返回，避免重复遍历
        if (!paramsMerged) {
            params.forEach {
                // extras为运行期代码逻辑产生的动态参数，优先级最高，不允许被路由表静态参数覆盖
                // 优化：使用Kotlin的containsKey替代keySet().contains()
                if (!extras.containsKey(it.key)) {
                    extras.putString(it.key, it.value)
                }
            }
            paramsMerged = true  // 标记已合并完成
        }
        return extras
    }

    override fun toString(): String {
        return "RouteItem(path='$path', className='$className', action='$action', description='$description', extras=$extras)"
    }

    fun copy(): RouteItem {
        val item = RouteItem()
        item.extras.putAll(extras)
        item.params.putAll(params)
        item.description = description
        item.action = action
        item.className = className
        item.path = path
        return item
    }

    override fun describeContents(): Int {
        return 0
    }

    override fun writeToParcel(dest: Parcel, flags: Int) {
        dest.writeString(path)
        dest.writeString(className)
        dest.writeString(action)
        dest.writeString(description)
        dest.writeSerializable(params)
        dest.writeBundle(extras)
    }

    fun readFromParcel(source: Parcel) {
        path = source.readString()!!
        className = source.readString()!!
        action = source.readString()!!
        description = source.readString()!!
        val obj = source.readSerializable()
        params = if (obj is HashMap<*, *>) {
            obj as HashMap<String, String>
        } else {
            HashMap<String, String>()
        }
        extras = source.readBundle(this::class.java.classLoader) ?: Bundle()
    }

    /**
     * 将当前路由转换为导航器
     */
    fun toNavigator() = Navigator(getUrlWithParams(), null)

    /**
     * 获取当前路由的完整url记录
     */
    fun getUrlWithParams() = getUrlWithParams { k, v -> "$k=$v" }

    /**
     * 获取当前路由的完整url记录
     */
    fun getUrlWithParams(handle: NavigatorParamsFixHandle) = getUrlWithParams(handle::fix)

    /**
     * 获取当前路由的完整url记录
     * 优化说明：
     * 1. 预分配StringBuilder容量，避免频繁扩容
     *    原因：append操作可能触发数组扩容，影响性能
     *    目的：预估参数数量，一次性分配足够容量
     * 2. 使用StringBuilder的append替代字符串拼接
     *    目的：减少中间字符串对象创建
     */
    fun getUrlWithParams(handle: (String, String) -> String): String {
        // 优化点：预估容量，避免StringBuilder频繁扩容
        // 估算方式：path长度 + (每个参数约16字符) * 参数数量
        val estimatedSize = path.length + (extras.keySet().size * 16)
        val stringBuilder = StringBuilder(estimatedSize)
        stringBuilder.append(path)

        var isFirst = true
        val extras = getExtras()
        for (key in extras.keySet()) {
            if (isFirst) {
                stringBuilder.append("?")
                isFirst = false
            } else {
                stringBuilder.append("&")
            }
            stringBuilder.append(handle(key, extras.get(key)?.toString() ?: ""))
        }
        return stringBuilder.toString()
    }

    companion object CREATOR : Parcelable.Creator<RouteItem> {
        override fun createFromParcel(parcel: Parcel): RouteItem {
            return RouteItem(parcel)
        }

        override fun newArray(size: Int): Array<RouteItem?> {
            return arrayOfNulls(size)
        }
    }
}

fun getExtras(): Bundle {
    // 优化点：只在首次调用时合并params，后续直接返回，避免重复遍历
    if (!paramsMerged) {
        params.forEach {
            // extras为运行期代码逻辑产生的动态参数，优先级最高，不允许被路由表静态参数覆盖
            // 优化：使用Kotlin的containsKey替代keySet().contains()
            if (!extras.containsKey(it.key)) {
                extras.putString(it.key, it.value)
            }
        }
        paramsMerged = true  // 标记已合并完成
    }
    return extras
}

fun getUrlWithParams(handle: (String, String) -> String): String {
    // 优化点：预估容量，避免StringBuilder频繁扩容
    // 估算方式：path长度 + (每个参数约16字符) * 参数数量
    val estimatedSize = path.length + (extras.keySet().size * 16)
    val stringBuilder = StringBuilder(estimatedSize)
    stringBuilder.append(path)

    var isFirst = true
    val extras = getExtras()
    for (key in extras.keySet()) {
        if (isFirst) {
            stringBuilder.append("?")
            isFirst = false
        } else {
            stringBuilder.append("&")
        }
        stringBuilder.append(handle(key, extras.get(key)?.toString() ?: ""))
    }
    return stringBuilder.toString()
}

fun initRouteMap() {
    try {
        InputStreamReader(
            getStreamFromAssets(getApplicationContext(), ROUTE_MAP_ASSETS_PATH), Charset.forName("UTF-8")
        ).use {
            BufferedReader(it).use { read ->
                var lineText: String?
                // 优化点：预估初始容量，避免频繁扩容 (路由表文件通常小于10KB)
                val stringBuilder = StringBuilder(8192)
                while (read.readLine().also { lineText = it } != null) {
                    stringBuilder.append(lineText).append("\n")
                }
                val content = stringBuilder.toString()
                debug("RouteMap", "will be add route map from assets: $content")
                if (!TextUtils.isEmpty(content)) {
                    val list: List<RouteItem> =
                        gson.fromJson(content, object : TypeToken<List<RouteItem?>?>() {}.getType())
                    addRouteMap(list)
                }
            }
        }
    } catch (e: Exception) {
        debug("RouteMap", "initRouteMap InputStreamReader error") {
            e.printStackTrace()
        }
    }
}

fun setRouteMapInitTask(task: RouterMapInitTask?) = task?.let {
    initTask = task
}

fun setRouteMapInitTask(task: () -> Unit) {
    initTask = object : RouterMapInitTask {
        override fun asyncInitRouteMap() {
            task.invoke()
        }
    }
}

fun matchRouteMap(url: String?): RouteItem? {
    fun matchRoute(): RouteItem? {
        var path = TheRouter.build(url ?: "").simpleUrl
        // 优化点：使用 Kotlin 标准库的 removeSuffix，代码更简洁
        if (path.endsWith("/")) {
            path = path.removeSuffix("/")
        }
        // copy是为了防止外部修改影响路由表
        val routeItem = ROUTER_MAP[path]?.copy()
        // 由于路由表中的path可能是正则path，要用入参替换掉
        routeItem?.path = path
        return routeItem
    }

    if (Thread.currentThread() == Looper.getMainLooper().thread) {
        return matchRoute()
    } else {
        synchronized(ROUTER_MAP) {
            return matchRoute()
        }
    }
}

fun addRouteItem(routeItem: RouteItem) {
    fun addRoute() {
        var path = routeItem.path
        // 优化点：使用 Kotlin 标准库的 removeSuffix
        if (path.endsWith("/")) {
            path = path.removeSuffix("/")
        }
        debugOnly("addRouteItem", "add $path")
        ROUTER_MAP[path] = routeItem
        onRouteMapChangedListener?.onChanged(routeItem)
    }

    if (Thread.currentThread() == Looper.getMainLooper().thread) {
        return addRoute()
    } else {
        synchronized(ROUTER_MAP) {
            return addRoute()
        }
    }
}

