public String buildUnionQuery(String[] subQueries, String sortOrder, String limit) {
    StringBuilder query = new StringBuilder(128);
    int subQueryCount = subQueries.length;
    String unionOperator = mDistinct ? " UNION " : " UNION ALL ";

    for (int i = 0; i < subQueryCount; i++) {
        if (i > 0) {
            query.append(unionOperator);
        }
        query.append(subQueries[i]);
    }
    appendClause(query, " ORDER BY ", sortOrder);
    appendClause(query, " LIMIT ", limit);
    return query.toString();
}

public final class SQLiteStatement extends SQLiteProgram {
    SQLiteStatement(SQLiteDatabase db, String sql, Object[] bindArgs) {
        super(db, sql, bindArgs, null);
    }

    /**
     * Execute this SQL statement, if it is not a SELECT / INSERT / DELETE / UPDATE, for example
     * CREATE / DROP table, view, trigger, index etc.
     *
     * @throws android.database.SQLException If the SQL string is invalid for
     *         some reason
     */
    public void execute() {
        acquireReference();
        try {
            B_setBindArgs();
            getPreparedStatement().execute();
        } catch (SQLException e) {
            throw new SQLiteException("Failed to execute SQL statement!", e);
        } finally {
            releaseReference();
        }
    }

    /**
     * Execute this SQL statement, if the the number of rows affected by execution of this SQL
     * statement is of any importance to the caller - for example, UPDATE / DELETE SQL statements.
     *
     * @return the number of rows affected by this SQL statement execution.
     * @throws android.database.SQLException If the SQL string is invalid for
     *         some reason
     */
    public int executeUpdateDelete() {
        acquireReference();
        try {
            B_setBindArgs();
            getPreparedStatement().execute();
            return getPreparedStatement().getUpdateCount();
        } catch (SQLException e) {
            throw new SQLiteException("Failed to execute SQL statement!", e);
        } finally {
            releaseReference();
        }
    }

    /**
     * Execute this SQL statement and return the ID of the row inserted due to this call.
     * The SQL statement should be an INSERT for this to be a useful call.
     *
     * @return the row ID of the last row inserted, if this insert is successful. -1 otherwise.
     *
     * @throws android.database.SQLException If the SQL string is invalid for
     *         some reason
     */
    public long executeInsert() {
        acquireReference();
        try {
            B_setBindArgs();
            getPreparedStatement().executeUpdate();
            ResultSet generated = getPreparedStatement().getGeneratedKeys();
            if(generated.next())
                return generated.getLong(1);
            else
                return -1;
        } catch (SQLException e) {
            throw new SQLiteException("Failed to execute SQL statement!", e);
        } finally {
            releaseReference();
        }
    }

    /**
     * Execute a statement that returns a 1 by 1 table with a numeric value.
     * For example, SELECT COUNT(*) FROM table;
     *
     * @return The result of the query.
     *
     * @throws android.database.sqlite.SQLiteDoneException if the query returns zero rows
     */
    public long simpleQueryForLong() {
        acquireReference();
        try {
            B_setBindArgs();
            getPreparedStatement().execute();
            if(getResultSet().next())
                return getResultSet().getLong(1);
            else
                throw new SQLiteDoneException();
        } catch (SQLException e) {
            throw new SQLiteException("Failed to execute SQL statement!", e);
        } finally {
            releaseReference();
        }
    }

    /**
     * Execute a statement that returns a 1 by 1 table with a text value.
     * For example, SELECT COUNT(*) FROM table;
     *
     * @return The result of the query.
     *
     * @throws android.database.sqlite.SQLiteDoneException if the query returns zero rows
     */
    public String simpleQueryForString() {
        acquireReference();
        try {
            B_setBindArgs();
            getPreparedStatement().execute();
            if(getResultSet().next())
                return getResultSet().getString(1);
            else
                throw new SQLiteDoneException();
        } catch (SQLException e) {
            throw new SQLiteException("Failed to execute SQL statement!", e);
        } finally {
            releaseReference();
        }
    }

    /**
     * Executes a statement that returns a 1 by 1 table with a blob value.
     *
     * @return A read-only file descriptor for a copy of the blob value, or {@code null}
     *         if the value is null or could not be read for some reason.
     *
     * @throws android.database.sqlite.SQLiteDoneException if the query returns zero rows
     */
    public ParcelFileDescriptor simpleQueryForBlobFileDescriptor() {
        throw new UnsupportedOperationException("Not implemented!");
    }

    @Override
    public String toString() {
        return "SQLiteProgram: " + getSql();
    }
