public @Nullable Message peekLastMessageForTest() {
    synchronized (this) {
        Message lastMsg = null;

        Message current = mMessages;
        while (current != null) {
            if (current.target != null && (lastMsg == null || lastMsg.when <= current.when)) {
                lastMsg = current;
            }
            current = current.next;
        }

        return lastMsg;
    }
}

public void resetForTest() {
    synchronized (this) {
        // This queue is already quitting, so we can't reset its state and continue using it.
        if (mQuitting) {
            return;
        }
        mIdleHandlers.clear();
        removeAllFdRecords();
        removeAllMessagesLocked();
        // We reset the sync barrier tokens to reflect the queue's state reset. This helps
        // ensure that the queue's behavior is deterministic in both individual tests and in a
        // test suite.
        resetSyncBarrierTokens();
        ShadowPausedMessageQueue.nativeWake(mPtr);
    }
}

synchronized (this) {
    final int token = mNextBarrierToken++;
    final Message msg = Message.obtain();
    msg.markInUse();
    msg.when = when;
    msg.arg1 = token;

    if (mLast != null && mLast.when <= when) {
        /* Message goes to tail of list */
        mLast.next = msg;
        mLast = msg;
        msg.next = null;
        return token;
    }

    Message prev = null;
    Message p = mMessages;
    if (when != 0) {
        while (p != null && p.when <= when) {
            prev = p;
            p = p.next;
        }
    }

    if (p == null) {
        /* We reached the tail of the list, or list is empty. */
        mLast = msg;
    }

    if (prev != null) { // invariant: p == prev.next
        msg.next = p;
        prev.next = msg;
    } else {
        msg.next = p;
        mMessages = msg;
    }
    return token;
}

@TestApi
public void removeSyncBarrier(int token) {
    // Remove a sync barrier token from the queue.
    // If the queue is no longer stalled by a barrier then wake it.
    synchronized (this) {
        Message prev = null;
        Message p = mMessages;
        while (p != null && (p.target != null || p.arg1 != token)) {
            prev = p;
            p = p.next;
        }
        if (p == null) {
            throw new IllegalStateException("The specified message queue synchronization "
                    + " barrier token has not been posted or has already been removed.");
        }
        final boolean needWake;
        if (prev != null) {
            prev.next = p.next;
            if (prev.next == null) {
                mLast = prev;
            }
            needWake = false;
        } else {
            mMessages = p.next;
            if (mMessages == null) {
                mLast = null;
            }
            needWake = mMessages == null || mMessages.target != null;
        }
        p.recycleUnchecked();

        // If the loop is quitting then it is already awake.
        // We can assume mPtr != 0 when mQuitting is false.
        if (needWake && !mQuitting) {
            ShadowPausedMessageQueue.nativeWake(mPtr);
        }
    }
}

