/**
 * A bridge that can be used to communicate between native and web.
 */
@Immutable
open class WebViewJsBridge(
    val navigator: WebViewNavigator? = null,
    val jsBridgeName: String = "kmpJsBridge",
) {
    private val jsMessageDispatcher = JsMessageDispatcher()
    var webView: IWebView? = null

    fun register(handler: IJsMessageHandler) = jsMessageDispatcher.registerJSHandler(handler)

    fun unregister(handler: IJsMessageHandler) = jsMessageDispatcher.unregisterJSHandler(handler)

    fun clear() = jsMessageDispatcher.clear()

    fun dispatch(message: JsMessage) =
        jsMessageDispatcher.dispatch(
            message,
            navigator,
            fun(it: String) {
                onCallback(it, message.callbackId)
            },
        )

    private fun onCallback(
        data: String,
        callbackId: Int,
    ) = webView?.evaluateJavaScript("window.$jsBridgeName.onCallback($callbackId, '$data')")
}

