val cssPattern =
    """<link\s+[^>]*href\s*=\s*["']([^"']+\.css)["'][^>]*>"""
        .toRegex(RegexOption.IGNORE_CASE)
modifiedHtml =
    cssPattern.replace(modifiedHtml) { matchResult ->
        val cssFile = matchResult.groupValues[1]
        try {
            val resourcePath = "$basePathInJar$cssFile".removePrefix("/")
            val cssInputStream =
                this::class.java.classLoader.getResourceAsStream(resourcePath)
            if (cssInputStream != null) {
                val cssContent =
                    InputStreamReader(
                        cssInputStream,
                        StandardCharsets.UTF_8,
                    ).use { it.readText() }
                "<style>\n$cssContent\n</style>"
            } else {
                KLogger.e { "DesktopWebView: CSS resource not found for inlining: $resourcePath" }
                matchResult.value // Keep original if can't inline
            }
        } catch (e: Exception) {
            KLogger.e { "DesktopWebView: Could not inline CSS $cssFile: ${e.message}" }
            matchResult.value
        }
    }

val jsPattern =
    """<script\s+[^>]*src\s*=\s*["']([^"']+\.js)["'][^>]*></script>"""
        .toRegex(RegexOption.IGNORE_CASE)
modifiedHtml =
    jsPattern.replace(modifiedHtml) { matchResult ->
        val jsFile = matchResult.groupValues[1]
        try {
            val resourcePath = "$basePathInJar$jsFile".removePrefix("/")
            val jsInputStream =
                this::class.java.classLoader.getResourceAsStream(resourcePath)
            if (jsInputStream != null) {
                val jsContent =
                    InputStreamReader(
                        jsInputStream,
                        StandardCharsets.UTF_8,
                    ).use { it.readText() }
                "<script>\n$jsContent\n</script>"
            } else {
                KLogger.e { "DesktopWebView: JS resource not found for inlining: $resourcePath" }
                matchResult.value // Keep original if can't inline
            }
        } catch (e: Exception) {
            KLogger.e { "DesktopWebView: Could not inline JS $jsFile: ${e.message}" }
            matchResult.value
        }
    }

actual class WebViewFactoryParam(
    val state: WebViewState,
    val client: KCEFClient,
    val fileContent: String,
) {
    inline val webSettings get() = state.webSettings
    inline val rendering: CefRendering get() =
        if (webSettings.desktopWebSettings.offScreenRendering) {
            CefRendering.OFFSCREEN
        } else {
            CefRendering.DEFAULT
        }
    inline val transparent: Boolean get() = webSettings.desktopWebSettings.transparent
}

actual fun defaultWebViewFactory(param: WebViewFactoryParam): NativeWebView =
    when (val content = param.state.content) {
        is WebContent.Url ->
            param.client
                .also {
                    it.addRequestHandler(createModifiedRequestHandler(param.webSettings))
                }.createBrowser(
                    content.url,
                    param.rendering,
                    param.transparent,
                )
        is WebContent.Data ->
            param.client.createBrowser(
                KCEFBrowser.BLANK_URI,
                param.rendering,
                param.transparent,
            )
        is WebContent.File -> {
            param.client
                .also {
                    it.addRequestHandler(createModifiedRequestHandler(param.webSettings))
                }.createBrowser(
                    KCEFBrowser.BLANK_URI,
                    param.rendering,
                    param.transparent,
                )
        }
        else ->
            param.client
                .also {
                    it.addRequestHandler(createModifiedRequestHandler(param.webSettings))
                }.createBrowser(
                    KCEFBrowser.BLANK_URI,
                    param.rendering,
                    param.transparent,
                )
    }

@Composable
fun DesktopWebView(
    state: WebViewState,
    modifier: Modifier,
    navigator: WebViewNavigator,
    webViewJsBridge: WebViewJsBridge?,
    onCreated: (NativeWebView) -> Unit,
    onDispose: (NativeWebView) -> Unit,
    factory: (WebViewFactoryParam) -> NativeWebView,
) {
    val currentOnDispose by rememberUpdatedState(onDispose)
    val client =
        remember(state.webSettings.desktopWebSettings.disablePopupWindows) {
            KCEF.newClientOrNullBlocking()?.also {
                if (state.webSettings.desktopWebSettings.disablePopupWindows) {
                    it.addLifeSpanHandler(DisablePopupWindowsLifeSpanHandler())
                } else {
                    if (it.getLifeSpanHandler() is DisablePopupWindowsLifeSpanHandler) {
                        it.removeLifeSpanHandler()
                    }
                }
            }
        }

    val scope = rememberCoroutineScope()
    val browser: KCEFBrowser? =
        remember(client, state.webSettings, state.content) {
            client?.let { factory(WebViewFactoryParam(state, client, "")) }
        }

    val desktopWebView: DesktopWebView? =
        remember(browser, state.content) {
            browser?.let {
                DesktopWebView(browser, scope, webViewJsBridge)
            }
        }

    LaunchedEffect(desktopWebView) {
        desktopWebView?.let { webView ->
            state.webView = webView
            webViewJsBridge?.webView = webView
        }
    }

    browser?.let {
        if (runCatching { browser.windowlessFrameRate.get(100L, TimeUnit.MILLISECONDS) }.getOrNull() == null) {
            SwingPanel(
                factory = {
                    onCreated(browser)
                    browser.apply {
                        addDisplayHandler(state)
                        addLoadListener(state, navigator)
                        addRequestHandler(state, navigator)
                    }
                    browser.uiComponent
                },
                modifier = modifier,
            )
        } else {
            onCreated(browser)
            browser.apply {
                addDisplayHandler(state)
                addLoadListener(state, navigator)
                addRequestHandler(state, navigator)
            }
            browser.uiComponent.size = java.awt.Dimension(1280, 720)
        }
    }

    DisposableEffect(Unit) {
        onDispose {
            client?.dispose()
            browser?.let { currentOnDispose(it) }
        }
    }
}

object IOSCookieManager : CookieManager {
    private val cookieStore: WKHTTPCookieStore =
        WKWebsiteDataStore.defaultDataStore().httpCookieStore

    @OptIn(ExperimentalCoroutinesApi::class)
    override suspend fun getCookies(url: String): List<Cookie> =
        suspendCancellableCoroutine {
            val cookieList = mutableListOf<Cookie>()
            cookieStore.getAllCookies { cookies ->
                cookies?.forEach { cookie ->
                    if (cookie is NSHTTPCookie) {
                        KLogger.d {
                            "IOSCookieManager getCookies: name: ${cookie.name}, value: ${cookie.value} url: $url, domain: ${cookie.domain}"
                        }
                        if (url.contains(cookie.domain.removePrefix("."))) {
                            cookieList.add(
                                Cookie(
                                    name = cookie.name,
                                    value = cookie.value,
                                    domain = cookie.domain,
                                    path = cookie.path,
                                    expiresDate = cookie.expiresDate?.timeIntervalSince1970?.toLong(),
                                    isSessionOnly = cookie.isSessionOnly(),
                                    sameSite = null,
                                    isSecure = cookie.isSecure(),
                                    isHttpOnly = cookie.isHTTPOnly(),
                                    maxAge = null,
                                ),
                            )
                        }
                    }
                }
                it.resume(cookieList, {})
            }
        }

    @OptIn(ExperimentalCoroutinesApi::class)
    override suspend fun removeAllCookies() =
        suspendCancellableCoroutine {
            cookieStore.getAllCookies { cookies ->
                cookies?.forEach { cookie ->
                    cookieStore.deleteCookie(cookie as NSHTTPCookie) {}
                }
                KLogger.d(tag = "iOSCookieManager") { ("IOSCookieManager removeAllCookies: $cookies") }
                it.resume(Unit, {})
            }
        }

    @OptIn(ExperimentalCoroutinesApi::class)
    override suspend fun removeCookies(url: String) =
        suspendCancellableCoroutine {
            cookieStore.getAllCookies { cookies ->
                cookies
                    ?.filter { cookie ->
                        cookie is NSHTTPCookie && url.contains(cookie.domain)
                    }?.forEach { cookie ->
                        cookieStore.deleteCookie(cookie as NSHTTPCookie) {}
                    }
                it.resume(Unit, {})
            }
        }

    @OptIn(ExperimentalCoroutinesApi::class)
    override suspend fun setCookie(
        url: String,
        cookie: Cookie,
    ) = suspendCancellableCoroutine {
        val iCookie =
            NSHTTPCookie.cookieWithProperties(
                mapOf(
                    NSHTTPCookieName to cookie.name,
                    NSHTTPCookieValue to cookie.value,
                    NSHTTPCookieDomain to (cookie.domain ?: ""),
                    NSHTTPCookiePath to (cookie.path ?: "/"),
                    NSHTTPCookieExpires to (
                        cookie.expiresDate?.let {
                            NSDate.dateWithTimeIntervalSince1970(
                                it.toDouble(),
                            )
                        }
                    ),
                ).filterValues { it != null },
            )
        if (iCookie == null) {
            it.resumeWithException(Exception("Cookie properties are invalid."))
        }
        cookieStore.setCookie(
            iCookie!!,
            completionHandler = {
                it.resume(Unit, {})
                KLogger.d(tag = "iOSCookieManager") { ("IOSCookieManager setCookie: $cookie") }
            },
        )
    }
}

