internal fun createJsBridgeScript(
    jsBridgeName: String,
    isIife: Boolean = false,
): String {
    val bridgeObjectCode =
        """
        window.$jsBridgeName = {
            _callbacks: {},
            _callbackId: 0,

            postMessage: function(methodName, params, callbackId) {
                // Send as JSON string instead of object to ensure proper parsing
                var messageData = JSON.stringify({
                    type: '$jsBridgeName',
                    action: methodName,
                    params: params,
                    callbackId: callbackId || 0
                });
                parent.postMessage(messageData, '*');
            },

            onCallback: function(callbackId, message) {
                var callback = this._callbacks[callbackId];
                if (callback) {
                    callback(message);
                    delete this._callbacks[callbackId];
                }
            },

            call: function(action, params, callback) {
                var callbackId = 0;
                if (callback) {
                    callbackId = ++this._callbackId;
                    this._callbacks[callbackId] = callback;
                }
                this.postMessage(action, params, callbackId);
                return callbackId;
            },

            // Standard API as per documentation
            callNative: function(methodName, params, callback) {
                return this.call(methodName, params, callback);
            }
        };

        // Listen for callback messages from parent
        window.addEventListener('message', function(event) {
            try {
                var data = typeof event.data === 'string' ? JSON.parse(event.data) : event.data;
                if (data && data.type === '$jsBridgeName') {
                    window.$jsBridgeName.onCallback(data.callbackId, data.message);
                }
            } catch (e) {
                console.error('Error processing callback message:', e);
            }
        });
        """.trimIndent()

    return if (isIife) {
        """
        (function() {
            $bridgeObjectCode
        })();
        """.trimIndent()
    } else {
        bridgeObjectCode
    }
}

var messageData = JSON.stringify({
    type: '$jsBridgeName',
    action: methodName,
    params: params,
    callbackId: callbackId || 0
}

callNative: function(methodName, params, callback) {
    return this.call(methodName, params, callback);
}

window.addEventListener('message', function(event) {
    try {
        var data = typeof event.data === 'string' ? JSON.parse(event.data) : event.data;
        if (data && data.type === '$jsBridgeName') {
            window.$jsBridgeName.onCallback(data.callbackId, data.message);
        }
    } catch (e) {
        console.error('Error processing callback message:', e);
    }
}

fun injectJsBridgeToHtml(
    htmlContent: String,
    jsBridgeName: String,
): String {
    // Only inject if it has a proper bridge implementation
    // We look for specific bridge functions like callNative in the content
    if (htmlContent.contains("window.$jsBridgeName") &&
        htmlContent.contains("$jsBridgeName.callNative") &&
        htmlContent.contains("$jsBridgeName._callbacks")
    ) {
        return htmlContent
    }

    // Create bridge initialization script wrapped in script tags
    val bridgeScriptContent = createJsBridgeScript(jsBridgeName)
    val bridgeScript =
        """
        <script>
        // Initialize JS bridge
        $bridgeScriptContent
        </script>
        """.trimIndent()

    // Insert script before end of head tag
    if (htmlContent.contains("</head>")) {
        return htmlContent.replace("</head>", "$bridgeScript</head>")
    }

    // If no head tag, insert after opening body tag
    if (htmlContent.contains("<body>") || htmlContent.contains("<body ")) {
        val bodyPattern = "<body[^>]*>".toRegex()
        return bodyPattern.replace(htmlContent, "$0$bridgeScript")
    }

    // As a last resort, prepend to the content
    return "$bridgeScript$htmlContent"
}

class WasmJsWebViewState(
    initialUrl: String = "",
    initialContent: String = "",
) {
    /** Current URL to be loaded */
    var url: String by mutableStateOf(initialUrl)

    /** HTML content to be displayed */
    var content: String by mutableStateOf(initialContent)

    /** Last URL that was successfully loaded */
    var lastLoadedUrl: String? by mutableStateOf(null)

    /** Whether the WebView is currently loading content */
    var isLoading: Boolean by mutableStateOf(false)

    /** Title of the current page */
    var pageTitle: String? by mutableStateOf(null)

    /**
     * Convert WebViewState to HtmlContent
     * @return HtmlContent representation of the current state
     */
    internal fun getHtmlContent(): HtmlContent =
        if (content.isNotBlank()) {
            HtmlContent.Data(content)
        } else if (url.isNotBlank()) {
            HtmlContent.Url(url)
        } else {
            HtmlContent.NavigatorOnly
        }
}

internal fun getHtmlContent(): HtmlContent =
    if (content.isNotBlank()) {
        HtmlContent.Data(content)
    }

sealed class HtmlContent {
    /** URL-based content with optional HTTP headers */
    data class Url(
        val url: String,
        val additionalHttpHeaders: Map<String, String> = emptyMap(),
    ) : HtmlContent()

    /** HTML data content with optional parameters */
    data class Data(
        val data: String,
        val baseUrl: String? = null,
        val mimeType: String? = null,
        val encoding: String? = "utf-8",
        val historyUrl: String? = null,
    ) : HtmlContent()

    /** POST request content */
    data class Post(
        val url: String,
        val postData: ByteArray,
    ) : HtmlContent() {
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (other == null || this::class != other::class) return false

            other as Post

            if (url != other.url) return false
            if (!postData.contentEquals(other.postData)) return false

            return true
        }

        override fun hashCode(): Int {
            var result = url.hashCode()
            result = 31 * result + postData.contentHashCode()
            return result
        }
    }

    /** Navigation-only content (no rendering) */
    data object NavigatorOnly : HtmlContent()
}

data class Post(
    val url: String,
    val postData: ByteArray,
) : HtmlContent() {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || this::class != other::class) return false

        other as Post

        if (url != other.url) return false
        if (!postData.contentEquals(other.postData)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = url.hashCode()
        result = 31 * result + postData.contentHashCode()
        return result
    }
}

sealed class HtmlLoadingState {
    /** Initial state before any loading has started */
    data object Initializing : HtmlLoadingState()

    /** Content is currently being loaded */
    data object Loading : HtmlLoadingState()

    /** Loading has finished, with success or error flag */
    data class Finished(
        val isError: Boolean = false,
        val errorMessage: String? = null,
    ) : HtmlLoadingState()
}

class HtmlViewState {
    /** Native HTML element (iframe) */
    var htmlElement: Any? by mutableStateOf(null)
        internal set

    /** Content to be displayed */
    var content: HtmlContent by mutableStateOf(HtmlContent.NavigatorOnly)
        internal set

    /** Current loading state */
    var loadingState: HtmlLoadingState by mutableStateOf(HtmlLoadingState.Initializing)
        internal set

    /** Last URL that was successfully loaded */
    var lastLoadedUrl: String? by mutableStateOf(null)
        internal set

    /** Title of the current page */
    var pageTitle: String? by mutableStateOf(null)
        internal set

    /** Error that occurred during loading */
    var error: Throwable? by mutableStateOf(null)
        internal set
}

