fun getLocalDateTime(long: Long): LocalDateTime {
    return LocalDateTime.ofInstant(Instant.ofEpochMilli(long), ZoneId.systemDefault())
}

fun getDate(localDateTime: LocalDateTime, context: Context): String {
    return when (val localDate = localDateTime.toLocalDate()) {
        today -> formatLocalTime(localDateTime.toLocalTime())
        yesterday -> context.getString(R.string.msg_yesterday)
        else -> {
            if (Period.between(lastWeek, localDate).days <= 0) {
                formatLocalDate(localDate)
            } else {
                localDate.dayOfWeek.getDisplayName(TextStyle.FULL, Locale.getDefault())
            }
        }
    }
}

fun getTime(localDateTime: LocalDateTime, showDateAndHour: Boolean = false): String {
    return if (showDateAndHour) {
        formatLocalDateTime(localDateTime)
    } else {
        val formatter = DateTimeFormatter.ofLocalizedTime(FormatStyle.SHORT)
        localDateTime.toLocalTime().format(formatter).toString()
    }
}

fun getDateTime(localDateTime: LocalDateTime): String {
    return formatLocalDateTime(localDateTime)
}

fun wrapDrawables(drawables: Array<Drawable>) {
    for (drawable in drawables) {
        DrawableCompat.wrap(drawable)
    }
}

fun tintDrawables(drawables: Array<Drawable>, context: Context, resId: Int) {
    for (drawable in drawables) {
        DrawableCompat.setTint(drawable, ContextCompat.getColor(context, resId))
    }
}

fun compoundDrawables(textView: Array<TextView>, drawables: Array<Drawable>) {
    if (textView.size != drawables.size) {
        return
    } else {
        for (i in textView.indices) {
            if (textView[i].resources.configuration.layoutDirection == View.LAYOUT_DIRECTION_RTL) {
                textView[i].setCompoundDrawablesWithIntrinsicBounds(null, null, drawables[i], null)
            } else {
                textView[i].setCompoundDrawablesWithIntrinsicBounds(drawables[i], null, null, null)
            }
        }
    }
}

fun compoundStartDrawable(textView: TextView, drawable: Drawable) =
    if (textView.resources.configuration.layoutDirection == View.LAYOUT_DIRECTION_RTL) {
        textView.setCompoundDrawablesWithIntrinsicBounds(null, null, drawable, null)
    }

fun compoundEndDrawable(textView: TextView, drawable: Drawable) =
    if (textView.resources.configuration.layoutDirection == View.LAYOUT_DIRECTION_RTL) {
        textView.setCompoundDrawablesWithIntrinsicBounds(drawable, null, null, null)
    }

fun compoundStartAndEndDrawable(
    textView: TextView,
    startDrawable: Drawable,
    endDrawable: Drawable
) =
    if (textView.resources.configuration.layoutDirection == View.LAYOUT_DIRECTION_RTL) {
        textView.setCompoundDrawablesWithIntrinsicBounds(endDrawable, null, startDrawable, null)
    }

fun getUserStatusDrawable(userStatus: UserStatus?, context: Context): Drawable {
    return when (userStatus) {
        is UserStatus.Online -> getDrawableFromId(R.drawable.ic_status_online_12dp, context)
        is UserStatus.Away -> getDrawableFromId(R.drawable.ic_status_away_12dp, context)
        is UserStatus.Busy -> getDrawableFromId(R.drawable.ic_status_busy_12dp, context)
        else -> getDrawableFromId(R.drawable.ic_status_invisible_12dp, context)
    }
}

fun loadEmojis() {
    EmojiRepository.init(this)
    runBlocking {
        getCurrentServerInteractor.get()?.let { server ->
            EmojiRepository.setCurrentServerUrl(server)
            val customEmojis = retryIO("getCustomEmojis()") {
                factory.get(server).getCustomEmojis().update
            }
            val customEmojiList = mutableListOf<Emoji>()
            try {
                if (customEmojis != null) {
                    for (customEmoji in customEmojis) {
                        customEmojiList.add(
                            Emoji(
                                shortname = ":${customEmoji.name}:",
                                category = EmojiCategory.CUSTOM.name,
                                url = "$server/emoji-custom/${customEmoji.name}.${customEmoji.extension}",
                                count = 0,
                                fitzpatrick = Fitzpatrick.Default.type,
                                keywords = customEmoji.aliases,
                                shortnameAlternates = customEmoji.aliases,
                                siblings = mutableListOf(),
                                unicode = "",
                                isDefault = true
                            )
                        )
                    }
                }
                EmojiRepository.load(this@RocketChatApplication, customEmojis = customEmojiList)
            } catch (ex: RocketChatException) {
                Timber.e(ex)
                EmojiRepository.load(this@RocketChatApplication as Context)
            }
        }
    }
}

