internal fun addToRecents(emoji: Emoji) {
    val emojiShortname = emoji.shortname
    val recentsJson = JSONObject(preferences.getString(PREF_EMOJI_RECENTS, "{}"))

    if (recentsJson.has(emojiShortname)) {
        val useCount = recentsJson.getInt(emojiShortname)
        recentsJson.put(emojiShortname, useCount + 1)
    } else {
        recentsJson.put(emojiShortname, 1)
    }

    preferences.edit().putString(PREF_EMOJI_RECENTS, recentsJson.toString()).apply()
}

internal suspend fun getRecents(): List<Emoji> = withContext(Dispatchers.IO) {
    val list = mutableListOf<Emoji>()
    val recentsJson = JSONObject(preferences.getString(PREF_EMOJI_RECENTS, "{}"))

    val allEmojis = db.emojiDao().loadAllEmojis()
    val len = recentsJson.length()
    val recentShortnames = recentsJson.keys()
    for (i in 0 until len) {
        val shortname = recentShortnames.next()
        allEmojis.firstOrNull {
            if (it.shortname == shortname) {
                if (it.isCustom()) {
                    return@firstOrNull getCurrentServerUrl()?.let { url ->
                        it.url?.startsWith(url)
                    } ?: false
                }
                return@firstOrNull true
            }
            false
        }?.let {
            val useCount = recentsJson.getInt(it.shortname)
            list.add(it.copy(count = useCount))
        }
    }

    list.sortWith(Comparator { o1, o2 ->
        o2.count - o1.count
    })

    return@withContext list
}

fun shortnameToUnicode(input: CharSequence): String {
    val matcher = SHORTNAME_PATTERN.matcher(input)
    var result: String = input.toString()

    while (matcher.find()) {
        val unicode = shortNameToUnicode.get(":${matcher.group(1)}:") ?: continue

        result = result.replace(":" + matcher.group(1) + ":", unicode)
    }

    return result
}

sealed class Fitzpatrick(val type: String) {

    object Default: Fitzpatrick("")
    object LightTone: Fitzpatrick("tone1")
    object MediumLightTone: Fitzpatrick("tone2")
    object MediumTone: Fitzpatrick("tone3")
    object MediumDarkTone: Fitzpatrick("tone4")
    object DarkTone: Fitzpatrick("tone5")

    companion object {
        fun valueOf(type: String): Fitzpatrick {
            return when(type) {
                "" -> Default
                "tone1" -> LightTone
                "tone2" -> MediumLightTone
                "tone3" -> MediumTone
                "tone4" -> MediumDarkTone
                "tone5" -> DarkTone
                else -> throw IllegalArgumentException("Fitzpatrick type '$type' is invalid")
            }
        }
    }
}

abstract class OverKeyboardPopupWindow(
    val context: Context,
    private val rootView: View
) : PopupWindow(context), ViewTreeObserver.OnGlobalLayoutListener {

    /**
     * @return keyboard height in pixels
     */
    var keyboardHeight = 0
        private set
    private var pendingOpen = false
    /**
     * @return Returns true if the soft keyboard is open, false otherwise.
     */
    var isKeyboardOpen = false
        private set

    private var keyboardHideListener: OnKeyboardHideListener? = null

    interface OnKeyboardHideListener {
        fun onKeyboardHide()
    }

    init {
        setBackgroundDrawable(null)
        val view = onCreateView(LayoutInflater.from(context))
        onViewCreated(view)
        contentView = view
        softInputMode = WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE

        // Default size
        setSize(this.context.resources.getDimensionPixelSize(R.dimen.supposed_keyboard_height),
                WindowManager.LayoutParams.MATCH_PARENT)
        setSizeForSoftKeyboard()
    }

    fun setKeyboardHideListener(keyboardHideListener: OnKeyboardHideListener) {
        this.keyboardHideListener = keyboardHideListener
    }

    /**
     * Manually set the popup window size
     *
     * @param width  Width of the popup
     * @param height Height of the popup
     */
    fun setSize(width: Int, height: Int) {
        setWidth(width)
        setHeight(height)
    }

    /**
     * Call this function to resize the emoji popup according to your soft keyboard size
     */
    private fun setSizeForSoftKeyboard() {
        val viewTreeObserver = rootView.viewTreeObserver
        viewTreeObserver.addOnGlobalLayoutListener(this)
    }

    override fun onGlobalLayout() {
        val r = Rect()
        rootView.getWindowVisibleDisplayFrame(r)

        val screenHeight = calculateScreenHeight()
        var heightDifference = screenHeight - (r.bottom - r.top)

        val resources = context.resources
        val resourceId = resources.getIdentifier("status_bar_height", "dimen", "android")
        if (resourceId > 0) {
            heightDifference -= resources.getDimensionPixelSize(resourceId)
        }

        if (heightDifference > 100) {
            keyboardHeight = heightDifference
            setSize(WindowManager.LayoutParams.MATCH_PARENT, keyboardHeight)

            isKeyboardOpen = true
            if (pendingOpen) {
                showAtBottom()
                pendingOpen = false
            }
        } else {
            if (isKeyboardOpen && keyboardHideListener != null) {
                keyboardHideListener!!.onKeyboardHide()
            }
            isKeyboardOpen = false
        }
    }

    private fun calculateScreenHeight(): Int {
        val wm = context.getSystemService(Context.WINDOW_SERVICE) as WindowManager
        val display = wm.defaultDisplay
        val size = Point()
        display.getSize(size)
        return size.y
    }

    /**
     * Use this function to show the popup.
     * NOTE: Since, the soft keyboard sizes are variable on different android devices, the
     * library needs you to open the soft keyboard at least once before calling this function.
     * If that is not possible see showAtBottomPending() function.
     */
    fun showAtBottom() {
        showAtLocation(rootView, Gravity.BOTTOM, 0, 0)
    }

    /**
     * Use this function when the soft keyboard has not been opened yet. This
     * will show the popup after the keyboard is up next time.
     * Generally, you will be calling InputMethodManager.showSoftInput function after
     * calling this function.
     */
    fun showAtBottomPending() {
        if (isKeyboardOpen) {
            showAtBottom()
        } else {
            pendingOpen = true
        }
    }

    abstract fun onCreateView(inflater: LayoutInflater): View

    abstract fun onViewCreated(view: View)
}

fun setSize(width: Int, height: Int) {
    setWidth(width)
    setHeight(height)
}

private fun setSizeForSoftKeyboard() {
    val viewTreeObserver = rootView.viewTreeObserver
