class AuthRepositoryImpl : AuthRepository {
    override suspend fun createUser(userName: String, password: String) = transaction {
        UserEntity.new {
            this.username = userName
            this.password = password
        }.let { User.fromEntity(it) }
    }

    override suspend fun isUsernameAvailable(userName: String): Boolean {
        return transaction {
            UserEntity.find { UserTable.userName eq userName }.firstOrNull()
        } == null
    }

    override suspend fun verifyPasswordForUsername(userName: String, password: String): Boolean {
        return transaction {
            UserEntity.find { (UserTable.userName eq userName) and (UserTable.password eq password) }.firstOrNull()
        } != null
    }

    override suspend fun findUserByUsername(userName: String): User? {
        return transaction {
            UserEntity.find { UserTable.userName eq userName }.firstOrNull()?.let {
                User.fromEntity(it)
            }
        }
    }

    override suspend fun verifyUsernameBelongsToUserId(userName: String, userId: UUID): Boolean {
        return transaction {
            UserEntity.find { (UserTable.userName eq userName) and (UserTable.id eq userId) }.firstOrNull()
        } != null
    }

    override fun findByUUID(uuid: UUID): User? = transaction {
        UserEntity.findById(uuid)
    }?.let { User.fromEntity(it) }
}

class TaskRepositoryImpl : TaskRepository {
    override suspend fun getAllTask(userId: String, category: String): List<Task> = transaction {
        val tasks = if (category.trim().isBlank()) {
            TaskTable.user eq UUID.fromString(userId)
        } else {
            (TaskTable.user eq UUID.fromString(userId)) and (TaskTable.category eq category)
        }

        TaskEntity.find { tasks }
            .sortedByDescending { it.id }
            .map { it.toDomain() }
    }

    override suspend fun createTask(userId: String, task: CreateTaskRequest): String = transaction {
        TaskEntity.new {
            this.user = UserEntity[UUID.fromString(userId)]
            this.title = task.title
            this.description = task.description
            this.category = task.category
            this.emoji = task.emoji
            this.urgency = task.urgency
            this.importance = task.importance
            this.priority = task.priority
            this.due = task.due
            this.isCompleted = task.isCompleted
        }.id.value.toString()
    }

    override suspend fun updateTask(taskId: String, task: CreateTaskRequest): String = transaction {
        TaskEntity[UUID.fromString(taskId)].apply {
            this.title = task.title
            this.description = task.description
            this.category = task.category
            this.emoji = task.emoji
            this.urgency = task.urgency
            this.importance = task.importance
            this.priority = task.priority
            this.due = task.due
            this.isCompleted = task.isCompleted
        }.id.value.toString()
    }

    override suspend fun deleteTask(taskId: String): Boolean = transaction {
        TaskEntity.findById(UUID.fromString(taskId))?.run {
            delete()
            return@transaction true
        }
        return@transaction false
    }

    override suspend fun verifyTaskExistence(taskId: String): Boolean = transaction {
        TaskEntity.findById(UUID.fromString(id)) == null
    }

    override suspend fun verifyTaskIsOfUser(userId: String, taskId: String): Boolean = transaction {
        TaskEntity.find {
            (TaskTable.user eq UUID.fromString(userId)) and (TaskTable.id eq UUID.fromString(taskId))
        }.firstOrNull() != null
    }
}

fun initializeDatabase(databaseConfig: DatabaseConfig) {
    val tables = arrayOf(UserTable, TaskTable)

    Database.connect(
        url = databaseConfig.url,
        driver = "org.postgresql.Driver",
        user = databaseConfig.user,
        password = databaseConfig.password
    )

    transaction {
        SchemaUtils.createMissingTablesAndColumns(*tables)
    }
}

class AuthService(
    private val authRepository: AuthRepository,
    private val jwtDomain: String,
    private val jwtAudience: String,
    private val jwtSecret: String
) {

    private val encryptorService = EncryptorService(jwtSecret)

    suspend fun String.getUser() = authRepository.findUserByUsername(this)

    suspend fun validateCredentialsForRegistration(userName: String, password: String): ServiceResult {
        return when {
            (userName.isBlank() || password.isBlank()) -> ServiceResult.Error("Required fields cannot be blank")
            (userName.trim().length !in (4..10)) -> ServiceResult.Error("Username length should be between 4 to 10 characters")
            (password.trim().length !in (4..20)) -> ServiceResult.Error("Password length should be between 4 to 20 characters")
            userName.containsOnlyNumbers() -> ServiceResult.Error("Username should not only consists of numbers")
            userName.containsSpecialCharacters() -> ServiceResult.Error("Special characters are not allowed inside username")
            !authRepository.isUsernameAvailable(userName) -> ServiceResult.Error("The username $userName is not available")
            else -> registerNewUser(userName, encryptorService.encryptPassword(password))
        }
    }

    suspend fun validateCredentialsForLogin(userName: String, password: String): ServiceResult {
        return when {
            (userName.isBlank() || password.isBlank()) -> ServiceResult.Error("Required fields cannot be blank")
            authRepository.isUsernameAvailable(userName) -> ServiceResult.Error("Invalid Credentials")
            !authRepository.verifyPasswordForUsername(
                userName,
                encryptorService.encryptPassword(password)
            ) -> ServiceResult.Error("Invalid Credentials")
            else -> loginUserAndGenerateToken(userName)
        }
    }

    private suspend fun registerNewUser(userName: String, password: String): ServiceResult {
        authRepository.createUser(userName, password).run {
            return ServiceResult.Success("Account created successfully.")
        }
    }

    private suspend fun loginUserAndGenerateToken(userName: String): ServiceResult {
        authRepository.findUserByUsername(userName)?.run {
            val expiresIn = 4102504735000L
            val token = JWT.create()
                .withClaim("userId", id)
                .withIssuer(jwtDomain)
                .withExpiresAt(Date(System.currentTimeMillis() + expiresIn))
                .withAudience(jwtAudience)
                .sign(Algorithm.HMAC256(jwtSecret))
            return ServiceResult.Success(token)
        }
        return ServiceResult.Error("Failed to log in, please try again later.")
    }
}

class EncryptorService(
    secretKey: String
) {

    private val hMacKey = SecretKeySpec(secretKey.toByteArray(), ALGORITHM)

    fun encryptPassword(password: String) = Mac.getInstance(ALGORITHM).run {
        init(hMacKey)
        hex(doFinal(password.toByteArray(Charsets.UTF_8)))
    }
}

class TaskService(
    private val taskRepository: TaskRepository
) {

    suspend fun getAllTasksOfUser(userId: String, category: String) = taskRepository.getAllTask(userId, category)

    suspend fun validateAndCreateTask(userId: String, request: CreateTaskRequest): ServiceResult {
        return when {
            (request.title.isBlank() || request.description.isBlank() || request.category.isBlank()) -> {
                ServiceResult.Error("Required fields cannot be blank")
            }
            (request.title.trim().length < 4 || request.description.trim().length < 4 || request.category.trim().length < 4) -> {
                ServiceResult.Error("Required fields length should be at least of 4 characters")
            }
            else -> createTask(userId, request)
        }
    }

    private suspend fun createTask(userId: String, task: CreateTaskRequest): ServiceResult {
        taskRepository.createTask(userId, task).run {
            return ServiceResult.Success(this)
        }
    }

    suspend fun validateAndUpdateTask(userId: String, taskId: String, request: CreateTaskRequest): ServiceResult {
        return when {
            !taskRepository.verifyTaskExistence(taskId) -> ServiceResult.Error("Task with $taskId doesn't exists")
            !taskRepository.verifyTaskIsOfUser(userId, taskId) -> ServiceResult.Error("This is none of your task")
            (request.title.isBlank() || request.description.isBlank() || request.category.isBlank()) -> {
                ServiceResult.Error("Required fields cannot be blank")
            }
            (request.title.trim().length < 4 || request.description.trim().length < 4 || request.category.trim().length < 4) -> {
                ServiceResult.Error("Required fields length should be at least of 4 characters")
            }
            else -> updateTask(taskId, request)
        }
    }

    private suspend fun updateTask(taskId: String, task: CreateTaskRequest): ServiceResult {
        taskRepository.updateTask(taskId, task).run {
            return ServiceResult.Success(this)
        }
    }

    suspend fun verifyAndDeleteTask(userId: String, taskId: String): ServiceResult {
        return when {
            !taskRepository.verifyTaskExistence(taskId) -> ServiceResult.Error("Task with $taskId doesn't exists")
            !taskRepository.verifyTaskIsOfUser(userId, taskId) -> ServiceResult.Error("This is none of your task")
            else -> deleteTask(taskId)
        }
    }

    private suspend fun deleteTask(taskId: String): ServiceResult {
        taskRepository.deleteTask(taskId).run {
            return if (this) ServiceResult.Success("Success") else
                ServiceResult.Error("Error deleting task with $taskId id. Please try again later")
        }
    }
}

