                            errorState = true
                            errorMessage = "$title should not be empty"
                        }
                        false -> {
                            errorState = false
                            errorMessage = ""
                        }
                    }
                }
            ),
            isError = errorState
        )

        if (errorState) {
            Text(
                errorMessage,
                style = AppTheme.typography.caption,
                color = AppTheme.colors.error,
                modifier = modifier.padding(
                    top = AppTheme.dimensions.paddingLarge,
                    start = AppTheme.dimensions.paddingXL,
