class BigImageResAnalyzerTask : AnalyzerTask {

    data class OverLimitImageInfo(val name:String, val size:String = "")

    companion object {
        val NAME = "BigImageRes"
    }

    private val checkedImageTypes = arrayOf("png", "jpeg", "jpg", "webp")

    override fun analyze(unZipContext: UnZipApkFileInfo): String {

        val limitImageSize = ApkAnalyzer.globalConfig.maxImageSizeKB

        val overLimitImages =
            unZipContext.fileMap.filter { checkedImageTypes.contains(it.key) }.flatMap { it.value }
                .filter { (it.size / 1024) > limitImageSize }
                .map { OverLimitImageInfo(Utils.getFileRelativeName(unZipContext.unZipDir,it.path), Utils.formatFileSize(it.size)) }

        return Gson().toJson(overLimitImages)
    }

    override fun getResultName() = NAME

}

class DuplicatedFileAnalyzerTask : AnalyzerTask {

    data class SameMd5Files(val files: ArrayList<String> = ArrayList(), val fileSize: String, var md5Value:String)

    override fun getResultName() = "DuplicatedFile"

    override fun analyze(unZipContext: UnZipApkFileInfo): String {

        val md5Map = HashMap<String, SameMd5Files>()

        unZipContext.fileMap.flatMap { it.value }.forEach {
            val md5Value = getMD5(File(it.path))

            var md5FileInfo = md5Map[md5Value]
            if (md5FileInfo == null) {
                md5FileInfo = SameMd5Files(fileSize = Utils.formatFileSize(it.size), md5Value = md5Value)
                md5Map[md5Value] = md5FileInfo
            }

            md5FileInfo.files.add(Utils.getFileRelativeName(unZipContext.unZipDir, it.path))
        }

        return Gson().toJson(md5Map.filter { it.value.files.size > 1 }.map { it.value })
    }

    private fun getMD5(file: File): String {
        val msgDigest = MessageDigest.getInstance("MD5")
        return Util.byteArrayToHex(msgDigest.digest(file.readBytes()))
    }

}

class MethodCountAnalyzerTask : AnalyzerTask {

    private val OTHER = "other-pkg"

    override fun getResultName() = "MethodCount"

    override fun analyze(unZipContext: UnZipApkFileInfo): String {
        //统计分组
        val methodGroup = HashMap<String, Int>()
        ApkAnalyzer.globalConfig.methodGroup.forEach {
            methodGroup[it.packageName] = 0
        }
        methodGroup[OTHER] = 0

        //统计所有方法数量
        unZipContext.fileMap.filter { it.key.contains("dex") }.flatMap { it.value }.forEach {
            countDex(RandomAccessFile(it.path, "rw"), methodGroup, unZipContext.proguardClassMap)
        }

        var totalCount = 0
        methodGroup.forEach { (_, count) ->
            totalCount += count
        }

        methodGroup["total-count"] = totalCount

        return Gson().toJson(methodGroup)
    }

    @Throws(IOException::class)
    private fun countDex(
        dexFile: RandomAccessFile,
        methodGroup: HashMap<String, Int>,
        proguardClassMap: Map<String, String>
    ) {
        val dexData = DexData(dexFile)
        dexData.load()
        val methodRefs = dexData.methodRefs
        for (methodRef in methodRefs) {

            var className = getNormalClassName(methodRef.declClassName)

            if (proguardClassMap.containsKey(className)) {
                className = proguardClassMap[className] ?:""
            }

            if (!Util.isNullOrNil(className)) {
                if (className.indexOf('.') == -1) {
                    continue
                }

                var hasSetting = false
                for (entry in methodGroup.entries) {
                    if (className.startsWith(entry.key)) {
                        methodGroup[entry.key] = entry.value + 1
                        hasSetting = true
                        continue
                    }
                }

                if (!hasSetting) {
                    methodGroup[OTHER] = methodGroup[OTHER]!! + 1
                }

            }
        }
    }

    /*
     *  parse the descriptor of class to normal dot-split class name (XXX.XXX.XXX)
     */
    private fun getNormalClassName(name: String): String {
        if (!Util.isNullOrNil(name)) {
            var className = Output.descriptorToDot(name)
            if (className.endsWith("[]")) {                                                //enum or array
                className = className.substring(0, className.indexOf("[]"))
            }
            return className
        }
        return ""
    }
}

