private static String descriptorFromProtoArray(String[] protos,
        String returnType) {
    StringBuilder builder = new StringBuilder();

    builder.append("(");
    for (int i = 0; i < protos.length; i++) {
        builder.append(protos[i]);
    }

    builder.append(")");
    builder.append(returnType);

    return builder.toString();
}

