class RabbitSimpleCardDecoration(
    val horizontalGap: Int = CARD_GAP,
    val verticalGap: Int = CARD_GAP
) : RecyclerView.ItemDecoration() {

    companion object {
        val CARD_GAP = dp2px(10f)
    }

    override fun getItemOffsets(
        outRect: Rect,
        view: View,
        parent: RecyclerView,
        state: RecyclerView.State
    ) {
        super.getItemOffsets(outRect, view, parent, state)
        val params = view.layoutParams as GridLayoutManager.LayoutParams
        outRect.top = verticalGap
        if (params.spanIndex == 0) {
            outRect.left = horizontalGap
            outRect.right = horizontalGap / 2
        } else {
            outRect.right = horizontalGap
            outRect.left = horizontalGap / 2
        }
    }
}

class RabbitSimpleDividerLine : RecyclerView.ItemDecoration {

    lateinit var mDividerPaint: Paint
    private var mDividerHeight: Int = 0
    private var mMargin: Rect
    private var mStartPos = UNDEFINE_POS
    private var endLastCount = 1

    constructor(context: Context, @ColorRes colorId: Int, dividerHeight: Int) {
        init(context, colorId, dividerHeight)
        mMargin = Rect(0, 0, 0, 0)
        mStartPos = 0
    }

    constructor(
        context: Context, @ColorRes colorId: Int,
        dividerHeight: Int,
        margin: Rect = Rect(0, 0, 0, 0)
    ) {
        init(context, colorId, dividerHeight)
        mMargin = margin
        mStartPos = 0
    }

    constructor(
        context: Context, @ColorRes colorId: Int,
        dividerHeight: Int,
        margin: Rect = Rect(0, 0, 0, 0),
        endLastCount: Int
    ) {
        init(context, colorId, dividerHeight)
        mMargin = margin
        mStartPos = 0
        this.endLastCount = endLastCount
    }

    constructor(
        context: Context,
        startPos: Int = 0, @ColorRes colorId: Int,
        dividerHeight: Int,
        margin: Rect = Rect(0, 0, 0, 0)
    ) {
        init(context, colorId, dividerHeight)
        mMargin = margin
        mStartPos = startPos
    }

    private fun init(context: Context, colorResId: Int, dividerHeight: Int) {
        mDividerPaint = Paint()
        mDividerPaint.color = getColor(context, colorResId)
        mDividerHeight = dividerHeight
    }

    override fun getItemOffsets(
        outRect: Rect,
        view: View,
        parent: RecyclerView,
        state: RecyclerView.State
    ) {
        super.getItemOffsets(outRect, view, parent, state)
        outRect.bottom = mDividerHeight
    }

    override fun onDraw(c: Canvas, parent: RecyclerView, state: RecyclerView.State) {
        val childCount = parent.childCount

        val left: Int = if (mMargin.left > 0) {
            parent.paddingLeft + mMargin.left
        } else {
            parent.paddingLeft
        }

        val right: Int = if (mMargin.right > 0) {
            parent.width - parent.paddingRight - mMargin.right
        } else {
            parent.width - parent.paddingRight
        }

        var startPos = 0
        if (mStartPos != UNDEFINE_POS && mStartPos < childCount - 1 && mStartPos >= 0) {
            startPos = mStartPos
        }

        for (i in startPos until childCount - endLastCount) {
            val view = parent.getChildAt(i)
            val top = view.bottom.toFloat()
            val bottom = (view.bottom + mDividerHeight).toFloat()
            c.drawRect(left.toFloat(), top, right.toFloat(), bottom, mDividerPaint)
        }
    }

    companion object {
        val UNDEFINE_POS = -1
    }
}

object RabbitUiUtils {

    private val sMetrics = Resources.getSystem().displayMetrics

    fun getScreenHeight(): Int {
        return sMetrics?.heightPixels ?: 0
    }

    fun getScreenWidth(): Int {
        return sMetrics?.widthPixels ?: 0
    }

    /**
     * get the color by id
     */
    fun getColor(context: Context?, resId: Int): Int {
        return if (null == context || context.resources == null || resId <= -1) {
            Color.TRANSPARENT
        } else ContextCompat.getColor(context, resId)
    }

    /*
    * 一种比较通用的 Status Bar Color , for Android 6.0 +
    * 魅族，小米 有特有的API。这里没做适配
    * */
    fun setGeneralStatusBarColor(window: Window) {
        setStatusBarColor(window, Color.WHITE)
        setStatusBarTextColor(window, true)
    }

    private fun setStatusBarColor(window: Window, @ColorInt color: Int) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            window.statusBarColor = color
            window.decorView.systemUiVisibility = View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR
        }
    }


    fun setStatusBarTextColor(window: Window, lightStatusBar: Boolean) {
        // 设置状态栏字体颜色 白色与深色
        val decor = window.decorView
        var ui = decor.systemUiVisibility
        ui = ui or View.SYSTEM_UI_FLAG_LAYOUT_STABLE
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            ui = if (lightStatusBar) {
                ui or View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR
            } else {
                ui and View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR.inv()
            }
        }
        decor.systemUiVisibility = ui
    }

    fun copyStrToClipBoard(context: Context, str: String) {
        val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        val clipData = ClipData.newPlainText(null, str)
        clipboard.primaryClip = clipData
    }

    fun formatFileSize(size: Long): String {
        if (size <= 0) return ""
        val formater = Formatter()
        return when {
            size < 1024 -> size.toString() + "B"
            size < 1024 * 1024 -> {
                formater.format("%.2f KB", size / 1024f).toString()
            }
            size < 1024 * 1024 * 1024 -> {
                formater.format("%.2f MB", size / 1024f / 1024f).toString()
            }
            else -> {
                formater.format("%.2f GB", size / 1024f / 1024f / 1024f).toString()
            }
        }
    }

    fun dropPackageName(str: String): String {
        val strSlice = str.split(".")
        if (strSlice.size < 3) return str
        return "${strSlice[strSlice.size - 2]}.${strSlice[strSlice.size - 1]}"
    }

    fun formatTimeDuration(durations: Long): String {
        if (durations < 60){
            return "$durations 秒"
        }

        val min = durations / 60
        val sec = durations % 60

        return "${min}分${sec}秒"
    }

}

