class RabbitPlugin : Plugin<Project> {

    override fun apply(project: Project) {

        //load custom config
        val config = project.extensions.create("rabbitConfig", RabbitConfigExtension::class.java)

        project.afterEvaluate {
            //如果配置的检测包的范围，则自动打开对应开关
            config.enableBlockCodeCheck = config.customBlockCodeCheckList.isNotEmpty()
            config.enableMethodCostCheck = config.methodMonitorPkgs.isNotEmpty()

            GlobalConfig.pluginConfig = config
            GlobalConfig.ioMethodCall.clear()
        }

        //register transform
        project.getAndroid<AppExtension>().apply {
            registerTransform(RabbitFirstTransform())
            registerTransform(RabbitLastTransform())
        }
    }

}

class AsmByteArrayTransformer(private val transformers: List<RabbitAsmByteArrayTransformer> = ArrayList()) :
    RabbitClassByteCodeTransformer {

    override fun transform(
        context: TransformContext,
        bytecode: ByteArray,
        classFilePath: String
    ): ByteArray {
        return transformers.fold(bytecode) { classNode, transformer ->
            transformer.transform(context, classNode, classFilePath)
        }
    }

    override fun onPreTransform(context: TransformContext) {
        transformers.forEach {
            it.onPreTransform(context)
        }
    }

    override fun onPostTransform(context: TransformContext) {
        transformers.forEach {
            it.onPostTransform(context)
        }
    }

}

class AsmClassVisitorTransformer(private val transformers:List<RabbitAsmClassVisitorTransformer> = ArrayList()) : RabbitClassByteCodeTransformer {

    override fun transform(context: TransformContext, bytecode: ByteArray, classFilePath:String): ByteArray {
        return ClassWriter(ClassWriter.COMPUTE_MAXS).also { writer ->
            transformers.fold(ClassNode().also { visitClassNode ->
                ClassReader(bytecode).accept(visitClassNode, 0)
            }) { classNode, transformer ->
                transformer.transform(context, classNode,classFilePath)
            }.accept(writer)
        }.toByteArray()
    }

    override fun onPreTransform(context: TransformContext) {
        transformers.forEach {
            it.onPreTransform(context)
        }
    }

    override fun onPostTransform(context: TransformContext) {
        transformers.forEach {
            it.onPostTransform(context)
        }
    }

}

interface RabbitAsmByteArrayTransformer : TransformListener {

    /**
     * Transform the specified class node
     *
     * @param context The transform context
