class ActivitySpeedMonitorTransform : RabbitAsmClassVisitorTransformer {

    private val ACTIVITY_SPEED_MONITOR_CLASS =
        "com/susion/rabbit/monitor/instance/ActivitySpeedMonitor"

    //ActivitySpeedMonitor.wrapperViewOnActivityCreateEnd()
    private val wapperMethodName = "wrapperViewOnActivityCreateEnd"
    private val wapperMethodDesc = "(Landroid/app/Activity;)V"

    //ActivitySpeedMonitor.activityCreateStart()
    private val acCreateStartName = "activityCreateStart"
    private val acCreateStartDesc = "(Landroid/app/Activity;)V"

    //ActivitySpeedMonitor.activityResumeEnd()
    private val acResumeEndName = "activityResumeEnd"
    private val acResumeEndDesc = "(Landroid/app/Activity;)V"

    //activity onCreate 方法
    private val METHOD_ON_CREATE_NAME = "onCreate"
    private val METHOD_ONCREATE_DESC = "(Landroid/os/Bundle;)V"

    //activity onResume 方法
    private val METHOD_ON_RESUME_NAME = "onResume"
    private val METHOD_ON_RESUME_DESC = "()V"

    private val activityList = mutableSetOf<String>()

    override fun onPreTransform(context: TransformContext) {
        val parser = SAXParserFactory.newInstance().newSAXParser()
        context.artifacts.get(ArtifactManager.MERGED_MANIFESTS).forEach { manifest ->
            val handler = ComponentHandler()
            parser.parse(manifest, handler)
            activityList.addAll(handler.activities)
        }
    }

    override fun transform(context: TransformContext, klass: ClassNode,classFilePath:String): ClassNode {

        if (!GlobalConfig.pluginConfig.enableSpeedCheck){
            return klass
        }

        if (!activityList.contains(klass.className) || !RabbitTransformUtils.classInPkgList(klass.className, GlobalConfig.pluginConfig.pageSpeedMonitorPkgs)) {
            return klass
        }

        insertCodeToActivityOnCreate(klass)

        insertCodeToActivityOnResume(klass)

        return klass

    }

    private fun insertCodeToActivityOnCreate(klass: ClassNode) {
        val onCreateMethod = klass.methods?.find {
            "${it.name}${it.desc}" == "$METHOD_ON_CREATE_NAME$METHOD_ONCREATE_DESC"
        } ?: return

        onCreateMethod.instructions?.find(Opcodes.RETURN)?.apply {
            RabbitTransformUtils.print("ActivitySpeedMonitorTransform : insert code to wrap activity content view ---> ${klass.name}")
            onCreateMethod.instructions?.insertBefore(this, VarInsnNode(Opcodes.ALOAD, 0)) //参数
            onCreateMethod.instructions?.insertBefore(this, getWrapSpeedViewMethod())
        }

        onCreateMethod.instructions?.find(Opcodes.ALOAD)?.apply {
            RabbitTransformUtils.print("ActivitySpeedMonitorTransform : insert code to on activity create ---> ${klass.name}")
            onCreateMethod.instructions?.insertBefore(this, VarInsnNode(Opcodes.ALOAD, 0)) //参数
            onCreateMethod.instructions?.insertBefore(this, getAcCreateStateMethod())
        }
    }

    private fun insertCodeToActivityOnResume(klass: ClassNode) {
        var onResumeMethod = klass.methods?.find {
            "${it.name}${it.desc}" == "$METHOD_ON_RESUME_NAME$METHOD_ON_RESUME_DESC"
        }

        if (onResumeMethod == null) {
            onResumeMethod = getDefaultOnResumeMethod(klass)
            klass.methods.add(onResumeMethod)
        }

        onResumeMethod.instructions?.find(Opcodes.RETURN)?.apply {
            RabbitTransformUtils.print("ActivitySpeedMonitorTransform: insert code to  ${onResumeMethod.name} --- ${klass.name}")
            onResumeMethod.instructions?.insertBefore(this, VarInsnNode(Opcodes.ALOAD, 0)) //参数
            onResumeMethod.instructions?.insertBefore(this, getAcResumeStateMethod())
        }
    }

    private fun getAcResumeStateMethod(): MethodInsnNode {
        return MethodInsnNode(
            Opcodes.INVOKESTATIC,
            ACTIVITY_SPEED_MONITOR_CLASS,
            acResumeEndName,
            acResumeEndDesc,
            false
        )
    }

    private fun getWrapSpeedViewMethod() = MethodInsnNode(
        Opcodes.INVOKESTATIC,
        ACTIVITY_SPEED_MONITOR_CLASS,
        wapperMethodName,
        wapperMethodDesc,
        false
    )

    private fun getAcCreateStateMethod() = MethodInsnNode(
        Opcodes.INVOKESTATIC,
        ACTIVITY_SPEED_MONITOR_CLASS,
        acCreateStartName,
        acCreateStartDesc,
        false
    )

    private fun getDefaultOnResumeMethod(klass: ClassNode): MethodNode {
        RabbitTransformUtils.print("ActivitySpeedMonitorTransform: new onResume() Method --> super class name : ${klass.superName}  --->")
        return MethodNode(
            Opcodes.ACC_PROTECTED,
            METHOD_ON_RESUME_NAME,
            METHOD_ON_RESUME_DESC,
            null,
            null
        ).apply {
            instructions.add(InsnList().apply {
                add(VarInsnNode(Opcodes.ALOAD, 0))
                add(
                    MethodInsnNode(
                        Opcodes.INVOKESPECIAL,
                        klass.superName,
                        METHOD_ON_RESUME_NAME,
                        METHOD_ON_RESUME_DESC,
                        false
                    )
                )
                add(InsnNode(Opcodes.RETURN))
            })
            maxStack = 1
        }
    }

}

class AppStartSpeedMeasureTransform : RabbitAsmClassVisitorTransformer {

    private val METHOD_ATTACH_CONTEXT_NAME = "attachBaseContext"
    private val METHOD_ATTACH_CONTEXT_DESC = "(Landroid/content/Context;)V"

    private val METHOD_ON_CREATE_NAME = "onCreate"
    private val METHOD_ONCREATE_DESC = "()V"

    private val applications = mutableSetOf<String>()

    override fun onPreTransform(context: TransformContext) {
        val parser = SAXParserFactory.newInstance().newSAXParser()
        context.artifacts.get(ArtifactManager.MERGED_MANIFESTS).forEach { manifest ->
            val handler = ComponentHandler()
            parser.parse(manifest, handler)
            applications.addAll(handler.applications)
        }
    }

    override fun transform(context: TransformContext, klass: ClassNode,classFilePath:String): ClassNode {

        if (!GlobalConfig.pluginConfig.enableSpeedCheck){
            return klass
        }

        if (!this.applications.contains(klass.className)) {
            return klass
        }

        insertApplicationStartRecordCode(klass)

        insertApplicationEndRecordCode(klass)

        return klass

    }

    private fun insertApplicationEndRecordCode(klass: ClassNode) {
        var onCreateMethod = klass.methods?.find {
            "${it.name}${it.desc}" == "$METHOD_ON_CREATE_NAME$METHOD_ONCREATE_DESC"
        }

        if (onCreateMethod == null) {
            onCreateMethod = getOnCreateMethod(klass)
            klass.methods.add(onCreateMethod)
        }

        onCreateMethod.instructions?.find(Opcodes.RETURN)?.apply {

            RabbitTransformUtils.print("AppStartSpeedMeasureTransform: insert code to  ${onCreateMethod.name} --- ${this.opcode}")

            onCreateMethod.instructions?.insertBefore(
                this,
                MethodInsnNode(
                    Opcodes.INVOKESTATIC,
                    AppStartTracer.CLASS_PATH,
                    AppStartTracer.METHOD_RECORD_APPLICATION_CREATE_END,
                    "()V",
                    false
                )
            )
        }
    }

    private fun insertApplicationStartRecordCode(klass: ClassNode) {
        var attachMethod = klass.methods?.find {
            "${it.name}${it.desc}" == "$METHOD_ATTACH_CONTEXT_NAME$METHOD_ATTACH_CONTEXT_DESC"
        }

        if (attachMethod == null) {
            attachMethod = getAttachBaseContextMethod(klass)
            klass.methods.add(attachMethod)
        }

        attachMethod.instructions?.find(Opcodes.ALOAD)?.apply {

            RabbitTransformUtils.print("insert code to  ${attachMethod.name} --- ${klass.name}")

            attachMethod.instructions?.insertBefore(
                this,
                MethodInsnNode(
                    Opcodes.INVOKESTATIC,
                    AppStartTracer.CLASS_PATH,
                    AppStartTracer.METHOD_RECORD_APPLICATION_CREATE_START,
                    "()V",
                    false
                )
            )
        }
    }


    private fun getAttachBaseContextMethod(klass: ClassNode): MethodNode {
        RabbitTransformUtils.print("new Attach Method --> super class name : ${klass.superName}  --->")
        return MethodNode(
            Opcodes.ACC_PROTECTED,
            METHOD_ATTACH_CONTEXT_NAME,
            METHOD_ATTACH_CONTEXT_DESC,
            null,
            null
        ).apply {
            instructions.add(InsnList().apply {
                add(VarInsnNode(Opcodes.ALOAD, 0))
                add(VarInsnNode(Opcodes.ALOAD, 1))
                add(
                    MethodInsnNode(
                        Opcodes.INVOKESPECIAL,
                        klass.superName,
                        METHOD_ATTACH_CONTEXT_NAME,
                        METHOD_ATTACH_CONTEXT_DESC,
                        false
                    )
                )
                add(InsnNode(Opcodes.RETURN))
            })
            maxStack = 1
        }
    }

    private fun getOnCreateMethod(klass: ClassNode): MethodNode {
        RabbitTransformUtils.print("new getOnCreateMethod Method --> super class name : ${klass.superName}  --->")
        return MethodNode(
            Opcodes.ACC_PUBLIC,
            METHOD_ON_CREATE_NAME,
            METHOD_ONCREATE_DESC,
            null,
            null
        ).apply {
            instructions.add(InsnList().apply {
                add(VarInsnNode(Opcodes.ALOAD, 0))
                add(
                    MethodInsnNode(
                        Opcodes.INVOKESPECIAL,
                        klass.superName,
                        METHOD_ON_CREATE_NAME,
                        METHOD_ONCREATE_DESC,
                        false
                    )
                )
                add(InsnNode(Opcodes.RETURN))
            })
            maxStack = 1
        }
    }

}

class BlockCodeLoadTransform : RabbitAsmClassVisitorTransformer {

    override fun transform(
        context: TransformContext,
        klass: ClassNode,
        classFilePath: String
    ): ClassNode {

        if (!GlobalConfig.pluginConfig.enableBlockCodeCheck) {
            return klass
        }

        if (klass.name != RabbitScanIoOpHelper.CLASS_PATH) {
            return klass
        }

        RabbitTransformUtils.print("🌞 BlockCodeLoadTransform start load io method call,  scan ${GlobalConfig.ioMethodCall.size} method !")

        val method = klass.methods.find { it.name == RabbitScanIoOpHelper.METHOD_INJECT_IO_CALL }
        method?.instructions?.find(Opcodes.RETURN)?.apply {
            GlobalConfig.ioMethodCall.forEach { ioCall ->
                method.instructions?.insertBefore(this, LdcInsnNode(ioCall))
                method.instructions?.insertBefore(this, getAddIoMethod())
            }
        }

        return klass
    }

    private fun getAddIoMethod(): MethodInsnNode {
        return MethodInsnNode(
            Opcodes.INVOKESTATIC,
            RabbitScanIoOpHelper.CLASS_PATH,
            RabbitScanIoOpHelper.METHOD_ADD_IO_METHOD,
            RabbitScanIoOpHelper.METHOD_ADD_PKG_IO_PARAMS,
            false
        )
    }

}

class BlockCodeScanTransform : RabbitAsmClassVisitorTransformer {

    private val blockApis: Set<String> by lazy {
        if (GlobalConfig.pluginConfig.customBlockCodeCheckList.isNotEmpty()) {
            GlobalConfig.pluginConfig.customBlockCodeCheckList
        } else {
            DEFAULT_BLOCK_APIS
        }
    }

    override fun transform(
        context: TransformContext,
        klass: ClassNode,
        classFilePath: String
    ): ClassNode {

        if (!GlobalConfig.pluginConfig.enableBlockCodeCheck) {
            return klass
        }

        if (!RabbitTransformUtils.classInPkgList(
                klass.className,
                GlobalConfig.pluginConfig.blockCodePkgs
            )
        ) {
            return klass
        }

        scanIoMethod(klass)

        return klass
    }

    private fun scanIoMethod(klass: ClassNode) {

        klass.methods.forEach { method ->

            val invokeStr = "${klass.name}.${method.name}"

            method.instructions.iterator().asIterable().filterIsInstance(MethodInsnNode::class.java)
                .forEach { invoke ->

                    val calledStr = "${invoke.owner}.${invoke.name}"

                    if (blockApis.any { it.contains(calledStr) }) {

                        val ioCallStr =
                            "${invokeStr.replace("/", ".")}()&${calledStr.replace("/", ".")}()"

                        GlobalConfig.ioMethodCall.add(ioCallStr)

                        RabbitTransformUtils.print("💻  BlockCodeScanTransform : scan io method -> $ioCallStr")
                    }
                }

        }
    }

}

class MethodCostMonitorTransform : RabbitAsmByteArrayTransformer {

    override fun transform(
        context: TransformContext,
        bytes: ByteArray,
        classFilePath: String
    ): ByteArray {

        if (!GlobalConfig.pluginConfig.enableMethodCostCheck) {
            return bytes
        }

        val classReader = ClassReader(bytes)
        val classWriter = ClassWriter(classReader, ClassWriter.COMPUTE_MAXS)
        val classVisitor = MethodCostClassVisitor(
            Opcodes.ASM6,
            classWriter
        )
        classReader.accept(classVisitor, EXPAND_FRAMES)
        return classWriter.toByteArray()
    }

}

class RabbitPluginConfigTransform : RabbitAsmClassVisitorTransformer {

    override fun transform(context: TransformContext, klass: ClassNode,classFilePath:String): ClassNode {

        if (klass.name != RabbitPluginConfig.CLASS_PATH) {
            return klass
        }

        loadMethodPkgConfig(klass)

        return klass
    }

    private fun loadMethodPkgConfig(klass: ClassNode) {
        val method = klass.methods.find { it.name == RabbitPluginConfig.METHOD_INJECT_METHOD_PKGS }
        method?.instructions?.find(Opcodes.RETURN)?.apply {
            GlobalConfig.pluginConfig.methodMonitorPkgs.forEach { name ->
                RabbitTransformUtils.print("RabbitPluginConfigTransform:  add method pkg : $name")
//                method.instructions?.insertBefore(this, VarInsnNode(Opcodes.ALOAD, 0))   调静态方法不需要这玩意， 这个是this
                method.instructions?.insertBefore(this, LdcInsnNode(name))
                method.instructions?.insertBefore(this, getAddMethodPkgMethod())
            }
        }
    }

    private fun getAddMethodPkgMethod(): MethodInsnNode {
        return MethodInsnNode(
            Opcodes.INVOKESTATIC,
            RabbitPluginConfig.CLASS_PATH,
            RabbitPluginConfig.METHOD_ADD_PKG_TO_METHOD_PKGS,
            RabbitPluginConfig.METHOD_ADD_PKG_TO_METHOD_PKGS_PARAMS,
            false
        )
    }

}

class MethodCostClassVisitor(api: Int, cv: ClassVisitor) : ClassVisitor(api, cv) {

    private val notTraceMethods = listOf("<init>", "<clinit>")
    private var className: String = ""
    private var isInConfigPkgList = false

    override fun visit(
        version: Int,
        access: Int,
        name: String?,
        signature: String?,
        superName: String?,
        interfaces: Array<out String>?
    ) {
        super.visit(version, access, name, signature, superName, interfaces)

        this.className = name?.replace("/", ".") ?: ""

        isInConfigPkgList = RabbitTransformUtils.classInPkgList(
            className,
            GlobalConfig.pluginConfig.methodMonitorPkgs
        )

    }

    override fun visitMethod(
        access: Int,
        name: String?,
        desc: String?,
        signature: String?,
        exceptions: Array<out String>?
    ): MethodVisitor {

        val isUnImplMethod = access and Opcodes.ACC_ABSTRACT > 0    //未实现的方法

        return if (notTraceMethods.contains(name) || isUnImplMethod || !isInConfigPkgList) {
            super.visitMethod(access, name, desc, signature, exceptions)
        } else {
            val methodName = "$className&$name()"
            RabbitTransformUtils.print("MethodCostClassVisitor -> className : $className  methodName-> $methodName")
            val mv = cv.visitMethod(access, name, desc, signature, exceptions)
            MethodCostMethodVisitor(
                api,
                mv,
                access,
                name,
                desc,
                methodName
            )
        }
    }

}

class MethodCostMethodVisitor(
    api: Int,
    methodVisitor: MethodVisitor?,
    access: Int,
    name: String?,
    descriptor: String?,
    val methodNameParams: String
) : AdviceAdapter(api, methodVisitor, access, name, descriptor) {

    override fun onMethodEnter() {
        super.onMethodEnter()
        mv.visitMethodInsn(
            Opcodes.INVOKESTATIC, MethodTracer.CLASS_PATH,
            MethodTracer.METHOD_RECORD_METHOD_START,
            "()V",
            false
        )
    }

    override fun onMethodExit(opcode: Int) {
        mv.visitLdcInsn(methodNameParams)
        mv.visitMethodInsn(
            Opcodes.INVOKESTATIC, MethodTracer.CLASS_PATH,
            MethodTracer.METHOD_RECORD_METHOD_END,
            MethodTracer.METHOD_RECORD_METHOD_END_PARAMS,
            false
        )
    }



}

object RabbitTransformUtils {


    fun print(msg: String) {
        if (!GlobalConfig.pluginConfig.printLog) return
        kotlin.io.print("🐰 -----> $msg \n")
    }

    fun print(tag: String, msg: String) {
        if (!GlobalConfig.pluginConfig.printLog) return
        kotlin.io.print("🐰 -----> TAG : $tag ; $msg \n")
    }


    fun classInPkgList(className: String, pkgList: List<String>): Boolean {

        if (pkgList.isEmpty()) return false

        pkgList.forEach {
            if (className.startsWith(it)) {
                return true
            }
        }
        return false
    }
}

internal open class ChoreographerFrameUpdateMonitor {

    private var isStart = false
    private val frameCallback = object : Choreographer.FrameCallback {
        override fun doFrame(frameTimeNanos: Long) {
            if (!isStart) return
            if (mLastFrameTimeNanos != 0L) {
                val diffFrameCoast = (frameTimeNanos - mLastFrameTimeNanos)
                mFrameListeners.forEach {
                    it.doFrame(diffFrameCoast)
                }
            }
            mLastFrameTimeNanos = frameTimeNanos
            Choreographer.getInstance().postFrameCallback(this)
        }
    }
    private val mFrameListeners = ArrayList<FrameUpdateListener>()
    private var mLastFrameTimeNanos: Long = 0

    fun startMonitorFrame() {
        isStart = true
        Choreographer.getInstance().postFrameCallback(frameCallback)
    }

    fun stopMonitorFrame() {
        isStart = false
        Choreographer.getInstance().removeFrameCallback(frameCallback)
    }

    interface FrameUpdateListener {
        fun doFrame(frameCostNs: Long)
    }

    fun addFrameUpdateListener(listener: FrameUpdateListener) {
        mFrameListeners.add(listener)
    }

    fun removeFrameUpdateListener(listener: FrameUpdateListener) {
        mFrameListeners.remove(listener)
    }

    fun getCurrentListenerSize() = mFrameListeners.size

}

internal object ChoreographerMonitorCenter {

    private val detailedFrameUpdateMonitor by lazy {
        LazyChoreographerFrameUpdateMonitor().apply {
            init()
        }
    }

    private val simpleFrameUpdateMonitor by lazy {
        ChoreographerFrameUpdateMonitor()
    }

    fun addSimpleFrameUpdateListener(listener: ChoreographerFrameUpdateMonitor.FrameUpdateListener) {
        if (simpleFrameUpdateMonitor.getCurrentListenerSize() == 0) {
            simpleFrameUpdateMonitor.startMonitorFrame()
            RabbitLog.d(TAG_MONITOR, "start simpleFrameUpdateMonitor")
        }
        simpleFrameUpdateMonitor.addFrameUpdateListener(listener)
    }

    fun removeSimpleFrameUpdateListener(listener: ChoreographerFrameUpdateMonitor.FrameUpdateListener) {
        simpleFrameUpdateMonitor.removeFrameUpdateListener(listener)
        if (simpleFrameUpdateMonitor.getCurrentListenerSize() == 0) {
            simpleFrameUpdateMonitor.stopMonitorFrame()
            RabbitLog.d(TAG_MONITOR, "stop simpleFrameUpdateMonitor")
        }
    }

    fun addDetailedFrameUpdateListener(listener: LazyChoreographerFrameUpdateMonitor.FrameUpdateListener) {
        if (detailedFrameUpdateMonitor.getCurrentListenerSize() == 0) {
            detailedFrameUpdateMonitor.startMonitor()
            RabbitLog.d(TAG_MONITOR, "start detailedFrameUpdateMonitor")
        }
        detailedFrameUpdateMonitor.addFrameUpdateListener(listener)
    }

    fun removeDetailedFrameUpdateListener(listener: LazyChoreographerFrameUpdateMonitor.FrameUpdateListener) {
        detailedFrameUpdateMonitor.removeFrameUpdateListener(listener)
        if (detailedFrameUpdateMonitor.getCurrentListenerSize() == 0) {
            detailedFrameUpdateMonitor.stopMonitor()
            RabbitLog.d(TAG_MONITOR, "stop detailedFrameUpdateMonitor")
        }
    }

}

private fun insertCallbackToInputQueue() {
    //已经插过一遍 [时间监控消息] 了， 不继续插入
    if (insertMonitorRunnable) {
        return
    }
    insertMonitorRunnable = true
    addCallbackToQueue(CALLBACK_INPUT, Runnable {
        insertMonitorRunnable = false
        actualExecuteDoFrame = true
        inputEventCostTimeNs = System.nanoTime()
    })

    addCallbackToQueue(CALLBACK_ANIMATION, Runnable {
        inputEventCostTimeNs = System.nanoTime() - inputEventCostTimeNs
        animationEventCostTimeNs = System.nanoTime()
    })

    addCallbackToQueue(CALLBACK_TRAVERSAL, Runnable {
        animationEventCostTimeNs = System.nanoTime() - animationEventCostTimeNs
        traversalEventCostTimeNs = System.nanoTime()
    })
}

internal class UIThreadLooperMonitor {

    private var mHandleEventListeners = ArrayList<LooperHandleEventListener>()
    private var mHookedPrinter: Printer? = null
    private var mOriginPrinter: Printer? = null
    var enable = false

    init {
        mOriginPrinter = RabbitReflectHelper.reflectField<Printer>(Looper.getMainLooper(), "mLogging")

        mHookedPrinter = Printer { x ->

            mOriginPrinter?.println(x)

            if (!enable) return@Printer

            val dispatch = x[0] == '>' || x[0] == '<'

            if (dispatch) {
                notifyListenerLooperProcessMsg(x[0] == '>')
            }
        }

        Looper.getMainLooper().setMessageLogging(mHookedPrinter)
    }

    fun addLooperHandleEventListener(listener: LooperHandleEventListener) {
        mHandleEventListeners.add(listener)
    }

    fun removeLooperHandleEventListener(listener: LooperHandleEventListener) {
        mHandleEventListeners.remove(listener)
    }

    @UiThread
    private fun notifyListenerLooperProcessMsg(start: Boolean) {
        mHandleEventListeners.forEach {
            if (start) {
                it.onMessageLooperStartHandleMessage()
            } else {
                it.onMessageLooperStopHandleMessage()
            }
        }
    }

    interface LooperHandleEventListener {
        fun onMessageLooperStartHandleMessage()
        fun onMessageLooperStopHandleMessage()
    }

}

public class ActivitySpeedMonitor extends FrameLayout {

    public String activityName = "UnDefined";

    public ActivitySpeedMonitor(@NonNull Context context) {
        super(context);
    }

    public ActivitySpeedMonitor(@NonNull Context context, @Nullable AttributeSet attrs) {
        super(context, attrs);
    }

    public ActivitySpeedMonitor(@NonNull Context context, @Nullable AttributeSet attrs, int defStyleAttr) {
        super(context, attrs, defStyleAttr);
    }

    @Override
    protected void dispatchDraw(Canvas canvas) {
        super.dispatchDraw(canvas);
        RabbitTracerEventNotifier.appSpeedNotifier.activityDrawFinish(activityName, System.currentTimeMillis());

    }

    public static void wrapperViewOnActivityCreateEnd(Activity activity) {
        RabbitTracerEventNotifier.appSpeedNotifier.activityCreateEnd(activity, System.currentTimeMillis());
        ViewGroup contentView = activity.findViewById(android.R.id.content);

        if (contentView != null && contentView.getChildCount() >= 1 && contentView instanceof FrameLayout) {
            View realAcContent = contentView.getChildAt(0);
            ActivitySpeedMonitor monitorWrapperView = new ActivitySpeedMonitor(contentView.getContext());
            monitorWrapperView.activityName = activity.getClass().getSimpleName();
            contentView.addView(monitorWrapperView,0);

            //把activity的根布局包上一层
            contentView.removeView(realAcContent);
            monitorWrapperView.addView(realAcContent);

            final int childCount = contentView.getChildCount();
            if (childCount > 1) {
                List<View>  oldChilds = new ArrayList<>();
                for (int i = 1; i < childCount; i++) {
                    View child = contentView.getChildAt(i);
                    if (child != null){
                        oldChilds.add(child);
                        contentView.removeView(child);
                    }
                }

                for (int i=0; i < oldChilds.size(); i++){
                    monitorWrapperView.addView(oldChilds.get(i));
                }
            }
        }
    }

    public static void activityCreateStart(Activity activity) {
        RabbitTracerEventNotifier.appSpeedNotifier.activityCreateStart(activity, System.currentTimeMillis());
    }

    public static void activityResumeEnd(Activity activity) {
        RabbitTracerEventNotifier.appSpeedNotifier.activityResumeEnd(activity, System.currentTimeMillis());
    }

}

internal class RabbitANRHighVersionMonitor(override var isOpen: Boolean = false) :
    RabbitMonitorProtocol, ChoreographerFrameUpdateMonitor.FrameUpdateListener {

    private var monitorThread: HandlerThread? = null
    private var stackCollectHandler: Handler? = null
    private var blockStackTraces = HashMap<String, RabbitBlockStackTraceInfo>()
    private val stackCollectPeriod = RabbitMonitor.mConfig.anrStackCollectPeriodNs
    private val stackPostDelayTime =
        TimeUnit.MILLISECONDS.convert(stackCollectPeriod, TimeUnit.NANOSECONDS)
    private val anrCheckPeriodNs = RabbitMonitor.mConfig.anrCheckPeriodNs
    private var collectCount = 0

    //采集一次主线程堆栈, 【随机的， 因此并不一定是卡顿点, 不过抓住卡顿点的概率很大】
    private val blockStackCollectTask = object : Runnable {
        override fun run() {
            if (collectCount > 1) {
                captureMainThreadStack()   // 避免频繁抓取主线程堆栈
            }
            collectCount++
            if (collectCount * stackCollectPeriod >= anrCheckPeriodNs) {
                Toast.makeText(RabbitMonitor.application, "检测到ANR!!", Toast.LENGTH_SHORT).show()
                val anrInfo = RabbitAnrInfo()
                anrInfo.apply {
                    stackStr = Gson().toJson(blockStackTraces.values.toList())
                    time = System.currentTimeMillis()
                    pageName = RabbitMonitor.getCurrentPage()
                    invalid = true
                }
                RabbitStorage.save(anrInfo)
                stackCollectHandler?.removeCallbacks(this)
            } else {
                stackCollectHandler?.postDelayed(this, stackPostDelayTime)
            }
        }
    }

    //在某个线程不断地获取主线程堆栈要暂停主线程的运行
    private fun captureMainThreadStack() {
        val stackStr = RabbitUtils.traceToString(0, Looper.getMainLooper().thread.stackTrace)
        val stackTrace = RabbitBlockStackTraceInfo(stackStr)
        val mapKey = stackTrace.getMapKey()
        val info = blockStackTraces[mapKey]
        if (info == null) {
            blockStackTraces[mapKey] = stackTrace
        } else {
            info.collectCount++
        }
    }

    override fun open(context: Context) {
        monitorThread = HandlerThread("rabbit_anr_monitor")
        monitorThread!!.start()
        stackCollectHandler = Handler(monitorThread!!.looper)

        ChoreographerMonitorCenter.addSimpleFrameUpdateListener(this)
        isOpen = true
    }

    override fun close() {
        monitorThread?.quitSafely()
        ChoreographerMonitorCenter.removeSimpleFrameUpdateListener(this)
        isOpen = false
    }

    override fun doFrame(frameCostNs: Long) {
        stackCollectHandler?.removeCallbacks(blockStackCollectTask)
        collectCount = 0
        blockStackTraces.clear()
        stackCollectHandler?.postDelayed(blockStackCollectTask, stackPostDelayTime)
    }

    override fun getMonitorInfo() = RabbitMonitorProtocol.ANR

}

private val blockStackCollectTask = object : Runnable {
    override fun run() {
        if (collectCount > 1) {
            captureMainThreadStack()   // 避免频繁抓取主线程堆栈
        }
