}

internal class RabbitANRLowVersionMonitor(override var isOpen: Boolean = false) : RabbitMonitorProtocol {

    private val calculatePeriodMS = 15000
    private var lastTime: Long = 0
    private val traceFileObserver by lazy {
        object : FileObserver("data/anr/", CLOSE_WRITE) {
            override fun onEvent(event: Int, path: String?) {
                if (path.isNullOrEmpty()) return
                RabbitLog.d(TAG_MONITOR, "monitor anr $path")
                val filepath = "/data/anr/$path"
                if (filepath.contains("trace")) {
                    RabbitAsync.asyncRun({
                        parseAnrFile(filepath)
                    })
                }
            }
        }
    }
    private val pageShowedListener = object : RabbitMonitor.PageChangeListener {
        override fun onPageShow() {
            syncAnrRecord()
        }
    }

    override fun open(context: Context) {
        try {
            traceFileObserver.startWatching()
        } catch (e: Exception) {
            RabbitLog.d(TAG_MONITOR, "anr file observer start failed")
        }
        RabbitMonitor.addPageChangeListener(pageShowedListener)
        syncAnrRecord()
        isOpen = true
    }

    override fun close() {
        traceFileObserver.stopWatching()
        RabbitMonitor.removePageChangeListener(pageShowedListener)
        isOpen = false
    }

    /**
     * 记录简要的anr信息,找时机补全 [syncAnrRecord]
     * */
    fun parseAnrFile(filepath: String) {

        val anrInfo = RabbitAnrInfo()
        val anrTime = System.currentTimeMillis()

        if (anrTime - lastTime < calculatePeriodMS) {
            return
        }

        lastTime = anrTime

        RabbitMonitorUtils.fillSimpleAnrInfo(anrInfo, File(filepath))

        RabbitLog.d(TAG_MONITOR, "采集anr信息成功 ! save to db")

        RabbitStorage.saveSync(anrInfo)

    }

    private fun syncAnrRecord() {
        RabbitLog.d(TAG_MONITOR, "syncAnrRecord---> ")
        RabbitStorage.getAll(RabbitAnrInfo::class.java,
            condition = Pair(RabbitAnrInfoDao.Properties.Invalid, false),
            orderDesc = true,
            loadResult = { anrList ->
                RabbitLog.d(TAG_MONITOR, " syncAnrRecord anr size : ${anrList.size}")
                for (anr in anrList) {
                    anr.stackStr = RabbitMonitorUtils.getAnrStack(anr)
                    if (anr.stackStr.isNotEmpty()) {
                        anr.invalid = true
                        RabbitLog.d(TAG_MONITOR, "回溯 ANR -> ${anr.time}")
                        RabbitStorage.updateOrCreate(
                            RabbitAnrInfo::class.java,
                            anr,
                            anr.id
                        )
                    } else {
                        RabbitStorage.delete(RabbitAnrInfo::class.java, anr.id)
                        RabbitLog.d(TAG_MONITOR, "删除无效的ANR记录 -> ${anr.time}")
                    }
                }
            })
    }

    override fun getMonitorInfo() = RabbitMonitorProtocol.ANR

}

internal class RabbitAppPerformanceMonitor(override var isOpen: Boolean = false) : RabbitMonitorProtocol {

    private var appPerformanceInfo: RabbitAppPerformanceInfo? = null
    private val dataStorageListener = object : RabbitStorage.EventListener {
        override fun onStorageData(obj: Any) {
            if (appPerformanceInfo == null) return
            relatedIdToAppPerformanceInfo(obj)
        }
    }

    override fun close() {
        saveMonitorInfo(false)
        appPerformanceInfo = null
        RabbitStorage.removeEventListener(dataStorageListener)
    }

    override fun open(context: Context) {
        appPerformanceInfo = RabbitAppPerformanceInfo()
        appPerformanceInfo?.time = System.currentTimeMillis()
        appPerformanceInfo?.endTime = System.currentTimeMillis()
        RabbitStorage.addEventListener(dataStorageListener)
    }

    private fun relatedIdToAppPerformanceInfo(obj: Any) {
        when (obj) {
            is RabbitFPSInfo -> {
                appPerformanceInfo?.fpsIds = "${appPerformanceInfo?.fpsIds ?: ""}${obj.id}&"
            }
            is RabbitMemoryInfo -> {
                appPerformanceInfo?.memoryIds = "${appPerformanceInfo?.memoryIds ?: ""}${obj.id}&"
            }
            is RabbitAppStartSpeedInfo -> {
                appPerformanceInfo?.appStartId = obj.id.toString()
            }
            is RabbitPageSpeedInfo -> {
                appPerformanceInfo?.pageSpeedIds =
                    "${appPerformanceInfo?.pageSpeedIds ?: ""}${obj.id}&"
            }
            is RabbitBlockFrameInfo -> {
                appPerformanceInfo?.blockIds = "${appPerformanceInfo?.blockIds ?: ""}${obj.id}&"
            }
            is RabbitSlowMethodInfo -> {
                appPerformanceInfo?.slowMethodIds =
                    "${appPerformanceInfo?.slowMethodIds ?: ""}${obj.id}&"
            }
        }

        saveMonitorInfo(true)
    }

    private fun saveMonitorInfo(isRunning: Boolean = false) {
        if (appPerformanceInfo != null) {
            appPerformanceInfo?.isRunning = isRunning
            appPerformanceInfo?.endTime = System.currentTimeMillis()
            RabbitStorage.updateOrCreate(
                RabbitAppPerformanceInfo::class.java,
                appPerformanceInfo!!,
                appPerformanceInfo?.id ?: 0
            )
        }
    }

    override fun getMonitorInfo() = RabbitMonitorProtocol.GLOBAL_MONITOR

}

internal class RabbitAppUseTimeMonitor(override var isOpen: Boolean = false) :
    RabbitMonitorProtocol {

    private var totalTime = 0L
    private var oneSessionRunTime: Long = 0

    //应用可见性监控
    private val applicationLifecycle = object : LifecycleObserver {
        @OnLifecycleEvent(Lifecycle.Event.ON_START)
        fun onForeground() {
            oneSessionRunTime = System.currentTimeMillis()
        }

        @OnLifecycleEvent(Lifecycle.Event.ON_STOP)
        fun onBackground() {
            totalTime += (System.currentTimeMillis() - oneSessionRunTime)
        }
    }

    override fun open(context: Context) {
        ProcessLifecycleOwner.get().lifecycle.addObserver(applicationLifecycle)
        oneSessionRunTime = System.currentTimeMillis()
        isOpen = true
    }

    override fun close() {
        ProcessLifecycleOwner.get().lifecycle.removeObserver(applicationLifecycle)
        isOpen = false
    }

    override fun getMonitorInfo() = RabbitMonitorProtocol.USE_TIME

    fun getAppUseTimeS(): Long {
        val useTime = totalTime + (System.currentTimeMillis() - oneSessionRunTime)
        return TimeUnit.SECONDS.convert(useTime, TimeUnit.MILLISECONDS)
    }

}

private val blockStackCollectTask = object : Runnable {
    override fun run() {
        collectCount++
        if (collectCount > 1) {
            val stackTrace = RabbitBlockStackTraceInfo(getUiThreadStackTrace())
            val mapKey = stackTrace.getMapKey()
            val info = blockStackTraces[mapKey]
            if (info == null) {
                blockStackTraces[mapKey] = stackTrace
            } else {
                info.collectCount++
            }
        }
        stackCollectHandler?.postDelayed(this, stackCollectPeriod)
    }
}

internal class RabbitExceptionMonitor(override var isOpen: Boolean = false) :
    RabbitMonitorProtocol {

    override fun open(context: Context) {
        val defaultExceptionHandler = Thread.getDefaultUncaughtExceptionHandler()
        Thread.setDefaultUncaughtExceptionHandler { thread, throwable ->
            saveCrash(throwable, thread, defaultExceptionHandler)
        }
        isOpen = true
    }

    override fun close() {
        isOpen = false
    }

    override fun getMonitorInfo() = RabbitMonitorProtocol.EXCEPTION

    fun saveCrash(
        e: Throwable,
        thread: Thread,
        defaultExceptionHandler: Thread.UncaughtExceptionHandler? = null
    ) {
        if (!isOpen) return
        toastInThread("发生异常! 日志已保存", RabbitMonitor.application)
        Thread.sleep(1000) // 把toast给弹出来
        val exceptionInfo = translateThrowableToExceptionInfo(e, Thread.currentThread().name)
        RabbitStorage.saveSync(exceptionInfo)
        //main thead 下崩溃
        if (RabbitUtils.isMainThread(thread.id)) {
            Thread.sleep(1500)
            defaultExceptionHandler?.uncaughtException(thread, e)
        }
    }

    private fun translateThrowableToExceptionInfo(
        e: Throwable,
        currentThread: String
    ): RabbitExceptionInfo {
        val exceptionInfo = RabbitExceptionInfo()
        exceptionInfo.apply {
            crashTraceStr = RabbitLog.getStackTraceString(e)
            exceptionName = e.javaClass.name
            simpleMessage = e.message ?: ""
            threadName = currentThread
            time = System.currentTimeMillis()
            pageName = RabbitMonitor.getCurrentPage()
        }

        return exceptionInfo
    }

}

internal class RabbitFPSMonitor(override var isOpen: Boolean = false) :
    LazyChoreographerFrameUpdateMonitor.FrameUpdateListener,
    RabbitMonitorProtocol {

    private var frameIntervalNs: Long = RabbitMonitorConfig.STANDARD_FRAME_NS
    private val FPS_COLLECT_PERIOD_NS = RabbitMonitor.mConfig.fpsCollectThresholdNs
    private val FPS_COLLECT_NUMBER = (TimeUnit.NANOSECONDS.convert(
        RabbitMonitor.mConfig.fpsReportPeriodS,
        TimeUnit.SECONDS
    )) / (RabbitMonitorConfig.STANDARD_FRAME_NS)  // 多少帧记录一次数据
    private var totalFrameNs: Long = 0
    private var totalFrameNumber: Long = 0
    private var lastTotalFrameNs: Long = 0
    private var lastTotalFrameNumber: Long = 0
    private val fpsList = ArrayList<Int>()
    private val pageShowedListener = object : RabbitMonitor.PageChangeListener {
        override fun onPageShow() {
            saveFpsInfo()
        }
    }

    override fun open(context: Context) {
        ChoreographerMonitorCenter.addDetailedFrameUpdateListener(this)
        RabbitMonitor.addPageChangeListener(pageShowedListener)
        isOpen = true
    }

    override fun close() {
        ChoreographerMonitorCenter.removeDetailedFrameUpdateListener(this)
        RabbitMonitor.uiEventListener?.updateUi(RabbitUiEvent.MSG_UPDATE_FPS, 0f)
        RabbitMonitor.removePageChangeListener(pageShowedListener)
        isOpen = false
    }

    override fun getMonitorInfo() = RabbitMonitorProtocol.FPS

    override fun doFrame(
        frameCostNs: Long,
        inputCostNs: Long,
        animationCostNs: Long,
        traversalCostNs: Long
    ) {
        fpsCalculate(frameCostNs)
    }

    /**
     * 计算当前的帧率
     * */
    private fun fpsCalculate(frameCostNs: Long) {

        val costUnitFrameNumber = (frameCostNs / frameIntervalNs) + 1

        totalFrameNs += (costUnitFrameNumber * frameIntervalNs)
        totalFrameNumber += 1

        val durationNs = totalFrameNs - lastTotalFrameNs
        val collectFrame = totalFrameNumber - lastTotalFrameNumber

        if (durationNs >= FPS_COLLECT_PERIOD_NS) {
            val radio =
                TimeUnit.NANOSECONDS.convert(1, TimeUnit.SECONDS) * 1.0f / FPS_COLLECT_PERIOD_NS
            val fps = min(60f, collectFrame * radio)
            RabbitMonitor.uiEventListener?.updateUi(RabbitUiEvent.MSG_UPDATE_FPS, fps)
            lastTotalFrameNs = totalFrameNs
            lastTotalFrameNumber = totalFrameNumber
            fpsList.add(fps.toInt())
        }

        if (totalFrameNumber > FPS_COLLECT_NUMBER && totalFrameNumber % FPS_COLLECT_NUMBER == 0L) {
            saveFpsInfo()
        }

    }

    //持久化fps采集的信息
    @Synchronized
    private fun saveFpsInfo() {
        if (fpsList.isEmpty()) return
        val currentPageName = RabbitMonitor.getCurrentPage()
        val monitorPkgList = RabbitMonitor.mConfig.fpsMonitorPkgList
        if (monitorPkgList.isNotEmpty() && !RabbitUtils.classInPkgList(
                currentPageName,
                monitorPkgList
            )
        ) return
//        RabbitLog.d(TAG_MONITOR, "saveFpsInfo ---> current page name : $currentPageName")
        val fpsInfo = RabbitFPSInfo()
        fpsInfo.maxFps = fpsList.max() ?: 0
        fpsInfo.minFps = fpsList.min() ?: 0
        fpsInfo.avgFps = fpsList.average().toInt()
        fpsInfo.pageName = currentPageName
        fpsInfo.time = System.currentTimeMillis()
        RabbitStorage.save(fpsInfo)
        fpsList.clear()
    }

}

