object RabbitReport {

    lateinit var application: Application
    var mConfig: RabbitReportConfig = RabbitReportConfig()
    private var deviceInfoStr = ""
    private val REQUEST_THREAD = Executors.newFixedThreadPool(
        1
    ) { r -> Thread(r, "rabbit_report_request_thread") }

    private val dataEmitterTask by lazy {
        RabbitReportDataEmitterTask()
    }

    private val LOAD_POINT_TO_EMITER_QUEUE = 1
    private val mHandler = object : Handler(Looper.getMainLooper()) {
        override fun handleMessage(msg: Message) {
            when (msg.what) {
                LOAD_POINT_TO_EMITER_QUEUE -> {
                    val loadDataCount = RabbitReportDataEmitterTask.EMITER_QUEUE_MAX_SIZE / 2
                    RabbitStorage.getAll(
                        RabbitReportInfo::class.java,
                        count = loadDataCount,
                        sortField = "time",
                        loadResult = {
                            dataEmitterTask.addPointsToEmitterQueue(it)
                            RabbitLog.d(TAG_REPORT, "load point from db! Emitter Start")
                            startEmitterTask()
                        })
                }
            }
        }
    }

    fun init(app: Application, config: RabbitReportConfig) {

        application = app
        mConfig = config

        mConfig.notReportDataFormat.add(RabbitReportInfo::class.java)

        mConfig.notReportDataFormat.forEach {
            mConfig.notReportDataNames.add(it.simpleName)
        }

        RabbitAsync.asyncRun({
            deviceInfoStr = Gson().toJson(getDeviceInfo(application))
            RabbitLog.d(TAG_REPORT, "device info : $deviceInfoStr")
        })

        dataEmitterTask.eventListener = object : RabbitReportDataEmitterTask.EventListener {
            override fun successEmitterPoint(pointInfo: RabbitReportInfo) {
                RabbitStorage.delete(
                    RabbitReportInfo::class.java,
                    condition = Pair(
                        RabbitReportInfoDao.Properties.Time,
                        pointInfo.time.toString()
                    )
                )
            }

            override fun pointQueueIsEmpty() {
                val currentDbPointCount =
                    RabbitStorage.totalCount(RabbitReportInfo::class.java)
                RabbitLog.d(TAG_REPORT, "pointQueueIsEmpty db point : $currentDbPointCount")
                if (currentDbPointCount > 0) {
                    mHandler.sendEmptyMessage(LOAD_POINT_TO_EMITER_QUEUE)
                }
            }
        }
    }

    /**
     * @param useTime  应用使用的总时长
     * */
    fun report(info: Any, useTime: Long = 0) {

        //暴露给外界的数据上报接口
        if (mConfig.dataReportListener?.onPrepareReportData(info, useTime) == false) return

        if (!mConfig.enable) return

        if (mConfig.notReportDataFormat.contains(info.javaClass)) return

        if (mConfig.reportPath == RabbitReportConfig.UNDEFINE_REPORT_PATH){
            RabbitLog.d(TAG_REPORT, "undefine report path")
            return
        }

        val reportInfo = RabbitReportTransformCenter.createReportInfo(info, useTime)

        RabbitLog.d(TAG_REPORT, "report  ${reportInfo.type} data  use time : $useTime")

        RabbitStorage.save(reportInfo)

        dataEmitterTask.addPoint(reportInfo)

        startEmitterTask()
    }

    private fun startEmitterTask() {
        if (!dataEmitterTask.isRunning) {
            REQUEST_THREAD.execute {
                dataEmitterTask.emitterPoints()
            }
        }
    }

    private fun getDeviceInfo(application: Application): RabbitDeviceInfo {
        val roomInfo = RomUtils.getRomInfo()
        return RabbitDeviceInfo().apply {
            deviceName = DeviceUtils.getDeviceName()
            deviceId = DeviceUtils.getDeviceId(application)
            systemVersion = Build.VERSION.RELEASE
            memorySize = DeviceUtils.getMemorySize(application)
            rom = "${roomInfo.name}/${roomInfo.version}"
            appVersionCode = "${DeviceUtils.getAppVersionCode(application)}"
            isRoot = DeviceUtils.isDeviceRooted()
            supportAbi = RabbitUtils.getAbiList()
            manufacturer = Build.MANUFACTURER
        }
    }

    fun getDeviceInfoStr() = deviceInfoStr

}

fun addPointsToEmitterQueue(points: List<RabbitReportInfo>) {
    listModifierLock.lock()
    try {
        trackPointsList.addAll(points)
    } finally {
        listModifierLock.unlock()
    }
}

override fun onRequestSucceed() {
    var emitterWithError = false //发射逻辑出现错误
    listModifierLock.lock()
    try {
        emitterFailedCount = 0
        copiedList.forEach {
            val removeStatus = trackPointsList.remove(it)
            if (!removeStatus) { // 没有正确把点从队列中删除
                RabbitLog.d(
                    TAG_REPORT,
                    "remove emitter point status false!!  stop emitter"
                )
                emitterWithError = true
            }
            eventListener?.successEmitterPoint(it)
        }
    } finally {
        listModifierLock.unlock()
    }

    if (trackPointsList.isNotEmpty()) {
        if (!emitterWithError) {
            emitterTrackPoints()
        } else {
            RabbitLog.d(TAG_REPORT, "emitterWithError is true --> stop emitter!")
        }
    } else {
        RabbitLog.d(TAG_REPORT, "emitter all count ! EmitterTask Stop")
        isRunning = false
        eventListener?.pointQueueIsEmpty()
    }
}

internal class RabbitReportRequestManager {

    val EMITTER_CONNECT_TIMEOUT: Long = 15  //网络链接超时时间
    private val CONTENT_TYPE_JSON = "application/json; charset=utf-8"
    private val gson = Gson()

    //构建 ok http client
    private val okHttpClient = OkHttpClient.Builder()
        .connectTimeout(EMITTER_CONNECT_TIMEOUT, TimeUnit.SECONDS)
        .readTimeout(EMITTER_CONNECT_TIMEOUT, TimeUnit.SECONDS)
        .protocols(Collections.unmodifiableList(listOf(Protocol.HTTP_1_1)))
        .build()

    fun postTrackRequest(points: List<RabbitReportInfo>, requestListener: TrackRequestListener) {

        val trackUrl = RabbitReport.mConfig.reportPath

        RabbitLog.d(
            TAG_REPORT,
            "target url : $trackUrl 准备发射 ${points.size} 个点位到服务器！  current execute thread is : ${Thread.currentThread().name}  "
        )

        //构建请求
        val trackRequest = Request.Builder()
            .url(trackUrl)
            .post(buildPostBody(points))
            .build()

        //请求服务器
        try {
            val resp = okHttpClient.newCall(trackRequest).execute()
            val code = resp.code()
            resp.body()?.close()
            if (isSuccessful(code)) {
                RabbitLog.d(TAG_REPORT, "发射成功! 服务器返回码是： $code")
                requestListener.onRequestSucceed()
            } else {
                RabbitLog.d(TAG_REPORT, "track request failed, response code is $code")
                requestListener.onRequestFailed()
            }
        } catch (e: Exception) {
            RabbitLog.d(TAG_REPORT, "track request exception ${e.message}")
            requestListener.onRequestFailed()
        }
    }

    private fun buildPostBody(points: List<RabbitReportInfo>): RequestBody {

        val bodyArg = StringBuilder()

        points.forEachIndexed { index, pointInfo ->
            val strByteArr = gson.toJson(pointInfo).toByteArray()
            if (index != 0) {
                bodyArg.append("&")
                bodyArg.append(getBase64Encode(strByteArr))
            } else {
                bodyArg.append(getBase64Encode(strByteArr))
            }
        }

        val content = "$bodyArg"

        RabbitLog.d(TAG_REPORT, content)

        return RequestBody.create(
            MediaType.parse(CONTENT_TYPE_JSON),
            gson.toJson(InnerRequestBody(content))
        )
    }

    private fun getBase64Encode(byteArray: ByteArray): String {
        return Base64.encodeToString(byteArray, Base64.DEFAULT).trim()
    }

    private fun isSuccessful(code: Int): Boolean {
        return code in 200..299
    }

    interface TrackRequestListener {
        fun onRequestSucceed()
        fun onRequestFailed()
    }

    @Keep
    private class InnerRequestBody(val content: String)

}

internal object RabbitReportTransformCenter {

    fun createReportInfo(info: Any, appUseTime: Long): RabbitReportInfo {
        val reportInfo = RabbitReportInfo(
            getRealInfoStr(info),
            System.currentTimeMillis(),
            RabbitReport.getDeviceInfoStr(),
            getDataType(info),
            appUseTime
        )

        if (reportInfo.deviceInfoStr.isEmpty()) {
            reportInfo.deviceInfoStr = "{}"
        }

        return reportInfo
    }

    private fun getDataType(info: Any): String {
        return when (info) {
            is RabbitPageSpeedInfo -> "page_speed"
            is RabbitAppStartSpeedInfo -> "app_start"
            is RabbitBlockFrameInfo -> "block_info"
            is RabbitFPSInfo -> "fps_info"
            is RabbitExceptionInfo -> "exception_info"
            is RabbitSlowMethodInfo -> "slow_method"
            is RabbitAnrInfo -> "anr"
            else -> "undefine"
        }
    }

    private fun getRealInfoStr(info: Any): String {
        val gson = Gson()
        var infoStr = ""

        when (info) {
            is RabbitPageSpeedInfo, is RabbitAppStartSpeedInfo, is RabbitFPSInfo, is RabbitSlowMethodInfo -> {
                infoStr = gson.toJson(info)
            }

            is RabbitBlockFrameInfo -> {
                infoStr =
                    gson.toJson(
                        RabbitSimpleBlockInfo(
                            info.costTime,
                            info.pageName,
                            info.time,
                            info.blockIdentifier
                        )
                    )
            }

            is RabbitExceptionInfo -> {
                infoStr = gson.toJson(
                    RabbitSimpleExceptionInfo(
                        info.time,
                        info.exceptionName,
                        info.simpleMessage,
                        info.threadName,
                        info.pageName
                    )
                )
            }
        }
        return infoStr
    }

}

