class RabbitSlowMethodCallStackPage(context: Context) : RabbitBasePage(context) {

    override fun getLayoutResId() = R.layout.rabbit_page_call_stack

    init {
        setTitle("函数调用栈")
    }

    override fun setEntryParams(slowMethodInfo: Any) {

        if (slowMethodInfo !is RabbitSlowMethodUiInfo) return

        mCallStackThreadName.text = "${slowMethodInfo.className} -> ${slowMethodInfo.name}"

        val redMaxLine = 4
        val spannableStringBuilder = SpannableStringBuilder()
        spannableStringBuilder.append("长按复制 : ")

        var spanEndIndex = 0

        slowMethodInfo.callStack.split("\n").forEachIndexed { index, string ->
            spannableStringBuilder.append(string)
            spannableStringBuilder.append("\n")
            if (index < redMaxLine){
                spanEndIndex = spannableStringBuilder.length
            }
        }

        val foregroundColorSpan = ForegroundColorSpan(Color.RED)
        spannableStringBuilder.setSpan(foregroundColorSpan,0, spanEndIndex, Spanned.SPAN_INCLUSIVE_EXCLUSIVE)

        mCallStackTvStackStr.text = spannableStringBuilder

        mCallStackTvStackStr.setOnLongClickListener {
            RabbitUiUtils.copyStrToClipBoard(context, mCallStackTvStackStr.text.toString())
            true
        }
    }

}

class RabbitSlowMethodPkgListPage(context: Context) : RabbitBasePage(context) {

    private val mAdapter =SimpleRvAdapter<RabbitSlowMethodUiInfo>(context).apply {
        registerMapping(RabbitSlowMethodUiInfo::class.java,RabbitSlowMethodInfoView::class.java )
    }

    private val methodRv = RecyclerView(context).apply {
        layoutParams = LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT).apply {
            topMargin = ACTION_BAR_HEIGHT
        }
        layoutManager = LinearLayoutManager(context, LinearLayoutManager.VERTICAL, false)
        adapter = mAdapter
    }

    init {
        background = getDrawable(context, R.color.rabbit_white)
        addView(methodRv)
    }

    override fun setEntryParams(params: Any) {

        val pkgName = params as String

        setTitle(pkgName)

        val uiMethodInfo = LinkedHashMap<String, RabbitSlowMethodUiInfo>()

        RabbitStorage.getAll(
            RabbitSlowMethodInfo::class.java,
            loadResult = {

                it.sortedByDescending { it.costTimeMs }.filter { it.pkgName.contains(pkgName) }
                    .forEach {
                        val keyIden = "${it.className}_${it.methodName}"
                        var info = uiMethodInfo[keyIden]
                        if (info == null) {
                            info = RabbitSlowMethodUiInfo(
                                it.className,
                                it.methodName,
                                0,
                                0,
                                it.callStack
                            )
                            uiMethodInfo[keyIden] = info
                        }

                        info.count++
                        info.totalTime += it.costTimeMs
                    }

                mAdapter.data.addAll(uiMethodInfo.values)
                mAdapter.notifyDataSetChanged()
            })

    }

    override fun getLayoutResId() = INVALID_RES_ID

}

class RabbitSlowMethodPreviewPage(context: Context) : RabbitBasePage(context) {

    val colorList = listOf(
        Color.parseColor("#42a5f5"),
        Color.parseColor("#f06292"),
        Color.parseColor("#ce93d8"),
        Color.parseColor("#00e676"),
        Color.parseColor("#18ffff"),
        Color.parseColor("#ff80ab"),
        Color.parseColor("#66bb6a")
    )

    private val adapter = SimpleRvAdapter<RabbitSlowMethodGroupInfo>(context).apply {
        registerMapping(RabbitSlowMethodGroupInfo::class.java, RabbitSlowMethodGroupItemView::class.java)
    }

    override fun getLayoutResId() = R.layout.rabbit_page_slow_method_list

    init {

        background = getDrawable(context, R.color.rabbit_white)
        setTitle("慢函数")
        mRabbitSlowMethodChart.setDrawCenterText(false)
        mRabbitSlowMethodChart.setDrawEntryLabels(false)
        mRabbitSlowMethodChart.holeRadius = 0f
        mRabbitSlowMethodChart.transparentCircleRadius = 0f

        mRabbitSlowMethodListPageSRL.setOnRefreshListener {
            loadData()
        }

        mRabbitSlowMethodRv.layoutManager =
            LinearLayoutManager(context, LinearLayoutManager.VERTICAL, false)
        mRabbitSlowMethodRv.adapter = adapter

        loadData()

    }

    private fun loadData() {
        val methodGroupMap = HashMap<String, Int>()
        RabbitPluginConfig.methodMonitorPkgs.forEach {
            methodGroupMap[it] = 0
        }

        val methodCountMap = HashMap<String, Int>()

        RabbitStorage.getAll(RabbitSlowMethodInfo::class.java, loadResult = {

            if (it.isEmpty()) {
                showEmptyView()
                mRabbitSlowMethodListPageSRL.visibility = View.GONE
            } else {
                hideEmptyView()
                mRabbitSlowMethodListPageSRL.visibility = View.VISIBLE
            }

            mRabbitSlowMethodListPageSRL.isRefreshing = false

            it.forEach { trackMethod ->
                val methodName =
                    "${trackMethod.pkgName}${trackMethod.className}${trackMethod.methodName}"

                RabbitPluginConfig.methodMonitorPkgs.forEach { configMethodPkg ->
                    if (trackMethod.pkgName.contains(configMethodPkg)) {
                        methodGroupMap[configMethodPkg] = (methodGroupMap[configMethodPkg] ?: 0) + 1
                    }
                }

                methodCountMap[methodName] = (methodCountMap[methodName] ?: 0) + 1
            }

            val pieEntryList = ArrayList<PieEntry>()

            for (pkgInfo in methodGroupMap.entries) {
                pieEntryList.add(PieEntry(pkgInfo.value.toFloat(), pkgInfo.key))
            }

            mRabbitSlowMethodChart.data = PieData(PieDataSet(pieEntryList, "").apply {
                colors = colorList
                valueFormatter = PercentFormatter()
                setDrawValues(true)
            })
            mRabbitSlowMethodChart.invalidate()

            val groupInfos = methodGroupMap.map {
                RabbitSlowMethodGroupInfo(
                    it.key,
                    it.value
                )
            }
            for (methodCountInfo in methodCountMap.entries) {
                groupInfos.forEach { groupInfo ->
                    if (methodCountInfo.key.contains(groupInfo.pkgName)) {
                        groupInfo.methodCount = methodCountInfo.value
                    }
                }
            }

            adapter.data.clear()
            adapter.data.addAll(groupInfos.filter { it.methodCount > 0 && it.slowMethodRecord > 0 })
            adapter.notifyDataSetChanged()

        })
    }

}

