abstract class LinearGauge @JvmOverloads constructor(
        context: Context,
        attrs: AttributeSet? = null,
        defStyleAttr: Int = 0,
) : Gauge(context, attrs, defStyleAttr) {

    private val paint = Paint(Paint.ANTI_ALIAS_FLAG)
    /** to draw part of bitmap  */
    private val rect = Rect()
    private var foregroundBitmap: Bitmap = Bitmap.createBitmap(1, 1, Bitmap.Config.ARGB_8888)

    /**
     * horizontal or vertical direction .
     * change fill orientation,
     * this will change view width and height.
     */
    var orientation = Orientation.HORIZONTAL
        set(orientation) {
            field = orientation
            if (isAttachedToWindow) {
                requestLayout()
                invalidateGauge()
            }
        }

    init {
        initAttributeSet(context, attrs)
    }

    /**
     * update background and foreground bitmap,
     * this method called when change size, color, orientation...
     *
     *
     * must call [createBackgroundBitmapCanvas] and
     * [createForegroundBitmapCanvas] inside this method.
     *
     */
    protected abstract fun updateFrontAndBackBitmaps()

    private fun initAttributeSet(context: Context, attrs: AttributeSet?) {
        if (attrs == null)
            return
        val a = context.theme.obtainStyledAttributes(attrs, R.styleable.LinearGauge, 0, 0)

        val orientation = a.getInt(R.styleable.LinearGauge_sv_orientation, -1)
        if (orientation != -1)
            this.orientation = Orientation.values()[orientation]
        a.recycle()
    }

    override fun onSizeChanged(w: Int, h: Int, oldW: Int, oldH: Int) {
        super.onSizeChanged(w, h, oldW, oldH)

        updateBackgroundBitmap()
    }

    override fun updateBackgroundBitmap() {
        updateFrontAndBackBitmaps()
    }

    protected fun createForegroundBitmapCanvas(): Canvas {
        if (widthPa == 0 || heightPa == 0)
            return Canvas()
        foregroundBitmap = Bitmap.createBitmap(widthPa, heightPa, Bitmap.Config.ARGB_8888)
        return Canvas(foregroundBitmap)
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)

        if (this.orientation == Orientation.HORIZONTAL)
            rect.set(0, 0, (widthPa * getOffsetSpeed()).toInt(), heightPa)
        else
            rect.set(0, heightPa - (heightPa * getOffsetSpeed()).toInt(), widthPa, heightPa)

        canvas.translate(padding.toFloat(), padding.toFloat())
        canvas.drawBitmap(foregroundBitmap, rect, rect, paint)
        canvas.translate((-padding).toFloat(), (-padding).toFloat())

        drawSpeedUnitText(canvas)
    }

    enum class Orientation {
        HORIZONTAL, VERTICAL
    }
}

var orientation = Orientation.HORIZONTAL
    set(orientation) {
        field = orientation
        if (isAttachedToWindow) {
            requestLayout()
            invalidateGauge()
        }
    }

var centerCircleRadius = dpTOpx(12f)
    set(centerCircleRadius) {
        field = centerCircleRadius
        if (isAttachedToWindow)
            invalidate()
    }

var isWithPointer: Boolean
    get() = withPointer
    set(withPointer) {
        this.withPointer = withPointer
        if (isAttachedToWindow)
             invalidate()
    }

open class ProgressiveGauge @JvmOverloads constructor(
        context: Context,
        attrs: AttributeSet? = null,
        defStyleAttr: Int = 0,
) : LinearGauge(context, attrs, defStyleAttr) {

    /** the shape  */
    private val path = Path()

    private val frontPaint = Paint(Paint.ANTI_ALIAS_FLAG)
    private val backPaint = Paint(Paint.ANTI_ALIAS_FLAG)

    /**
     * change the color of progress.
     * @return foreground progress color.
     */
    var speedometerColor: Int
        get() = frontPaint.color
        set(speedometerColor) {
            frontPaint.color = speedometerColor
            invalidateGauge()
        }

    /**
     * change the color of background progress.
     * @return background progress color.
     */
    var speedometerBackColor: Int
        get() = backPaint.color
        set(speedometerBackColor) {
            backPaint.color = speedometerBackColor
            invalidateGauge()
        }

    init {
        init()
        initAttributeSet(context, attrs)
    }

    override fun defaultGaugeValues() {
        super.speedTextPosition = Position.CENTER
        super.unitUnderSpeedText = true
    }

    private fun init() {
        frontPaint.color = 0xFF00FFFF.toInt()
        backPaint.color = 0xffd6d7d7.toInt()
    }

    private fun initAttributeSet(context: Context, attrs: AttributeSet?) {
        if (attrs == null)
            return
        val a = context.theme.obtainStyledAttributes(attrs, R.styleable.LinearGauge, 0, 0)

        frontPaint.color = a.getColor(R.styleable.LinearGauge_sv_speedometerColor, frontPaint.color)
        backPaint.color = a.getColor(R.styleable.LinearGauge_sv_speedometerBackColor, backPaint.color)
        a.recycle()
    }

    override fun onMeasure(widthMeasureSpec: Int, heightMeasureSpec: Int) {
        super.onMeasure(widthMeasureSpec, heightMeasureSpec)
        val w = measuredWidth
        val h = measuredHeight
        if (orientation === Orientation.HORIZONTAL) {
            if (h > w / 2)
                setMeasuredDimension(w, w / 2)
            else
                setMeasuredDimension(h * 2, h)
        } else {
            if (w > h / 2)
                setMeasuredDimension(h / 2, h)
            else
                setMeasuredDimension(w, w * 2)
        }
    }

    override fun updateFrontAndBackBitmaps() {
        updateOrientation()
        val canvasBack = createBackgroundBitmapCanvas()
        val canvasFront = createForegroundBitmapCanvas()

        canvasBack.translate(padding.toFloat(), padding.toFloat())
        canvasBack.drawPath(path, backPaint)

        canvasFront.drawPath(path, frontPaint)
    }

    private fun updateOrientation() {
        if (orientation === Orientation.HORIZONTAL)
            updateHorizontalPath()
        else
            updateVerticalPath()
    }

    /**
     * to reset [path] for horizontal shape.
     */
    protected fun updateHorizontalPath() {
        path.reset()
        path.moveTo(0f, heightPa.toFloat())
        path.lineTo(0f, heightPa - heightPa * .1f)
        path.quadTo(widthPa * .75f, heightPa * .75f, widthPa.toFloat(), 0f)
        path.lineTo(widthPa.toFloat(), heightPa.toFloat())
        path.lineTo(0f, heightPa.toFloat())
    }

    /**
     * to reset [path] for vertical shape.
     */
    protected fun updateVerticalPath() {
        path.reset()
        path.moveTo(0f, heightPa.toFloat())
        path.lineTo(widthPa * .1f, heightPa.toFloat())
        path.quadTo(widthPa * .25f, heightPa * .25f, widthPa.toFloat(), 0f)
        path.lineTo(0f, 0f)
        path.lineTo(0f, heightPa.toFloat())
    }
}

var speedometerColor: Int
    get() = frontPaint.color
    set(speedometerColor) {
        frontPaint.color = speedometerColor
        invalidateGauge()
    }

var speedometerBackColor: Int
    get() = backPaint.color
    set(speedometerBackColor) {
        backPaint.color = speedometerBackColor
        invalidateGauge()
    }

//    override var indicatorColor: Int
//        @Deprecated("")
//        get() = 0
//        @Deprecated("")
//        set(indicatorColor) {
//        }

    init {
        init()
        initAttributeSet(context, attrs)
    }

    override fun defaultGaugeValues() {
        super.textColor = 0xFFFFFFFF.toInt()
    }

    override fun defaultSpeedometerValues() {
        super.backgroundCircleColor = 0xff212121.toInt()
        super.markColor = 0xFF000000.toInt()
    }

    private fun initAttributeSet(context: Context, attrs: AttributeSet?) {
        if (attrs == null)
            return
        val a = context.theme.obtainStyledAttributes(attrs, R.styleable.RaySpeedometer, 0, 0)

        rayPaint.color = a.getColor(R.styleable.RaySpeedometer_sv_rayColor, rayPaint.color)
        val degreeBetweenMark = a.getInt(R.styleable.RaySpeedometer_sv_degreeBetweenMark, this.degreeBetweenMark)
        val rayMarkWidth = a.getDimension(R.styleable.RaySpeedometer_sv_rayMarkWidth, rayMarkPaint.strokeWidth)
        rayMarkPaint.strokeWidth = rayMarkWidth
        activeMarkPaint.strokeWidth = rayMarkWidth
        speedBackgroundPaint.color = a.getColor(R.styleable.RaySpeedometer_sv_speedBackgroundColor, speedBackgroundPaint.color)
        withEffects = a.getBoolean(R.styleable.RaySpeedometer_sv_withEffects, withEffects)
        a.recycle()
        isWithEffects = withEffects
        if (degreeBetweenMark in 1..20)
            this.degreeBetweenMark = degreeBetweenMark
    }

    private fun init() {
        rayMarkPaint.style = Paint.Style.STROKE
        rayMarkPaint.strokeWidth = dpTOpx(3f)
        activeMarkPaint.style = Paint.Style.STROKE
        activeMarkPaint.strokeWidth = dpTOpx(3f)
        rayPaint.style = Paint.Style.STROKE
        rayPaint.strokeWidth = dpTOpx(1.8f)
        rayPaint.color = 0xFFFFFFFF.toInt()
        speedBackgroundPaint.color = 0xFFFFFFFF.toInt()

        if (Build.VERSION.SDK_INT >= 11)
            setLayerType(LAYER_TYPE_SOFTWARE, null)
        isWithEffects = withEffects
    }


    override fun onSizeChanged(w: Int, h: Int, oldW: Int, oldH: Int) {
        super.onSizeChanged(w, h, oldW, oldH)

        updateMarkPath()
        updateBackgroundBitmap()
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)

        canvas.save()
        canvas.rotate(getStartDegree() + 90f, size * .5f, size * .5f)
        var i = getStartDegree()
        while (i < getEndDegree()) {
            if (degree <= i) {
                rayMarkPaint.color = markColor
                canvas.drawPath(markPath, rayMarkPaint)
                canvas.rotate(degreeBetweenMark.toFloat(), size * .5f, size * .5f)
                i += degreeBetweenMark
                continue
            }
            if (currentSection != null)
                activeMarkPaint.color = currentSection!!.color
            else
                activeMarkPaint.color = 0 // transparent color
            canvas.drawPath(markPath, activeMarkPaint)
            canvas.rotate(degreeBetweenMark.toFloat(), size * .5f, size / 2f)
            i += degreeBetweenMark
        }
        canvas.restore()

        val speedBackgroundRect = getSpeedUnitTextBounds()
        speedBackgroundRect.left -= 2f
        speedBackgroundRect.right += 2f
        speedBackgroundRect.bottom += 2f
        canvas.drawRect(speedBackgroundRect, speedBackgroundPaint)

        drawSpeedUnitText(canvas)
        drawIndicator(canvas)
        drawNotes(canvas)
    }

    override fun updateBackgroundBitmap() {
        val c = createBackgroundBitmapCanvas()

        updateMarkPath()

        ray1Path.reset()
        ray1Path.moveTo(size / 2f, size / 2f)
        ray1Path.lineTo(size / 2f, sizePa / 3.2f + padding)
        ray1Path.moveTo(size / 2f, sizePa / 3.2f + padding)
        ray1Path.lineTo(size / 2.2f, sizePa / 3f + padding)
        ray1Path.moveTo(size / 2.2f, sizePa / 3f + padding)
        ray1Path.lineTo(size / 2.1f, sizePa / 4.5f + padding)

        ray2Path.reset()
        ray2Path.moveTo(size / 2f, size / 2f)
        ray2Path.lineTo(size / 2f, sizePa / 3.2f + padding)
        ray2Path.moveTo(size / 2f, sizePa / 3.2f + padding)
        ray2Path.lineTo(size / 2.2f, sizePa / 3.8f + padding)
        ray2Path.moveTo(size / 2f, sizePa / 3.2f + padding)
        ray2Path.lineTo(size / 1.8f, sizePa / 3.8f + padding)

        c.save()
        for (i in 0..5) {
            c.rotate(58f, size * .5f, size * .5f)
            if (i % 2 == 0)
                c.drawPath(ray1Path, rayPaint)
            else
                c.drawPath(ray2Path, rayPaint)
        }
        c.restore()

        drawMarks(c)

        if (tickNumber > 0)
            drawTicks(c)
        else
            drawDefMinMaxSpeedPosition(c)
    }

    private fun updateMarkPath() {
        markPath.reset()
        markPath.moveTo(size * .5f, padding.toFloat())
        markPath.lineTo(size * .5f, speedometerWidth + padding)
    }

    override fun setIndicator(indicator: Indicator.Indicators) {
        super.setIndicator(indicator)
        this.indicator.withEffects(withEffects)
    }

    fun getDegreeBetweenMark(): Int {
        return degreeBetweenMark
    }

    /**
     * The spacing between the marks
     *
     * it should be between (0-20] ,else well be ignore.
     *
     * @param degreeBetweenMark degree between two marks.
     */
    fun setDegreeBetweenMark(degreeBetweenMark: Int) {
        if (degreeBetweenMark <= 0 || degreeBetweenMark > 20)
            return
        this.degreeBetweenMark = degreeBetweenMark
        if (isAttachedToWindow)
            invalidate()
    }
}

fun setDegreeBetweenMark(degreeBetweenMark: Int) {
    if (degreeBetweenMark <= 0 || degreeBetweenMark > 20)
        return
    this.degreeBetweenMark = degreeBetweenMark
    if (isAttachedToWindow)
        invalidate()
}

