open class TubeSpeedometer @JvmOverloads constructor(
        context: Context,
        attrs: AttributeSet? = null,
        defStyleAttr: Int = 0,
) : Speedometer(context, attrs, defStyleAttr) {

    private val tubePaint = Paint(Paint.ANTI_ALIAS_FLAG)
    private val tubeBacPaint = Paint(Paint.ANTI_ALIAS_FLAG)
    private val speedometerRect = RectF()


    var speedometerBackColor: Int
        get() = tubeBacPaint.color
        set(speedometerBackColor) {
            tubeBacPaint.color = speedometerBackColor
            invalidateGauge()
        }

    init {
        init()
        initAttributeSet(context, attrs)
    }

    override fun defaultGaugeValues() {
        super.speedometerWidth = dpTOpx(40f)
        sections[0].color = 0xff00BCD4.toInt()
        sections[1].color = 0xffFFC107.toInt()
        sections[2].color = 0xffF44336.toInt()
    }

    override fun defaultSpeedometerValues() {
        super.backgroundCircleColor = 0
    }

    private fun init() {
        tubePaint.style = Paint.Style.STROKE
        tubeBacPaint.style = Paint.Style.STROKE
        tubeBacPaint.color = 0xff757575.toInt()

        if (Build.VERSION.SDK_INT >= 11)
            setLayerType(LAYER_TYPE_SOFTWARE, null)
    }

    private fun initAttributeSet(context: Context, attrs: AttributeSet?) {
        if (attrs == null)
            return
        val a = context.theme.obtainStyledAttributes(attrs, R.styleable.TubeSpeedometer, 0, 0)

        tubeBacPaint.color = a.getColor(R.styleable.TubeSpeedometer_sv_speedometerBackColor, tubeBacPaint.color)
        a.recycle()
    }

    override fun onSizeChanged(w: Int, h: Int, oldW: Int, oldH: Int) {
        super.onSizeChanged(w, h, oldW, oldH)

        updateBackgroundBitmap()
    }

    private fun initDraw() {
        tubePaint.strokeWidth = speedometerWidth
        if (currentSection != null)
            tubePaint.color = currentSection!!.color
        else
            tubePaint.color = 0 // transparent color
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)
        initDraw()

        val sweepAngle = (getEndDegree() - getStartDegree()) * getOffsetSpeed()
        canvas.drawArc(speedometerRect, getStartDegree().toFloat(), sweepAngle, false, tubePaint)

        drawSpeedUnitText(canvas)
        drawIndicator(canvas)
        drawNotes(canvas)
    }

    override fun updateBackgroundBitmap() {
        val c = createBackgroundBitmapCanvas()
        tubeBacPaint.strokeWidth = speedometerWidth

        val risk = speedometerWidth * .5f + padding
        speedometerRect.set(risk, risk, size - risk, size - risk)

        c.drawArc(speedometerRect, getStartDegree().toFloat(), (getEndDegree() - getStartDegree()).toFloat(), false, tubeBacPaint)

        drawMarks(c)

        if (tickNumber > 0)
            drawTicks(c)
        else
            drawDefMinMaxSpeedPosition(c)
    }
}

@Suppress("MemberVisibilityCanBePrivate")
class Section @JvmOverloads constructor(
        startOffset: Float,
        endOffset: Float,
        color: Int,
        width: Float = 0f,
        style: Style = Style.BUTT,
): Parcelable {

    private var gauge: Gauge? = null

    var width: Float = width
        set(value) {
            field = value
            gauge?.invalidateGauge()
        }
    var padding: Float = 0f
        set(value) {
            field = value
            gauge?.invalidateGauge()
        }

    constructor(section: Section) : this(section.startOffset, section.endOffset, section.color, section.width, section.style) {
        padding = section.padding
    }

    constructor(parcel: Parcel) : this(parcel.readFloat(), parcel.readFloat(), parcel.readInt(), parcel.readFloat(), parcel.readSerializable() as Style) {
        padding = parcel.readFloat()
    }

    private var _startOffset: Float = startOffset
    private var _endOffset: Float = endOffset

    /**
     * start percent value to section range [0, 1]
     * 0 means 0%
     * 1 means 100%
     * @throws IllegalArgumentException if [startOffset] is invalid.
     */
    var startOffset
        get() = _startOffset
        set(value) = setStartEndOffset(value, endOffset)

    /**
     * end percent value to section range [0, 1]
     * 0 means 0%
     * 1 means 100%
     * @throws IllegalArgumentException if [endOffset] is invalid.
     */
    var endOffset
        get() = _endOffset
        set(value) = setStartEndOffset(startOffset, value)

    /**
     * section color, for speedometer family (not for all speedometer).
     */
    var color: Int = color
        set(value) {
            field = value
            gauge?.invalidateGauge()
        }

    /**
     * style to ths section.
     */
    var style: Style = style
        set(value) {
            field = value
            gauge?.invalidateGauge()
        }

    /**
     * change both offsets at once.
     * @param startOffset start of the section [0, 1)
     * @param endOffset end of the section (0, 1]
     * @throws IllegalArgumentException if [startOffset] or [endOffset] are invalid.
     */
    fun setStartEndOffset(startOffset: Float, endOffset: Float) {
        _startOffset = startOffset
        _endOffset = endOffset
        gauge?.checkSection(this)
        gauge?.checkSectionChange()
        gauge?.invalidateGauge()
    }

    /**
     * add gauge to this section to attache to, **a section can attache to one gauge**.
     */
    internal fun inGauge(gauge: Gauge): Section {
        require(this.gauge == null) { "This instance of Section is already attached to a Gauge." }
        this.gauge = gauge
        return this
    }

    /**
     * remove gauge that this section attached to,
     * to avoid call `invalidate()` from this section.
     */
    internal fun clearGauge() { gauge = null }

    override fun writeToParcel(parcel: Parcel, flags: Int) {
        parcel.writeFloat(startOffset)
        parcel.writeFloat(endOffset)
        parcel.writeInt(color)
        parcel.writeFloat(width)
        parcel.writeSerializable(style.ordinal)
        parcel.writeFloat(padding)
    }

    override fun describeContents(): Int {
        return 0
    }

    companion object CREATOR : Parcelable.Creator<Section> {

        override fun createFromParcel(parcel: Parcel): Section {
            return Section(parcel)
        }

        override fun newArray(size: Int): Array<Section?> {
            return arrayOfNulls(size)
        }
    }

}

var color: Int = color
    set(value) {
        field = value
        gauge?.invalidateGauge()
    }

var style: Style = style
    set(value) {
        field = value
        gauge?.invalidateGauge()
    }

internal fun inGauge(gauge: Gauge): Section {
    require(this.gauge == null) { "This instance of Section is already attached to a Gauge." }
    this.gauge = gauge
    return this
}

