    override fun draw(canvas: Canvas) {
        canvas.drawPath(indicatorPath, indicatorPaint)
    }

    override fun updateIndicator() {
        indicatorPath.reset()
        indicatorPath.moveTo(getCenterX(), getViewSize() / 5f + speedometer!!.padding)
        bottomY = getViewSize() * 3f / 5f + speedometer!!.padding
        indicatorPath.lineTo(getCenterX() - width, bottomY)
        indicatorPath.lineTo(getCenterX() + width, bottomY)
        val rectF = RectF(getCenterX() - width, bottomY - width, getCenterX() + width, bottomY + width)
        indicatorPath.addArc(rectF, 0f, 180f)

        indicatorPaint.color = color
    }

    override fun setWithEffects(withEffects: Boolean) {
        if (withEffects && !speedometer!!.isInEditMode) {
            indicatorPaint.maskFilter = BlurMaskFilter(15f, BlurMaskFilter.Blur.SOLID)
        } else {
            indicatorPaint.maskFilter = null
        }
    }
}

class SpindleIndicator(context: Context) : Indicator<SpindleIndicator>(context) {

    private val indicatorPath = Path()

    init {
        width = dpTOpx(16f)
    }

    override fun getTop(): Float {
        return getViewSize() * .18f + speedometer!!.padding
    }

    override fun draw(canvas: Canvas) {
        canvas.drawPath(indicatorPath, indicatorPaint)
    }

    override fun updateIndicator() {
        indicatorPath.reset()
        indicatorPath.moveTo(getCenterX(), getCenterY())
        indicatorPath.quadTo(getCenterX() - width, getViewSize() * .34f + speedometer!!.padding, getCenterX(), getViewSize() * .18f + speedometer!!.padding)
        indicatorPath.quadTo(getCenterX() + width, getViewSize() * .34f + speedometer!!.padding, getCenterX(), getCenterY())

        indicatorPaint.color = color
    }

    override fun setWithEffects(withEffects: Boolean) {
        if (withEffects && !speedometer!!.isInEditMode) {
            indicatorPaint.maskFilter = BlurMaskFilter(15f, BlurMaskFilter.Blur.SOLID)
        } else {
            indicatorPaint.maskFilter = null
        }
    }
}

class TriangleIndicator(context: Context) : Indicator<TriangleIndicator>(context) {

    private var indicatorPath = Path()
    private var indicatorTop = 0f

    init {
        width = dpTOpx(25f)
    }

    override fun getTop(): Float {
        return indicatorTop
    }

    override fun getBottom(): Float {
        return indicatorTop + width
    }

    override fun draw(canvas: Canvas) {
        canvas.drawPath(indicatorPath, indicatorPaint)
    }

    override fun updateIndicator() {
        indicatorPath = Path()
        indicatorTop = speedometer!!.padding.toFloat() + speedometer!!.speedometerWidth + dpTOpx(5f)
        indicatorPath.moveTo(getCenterX(), indicatorTop)
        indicatorPath.lineTo(getCenterX() - width, indicatorTop + width)
        indicatorPath.lineTo(getCenterX() + width, indicatorTop + width)
        indicatorPath.moveTo(0f, 0f)

        val endColor = Color.argb(0, Color.red(color), Color.green(color), Color.blue(color))
        val linearGradient = LinearGradient(getCenterX(), indicatorTop, getCenterX(), indicatorTop + width, color, endColor, Shader.TileMode.CLAMP)
        indicatorPaint.shader = linearGradient
    }

    override fun setWithEffects(withEffects: Boolean) {
        if (withEffects && !speedometer!!.isInEditMode) {
            indicatorPaint.maskFilter = BlurMaskFilter(15f, BlurMaskFilter.Blur.SOLID)
        } else {
            indicatorPaint.maskFilter = null
        }
    }
}

class ImageNote
/**
 * @param context you can use `getApplicationContext()` method.
 * @param image to display.
 * @param width set custom width.
 * @param height set custom height.
 * @throws IllegalArgumentException if `width <= 0 OR height <= 0`.
 */
@JvmOverloads constructor(context: Context, private val image: Bitmap, private val width: Int = image.width, private val height: Int = image.height) : Note<ImageNote>(context) {
    private val imageRect = RectF()
    private val notePaint = Paint(Paint.ANTI_ALIAS_FLAG)

    /**
     * @param context you can use `getApplicationContext()` method.
     * @param resource the image id.
     */
    constructor(context: Context, resource: Int) : this(context, BitmapFactory.decodeResource(context.resources, resource))

    /**
     * @param context you can use `getApplicationContext()` method.
     * @param resource the image id.
     * @param width set custom width.
     * @param height set custom height.
     * @throws IllegalArgumentException if `width <= 0 OR height <= 0`.
     */
    constructor(context: Context, resource: Int, width: Int, height: Int) : this(context, BitmapFactory.decodeResource(context.resources, resource), width, height)

    init {
        require(width > 0) { "width must be bigger than 0" }
        require(height > 0) { "height must be bigger than 0" }
    }

    override fun build(viewWidth: Int) {
        noticeContainsSizeChange(this.width, this.height)
    }

    override fun drawContains(canvas: Canvas, leftX: Float, topY: Float) {
        imageRect.set(leftX, topY, leftX + width, topY + height)
        canvas.drawBitmap(image, null, imageRect, notePaint)
    }
}

protected fun noticeContainsSizeChange(containsW: Int, containsH: Int) {
    this.containsW = containsW
    this.containsH = containsH
    if (align == Align.Top || align == Align.Bottom) {
        this.noteW = (containsW.toFloat() + paddingLeft + paddingRight).toInt()
        this.noteH = (containsH.toFloat() + paddingTop + paddingBottom + triangleHeight).toInt()
    } else {
        this.noteW = (containsW.toFloat() + paddingLeft + paddingRight + triangleHeight).toInt()
        this.noteH = (containsH.toFloat() + paddingTop + paddingBottom).toInt()
    }
    updateBackgroundBitmap()
}

private fun updateBackgroundBitmap() {
    if (noteW > 0 && noteH > 0) {
        backgroundBitmap = Bitmap.createBitmap(noteW, noteH, Bitmap.Config.ARGB_8888)
        val c = Canvas(backgroundBitmap)
        when (align) {
            Align.Left -> bitmapLeft(c)
            Align.Top -> bitmapTop(c)
            Align.Right -> bitmapRight(c)
            Align.Bottom -> bitmapBottom(c)
        }
    }
}

