fun <T> Flow<T>.asObservable(): Observable<T> =
    observable { emitter ->
        launchCoroutine(
            setDisposable = emitter::setDisposable,
            onSuccess = { emitter.onComplete() },
            onError = emitter::onError
        ) {
            collect { emitter.onNext(it) }
        }
    }

interface CompleteCallback {

    /**
     * Notifies the host (typically an [Observer]) about completion
     */
    fun onComplete()
}

interface Emitter {

    val isDisposed: Boolean

    /**
     * Sets a [Disposable] on this emitter, any existing [Disposable]
     * will be replaced and disposed.
     *
     * @param disposable the [Disposable]
     */
    fun setDisposable(disposable: Disposable?)
}

interface ErrorCallback {

    /**
     * Called when there is an exception occurred
     *
     * @param error the exception
     */
    fun onError(error: Throwable)
}

interface Observer {

    /**
     * Provides the [Observer] with a [Disposable]. This method must be called before any other methods.
     *
     * @param disposable the [Disposable] that can be used to cancel the source
     */
    fun onSubscribe(disposable: Disposable)
}

interface Source<in T : Observer> {

    /**
     * Subscribes the specified [Observer] to this [Source]
     *
     * @param observer the [Observer] to be subscribed
     */
    fun subscribe(observer: T)
}

interface SuccessCallback<in T> {

    /**
     * Notifies the host (typically an [Observer]) about completion with a value
     */
    fun onSuccess(value: T)
}

fun interface ValueCallback<in T> {

    /**
     * Delivers values to the host (typically an [Observer])
     */
    fun onNext(value: T)
}

fun Iterable<Completable>.amb(): Completable =
    completable { emitter ->
        val sources = toList()

        if (sources.isEmpty()) {
            emitter.onComplete()
            return@completable
        }

        val disposableObserver =
            object : CompositeDisposableObserver(), CompletableObserver {
                private val isFinished = AtomicBoolean()

                override fun onComplete() {
                    race(emitter::onComplete)
                }

                override fun onError(error: Throwable) {
                    race { emitter.onError(error) }
                }

                private inline fun race(block: () -> Unit) {
                    if (isFinished.compareAndSet(false, true)) {
                        block()
                    }
                }
            }

        emitter.setDisposable(disposableObserver)

        sources.forEach { it.subscribe(disposableObserver) }
    }

