fun <T> Observable<T>.reduce(reducer: (a: T, b: T) -> T): Maybe<T> =
    maybe { emitter ->
        subscribe(
            object : ObservableObserver<T>, ErrorCallback by emitter {
                private var value: Any? = Uninitialized

                override fun onSubscribe(disposable: Disposable) {
                    emitter.setDisposable(disposable)
                }

                override fun onComplete() {
                    getCurrentValue(onExists = emitter::onSuccess, onNotExists = emitter::onComplete)
                }

                override fun onNext(value: T) {
                    getCurrentValue(
                        onExists = { currentValue ->
                            emitter.tryCatch {
                                this.value = reducer(currentValue, value)
                            }
                        },
                        onNotExists = { this.value = value }
                    )
                }

                private inline fun getCurrentValue(onExists: (T) -> Unit, onNotExists: () -> Unit) {
                    val prevValue: Any? = value
                    if (prevValue === Uninitialized) {
                        onNotExists()
                    } else {
                        @Suppress("UNCHECKED_CAST")
                        onExists(prevValue as T)
                    }
                }
            }
        )
    }

fun <T> ConnectableObservable<T>.refCount(subscriberCount: Int = 1): Observable<T> {
    require(subscriberCount > 0)

    var subscribeCount = 0
    val lock = Lock()
    val connectionDisposable = SerialDisposable()

    return observable { emitter ->
        val disposables = CompositeDisposable()
        emitter.setDisposable(disposables)

        val shouldConnect = lock.synchronized { ++subscribeCount == subscriberCount }

        this@refCount.subscribe(
            object : ObservableObserver<T>, ObservableCallbacks<T> by emitter {
                override fun onSubscribe(disposable: Disposable) {
                    disposables += disposable
                }
            }
        )

        if (shouldConnect) {
            this@refCount.connect(connectionDisposable::set)
        }

        disposables +=
            Disposable {
                lock.synchronized {
                    if (--subscribeCount == 0) {
                        connectionDisposable.set(null)
                    }
                }
            }
    }
}

fun <T> Observable<T>.repeat(times: Long = Long.MAX_VALUE): Observable<T> {
    require(times >= 0L) { "Number of times must not be negative" }

    if (times == 0L) {
        return observableOfEmpty()
    }

    return observable { emitter ->
        val observer =
            object : ObservableObserver<T>, ValueCallback<T> by emitter, ErrorCallback by emitter {
                private var counter = times

                // Prevents recursive subscriptions
                private val serializer =
                    serializer<Unit> {
                        subscribe(this)
                        true
                    }

                override fun onSubscribe(disposable: Disposable) {
                    emitter.setDisposable(disposable)
                }

                override fun onComplete() {
                    if ((counter == Long.MAX_VALUE) || (--counter > 0)) {
                        if (!emitter.isDisposed) {
                            subscribeToUpstream()
                        }
                    } else {
                        emitter.onComplete()
                    }
                }

                fun subscribeToUpstream() {
                    serializer.accept(Unit)
                }
            }

        observer.subscribeToUpstream()
    }
}

fun <T> Observable<T>.repeatUntil(predicate: () -> Boolean): Observable<T> =
    observable { emitter ->
        val observer =
            object : ObservableObserver<T>, ValueCallback<T> by emitter, ErrorCallback by emitter {
                private var recursiveGuard = 0

                override fun onSubscribe(disposable: Disposable) {
                    emitter.setDisposable(disposable)
                }

                override fun onComplete() {
                    emitter.tryCatch(
                        block = predicate,
                        onSuccess = {
                            if (!emitter.isDisposed) {
                                if (it) {
                                    emitter.onComplete()
                                } else {
                                    subscribeToUpstream()
                                }
                            }
                        }
                    )
                }

                fun subscribeToUpstream() {
                    // Prevents recursive subscriptions
                    if (++recursiveGuard == 1) {
                        do {
                            subscribe(this)
                        } while (--recursiveGuard > 0)
                    }
                }
            }

        observer.subscribeToUpstream()
    }

fun <T> Observable<T>.repeatWhen(handler: (attempt: Int) -> Maybe<*>): Observable<T> =
    observable { emitter ->
        val observer =
            object : ObservableObserver<T>, ValueCallback<T> by emitter, ErrorCallback by emitter {
                private var repeatNumber = 0
                private var recursiveGuard = 0

                private val repeatObserver: MaybeObserver<Any?> =
                    object : MaybeObserver<Any?>, Observer by this, CompletableCallbacks by emitter {
                        override fun onSuccess(value: Any?) {
                            emitter.tryCatch(block = ::subscribeToUpstream)
                        }
                    }

                override fun onSubscribe(disposable: Disposable) {
                    emitter.setDisposable(disposable)
                }

                override fun onComplete() {
                    emitter.tryCatch {
                        repeatNumber++
                        handler(repeatNumber).subscribe(repeatObserver)
                    }
                }

                fun subscribeToUpstream() {
                    // Prevents recursive subscriptions
                    if (++recursiveGuard == 1) {
                        do {
                            subscribe(this)
                        } while (--recursiveGuard > 0)
                    }
                }
            }

        observer.subscribeToUpstream()
    }

