                    serialDisposable.set(disposable)
                }

                override fun onNext(value: T) {
                    emitter.onNext(value)

                    emitter.tryCatch(block = { predicate(value) }) {
                        if (it) {
                            emitter.onComplete()
                        }
                    }
                }
            }
        )
    }

fun <T> Observable<T>.takeWhile(predicate: (T) -> Boolean): Observable<T> =
    observable { emitter ->
        subscribe(
            object : ObservableObserver<T>, CompletableCallbacks by emitter {
                override fun onSubscribe(disposable: Disposable) {
                    emitter.setDisposable(disposable)
                }

                override fun onNext(value: T) {
                    emitter.tryCatch(block = { predicate(value) }) {
                        if (it) {
                            emitter.onNext(value)
                        } else {
                            emitter.onComplete()
                        }
                    }
                }
            }
        )
    }

fun <T> Observable<T>.throttle(window: Duration, scheduler: Scheduler = computationScheduler): Observable<T> {
    if (!window.isPositive()) {
        return this
    }

    return observable { emitter ->
        subscribe(
            object : CompositeDisposableObserver(), ObservableObserver<T>, ObservableCallbacks<T> by emitter {
                private val executor = scheduler.newExecutor().addTo(this)
                private val gate = AtomicBoolean()

                init {
                    emitter.setDisposable(this)
                }

                override fun onNext(value: T) {
                    if (gate.compareAndSet(false, true)) {
                        emitter.onNext(value)
                        executor.submit(delay = window) { gate.value = false }
                    }
                }
            }
        )
    }
}

fun <T> Observable<T>.throttleLatest(timeout: Duration, scheduler: Scheduler, emitLast: Boolean = false): Observable<T> {
    val timeoutTimer = completableTimer(timeout, scheduler)

    return throttleLatest(timeout = { timeoutTimer }, emitLast = emitLast)
}

fun <T> Observable<T>.timeout(timeout: Duration, scheduler: Scheduler, other: Observable<T>? = null): Observable<T> =
    observable { emitter ->
        val onTimeout: () -> Unit =
            {
                if (other != null) {
                    emitter.setDisposable(null)
                    other.subscribe(
                        object : ObservableObserver<T>, ObservableCallbacks<T> by emitter {
                            override fun onSubscribe(disposable: Disposable) {
                                emitter.setDisposable(disposable)
                            }
                        }
                    )
                } else {
                    emitter.onError(TimeoutException())
                }
            }

        val upstreamObserver =
            object : CompositeDisposableObserver(), ObservableObserver<T>, CompletableCallbacks by emitter {
                private val executor = scheduler.newExecutor().addTo(this)

                override fun onNext(value: T) {
                    executor.cancel()
                    emitter.onNext(value)
                    startTimeout()
                }

                fun startTimeout() {
                    executor.submit(delay = timeout, task = onTimeout)
                }
            }

        emitter.setDisposable(upstreamObserver)
        upstreamObserver.startTimeout()

        subscribe(upstreamObserver)
    }

fun observableTimer(delay: Duration, scheduler: Scheduler): Observable<Duration> =
    observable { emitter ->
        val executor = scheduler.newExecutor()
        emitter.setDisposable(executor)
        executor.submit(delay = delay) {
            emitter.onNext(delay)
            emitter.onComplete()
        }
    }

fun <T, R> observableUsing(
    resourceSupplier: () -> R,
    resourceCleanup: (resource: R) -> Unit,
    eager: Boolean = true,
    sourceSupplier: (resource: R) -> Observable<T>,
): Observable<T> =
    observableDefer {
        val resource = resourceSupplier()

        sourceSupplier(resource).run {
            if (eager) {
                doOnBeforeFinally { resourceCleanup(resource) }
            } else {
                doOnAfterFinally { resourceCleanup(resource) }
            }
        }
    }

