fun <T> Observable<T>.window(
    span: Duration,
    scheduler: Scheduler,
    limit: Long = Long.MAX_VALUE,
    restartOnLimit: Boolean = false
): Observable<Observable<T>> {
    require(span.isPositive()) { "Span duration must by positive" }

    return window(
        boundaries = singleOf(Unit).delay(span, scheduler).repeat(),
        limit = limit,
        restartOnLimit = restartOnLimit
    )
}

fun <T> Observable<T>.window(
    boundaries: Observable<*>,
    limit: Long = Long.MAX_VALUE,
    restartOnLimit: Boolean = false
): Observable<Observable<T>> {
    require(limit > 0) { "Limit must be positive" }

    return observable { emitter ->
        WindowByBoundary(
            upstream = this,
            boundaries = boundaries,
            limit = limit,
            restartOnLimit = restartOnLimit,
            emitter = emitter
        )
    }
}

fun <T> Observable<T>.window(
    span: Duration,
    skip: Duration,
    scheduler: Scheduler,
    limit: Long = Long.MAX_VALUE,
    restartOnLimit: Boolean = false
): Observable<Observable<T>> {
    require(span.isPositive()) { "Span duration must by positive" }
    require(skip.isPositive()) { "Skip duration must by positive" }

    return window(
        opening = singleOf(Unit).repeatWhen { _, _ -> maybeTimer(skip, scheduler) },
        closing = { completableTimer(span, scheduler) },
        limit = limit,
        restartOnLimit = restartOnLimit
    )
}

fun <T, S> Observable<T>.window(
    opening: Observable<S>,
    closing: (S) -> Completable,
    limit: Long = Long.MAX_VALUE,
    restartOnLimit: Boolean = false
): Observable<Observable<T>> {
    require(limit > 0) { "Limit must be positive" }

    return observable { emitter ->
        WindowBySignal(
            upstream = this,
            opening = opening,
            closing = closing,
            limit = limit,
            restartOnLimit = restartOnLimit,
            emitter = emitter
        )
    }
}

fun <T> Observable<T>.window(
    count: Long,
    skip: Long = count
): Observable<Observable<T>> {
    require(count > 0) { "count > 0 required but it was $count" }
    require(skip > 0) { "skip > 0 required but it was $skip" }

    return observable { emitter ->
        val activeWindowsCount = AtomicInt(1)
        val upstreamObserver = UpstreamObserver(
            count = count,
            skip = skip,
            activeWindowsCount = activeWindowsCount,
            downstream = emitter
        )

        emitter.setCancellable {
            if (activeWindowsCount.addAndGet(-1) == 0) {
                upstreamObserver.dispose()
            }
        }

        subscribe(upstreamObserver)
    }
}

fun <T, U, R> Observable<T>.withLatestFrom(
    others: Iterable<Observable<U>>,
    mapper: (value: T, others: List<U>) -> R
): Observable<R> =
    observable { emitter ->
        val disposables = CompositeDisposable()
        emitter.setDisposable(disposables)

        val otherSources = others.toList()
        val otherValues = arrayOfNulls<Any?>(otherSources.size)
        var otherValuesInitialised: BooleanArray? = if (otherSources.isNotEmpty()) BooleanArray(otherSources.size) else null
        val lock = Lock()

        otherSources.forEachIndexed { index, source ->
            source.subscribe(
                object : ObservableObserver<U>, ErrorCallback by emitter {
                    override fun onSubscribe(disposable: Disposable) {
                        disposables += disposable
                    }

                    override fun onNext(value: U) {
                        lock.synchronized {
                            otherValues[index] = value

                            otherValuesInitialised?.takeUnless { it[index] }?.also { flags ->
                                flags[index] = true
                                if (flags.all { it }) {
                                    otherValuesInitialised = null
                                }
                            }
                        }
                    }

                    override fun onComplete() {
                        // no-op
                    }
                }
            )
        }

        subscribe(
            object : ObservableObserver<T>, CompletableCallbacks by emitter {
                override fun onSubscribe(disposable: Disposable) {
                    disposables += disposable
                }

                override fun onNext(value: T) {
                    @Suppress("UNCHECKED_CAST")
                    val valueList =
                        lock.synchronized {
                            otherValues
                                .takeIf { otherValuesInitialised == null }
                                ?.toList() as List<U>?
                        } ?: return

                    emitter.tryCatch(block = { mapper(value, valueList) }, onSuccess = emitter::onNext)
                }
            }
        )
    }

fun <T, T1, T2, R> Observable<T>.withLatestFrom(
