        @Suppress("UNCHECKED_CAST")
        mapper(value, others[0] as T1, others[1] as T2, others[2] as T3)
    }

@Suppress("ComplexMethod", "LongMethod")
fun <T, R> Iterable<Observable<T>>.zip(mapper: (List<T>) -> R): Observable<R> =
    observable { emitter ->
        val sources = toList()

        if (sources.isEmpty()) {
            emitter.onComplete()
            return@observable
        }

        val disposables = CompositeDisposable()
        emitter.setDisposable(disposables)

        val values = List<ArrayList<T>>(sources.size) { ArrayList() }
        val completed = BooleanArray(sources.size)

        val serializer =
            serializer<ZipEvent<T>> { event ->
                when (event) {
                    is ZipEvent.OnNext -> {
                        var readyValues: List<T>? = null

                        values[event.index].add(event.value)
                        if (values.all(List<*>::isNotEmpty)) {
                            readyValues = values.map { it[0] }
                            values.forEach { it.removeAt(0) }
                        }

                        if (readyValues == null) {
                            return@serializer true
                        }

                        val result =
                            try {
                                mapper(readyValues)
                            } catch (e: Throwable) {
                                emitter.onError(e)
                                return@serializer false
                            }

                        emitter.onNext(result)

                        // Complete if for any completed source there are no values left in the queue
                        values.forEachIndexed { index, queue ->
                            if (queue.isEmpty() && completed[index]) {
                                emitter.onComplete()
                                return@serializer false
                            }
                        }

                        true
                    }

                    is ZipEvent.OnComplete -> {
                        completed[event.index] = true

                        // Complete if a source is completed and no values left in its queue
                        val isEmpty = values[event.index].isEmpty()
                        if (isEmpty) {
                            emitter.onComplete()
                        }

                        !isEmpty
                    }

                    is ZipEvent.OnError -> {
                        emitter.onError(event.error)
                        false
                    }
                }
            }

        sources.forEachIndexed { index, source ->
            source.subscribe(
                object : ObservableObserver<T> {
                    override fun onSubscribe(disposable: Disposable) {
                        disposables += disposable
                    }

                    override fun onNext(value: T) {
                        serializer.accept(ZipEvent.OnNext(index, value))
                    }

                    override fun onComplete() {
                        serializer.accept(ZipEvent.OnComplete(index))
                    }

                    override fun onError(error: Throwable) {
                        serializer.accept(ZipEvent.OnError(error))
                    }
                }
            )
        }
    }

val isEmpty = values[event.index].isEmpty()
if (isEmpty) {
    emitter.onComplete()
}

fun <T1, T2, R> zip(
    source1: Observable<T1>,
    source2: Observable<T2>,
    mapper: (T1, T2) -> R
): Observable<R> =
    listOf(source1, source2)
        .zip { values ->
            @Suppress("UNCHECKED_CAST")
            mapper(values[0] as T1, values[1] as T2)
        }

interface Scheduler {

    /**
     * Creates a new instance of [Executor]. Throws an exception if [Scheduler] is destroyed.
     */
    fun newExecutor(): Executor

    /**
     * Destroys the scheduler
     */
    fun destroy()

    /**
     * Base interface for [Scheduler] executors. All tasks are executed synchronously one by one, never concurrently.
     * [Executor]s must be disposed when they are no longer needed.
     */
    interface Executor : Disposable {

        /**
         * Submits a new task, repeating if [period] is specified.
         *
         * @param delay a delay before first execution, default is [Duration.ZERO] (as soon as possible).
         * @param period a period between executions, default is [Duration.INFINITE] (non-repeating).
         * @param task the task to be executed
         */
        fun submit(
            delay: Duration = Duration.ZERO,
            period: Duration = Duration.INFINITE,
            task: () -> Unit,
        )

        /**
         * Cancels all tasks. All running tasks will be interrupted, all pending tasks will not be executed.
         */
        fun cancel()
    }
}

fun <T> Iterable<Single<T>>.amb(): Single<T> =
    com.badoo.reaktive.single.single { emitter ->
        val sources = toList()

        if (sources.isEmpty()) {
            emitter.onError(NoSuchElementException())
            return@single
        }

        val disposableObserver =
            object : CompositeDisposableObserver(), SingleObserver<T> {
                private val isFinished = AtomicBoolean()

                override fun onSuccess(value: T) {
                    race { emitter.onSuccess(value) }
                }

                override fun onError(error: Throwable) {
                    race { emitter.onError(error) }
                }

                private inline fun race(block: () -> Unit) {
                    if (isFinished.compareAndSet(false, true)) {
                        block()
                    }
                }
            }

        emitter.setDisposable(disposableObserver)

        sources.forEach { it.subscribe(disposableObserver) }
    }

