}

fun terminate() {
    lock.synchronized {
        queue = null
        lock.signal()
    }
}

@Suppress("NestedBlockDepth")
fun take(): T? {
    lock.synchronized {
        while (true) {
            val queue = queue ?: return null
            val item: Holder<T>? = queue.peek()

            if (item == null) {
                lock.await()
            } else {
                val timeout = item.endTime - clock.uptime

                if (!timeout.isPositive()) {
                    queue.poll()

                    return item.value
                }

                lock.await(timeout)
            }
        }
    }
}

