internal class ChildNodeLifecycleManager<NavTarget>(
    private val navModel: NavModel<NavTarget, *>,
    private val children: StateFlow<ChildEntryMap<NavTarget>>,
    private val keepMode: ChildEntry.KeepMode,
    private val coroutineScope: CoroutineScope,
) {

    private val lifecycleState = MutableStateFlow(Lifecycle.State.INITIALIZED)

    /**
     * Propagates the parent lifecycle to children.
     *
     * Child lifecycles should be updated only after all lifecycle callbacks are invoked in the current node.
     *
     * **DO NOT USE LIFECYCLE.OBSERVE HERE!**
     *
     * Otherwise a child node lifecycle might be updated before the parent.
     * It leads to incorrect registration order of back handlers.
     */
    fun propagateLifecycleToChildren(state: Lifecycle.State) {
        lifecycleState.value = state
    }

    fun launch() {
        // previously state management was split into multiple jobs
        // but we found execution order issues when the main thread is busy (?)
        // so we merged it into single one
        coroutineScope.launch {
            combine(
                lifecycleState,
                navModel.screenState.keys(),
                children.withPrevious(),
                ::Triple
            )
                .onCompletion {
                    // when scope is closed we need to destroy all existing children
                    // do it manually here as emit() does not work for cancellation case
                    children
                        .value
                        .values
                        .forEach { entry -> entry.setState(Lifecycle.State.DESTROYED) }
                }
                .collect { (parentLifecycleState, screenState, children) ->
                    screenState.onScreen.forEach { key ->
                        val childState = minOf(parentLifecycleState, Lifecycle.State.RESUMED)
                        children.current[key]?.setState(childState)
                    }

                    screenState.offScreen.forEach { key ->
                        if (keepMode == ChildEntry.KeepMode.KEEP) {
                            val childState = minOf(parentLifecycleState, Lifecycle.State.CREATED)
                            children.current[key]?.setState(childState)
                        } else {
                            // Look up in the previous because in the current it is already suspended
                            // and does not have a reference to the node
                            children.previous?.get(key)?.setState(Lifecycle.State.DESTROYED)
                        }
                    }

                    if (children.previous != null) {
                        val removedKeys = children.previous.keys - children.current.keys
                        removedKeys.forEach { key ->
                            val removedChild = children.previous[key]
                            removedChild?.setState(Lifecycle.State.DESTROYED)
                        }
                    }
                }
        }
    }

    private fun <NavTarget> Flow<NavModelAdapter.ScreenState<NavTarget, *>>.keys() =
        this
            .map { screenState ->
                ScreenState(
                    onScreen = screenState.onScreen.map { it.key },
                    offScreen = screenState.offScreen.map { it.key },
                )
            }
            .distinctUntilChanged()

    private fun ChildEntry<*>.setState(state: Lifecycle.State) {
        nodeOrNull?.updateLifecycleState(state)
    }

    private data class ScreenState<NavTarget>(
        val onScreen: List<NavKey<NavTarget>> = emptyList(),
        val offScreen: List<NavKey<NavTarget>> = emptyList(),
    )

}

fun propagateLifecycleToChildren(state: Lifecycle.State) {
    lifecycleState.value = state
}

internal class MinimumCombinedLifecycle(
    vararg lifecycles: Lifecycle,
) : LifecycleOwner {
    private val registry = LifecycleRegistry(this)
    private val lifecycles = ArrayList<Lifecycle>()

    init {
        /*
        Sort list to avoid unnecessary state jumps.
        If Lifecycle(RESUMED) + Lifecycle(DESTROYED) is passed,
        then we should have the final state in DESTROYED state without additional jumping to RESUMED.
         */
        lifecycles.sortedBy { it.currentState }.forEach { manage(it) }
    }

    override val lifecycle: Lifecycle
        get() = registry

    fun manage(lifecycle: Lifecycle) {
        lifecycles += lifecycle
        lifecycle.addObserver(object : DefaultLifecycleObserver {
            override fun onCreate(owner: LifecycleOwner) {
                update()
            }

            override fun onStart(owner: LifecycleOwner) {
                update()
            }

            override fun onResume(owner: LifecycleOwner) {
                update()
            }

            override fun onPause(owner: LifecycleOwner) {
                update()
            }

            override fun onStop(owner: LifecycleOwner) {
                update()
            }

            override fun onDestroy(owner: LifecycleOwner) {
                update()
            }
        })
        update()
    }

    private fun update() {
        lifecycles
            .minByOrNull { it.currentState }
            ?.takeIf { it.currentState != Lifecycle.State.INITIALIZED }
            ?.also { registry.currentState = it.currentState }
    }

}

abstract class BaseNavModel<NavTarget, State>(
    private val backPressHandler: BackPressHandlerStrategy<NavTarget, State> = DontHandleBackPress(),
    private val operationStrategy: OperationStrategy<NavTarget, State> = ExecuteImmediately(),
    private val screenResolver: OnScreenStateResolver<State>,
    protected val scope: CoroutineScope = CoroutineScope(EmptyCoroutineContext + Dispatchers.Unconfined),
    protected val finalStates: Set<State>,
    private val key: String = KEY_NAV_MODEL,
    savedStateMap: SavedStateMap?
) : NavModel<NavTarget, State>, Destroyable, BackPressHandler {

    constructor(
        backPressHandler: BackPressHandlerStrategy<NavTarget, State> = DontHandleBackPress(),
        operationStrategy: OperationStrategy<NavTarget, State> = ExecuteImmediately(),
        screenResolver: OnScreenStateResolver<State>,
        scope: CoroutineScope = CoroutineScope(EmptyCoroutineContext + Dispatchers.Unconfined),
        finalState: State?,
        key: String = KEY_NAV_MODEL,
        savedStateMap: SavedStateMap?
    ) : this(
        backPressHandler = backPressHandler,
        operationStrategy = operationStrategy,
        screenResolver = screenResolver,
        scope = scope,
        finalStates = setOfNotNull(finalState),
        key = key,
        savedStateMap = savedStateMap
    )

    // TODO: think about how we can avoid keeping unnecessary object after state initialization https://github.com/bumble-tech/appyx/issues/193
    protected abstract val initialElements: NavElements<NavTarget, State>

    private val state: MutableStateFlow<NavElements<NavTarget, State>> by lazy {
        MutableStateFlow(savedStateMap?.restoreHistory() ?: initialElements)
    }

    override val elements: StateFlow<NavElements<NavTarget, State>> get() = state

    override val screenState: StateFlow<NavModelAdapter.ScreenState<NavTarget, State>> by lazy {
        state
            .mapState(scope) { elements ->
                NavModelAdapter.ScreenState(
                    onScreenWithVisibleTargetState = elements.filter { screenResolver.isOnScreen(it.targetState) },
                    onScreen = elements.filter { screenResolver.isOnScreen(it) },
                    offScreen = elements.filterNot { screenResolver.isOnScreen(it) },
                )
            }
    }

    override val onBackPressedCallback: OnBackPressedCallback by lazy {
        val callback = object : OnBackPressedCallback(false) {
            override fun handleOnBackPressed() {
                backPressHandler.onBackPressed()
            }
        }
        scope.launch {
            backPressHandler.canHandleBackPress.collect {
                callback.isEnabled = it
            }
        }
        callback
    }

    init {
        backPressHandler.init(this, scope)
        operationStrategy.init(this, scope, ::execute)
    }

    override fun accept(operation: Operation<NavTarget, State>) {
        operationStrategy.accept(operation)
    }

    protected fun updateState(block: (NavElements<NavTarget, State>) -> NavElements<NavTarget, State>) {
        state.update { currentState ->
            val newState = block(currentState)
            sanitizeOffScreenTransitions(newState)
        }
    }

    private fun execute(operation: Operation<NavTarget, State>) {
        updateState {
            if (operation.isApplicable(it)) {
                operation(it)
            } else {
                it
            }
        }
    }

    /**
     * Off screen transitions can't finish without [onTransitionFinished] callback from UI.
     * In case if we have any, lets finish them instantly.
     */
    protected fun sanitizeOffScreenTransitions(
        state: NavElements<NavTarget, State>
    ): NavElements<NavTarget, State> =
        state.mapNotNull {
            if (screenResolver.isOnScreen(it)) {
                it
            } else {
                it.finishTransitionOrRemove()
            }
        }

    override fun onTransitionFinished(keys: Collection<NavKey<NavTarget>>) {
        if (keys.isEmpty()) return
        state.update { list ->
            list.mapNotNull {
                if (it.key in keys) {
                    it.finishTransitionOrRemove()
                } else {
                    it
                }
            }
        }
    }

    protected open fun NavElement<NavTarget, State>.finishTransitionOrRemove(): NavElement<NavTarget, State>? =
        if (targetState.isFinalState) {
            null
        } else {
            onTransitionFinished()
        }

    override fun saveInstanceState(state: MutableSavedStateMap) {
        state[key] =
            elements.value.mapNotNull {
                // Sanitize outputs, removing all transitions
                if (it.targetState.isFinalState) {
                    null
                } else {
                    it.onTransitionFinished()
                }
            }
    }

    override fun destroy() {
        scope.cancel()
    }

    protected val State.isFinalState
        get() = finalStates.contains(this)

    private fun SavedStateMap.restoreHistory() =
        this[key] as? NavElements<NavTarget, State>

    companion object {
        const val KEY_NAV_MODEL = "NavModel"
    }

}

protected fun sanitizeOffScreenTransitions(
    state: NavElements<NavTarget, State>
): NavElements<NavTarget, State> =
    state.mapNotNull {
        if (screenResolver.isOnScreen(it)) {
