internal sealed interface ParaformerEvent {
    data object Started : ParaformerEvent
    data object Finished : ParaformerEvent
    data class Failed(val code: String, val message: String) : ParaformerEvent
    data class Result(val text: String, val sentenceEnd: Boolean, val heartbeat: Boolean, val itemId: String? = null) : ParaformerEvent

    companion object {
        private val json = Json { ignoreUnknownKeys = true }

        fun parse(text: String): ParaformerEvent? = runCatching {
            val root = json.parseToJsonElement(text).jsonObject
            val header = root["header"]?.jsonObject ?: return null
            when (header.string("event")) {
                "task-started" -> Started
                "task-finished" -> Finished
                "task-failed" -> Failed(header.string("error_code").orEmpty(), header.string("error_message").orEmpty())
                "result-generated" -> {
                    val sentence = root["payload"]?.jsonObject?.get("output")?.jsonObject
                        ?.get("sentence")?.jsonObject ?: return null
                    Result(
                        text = sentence.string("text").orEmpty(),
                        sentenceEnd = sentence["sentence_end"]?.jsonPrimitive?.booleanOrNull == true,
                        heartbeat = sentence["heartbeat"]?.jsonPrimitive?.booleanOrNull == true,
                    )
                }
                else -> null
            }
        }.onFailure { Timber.w("[asr-cloud] unreadable server event") }.getOrNull()

        private fun JsonObject.string(key: String): String? =
            (get(key) as? JsonPrimitive)?.contentOrNull
    }
}

internal class PcmDecimator(private val factor: Int, taps: Int = 63) {
    private val coefficients: FloatArray
    private var history: FloatArray
    private var phase = 0

    init {
        require(factor >= 1) { "factor must be positive" }
        require(taps % 2 == 1) { "taps must be odd" }
        // Pass band ends at 90% of the output Nyquist frequency (cycles per input sample).
        val cutoff = 0.45 / factor
        val middle = (taps - 1) / 2.0
        val raw = DoubleArray(taps) { n ->
            val x = n - middle
            val sinc = if (x == 0.0) 2 * cutoff else sin(2 * PI * cutoff * x) / (PI * x)
            val hamming = 0.54 - 0.46 * cos(2 * PI * n / (taps - 1))
            sinc * hamming
        }
        val sum = raw.sum()
        coefficients = FloatArray(taps) { (raw[it] / sum).toFloat() }
        history = FloatArray(taps - 1)
    }

    fun process(input: FloatArray, count: Int = input.size): FloatArray {
        if (factor == 1) return input.copyOf(count)
        val buffer = FloatArray(history.size + count)
        history.copyInto(buffer)
        input.copyInto(buffer, history.size, 0, count)
        val output = FloatArray((count - phase + factor - 1).coerceAtLeast(0) / factor)
        var produced = 0
        var index = phase
        while (index < count) {
            var acc = 0f
            val newest = index + history.size
            for (k in coefficients.indices) acc += coefficients[k] * buffer[newest - k]
            output[produced++] = acc
            index += factor
        }
        phase = index - count
        history = buffer.copyOfRange(buffer.size - history.size, buffer.size)
        return if (produced == output.size) output else output.copyOf(produced)
    }

    fun reset() {
        history.fill(0f)
        phase = 0
    }
}

internal class PlaybackAudioCapture private constructor(
    private val record: AudioRecord,
    val sourceRate: Int,
) {
    private val decimator = if (sourceRate == TARGET_RATE) null else PcmDecimator(sourceRate / TARGET_RATE)
    private val pcm = ShortArray(sourceRate * READ_MS / 1000)

    fun start() {
        decimator?.reset()
        record.startRecording()
    }

    fun stop() {
        runCatching { record.stop() }
    }

    fun release() {
        stop()
        record.release()
    }

    /**
     * Blocks for roughly [READ_MS]. Returns null when the recorder fails or was stopped; the
     * caller ends its read loop before [release] so native memory is never read after release.
     */
    fun read(): FloatArray? {
        val count = record.read(pcm, 0, pcm.size, AudioRecord.READ_BLOCKING)
        if (count < 0) {
            Timber.w("[asr-capture] AudioRecord.read error=%d", count)
            return null
        }
        val samples = FloatArray(count) { pcm[it] / 32768f }
        return decimator?.process(samples, count) ?: samples
    }

    companion object {
        const val TARGET_RATE = 16_000
        const val READ_MS = 100

        /** Requires a granted RECORD_AUDIO permission; returns null when no format initializes. */
        @RequiresApi(Build.VERSION_CODES.Q)
        @SuppressLint("MissingPermission")
        fun create(projection: MediaProjection, excludedUid: Int): PlaybackAudioCapture? {
            val config = AudioPlaybackCaptureConfiguration.Builder(projection)
                .addMatchingUsage(AudioAttributes.USAGE_MEDIA)
                .addMatchingUsage(AudioAttributes.USAGE_GAME)
                .addMatchingUsage(AudioAttributes.USAGE_UNKNOWN)
                .excludeUid(excludedUid)
                .build()
            for (rate in listOf(TARGET_RATE, 48_000)) {
                val minBytes = AudioRecord.getMinBufferSize(
                    rate, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT,
                )
                if (minBytes <= 0) continue
                val record = runCatching {
                    AudioRecord.Builder()
                        .setAudioFormat(
                            AudioFormat.Builder()
                                .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                                .setSampleRate(rate)
                                .setChannelMask(AudioFormat.CHANNEL_IN_MONO)
                                .build()
                        )
                        .setBufferSizeInBytes(maxOf(minBytes, rate * 2))
                        .setAudioPlaybackCaptureConfig(config)
                        .build()
                }.onFailure { Timber.w(it, "[asr-capture] AudioRecord rate=%d failed", rate) }.getOrNull()
                if (record?.state == AudioRecord.STATE_INITIALIZED) {
                    Timber.i("[asr-capture] AudioRecord ready rate=%d bufferBytes=%d", rate, maxOf(minBytes, rate * 2))
                    return PlaybackAudioCapture(record, rate)
                }
                record?.release()
            }
            return null
        }
    }
}

