        AsrCloudProvider.TENCENT, AsrCloudProvider.VOLCENGINE -> NativeCloudSpeechEngine(httpClient,
            current.asrCloudProvider, current.asrCloudConnections, sink, failed, sessionMetrics,
            onReady = ready, tencentSecretId = current.tencentSecretId, tencentSecretKey = current.tencentSecretKey,
            language = language, targetLanguage = current.targetLang, hintSource = hintSource)
        AsrCloudProvider.ALIYUN -> ParaformerRealtimeEngine(
            client = httpClient,
            apiKey = current.asrDashScopeApiKey.trim(),
            language = language,
            cloudModel = current.asrCloudModel,
            targetLanguage = current.targetLang,
            sink = sink,
            onFailure = failed,
            metrics = sessionMetrics,
            onReady = ready,
            hintSource = hintSource,
        )
    }
}

fun pause() = command("pause") {
    if (state != SpeechBallState.RECOGNIZING) return@command
    nextGeneration()
    stopLoop()
    withContext(inferenceThread) { engine?.reset() }
    logMetrics("pause")
    setState(SpeechBallState.PAUSED)
}

fun shutdown(): Job = scope.launch {
    installer.unregisterModelReleaser(modelReleaser)
    commands.withLock { stopNow() }
    inferenceThread.close()
    captureThread.close()
    scope.cancel()
}

private suspend fun releaseModel(model: AsrModelId) {
    command("release ${model.name}") {
        if (engineModel != model) return@command
        Timber.i("[asr] releasing %s for model management", model.name)
        stopNow()
    }.join()
}

val gap = now - lastReadAt - PlaybackAudioCapture.READ_MS * 2
lastReadAt = now
if (gap > CAPTURE_GAP_RESET_MS) chunks.markGap()
if (samples.isEmpty()) continue
if (isOwnAudioPlaying()) {
    // Never transcribe this app's own read-aloud output.
    if (!ownAudio) chunks.markGap()
    ownAudio = true
    continue
}

private inline fun guarded(name: String, loopGeneration: Long, body: () -> Unit) =
    runWorkerLoop(onFailure = { error ->
        Timber.e(error, "[asr] %s loop failed", name)
        if (!loopStopping) scope.launch { failFromLoop(loopGeneration) }
    }

internal class SpeechStartGuard {
    private var active: Long? = null
    private var next = 0L

    val isActive: Boolean get() = active != null

    /** Returns the new request's token, or null while another request is still preparing. */
    fun begin(): Long? {
        if (active != null) return null
        return (++next).also { active = it }
    }

    fun isCurrent(token: Long): Boolean = active == token

    /** Returns true when [token] was the active request and is now finished. */
    fun finish(token: Long): Boolean {
        if (active != token) return false
        active = null
        return true
    }

    fun invalidate() {
        active = null
    }
}

fun begin(): Long? {
    if (active != null) return null
    return (++next).also { active = it }
}

fun finish(token: Long): Boolean {
    if (active != token) return false
    active = null
    return true
}

internal inline fun runWorkerLoop(onFailure: (Exception) -> Unit, body: () -> Unit) {
    try {
        body()
    } catch (cancelled: CancellationException) {
        throw cancelled
    } catch (error: Exception) {
        onFailure(error)
    }
}

fun blockReason(settings: Settings, modelInstalled: Boolean?): SpeechStartBlock? = when {
    settings.asrEngine.isCloud && settings.asrCloudProvider == AsrCloudProvider.TENCENT &&
        settings.asrCloudConnections.tencentModel.translatesSpeech &&
        !com.gameocr.app.data.TencentSpeechLanguagePolicy.supports(
            AsrLanguagePolicy.effective(settings.asrEngine, settings.asrLanguage, settings.asrCloudModel, settings.asrCloudProvider, settings.asrCloudConnections), settings.targetLang) ->
        SpeechStartBlock.CLOUD_LANGUAGE_UNSUPPORTED
    settings.asrEngine.isCloud && settings.asrCloudProvider != AsrCloudProvider.ALIYUN ->
        SpeechStartBlock.CLOUD_CONFIGURATION_INCOMPLETE.takeIf { !configurationReady(settings) }
    settings.asrEngine.isCloud ->
        SpeechStartBlock.CLOUD_NOT_CONFIGURED.takeIf { settings.asrDashScopeApiKey.isBlank() }
    modelInstalled != true -> SpeechStartBlock.MODEL_MISSING
    else -> null
}

fun engineKey(settings: Settings): String {
    val model = AsrModelId.forSettings(settings.asrEngine, settings.asrWhisperVariant)
    val language = AsrLanguagePolicy.effective(settings.asrEngine, settings.asrLanguage, settings.asrCloudModel, settings.asrCloudProvider, settings.asrCloudConnections).code
    val hintKey = if (com.gameocr.app.data.AsrHintPolicy.capabilities(settings).available)
        ":${settings.asrHints.hashCode()}:${settings.foregroundAppDetectionMode}" else ""
    val segmentation = AsrSegmentationPolicy.durations(settings)?.let { ":${it.pauseMs}:${it.maxSpeechMs}" }.orEmpty() + hintKey
    if (settings.asrEngine.isCloud && settings.asrCloudProvider != AsrCloudProvider.ALIYUN) {
        val connection = settings.asrCloudConnections
        val selected = when (settings.asrCloudProvider) {
            AsrCloudProvider.TENCENT -> listOf(connection.tencentAppId.trim(), settings.tencentSecretId.trim(), settings.tencentSecretKey.trim(), connection.tencentModel.modelId,
                if (connection.tencentModel.translatesSpeech) com.gameocr.app.data.TencentSpeechLanguagePolicy.target(settings.targetLang) else "")
            AsrCloudProvider.VOLCENGINE -> listOf(connection.volcApiKey.trim(), connection.volcResource.resourceId)
            AsrCloudProvider.OPENAI_COMPATIBLE -> listOf(connection.openAiBaseUrl.trim(), connection.openAiApiKey.trim(), connection.openAiModel.trim(), connection.openAiTransport.name)
            else -> emptyList()
        }
        return "${settings.asrCloudProvider.name}:$language:${selected.hashCode()}$segmentation"
    }
    // The key is only compared, never logged with its value; a hash marks a changed key.
    val credential = if (settings.asrEngine.isCloud) ":" + settings.asrDashScopeApiKey.trim().hashCode() else ""
    val cloudModel = if (settings.asrEngine.isCloud) ":${settings.asrCloudModel.modelId}" else ""
    val target = if (settings.asrEngine.isCloud && settings.asrCloudModel.translatesSpeech)
        ":${settings.targetLang.trim()}" else ""
    return "${model?.name ?: settings.asrEngine.name}$cloudModel:$language$credential$target$segmentation"
}

private val render: (List<SpeechDisplayRecord>) -> Unit,
private val userMessage: (Int) -> String,
private val clock: () -> Long = { SystemClock.elapsedRealtime() }

fun onGenerationChanged() = post {
    cancelTasks()
    loggedProviderResults.clear()
    transcript.closeGeneration()
    scheduleRender()
}

private fun post(action: suspend () -> Unit) {
    inbox.trySend(action)
}

private fun cancelTasks() {
    if (tasks.isNotEmpty()) Timber.i("[asr] canceled %d unfinished translations", tasks.size)
    tasks.values.forEach { task ->
        task.canceled = true
        task.job?.cancel()
    }
    tasks.clear()
}

private suspend fun run(task: Task) = coroutineScope {
    val job = launch { translate(task) }
    lock.withLock {
        if (task.canceled) job.cancel() else task.job = job
    }
}

private suspend fun update(record: SpeechRecord, translation: String, state: SpeechRecordState): Boolean =
    lock.withLock {
        if (record.generation != currentGeneration()) return@withLock false
        if (state == SpeechRecordState.DONE) history.complete(record.id, translation)
        // The record may have scrolled out of the display limit; its task still completes.
        if (transcript.applyTranslation(record.id, translation, state)) scheduleRender()
        true
    }

private fun scheduleRender() {
    dirty = true
    if (renderJob?.isActive == true) return
    renderJob = scope.launch {
        while (true) {
            val records = lock.withLock {
                if (!dirty) return@launch
                dirty = false
                transcript.trim(maxRecords)
                transcript.display()
            }
            render(records)
            delay(RENDER_INTERVAL_MS)
        }
    }
}

fun isLikelyHallucination(text: String, audioSeconds: Float): Boolean {
    if (text.isBlank()) return true
    val seconds = audioSeconds.coerceAtLeast(0.1f)
    if (text.length / seconds > MAX_CHARS_PER_SECOND) return true
    val words = text.split(' ').filter { it.isNotBlank() }
    if (words.size >= REPEAT_LIMIT && words.distinct().size == 1) return true
    return hasRepeatedRun(text.replace(" ", ""))
}

private fun hasRepeatedRun(text: String): Boolean {
    for (unit in 1..16) {
        if (text.length < unit * REPEAT_LIMIT) break
        var run = 1
        var i = unit
        while (i + unit <= text.length) {
            if (text.regionMatches(i, text, i - unit, unit)) {
                run++
                if (run >= REPEAT_LIMIT) return true
                i += unit
            } else {
                run = 1
                i++
            }
        }
    }
    return false
}

internal class SpeechTranscript {
    private val records = ArrayList<SpeechRecord>()
    private var nextId = 1L
    private var providerTrimmedGeneration = -1L
    private var providerTrimmedThrough = -1L

    val all: List<SpeechRecord> get() = records

    /** Full S2TT snapshots update their own row, even when source and translation interleave. */
    fun onProviderResult(generation: Long, event: SpeechEvent) {
        if (event.text.isEmpty() && event.providerTranslation.isNullOrEmpty()) return
        val index = records.indexOfFirst { it.generation == generation && it.segmentId == event.segmentId }
        val current = records.getOrNull(index)
        if (current?.state == SpeechRecordState.CANCELED) return
        if (current == null && generation == providerTrimmedGeneration && event.segmentId <= providerTrimmedThrough) return
        val record = SpeechRecord(
            current?.id ?: nextId++, generation, event.segmentId, event.text,
            event.providerTranslation.orEmpty(),
            when {
                event.providerTranslationFailed -> SpeechRecordState.FAILED
                event.isFinal -> SpeechRecordState.DONE
                else -> SpeechRecordState.TRANSLATING
            }, providerTranslated = true,
        )
        if (index >= 0) records[index] = record else {
            val before = records.indexOfFirst {
                it.providerTranslated && it.generation == generation && it.segmentId > event.segmentId
            }
            if (before >= 0) records.add(before, record) else records.add(record)
        }
    }

    /** Shows or revises the utterance being spoken. */
    fun onPartial(generation: Long, segmentId: Long, text: String) {
        val open = records.lastOrNull()?.takeIf { it.state == SpeechRecordState.LISTENING }
        if (open != null && open.generation == generation && open.segmentId == segmentId) {
            records[records.lastIndex] = open.copy(source = text)
            return
        }
        // Any other open utterance was abandoned by the engine (reset, dropped audio, empty final).
        if (open != null) records.removeAt(records.lastIndex)
        records += SpeechRecord(nextId++, generation, segmentId, text, "", SpeechRecordState.LISTENING)
    }

    /** Removes only the matching unconfirmed row when the server retracts an empty result. */
    fun discardPartial(generation: Long, segmentId: Long) {
        records.removeAll { it.generation == generation && it.segmentId == segmentId && it.state == SpeechRecordState.LISTENING }
    }

    /** Finalizes the matching utterance (or appends a new one) and returns it for translation. */
    fun onFinal(generation: Long, segmentId: Long, text: String): SpeechRecord {
        val open = records.lastOrNull()?.takeIf { it.state == SpeechRecordState.LISTENING }
        if (open != null) records.removeAt(records.lastIndex)
        val id = if (open != null && open.generation == generation && open.segmentId == segmentId) open.id else nextId++
        return SpeechRecord(id, generation, segmentId, text, "", SpeechRecordState.QUEUED).also { records += it }
    }

    /** Applies a (partial or final) translation by id. Returns false when the record is gone. */
    fun applyTranslation(id: Long, translation: String, state: SpeechRecordState): Boolean {
        val index = records.indexOfFirst { it.id == id }
        if (index < 0) return false
        val current = records[index]
        // A late result never revives a record that was canceled at a pause.
        if (current.state == SpeechRecordState.CANCELED) return false
        records[index] = current.copy(translation = translation, state = state)
        return true
    }

    /**
     * Pause/resume/stop boundary: drops the unfinished utterance and marks every translation that
     * has not finished as canceled. Finished history stays, but nothing new is joined to it.
     */
    fun closeGeneration() {
        records.removeAll { it.state == SpeechRecordState.LISTENING }
        records.replaceAll { record ->
            when (record.state) {
                SpeechRecordState.QUEUED, SpeechRecordState.TRANSLATING ->
                    record.copy(translation = if (record.providerTranslated) record.translation else "", state = SpeechRecordState.CANCELED)
                else -> record
            }
        }
    }

    /** Keeps the newest [maxRecords]; the open utterance is never trimmed. */
    fun trim(maxRecords: Int) {
        val excess = records.size - maxRecords.coerceAtLeast(1)
        if (excess > 0) {
            records.take(excess).filter { it.providerTranslated }.forEach {
                if (it.generation != providerTrimmedGeneration) {
                    providerTrimmedGeneration = it.generation
                    providerTrimmedThrough = -1L
                }
                providerTrimmedThrough = maxOf(providerTrimmedThrough, it.segmentId)
            }
            records.subList(0, excess).clear()
        }
    }

    fun clear() {
        records.clear()
        providerTrimmedGeneration = -1L
        providerTrimmedThrough = -1L
    }

    fun display(): List<SpeechDisplayRecord> = records.map { record ->
        val translation = when (record.state) {
            SpeechRecordState.LISTENING, SpeechRecordState.QUEUED -> PENDING
            SpeechRecordState.TRANSLATING -> record.translation.ifEmpty { PENDING }
            // A failed or canceled translation leaves the source line on its own.
            SpeechRecordState.DONE, SpeechRecordState.FAILED, SpeechRecordState.CANCELED -> record.translation
        }
        SpeechDisplayRecord(record.id, record.source, translation)
    }

    companion object {
        const val PENDING = "…"
    }
}

fun onProviderResult(generation: Long, event: SpeechEvent) {
    if (event.text.isEmpty() && event.providerTranslation.isNullOrEmpty()) return
    val index = records.indexOfFirst { it.generation == generation && it.segmentId == event.segmentId }
    val current = records.getOrNull(index)
    if (current?.state == SpeechRecordState.CANCELED) return
    if (current == null && generation == providerTrimmedGeneration && event.segmentId <= providerTrimmedThrough) return
    val record = SpeechRecord(
        current?.id ?: nextId++, generation, event.segmentId, event.text,
        event.providerTranslation.orEmpty(),
        when {
            event.providerTranslationFailed -> SpeechRecordState.FAILED
            event.isFinal -> SpeechRecordState.DONE
            else -> SpeechRecordState.TRANSLATING
        }, providerTranslated = true,
    )
    if (index >= 0) records[index] = record else {
        val before = records.indexOfFirst {
            it.providerTranslated && it.generation == generation && it.segmentId > event.segmentId
        }
        if (before >= 0) records.add(before, record) else records.add(record)
    }
}

fun onPartial(generation: Long, segmentId: Long, text: String) {
    val open = records.lastOrNull()?.takeIf { it.state == SpeechRecordState.LISTENING }
    if (open != null && open.generation == generation && open.segmentId == segmentId) {
        records[records.lastIndex] = open.copy(source = text)
        return
    }
    // Any other open utterance was abandoned by the engine (reset, dropped audio, empty final).
    if (open != null) records.removeAt(records.lastIndex)
    records += SpeechRecord(nextId++, generation, segmentId, text, "", SpeechRecordState.LISTENING)
}

fun discardPartial(generation: Long, segmentId: Long) {
    records.removeAll { it.generation == generation && it.segmentId == segmentId && it.state == SpeechRecordState.LISTENING }
}

fun onFinal(generation: Long, segmentId: Long, text: String): SpeechRecord {
    val open = records.lastOrNull()?.takeIf { it.state == SpeechRecordState.LISTENING }
    if (open != null) records.removeAt(records.lastIndex)
    val id = if (open != null && open.generation == generation && open.segmentId == segmentId) open.id else nextId++
    return SpeechRecord(id, generation, segmentId, text, "", SpeechRecordState.QUEUED).also { records += it }
}

fun applyTranslation(id: Long, translation: String, state: SpeechRecordState): Boolean {
    val index = records.indexOfFirst { it.id == id }
    if (index < 0) return false
    val current = records[index]
    // A late result never revives a record that was canceled at a pause.
    if (current.state == SpeechRecordState.CANCELED) return false
    records[index] = current.copy(translation = translation, state = state)
    return true
}

fun closeGeneration() {
    records.removeAll { it.state == SpeechRecordState.LISTENING }
    records.replaceAll { record ->
        when (record.state) {
            SpeechRecordState.QUEUED, SpeechRecordState.TRANSLATING ->
                record.copy(translation = if (record.providerTranslated) record.translation else "", state = SpeechRecordState.CANCELED)
            else -> record
        }
    }
}

fun trim(maxRecords: Int) {
    val excess = records.size - maxRecords.coerceAtLeast(1)
    if (excess > 0) {
        records.take(excess).filter { it.providerTranslated }.forEach {
            if (it.generation != providerTrimmedGeneration) {
                providerTrimmedGeneration = it.generation
                providerTrimmedThrough = -1L
            }
            providerTrimmedThrough = maxOf(providerTrimmedThrough, it.segmentId)
        }
        records.subList(0, excess).clear()
    }
}

fun complete(recordId: Long, translation: String) {
    val turn = turns[recordId] ?: return
    val text = translation.trim().takeIf { it.isNotEmpty() && it != turn.source } ?: return
    turns[recordId] = turn.copy(translation = text)
}

fun before(recordId: Long, contextKey: String): List<RuntimeDialogueTurn> {
    if (key != contextKey) {
        // The first request adopts the key; only a real change makes old turns stale.
        if (key != null) turns.keys.removeAll { it < recordId }
        key = contextKey
    }
    return turns.filterKeys { it < recordId }.values.toList().takeLast(maxTurns)
}

internal object SpeechTranslationContextPolicy {
    /** Required by [DialogueTranslationContextPolicy.contextualize]; never read when history is passed. */
    private val unusedSession = DialogueHistorySession()

    fun enabled(settings: Settings): Boolean =
        settings.translationContextMode != TranslationContextMode.FAST_PER_SEGMENT &&
            supportsTranslationPromptContext(settings.translatorEngine)

    fun contextualize(settings: Settings, source: String, history: List<RuntimeDialogueTurn>): Settings {
        if (!enabled(settings) || history.isEmpty()) return settings
        val continuous = settings.copy(translationContextMode = TranslationContextMode.CONTINUOUS_CONTEXT)
        return DialogueTranslationContextPolicy.contextualize(
            settings = continuous,
            currentSources = listOf(source),
            historySession = unusedSession,
            availableHistory = DialogueContextFrame(
                history.mapIndexed { index, turn -> DialogueContextItem(index + 1, turn.source, turn.translation) },
            ),
        )
    }
}

internal object TencentSpeechTranslationProtocol {
    fun request(config: AsrCloudConnections, voice: String, now: Long, nonce: Int,
        secretId: String, secretKey: String, source: AsrLanguage, target: String): Request {
        require(config.tencentModel.translatesSpeech)
        require(config.tencentAppId.trim().matches(Regex("[0-9]+")))
        require(TencentSpeechLanguagePolicy.supports(source, target))
        val params = sortedMapOf("expired" to (now + 3600).toString(), "nonce" to nonce.toString(),
            "secretid" to secretId.trim(), "source" to source.code,
            "target" to TencentSpeechLanguagePolicy.target(target), "timestamp" to now.toString(),
            "trans_model" to config.tencentModel.modelId, "voice_format" to "1", "voice_id" to voice,
            "enable_tts" to "0")
        if (source in listOf(AsrLanguage.ZH, AsrLanguage.EN, AsrLanguage.ZH_EN)) {
            params["vad_silence_time"] = "1300"
            params["max_speak_time"] = "10000"
        }
        return TencentSpeechProtocol.signedRequest("asr.cloud.tencent.com/asr/speech_translate/${config.tencentAppId.trim()}", params, secretKey)
    }

    fun parse(message: String): NativeSpeechPacket {
        val root = Json.parseToJsonElement(message).jsonObject
        val code = root["code"]?.jsonPrimitive?.intOrNull ?: error("Missing Tencent translation status")
        if (code != 0) return NativeSpeechPacket(error = code, errorMessage = root["message"]?.jsonPrimitive?.contentOrNull)
        val finished = root["final"]?.jsonPrimitive?.intOrNull == 1
        val result = root["result"] as? JsonObject ?: return NativeSpeechPacket(finished = finished)
        val id = root["sentence_id"]?.jsonPrimitive?.contentOrNull?.takeIf { it.isNotBlank() }
            ?: error("Missing Tencent translation sentence id")
        return NativeSpeechPacket(finished = finished, translations = listOf(TencentSpeechTranslationResult(id,
            result["source_text"]?.jsonPrimitive?.contentOrNull.orEmpty(),
            result["target_text"]?.jsonPrimitive?.contentOrNull.orEmpty(),
            result["sentence_end"]?.jsonPrimitive?.booleanOrNull == true)))
    }
}

internal class TencentSpeechTranslationItems {
    private data class Item(val segment: Long, var source: String = "", var target: String = "", var final: Boolean = false)
    private val items = linkedMapOf<String, Item>()
    private var nextId = 0L
    fun reset() { items.clear() }
    fun accept(result: TencentSpeechTranslationResult): SpeechEvent? {
        val item = items.getOrPut(result.id) { Item(nextId++) }
        if (item.final) return null
        val source = result.source.ifEmpty { item.source }
        val target = result.target.ifEmpty { item.target }
        if (!result.final && source == item.source && target == item.target) return null
        item.source = source; item.target = target; item.final = result.final
        while (items.size > 256) items.remove(items.keys.first())
        return SpeechEvent(item.segment, source, result.final, providerTranslation = target,
            providerTranslationFailed = result.final && target.isBlank())
            .takeIf { source.isNotBlank() || target.isNotBlank() }
    }
}

class AccessibilityScreenshotter : Screenshotter {
    private val released = AtomicBoolean(false)
    override val isReady: Boolean
        get() = !released.get() && GameOcrAccessibilityService.isScreenshotReady()

    override suspend fun capture(): Bitmap? = requestMutex.withLock {
        if (!isReady) {
            Timber.w("[a11y-capture] service disconnected or screenshot capability unavailable")
            return@withLock null
        }
        delay(pacing.delayBeforeRequest(SystemClock.uptimeMillis()))
        if (!isReady) return@withLock null
        pacing.requestStarted(SystemClock.uptimeMillis())
        val unconsumed = AtomicReference<Bitmap?>(null)
        try {
            val frame = withTimeoutOrNull(5_000L) {
                withContext(Dispatchers.Default) { capturePlatformScreenshot(unconsumed) }
            }
            if (frame == null || released.get()) {
                Timber.w("[a11y-capture] no frame (failure, disconnect or timeout)")
                null
            } else {
                unconsumed.set(null)
                frame
            }
        } finally {
            // Also covers cancellation during the withContext/timeout result handoff.
            unconsumed.getAndSet(null)?.recycle()
        }
    }

    private suspend fun capturePlatformScreenshot(unconsumed: AtomicReference<Bitmap?>): Bitmap? {
        if (Build.VERSION.SDK_INT < 30) return null
        val service = GameOcrAccessibilityService.screenshotServiceOrNull() ?: return null
        return suspendCancellableCoroutine { continuation ->
            try {
                service.takeScreenshot(Display.DEFAULT_DISPLAY, callbackExecutor,
                    object : AccessibilityService.TakeScreenshotCallback {
                        override fun onSuccess(result: AccessibilityService.ScreenshotResult) {
                            val buffer = result.hardwareBuffer
                            var hardwareBitmap: Bitmap? = null
                            var bitmap: Bitmap? = null
                            try {
                                if (continuation.isActive && !released.get() &&
                                    GameOcrAccessibilityService.screenshotServiceOrNull() === service) {
                                    hardwareBitmap = Bitmap.wrapHardwareBuffer(buffer, result.colorSpace)
                                    bitmap = hardwareBitmap?.copy(Bitmap.Config.ARGB_8888, false)
                                    unconsumed.set(bitmap)
                                }
                            } catch (error: Exception) {
                                Timber.w(error, "[a11y-capture] bitmap conversion failed")
                            } finally {
                                hardwareBitmap?.recycle()
                                buffer.close()
                            }
                            if (!continuation.isActive || released.get()) {
                                bitmap?.recycle()
                                if (continuation.isActive) continuation.resume(null)
                            } else {
                                @OptIn(kotlinx.coroutines.ExperimentalCoroutinesApi::class)
                                continuation.resume(bitmap, onCancellation = { _, unclaimed, _ -> unclaimed?.recycle() })
                            }
                        }

                        override fun onFailure(errorCode: Int) {
                            Timber.w("[a11y-capture] platform failure code=%d", errorCode)
                            if (continuation.isActive) continuation.resume(null)
                        }
                    })
            } catch (error: Exception) {
                Timber.w(error, "[a11y-capture] request failed")
                if (continuation.isActive) continuation.resume(null)
            }
        }
    }

    override fun release() { released.set(true) }

    companion object {
        private val requestMutex = Mutex()
        private val pacing = AccessibilityScreenshotPacing()
        private val callbackExecutor = Executor { command ->
            Dispatchers.Default.dispatch(kotlin.coroutines.EmptyCoroutineContext, command)
        }
    }
}

fun mapBlocksToOcr(
    blocks: List<TextBlock>,
    originalWidth: Int,
    originalHeight: Int,
    counterClockwiseDegrees: Int,
): List<TextBlock> {
    val angle = normalizeAngle(counterClockwiseDegrees)
    if (angle == 0) return blocks
    return blocks.map { block ->
        block.copy(
            boundingBox = mapRectToOcr(
                block.boundingBox,
                originalWidth,
                originalHeight,
                angle,
            ),
            sourceBoxes = block.sourceBoxes.map { box ->
                mapRectToOcr(box, originalWidth, originalHeight, angle)
            },
            presentationRotationDegrees = 0,
        )
    }
}

fun mapPatchesToOriginal(
    patches: List<ShapeAwareBubblePatch>,
    originalImageWidth: Int,
    originalImageHeight: Int,
    counterClockwiseDegrees: Int,
): List<ShapeAwareBubblePatch> {
    val angle = normalizeAngle(counterClockwiseDegrees)
    require(originalImageWidth > 0 && originalImageHeight > 0)
    require(canUseOcrSpacePixelMask(angle))
    if (angle == 0 && patches.all {
            it.bounds.left >= 0 && it.bounds.top >= 0 &&
                it.bounds.right <= originalImageWidth && it.bounds.bottom <= originalImageHeight
        }
    ) return patches
    return patches.mapNotNull { patch ->
        val mappedBounds = mapIntRectToOriginal(
            rect = patch.bounds,
            originalWidth = originalImageWidth,
            originalHeight = originalImageHeight,
            counterClockwiseDegrees = angle,
        )
        if (mappedBounds.width <= 0 || mappedBounds.height <= 0) return@mapNotNull null
        // Pull each visible destination pixel from its OCR coordinate. Clipping only the
        // rectangle would leave the old pixel stride, shifting the mask or crashing creation.
        val pixels = IntArray(mappedBounds.width * mappedBounds.height)
        for (y in 0 until mappedBounds.height) for (x in 0 until mappedBounds.width) {
            val originalX = mappedBounds.left + x
            val originalY = mappedBounds.top + y
            val sourceX = when (angle) {
                90 -> originalY
                180 -> originalImageWidth - 1 - originalX
                270 -> originalImageHeight - 1 - originalY
                else -> originalX
            } - patch.bounds.left
            val sourceY = when (angle) {
                90 -> originalImageWidth - 1 - originalX
                180 -> originalImageHeight - 1 - originalY
                270 -> originalX
                else -> originalY
            } - patch.bounds.top
            pixels[y * mappedBounds.width + x] = patch.pixels[sourceY * patch.bounds.width + sourceX]
        }
        patch.copy(
            bounds = mappedBounds,
            pixels = pixels,
        )
    }
}

val pixels = IntArray(mappedBounds.width * mappedBounds.height)
for (y in 0 until mappedBounds.height) for (x in 0 until mappedBounds.width) {
    val originalX = mappedBounds.left + x
    val originalY = mappedBounds.top + y
    val sourceX = when (angle) {
        90 -> originalY
        180 -> originalImageWidth - 1 - originalX
        270 -> originalImageHeight - 1 - originalY
        else -> originalX
    } - patch.bounds.left
    val sourceY = when (angle) {
        90 -> originalImageWidth - 1 - originalX
        180 -> originalImageHeight - 1 - originalY
        270 -> originalX
        else -> originalY
    } - patch.bounds.top
    pixels[y * mappedBounds.width + x] = patch.pixels[sourceY * patch.bounds.width + sourceX]
}

@Serializable
data class CaptureRegion(
    val left: Int,
    val top: Int,
    val right: Int,
    val bottom: Int
) {
    val width: Int get() = right - left
    val height: Int get() = bottom - top
    fun isValid(): Boolean = width > 8 && height > 8
}

internal fun resizedCaptureRegion(
    region: CaptureRegion,
    corner: CaptureRegionResizeCorner,
    deltaX: Int,
    deltaY: Int,
    screenWidth: Int,
    screenHeight: Int,
    minSidePx: Int,
): CaptureRegion? {
    if (!region.isValid() || screenWidth <= 0 || screenHeight <= 0) return null
    val minSide = minSidePx.coerceAtLeast(9)
    if (minSide > screenWidth || minSide > screenHeight) return null

    var left = region.left.coerceIn(0, screenWidth)
    var top = region.top.coerceIn(0, screenHeight)
    var right = region.right.coerceIn(0, screenWidth)
    var bottom = region.bottom.coerceIn(0, screenHeight)
    if (right - left < minSide || bottom - top < minSide) return null

    when (corner) {
        CaptureRegionResizeCorner.TOP_LEFT -> {
            left = (region.left.toLong() + deltaX.toLong())
                .coerceIn(0L, (right - minSide).toLong()).toInt()
            top = (region.top.toLong() + deltaY.toLong())
                .coerceIn(0L, (bottom - minSide).toLong()).toInt()
        }
        CaptureRegionResizeCorner.TOP_RIGHT -> {
            right = (region.right.toLong() + deltaX.toLong())
                .coerceIn((left + minSide).toLong(), screenWidth.toLong()).toInt()
            top = (region.top.toLong() + deltaY.toLong())
                .coerceIn(0L, (bottom - minSide).toLong()).toInt()
        }
        CaptureRegionResizeCorner.BOTTOM_LEFT -> {
            left = (region.left.toLong() + deltaX.toLong())
                .coerceIn(0L, (right - minSide).toLong()).toInt()
            bottom = (region.bottom.toLong() + deltaY.toLong())
                .coerceIn((top + minSide).toLong(), screenHeight.toLong()).toInt()
        }
        CaptureRegionResizeCorner.BOTTOM_RIGHT -> {
            right = (region.right.toLong() + deltaX.toLong())
                .coerceIn((left + minSide).toLong(), screenWidth.toLong()).toInt()
            bottom = (region.bottom.toLong() + deltaY.toLong())
                .coerceIn((top + minSide).toLong(), screenHeight.toLong()).toInt()
        }
    }
    return CaptureRegion(left, top, right, bottom)
}

@Singleton
class CaptureStartCoordinator @Inject constructor(
    @ApplicationContext private val context: Context,
    private val shizuku: ShizukuManager,
    private val permissions: AppPermissionCoordinator,
    private val capabilities: ShizukuCapabilities,
    private val logs: LogRepository,
    private val rootShell: RootShell,
) {
    internal val gate = CaptureStartGate()

    /**
     * [modeOverride] is the method the home one-button setup already resolved and showed, so this
     * launch uses exactly that method once. Without it the session choice ([CaptureStartPreference]) applies.
     */
    internal suspend fun prepare(modeOverride: CaptureStartMode? = null): CaptureStartDecision {
        if (CaptureServiceState.running.value) {
            return CaptureStartDecision.AlreadyRunning
        }
        val preference = modeOverride ?: CaptureStartPreference.mode.value
        // Root comes first in Auto. A refusal is remembered for the session, so Auto then moves on.
        rootShell.refreshInstalled()
        val rootFirst = resolveCaptureStartMode(
            preference, rootUsableForAuto(rootShell.access.value), capabilities.availability(context),
            Build.VERSION.SDK_INT, AccessibilityServiceStatus.isEnabled(context),
        ) == CaptureStartMode.ROOT
        if (rootFirst) {
            if (rootShell.ensureGranted()) return prepareRoot()
            if (preference == CaptureStartMode.ROOT) return CaptureStartDecision.OpenSetup
        }
        // Resolve initial asynchronous readiness before choosing a backend, not from a stale UI snapshot.
        if (preference == null || preference == CaptureStartMode.SHIZUKU) shizuku.verifyShellPrivilegeAsync()
        val useShizuku = resolveCaptureStartMode(
            preference.takeUnless { it == CaptureStartMode.ROOT }, false, capabilities.availability(context),
            Build.VERSION.SDK_INT, AccessibilityServiceStatus.isEnabled(context),
        ) == CaptureStartMode.SHIZUKU
        if (useShizuku && !shizuku.ensureReady()) return CaptureStartDecision.OpenSetup
        val permissionState = permissions.currentState()
        if (shouldConfigureCapturePermissions(
                overlayPermissionGranted = permissionState.overlayGranted,
                accessibilityReady = permissionState.accessibilityReady,
                useShizuku = useShizuku,
                availability = capabilities.availability(context),
            )) {
            if (useShizuku) permissions.configure() else permissions.configureIfReady()
        }
        if (!Settings.canDrawOverlays(context)) return CaptureStartDecision.OpenOverlaySettings
        if (CaptureServiceState.running.value) return CaptureStartDecision.AlreadyRunning
        if (useShizuku) return CaptureStartDecision.Ready(CaptureBackend.SHIZUKU)
        if (preference != CaptureStartMode.SYSTEM &&
            Build.VERSION.SDK_INT >= 30 && AccessibilityServiceStatus.isEnabled(context)) {
            repeat(15) {
                if (GameOcrAccessibilityService.isScreenshotReady()) {
                    return CaptureStartDecision.Ready(CaptureBackend.ACCESSIBILITY)
                }
                delay(100)
            }
        }
        val backend = nonShizukuCaptureBackend(preference, Build.VERSION.SDK_INT,
            GameOcrAccessibilityService.isConnected(), GameOcrAccessibilityService.isScreenshotReady())
            ?: return CaptureStartDecision.OpenAccessibilitySettings
        return CaptureStartDecision.Ready(backend)
    }

    /** Root is granted: grant the overlay through root when it is missing, then start. */
    private suspend fun prepareRoot(): CaptureStartDecision {
        // Root-only path: grant the overlay ourselves; the shared Shizuku/system checks are not involved.
        val overlayMissing = !Settings.canDrawOverlays(context)
        if (overlayMissing) {
            rootShell.run("appops set ${context.packageName} SYSTEM_ALERT_WINDOW allow")
            for (attempt in 0 until 10) {
                if (Settings.canDrawOverlays(context)) break
                delay(100)
            }
        }
        if (!Settings.canDrawOverlays(context)) return CaptureStartDecision.OpenOverlaySettings
        if (CaptureServiceState.running.value) return CaptureStartDecision.AlreadyRunning
        return CaptureStartDecision.Ready(CaptureBackend.ROOT)
    }

    internal fun start(backend: CaptureBackend, resultCode: Int = 0, data: Intent? = null) {
        if (CaptureServiceState.running.value) return
        require(backend != CaptureBackend.MEDIA_PROJECTION || data != null)
        Timber.i("[capture-start] backend=%s", backend)
        try {
            ContextCompat.startForegroundService(context, Intent(context, CaptureService::class.java).apply {
                action = CaptureService.ACTION_START
                putExtra(CaptureService.EXTRA_CAPTURE_BACKEND, backend.name)
                if (backend == CaptureBackend.MEDIA_PROJECTION) {
                    putExtra(CaptureService.EXTRA_RESULT_CODE, resultCode)
                    putExtra(CaptureService.EXTRA_RESULT_DATA, data)
                }
            })
        } catch (error: Exception) {
            logs.error(LogRepository.Category.CAPTURE, context.getString(R.string.log_msg_capture_failed), error)
            showStartFailure()
        }
    }

    private fun showStartFailure() {
        Toast.makeText(context, R.string.toast_capture_failed, Toast.LENGTH_LONG).show()
    }
}

