class FrameDeduper(private val threshold: Int = 6) {

    private var lastHash: Long = 0L
    private var hasLast = false

    /** 返回是否应跳过这一帧（true = 跳过）。同时更新内部缓存。 */
    fun shouldSkip(bitmap: Bitmap): Boolean {
        val h = dHash(bitmap)
        val skip = hasLast && hammingDistance(h, lastHash) <= threshold
        lastHash = h
        hasLast = true
        return skip
    }

    fun reset() {
        hasLast = false
        lastHash = 0L
    }

    /**
     * dHash：缩小到 9x8 灰度，比较相邻像素，得到 64bit 指纹。
     */
    private fun dHash(src: Bitmap): Long {
        val scaled = Bitmap.createScaledBitmap(src, 9, 8, true)
        var hash = 0L
        for (y in 0 until 8) {
            for (x in 0 until 8) {
                val l = luminance(scaled.getPixel(x, y))
                val r = luminance(scaled.getPixel(x + 1, y))
                hash = (hash shl 1) or (if (l > r) 1L else 0L)
            }
        }
        if (scaled !== src) scaled.recycle()
        return hash
    }

    private fun luminance(argb: Int): Int {
        val r = (argb shr 16) and 0xFF
        val g = (argb shr 8) and 0xFF
        val b = argb and 0xFF
        return (r * 299 + g * 587 + b * 114) / 1000
    }

    private fun hammingDistance(a: Long, b: Long): Int = java.lang.Long.bitCount(a xor b)
}

private fun dHash(src: Bitmap): Long {
    val scaled = Bitmap.createScaledBitmap(src, 9, 8, true)
    var hash = 0L
    for (y in 0 until 8) {
        for (x in 0 until 8) {
            val l = luminance(scaled.getPixel(x, y))
            val r = luminance(scaled.getPixel(x + 1, y))
            hash = (hash shl 1) or (if (l > r) 1L else 0L)
        }
    }
    if (scaled !== src) scaled.recycle()
    return hash
}

internal class LoopCaptureFeedbackPolicy {
    private var lastCaptureId: Long? = null

    @Synchronized
    fun accept(enabled: Boolean, loopActive: Boolean, captureId: Long): Boolean {
        if (!enabled || !loopActive || lastCaptureId == captureId) return false
        lastCaptureId = captureId
        return true
    }

    @Synchronized
    fun reset() { lastCaptureId = null }
}

fun createObservation(
    bitmap: Bitmap,
    contextId: Int,
    excludedRects: List<Rect>,
): SettledPageFrame {
    val visible = SettledPageVisualPolicy.visibility(
        bitmap.width, bitmap.height, SAMPLE_SIZE,
        excludedRects.map { OverlayCaptureRect(it.left, it.top, it.right, it.bottom) },
    )
    return SettledPageFrame(bitmap.width, bitmap.height, contextId, luminanceSample(bitmap, null), visible)
}

val updateToolbarPos: (Rect?) -> Unit = { rect ->
    placeToolbar(container, toolbar, rect)
}

private fun placeToolbar(container: FrameLayout, toolbar: ViewGroup, rect: Rect?) {
    val parentW = container.width
    val parentH = container.height
    val tbW = toolbar.width
    val tbH = toolbar.height
    if (tbW == 0 || tbH == 0 || parentW == 0 || parentH == 0) {
        // 还没测量完，等下一轮 post 再来
        container.post { placeToolbar(container, toolbar, rect) }
        return
    }
    val gap = dp(12)
    val safe = dp(16)
    val lp = toolbar.layoutParams as FrameLayout.LayoutParams

    if (rect != null && rect.width() >= 20 && rect.height() >= 20) {
        var top = rect.bottom + gap
        if (top + tbH > parentH - safe) {
            // 下方空间不够 → 翻到上方
            top = rect.top - gap - tbH
        }
        if (top < safe) {
            // 上方也不够 → 屏幕底部
            top = parentH - safe - tbH
        }
        val left = (rect.centerX() - tbW / 2)
            .coerceIn(safe, parentW - tbW - safe)
        lp.gravity = Gravity.TOP or Gravity.START
        lp.leftMargin = left
        lp.topMargin = top
        lp.rightMargin = 0
        lp.bottomMargin = 0
    } else {
        // 阶段 1 还没框：右下角
        lp.gravity = Gravity.BOTTOM or Gravity.END
        lp.leftMargin = 0
        lp.topMargin = 0
        lp.rightMargin = safe
        lp.bottomMargin = dp(32)
    }
    toolbar.layoutParams = lp
}

    top = rect.top - gap - tbH
}
if (top < safe) {
    // 上方也不够 → 屏幕底部
    top = parentH - safe - tbH
}

