fun refreshInstalled() {
    val present = rootBinaryPresent { File(it).exists() }
    state.value = when {
        !present -> RootAccess.NOT_INSTALLED
        state.value == RootAccess.NOT_INSTALLED -> RootAccess.UNKNOWN
        else -> state.value
    }
}

suspend fun ensureGranted(timeoutMs: Long = GRANT_TIMEOUT_MS): Boolean = mutex.withLock {
    when (state.value) {
        RootAccess.NOT_INSTALLED, RootAccess.DENIED -> return@withLock false
        RootAccess.GRANTED -> if (process?.isAliveCompat() == true) return@withLock true
        RootAccess.UNKNOWN -> Unit
    }
    val granted = withContext(Dispatchers.IO) { openShell(timeoutMs) }
    state.value = if (granted) RootAccess.GRANTED else RootAccess.DENIED
    Timber.i("[root] access=%s", state.value)
    granted
}

suspend fun run(command: String, timeoutMs: Long = COMMAND_TIMEOUT_MS): Boolean {
    if (!ensureGranted()) return false
    return mutex.withLock {
        withContext(Dispatchers.IO) {
            val input = stdout ?: return@withContext false
            val output = stdin ?: return@withContext false
            guarded(timeoutMs) {
                output.write("$command >/dev/null 2>&1; echo \"__ST_RC=\$?\"\n".toByteArray())
                output.flush()
                var line: String
                do {
                    line = readLine(input) ?: return@guarded false
                } while (!line.startsWith("__ST_RC="))
                line.removePrefix("__ST_RC=").trim() == "0"
            } ?: false
        }
    }
}

suspend fun captureRaw(): Bitmap? {
    if (!ensureGranted()) return null
    return mutex.withLock {
        withContext(Dispatchers.IO) {
            val input = stdout ?: return@withContext null
            val output = stdin ?: return@withContext null
            guarded(CAPTURE_TIMEOUT_MS) {
                // A failed screencap prints the marker twice, which fills the 16-byte header read.
                output.write(
                    ("screencap 2>/dev/null || printf '$ROOT_FRAME_MARKER'; " +
                        "printf '$ROOT_FRAME_MARKER'\n").toByteArray()
                )
                output.flush()
                readFrame(input)
            }
        }
    }
}

suspend fun capturePng(): Bitmap? = withContext(Dispatchers.IO) {
    if (!isGranted) return@withContext null
    runCatching {
        val png = ProcessBuilder("su", "-c", "screencap -p").start()
        val bytes = png.inputStream.use { it.readBytes() }
        png.waitFor(CAPTURE_TIMEOUT_MS, TimeUnit.MILLISECONDS)
        png.destroy()
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }.onFailure { Timber.w(it, "[root] png fallback failed") }.getOrNull()
}

private inline fun <T> guarded(timeoutMs: Long, block: () -> T?): T? {
    val shell = process ?: return null
    val finished = AtomicBoolean(false)
    val watchdog = watchdogScope.launch {
        delay(timeoutMs)
        if (!finished.get()) {
            Timber.w("[root] command timed out; restarting shell")
            shell.destroy()
        }
    }
    return try {
        block().also { finished.set(true) }
    } catch (error: Exception) {
        Timber.w(error, "[root] shell failed; it will be reopened")
        close()
        if (state.value == RootAccess.GRANTED) state.value = RootAccess.UNKNOWN
        null
    } finally {
        watchdog.cancel()
    }
}

class RootScreenshotter(private val shell: RootShell) : Screenshotter {
    private val released = AtomicBoolean(false)

    override val isReady: Boolean
        get() = !released.get() && shell.isGranted

    override val minimumLoopObservationIntervalMs: Long
        get() = MIN_LOOP_OBSERVATION_INTERVAL_MS

    override suspend fun capture(): Bitmap? {
        if (released.get()) return null
        shell.captureRaw()?.let { return it }
        Timber.w("[root] raw capture failed; trying PNG")
        return shell.capturePng()
    }

    override fun release() {
        released.set(true)
    }

    private companion object {
        const val MIN_LOOP_OBSERVATION_INTERVAL_MS = 250L
    }
}

interface Screenshotter {

    /** 是否已就绪：MediaProjection 已授权且 VirtualDisplay 已建好。 */
    val isReady: Boolean

    /** Backend-specific lower bound for repeated lightweight page observations. */
    val minimumLoopObservationIntervalMs: Long
        get() = 0L

    /** 抓一帧。返回 null 表示这一帧没有就绪 / 上一帧没变化，调用方应跳过。 */
    suspend fun capture(): Bitmap?

    /** 释放资源（VirtualDisplay、ImageReader、MediaProjection token）。 */
    fun release()
}

internal class SettledPagePolicy {
    data class Decision(
        val revision: Long,
        val invalidatePrevious: Boolean,
        val replaceAnchor: Boolean,
        val ready: Boolean,
    )

    private var revision = 0L
    private var hasAnchor = false
    private var stableSinceMs = 0L
    private var lastObservationMs: Long? = null
    private var submittedRevision: Long? = null
    private var readyRevision: Long? = null
    private var observationPaused = false

    @Synchronized
    fun observe(
        sameAsAnchor: Boolean,
        contextUnchanged: Boolean,
        nowMs: Long,
        stableDurationMs: Long,
    ): Decision {
        val clockWentBack = lastObservationMs?.let { nowMs < it } == true
        lastObservationMs = nowMs
        val changed = !hasAnchor || !contextUnchanged || !sameAsAnchor || clockWentBack
        if (observationPaused) stableSinceMs = nowMs
        observationPaused = false
        if (changed) {
            val invalidate = hasAnchor
            revision++
            hasAnchor = true
            stableSinceMs = nowMs
            submittedRevision = null
            readyRevision = null
            return Decision(revision, invalidate, replaceAnchor = true, ready = false)
        }
        val ready = submittedRevision != revision &&
            nowMs - stableSinceMs >= stableDurationMs.coerceAtLeast(1L)
        readyRevision = revision.takeIf { ready }
        return Decision(
            revision,
            invalidatePrevious = false,
            replaceAnchor = false,
            ready = ready,
        )
    }

    /** Claim only after an execution slot is available; never queue intermediate pages. */
    @Synchronized
    fun claim(expectedRevision: Long): Boolean {
        if (!hasAnchor || expectedRevision != revision || readyRevision != revision || submittedRevision == revision) return false
        submittedRevision = revision
        return true
    }

    @Synchronized
    fun accepts(expectedRevision: Long): Boolean = hasAnchor && expectedRevision == revision

    /** Occlusion is not a page turn. Preserve the displayed/submitted page but restart settling. */
    @Synchronized
    fun pauseObservation(nowMs: Long) {
        observationPaused = true
        stableSinceMs = nowMs
        lastObservationMs = nowMs
        readyRevision = null
    }

    /** A discontinuity (sleep, lost capture session, stopped loop) invalidates pending results. */
    @Synchronized
    fun reset() {
        revision++
        hasAnchor = false
        stableSinceMs = 0L
        lastObservationMs = null
        submittedRevision = null
        readyRevision = null
        observationPaused = false
    }
}

@Synchronized
fun claim(expectedRevision: Long): Boolean {
    if (!hasAnchor || expectedRevision != revision || readyRevision != revision || submittedRevision == revision) return false
    submittedRevision = revision
    return true
}

@Synchronized
fun pauseObservation(nowMs: Long) {
    observationPaused = true
    stableSinceMs = nowMs
    lastObservationMs = nowMs
    readyRevision = null
}

@Synchronized
fun reset() {
    revision++
    hasAnchor = false
    stableSinceMs = 0L
    lastObservationMs = null
    submittedRevision = null
    readyRevision = null
    observationPaused = false
}

fun similarity(a: SettledPageFrame, b: SettledPageFrame): Float? {
    if (!comparable(a, b) || a.luminance.isEmpty() ||
        a.visible.size != a.luminance.size || b.visible.size != b.luminance.size
    ) return null
    var count = 0
    var difference = 0L
    for (i in a.luminance.indices) {
        if (!a.visible[i] || !b.visible[i]) continue
        count++
        difference += abs((a.luminance[i].toInt() and 255) - (b.luminance[i].toInt() and 255))
    }
    if (count == 0 || count.toFloat() / a.luminance.size < MIN_VISIBLE_FRACTION) return null
    return (1.0 - difference.toDouble() / (count.toLong() * 255L)).toFloat().coerceIn(0f, 1f)
}

internal object ShizukuRawScreencapDecoder {

    private const val LEGACY_HEADER_BYTES = 12
    private const val COLORSPACE_HEADER_BYTES = 16
    private const val UNKNOWN_COLORSPACE = 0
    private const val MAX_DIMENSION = 10_000
    private const val MAX_PIXELS = 25_000_000

    internal data class FrameSpec(
        val width: Int,
        val height: Int,
        val pixelFormat: Int,
        val colorspace: Int,
        val headerBytes: Int,
        val bytesPerPixel: Int,
        val bitmapEncoding: BitmapEncoding
    ) {
        val pixelByteCount: Int = width * height * bytesPerPixel
    }

    internal data class HeaderProbe(
        val width: Int,
        val height: Int,
        val pixelFormat: Int,
        val pixelByteCount: Int,
    )

    internal enum class BitmapEncoding {
        ARGB_8888_DIRECT,
        RGB_565_DIRECT,
        RGB_888_TO_ARGB_8888
    }

    fun decode(bytes: ByteArray): Bitmap? {
        val spec = parse(bytes) ?: return null
        val offset = spec.headerBytes
        return when (spec.bitmapEncoding) {
            BitmapEncoding.ARGB_8888_DIRECT -> Bitmap
                .createBitmap(spec.width, spec.height, Bitmap.Config.ARGB_8888)
                .also { bitmap ->
                    bitmap.copyPixelsFromBuffer(
                        ByteBuffer.wrap(bytes, offset, spec.pixelByteCount)
                    )
                }

            BitmapEncoding.RGB_565_DIRECT -> Bitmap
                .createBitmap(spec.width, spec.height, Bitmap.Config.RGB_565)
                .also { bitmap ->
                    bitmap.copyPixelsFromBuffer(
                        ByteBuffer.wrap(bytes, offset, spec.pixelByteCount)
                    )
                }

            BitmapEncoding.RGB_888_TO_ARGB_8888 -> decodeRgb888(spec, bytes, offset)
        }
    }

    /**
     * Reads only the common 12-byte prefix so the caller can allocate the final raw-frame buffer
     * once. Current frames use a 16-byte header; legacy frames are exactly four bytes shorter.
     */
    internal fun probeHeader(prefix: ByteArray): HeaderProbe? {
        if (prefix.size < LEGACY_HEADER_BYTES) return null
        val width = readIntLe(prefix, 0)
        val height = readIntLe(prefix, 4)
        val format = readIntLe(prefix, 8)
        val encoding = encodingFor(format) ?: return null
        if (!isPlausibleDimensions(width, height)) return null
        val pixelBytes = width.toLong() * height.toLong() * encoding.bytesPerPixel
        if (pixelBytes > Int.MAX_VALUE) return null
        return HeaderProbe(width, height, format, pixelBytes.toInt())
    }

    internal fun parse(bytes: ByteArray): FrameSpec? =
        parseCandidate(bytes, COLORSPACE_HEADER_BYTES, requireExactPayload = true)
            ?: parseCandidate(bytes, LEGACY_HEADER_BYTES, requireExactPayload = true)
            ?: parseCandidate(bytes, COLORSPACE_HEADER_BYTES, requireExactPayload = false)

    private fun parseCandidate(
        bytes: ByteArray,
        headerBytes: Int,
        requireExactPayload: Boolean
    ): FrameSpec? {
        if (bytes.size < headerBytes) return null
        val probe = probeHeader(bytes) ?: return null
        val width = probe.width
        val height = probe.height
        val format = probe.pixelFormat
        val colorspace = if (headerBytes >= COLORSPACE_HEADER_BYTES) {
            readIntLe(bytes, 12)
        } else {
            UNKNOWN_COLORSPACE
        }
        val encoding = requireNotNull(encodingFor(format))
        val expectedPayload = probe.pixelByteCount
        val actualPayload = bytes.size - headerBytes
        if (requireExactPayload) {
            if (actualPayload != expectedPayload) return null
        } else if (actualPayload < expectedPayload) {
            return null
        }

        return FrameSpec(
            width = width,
            height = height,
            pixelFormat = format,
            colorspace = colorspace,
            headerBytes = headerBytes,
            bytesPerPixel = encoding.bytesPerPixel,
            bitmapEncoding = encoding.bitmapEncoding
        )
    }

    private fun isPlausibleDimensions(width: Int, height: Int): Boolean {
        if (width <= 0 || height <= 0) return false
        if (width > MAX_DIMENSION || height > MAX_DIMENSION) return false
        return width.toLong() * height.toLong() <= MAX_PIXELS
    }

    private fun encodingFor(format: Int): PixelEncoding? = when (format) {
        PixelFormat.RGBA_8888,
        PixelFormat.RGBX_8888 -> PixelEncoding(4, BitmapEncoding.ARGB_8888_DIRECT)
        PixelFormat.RGB_565 -> PixelEncoding(2, BitmapEncoding.RGB_565_DIRECT)
        PixelFormat.RGB_888 -> PixelEncoding(3, BitmapEncoding.RGB_888_TO_ARGB_8888)
        else -> null
    }

    private data class PixelEncoding(
        val bytesPerPixel: Int,
        val bitmapEncoding: BitmapEncoding
    )

    private fun decodeRgb888(spec: FrameSpec, bytes: ByteArray, offset: Int): Bitmap {
        val pixels = IntArray(spec.width * spec.height)
        var source = offset
        for (i in pixels.indices) {
            val r = bytes[source++].toInt() and 0xff
            val g = bytes[source++].toInt() and 0xff
            val b = bytes[source++].toInt() and 0xff
            pixels[i] = (0xff shl 24) or (r shl 16) or (g shl 8) or b
        }
        return Bitmap.createBitmap(pixels, spec.width, spec.height, Bitmap.Config.ARGB_8888)
    }

    private fun readIntLe(bytes: ByteArray, offset: Int): Int =
        (bytes[offset].toInt() and 0xff) or
            ((bytes[offset + 1].toInt() and 0xff) shl 8) or
            ((bytes[offset + 2].toInt() and 0xff) shl 16) or
            ((bytes[offset + 3].toInt() and 0xff) shl 24)
}

