        AsrEngineKind.ZIPFORMER -> emptyList()
        AsrEngineKind.PARAFORMER_CLOUD -> when (provider) {
            // These real-time protocols do not expose a manual source-language parameter.
            AsrCloudProvider.TENCENT -> when {
                connections.tencentModel == TencentAsrModel.STANDARD -> TencentSpeechLanguagePolicy.standard
                connections.tencentModel.translatesSpeech -> TencentSpeechLanguagePolicy.translation
                else -> listOf(AsrLanguage.AUTO)
            }
            AsrCloudProvider.VOLCENGINE -> listOf(AsrLanguage.AUTO)
            AsrCloudProvider.OPENAI_COMPATIBLE -> {
                val model = connections.openAiModel.lowercase()
                when {
                    "sensevoice" in model -> senseVoice
                    "qwen3-asr" in model -> qwenRealtime
                    "whisper" in model -> if ("large-v3" in model || "turbo" in model) whisper + AsrLanguage.YUE else whisper
                    // Generic endpoints are user-configured; expose the complete ISO language
                    // catalog, avoiding aliases. The selected server determines actual support.
                    else -> AsrLanguage.entries.filter { it !in setOf(AsrLanguage.JW, AsrLanguage.FIL, AsrLanguage.NB, AsrLanguage.ZH_EN, AsrLanguage.ZH_TW) }
                }
            }
            AsrCloudProvider.ALIYUN -> when (cloudModel) {
                AsrCloudModel.PARAFORMER -> paraformer
                AsrCloudModel.QWEN_AUDIO_STREAMING, AsrCloudModel.FUN_ASR -> streaming
                AsrCloudModel.QWEN_ASR_REALTIME -> qwenRealtime
                AsrCloudModel.QWEN_LIVE_TRANSLATE_35 -> liveTranslate
                AsrCloudModel.QWEN_LIVE_TRANSLATE_38 -> listOf(AsrLanguage.AUTO)
            }
        }
    }

    fun effective(engine: AsrEngineKind, language: AsrLanguage, cloudModel: AsrCloudModel = AsrCloudModel.PARAFORMER,
        provider: AsrCloudProvider = AsrCloudProvider.ALIYUN,
        connections: AsrCloudConnections = AsrCloudConnections()): AsrLanguage =
        options(engine, cloudModel, provider, connections).let { options ->
            language.takeIf { it in options } ?: options.firstOrNull() ?: AsrLanguage.AUTO
        }
}

object TencentSpeechLanguagePolicy {
    val standard = "zh zh-TW en yue ko ja th id vi ms fil pt tr ar es hi fr de".split(" ").map { code -> AsrLanguage.entries.single { it.code == code } }
    val translation = listOf(AsrLanguage.ZH, AsrLanguage.EN, AsrLanguage.ZH_EN, AsrLanguage.JA,
        AsrLanguage.KO, AsrLanguage.YUE, AsrLanguage.ID, AsrLanguage.TH, AsrLanguage.RU)
    fun standardEngine(language: AsrLanguage): String {
        require(language in standard)
        return "16k_${language.code}"
    }
    fun target(value: String): String = value.trim().lowercase(java.util.Locale.ROOT).let {
        if (it == "zh_en") it else it.replace('_', '-').substringBefore('-')
    }
    fun supports(source: AsrLanguage, targetValue: String): Boolean {
        val allowed = when (source) {
            AsrLanguage.ZH, AsrLanguage.EN -> setOf("zh", "en", "ja", "ko", "yue", "id", "th")
            AsrLanguage.ZH_EN -> setOf("zh_en", "zh", "en", "ja", "ko", "yue", "id", "th")
            AsrLanguage.JA, AsrLanguage.KO, AsrLanguage.YUE -> setOf("zh", "en", "ja", "ko", "yue")
            AsrLanguage.ID -> setOf("zh", "en", "id")
            AsrLanguage.TH -> setOf("zh", "en", "th")
            AsrLanguage.RU -> setOf("zh", "en", "ru")
            else -> emptySet()
        }
        return target(targetValue) in allowed
    }
}

object AutoOcrLanguageListPolicy {
    private val defaults = setOf("zh", "ja", "en", "ko")

    private fun catalog(languages: List<Language>): List<Language> = languages
        .filterNot { AutoOcrSettings.languageKey(it.code) == "auto" }
        .distinctBy { AutoOcrSettings.languageKey(it.code) }

    fun isDefault(code: String): Boolean = AutoOcrSettings.languageKey(code) in defaults

    fun visible(settings: AutoOcrSettings, languages: List<Language> = Languages.ALL): List<Language> {
        val normalized = settings.normalized()
        val selected = defaults + normalized.additionalLanguages
        return catalog(languages).filter { AutoOcrSettings.languageKey(it.code) in selected }
    }

    fun addable(settings: AutoOcrSettings, languages: List<Language> = Languages.ALL): List<Language> {
        val selected = visible(settings, languages).mapTo(mutableSetOf()) { AutoOcrSettings.languageKey(it.code) }
        return catalog(languages).filterNot { AutoOcrSettings.languageKey(it.code) in selected }
    }

    fun add(settings: AutoOcrSettings, language: String): AutoOcrSettings {
        val key = AutoOcrSettings.languageKey(language)
        if (addable(settings).none { AutoOcrSettings.languageKey(it.code) == key }) return settings
        return settings.copy(additionalLanguages = settings.additionalLanguages + key).normalized()
    }

    fun remove(settings: AutoOcrSettings, language: String): AutoOcrSettings {
        val key = AutoOcrSettings.languageKey(language)
        if (key in defaults) return settings
        return settings.copy(
            routes = settings.routes.filterKeys { AutoOcrSettings.languageKey(it) != key },
            additionalLanguages = settings.additionalLanguages.filterNot { AutoOcrSettings.languageKey(it) == key },
        ).normalized()
    }
}

    val additionalLanguages: List<String> = emptyList(),
) {
    fun normalized() = copy(
        routes = routes.entries
            .filter { (code, route) -> code.isNotBlank() && languageKey(code) != "auto" &&
                route.engine != OcrEngineKind.ML_KIT_AUTO }
            .associate { (code, route) -> languageKey(code) to route }
            .toSortedMap(),
        additionalLanguages = additionalLanguages.map(::languageKey)
            .filter { it.isNotBlank() && it != "auto" && it != "und" }
            .distinct().sorted(),
    )

    fun routeFor(language: String): AutoOcrRoute? =
        routes[languageKey(language)] ?: defaultRoute(language)

    companion object {
        fun languageKey(code: String): String = code.trim().replace('_', '-')
            .lowercase(Locale.ROOT).substringBefore('-').let {
                when (it) { "iw" -> "he"; "in" -> "id"; "nb" -> "no"; else -> it }
            }

        fun defaultRoute(language: String): AutoOcrRoute? {
            val code = languageKey(language)
            if (code.isBlank() || code == "auto" || code == "und") return null
            OcrLanguageCapability.preferredPaddleModelVersion(code)?.let {
                return AutoOcrRoute(OcrEngineKind.PADDLE_ONNX, it)
            }
            val engine = when (code) {
                "zh" -> OcrEngineKind.ML_KIT_CHINESE
                "ja" -> OcrEngineKind.ML_KIT_JAPANESE
                "ko" -> OcrEngineKind.ML_KIT_KOREAN
                "hi", "mr", "ne", "sa" -> OcrEngineKind.ML_KIT_DEVANAGARI
                else -> OcrEngineKind.ML_KIT_LATIN.takeIf {
                    OcrLanguageCapability.supports(it, code)
                }
            }
            if (engine != null) return AutoOcrRoute(engine)
            return AutoOcrRoute(OcrEngineKind.PADDLE_ONNX).takeIf {
                OcrLanguageCapability.supports(it.engine, code, paddleModelVersion = it.paddleVersion)
            }
        }
    }
}

object AutoOcrRoutingPolicy {
    val candidates: List<AutoOcrRoute> = OcrEngineCatalog.automaticRoutes()

    fun settingsFor(settings: Settings, language: String, route: AutoOcrRoute): Settings {
        val code = AutoOcrSettings.languageKey(language)
        return settings.copy(
            sourceLang = if (route.engine == OcrEngineKind.TENCENT && code == "no") "nb" else code,
            ocrEngine = route.engine,
            paddleModelVersion = if (route.engine == OcrEngineKind.MANGA_OCR_JA) {
                PaddleModelVersion.V6_SMALL
            } else route.paddleVersion,
            baiduOcrLanguage = if (code == "zh") BaiduOcrLanguage.CHN_ENG else BaiduOcrLanguage.entries.firstOrNull {
                it.bcp47 == code && it.supportedOn(settings.baiduOcrEndpoint)
            } ?: settings.baiduOcrLanguage,
            tencentOcrLanguage = if (code == "zh" || code == "en") TencentOcrLanguage.AUTO else TencentOcrLanguage.entries.firstOrNull {
                it.bcp47?.let(AutoOcrSettings::languageKey) == code && it.supportedOn(settings.tencentOcrEndpoint)
            } ?: settings.tencentOcrLanguage,
        )
    }

    fun supports(settings: Settings, language: String, route: AutoOcrRoute): Boolean {
        if (route.engine == OcrEngineKind.ML_KIT_AUTO) return false
        val effective = settingsFor(settings, language, route)
        return OcrLanguageCapability.supports(effective, effective.sourceLang)
    }

    fun options(settings: Settings, language: String): List<AutoOcrRoute> =
        candidates.filter { supports(settings, language, it) }

    fun configured(settings: Settings, route: AutoOcrRoute): Boolean = when (route.engine) {
        OcrEngineKind.BAIDU -> settings.baiduOcrApiKey.isNotBlank() && settings.baiduOcrSecretKey.isNotBlank()
        OcrEngineKind.TENCENT -> settings.tencentSecretId.isNotBlank() && settings.tencentSecretKey.isNotBlank()
        OcrEngineKind.YOUDAO -> settings.youdaoAppKey.isNotBlank() && settings.youdaoAppSecret.isNotBlank()
        OcrEngineKind.PADDLE_AI_STUDIO -> settings.paddleAiStudioToken.isNotBlank()
        OcrEngineKind.UMI_OCR -> settings.umiOcrBaseUrl.isNotBlank()
        OcrEngineKind.LUNA_OCR -> settings.lunaOcrBaseUrl.isNotBlank()
        OcrEngineKind.ML_KIT_AUTO -> false
        else -> true
    }

    /** Never invent a cloud fallback. An unavailable override falls back to a built-in local route. */
    fun resolve(settings: Settings, language: String, ready: (AutoOcrRoute) -> Boolean): AutoOcrRoute? {
        val selected = settings.autoOcr.routeFor(language)
        if (selected != null && supports(settings, language, selected) &&
            configured(settings, selected) && ready(selected)) return selected
        return AutoOcrSettings.defaultRoute(language)?.takeIf { ready(it) }
    }
}

fun resolve(settings: Settings, language: String, ready: (AutoOcrRoute) -> Boolean): AutoOcrRoute? {
    val selected = settings.autoOcr.routeFor(language)
    if (selected != null && supports(settings, language, selected) &&
        configured(settings, selected) && ready(selected)) return selected
    return AutoOcrSettings.defaultRoute(language)?.takeIf { ready(it) }
}

