internal fun languageDisplayName(tag: String, displayLocale: Locale = Locale.getDefault()): String {
    val normalized = tag.trim().replace('_', '-')
    val locale = Locale.forLanguageTag(normalized)
    if (locale.language.isBlank()) return tag
    return locale.getDisplayName(displayLocale).takeIf { it.isNotBlank() } ?: tag
}

fun nameOf(context: Context, code: String): String {
    val lang = ALL.firstOrNull { it.code.equals(code, ignoreCase = true) }
        ?: return languageDisplayName(code, context.resources.configuration.locales[0])
    return context.getString(lang.nameRes)
}

fun search(context: Context, query: String): List<Language> {
    val q = query.trim()
    if (q.isEmpty()) return ALL
    val lower = q.lowercase()
    return ALL.filter {
        context.getString(it.nameRes).contains(q, ignoreCase = true) ||
            it.code.lowercase().contains(lower)
    }
}

@Singleton
class LogRepository @Inject constructor() {

    enum class Level { INFO, WARN, ERROR }
    enum class Category { CAPTURE, OCR, TRANSLATE, CRASH, SPEECH }

    data class Entry(
        /** 全局递增唯一 id。同毫秒并发产生多条日志时也保证不撞，给 LazyColumn 用作稳定 key。 */
        val id: Long,
        val timestamp: Long,
        val level: Level,
        val category: Category,
        val message: String,
        val elapsedMs: Long? = null,
        val imagePath: String? = null,
        /** 可选：OCR / 翻译这种场景的源文本。 */
        val source: String? = null,
        /** 可选：翻译完成后的译文。 */
        val translated: String? = null
    )

    private val idGen = AtomicLong(0)
    private val _entries = MutableStateFlow<List<Entry>>(emptyList())
    val entries: StateFlow<List<Entry>> = _entries.asStateFlow()

    /** App 内运行日志在 Debug / Release 都保留；系统 Logcat 由构建类型单独控制。 */
    @Volatile
    internal var verboseEnabled: Boolean = true

    internal fun configureVerbose(developerOptionsEnabled: Boolean) {
        verboseEnabled = RuntimeLogPolicy.verboseEnabled(
            debugBuild = false,
            developerOptionsEnabled = developerOptionsEnabled,
        )
    }

    fun info(
        category: Category,
        message: String,
        elapsedMs: Long? = null,
        imagePath: String? = null,
        timestamp: Long = System.currentTimeMillis(),
    ) {
        if (!verboseEnabled) return
        add(Level.INFO, category, message, elapsedMs, imagePath, timestamp)
    }

    fun warn(
        category: Category,
        message: String,
        elapsedMs: Long? = null,
        imagePath: String? = null,
        timestamp: Long = System.currentTimeMillis(),
    ) = add(Level.WARN, category, message, elapsedMs, imagePath, timestamp)

    fun error(
        category: Category,
        message: String,
        t: Throwable? = null,
        elapsedMs: Long? = null,
        timestamp: Long = System.currentTimeMillis(),
    ) {
        val full = if (t != null) "$message: ${t.javaClass.simpleName}: ${t.message}" else message
        add(Level.ERROR, category, full, elapsedMs, timestamp = timestamp)
    }

    /** 记录一对"原文 → 译文"（翻译场景）。 */
    fun pair(category: Category, source: String, translated: String, elapsedMs: Long? = null) {
        if (!verboseEnabled) return
        val e = Entry(
            id = idGen.incrementAndGet(),
            timestamp = System.currentTimeMillis(),
            level = Level.INFO,
            category = category,
            elapsedMs = elapsedMs,
            message = "原文 → 译文",
            source = source,
            translated = translated
        )
        push(e)
    }

    fun clear() {
        _entries.value = emptyList()
    }

    private fun add(
        level: Level,
        category: Category,
        message: String,
        elapsedMs: Long?,
        imagePath: String? = null,
        timestamp: Long = System.currentTimeMillis(),
    ) {
        push(
            Entry(
                id = idGen.incrementAndGet(),
                timestamp = timestamp,
                level = level,
                category = category,
                message = message,
                elapsedMs = elapsedMs,
                imagePath = imagePath
            )
        )
    }

    private fun push(e: Entry) {
        val current = _entries.value
        val next = if (current.size >= CAPACITY) {
            // 丢最旧的，append 新的；保留最近 CAPACITY 条
            current.drop(current.size - CAPACITY + 1) + e
        } else {
            current + e
        }
        _entries.value = next
    }

    companion object {
        private const val CAPACITY = 200
    }
}

    current.drop(current.size - CAPACITY + 1) + e
} else {
    current + e
}

object MangaOcrAdvancedSettingsPolicy {
    const val BUBBLE_CLUSTER_GAP: Int = 0
    const val CROP_PADDING_PX: Int = 0

    @Suppress("UNUSED_PARAMETER")
    fun effectiveBubbleClusterGap(storedValue: Int): Int = BUBBLE_CLUSTER_GAP

    @Suppress("UNUSED_PARAMETER")
    fun effectiveCropPaddingPx(storedValue: Int): Int = CROP_PADDING_PX

    fun normalize(settings: Settings): Settings {
        val normalizedPresets = settings.translationPresets.map(::normalize)
        if (
            settings.bubbleClusterGap == BUBBLE_CLUSTER_GAP &&
            settings.mangaOcrCropPaddingPx == CROP_PADDING_PX &&
            normalizedPresets == settings.translationPresets
        ) {
            return settings
        }
        return settings.copy(
            bubbleClusterGap = BUBBLE_CLUSTER_GAP,
            mangaOcrCropPaddingPx = CROP_PADDING_PX,
            translationPresets = normalizedPresets,
        )
    }

    fun normalize(preset: TranslationPreset): TranslationPreset {
        if (
            preset.bubbleClusterGap == BUBBLE_CLUSTER_GAP &&
            preset.mangaOcrCropPaddingPx == CROP_PADDING_PX
        ) {
            return preset
        }
        return TranslationPresetCatalog.fromSettings(
            id = preset.id,
            name = preset.name,
            shortName = preset.shortName,
            settings = preset.applyTo(Settings()),
        )
    }
}

object MangaOcrSettingsPolicy {
    fun normalize(settings: Settings): Settings =
