internal class BoundedHttpBodyCapture(private val enabled: Boolean = true) {
    private val buffer = Buffer()
    private var omitted = false
    internal val retainedBytes: Long get() = buffer.size

    fun copyFrom(source: Buffer, offset: Long, count: Long) {
        if (!enabled || omitted) return
        try {
            if (count > MAX_BYTES - buffer.size) {
                omitted = true
                buffer.clear()
            } else source.copyTo(buffer, offset, count)
        } catch (error: Throwable) {
            // Never later emit a partial body if capturing failed (including memory pressure).
            omitted = true
            buffer.clear()
            throw error
        }
    }

    fun finish(type: MediaType?, complete: Boolean): String = when {
        !enabled -> "<binary>"
        !complete -> "<incomplete body omitted>"
        omitted -> "<body omitted: exceeds $MAX_BYTES bytes>"
        else -> DebugHttpLogSanitizer.payload(buffer.readString(type?.charset(Charsets.UTF_8) ?: Charsets.UTF_8))
    }

    fun clear() = buffer.clear()
    companion object { const val MAX_BYTES = 64L * 1024 }
}

} catch (_: OutOfMemoryError) {
    // In particular, logging must not turn an already-written file into a failed download.
}

internal class NetworkPerformanceEventListener(
    private val host: String,
    private val performanceDiagnostics: RuntimePerformanceDiagnostics,
    private val wakeContext: ScreenWakePerformanceContext? = null,
    private val nowNanos: () -> Long = System::nanoTime,
) : EventListener() {
    private val callStartedAt = nowNanos()
    private var dnsStartedAt: Long? = null
    private var connectStartedAt: Long? = null
    private var tlsStartedAt: Long? = null
    private var requestFinishedAt: Long? = null
    private var dnsNanos = 0L
    private var connectNanos = 0L
    private var tlsNanos = 0L
    private var connectAttempts = 0
    private var summaryLogged = false

    override fun dnsStart(call: Call, domainName: String) {
        dnsStartedAt = nowNanos()
    }

    override fun dnsEnd(call: Call, domainName: String, inetAddressList: List<InetAddress>) {
        dnsStartedAt?.let { dnsNanos += elapsedNanos(it, nowNanos()) }
        dnsStartedAt = null
    }

    override fun connectStart(call: Call, inetSocketAddress: InetSocketAddress, proxy: Proxy) {
        connectAttempts++
        connectStartedAt = nowNanos()
    }

    override fun secureConnectStart(call: Call) {
        tlsStartedAt = nowNanos()
    }

    override fun secureConnectEnd(call: Call, handshake: Handshake?) {
        tlsStartedAt?.let { tlsNanos += elapsedNanos(it, nowNanos()) }
        tlsStartedAt = null
    }

    override fun connectEnd(
        call: Call,
        inetSocketAddress: InetSocketAddress,
        proxy: Proxy,
        protocol: Protocol?,
    ) {
        finishConnectAttempt()
    }

    override fun connectFailed(
        call: Call,
        inetSocketAddress: InetSocketAddress,
        proxy: Proxy,
        protocol: Protocol?,
        ioe: IOException,
    ) {
        finishConnectAttempt()
    }

    override fun requestHeadersEnd(call: Call, request: okhttp3.Request) {
        requestFinishedAt = nowNanos()
    }

    override fun requestBodyEnd(call: Call, byteCount: Long) {
        requestFinishedAt = nowNanos()
    }

    override fun responseHeadersEnd(call: Call, response: Response) {
        logSummary(outcome = "http_${response.code}", finishedAt = nowNanos())
    }

    override fun callFailed(call: Call, ioe: IOException) {
        logSummary(
            outcome = "failed_${ioe.javaClass.simpleName}",
            finishedAt = nowNanos(),
        )
    }

    private fun finishConnectAttempt() {
        val finishedAt = nowNanos()
        tlsStartedAt?.let { tlsNanos += elapsedNanos(it, finishedAt) }
        tlsStartedAt = null
        connectStartedAt?.let { connectNanos += elapsedNanos(it, finishedAt) }
        connectStartedAt = null
    }

    private fun logSummary(outcome: String, finishedAt: Long) {
        if (summaryLogged) return
        summaryLogged = true
        val timing = NetworkPhaseTiming(
            host = host,
            outcome = outcome,
            headersMs = toMillis(elapsedNanos(callStartedAt, finishedAt)),
            dnsMs = toMillis(dnsNanos),
            connectMs = toMillis(connectNanos),
            tlsMs = toMillis(tlsNanos),
            serverWaitMs = requestFinishedAt?.let { toMillis(elapsedNanos(it, finishedAt)) } ?: 0L,
            reusedConnection = connectAttempts == 0,
            connectAttempts = connectAttempts,
            firstRequestAfterWake = wakeContext != null,
            wakeAgeMs = wakeContext?.wakeAgeMs,
            screenOffDurationMs = wakeContext?.screenOffDurationMs,
            idleConnectionsCleared = wakeContext?.idleConnectionsCleared,
        )
        val message = timing.logMessage()
        Timber.tag(NETWORK_PERF_TAG).i(message)
    }

    private fun elapsedNanos(start: Long, end: Long): Long = (end - start).coerceAtLeast(0L)

    private fun toMillis(nanos: Long): Long = nanos / 1_000_000L

    class Factory(
        private val performanceDiagnostics: RuntimePerformanceDiagnostics,
    ) : EventListener.Factory {
        override fun create(call: Call): EventListener = NetworkPerformanceEventListener(
            host = call.request().url.host,
            performanceDiagnostics = performanceDiagnostics,
            wakeContext = performanceDiagnostics.claimFirstNetworkRequestAfterWake(),
        )
    }
}

internal class ScreenWakeConnectionCleaner(
    private val evictIdleConnections: () -> Int,
    private val onRecovered: (Long?, Int) -> Unit,
    private val onFailure: (Exception) -> Unit,
    private val dispatcher: CoroutineDispatcher = Dispatchers.IO,
) {
    private val lock = Any()
    private val cleanupMutex = Mutex()
    private var scope: CoroutineScope? = null

    fun start() = synchronized(lock) {
        if (scope == null) scope = CoroutineScope(SupervisorJob() + dispatcher)
    }

    fun stop() = synchronized(lock) {
        scope?.cancel()
        scope = null
    }

    fun enqueue(screenOffDurationMs: Long?) = synchronized(lock) {
        val session = scope ?: return@synchronized
        session.launch {
            try {
                cleanupMutex.withLock {
                    coroutineContext.ensureActive()
                    val cleared = evictIdleConnections()
                    // A running socket close cannot be interrupted by coroutine cancellation.
                    // Do not publish its result after stop() or a subsequent start().
                    synchronized(lock) {
                        coroutineContext.ensureActive()
                        if (scope === session) onRecovered(screenOffDurationMs, cleared)
                    }
                }
            } catch (cancelled: CancellationException) {
                throw cancelled
            } catch (error: Exception) {
                synchronized(lock) {
                    coroutineContext.ensureActive()
                    if (scope === session) onFailure(error)
                }
            }
        }
        Unit
    }
}

synchronized(lock) {
    coroutineContext.ensureActive()
    if (scope === session) onRecovered(screenOffDurationMs, cleared)
}

@Singleton
class ScreenWakeNetworkRecovery @Inject constructor(
    @ApplicationContext private val context: Context,
    private val httpClient: OkHttpClient,
    private val performanceDiagnostics: RuntimePerformanceDiagnostics,
) {
    private val lock = Any()
    private var registered = false
    private var state = ScreenWakeRecoveryState()
    private val connectionCleaner = ScreenWakeConnectionCleaner(
        evictIdleConnections = {
            val idleConnections = httpClient.connectionPool.idleConnectionCount()
            httpClient.connectionPool.evictAll()
            idleConnections
        },
        onRecovered = ::onConnectionsCleared,
        onFailure = { Timber.tag(NETWORK_PERF_TAG).w(it, "[network-wake] idle connection cleanup failed") },
    )

    private val receiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            onScreenPowerEvent(intent?.action.toScreenPowerEvent())
        }
    }

    fun start() = synchronized(lock) {
        if (registered) return
        val now = SystemClock.elapsedRealtime()
        val powerManager = context.getSystemService(PowerManager::class.java)
        state = ScreenWakeRecoveryPolicy.initialState(
            isInteractive = powerManager?.isInteractive != false,
            nowElapsedMs = now,
        )
        if (state.recoveryPending) performanceDiagnostics.onScreenOff()
        val filter = IntentFilter().apply {
            addAction(Intent.ACTION_SCREEN_OFF)
            addAction(Intent.ACTION_SCREEN_ON)
            addAction(Intent.ACTION_USER_PRESENT)
        }
        ContextCompat.registerReceiver(
            context,
            receiver,
            filter,
            ContextCompat.RECEIVER_NOT_EXPORTED,
        )
        registered = true
        connectionCleaner.start()
    }

    fun stop() = synchronized(lock) {
        if (!registered) return
        runCatching { context.unregisterReceiver(receiver) }
            .onFailure { Timber.w(it, "Failed to unregister screen wake network recovery") }
        registered = false
        connectionCleaner.stop()
        state = ScreenWakeRecoveryState()
        performanceDiagnostics.resetWakeContext()
    }

    private fun onScreenPowerEvent(event: ScreenPowerEvent) = synchronized(lock) {
        if (!registered) return
        if (event == ScreenPowerEvent.SCREEN_OFF) performanceDiagnostics.onScreenOff()
        val decision = ScreenWakeRecoveryPolicy.transition(
            state = state,
            event = event,
            nowElapsedMs = SystemClock.elapsedRealtime(),
        )
        state = decision.state
        if (!decision.evictIdleConnections) return

        connectionCleaner.enqueue(decision.screenOffDurationMs)
    }

    private fun onConnectionsCleared(screenOffDurationMs: Long?, idleConnections: Int) {
        performanceDiagnostics.onScreenWake(
            screenOffDurationMs = screenOffDurationMs,
            idleConnectionsCleared = idleConnections,
        )
        val message = buildString {
            append("[network-wake] cleared idle cloud connections=")
            append(idleConnections)
            screenOffDurationMs?.let {
                append(" screenOffMs=")
                append(it)
            }
        }
        Timber.tag(NETWORK_PERF_TAG).i(message)
    }

    private fun String?.toScreenPowerEvent(): ScreenPowerEvent = when (this) {
        Intent.ACTION_SCREEN_OFF -> ScreenPowerEvent.SCREEN_OFF
        Intent.ACTION_SCREEN_ON -> ScreenPowerEvent.SCREEN_ON
        Intent.ACTION_USER_PRESENT -> ScreenPowerEvent.USER_PRESENT
        else -> ScreenPowerEvent.OTHER
    }
}

internal enum class ScreenPowerEvent {
    SCREEN_OFF,
    SCREEN_ON,
    USER_PRESENT,
    OTHER,
}

internal object ScreenWakeRecoveryPolicy {
    fun initialState(
        isInteractive: Boolean,
        nowElapsedMs: Long,
    ): ScreenWakeRecoveryState = if (isInteractive) {
        ScreenWakeRecoveryState()
    } else {
        ScreenWakeRecoveryState(
            screenOffAtElapsedMs = nowElapsedMs,
            recoveryPending = true,
        )
    }

    fun transition(
        state: ScreenWakeRecoveryState,
        event: ScreenPowerEvent,
        nowElapsedMs: Long,
    ): ScreenWakeRecoveryDecision = when (event) {
        ScreenPowerEvent.SCREEN_OFF -> ScreenWakeRecoveryDecision(
            state = if (state.recoveryPending) {
                state
            } else {
                ScreenWakeRecoveryState(
                    screenOffAtElapsedMs = nowElapsedMs,
                    recoveryPending = true,
                )
            },
            evictIdleConnections = false,
        )

        ScreenPowerEvent.SCREEN_ON,
        ScreenPowerEvent.USER_PRESENT -> if (state.recoveryPending) {
            ScreenWakeRecoveryDecision(
                state = ScreenWakeRecoveryState(),
                evictIdleConnections = true,
                screenOffDurationMs = state.screenOffAtElapsedMs?.let { startedAt ->
                    (nowElapsedMs - startedAt).coerceAtLeast(0L)
                },
            )
        } else {
            ScreenWakeRecoveryDecision(state, evictIdleConnections = false)
        }

        ScreenPowerEvent.OTHER -> ScreenWakeRecoveryDecision(
            state = state,
            evictIdleConnections = false,
        )
    }
}

internal object ArgbChannelMedian {

    fun fromIndexedColors(
        sourceArgb: IntArray,
        sampleIndices: IntArray,
    ): Int {
        require(sampleIndices.isNotEmpty())
        val alpha = IntArray(CHANNEL_VALUES)
        val red = IntArray(CHANNEL_VALUES)
        val green = IntArray(CHANNEL_VALUES)
        val blue = IntArray(CHANNEL_VALUES)
        sampleIndices.forEach { index ->
            val color = sourceArgb[index]
            alpha[color ushr 24 and CHANNEL_MASK]++
            red[color ushr 16 and CHANNEL_MASK]++
            green[color ushr 8 and CHANNEL_MASK]++
            blue[color and CHANNEL_MASK]++
        }
        val rank = sampleIndices.size / 2
        return argb(
            alpha = valueAtRank(alpha, rank),
            red = valueAtRank(red, rank),
            green = valueAtRank(green, rank),
            blue = valueAtRank(blue, rank),
        )
    }

    private fun valueAtRank(histogram: IntArray, rank: Int): Int {
        var cumulative = 0
        histogram.forEachIndexed { value, count ->
            cumulative += count
            if (cumulative > rank) return value
        }
        error("rank exceeds histogram population")
    }

    private fun argb(alpha: Int, red: Int, green: Int, blue: Int): Int =
        (alpha shl 24) or (red shl 16) or (green shl 8) or blue

    private const val CHANNEL_VALUES = 256
    private const val CHANNEL_MASK = 0xff
}

internal object AutoOcrLanguagePolicy {
    fun choose(text: String, candidates: List<LanguageScore>): String? {
        val letters = text.count(Char::isLetter)
        if (letters < 2) return null
        val sorted = candidates.filter { it.language != "und" && it.confidence.isFinite() }
            .sortedByDescending { it.confidence }
        val best = sorted.firstOrNull() ?: return null
        val code = AutoOcrSettings.languageKey(best.language)
        val kana = text.count { it in '\u3040'..'\u30ff' || it in '\uff65'..'\uff9f' }
        val hangul = text.count { it in '\uac00'..'\ud7af' || it in '\u1100'..'\u11ff' || it in '\u3130'..'\u318f' }
        val han = text.count { it in '\u3400'..'\u9fff' }
        if (kana > 0 && code != "ja") return null
        if (hangul > 0 && code != "ko") return null
        if (code == "ja" && kana == 0 && letters < 8) return null
        // Short shared Han words and Latin UI tokens are insufficient routing evidence.
        if (kana == 0 && hangul == 0 && letters < 4) return null
        val threshold = if (han == letters) 0.85f else 0.65f
        if (best.confidence < threshold) return null
        if (best.confidence - (sorted.getOrNull(1)?.confidence ?: 0f) < 0.15f) return null
        return code
    }

    fun weight(evidence: AutoOcrEvidence): Float = evidence.text.count(Char::isLetter)
        .coerceAtMost(400) * evidence.confidence.takeIf(Float::isFinite)?.coerceIn(0f, 1f).orZero()

    private fun Float?.orZero(): Float = this ?: 0f

    // Language ID describes the recognized string, not whether the pixels were read correctly.
    // Short valid words may be unidentified; a confidently identified hallucination must not
    // receive a 6.7x advantage over them. Apply the same OCR evidence weight to every script.
    fun score(evidence: List<AutoOcrEvidence>): Float = evidence.sumOf {
        weight(it).toDouble()
    }.toFloat()

    fun dominant(evidence: List<AutoOcrEvidence>): String? {
        val total = evidence.sumOf { weight(it).toDouble() }
        if (total < 12) return null
        val grouped = evidence.filter { it.language != null }.groupBy { it.language!! }
            .mapValues { (_, items) -> items.sumOf { weight(it).toDouble() } }
        val top = grouped.maxByOrNull { it.value } ?: return null
        return top.key.takeIf { top.value / total >= 0.75 }
    }

    /** A refinement must not erase readable text with punctuation or a different language. */
    fun canRefine(original: List<AutoOcrEvidence>, refined: AutoOcrEvidence, language: String): Boolean {
        if (refined.text.none(Char::isLetterOrDigit)) return false
        if (refined.language != language) return false
        // A later language-specific pass must not undo the region competition. In particular,
        // an unidentified Chinese/Korean UI label is still valid evidence, not an empty region.
        if (original.any { it.language == null && weight(it) > weight(refined) }) return false
        val targets = original.filter { it.language == language }
        if (targets.isEmpty()) return true
        val previousLetters = targets.sumOf { it.text.count(Char::isLetter) }
        val nextLetters = refined.text.count(Char::isLetter)
        // Reject severe loss; retain the bootstrap rather than guessing that missing text is noise.
        return nextLetters * 2 >= previousLetters
    }
}

fun score(evidence: List<AutoOcrEvidence>): Float = evidence.sumOf {
    weight(it).toDouble()
}

fun canRefine(original: List<AutoOcrEvidence>, refined: AutoOcrEvidence, language: String): Boolean {
    if (refined.text.none(Char::isLetterOrDigit)) return false
    if (refined.language != language) return false
    // A later language-specific pass must not undo the region competition. In particular,
    // an unidentified Chinese/Korean UI label is still valid evidence, not an empty region.
    if (original.any { it.language == null && weight(it) > weight(refined) }) return false
    val targets = original.filter { it.language == language }
    if (targets.isEmpty()) return true
    val previousLetters = targets.sumOf { it.text.count(Char::isLetter) }
    val nextLetters = refined.text.count(Char::isLetter)
    // Reject severe loss; retain the bootstrap rather than guessing that missing text is noise.
    return nextLetters * 2 >= previousLetters
}

internal fun <T> selectAutoOcrRegions(
    candidates: List<T>,
    evidenceOf: (T) -> AutoOcrEvidence,
    overlaps: (T, T) -> Boolean,
): List<T> {
    val ranked = candidates.filter { evidenceOf(it).text.any(Char::isLetterOrDigit) }
        .sortedByDescending { AutoOcrLanguagePolicy.score(listOf(evidenceOf(it))) }
    val selected = mutableListOf<T>()
    for (candidate in ranked) {
        if (selected.none { overlaps(candidate, it) }) selected += candidate
    }
    return selected
}

internal fun <T> replaceAutoOcrRegions(
    original: List<T>,
    refined: List<T>,
    language: String,
    languageOf: (T) -> String?,
    overlaps: (T, T) -> Boolean,
): List<T> {
    val targets = original.filter { languageOf(it) == language }
    val otherLanguages = original.filter { languageOf(it) != null && languageOf(it) != language }
    val accepted = refined.filter { candidate ->
        (targets.any { overlaps(candidate, it) } || languageOf(candidate) == language) &&
            otherLanguages.none { overlaps(candidate, it) }
    }
    if (accepted.isEmpty()) return original
    return original.filterNot { old -> accepted.any { overlaps(it, old) } } + accepted
}

