internal object BinarySquareDilation {
    fun dilate(
        input: BooleanArray,
        width: Int,
        height: Int,
        radius: Int,
    ): BooleanArray {
        require(width > 0 && height > 0)
        require(input.size == width * height)
        require(radius >= 0)
        if (radius == 0) return input.copyOf()

        val horizontal = BooleanArray(input.size)
        for (y in 0 until height) {
            val rowOffset = y * width
            var active = 0
            for (x in 0..minOf(radius, width - 1)) {
                if (input[rowOffset + x]) active++
            }
            for (x in 0 until width) {
                horizontal[rowOffset + x] = active > 0
                val leavingX = x - radius
                if (leavingX >= 0 && input[rowOffset + leavingX]) active--
                val enteringX = x + radius + 1
                if (enteringX < width && input[rowOffset + enteringX]) active++
            }
        }

        val output = BooleanArray(input.size)
        for (x in 0 until width) {
            var active = 0
            for (y in 0..minOf(radius, height - 1)) {
                if (horizontal[y * width + x]) active++
            }
            for (y in 0 until height) {
                output[y * width + x] = active > 0
                val leavingY = y - radius
                if (leavingY >= 0 && horizontal[leavingY * width + x]) active--
                val enteringY = y + radius + 1
                if (enteringY < height && horizontal[enteringY * width + x]) active++
            }
        }
        return output
    }
}

object BitmapPreprocessor {

    fun apply(src: Bitmap, opts: PreprocessOptions): Bitmap {
        if (!opts.anyEnabled()) return src
        var cur = src
        if (opts.upscale2x) cur = upscale(cur, 2f).also { if (it !== src) Unit }
        if (opts.invert) {
            val n = invert(cur)
            if (cur !== src) cur.recycle()
            cur = n
        }
        if (opts.binarize) {
            val n = binarizeOtsu(cur)
            if (cur !== src) cur.recycle()
            cur = n
        }
        return cur
    }

    private fun upscale(src: Bitmap, factor: Float): Bitmap {
        val w = (src.width * factor).toInt()
        val h = (src.height * factor).toInt()
        return Bitmap.createScaledBitmap(src, w, h, true)
    }

    /** 颜色反转：通道 → 255 - 通道。alpha 保留。 */
    private fun invert(src: Bitmap): Bitmap {
        val dst = Bitmap.createBitmap(src.width, src.height, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(dst)
        val matrix = ColorMatrix(floatArrayOf(
            -1f, 0f, 0f, 0f, 255f,
            0f, -1f, 0f, 0f, 255f,
            0f, 0f, -1f, 0f, 255f,
            0f, 0f, 0f, 1f, 0f
        ))
        val paint = Paint().apply { colorFilter = ColorMatrixColorFilter(matrix) }
        canvas.drawBitmap(src, 0f, 0f, paint)
        return dst
    }

    /** Otsu 自动阈值二值化。 */
    private fun binarizeOtsu(src: Bitmap): Bitmap {
        val w = src.width
        val h = src.height
        val pixels = IntArray(w * h)
        src.getPixels(pixels, 0, w, 0, 0, w, h)

        val gray = ByteArray(pixels.size)
        val hist = IntArray(256)
        for (i in pixels.indices) {
            val p = pixels[i]
            val r = (p shr 16) and 0xFF
            val g = (p shr 8) and 0xFF
            val b = p and 0xFF
            val v = (r * 299 + g * 587 + b * 114) / 1000
            gray[i] = v.toByte()
            hist[v]++
        }

        val total = pixels.size
        var sum = 0L
        for (t in 0..255) sum += t * hist[t].toLong()
        var sumB = 0L
        var wB = 0
        var maxVar = 0.0
        var threshold = 127
        for (t in 0..255) {
            wB += hist[t]
            if (wB == 0) continue
            val wF = total - wB
            if (wF == 0) break
            sumB += t * hist[t].toLong()
            val mB = sumB.toDouble() / wB
            val mF = (sum - sumB).toDouble() / wF
            val v = wB.toDouble() * wF * (mB - mF) * (mB - mF)
            if (v > maxVar) {
                maxVar = v
                threshold = t
            }
        }

        for (i in pixels.indices) {
            val v = gray[i].toInt() and 0xFF
            val nv = if (v > threshold) 0xFFFFFFFF.toInt() else 0xFF000000.toInt()
            pixels[i] = nv
        }
        val dst = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        dst.setPixels(pixels, 0, w, 0, 0, w, h)
        return dst
    }
}

private fun invert(src: Bitmap): Bitmap {
    val dst = Bitmap.createBitmap(src.width, src.height, Bitmap.Config.ARGB_8888)
    val canvas = Canvas(dst)
    val matrix = ColorMatrix(floatArrayOf(
        -1f, 0f, 0f, 0f, 255f,
        0f, -1f, 0f, 0f, 255f,
        0f, 0f, -1f, 0f, 255f,
        0f, 0f, 0f, 1f, 0f
    ))
    val paint = Paint().apply { colorFilter = ColorMatrixColorFilter(matrix) }
    canvas.drawBitmap(src, 0f, 0f, paint)
    return dst
}

internal object BubbleBackgroundStatistics {

    data class Estimate(
        val red: Int,
        val green: Int,
        val blue: Int,
        val luminance: Int,
        val lowLuminance: Int,
    )

    class Scratch {
        var samples = IntArray(0)
            private set
        private var sorted = IntArray(0)
        private val luminanceCounts = IntArray(CHANNEL_VALUES)
        private val writeOffsets = IntArray(CHANNEL_VALUES)
        private val redCounts = IntArray(CHANNEL_VALUES)
        private val greenCounts = IntArray(CHANNEL_VALUES)
        private val blueCounts = IntArray(CHANNEL_VALUES)

        fun ensureSampleCapacity(required: Int) {
            if (samples.size >= required) return
            val capacity = maxOf(required, samples.size.coerceAtLeast(64) * 2)
            samples = IntArray(capacity)
            sorted = IntArray(capacity)
        }

        fun estimate(
            count: Int,
            brightSampleStartRatio: Float,
            lowSampleRatio: Float,
        ): Estimate {
            require(count in 1..samples.size)
            luminanceCounts.fill(0)
            for (index in 0 until count) luminanceCounts[luminance(samples[index])]++

            var offset = 0
            for (value in 0 until CHANNEL_VALUES) {
                writeOffsets[value] = offset
                offset += luminanceCounts[value]
            }
            // Counting sort is stable because samples are visited in their original order.
            for (index in 0 until count) {
                val color = samples[index]
                val value = luminance(color)
                sorted[writeOffsets[value]++] = color
            }

            val brightestStart = (count * brightSampleStartRatio).roundToInt()
                .coerceIn(0, count - 1)
            redCounts.fill(0)
            greenCounts.fill(0)
            blueCounts.fill(0)
            for (index in brightestStart until count) {
                val color = sorted[index]
                redCounts[color ushr 16 and 0xff]++
                greenCounts[color ushr 8 and 0xff]++
                blueCounts[color and 0xff]++
            }
            val brightestCount = count - brightestStart
            val medianRank = brightestCount / 2
            val red = valueAtRank(redCounts, medianRank)
            val green = valueAtRank(greenCounts, medianRank)
            val blue = valueAtRank(blueCounts, medianRank)
            val lowIndex = ((count - 1) * lowSampleRatio).roundToInt().coerceIn(0, count - 1)
            return Estimate(
                red = red,
                green = green,
                blue = blue,
                luminance = luminance(red, green, blue),
                lowLuminance = luminance(sorted[lowIndex]),
            )
        }
    }

    private fun valueAtRank(histogram: IntArray, rank: Int): Int {
        var cumulative = 0
        histogram.forEachIndexed { value, count ->
            cumulative += count
            if (cumulative > rank) return value
        }
        return CHANNEL_VALUES - 1
    }

    private fun luminance(color: Int): Int = luminance(
        red = color ushr 16 and 0xff,
        green = color ushr 8 and 0xff,
        blue = color and 0xff,
    )

    private fun luminance(red: Int, green: Int, blue: Int): Int =
        (red * 299 + green * 587 + blue * 114) / 1000

    private const val CHANNEL_VALUES = 256
}

