internal object BubbleDetectionModelProvider {
    const val MODEL_FILE_NAME = "detector-v4-s_int8.onnx"
    const val BUNDLED_ASSET_PATH = "models/bubble_detection/$MODEL_FILE_NAME"
    const val MODEL_SOURCE_URL =
        "https://huggingface.co/ogkalu/comic-text-and-bubble-detector"
    const val MODEL_LICENSE = "Apache-2.0"
    const val EXPECTED_BYTES = 11_120_765L
    const val EXPECTED_SHA256 =
        "5FE9E4F576E49D4E7E8B0E029D6D3CDC252ABD4694113E1CAE120E62C931EA79"

    private const val PRIVATE_MODEL_DIRECTORY = "bundled_models/bubble_detection"
    private val lock = Any()
    private var readyStamp: Triple<String, Long, Long>? = null

    fun prepare(context: Context): File? = synchronized(lock) {
        val destination = File(
            context.noBackupFilesDir,
            "$PRIVATE_MODEL_DIRECTORY/$MODEL_FILE_NAME",
        )
        val stamp = destination.stamp()
        if (stamp != null && readyStamp == stamp) return@synchronized destination
        if (validateModelFile(destination) == null) {
            readyStamp = destination.stamp()
            return@synchronized destination
        }

        val directory = destination.parentFile ?: return@synchronized null
        val temporary = File(directory, "$MODEL_FILE_NAME.asset.tmp")
        try {
            directory.mkdirs()
            context.assets.open(BUNDLED_ASSET_PATH).use { input ->
                FileOutputStream(temporary).use(input::copyTo)
            }
            validateModelFile(temporary)?.let { reason ->
                error("invalid bundled bubble detector: $reason")
            }
            if (destination.exists() && !destination.delete()) {
                error("unable to replace ${destination.name}")
            }
            if (!temporary.renameTo(destination)) {
                error("unable to publish ${destination.name}")
            }
            readyStamp = destination.stamp()
            Timber.i(
                "Bundled bubble detector prepared bytes=%d sha256=%s",
                destination.length(),
                EXPECTED_SHA256,
            )
            destination
        } catch (error: Throwable) {
            readyStamp = null
            Timber.w(error, "Unable to prepare bundled bubble detector")
            null
        } finally {
            if (temporary.exists() && !temporary.delete()) {
                Timber.w("Unable to remove temporary bubble detector: %s", temporary)
            }
        }
    }

    internal fun validateModelFile(file: File): String? {
        if (!file.isFile) return "missing"
        if (file.length() != EXPECTED_BYTES) {
            return "size mismatch: ${file.length()} bytes"
        }
        val actual = runCatching { sha256(file) }
            .getOrElse { return "unreadable: ${it.message}" }
        return if (actual.equals(EXPECTED_SHA256, ignoreCase = true)) {
            null
        } else {
            "SHA-256 mismatch: $actual"
        }
    }

    private fun File.stamp(): Triple<String, Long, Long>? =
        takeIf(File::isFile)?.let { Triple(it.absolutePath, it.length(), it.lastModified()) }

    private fun sha256(file: File): String {
        val digest = MessageDigest.getInstance("SHA-256")
        file.inputStream().buffered().use { input ->
            val buffer = ByteArray(64 * 1024)
            while (true) {
                val count = input.read(buffer)
                if (count <= 0) break
                digest.update(buffer, 0, count)
            }
        }
        return digest.digest().joinToString("") { byte -> "%02X".format(byte) }
    }
}

internal object BubbleModelRegrouper {

    enum class Source {
        MODEL,
        LEGACY_FALLBACK,
    }

    data class Group(
        val source: Source,
        val modelBubbleIndex: Int?,
        val cropBounds: IntRect,
        val contentBounds: IntRect,
        val memberIndices: List<Int>,
    )

    fun regroup(
        width: Int,
        height: Int,
        memberBounds: List<IntRect>,
        modelBounds: List<IntRect>,
        associations: List<BubbleMaskAssociator.Association>,
        fallbackPadding: Int,
        fallbackGap: Int,
    ): List<Group> {
        val modelByMember = MutableList<Int?>(memberBounds.size) { null }
        val assigned = BooleanArray(memberBounds.size)
        associations.forEach { association ->
            val memberIndex = association.ocrGroupIndex
            require(memberIndex in memberBounds.indices)
            require(!assigned[memberIndex]) {
                "Duplicate association for OCR member $memberIndex"
            }
            assigned[memberIndex] = true
            modelByMember[memberIndex] = association.modelBubbleIndex
        }
        return regroupByModelAssignments(
            width = width,
            height = height,
            memberBounds = memberBounds,
            modelBounds = modelBounds,
            modelByMember = modelByMember,
            fallbackPadding = fallbackPadding,
            fallbackGap = fallbackGap,
        )
    }

    fun regroupByModelAssignments(
        width: Int,
        height: Int,
        memberBounds: List<IntRect>,
        modelBounds: List<IntRect>,
        modelByMember: List<Int?>,
        fallbackPadding: Int,
        fallbackGap: Int,
        excludedMemberIndices: Set<Int> = emptySet(),
        standaloneMemberIndices: Set<Int> = emptySet(),
    ): List<Group> {
        require(width > 0 && height > 0)
        require(modelByMember.size == memberBounds.size)
        require(excludedMemberIndices.all(memberBounds.indices::contains))
        require(standaloneMemberIndices.all(memberBounds.indices::contains))
        require(excludedMemberIndices.intersect(standaloneMemberIndices).isEmpty())

        val membersByModel = linkedMapOf<Int, MutableList<Int>>()
        val fallbackMemberIndices = mutableListOf<Int>()
        memberBounds.indices.forEach { memberIndex ->
            if (memberIndex in excludedMemberIndices) return@forEach
            val modelIndex = modelByMember[memberIndex]
            val usableModelIndex = modelIndex?.takeIf { index ->
                index in modelBounds.indices && isValid(clamp(modelBounds[index], width, height))
            }
            if (usableModelIndex == null) {
                fallbackMemberIndices += memberIndex
            } else {
                membersByModel.getOrPut(usableModelIndex) { mutableListOf() } += memberIndex
            }
        }

        val modelGroups = membersByModel.map { (modelIndex, memberIndices) ->
            val content = union(memberIndices.map { memberBounds[it] })
            val model = clamp(modelBounds[modelIndex], width, height)
            Group(
                source = Source.MODEL,
                modelBubbleIndex = modelIndex,
                cropBounds = clamp(union(listOf(model, content)), width, height),
                contentBounds = clamp(content, width, height),
                memberIndices = memberIndices.sorted(),
            )
        }
        fun clusterFallback(memberIndices: List<Int>): List<Group> {
            if (memberIndices.isEmpty()) return emptyList()
            return BubbleClusterer.cluster(
                rects = memberIndices.map { memberBounds[it] },
                imgW = width,
                imgH = height,
                pad = fallbackPadding,
                gap = fallbackGap,
            ).map { bubble ->
                Group(
                    source = Source.LEGACY_FALLBACK,
                    modelBubbleIndex = null,
                    cropBounds = bubble.rect,
                    contentBounds = bubble.contentRect,
                    memberIndices = bubble.memberIndices.map { memberIndices[it] }.sorted(),
                )
            }
        }
        val standaloneFallbackIndices = fallbackMemberIndices.filter(standaloneMemberIndices::contains)
        val ordinaryFallbackIndices = fallbackMemberIndices.filterNot(standaloneMemberIndices::contains)
        val fallbackGroups =
            clusterFallback(ordinaryFallbackIndices) + clusterFallback(standaloneFallbackIndices)
        return (modelGroups + fallbackGroups).sortedWith(
            compareBy<Group>(
                { it.contentBounds.top },
                { it.contentBounds.left },
                { it.source.ordinal },
            )
        )
    }

    private fun union(rects: List<IntRect>): IntRect {
        require(rects.isNotEmpty())
        return IntRect(
            left = rects.minOf { it.left },
            top = rects.minOf { it.top },
            right = rects.maxOf { it.right },
            bottom = rects.maxOf { it.bottom },
        )
    }

    private fun clamp(rect: IntRect, width: Int, height: Int): IntRect = IntRect(
        left = min(rect.left.coerceAtLeast(0), width),
        top = min(rect.top.coerceAtLeast(0), height),
        right = max(0, rect.right.coerceAtMost(width)),
        bottom = max(0, rect.bottom.coerceAtMost(height)),
    )

    private fun isValid(rect: IntRect): Boolean = rect.width > 0 && rect.height > 0
}

internal enum class BubbleShapeMaskQuality {
