}

internal object BubbleTextBlockRegrouper {

    fun regroup(
        blocks: List<TextBlock>,
        bubbleByBlock: List<Int?>,
    ): List<TextBlock> {
        require(blocks.size == bubbleByBlock.size)
        if (blocks.isEmpty()) return emptyList()

        val matchedByBubble = linkedMapOf<Int, MutableList<TextBlock>>()
        val unmatched = mutableListOf<TextBlock>()
        blocks.forEachIndexed { index, block ->
            val bubbleId = bubbleByBlock[index]
            if (bubbleId == null) {
                unmatched += block.withSourceBoxFallback()
            } else {
                matchedByBubble.getOrPut(bubbleId) { mutableListOf() } += block
            }
        }

        val grouped = matchedByBubble.flatMap { (bubbleId, members) ->
            val boxes = members.map { it.boundingBox.let { b -> IntRect(b.left,b.top,b.right,b.bottom) } }
            val union = IntRect(boxes.minOf { it.left },boxes.minOf { it.top },boxes.maxOf { it.right },boxes.maxOf { it.bottom })
            val horizontal = inferSourceLayoutOrientation(boxes,union,TextOrientation.HORIZONTAL_LTR) == TextOrientation.HORIZONTAL_LTR
            BubbleTextGroupingPolicy.partition(boxes,horizontal).map { group ->
                mergeBubbleMembers(bubbleId,group.map(members::get))
            }
        }
        return (grouped + unmatched).sortedWith(
            compareBy(
                { it.boundingBox.top },
                { it.boundingBox.left },
            )
        )
    }

    private fun mergeBubbleMembers(
        bubbleId: Int,
        members: List<TextBlock>,
    ): TextBlock {
        val sourceBoxes = members.flatMap { it.sourceBoxesOrBoundingBox() }
        val bounds = Rect(
            sourceBoxes.minOf { it.left },
            sourceBoxes.minOf { it.top },
            sourceBoxes.maxOf { it.right },
            sourceBoxes.maxOf { it.bottom },
        )
        val orientation = inferSourceLayoutOrientation(
            sourceBoxes = sourceBoxes.map { box ->
                IntRect(box.left, box.top, box.right, box.bottom)
            },
            blockBounds = IntRect(bounds.left, bounds.top, bounds.right, bounds.bottom),
            ambiguousFallback = TextOrientation.HORIZONTAL_LTR,
        )
        val ordered = when (orientation) {
            TextOrientation.VERTICAL_RTL -> members.sortedWith(
                compareByDescending<TextBlock> { it.boundingBox.centerX() }
                    .thenBy { it.boundingBox.top }
            )
            else -> members.sortedWith(
                compareBy(
                    { it.boundingBox.top },
                    { it.boundingBox.left },
                )
            )
        }
        val first = ordered.first()
        return first.copy(
            text = ordered.map(TextBlock::text).filter(String::isNotBlank).joinToString("\n"),
            boundingBox = bounds,
            confidence = ordered.minOf(TextBlock::confidence),
            layoutOrientation = orientation,
            sourceBoxes = sourceBoxes.map(::Rect),
            bubbleGroupId = bubbleId,
            regionGranularity = TextRegionGranularity.BUBBLE,
            parentRegionId = bubbleId,
        )
    }

    private fun TextBlock.withSourceBoxFallback(): TextBlock =
        if (sourceBoxes.isEmpty()) {
            copy(sourceBoxes = listOf(Rect(boundingBox)))
        } else {
            this
        }
}

internal object BubbleTextGroupingPolicy {
    fun partition(bounds: List<IntRect>, horizontal: Boolean): List<List<Int>> {
        if (!horizontal) return if (bounds.isEmpty()) emptyList() else listOf(bounds.indices.toList())
        return groupHorizontalParagraphRects(
            bounds.map { MergeDebugRect(it.left,it.top,it.right,it.bottom) },
            List(bounds.size) { 0 }, verticalGapRatio=1.3f, horizontalOverlapRatio=.3f,
        )
    }
}

data class Quad @JvmOverloads constructor(
    val p0: PointF, val p1: PointF, val p2: PointF, val p3: PointF,
    // Unexpanded detector support, distinct from the recognition crop's padding.
    val support: Quad? = null,
) {
    val centerX: Float get() = (p0.x + p1.x + p2.x + p3.x) / 4f
    val centerY: Float get() = (p0.y + p1.y + p2.y + p3.y) / 4f
    val width: Float get() = hypot(p1.x - p0.x, p1.y - p0.y)
    val height: Float get() = hypot(p3.x - p0.x, p3.y - p0.y)

    fun axisAlignedBounds(): IntArray {
        val xs = floatArrayOf(p0.x, p1.x, p2.x, p3.x)
        val ys = floatArrayOf(p0.y, p1.y, p2.y, p3.y)
        return intArrayOf(xs.min().toInt(), ys.min().toInt(), xs.max().toInt(), ys.max().toInt())
    }
}

@JvmOverloads
fun extractQuads(
    probMap: Array<FloatArray>,
    scaleX: Float,
    scaleY: Float,
    binThresh: Float,
    scoreThresh: Float,
    unclipRatio: Float,
    minSide: Int = 3,
    retainSupport: Boolean = false,
    columnCutValidator: ((Float, Int, Int) -> Boolean)? = null,
): List<Quad> {
    val h = probMap.size
    val w = probMap[0].size
    val visited = Array(h) { BooleanArray(w) }
    val result = mutableListOf<Quad>()
    val splitIndices = mutableSetOf<Int>()

    for (y0 in 0 until h) {
        for (x0 in 0 until w) {
            if (visited[y0][x0] || probMap[y0][x0] < binThresh) continue
            val component = mutableListOf<IntPoint>()
            val boundary = mutableListOf<IntPoint>()
            val stack = ArrayDeque<IntArray>()
            stack.addLast(intArrayOf(x0, y0))
            visited[y0][x0] = true
            while (stack.isNotEmpty()) {
                val (cx, cy) = stack.removeLast()
                component.add(IntPoint(cx, cy))
                // 该点 8-邻接里有任何超出 binThresh 的"边界（与背景接触）"点，则记入 boundary
                var isBoundary = false
                for ((dx, dy) in NEIGHBORS_8) {
                    val nx = cx + dx; val ny = cy + dy
                    if (nx !in 0 until w || ny !in 0 until h) { isBoundary = true; continue }
                    if (probMap[ny][nx] < binThresh) { isBoundary = true; continue }
                    if (!visited[ny][nx]) {
                        visited[ny][nx] = true
                        stack.addLast(intArrayOf(nx, ny))
                    }
                }
                if (isBoundary) boundary.add(IntPoint(cx, cy))
            }
            if (component.size < 16) continue
            val hull = convexHull(if (boundary.isNotEmpty()) boundary else component)
            if (hull.size < 3) continue
            val quad = minAreaRect(hull) ?: continue
            val side = minOf(quad.width, quad.height)
            if (side < minSide) continue
            val score = boxScore(probMap, quad)
            if (score < scoreThresh) continue
            val partition = if (columnCutValidator != null &&
                kotlin.math.abs(quad.p1.y - quad.p0.y) < quad.width * 0.1f
            ) PaddleTextColumnSplitPolicy.split(
                probMap, component.map { it.y * w + it.x }.toIntArray(), binThresh, columnCutValidator,
            ) else null
            val childSupports = partition?.members?.map { pixels ->
                minAreaRect(convexHull(pixels.map { IntPoint(it % w, it / w) }))
            }?.takeIf { children -> children.all { it != null && minOf(it.width, it.height) >= minSide && boxScore(probMap, it) >= scoreThresh } }
            val supports = childSupports?.filterNotNull() ?: listOf(quad)
            supports.forEachIndexed { childIndex, support ->
                var unclipped = unclip(support, unclipRatio)
                if (supports.size > 1) {
                    // Splitting changes only the cross-column axis. Keep the parent's longitudinal
                    // extent: detached punctuation may lie beyond a short child's probability core.
                    val parentCrop = unclip(quad, unclipRatio)
                    val xs = listOf(unclipped.p0.x, unclipped.p1.x, unclipped.p2.x, unclipped.p3.x)
                    unclipped = Quad(
                        paddlePointF(xs.min(), parentCrop.p0.y), paddlePointF(xs.max(), parentCrop.p1.y),
                        paddlePointF(xs.max(), parentCrop.p2.y), paddlePointF(xs.min(), parentCrop.p3.y),
                    )
                    val l = partition!!.cuts.getOrNull(childIndex - 1) ?: Float.NEGATIVE_INFINITY
                    val r = partition.cuts.getOrNull(childIndex) ?: Float.POSITIVE_INFINITY
                    unclipped = clipHorizontal(unclipped, l, r)
                    splitIndices += result.size
                }
                val mapped = Quad(
                    paddlePointF(unclipped.p0.x * scaleX, unclipped.p0.y * scaleY),
                    paddlePointF(unclipped.p1.x * scaleX, unclipped.p1.y * scaleY),
                    paddlePointF(unclipped.p2.x * scaleX, unclipped.p2.y * scaleY),
                    paddlePointF(unclipped.p3.x * scaleX, unclipped.p3.y * scaleY),
                    support = if (retainSupport || columnCutValidator != null) Quad(
                        paddlePointF(support.p0.x * scaleX, support.p0.y * scaleY),
                        paddlePointF(support.p1.x * scaleX, support.p1.y * scaleY),
                        paddlePointF(support.p2.x * scaleX, support.p2.y * scaleY),
                        paddlePointF(support.p3.x * scaleX, support.p3.y * scaleY),
                    ) else null,
                )
                result.add(mapped)
            }
        }
    }
    // An outer child's padding must not reach an already separate neighbouring column.
    if (splitIndices.isEmpty()) return result
    return result.mapIndexed { index, crop ->
        if (index !in splitIndices) return@mapIndexed crop
        val core = crop.support!!
        var leftLimit = Float.NEGATIVE_INFINITY
        var rightLimit = Float.POSITIVE_INFINITY
        result.forEach { other ->
            val adjacent = other.support ?: return@forEach
            if (other === crop) return@forEach
            val overlap = minOf(core.p3.y, adjacent.p3.y) - maxOf(core.p0.y, adjacent.p0.y)
            if (overlap < minOf(core.height, adjacent.height) * 0.4f) return@forEach
            if (adjacent.p1.x < core.p0.x) leftLimit = maxOf(leftLimit, (adjacent.p1.x + core.p0.x) / 2)
            if (adjacent.p0.x > core.p1.x) rightLimit = minOf(rightLimit, (adjacent.p0.x + core.p1.x) / 2)
        }
        clipHorizontal(crop, leftLimit, rightLimit).copy(support = core)
    }
}

var isBoundary = false
for ((dx, dy) in NEIGHBORS_8) {
    val nx = cx + dx; val ny = cy + dy
    if (nx !in 0 until w || ny !in 0 until h) { isBoundary = true; continue }
    if (probMap[ny][nx] < binThresh) { isBoundary = true; continue }
    if (!visited[ny][nx]) {
        visited[ny][nx] = true
        stack.addLast(intArrayOf(nx, ny))
    }
}

internal fun fitRecognitionCropQuad(quad: Quad, imageWidth: Int, imageHeight: Int): Quad? {
    val corners = listOf(quad.p0, quad.p1, quad.p2, quad.p3).map { point ->
        IntPoint(
            Math.round(point.x).coerceIn(0, imageWidth),
            Math.round(point.y).coerceIn(0, imageHeight),
        )
    }
    return minAreaRect(convexHull(corners))?.copy(support = quad.support)
}

private fun convexHull(pts: List<IntPoint>): List<IntPoint> {
    if (pts.size <= 2) return pts
    val sorted = pts.distinct().sortedWith(compareBy({ it.x }, { it.y }))
    if (sorted.size <= 2) return sorted
    val hull = mutableListOf<IntPoint>()
    // 下半
    for (p in sorted) {
        while (hull.size >= 2 && cross(hull[hull.size - 2], hull[hull.size - 1], p) <= 0) {
            hull.removeAt(hull.size - 1)
        }
        hull.add(p)
    }
    val lower = hull.size + 1
    // 上半
    for (i in sorted.size - 2 downTo 0) {
        val p = sorted[i]
        while (hull.size >= lower && cross(hull[hull.size - 2], hull[hull.size - 1], p) <= 0) {
            hull.removeAt(hull.size - 1)
        }
        hull.add(p)
    }
    hull.removeAt(hull.size - 1)
    return hull
}

private fun sortCornersLikePaddle(a: PointF, b: PointF, c: PointF, d: PointF): Quad {
    val sorted = listOf(a, b, c, d).sortedBy { it.x }
    val leftPair = sorted.take(2).sortedBy { it.y }
    val rightPair = sorted.drop(2).sortedBy { it.y }
    return Quad(leftPair[0], rightPair[0], rightPair[1], leftPair[1])
}

private fun boxScore(probMap: Array<FloatArray>, quad: Quad): Float {
    val bounds = quad.axisAlignedBounds()
    val h = probMap.size; val w = probMap[0].size
    val x0 = bounds[0].coerceAtLeast(0)
    val y0 = bounds[1].coerceAtLeast(0)
    val x1 = bounds[2].coerceAtMost(w - 1)
    val y1 = bounds[3].coerceAtMost(h - 1)
    if (x1 <= x0 || y1 <= y0) return 0f
    var sum = 0.0
    var count = 0
    val poly = listOf(quad.p0, quad.p1, quad.p2, quad.p3)
    for (y in y0..y1) for (x in x0..x1) {
        if (pointInQuad(x.toFloat() + 0.5f, y.toFloat() + 0.5f, poly)) {
            sum += probMap[y][x]
            count++
        }
    }
    return if (count == 0) 0f else (sum / count).toFloat()
}

private fun pointInQuad(x: Float, y: Float, poly: List<PointF>): Boolean {
    var inside = false
    var j = poly.size - 1
    for (i in poly.indices) {
        val xi = poly[i].x; val yi = poly[i].y
        val xj = poly[j].x; val yj = poly[j].y
        if (((yi > y) != (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi + 1e-9f) + xi)) {
            inside = !inside
        }
        j = i
    }
    return inside
}

internal fun groupHorizontalLineRects(
    rects: List<MergeDebugRect>,
    bubbleGroupIds: List<Int?>,
    alignmentTolerance: Float,
    adjacentGapRatio: Float,
    heightRatioLimit: Float,
): List<List<Int>> {
    require(rects.size == bubbleGroupIds.size)
    val minOverlap = maxOf(0.5f, 1f - alignmentTolerance)
    fun aligned(a: MergeDebugRect, b: MergeDebugRect): Boolean {
        val minHeight = minOf(a.height, b.height)
        val overlap = minOf(a.bottom, b.bottom) - maxOf(a.top, b.top)
        return maxOf(a.height, b.height) <= minHeight * heightRatioLimit &&
            overlap > minHeight * minOverlap
    }
    fun overlapAllowed(a: MergeDebugRect, b: MergeDebugRect): Boolean {
        val (left, right) = if (a.left <= b.left) a to b else b to a
        val gap = right.left - left.right
        // Allow modest detector padding overlap, not nested boxes or neighbouring text rows.
        val maxOverlap = minOf(minOf(a.width, b.width) * 0.25f, minOf(a.height, b.height) * 0.5f)
        return gap >= -maxOverlap
    }
    fun close(a: MergeDebugRect, b: MergeDebugRect): Boolean {
        val gap = maxOf(a.left, b.left) - minOf(a.right, b.right)
        return gap <= (a.height + b.height) * 0.5f * adjacentGapRatio
    }
    val groups = mutableListOf<MutableList<Int>>()
    // Sweep left to right so a slightly lower middle box cannot arrive after both ends.
    val ordered = rects.indices.sortedWith(compareBy({ rects[it].left }, { rects[it].top }))
    for (index in ordered) {
        val box = rects[index]
        val row = groups.filter { members ->
            bubbleGroupIds[members.first()] == bubbleGroupIds[index] &&
                // Pairwise vertical compatibility prevents a sloping chain growing across rows.
                members.all { aligned(rects[it], box) && overlapAllowed(rects[it], box) } &&
                members.any { close(rects[it], box) }
        }.minByOrNull { members ->
            members.minOf { kotlin.math.abs((rects[it].top + rects[it].bottom) - (box.top + box.bottom)) }
        }
        if (row == null) groups += mutableListOf(index) else row += index
    }
    return groups.map { row -> row.sortedWith(compareBy({ rects[it].left }, { rects[it].top })) }
        .sortedWith(compareBy({ row -> row.minOf { rects[it].top } }, { row -> row.minOf { rects[it].left } }))
}

    val maxOverlap = minOf(minOf(a.width, b.width) * 0.25f, minOf(a.height, b.height) * 0.5f)
    return gap >= -maxOverlap
}
fun close(a: MergeDebugRect, b: MergeDebugRect): Boolean {
    val gap = maxOf(a.left, b.left) - minOf(a.right, b.right)
    return gap <= (a.height + b.height) * 0.5f * adjacentGapRatio
}

