var position = 0
while (position < length) {
    fun dark(position: Int) = flags[index(lane, position)].toInt() and 1 != 0
    if (!dark(position)) { position++; continue }
    val start = position
    var lightBefore = 0; var lightAfter = 0
    while (position < length && dark(position)) {
        val pixelFlags = flags[index(lane, position)].toInt()
        if (pixelFlags and 2 != 0) lightBefore++
        if (pixelFlags and 4 != 0) lightAfter++
        position++
    }
    val run = position - start
    if (run >= minimumRun && maxOf(lightBefore, lightAfter) >= run * 0.80f) {
        output += Separator(vertical, lane, start, position)
    }
}

internal object MangaRecognizedTextConsolidator {
    data class Result(
        val entries: List<MangaOcrBubbleGroupingPolicy.Entry>,
        val texts: List<String>,
        val absorbedByOwner: Map<Int, Int>,
        val retainedIndices: List<Int>,
    )

    fun consolidate(entries: List<MangaOcrBubbleGroupingPolicy.Entry>, texts: List<String>): Result {
        require(entries.size == texts.size)
        val normalized = texts.map { text ->
            Normalizer.normalize(text, Normalizer.Form.NFKC).lowercase(Locale.ROOT)
                .filter { it.isLetterOrDigit() }
        }
        val absorbed = entries.indices.mapNotNull { index ->
            val fragment = entries[index]
            val text = normalized[index]
            if (fragment.guidedSource != BubbleModelRegrouper.Source.LEGACY_FALLBACK ||
                fragment.regionGranularity == TextRegionGranularity.FREE_TEXT || text.length < 3
            ) return@mapNotNull null
            val owners = entries.indices.filter { owner ->
                val entry = entries[owner]
                entry.guidedSource == BubbleModelRegrouper.Source.MODEL &&
                    entry.modelBubbleIndex != null &&
                    entry.regionGranularity == TextRegionGranularity.BUBBLE &&
                    normalized[owner].length >= text.length && normalized[owner].contains(text) &&
                    coverage(fragment.bubble.contentRect, entry.bubble.contentRect) >= 0.70
            }
            owners.singleOrNull()?.let { owner -> index to owner }
        }.toMap()
        val fragmentsByOwner = absorbed.entries.groupBy({ it.value }, { it.key })
        val keptIndices = entries.indices.filterNot(absorbed::containsKey)
        return Result(
            entries = keptIndices.map { index ->
                val entry = entries[index]
                val fragments = fragmentsByOwner[index].orEmpty().map(entries::get)
                if (fragments.isEmpty()) entry else entry.copy(bubble = entry.bubble.copy(
                    rect = fragments.fold(entry.bubble.rect) { bounds, other -> union(bounds, other.bubble.rect) },
                    contentRect = fragments.fold(entry.bubble.contentRect) { bounds, other -> union(bounds, other.bubble.contentRect) },
                    memberIndices = (entry.bubble.memberIndices + fragments.flatMap { it.bubble.memberIndices }).distinct().sorted(),
                ))
            },
            texts = keptIndices.map(texts::get),
            absorbedByOwner = absorbed,
            retainedIndices = keptIndices,
        )
    }

    private fun coverage(fragment: IntRect, owner: IntRect): Double {
        val area = fragment.width.toDouble() * fragment.height
        if (area <= 0) return 0.0
        return (minOf(fragment.right, owner.right) - maxOf(fragment.left, owner.left)).coerceAtLeast(0).toDouble() *
            (minOf(fragment.bottom, owner.bottom) - maxOf(fragment.top, owner.top)).coerceAtLeast(0) / area
    }

    private fun union(a: IntRect, b: IntRect) = IntRect(
        minOf(a.left, b.left), minOf(a.top, b.top), maxOf(a.right, b.right), maxOf(a.bottom, b.bottom),
    )
}

internal class MangaSeedSearchOrder private constructor(
    private val imageWidth: Int,
    private val globalIndices: IntArray,
    private val keys: LongArray,
) {
    /** Sample the center and spatial extremes so a letter counter cannot become the only seed. */
    fun spatialSeeds(candidate: BooleanArray, roi: IntRect): List<Int> {
        require(roi.width > 0 && roi.height > 0)
        require(candidate.size == roi.width * roi.height)
        var nearest = -1
        var left = -1
        var right = -1
        var top = -1
        var bottom = -1
        var nearestKey = Long.MAX_VALUE
        var leftKey = Long.MAX_VALUE
        var rightKey = Long.MAX_VALUE
        var topKey = Long.MAX_VALUE
        var bottomKey = Long.MAX_VALUE
        var minX = Int.MAX_VALUE
        var maxX = Int.MIN_VALUE
        var minY = Int.MAX_VALUE
        var maxY = Int.MIN_VALUE
        for (position in keys.indices) {
            val globalIndex = globalIndices[position]
            val y = globalIndex / imageWidth
            val x = globalIndex - y * imageWidth
            if (x !in roi.left until roi.right || y !in roi.top until roi.bottom) continue
            val index = (y - roi.top) * roi.width + x - roi.left
            if (!candidate[index]) continue
            val key = keys[position]
            if (key < nearestKey) { nearestKey = key; nearest = index }
            // Equal coordinates resolve to the nearer pixel, as the first hit in distance order did.
            if (x < minX || (x == minX && key < leftKey)) { minX = x; leftKey = key; left = index }
            if (x > maxX || (x == maxX && key < rightKey)) { maxX = x; rightKey = key; right = index }
            if (y < minY || (y == minY && key < topKey)) { minY = y; topKey = key; top = index }
            if (y > maxY || (y == maxY && key < bottomKey)) { maxY = y; bottomKey = key; bottom = index }
        }
        return listOf(nearest, left, right, top, bottom).filter { it >= 0 }.distinct()
    }

    fun nearest(
        candidate: BooleanArray,
        roi: IntRect,
    ): Int? {
        require(roi.width > 0 && roi.height > 0)
        require(candidate.size == roi.width * roi.height)
        var nearest: Int? = null
        var nearestKey = Long.MAX_VALUE
        for (position in keys.indices) {
            val key = keys[position]
            if (key >= nearestKey) continue
            val globalIndex = globalIndices[position]
            val y = globalIndex / imageWidth
            val x = globalIndex - y * imageWidth
            if (x !in roi.left until roi.right || y !in roi.top until roi.bottom) continue
            val localIndex = (y - roi.top) * roi.width + (x - roi.left)
            if (candidate[localIndex]) {
                nearestKey = key
                nearest = localIndex
            }
        }
        return nearest
    }

    companion object {
        fun prepare(
            imageWidth: Int,
            globalIndices: IntArray,
            distanceSquared: FloatArray,
            count: Int = globalIndices.size,
        ): MangaSeedSearchOrder {
            require(imageWidth > 0)
            require(count in 0..globalIndices.size)
            require(count <= distanceSquared.size)
            val indices = globalIndices.copyOf(count)
            val keys = LongArray(count) { position ->
                val distance = distanceSquared[position]
                require(distance.isFinite() && distance >= 0f)
                (java.lang.Float.floatToRawIntBits(distance).toLong() shl 32) or
                    (position.toLong() and 0xffff_ffffL)
            }
            return MangaSeedSearchOrder(
                imageWidth = imageWidth,
                globalIndices = indices,
                keys = keys,
            )
        }
    }
}

fun spatialSeeds(candidate: BooleanArray, roi: IntRect): List<Int> {
    require(roi.width > 0 && roi.height > 0)
    require(candidate.size == roi.width * roi.height)
    var nearest = -1
    var left = -1
    var right = -1
    var top = -1
    var bottom = -1
    var nearestKey = Long.MAX_VALUE
    var leftKey = Long.MAX_VALUE
    var rightKey = Long.MAX_VALUE
    var topKey = Long.MAX_VALUE
    var bottomKey = Long.MAX_VALUE
    var minX = Int.MAX_VALUE
    var maxX = Int.MIN_VALUE
    var minY = Int.MAX_VALUE
    var maxY = Int.MIN_VALUE
    for (position in keys.indices) {
        val globalIndex = globalIndices[position]
        val y = globalIndex / imageWidth
        val x = globalIndex - y * imageWidth
        if (x !in roi.left until roi.right || y !in roi.top until roi.bottom) continue
        val index = (y - roi.top) * roi.width + x - roi.left
        if (!candidate[index]) continue
        val key = keys[position]
        if (key < nearestKey) { nearestKey = key; nearest = index }
        // Equal coordinates resolve to the nearer pixel, as the first hit in distance order did.
        if (x < minX || (x == minX && key < leftKey)) { minX = x; leftKey = key; left = index }
        if (x > maxX || (x == maxX && key < rightKey)) { maxX = x; rightKey = key; right = index }
        if (y < minY || (y == minY && key < topKey)) { minY = y; topKey = key; top = index }
        if (y > maxY || (y == maxY && key < bottomKey)) { maxY = y; bottomKey = key; bottom = index }
    }
    return listOf(nearest, left, right, top, bottom).filter { it >= 0 }.distinct()
}

fun interface Decoder {
    fun logits(rows: IntArray, ids: List<IntArray>, lengths: IntArray): Array<Array<FloatArray>>
}

private fun continueGreedy(
    decoder: Decoder,
    rows: IntArray,
    prefixes: List<IntArray>,
    maxNewTokens: IntArray,
    confidences: List<FloatArray>?,
    checkActive: () -> Unit,
): Pair<List<Draft>, Int> {
    val ids = prefixes.map { it.copyOf(maxTokens + 1) }
    val lengths = IntArray(rows.size) { prefixes[it].size }
    val ended = BooleanArray(rows.size)
    var calls = 0
    while (true) {
        val active = rows.indices.filter { index ->
            !ended[index] && lengths[index] <= maxTokens && lengths[index] - prefixes[index].size < maxNewTokens[index]
        }
        if (active.isEmpty()) break
        checkActive()
        val logits = decoder.logits(
            IntArray(active.size) { rows[active[it]] },
            active.map { ids[it] },
            IntArray(active.size) { lengths[active[it]] },
        )
        calls++
        active.forEachIndexed { batchIndex, index ->
            val prediction = predict(logits[batchIndex], lengths[index] - 1, confidences != null)
            if (prediction.tokenId == endTokenId) {
                ended[index] = true
            } else {
                confidences?.get(index)?.set(lengths[index], prediction.confidence)
                ids[index][lengths[index]++] = prediction.tokenId
            }
        }
    }
    return rows.indices.map { Draft(ids[it].copyOf(lengths[it]), ended[it]) } to calls
}

private fun judge(acceptedSize: Int, draft: Draft, logits: Array<FloatArray>, confidences: FloatArray): Outcome {
    val verifyLength = verifyLength(draft)
    var position = acceptedSize - 1
    var prediction: MangaTokenPrediction? = null
    var rejected = false
    while (position < verifyLength) {
        val current = predict(logits, position, calculateConfidence)
        prediction = current
        val expected = when {
            position + 1 < draft.ids.size -> draft.ids[position + 1]
            draft.ended -> endTokenId
            else -> break // past a draft cut by its length limit: predicted is a free extra id
        }
        if (current.tokenId != expected) {
            rejected = true
            break
        }
        if (current.tokenId != endTokenId) confidences[position + 1] = current.confidence
        position++
    }
    if (position == verifyLength && (draft.ids.size > maxTokens || draft.ended)) {
        return Outcome(draft.ids, done = true, rejected = false)
    }
    // Reached only after a rejection or a length-limited draft, so a prediction exists.
    val taken = checkNotNull(prediction)
    val kept = draft.ids.copyOf(position + 1)
    if (taken.tokenId == endTokenId) return Outcome(kept, done = true, rejected = rejected)
    confidences[position + 1] = taken.confidence
    val accepted = kept + taken.tokenId
    return Outcome(accepted, done = accepted.size > maxTokens, rejected = rejected)
}

internal object MangaTextMemberConsolidator {
    data class Result(val entries: List<MangaOcrBubbleGroupingPolicy.Entry>, val movedMembers: Map<Int, Int>)

    fun consolidate(
        entries: List<MangaOcrBubbleGroupingPolicy.Entry>,
        memberBounds: List<IntRect>,
        textDetections: List<MangaBubbleDetectionPostprocessor.Detection>,
    ): Result {
        val assignments = MangaTextEvidenceMatcher.assignTextBubbleDetections(entries, textDetections)
        val moved = linkedMapOf<Int, Int>()
        entries.filter { it.guidedSource == BubbleModelRegrouper.Source.LEGACY_FALLBACK &&
            it.regionGranularity != TextRegionGranularity.FREE_TEXT }.forEach { entry ->
            entry.bubble.memberIndices.forEach memberLoop@ { member ->
                val bounds = memberBounds.getOrNull(member) ?: return@memberLoop
                val owners = assignments.filter { assignment ->
                    val detection = textDetections[assignment.detectionIndex]
                    val centerX = (bounds.left + bounds.right) / 2f
                    val centerY = (bounds.top + bounds.bottom) / 2f
                    val detectionWidth = detection.right - detection.left
                    val detectionHeight = detection.bottom - detection.top
                    // A tiny corner already covered by one larger word may have weaker detector
                    // evidence. Give it to that word so it is erased once with the complete text,
                    // instead of recognizing it separately or leaving a protected stroke behind.
                    val smallWordCorner = detection.confidence >= 0.35f &&
                        bounds.width.toDouble() * bounds.height <= detectionWidth * detectionHeight * 0.10 &&
                        maxOf(bounds.width, bounds.height) <= minOf(detectionWidth, detectionHeight) * 0.40f
                    (detection.confidence >= 0.50f || smallWordCorner) && centerX >= detection.left && centerX < detection.right &&
                        centerY >= detection.top && centerY < detection.bottom && coverage(bounds, detection) >= 0.60
                }.map { it.entryIndex }.distinct()
                owners.singleOrNull()?.let { moved[member] = it }
            }
        }
        if (moved.isEmpty()) return Result(entries, emptyMap())
        val byOwner = moved.entries.groupBy({ it.value }, { it.key })
        val updated = entries.mapIndexedNotNull { index, entry ->
            val added = byOwner[index].orEmpty()
            val retained = entry.bubble.memberIndices.filterNot(moved::containsKey)
            if (retained.isEmpty() && added.isEmpty()) return@mapIndexedNotNull entry.takeIf { entry.bubble.memberIndices.isEmpty() }
            val members = (retained + added).distinct().sorted()
            val changedFallback = retained.size != entry.bubble.memberIndices.size
            val content = if (changedFallback) {
                retained.map(memberBounds::get).reduce(::union)
            } else {
                added.fold(entry.bubble.contentRect) { bounds, member -> union(bounds, memberBounds[member]) }
            }
            entry.copy(bubble = entry.bubble.copy(memberIndices = members, contentRect = content,
                rect = if (changedFallback) content else added.fold(entry.bubble.rect) { b, m -> union(b, memberBounds[m]) }))
        }
        return Result(updated, moved.mapValues { (_, owner) -> entries[owner].modelBubbleIndex ?: owner })
    }

    private fun coverage(bounds: IntRect, d: MangaBubbleDetectionPostprocessor.Detection): Double {
        val area = bounds.width.toDouble() * bounds.height
        if (area <= 0) return 0.0
        val l = floor(d.left).toInt(); val t = floor(d.top).toInt()
        val r = ceil(d.right).toInt(); val b = ceil(d.bottom).toInt()
        return (minOf(bounds.right, r) - maxOf(bounds.left, l)).coerceAtLeast(0).toDouble() *
            (minOf(bounds.bottom, b) - maxOf(bounds.top, t)).coerceAtLeast(0) / area
    }

    private fun union(a: IntRect, b: IntRect) = IntRect(minOf(a.left, b.left), minOf(a.top, b.top),
        maxOf(a.right, b.right), maxOf(a.bottom, b.bottom))
}

    val smallWordCorner = detection.confidence >= 0.35f &&
        bounds.width.toDouble() * bounds.height <= detectionWidth * detectionHeight * 0.10 &&
        maxOf(bounds.width, bounds.height) <= minOf(detectionWidth, detectionHeight) * 0.40f
    (detection.confidence >= 0.50f || smallWordCorner) && centerX >= detection.left && centerX < detection.right &&
        centerY >= detection.top && centerY < detection.bottom && coverage(bounds, detection) >= 0.60
}.map { it.entryIndex }

internal object MangaTextRegionRecoveryPolicy {
    data class Result(
        val evidence: MangaOcrTextEvidencePolicy.Result,
        val recoveredDetectionIndices: List<Int>,
        val skippedDetectionIndices: List<Int>,
    )

    fun recover(
        evidence: MangaOcrTextEvidencePolicy.Result,
        textDetections: List<MangaBubbleDetectionPostprocessor.Detection>,
        imageWidth: Int,
        imageHeight: Int,
    ): Result {
        require(imageWidth > 0 && imageHeight > 0)
        val entries = evidence.entries.toMutableList()
        val supported = evidence.textSupportedEntryIndices.toMutableSet()
        val assignments = evidence.assignments.toMutableList()
        val recovered = mutableListOf<Int>()
        val skipped = mutableListOf<Int>()
        // Confidence order makes overlap suppression deterministic and independent of scan order.
        val candidates = evidence.unassignedTextBubbleDetectionIndices.sortedWith(
            compareByDescending<Int> { textDetections.getOrNull(it)?.confidence ?: -1f }
                .thenBy { it },
        )
        for (index in candidates) {
            val detection = textDetections.getOrNull(index)
            val bounds = detection?.validBounds(imageWidth, imageHeight)
            if (bounds == null || entries.any { overlapsText(bounds, it.bubble.contentRect) }) {
                skipped += index
                continue
            }
            val entryIndex = entries.size
            entries += MangaOcrBubbleGroupingPolicy.Entry(
                bubble = Bubble(rect = bounds, contentRect = bounds, memberIndices = emptyList()),
                // Do not fabricate DBNet members or a bubble-mask association.
                guidedSource = null,
                modelBubbleIndex = null,
                regionGranularity = TextRegionGranularity.BUBBLE,
            )
            assignments += MangaTextEvidenceMatcher.EntryAssignment(index, entryIndex, 1f, 1f, 0.0)
            supported += entryIndex
            recovered += index
        }
        return Result(
            evidence = evidence.copy(
                entries = entries,
                textSupportedEntryIndices = supported,
                assignments = assignments,
                unassignedTextBubbleDetectionIndices =
                    evidence.unassignedTextBubbleDetectionIndices - recovered.toSet(),
            ),
            recoveredDetectionIndices = recovered,
            skippedDetectionIndices = skipped,
        )
    }

    private fun MangaBubbleDetectionPostprocessor.Detection.validBounds(w: Int, h: Int): IntRect? {
        if (kind != MangaBubbleDetectionPostprocessor.Kind.TEXT_BUBBLE ||
            !confidence.isFinite() || confidence < MangaBubbleDetectionPostprocessor.DEFAULT_CONFIDENCE_THRESHOLD ||
            !left.isFinite() || !top.isFinite() || !right.isFinite() || !bottom.isFinite()
        ) return null
        val bounds = IntRect(
            floor(left).toInt().coerceIn(0, w), floor(top).toInt().coerceIn(0, h),
            ceil(right).toInt().coerceIn(0, w), ceil(bottom).toInt().coerceIn(0, h),
        )
        return bounds.takeIf {
            it.width >= MangaBubbleDetectionPostprocessor.MIN_BOX_SIDE_PX &&
                it.height >= MangaBubbleDetectionPostprocessor.MIN_BOX_SIDE_PX
        }
    }

    private fun overlapsText(a: IntRect, b: IntRect): Boolean {
        val area = (minOf(a.right, b.right) - maxOf(a.left, b.left)).coerceAtLeast(0).toLong() *
            (minOf(a.bottom, b.bottom) - maxOf(a.top, b.top)).coerceAtLeast(0)
        val smaller = minOf(a.width.toLong() * a.height, b.width.toLong() * b.height)
        return smaller > 0 && area.toDouble() / smaller >= MangaTextEvidenceMatcher.MIN_BOUNDS_COVERAGE
    }
}

internal fun mangaTokenPrediction(
    logitsByStep: Array<FloatArray>,
    calculateConfidence: Boolean,
): MangaTokenPrediction {
    require(logitsByStep.isNotEmpty()) { "Manga OCR logits must contain at least one step" }
    val logits = logitsByStep.last()
    require(logits.isNotEmpty()) { "Manga OCR logits vocabulary must not be empty" }

    var bestIndex = 0
    var bestLogit = logits[0]
    for (index in 1 until logits.size) {
        if (logits[index] > bestLogit) {
            bestLogit = logits[index]
            bestIndex = index
        }
    }
    if (!calculateConfidence) {
        return MangaTokenPrediction(bestIndex, Float.NaN)
    }

    var denominator = 0.0
    for (logit in logits) {
        denominator += exp((logit - bestLogit).toDouble())
    }
    val confidence = if (denominator.isFinite() && denominator > 0.0) {
        (1.0 / denominator).toFloat().coerceIn(0f, 1f)
    } else {
        Float.NaN
    }
    return MangaTokenPrediction(bestIndex, confidence)
}

val maximumDistance = minOf(width, height) / 2
for (index in component) {
    if (count >= samples.size) break
    val x = index % width; val y = index / width
    if (!isComponentBoundary(x, y, width, height, eraseMask)) continue
    for ((dx, dy) in DIRECTIONS) {
        for (distance in BOUNDARY_OUTER_RADIUS + 1..maximumDistance) {
            val nx = x + dx * distance; val ny = y + dy * distance
            if (nx !in 0 until width || ny !in 0 until height) break
            val sample = ny * width + nx
            if (eraseMask[sample] || !allowedSampleMask[sample]) continue
            if (sampleMarks[sample] != sampleStamp && count < samples.size) {
                sampleMarks[sample] = sampleStamp; samples[count++] = sample
            }
            break
        }
    }
}

internal object MlKitJapaneseRegionPolicy {
    fun expand(
        columns: List<MlKitJapaneseColumnCandidate>,
        lineBounds: List<MlKitGeometryRect>,
    ): List<MlKitJapaneseColumnCandidate> {
        if (columns.isEmpty()) return emptyList()
        val expanded = columns.map { column ->
            val completeLineBounds = column.sourceLineIndices.mapNotNull { lineIndex ->
                lineBounds.getOrNull(lineIndex)?.takeUnless(MlKitGeometryRect::isEmpty)
            }
            column.copy(bounds = union(completeLineBounds + column.bounds))
        }
        val unionFind = RegionUnionFind(expanded.size)
        for (firstIndex in expanded.indices) {
            val firstLines = expanded[firstIndex].sourceLineIndices.toSet()
            for (secondIndex in firstIndex + 1 until expanded.size) {
                if (firstLines.any(expanded[secondIndex].sourceLineIndices::contains)) {
                    unionFind.union(firstIndex, secondIndex)
                }
            }
        }
        return expanded.indices
            .groupBy(unionFind::find)
            .values
            .map { group ->
                val members = group.flatMap { expanded[it].memberIndices }.distinct().sorted()
                val sourceLines = group.flatMap { expanded[it].sourceLineIndices }.distinct().sorted()
                MlKitJapaneseColumnCandidate(
                    memberIndices = members,
                    sourceLineIndices = sourceLines,
                    bounds = union(group.map { expanded[it].bounds }),
                    medianGlyphSize = median(group.map { expanded[it].medianGlyphSize }),
                )
            }
            .distinctBy { region ->
                listOf(
                    region.bounds.left,
                    region.bounds.top,
                    region.bounds.right,
                    region.bounds.bottom,
                ) to region.sourceLineIndices
            }
            .sortedWith(
                compareByDescending<MlKitJapaneseColumnCandidate> { it.memberIndices.size }
                    .thenByDescending { it.bounds.centerX }
                    .thenBy { it.bounds.top },
            )
    }

    private fun union(rects: List<MlKitGeometryRect>): MlKitGeometryRect {
        require(rects.isNotEmpty())
        return MlKitGeometryRect(
            left = rects.minOf { it.left },
            top = rects.minOf { it.top },
            right = rects.maxOf { it.right },
            bottom = rects.maxOf { it.bottom },
        )
    }

    private fun median(values: List<Float>): Float {
        val sorted = values.sorted()
        val middle = sorted.size / 2
        return if (sorted.size % 2 == 1) {
            sorted[middle]
        } else {
            (sorted[middle - 1] + sorted[middle]) / 2f
        }
    }

    private class RegionUnionFind(size: Int) {
        private val parent = IntArray(size) { it }

        fun find(value: Int): Int {
            if (parent[value] != value) parent[value] = find(parent[value])
            return parent[value]
        }

        fun union(first: Int, second: Int) {
            val firstRoot = find(first)
            val secondRoot = find(second)
            if (firstRoot != secondRoot) parent[secondRoot] = firstRoot
        }
    }
}

internal object MlKitJapaneseInputPolicy {
    private const val TARGET_SHORT_SIDE = 1_200
    private const val MAX_LONG_SIDE = 3_000
    private const val MAX_UPSCALE = 3f

    fun plan(width: Int, height: Int): MlKitInputScalePlan {
        require(width > 0 && height > 0)
        val shortSide = min(width, height).toFloat()
        val longSide = max(width, height).toFloat()
        val growForShortSide = TARGET_SHORT_SIDE / shortSide
        val shrinkForLongSide = MAX_LONG_SIDE / longSide
        val scale = when {
            longSide > MAX_LONG_SIDE -> shrinkForLongSide
            shortSide < TARGET_SHORT_SIDE -> min(growForShortSide, min(MAX_UPSCALE, shrinkForLongSide))
            else -> 1f
        }.coerceAtMost(1f.takeIf { longSide >= MAX_LONG_SIDE } ?: MAX_UPSCALE)

        val outputWidth = (width * scale).toInt().coerceAtLeast(1)
        val outputHeight = (height * scale).toInt().coerceAtLeast(1)
        return MlKitInputScalePlan(
            inputWidth = width,
            inputHeight = height,
            outputWidth = outputWidth,
            outputHeight = outputHeight,
        )
    }
}

fun dominantAxis(points: List<MlKitGeometryPoint>): MlKitGeometryAxis {
    if (points.size < 2) return MlKitGeometryAxis.UNKNOWN
    val xSpread = points.maxOf { it.x } - points.minOf { it.x }
    val ySpread = points.maxOf { it.y } - points.minOf { it.y }
    return when {
        ySpread >= xSpread * AXIS_DOMINANCE_RATIO && ySpread > 0f -> MlKitGeometryAxis.VERTICAL
        xSpread >= ySpread * AXIS_DOMINANCE_RATIO && xSpread > 0f -> MlKitGeometryAxis.HORIZONTAL
        else -> MlKitGeometryAxis.UNKNOWN
    }
}

