private fun getTypingIndicatorForConversation(
    conversation: Conversation,
    typingIndicators: Map<String, com.cometchat.chat.models.TypingIndicator>
): TypingIndicator? {
    val conversationType = conversation.conversationType

    // Find all typing indicators that match this conversation
    // For user-to-user: match sender's UID with conversation's user UID
    // For groups: match receiverId with group's GUID
    val matchingTypingIndicators = typingIndicators.values.filter { indicator ->
        when (conversationType) {
            UIKitConstants.ConversationType.USERS -> {
                // For user conversations, the typing indicator's sender is the one typing
                // We need to match the sender's UID with the conversation's user UID
                val conversationUser = conversation.conversationWith as? User
                indicator.receiverType == conversationType && 
                    conversationUser?.uid == indicator.sender?.uid
            }
            UIKitConstants.ConversationType.GROUPS -> {
                // For group conversations, match the receiverId with the group's GUID
                val conversationGroup = conversation.conversationWith as? Group
                indicator.receiverType == conversationType && 
                    indicator.receiverId == conversationGroup?.guid
            }
            else -> false
        }
    }

    if (matchingTypingIndicators.isEmpty()) {
        return null
    }

    // Convert SDK TypingIndicators to UIKit TypingIndicator
    // Collect all users who are typing in this conversation
    val typingUsers = matchingTypingIndicators.mapNotNull { it.sender }

    return TypingIndicator(
        typingUsers = typingUsers,
        isTyping = true
    )
}

            val conversationGroup = conversation.conversationWith as? Group
            indicator.receiverType == conversationType && 
                indicator.receiverId == conversationGroup?.guid
        }
        else -> false
    }
}

if (matchingTypingIndicators.isEmpty()) {
    return null
}

@Composable
private fun buildMenuItems(
    context: Context,
    conversation: Conversation,
    style: CometChatConversationsStyle,
    hidePinOption: Boolean,
    hideDeleteOption: Boolean,
    options: ((Context, Conversation) -> List<MenuItem>)?,
    addOptions: ((Context, Conversation) -> List<MenuItem>)?,
    onDelete: () -> Unit,
    onPinToggle: () -> Unit
): List<MenuItem> {
    // If custom options are provided, use them exclusively
    if (options != null) {
        return options(context, conversation)
    }

    val menuItems = mutableListOf<MenuItem>()

    // Pin / Unpin conversation (toggles on the conversation's current pin state), gated by the SDK
    // Pin Conversation feature flag. Non-destructive — keeps default (neutral) styling.
    // System-pinned conversations (pinned via the REST API, pinnedBy = "app_system") are not
    // user-controllable, so neither pin nor unpin is offered for them.
    if (!hidePinOption &&
        com.cometchat.uikit.core.CometChatUIKit.isPinConversationEnabled() &&
        !conversation.isSystemPinned
    ) {
        val isPinned = conversation.isPinned
        menuItems.add(
            MenuItem(
                id = if (isPinned) UIKitConstants.ConversationOption.UNPIN
                else UIKitConstants.ConversationOption.PIN,
                name = context.getString(
                    if (isPinned) R.string.cometchat_unpin_conversation
                    else R.string.cometchat_pin_conversation
                ),
                startIcon = painterResource(
                    if (isPinned) com.cometchat.uikit.core.R.drawable.cometchat_ic_pin_off
                    else com.cometchat.uikit.core.R.drawable.cometchat_ic_pin
                ),
                onClick = onPinToggle
            )
        )
    }

    // Add default delete option if not hidden
    if (!hideDeleteOption) {
        menuItems.add(
            MenuItem(
                id = "delete",
                name = context.getString(R.string.cometchat_delete),
                startIcon = painterResource(R.drawable.cometchat_ic_delete),
                startIconTint = style.deleteOptionIconTint,
                textColor = style.deleteOptionTextColor,
                textStyle = style.deleteOptionTextStyle,
                onClick = onDelete
            )
        )
    }

    // Add additional options if provided
    if (addOptions != null) {
        menuItems.addAll(addOptions(context, conversation))
    }

    return menuItems
}

public fun getLastMessageText(context: Context, message: BaseMessage?): String {
    if (message == null) {
        return context.getString(R.string.cometchat_start_conv_hint)
    }

    // Check if message is deleted
    if (message.deletedAt > 0) {
        return context.getString(R.string.cometchat_this_message_deleted)
    }

    return when (message) {
        is AIAssistantMessage -> getAIAssistantMessageText(context, message)
        is TextMessage -> getTextMessageText(context, message)
        is MediaMessage -> getMediaMessageText(context, message)
        is CustomMessage -> getCustomMessageText(context, message)
        is Call -> CallsUtils.getCallStatus(context, message)
        is CardMessage -> message.text?.ifEmpty { null }
            ?: context.getString(R.string.cometchat_message_card)
        is InteractiveMessage -> context.getString(R.string.cometchat_this_message_type_is_not_supported)
        is Action -> getActionMessageText(context, message)
        else -> context.getString(R.string.cometchat_start_conv_hint)
    }
}

@DrawableRes
public fun getLastMessageIcon(message: BaseMessage?): Int? {
    if (message == null) return null

    // Check if message is deleted
    if (message.deletedAt > 0) {
        return R.drawable.cometchat_ic_conversations_deleted_message
    }

    // Check if message is a thread reply
    if (message.parentMessageId != 0L) {
        return R.drawable.cometchat_ic_conversations_thread
    }

    return when (message) {
        is TextMessage -> getTextMessageIcon(message)
        is MediaMessage -> getMediaMessageIcon(message)
        is CustomMessage -> getCustomMessageIcon(message)
        is Call -> getCallIcon(message)
        is InteractiveMessage -> R.drawable.cometchat_ic_conversations_deleted_message // Not supported
        is Action -> null // Action messages don't have icons
        else -> null
    }
}

public fun getMessagePrefix(context: Context, message: BaseMessage): String {
    // Only show prefix for group messages
    if (message.receiverType != CometChatConstants.RECEIVER_TYPE_GROUP) {
        return ""
    }

    // Don't show prefix for Action messages - they already contain the actor name
    // (e.g., "John joined", "John left", "John kicked Mary")
    if (message is Action) {
        return ""
    }

    val sender = message.sender ?: return ""

    // Safely get logged-in user, return sender name if SDK not initialized (preview mode)
    val currentUser = try {
        CometChatUIKit.getLoggedInUser()
    } catch (e: Exception) {
        null
    }

    return if (currentUser != null && sender.uid == currentUser.uid) {
        "${context.getString(R.string.cometchat_you)}: "
    } else {
        "${sender.name}: "
    }
}

public fun getFormattedSubtitleText(context: Context, message: BaseMessage?): String {
    if (message == null) {
        return context.getString(R.string.cometchat_start_conv_hint)
    }

    val prefix = getMessagePrefix(context, message)
    val messageText = getLastMessageText(context, message)

    return prefix + messageText
}

private fun getAIAssistantMessageText(context: Context, message: AIAssistantMessage): String {
    val text = message.text
    if (!text.isNullOrEmpty()) {
        return text
    }
    return context.getString(R.string.cometchat_ai_agent_message)
}

val attachment = message.attachment
if (attachment?.toString()?.contains(UIKitConstants.MimeType.GIF_EXTENSION) == true) {
    context.getString(R.string.cometchat_message_gif)
}

val conversationText = message.conversationText
if (!conversationText.isNullOrEmpty()) {
    return conversationText
}

val senderPrefix = getMessagePrefix(context, message)
val senderName = if (senderPrefix.isNotEmpty()) {
    senderPrefix.substringBefore(":")
}

@DrawableRes
private fun getTextMessageIcon(message: TextMessage): Int? {
    // Check for links in metadata
    val metadata = message.metadata
    if (metadata != null && checkForLinks(metadata.toString())) {
        return R.drawable.cometchat_ic_conversations_link
    }
    // Plain text messages don't have icons
    return null
}

