.pointerInput(minScale, maxScale) {
    awaitEachGesture {
        awaitFirstDown(requireUnconsumed = false)
        do {
            val event = awaitPointerEvent()
            val pressedCount = event.changes.count { it.pressed }
            if (pressedCount > 1 || scale > minScale) {
                val zoom = event.calculateZoom()
                val pan = event.calculatePan()
                if (zoom != 1f || pan != Offset.Zero) {
                    val newScale = (scale * zoom).coerceIn(minScale, maxScale)
                    val newOffset = if (newScale > minScale) {
                        ImageViewerUtils.constrainOffset(
                            offset = offset + pan,
                            scale = newScale,
                            imageSize = imageIntrinsicSize,
                            containerSize = containerSize
                        )
                    } else {
                        Offset.Zero
                    }
                    scale = newScale
                    offset = newOffset
                    event.changes.forEach {
                        if (it.positionChanged()) it.consume()
                    }
                }
            }
        } while (event.changes.any { it.pressed })
    }
}

.pointerInput(minScale, maxScale) {
    detectTapGestures(
        onDoubleTap = { tapOffset ->
            coroutineScope.launch {
                val targetScale = ImageViewerUtils.calcDoubleTapTargetScale(
                    currentScale = scale,
                    minScale = minScale,
                    maxScale = maxScale
                )
                if (scale <= minScale) {
                    // Zoom in centered on tap point
                    val centroidX = tapOffset.x - containerWidth / 2f
                    val centroidY = tapOffset.y - containerHeight / 2f
                    val scaleFactor = targetScale / scale
                    val targetOffset = ImageViewerUtils.constrainOffset(
                        offset = Offset(
                            x = centroidX * (1f - scaleFactor),
                            y = centroidY * (1f - scaleFactor)
                        ),
                        scale = targetScale,
                        imageSize = imageIntrinsicSize,
                        containerSize = containerSize
                    )
                    // Animate scale
                    scaleAnimatable.snapTo(scale)
                    offsetAnimatable.snapTo(offset)
                    launch {
                        scaleAnimatable.animateTo(
                            targetValue = targetScale,
                            animationSpec = spring()
                        ) { scale = value }
                    }
                    launch {
                        offsetAnimatable.animateTo(
                            targetValue = targetOffset,
                            animationSpec = spring()
                        ) { offset = value }
                    }
                } else {
                    // Zoom out to minScale
                    scaleAnimatable.snapTo(scale)
                    offsetAnimatable.snapTo(offset)
                    launch {
                        scaleAnimatable.animateTo(
                            targetValue = minScale,
                            animationSpec = spring()
                        ) { scale = value }
                    }
                    launch {
                        offsetAnimatable.animateTo(
                            targetValue = Offset.Zero,
                            animationSpec = spring()
                        ) { offset = value }
                    }
                }
            }
        }
    )
}

scaleAnimatable.snapTo(scale)
offsetAnimatable.snapTo(offset)
launch {
    scaleAnimatable.animateTo(
        targetValue = minScale,
        animationSpec = spring()
    ) { scale = value }
}

.pointerInput(minScale) {
    val velocityTracker = VelocityTracker()
    awaitPointerEventScope {
        while (true) {
            val down = awaitFirstDown(requireUnconsumed = false)
            // Only handle drag-to-dismiss at minimum scale
            if (scale > minScale) continue

            velocityTracker.resetTracking()
            velocityTracker.addPosition(
                down.uptimeMillis,
                down.position
            )

            var dragStarted = false
            var totalDragY = 0f
            var totalDragX = 0f

            try {
                while (true) {
                    val event = awaitPointerEvent()
                    val change = event.changes.firstOrNull() ?: break

                    if (!change.pressed) {
                        // Pointer released — handle end/fling
                        val velocity = velocityTracker.calculateVelocity()
                        val velocityY = velocity.y

                        if (dragStarted) {
                            if (ImageViewerUtils.shouldFlingDismiss(velocityY)) {
                                // Fling dismiss
                                coroutineScope.launch {
                                    val direction = sign(velocityY)
                                    dragAnimatable.snapTo(dragOffsetY)
                                    dragAnimatable.animateTo(
                                        targetValue = direction * screenHeightPx,
                                        animationSpec = spring()
                                    ) { dragOffsetY = value }
                                    onDismiss()
                                }
                            } else if (ImageViewerUtils.shouldDismiss(
                                    dragOffsetY, screenHeightPx
                                )
                            ) {
                                // Drag distance exceeds threshold — dismiss
                                coroutineScope.launch {
                                    val direction = sign(dragOffsetY)
                                    dragAnimatable.snapTo(dragOffsetY)
                                    dragAnimatable.animateTo(
                                        targetValue = direction * screenHeightPx,
                                        animationSpec = spring()
                                    ) { dragOffsetY = value }
                                    onDismiss()
                                }
                            } else {
                                // Restore — animate back to center
                                coroutineScope.launch {
                                    dragAnimatable.snapTo(dragOffsetY)
                                    dragAnimatable.animateTo(
                                        targetValue = 0f,
                                        animationSpec = spring()
                                    ) { dragOffsetY = value }
                                    onDragProgress(0f)
                                    onDragEnd()
                                }
                            }
                            isDragging = false
                        }
                        break
                    }

                    velocityTracker.addPosition(
                        change.uptimeMillis,
                        change.position
                    )

                    val dragDelta = change.position - change.previousPosition
                    totalDragY += dragDelta.y
                    totalDragX += dragDelta.x

                    // Start drag after a small threshold to avoid accidental
                    // drags; mostly-horizontal movement is left unconsumed so the
                    // hosting pager can swipe between images instead.
                    if (!dragStarted && abs(totalDragY) > 8f && abs(totalDragY) > abs(totalDragX)) {
                        dragStarted = true
                        isDragging = true
                        onDragStart()
                    }

                    if (dragStarted) {
                        dragOffsetY += dragDelta.y
                        val fraction = (abs(dragOffsetY) / screenHeightPx)
                            .coerceIn(0f, 1f)
                        onDragProgress(fraction)
                        change.consume()
                    }
                }
            } catch (_: Exception) {
                // Gesture cancelled
                if (dragStarted) {
                    isDragging = false
                    coroutineScope.launch {
                        dragAnimatable.snapTo(dragOffsetY)
                        dragAnimatable.animateTo(
                            targetValue = 0f,
                            animationSpec = spring()
                        ) { dragOffsetY = value }
                        onDragProgress(0f)
                        onDragEnd()
                    }
                }
            }
        }
    }
}

private fun downloadImage(url: String, fileName: String) {
    if (url.isEmpty()) {
        CometChatLogger.e(TAG, "Cannot download image, url is empty")
        return
    }
    try {
        val safeName = fileName.ifEmpty { url.substringAfterLast('/').ifEmpty { "download" } }
        val request = DownloadManager.Request(Uri.parse(url))
            .setTitle(safeName)
            .setDescription("Downloading…")
            .setNotificationVisibility(
                DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED
            )
            .setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS, safeName)
        (getSystemService(Context.DOWNLOAD_SERVICE) as DownloadManager).enqueue(request)
        Toast.makeText(this, R.string.cometchat_downloading, Toast.LENGTH_SHORT).show()
    } catch (e: Exception) {
        CometChatLogger.e(TAG, "Failed to download image: ${e.message}")
    }
}

private fun shareImage(url: String, fileName: String, mimeType: String) {
    if (!ImageViewerUtils.isShareValid(url, fileName, mimeType)) {
        CometChatLogger.e(TAG, "Cannot share image, url or mimeType or filename is empty")
        return
    }

    Thread {
        try {
            val downloadsDir = Environment.getExternalStoragePublicDirectory(
                Environment.DIRECTORY_DOWNLOADS
            )
            val file = File(downloadsDir, fileName)

            if (!file.exists()) {
                val connection = URL(url).openConnection() as HttpURLConnection
                connection.connect()
                if (connection.responseCode != HttpURLConnection.HTTP_OK) {
                    CometChatLogger.e(TAG, "Failed to download image: HTTP ${connection.responseCode}")
                    return@Thread
                }
                connection.inputStream.use { input ->
                    FileOutputStream(file).use { output ->
                        input.copyTo(output)
                    }
                }
            }

            runOnUiThread {
                try {
                    val uri = FileProvider.getUriForFile(
                        this,
                        cometchatFileProviderAuthority,
                        file
                    )
                    val shareIntent = Intent(Intent.ACTION_SEND).apply {
                        putExtra(Intent.EXTRA_STREAM, uri)
                        type = mimeType
                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    }
                    startActivity(Intent.createChooser(shareIntent, null))
                } catch (e: Exception) {
                    CometChatLogger.e(TAG, "Failed to share image: ${e.message}")
                }
            }
        } catch (e: Exception) {
            CometChatLogger.e(TAG, "Failed to download image for sharing: ${e.message}")
        }
    }.start()
}

