@Composable
private fun QuickReactionsCard(
    reactions: List<String>,
    onReactionClick: (String) -> Unit,
    onEmojiPickerClick: () -> Unit,
    isLeft: Boolean
) {
    val cardShape = RoundedCornerShape(50)

    // Card-level entrance animation (matches XML's translationX + alpha + scale animation)
    var cardVisible by remember { mutableStateOf(false) }
    LaunchedEffect(Unit) {
        kotlinx.coroutines.delay(reactions.size * 40L)
        cardVisible = true
    }
    val cardScale by animateFloatAsState(
        targetValue = if (cardVisible) 1f else 0.8f,
        animationSpec = tween(durationMillis = 200, easing = FastOutSlowInEasing),
        label = "reaction_card_scale"
    )
    val cardAlpha by animateFloatAsState(
        targetValue = if (cardVisible) 1f else 0f,
        animationSpec = tween(durationMillis = 200, easing = FastOutSlowInEasing),
        label = "reaction_card_alpha"
    )

    Surface(
        modifier = Modifier
            .graphicsLayer {
                scaleX = cardScale
                scaleY = cardScale
                alpha = cardAlpha
                translationX = if (cardVisible) 0f else if (isLeft) -100f else 100f
            }
            .testTag("cometchat_message_popup_menu_reactions"),
        shape = cardShape,
        color = CometChatTheme.colorScheme.backgroundColor1
    ) {
        Row(
            modifier = Modifier
                .horizontalScroll(rememberScrollState())
                .padding(4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            reactions.forEachIndexed { index, emoji ->
                // Per-chip staggered animation
                var chipVisible by remember { mutableStateOf(false) }
                LaunchedEffect(Unit) {
                    kotlinx.coroutines.delay(index * 40L)
                    chipVisible = true
                }
                val chipScale by animateFloatAsState(
                    targetValue = if (chipVisible) 1f else 0.6f,
                    animationSpec = tween(durationMillis = 200, easing = FastOutSlowInEasing),
                    label = "chip_scale_$index"
                )
                val chipAlpha by animateFloatAsState(
                    targetValue = if (chipVisible) 1f else 0f,
                    animationSpec = tween(durationMillis = 200, easing = FastOutSlowInEasing),
                    label = "chip_alpha_$index"
                )

                Box(
                    modifier = Modifier
                        .padding(
                            start = if (index == 0) 0.dp else 2.dp,
                            end = 2.dp
                        )
                        .graphicsLayer {
                            scaleX = chipScale
                            scaleY = chipScale
                            alpha = chipAlpha
                            translationY = if (chipVisible) 0f else 20f
                        }
                        .clip(RoundedCornerShape(50))
                        .clickable { onReactionClick(emoji) }
                        .testTag("cometchat_reaction_chip_$emoji")
                ) {
                    Text(
                        text = emoji,
                        modifier = Modifier.padding(4.dp),
                        fontSize = 18.sp
                    )
                }
            }

            // "Add reaction" icon chip
            var addVisible by remember { mutableStateOf(false) }
            LaunchedEffect(Unit) {
                kotlinx.coroutines.delay(reactions.size * 40L)
                addVisible = true
            }
            val addScale by animateFloatAsState(
                targetValue = if (addVisible) 1f else 0.6f,
                animationSpec = tween(durationMillis = 200, easing = FastOutSlowInEasing),
                label = "add_chip_scale"
            )
            val addAlpha by animateFloatAsState(
                targetValue = if (addVisible) 1f else 0f,
                animationSpec = tween(durationMillis = 200, easing = FastOutSlowInEasing),
                label = "add_chip_alpha"
            )

            Box(
                modifier = Modifier
                    .padding(start = 2.dp)
                    .graphicsLayer {
                        scaleX = addScale
                        scaleY = addScale
                        alpha = addAlpha
                        translationY = if (addVisible) 0f else 20f
                    }
                    .clip(RoundedCornerShape(50))
                    .clickable { onEmojiPickerClick() }
                    .testTag("cometchat_add_reaction_chip")
            ) {
                Icon(
                    painter = painterResource(id = R.drawable.cometchat_add_reaction),
                    contentDescription = stringResource(R.string.cometchat_a11y_add_reaction),
                    tint = CometChatTheme.colorScheme.iconTintSecondary,
                    modifier = Modifier
                        .padding(4.dp)
                        .size(24.dp)
                )
            }
        }
    }
}

@Composable
private fun OptionListCard(
    menuItems: List<CometChatMessageOption>,
    onOptionClick: (CometChatMessageOption) -> Unit,
    style: CometChatMessagePopupMenuStyle
) {
    val shape = RoundedCornerShape(style.cornerRadius)

    // Split the resolved options into pages (reset whenever the option set changes).
    val pages = remember(menuItems) { MessageOptionsPaginator.paginate(menuItems.size) }
    var pageIndex by remember(menuItems) { mutableIntStateOf(0) }
    // Tracks navigation direction so the swipe animates the correct way.
    var forward by remember(menuItems) { mutableStateOf(true) }

    val moreTitle = stringResource(R.string.cometchat_message_option_more)
    val backTitle = stringResource(R.string.cometchat_message_option_back)

    val moreOption = CometChatMessageOption(
        id = MessageOptionsPaginator.MORE_ID,
        title = moreTitle,
        icon = R.drawable.cometchat_ic_arrow_forward
    )
    val backOption = CometChatMessageOption(
        id = MessageOptionsPaginator.BACK_ID,
        title = backTitle,
        icon = R.drawable.cometchat_ic_back
    )

    // Rows used only to fix the card width to the full option set, so pages never shrink the
    // width. The visible pages are then pinned to this measured width.
    val anchorOptions = if (pages.size > 1) menuItems + moreOption + backOption else menuItems
    var anchorWidthPx by remember(menuItems) { mutableIntStateOf(0) }
    val density = LocalDensity.current

    Surface(
        modifier = Modifier
            .widthIn(min = 128.dp)
            .border(
                width = style.strokeWidth,
                color = style.strokeColor,
                shape = shape
            )
            .testTag("cometchat_message_popup_menu_options"),
        shape = shape,
        color = style.backgroundColor,
        shadowElevation = style.elevation,
        tonalElevation = 0.dp
    ) {
        Column {
            // Invisible width anchor: measures the widest row across all options (+ More/Back)
            // and contributes zero height, so height still fits the current page.
            Box(
                modifier = Modifier
                    .height(0.dp)
                    .clipToBounds()
                    .clearAndSetSemantics { }
                    .onSizeChanged { anchorWidthPx = it.width }
            ) {
                Column {
                    anchorOptions.forEach { option ->
                        OptionRow(option = option, onClick = {}, style = style)
                    }
                }
            }

            val pageWidthModifier = if (anchorWidthPx > 0) {
                Modifier.width(with(density) { anchorWidthPx.toDp() })
            } else {
                Modifier
            }

            AnimatedContent(
                targetState = pageIndex.coerceIn(0, pages.lastIndex),
                modifier = pageWidthModifier,
                transitionSpec = {
                    val direction = if (forward) 1 else -1
                    (slideInHorizontally { width -> direction * width } + fadeIn()) togetherWith
                        (slideOutHorizontally { width -> -direction * width } + fadeOut())
                },
                label = "cometchat_message_options_page"
            ) { page ->
                Column(modifier = Modifier.padding(vertical = 8.dp)) {
                    pages[page].forEach { slot ->
                        when (slot) {
                            is MessageOptionsPaginator.Slot.Item -> {
                                val option = menuItems[slot.index]
                                OptionRow(
                                    option = option,
                                    onClick = { onOptionClick(option) },
                                    style = style,
                                    fillWidth = true
                                )
                            }

                            MessageOptionsPaginator.Slot.More -> {
                                // Divider separating the real options from the "More" row.
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(style.strokeWidth.coerceAtLeast(1.dp))
                                        .background(style.strokeColor)
                                )
                                OptionRow(
                                    option = moreOption,
                                    onClick = {
                                        forward = true
                                        pageIndex++
                                    },
                                    style = style,
                                    fillWidth = true
                                )
                            }

                            MessageOptionsPaginator.Slot.Back -> OptionRow(
                                option = backOption,
                                onClick = {
                                    forward = false
                                    pageIndex--
                                },
                                style = style,
                                fillWidth = true
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun OptionRow(
    option: CometChatMessageOption,
    onClick: () -> Unit,
    style: CometChatMessagePopupMenuStyle,
    fillWidth: Boolean = false
) {
    val textColor = if (option.titleColor != 0) Color(option.titleColor) else style.textColor
    val iconTint = if (option.iconTintColor != 0) Color(option.iconTintColor) else style.startIconTint

    Row(
        modifier = Modifier
            // Fill the card width so the whole row is the tap target, not just the text.
            // The invisible width anchor keeps this false so it can measure intrinsic width.
            .then(if (fillWidth) Modifier.fillMaxWidth() else Modifier)
            .clickable(onClick = onClick)
            .padding(horizontal = 16.dp, vertical = 8.dp)
            .semantics { contentDescription = option.title },
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.Start
    ) {
        // Start icon
        if (option.icon != 0) {
            Icon(
                painter = painterResource(id = option.icon),
                contentDescription = null,
                tint = iconTint,
                modifier = Modifier.size(24.dp)
            )
            Spacer(modifier = Modifier.width(8.dp))
        }

        // Label text
        Text(
            text = option.title,
            color = textColor,
            style = style.textStyle
        )
    }
}

