sealed public class PaginationDecision {
    /**
     * Indicates that older messages should be fetched.
     * This occurs when the user scrolls near the top of the message list.
     */
    public data object FetchOlderMessages : PaginationDecision()

    /**
     * Indicates that newer messages should be fetched.
     * This occurs when the user scrolls near the bottom of the message list
     * after having scrolled up.
     */
    public data object FetchNewerMessages : PaginationDecision()

    /**
     * Indicates that no pagination action should be taken.
     * This occurs when guard conditions prevent fetching or when
     * the scroll position doesn't meet the threshold requirements.
     */
    public data object NoAction : PaginationDecision()
}

val nearTop = lastVisibleIndex >= totalItems - PAGINATION_THRESHOLD

// Check if near the bottom (newer messages direction)
// With reverseLayout=true: firstVisibleIndex approaches 0 when scrolling down
val nearBottom = firstVisibleIndex <= PAGINATION_THRESHOLD

// Priority: Fetch older messages first when both conditions are met
return when {
    nearTop && hasMorePreviousMessages -> PaginationDecision.FetchOlderMessages
    nearBottom && hasMoreNewMessages -> PaginationDecision.FetchNewerMessages
    else -> PaginationDecision.NoAction
}

val progress = (offsetX.value / swipeThresholdPx).coerceIn(0f, 1f)

// Get the reply icon drawable
val replyIcon = remember {
    ContextCompat.getDrawable(context, R.drawable.cometchat_ic_reply_to_message)
}

val iconTint = CometChatTheme.colorScheme.iconTintSecondary
val circleBackground = CometChatTheme.colorScheme.neutralColor300

Box(
    modifier = Modifier.fillMaxWidth()
) {
    // Draw reply icon and circular background using Canvas (matches Kotlin's onChildDraw)
    if (progress > 0f) {
        Canvas(
            modifier = Modifier.fillMaxSize()
        ) {
            // Calculate center position for icon
            // Icon is positioned at: left margin + half icon size
            val centerX = iconMarginPx + iconSizePx / 2f
            // Add vertical offset to move icon down from center
            val centerY = size.height / 2f + iconVerticalOffsetPx

            // Draw growing circular background with alpha
            val circleRadius = maxCircleRadius * progress
            val circleAlpha = progress
            drawCircle(
                color = circleBackground.copy(alpha = circleAlpha),
                radius = circleRadius,
                center = Offset(centerX, centerY)
            )

            // Draw reply icon with alpha (fixed size, only alpha changes)
            replyIcon?.let { icon ->
                icon.setTint(iconTint.hashCode())
                icon.alpha = (progress * 255).toInt()
                val halfIcon = (iconSizePx / 2).toInt()
                icon.setBounds(
                    (centerX - halfIcon).toInt(),
                    (centerY - halfIcon).toInt(),
                    (centerX + halfIcon).toInt(),
                    (centerY + halfIcon).toInt()
                )
                drawContext.canvas.nativeCanvas.let { canvas ->
                    icon.draw(canvas)
                }
            }
        }
    }

    // Message content with horizontal offset
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .offset { IntOffset(offsetX.value.roundToInt(), 0) }
            .pointerInput(enabled) {
                detectHorizontalDragGestures(
                    onDragStart = {
                        swipeTriggered = false
                    },
                    onDragEnd = {
                        // Animate back to original position
                        scope.launch {
                            offsetX.animateTo(0f, animationSpec = tween(200))
