@Composable
private fun NotificationFeedChip(
    chip: FilterChipState,
    style: CometChatNotificationFeedStyle,
    onClick: () -> Unit
) {
    val chipShape = RoundedCornerShape(20.dp)
    val backgroundColor = if (chip.isActive) style.chipActiveBackgroundColor else style.chipInactiveBackgroundColor
    val textColor = when {
        chip.isActive -> style.chipActiveTextColor
        chip.unreadCount > 0 -> CometChatTheme.colorScheme.textColorSecondary  // Has unreads: medium-dark
        else -> style.chipInactiveTextColor  // No unreads: light gray
    }

    Row(
        modifier = Modifier
            .height(34.dp)
            .clip(chipShape)
            .then(
                if (!chip.isActive) {
                    Modifier.border(1.dp, style.chipBorderColor, chipShape)
                } else {
                    Modifier
                }
            )
            .background(backgroundColor, chipShape)
            .clickable { onClick() }
            .padding(horizontal = 12.dp, vertical = 6.dp)
            .testTag("notification-feed-chip-${chip.id}"),
        verticalAlignment = Alignment.CenterVertically
    ) {
        // Chip label
        Text(
            text = chip.label,
            color = textColor,
            style = CometChatTheme.typography.bodyMedium
        )

        // Unread badge
        if (chip.unreadCount > 0) {
            Spacer(modifier = Modifier.width(6.dp))
            UnreadBadge(
                count = chip.unreadCount,
                style = style,
                isActive = chip.isActive
            )
        }
    }
}

@Composable
private fun UnreadBadge(
    count: Int,
    style: CometChatNotificationFeedStyle,
    isActive: Boolean,
    modifier: Modifier = Modifier
) {
    val badgeBg = if (isActive) style.badgeActiveBackgroundColor else style.badgeInactiveBackgroundColor
    val badgeText = if (isActive) style.badgeActiveTextColor else style.badgeInactiveTextColor
    val badgeShape = RoundedCornerShape(10.dp)

    Box(
        contentAlignment = Alignment.Center,
        modifier = modifier
            .clip(badgeShape)
            .then(
                if (isActive) {
                    Modifier.border(1.dp, style.badgeActiveBorderColor, badgeShape)
                } else {
                    Modifier
                }
            )
            .background(badgeBg, badgeShape)
            .padding(horizontal = 6.dp, vertical = 2.dp)
    ) {
        Text(
            text = if (count > 99) "99+" else count.toString(),
            color = badgeText,
            style = CometChatTheme.typography.caption1Medium,
            textAlign = TextAlign.Center
        )
    }
}

@Composable
public fun NotificationFeedItemCard(
    item: NotificationFeedItem,
    style: CometChatNotificationFeedStyle,
    onItemVisible: (NotificationFeedItem) -> Unit,
    onItemHidden: (NotificationFeedItem) -> Unit,
    onItemClick: (NotificationFeedItem) -> Unit,
    onActionClick: (NotificationFeedItem, Map<String, Any>) -> Unit,
    modifier: Modifier = Modifier
) {
    val cdHoist1 = stringResource(R.string.cometchat_a11y_notification_from, item.category ?: "unknown")
    var isVisible by remember { mutableStateOf(false) }
    val lifecycleOwner = androidx.lifecycle.compose.LocalLifecycleOwner.current

    // Track visibility based on lifecycle
    DisposableEffect(lifecycleOwner, item.id) {
        val observer = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_PAUSE,
                Lifecycle.Event.ON_STOP -> {
                    if (isVisible) {
                        isVisible = false
                        onItemHidden(item)
                    }
                }
                else -> {}
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose {
            lifecycleOwner.lifecycle.removeObserver(observer)
            if (isVisible) {
                onItemHidden(item)
            }
        }
    }

    Card(
        modifier = modifier
            .fillMaxWidth()
            .clickable { onItemClick(item) }
            .padding(horizontal = 16.dp, vertical = 8.dp)
            .onGloballyPositioned { coordinates ->
                val newVisibility = coordinates.size.height > 0
                if (newVisibility && !isVisible) {
                    isVisible = true
                    onItemVisible(item)
                } else if (!newVisibility && isVisible) {
                    isVisible = false
                    onItemHidden(item)
                }
            }
            .testTag("notification-feed-item-${item.id}")
            .semantics {
                contentDescription = cdHoist1
            },
        shape = RoundedCornerShape(0.dp),
        colors = CardDefaults.cardColors(containerColor = Color.Transparent),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
        ) {
            // CometChatCardsRenderer content
            val cardJson = item.content?.toString() ?: ""
            if (cardJson.isNotEmpty()) {
                CometChatCardComposable(
                    cardJson = cardJson,
                    themeMode = CometChatCardThemeMode.AUTO,
                    logLevel = com.cometchat.cards.models.CometChatCardLogLevel.VERBOSE,
                    onAction = { event ->
                        onActionClick(
                            item,
                            mapOf(
                                "type" to event.action,
                                "elementId" to event.elementId
                            )
                        )
                    }
                )
            } else {
                Text(
                    text = "Unable to display notification",
                    style = CometChatTheme.typography.bodyRegular,
                    color = CometChatTheme.colorScheme.textColorSecondary
                )
            }
        }
    }
