private fun conversationTitle(message: BaseMessage, uid: String?, guid: String?): String {
    val currentUser = try { com.cometchat.uikit.core.CometChatUIKit.getLoggedInUser() } catch (e: Exception) { null }
    if (uid != null || guid != null) {
        return if (message.sender?.uid == currentUser?.uid) "You" else message.sender?.name ?: ""
    }
    val receiver = message.receiver
    return if (receiver is com.cometchat.chat.models.Group) {
        receiver.name ?: ""
    } else {
        message.sender?.name ?: ""
    }
}

private fun senderPrefix(message: BaseMessage, uid: String?, guid: String?): String? {
    if (uid != null || guid != null) return null
    val currentUser = try { com.cometchat.uikit.core.CometChatUIKit.getLoggedInUser() } catch (e: Exception) { null }
    val name = if (currentUser != null && message.sender?.uid == currentUser.uid) {
        "You"
    } else {
        message.sender?.name ?: ""
    }
    return name.takeIf { it.isNotEmpty() }
}

private fun mediaCountLabel(context: Context, messageType: String?, count: Int): String =
    when (messageType?.lowercase()) {
        UIKitConstants.MessageType.IMAGE -> context.getString(R.string.cometchat_n_images, count)
        UIKitConstants.MessageType.VIDEO -> context.getString(R.string.cometchat_n_videos, count)
        UIKitConstants.MessageType.AUDIO -> context.getString(R.string.cometchat_n_audio, count)
        else -> context.getString(R.string.cometchat_n_files, count)
    }

private fun getDocumentFileIcon(attachment: com.cometchat.chat.models.Attachment?): Int {
    if (attachment == null) return R.drawable.cometchat_unknown_file_icon
    val mimeType = attachment.fileMimeType ?: return R.drawable.cometchat_unknown_file_icon
    val fileUrl = attachment.fileUrl ?: ""

    return when {
        mimeType.contains("video") -> R.drawable.cometchat_video_file_icon
        mimeType.contains("octet-stream") -> {
            when {
                fileUrl.endsWith(".doc") || fileUrl.endsWith(".docx") -> R.drawable.cometchat_word_file_icon
                fileUrl.endsWith(".ppt") || fileUrl.endsWith(".pptx") -> R.drawable.cometchat_ppt_file_icon
                fileUrl.endsWith(".xls") || fileUrl.endsWith(".xlsx") -> R.drawable.cometchat_xlsx_file_icon
                else -> R.drawable.cometchat_unknown_file_icon
            }
        }
        mimeType.contains("pdf") -> R.drawable.cometchat_pdf_file_icon
        mimeType.contains("zip") -> R.drawable.cometchat_zip_file_icon
        fileUrl.contains(".csv") -> R.drawable.cometchat_text_file_icon
        mimeType.contains("audio") -> R.drawable.cometchat_audio_file_icon
        mimeType.contains("image") -> R.drawable.cometchat_image_file_icon
        mimeType.contains("text") -> R.drawable.cometchat_text_file_icon
        mimeType.contains("link") -> R.drawable.cometchat_link_file_icon
        else -> R.drawable.cometchat_unknown_file_icon
    }
}

public fun add(item: T) {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList + item
}

public fun remove(item: T) {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList - item
}

public fun addAll(items: List<T>) {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList + items
}

public fun removeAt(index: Int) {
    val currentList = _items.value ?: emptyList()
    if (index in currentList.indices) {
        _items.value = currentList - currentList[index]
    }
}

public fun update(index: Int, newItem: T) {
    val currentList = _items.value ?: emptyList()
    if (index in currentList.indices) {
        val updatedList = currentList.toMutableList()
        updatedList[index] = newItem
        _items.value = updatedList
    }
}

public fun insertAt(index: Int, newItem: T) {
    val currentList = _items.value ?: emptyList()
    if (index in currentList.indices) {
        val updatedList = currentList.toMutableList()
        updatedList.add(index, newItem)
        _items.value = updatedList
    }
}

public fun addAllAtStart(items: List<T>) {
    val currentList = _items.value ?: emptyList()
    _items.value = items + currentList
}

public fun swapItems(index1: Int, index2: Int) {
    val currentList = _items.value ?: emptyList()
    if (index1 in currentList.indices && index2 in currentList.indices) {
        val updatedList = currentList.toMutableList()
        val temp = updatedList[index1]
        updatedList[index1] = updatedList[index2]
        updatedList[index2] = temp
        _items.value = updatedList
    }
}

public fun replaceAll(newItems: List<T>) {
    _items.value = newItems
}

public fun findFirst(predicate: (T) -> Boolean): T? {
    return _items.value?.find(predicate)
}

public fun filterItems(predicate: (T) -> Boolean) {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList.filter(predicate)
}

public fun containsItem(item: T): Boolean {
    return _items.value?.contains(item) == true
}

public fun removeIf(predicate: (T) -> Boolean) {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList.filterNot(predicate)
}

public fun reverse() {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList.reversed()
}

public fun shuffle() {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList.shuffled()
}

public fun clearIf(predicate: (T) -> Boolean) {
    val currentList = _items.value ?: emptyList()
    _items.value = currentList.filterNot(predicate)
}

public fun subList(fromIndex: Int, toIndex: Int) {
    val currentList = _items.value ?: emptyList()
    if (fromIndex in currentList.indices && toIndex in currentList.indices) {
        _items.value = currentList.subList(fromIndex, toIndex)
    }
}

public fun replaceFirst(oldItem: T, newItem: T) {
    val currentList = _items.value ?: emptyList()
    val updatedList = currentList.toMutableList()
    val index = updatedList.indexOf(oldItem)
    if (index >= 0) {
        updatedList[index] = newItem
        _items.value = updatedList
    }
}

public fun addUnique(item: T) {
    val currentList = _items.value ?: emptyList()
    if (item !in currentList) {
        _items.value = currentList + item
    }
}

public fun getItemAt(index: Int): T? {
    return _items.value?.getOrNull(index)
}

public fun updateRange(startIndex: Int, endIndex: Int, newItems: List<T>) {
    val currentList = _items.value ?: emptyList()
    if (startIndex in currentList.indices && endIndex in currentList.indices) {
        val updatedList = currentList.toMutableList()
        for (i in startIndex..endIndex) {
            if (i - startIndex < newItems.size) {
                updatedList[i] = newItems[i - startIndex]
            }
        }
        _items.value = updatedList
    }
}

public fun addIfNotEmpty(item: T) {
    val currentList = _items.value ?: emptyList()
    if (currentList.isNotEmpty()) {
        _items.value = currentList + item
    }
}

public fun clear() {
    _items.value = emptyList()
}

@Composable
private fun ConversationStarterList(
    starters: List<String>,
    style: CometChatAIConversationStarterStyle,
    itemView: (@Composable (starter: String, position: Int) -> Unit)?,
    onClick: ((starter: String, position: Int) -> Unit)?
) {
    LazyColumn(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 8.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        itemsIndexed(
            items = starters,
            key = { index, starter -> "$index-$starter" }
        ) { index, starter ->
            if (itemView != null) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 8.dp)
                        .clickable { onClick?.invoke(starter, index) }
                ) {
                    itemView(starter, index)
                }
            } else {
                ConversationStarterItem(
                    starter = starter,
                    position = index,
                    style = style,
                    onClick = onClick
                )
            }
        }
    }
}

