fun find(name: String): Category? {
    var cursor: Cursor? = null
    val db = clientProvider.get()
    try {
        cursor =
            db.query(
                CategoryContentProvider.BASE_URI,
                ALL_FIELDS,
                "${COLUMN_NAME}=?",
                arrayOf(name),
                null,
            )
        if (cursor != null && cursor.moveToFirst()) {
            return fromCursor(cursor)
        }
    } catch (e: RemoteException) {
        throw IllegalStateException(e)
    } finally {
        cursor?.close()
        db.release()
    }
    return null
}

fun recentCategories(limit: Int): List<CategoryItem> {
    val items = ArrayList<CategoryItem>()
    var cursor: Cursor? = null
    val db = clientProvider.get()
    try {
        cursor =
            db.query(
                CategoryContentProvider.BASE_URI,
                ALL_FIELDS,
                null,
                emptyArray(),
                "$COLUMN_LAST_USED DESC",
            )
        while (cursor != null && cursor.moveToNext() && cursor.position < limit) {
            val category = fromCursor(cursor)
            if (category.name != null) {
                items.add(
                    CategoryItem(
                        category.name,
                        category.description,
                        category.thumbnail,
                        false,
                    ),
                )
            }
        }
    } catch (e: RemoteException) {
        throw IllegalStateException(e)
    } finally {
        cursor?.close()
        db.release()
    }
    return items
}

