class ContributionsLocalDataSource
    @Inject
    constructor(
        @param:Named("default_preferences") private val defaultKVStore: JsonKvStore,
        private val contributionDao: ContributionDao,
    ) {
        /**
         * Get contribution object from cursor
         *
         * @param uri
         * @return
         */
        fun getContributionWithFileName(uri: String): Contribution {
            val contributionWithUri = contributionDao.getContributionWithTitle(uri)
            if (contributionWithUri.isNotEmpty()) {
                return contributionWithUri[0]
            }
            throw IllegalArgumentException("Contribution not found for URI: $uri")
        }

        /**
         * Remove a contribution from the contributions table
         *
         * @param contribution
         * @return
         */
        fun deleteContribution(contribution: Contribution): Completable = contributionDao.delete(contribution)

        /**
         * Marks a completed contribution deleted after a normal request reports the file page is gone.
         * Rows that are still uploading are left in place.
         */
        fun markCompletedContributionDeleted(fileName: String): Completable =
            Completable.fromAction {
                contributionDao
                    .getContributionWithTitle(fileName)
                    .filter { it.state == Contribution.STATE_COMPLETED }
                    .forEach {
                        it.state = Contribution.STATE_DELETED
                        contributionDao.updateSynchronous(it)
                    }
            }

        /**
         * Deletes contributions with specific states.
         *
         * @param states The states of the contributions to delete.
         * @return A Completable indicating the result of the operation.
         */
        fun deleteContributionsWithStates(states: List<Int>): Completable =
            contributionDao.deleteContributionsWithStates(states)

        /**
         * Fetches contributions with specific states.
         *
         * @param states The states of the contributions to fetch.
         * @param sortedByDateUploadStarted Whether the contributions are sorted by the date the upload
         * started.
         * @return A DataSource factory for paginated contributions with the specified states.
         */
        fun getContributionsWithStates(
            states: List<Int>,
            sortedByDateUploadStarted: Boolean = false,
        ): DataSource.Factory<Int, Contribution> =
            if (sortedByDateUploadStarted) {
                contributionDao.getContributionsSortedByDateUploadStarted(states)
            } else {
                contributionDao.getContributions(states)
            }

        /**
         * Fetches all contributions with specific states at once, not page by page.
         *
         * @param states The states of the contributions to fetch.
         * @return A Single with the list of all contributions with the specified states.
         */
        fun getAllContributionsWithStates(states: List<Int>): Single<List<Contribution>> =
            contributionDao.getContribution(states)

        fun saveContributions(contributions: List<Contribution>): Single<List<Long>> {
            val contributionList: MutableList<Contribution> = ArrayList()
            for (contribution in contributions) {
                val oldContribution =
                    contributionDao.getContribution(
                        contribution.pageId,
                    )
                if (oldContribution != null) {
                    contribution.wikidataPlace = oldContribution.wikidataPlace
                }
                contributionList.add(contribution)
            }
            return contributionDao.save(contributionList)
        }

        fun saveContributions(contribution: Contribution): Completable = contributionDao.save(contribution)

        fun set(
            key: String,
            value: Long,
        ) {
            defaultKVStore.putLong(key, value)
        }

        fun updateContributionsWithStates(
            states: List<Int>,
            newState: Int,
        ): Completable = contributionDao.updateContributionsWithStates(states, newState)
    }

fun getContributionWithFileName(uri: String): Contribution {
    val contributionWithUri = contributionDao.getContributionWithTitle(uri)
    if (contributionWithUri.isNotEmpty()) {
        return contributionWithUri[0]
    }
    throw IllegalArgumentException("Contribution not found for URI: $uri")
}

fun markCompletedContributionDeleted(fileName: String): Completable =
    Completable.fromAction {
        contributionDao
            .getContributionWithTitle(fileName)
            .filter { it.state == Contribution.STATE_COMPLETED }
