            Single.just(showCoordinatesEditNotification(context, media, coordinatesInfo, result))
        }.firstOrError()
}

private fun getFormattedWikiText(
    wikiText: String,
    editedLocation: String,
): String {
    if (wikiText.contains("filedesc") && wikiText.contains("Location")) {
        val fromLocationToEnd = wikiText.substring(wikiText.indexOf("{{Location"))
        val firstHalf = wikiText.substring(0, wikiText.indexOf("{{Location"))
        val lastHalf = fromLocationToEnd.substring(fromLocationToEnd.indexOf("}}") + 2)

        val startOfSecondSection = StringUtils.ordinalIndexOf(wikiText, "==", 3)
        val buffer = StringBuilder()
        if (wikiText[wikiText.indexOf("{{Location") - 1] == '\n') {
            buffer.append(editedLocation.substring(1))
        } else {
            buffer.append(editedLocation)
        }
        if (startOfSecondSection != -1 && wikiText[startOfSecondSection - 1] != '\n') {
            buffer.append("\n")
        }

        return firstHalf + buffer + lastHalf
    }
    if (wikiText.contains("filedesc") && !wikiText.contains("Location")) {
        val startOfSecondSection = StringUtils.ordinalIndexOf(wikiText, "==", 3)

        if (startOfSecondSection != -1) {
            val firstHalf = wikiText.substring(0, startOfSecondSection)
            val lastHalf = wikiText.substring(startOfSecondSection)
            val buffer = editedLocation.substring(1) + "\n"
            return firstHalf + buffer + lastHalf
        }

        return wikiText + editedLocation
    }
    return "== {{int:filedesc}} ==$editedLocation$wikiText"
}

private fun showCoordinatesEditNotification(
    context: Context,
    media: Media,
    coordinatesInfo: CoordinatesInfo,
    result: Boolean,
): Boolean {
    val message: String
    var title = context.getString(R.string.coordinates_edit_helper_show_edit_title)

    if (result) {
        media.coordinates =
            fr.free.nrw.commons.location.LatLng(
                coordinatesInfo.latitude.toDouble(),
                coordinatesInfo.longitude.toDouble(),
                coordinatesInfo.accuracy.toFloat(),
            )
        title += ": " + context.getString(R.string.coordinates_edit_helper_show_edit_title_success)
        message =
            context.getString(
                R.string.coordinates_edit_helper_show_edit_message,
                media.coordinates.toString(),
            )
    } else {
        title += ": " + context.getString(R.string.coordinates_edit_helper_show_edit_title)
        message = context.getString(R.string.coordinates_edit_helper_edit_message_else)
    }

    val urlForFile = BuildConfig.COMMONS_URL + "/wiki/" + media.filename
    val browserIntent = Intent(Intent.ACTION_VIEW, urlForFile.toUri())
    notificationHelper.showNotification(
        context,
        title,
        message,
        NOTIFICATION_EDIT_COORDINATES,
        browserIntent,
    )
    return result
}

object CryptoUtils {
    private const val ANDROID_KEYSTORE = "AndroidKeyStore"
    private const val KEY_ALIAS = "commons_cookie_store_key"
    private const val TRANSFORMATION = "AES/GCM/NoPadding"
    private const val IV_LENGTH = 12

    private fun getOrGenerateKey(): SecretKey {
        val keyStore = KeyStore.getInstance(ANDROID_KEYSTORE).apply { load(null) }
        keyStore.getKey(KEY_ALIAS, null)?.let { return it as SecretKey }

        val keyGenerator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, ANDROID_KEYSTORE)
        val spec = KeyGenParameterSpec.Builder(
            KEY_ALIAS,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
        )
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setKeySize(256)
            .build()
        keyGenerator.init(spec)
        return keyGenerator.generateKey()
    }

    /**
     * Encrypts the given plaintext string using AES-GCM and Android KeyStore.
     */
    fun encrypt(plaintext: String?): String? {
        if (plaintext == null) return null
        return try {
            val cipher = Cipher.getInstance(TRANSFORMATION)
            cipher.init(Cipher.ENCRYPT_MODE, getOrGenerateKey())
            val iv = cipher.iv
            val ciphertext = cipher.doFinal(plaintext.toByteArray(Charsets.UTF_8))
            val combined = iv + ciphertext
            Base64.encodeToString(combined, Base64.DEFAULT)
        } catch (e: Exception) {
            Timber.e(e, "Error encrypting data")
            null
        }
    }

    /**
     * Decrypts the given base64 encrypted string using AES-GCM and Android KeyStore.
     * Returns the input string if decryption fails (useful for migration from plaintext).
     */
    fun decrypt(encryptedBase64: String?): String? {
        if (encryptedBase64 == null) return null
        return try {
            val combined = Base64.decode(encryptedBase64, Base64.DEFAULT)
            if (combined.size <= IV_LENGTH) return encryptedBase64

            val iv = combined.copyOfRange(0, IV_LENGTH)
            val ciphertext = combined.copyOfRange(IV_LENGTH, combined.size)
            val cipher = Cipher.getInstance(TRANSFORMATION)
            val spec = GCMParameterSpec(128, iv)
            cipher.init(Cipher.DECRYPT_MODE, getOrGenerateKey(), spec)
            val plaintext = cipher.doFinal(ciphertext)
            String(plaintext, Charsets.UTF_8)
        } catch (e: Exception) {
            Timber.w(e, "Decryption failed, assuming plaintext (migration)")
            // It might be plaintext (before migration), so return it directly
            encryptedBase64
        }
    }
}

