fun onThumbnailClicked(
    position: Int,
    holder: ImageAdapter.ImageViewHolder,
    images: List<Image>,
    actionableImagesMap: TreeMap<Int, Image>,
    notifyItemChanged: (Int, Any?) -> Unit,
) {
    val sharedPreferences: SharedPreferences =
        context.getSharedPreferences(CUSTOM_SELECTOR_PREFERENCE_KEY, 0)
    val switchState =
        sharedPreferences.getBoolean(SHOW_ALREADY_ACTIONED_IMAGES_PREFERENCE_KEY, true)

    // While switch is turned off, lets user click on image only if the position is
    // added inside map
    if (!switchState) {
        if (actionableImagesMap.size > position) {
            selectOrRemoveImage(holder, position, images, actionableImagesMap, notifyItemChanged)
        }
    } else {
        selectOrRemoveImage(holder, position, images, actionableImagesMap, notifyItemChanged)
    }
}

private fun selectOrRemoveImage(
    holder: ImageAdapter.ImageViewHolder,
    position: Int,
    images: List<Image>,
    actionableImagesMap: TreeMap<Int, Image>,
    notifyItemChanged: (Int, Any?) -> Unit,
) {
    val sharedPreferences: SharedPreferences =
        context.getSharedPreferences(CUSTOM_SELECTOR_PREFERENCE_KEY, 0)
    val showAlreadyActionedImages =
        sharedPreferences.getBoolean(SHOW_ALREADY_ACTIONED_IMAGES_PREFERENCE_KEY, true)

    val image =
        if (showAlreadyActionedImages) {
            images[position]
        } else {
            ArrayList(actionableImagesMap.values)[position]
        }

    if (singleSelection) {
        // If single selection mode, clear previous selection and select only the new one
        if (selectedImages.isNotEmpty() && (selectedImages[0] != image)) {
            val prevIndex = images.indexOf(selectedImages[0])
            selectedImages.clear()
            notifyItemChanged(prevIndex, ImageAdapter.ImageUnselected())
        }
    }

    // Getting clicked index from all images index when show_already_actioned_images
    // switch is on
    val clickedIndex: Int = ImageHelper.getIndex(selectedImages, image)

    if (clickedIndex != -1) {
        deselectImage(holder, position, clickedIndex, notifyItemChanged)
    } else {
        selectImage(holder, position, image, notifyItemChanged)
    }
}

private fun deselectImage(
    holder: ImageAdapter.ImageViewHolder,
    position: Int,
    clickedIndex: Int,
    notifyItemChanged: (Int, Any?) -> Unit,
) {
    selectedImages.removeAt(clickedIndex)
    if (holder.isItemNotForUpload()) {
        numberOfSelectedImagesMarkedAsNotForUpload--
    }
    notifyItemChanged(position, ImageAdapter.ImageUnselected())
    // Notify listener of deselection to update UI
    imageSelectListener.onSelectedImagesChanged(
        selectedImages,
        numberOfSelectedImagesMarkedAsNotForUpload,
    )
}

private fun selectImage(
    holder: ImageAdapter.ImageViewHolder,
    position: Int,
    image: Image,
    notifyItemChanged: (Int, Any?) -> Unit,
) {
    // check the maximum limit before allowing the selection
    if (!singleSelection && selectedImages.size >= maxUploadLimit) {
        // limit reached, show a toast and prevent selection
        Toast
            .makeText(
                context,
                context.getString(
                    R.string.custom_selector_max_image_limit_reached,
                    maxUploadLimit,
                ),
                Toast.LENGTH_SHORT,
            ).show()
        return // exit the function, preventing selection
    }

    // Prevent adding the same image multiple times
    if (selectedImages.contains(image)) {
        return // Image already selected, ignore additional clicks
    }
    scope.launch(ioDispatcher) {
        val imageSHA1 = imageLoader.getSHA1(image, defaultDispatcher)
        withContext(Dispatchers.Main) {
            handleUploadedCheckAndSelection(
                holder,
                position,
                image,
                imageSHA1,
                notifyItemChanged,
            )
        }
    }
}

private suspend fun handleUploadedCheckAndSelection(
    holder: ImageAdapter.ImageViewHolder,
    position: Int,
    image: Image,
    imageSHA1: String?,
    notifyItemChanged: (Int, Any?) -> Unit,
) {
    if (holder.isItemUploaded()) {
        Toast
            .makeText(
                context,
                R.string.custom_selector_already_uploaded_image_text,
                Toast.LENGTH_SHORT,
            ).show()
        return
    }

    val uploadedStatus =
        if (!imageSHA1.isNullOrEmpty()) {
            imageLoader.getFromUploaded(imageSHA1)
        } else {
            null
        }
    val isUploaded =
        uploadedStatus?.let {
            imageLoader.getResultFromUploadedStatus(it) == ImageLoader.Result.TRUE
        } ?: false

    if (isUploaded) {
        holder.itemUploaded()
        Toast
            .makeText(
                context,
                R.string.custom_selector_already_uploaded_image_text,
                Toast.LENGTH_SHORT,
            ).show()
        return
    }

    if (holder.isItemNotForUpload()) {
        numberOfSelectedImagesMarkedAsNotForUpload++
    }
    selectedImages.add(image)
    notifyItemChanged(position, ImageAdapter.ImageSelectedOrUpdated())
    imageSelectListener.onSelectedImagesChanged(
        selectedImages,
        numberOfSelectedImagesMarkedAsNotForUpload,
    )
}

fun setSelectedImages(newSelectedImages: ArrayList<Image>) {
    selectedImages = ArrayList(newSelectedImages)
    imageSelectListener.onSelectedImagesChanged(selectedImages, 0)
}

fun clearSelectedImages() {
    numberOfSelectedImagesMarkedAsNotForUpload = 0
    selectedImages.clear()
    selectedImages = arrayListOf()
}

fun reset() {
    numberOfSelectedImagesMarkedAsNotForUpload = 0
    selectedImages = ArrayList()
}

open class OnSwipeTouchListener(
    context: Context?,
) : View.OnTouchListener {
    private val gestureDetector: GestureDetector

    private val swipeThresholdHeight = (getScreenResolution(context!!)).second / SWIPE_THRESHOLD_SCREEN_DIVISOR
    private val swipeThresholdWidth = (getScreenResolution(context!!)).first / SWIPE_THRESHOLD_SCREEN_DIVISOR
    private val swipeVelocityThreshold = SWIPE_VELOCITY_THRESHOLD

    override fun onTouch(
        view: View?,
        motionEvent: MotionEvent,
    ): Boolean = gestureDetector.onTouchEvent(motionEvent)

    fun getScreenResolution(context: Context): Pair<Int, Int> {
        val wm: WindowManager = context.getSystemService(Context.WINDOW_SERVICE) as WindowManager
        val display: Display = wm.getDefaultDisplay()
        val metrics = DisplayMetrics()
        display.getMetrics(metrics)
        val width: Int = metrics.widthPixels
        val height: Int = metrics.heightPixels
        return width to height
    }

    inner class GestureListener : GestureDetector.SimpleOnGestureListener() {
        override fun onDown(e: MotionEvent): Boolean = false

        /**
         * Detects the gestures
         */
        override fun onFling(
            event1: MotionEvent?,
            event2: MotionEvent,
            velocityX: Float,
            velocityY: Float,
        ): Boolean {
            try {
                val diffY: Float = event2.y - (event1?.y ?: event2.y)
                val diffX: Float = event2.x - (event1?.x ?: event2.x)
                if (abs(diffX) > abs(diffY)) {
                    if (abs(diffX) > swipeThresholdWidth &&
                        abs(velocityX) >
                        swipeVelocityThreshold
                    ) {
                        if (diffX > 0) {
                            onSwipeRight()
                        } else {
                            onSwipeLeft()
                        }
                    }
                } else {
                    if (abs(diffY) > swipeThresholdHeight &&
                        abs(velocityY) >
                        swipeVelocityThreshold
                    ) {
                        if (diffY > 0) {
                            onSwipeDown()
                        } else {
                            onSwipeUp()
                        }
                    }
                }
            } catch (exception: Exception) {
                Timber.e(exception, "Could not process fling gesture")
            }
            return false
        }
    }

    /**
     * Swipe right to view previous image
     */
    open fun onSwipeRight() {}

    /**
     * Swipe left to view next image
     */
    open fun onSwipeLeft() {}

    /**
     * Swipe up to select the picture (the equivalent of tapping it in non-fullscreen mode)
     * and show the next picture skipping pictures that have either already been uploaded or
     * marked as not for upload
     */
    open fun onSwipeUp() {}

    /**
     * Swipe down to mark that picture as "Not for upload" (the equivalent of selecting it then
     * tapping "Mark as not for upload" in non-fullscreen mode), and show the next picture.
     */
    open fun onSwipeDown() {}

    init {
        gestureDetector = GestureDetector(context, GestureListener())
    }
}

override fun onFling(
    event1: MotionEvent?,
    event2: MotionEvent,
    velocityX: Float,
    velocityY: Float,
): Boolean {
    try {
        val diffY: Float = event2.y - (event1?.y ?: event2.y)
        val diffX: Float = event2.x - (event1?.x ?: event2.x)
        if (abs(diffX) > abs(diffY)) {
            if (abs(diffX) > swipeThresholdWidth &&
                abs(velocityX) >
                swipeVelocityThreshold
            ) {
                if (diffX > 0) {
                    onSwipeRight()
                } else {
                    onSwipeLeft()
                }
            }
        } else {
            if (abs(diffY) > swipeThresholdHeight &&
                abs(velocityY) >
                swipeVelocityThreshold
            ) {
                if (diffY > 0) {
                    onSwipeDown()
                } else {
                    onSwipeUp()
                }
            }
        }
    } catch (exception: Exception) {
        Timber.e(exception, "Could not process fling gesture")
    }
    return false
}

