fun makeDeletion(
    context: Context?,
    media: Media?,
    reason: String?,
): Single<Boolean>? {
    if (context == null && media == null) {
        return null
    }

    viewUtil.showShortToast(
        context!!,
        "Trying to nominate ${media?.displayTitle} for deletion",
    )

    return reason?.let {
        delete(media!!, it)
            .flatMapSingle { result ->
                Single.just(showDeletionNotification(context, media, result))
            }.firstOrError()
            .onErrorResumeNext { throwable ->
                if (throwable is InvalidLoginTokenException) {
                    Single.error(throwable)
                } else {
                    Single.error(throwable)
                }
            }
    }
}

private fun delete(
    media: Media,
    reason: String,
): Observable<Boolean> {
    val summary = "Nominating ${media.filename} for deletion."
    val calendar = Calendar.getInstance()
    val fileDeleteString =
        """
        {{delete|reason=$reason|subpage=${media.filename}|day=
        ${calendar.get(Calendar.DAY_OF_MONTH)}|month=${
            calendar.getDisplayName(
                Calendar.MONTH,
                Calendar.LONG,
                Locale.ENGLISH,
            )
        }|year=${calendar.get(Calendar.YEAR)}}}
        """.trimIndent()

    val subpageString =
        """
        === [[:${media.filename}]] ===
        $reason ~~~~
        """.trimIndent()

    val logPageString = "\n{{Commons:Deletion requests/${media.filename}}}\n"
    // The log page title needs Western digits whatever the device language is.
    // Bad:  https://commons.wikimedia.org/wiki/Commons:Deletion_requests/২০২৩/০৭/০৬
    // Good: https://commons.wikimedia.org/wiki/Commons:Deletion_requests/2023/07/06
    val sdf = SimpleDateFormat("yyyy/MM/dd", Locale.ENGLISH)
    val date = sdf.format(calendar.time)

    val userPageString = "\n{{subst:idw|${media.filename}}} ~~~~"

    val creator =
        media.getAuthorOrUser()
            ?: error("Failed to nominate for deletion")

    return pageEditClient
        .prependEdit(
            media.filename!!,
            "$fileDeleteString\n",
            summary,
        ).onErrorResumeNext { throwable: Throwable ->
            if (throwable is InvalidLoginTokenException) {
                Observable.error(throwable)
            } else {
                Observable.error(throwable)
            }
        }.flatMap { result: Boolean ->
            if (result) {
                pageEditClient.edit(
                    "Commons:Deletion_requests/${media.filename}",
                    "$subpageString\n",
                    summary,
                )
            } else {
                Observable.error(RuntimeException("Failed to nominate for deletion"))
            }
        }.flatMap { result: Boolean ->
            if (result) {
                pageEditClient.appendEdit(
                    "Commons:Deletion_requests/$date",
                    "$logPageString\n",
                    summary,
                )
            } else {
                Observable.error(RuntimeException("Failed to nominate for deletion"))
            }
        }.flatMap { result: Boolean ->
            if (result) {
                pageEditClient.appendEdit("User_Talk:$creator", "$userPageString\n", summary)
            } else {
                Observable.error(RuntimeException("Failed to nominate for deletion"))
            }
        }
}

