    ivMatrix: Matrix,
): Pair<Int, Handle>? {
    var match: Pair<Int, Handle>? = null
    for (i in regions.indices) {
        val region = regions[i]
        if (match == null && region.width() > 0 && region.height() > 0) {
            val handle = handleAt(region, screenX, screenY, ivMatrix)
            if (handle != null) {
                match = i to handle
