    imgX: Float,
    imgY: Float,
) {
    val region = regions[index]
    val minSize = minRegionSize

    when (handle) {
        Handle.TOP_LEFT -> {
            region.left = min(imgX, region.right - minSize)
            region.top = min(imgY, region.bottom - minSize)
        }
        Handle.TOP_RIGHT -> {
            region.right = max(imgX, region.left + minSize)
            region.top = min(imgY, region.bottom - minSize)
        }
        Handle.BOTTOM_LEFT -> {
            region.left = min(imgX, region.right - minSize)
            region.bottom = max(imgY, region.top + minSize)
        }
        Handle.BOTTOM_RIGHT -> {
            region.right = max(imgX, region.left + minSize)
            region.bottom = max(imgY, region.top + minSize)
        }
        Handle.TOP -> {
            region.top = min(imgY, region.bottom - minSize)
        }
        Handle.BOTTOM -> {
            region.bottom = max(imgY, region.top + minSize)
        }
        Handle.LEFT -> {
            region.left = min(imgX, region.right - minSize)
        }
        Handle.RIGHT -> {
            region.right = max(imgX, region.left + minSize)
        }
    }
}

fun snapRectToMCU(rect: RectF) {
    // Pre-check.
    val image = mcuImage()?.takeIf { it.mcuWidth > 0 && it.mcuHeight > 0 } ?: return

    // MCU size in drawable-pixel space.
    val mcuW = image.mcuWidth.toFloat() * image.drawableWidth / image.width
    val mcuH = image.mcuHeight.toFloat() * image.drawableHeight / image.height
    val maxW = image.drawableWidth.toFloat()
    val maxH = image.drawableHeight.toFloat()

    val widthRemainder = rect.width() % mcuW
    val widthAligned = widthRemainder < MCU_SIZE_TOLERANCE || widthRemainder > (mcuW - MCU_SIZE_TOLERANCE)
    val heightRemainder = rect.height() % mcuH
    val heightAligned = heightRemainder < MCU_SIZE_TOLERANCE || heightRemainder > (mcuH - MCU_SIZE_TOLERANCE)

    // Already MCU-sized, Snap to nearest border position only, preserve size.
    if (widthAligned && heightAligned) {
        val w = rect.width()
        val h = rect.height()
        rect.left = round(rect.left / mcuW) * mcuW
        rect.top = round(rect.top / mcuH) * mcuH
        rect.right = rect.left + w
        rect.bottom = rect.top + h

        // Shift back if pushed past total image size.
        if (rect.right > maxW) {
            rect.offset(maxW - rect.right, 0f)
        }
        if (rect.bottom > maxH) {
            rect.offset(0f, maxH - rect.bottom)
        }
        if (rect.left < 0f) {
            rect.offset(-rect.left, 0f)
        }
        if (rect.top < 0f) {
            rect.offset(0f, -rect.top)
        }
    } else {
        // Not aligned, Expand outward to full MCU blocks.
        rect.left = floor(rect.left.toDouble() / mcuW).toFloat() * mcuW
        rect.top = floor(rect.top.toDouble() / mcuH).toFloat() * mcuH
        rect.right = ceil(rect.right.toDouble() / mcuW).toFloat() * mcuW
        rect.bottom = ceil(rect.bottom.toDouble() / mcuH).toFloat() * mcuH

        // Clamp to drawable bounds.
        rect.left = max(0f, rect.left)
        rect.top = max(0f, rect.top)
        rect.right = min(maxW, rect.right)
        rect.bottom = min(maxH, rect.bottom)
    }
}

private fun handleAt(
    region: RectF,
    screenX: Float,
    screenY: Float,
    ivMatrix: Matrix,
): Handle? {
    // Corners.
    val corners =
        listOf(
            Handle.TOP_LEFT to floatArrayOf(region.left, region.top),
            Handle.TOP_RIGHT to floatArrayOf(region.right, region.top),
            Handle.BOTTOM_LEFT to floatArrayOf(region.left, region.bottom),
            Handle.BOTTOM_RIGHT to floatArrayOf(region.right, region.bottom),
        )
    // Edges (midpoints).
    val edges =
        listOf(
            Handle.TOP to floatArrayOf(region.centerX(), region.top),
            Handle.BOTTOM to floatArrayOf(region.centerX(), region.bottom),
            Handle.LEFT to floatArrayOf(region.left, region.centerY()),
            Handle.RIGHT to floatArrayOf(region.right, region.centerY()),
        )
    return firstNear(corners, screenX, screenY, ivMatrix, cornerTouchSlop)
        ?: firstNear(edges, screenX, screenY, ivMatrix, edgeTouchSlop)
}

private fun firstNear(
    candidates: List<Pair<Handle, FloatArray>>,
    screenX: Float,
    screenY: Float,
    ivMatrix: Matrix,
    slop: Float,
): Handle? {
    val point = FloatArray(2)
    var found: Handle? = null
    for ((handle, imagePoint) in candidates) {
        if (found != null) break
        point[0] = imagePoint[0]
        point[1] = imagePoint[1]
        ivMatrix.mapPoints(point)
        if (isNearScreen(screenX, screenY, point[0], point[1], slop)) {
            found = handle
        }
    }
    return found
}

private fun isNearScreen(
    x: Float,
    y: Float,
    targetX: Float,
    targetY: Float,
    slop: Float,
): Boolean {
    val dx = x - targetX
    val dy = y - targetY
    return dx * dx + dy * dy <= slop * slop
}

fun sourceOf(
    properties: Properties?,
    drawable: Drawable?,
): McuImageSource? =
    if (properties == null || drawable == null) {
        null
    }

fun setImageBounds(
    left: Float,
    top: Float,
    right: Float,
    bottom: Float,
) {
    imageBounds.set(left, top, right, bottom)
    resetCropRect()
    invalidate()
}

fun resetCropRect() {
    if (!imageBounds.isEmpty) {
        cropRect.set(imageBounds)
    } else {
        val padding = 50f * density
        cropRect.set(
            padding,
            padding,
            width.toFloat() - padding,
            height.toFloat() - padding,
        )
    }
    invalidate()
}

internal class CropRectEditor(
    private val cropRect: RectF,
    private val minCropSize: Float,
    private val cornerTouchSlop: Float,
    private val edgeTouchSlop: Float,
) {
    /**
     * A corner, edge, or the interior of the crop rectangle that a drag can move.
     */
    enum class Handle {
        TOP_LEFT,
        TOP_RIGHT,
        BOTTOM_LEFT,
        BOTTOM_RIGHT,
        TOP,
        BOTTOM,
        LEFT,
        RIGHT,
        CENTER,
    }

    /**
     * Returns the handle under [x] and [y]. Corners win over edges, and the interior selects the center.
     */
    fun findHandle(
        x: Float,
        y: Float,
    ): Handle? {
        // Check corners first with larger touch zone (priority over edges)
        val corners =
            listOf(
                Triple(Handle.TOP_LEFT, cropRect.left, cropRect.top),
                Triple(Handle.TOP_RIGHT, cropRect.right, cropRect.top),
                Triple(Handle.BOTTOM_LEFT, cropRect.left, cropRect.bottom),
                Triple(Handle.BOTTOM_RIGHT, cropRect.right, cropRect.bottom),
            )
        val corner = corners.firstOrNull { (_, handleX, handleY) -> isNear(x, y, handleX, handleY, cornerTouchSlop) }

        // Then check edges with smaller touch zone
        val edges =
            listOf(
                Triple(Handle.TOP, cropRect.centerX(), cropRect.top),
                Triple(Handle.BOTTOM, cropRect.centerX(), cropRect.bottom),
                Triple(Handle.LEFT, cropRect.left, cropRect.centerY()),
                Triple(Handle.RIGHT, cropRect.right, cropRect.centerY()),
            )
        val edge =
            if (corner == null) {
                edges.firstOrNull { (_, handleX, handleY) -> isNear(x, y, handleX, handleY, edgeTouchSlop) }
            } else {
                null
            }

        // Check center last (for moving the entire crop area)
        return when {
            corner != null -> corner.first
            edge != null -> edge.first
            cropRect.contains(x, y) -> Handle.CENTER
            else -> null
        }
    }

    /**
     * Moves [handle] by [dx] and [dy], keeping the crop rectangle inside [bounds] and at least the minimum size.
     */
    fun moveHandle(
        handle: Handle,
        dx: Float,
        dy: Float,
        bounds: RectF,
    ) {
        when (handle) {
            Handle.TOP_LEFT -> {
                cropRect.left = constrainMin(cropRect.left + dx, bounds.left, cropRect.right - minCropSize)
                cropRect.top = constrainMin(cropRect.top + dy, bounds.top, cropRect.bottom - minCropSize)
            }
            Handle.TOP_RIGHT -> {
                cropRect.right = constrainMax(cropRect.right + dx, cropRect.left + minCropSize, bounds.right)
                cropRect.top = constrainMin(cropRect.top + dy, bounds.top, cropRect.bottom - minCropSize)
            }
            Handle.BOTTOM_LEFT -> {
                cropRect.left = constrainMin(cropRect.left + dx, bounds.left, cropRect.right - minCropSize)
                cropRect.bottom = constrainMax(cropRect.bottom + dy, cropRect.top + minCropSize, bounds.bottom)
            }
            Handle.BOTTOM_RIGHT -> {
                cropRect.right = constrainMax(cropRect.right + dx, cropRect.left + minCropSize, bounds.right)
                cropRect.bottom = constrainMax(cropRect.bottom + dy, cropRect.top + minCropSize, bounds.bottom)
            }
            Handle.TOP -> {
                cropRect.top = constrainMin(cropRect.top + dy, bounds.top, cropRect.bottom - minCropSize)
            }
            Handle.BOTTOM -> {
                cropRect.bottom = constrainMax(cropRect.bottom + dy, cropRect.top + minCropSize, bounds.bottom)
            }
            Handle.LEFT -> {
                cropRect.left = constrainMin(cropRect.left + dx, bounds.left, cropRect.right - minCropSize)
            }
            Handle.RIGHT -> {
                cropRect.right = constrainMax(cropRect.right + dx, cropRect.left + minCropSize, bounds.right)
            }
            Handle.CENTER -> moveCenter(dx, dy, bounds)
        }
    }

    /**
     * Shifts the whole crop rectangle by [dx] and [dy], sliding it back inside [bounds] so its size stays the same.
     */
    private fun moveCenter(
        dx: Float,
        dy: Float,
        bounds: RectF,
    ) {
        var newLeft = cropRect.left + dx
        var newTop = cropRect.top + dy
        var newRight = cropRect.right + dx
        var newBottom = cropRect.bottom + dy

        // Keep within bounds
        if (newLeft < bounds.left) {
            newRight += bounds.left - newLeft
            newLeft = bounds.left
        }
        if (newRight > bounds.right) {
            newLeft -= newRight - bounds.right
            newRight = bounds.right
        }
        if (newTop < bounds.top) {
            newBottom += bounds.top - newTop
            newTop = bounds.top
        }
        if (newBottom > bounds.bottom) {
            newTop -= newBottom - bounds.bottom
            newBottom = bounds.bottom
        }

        cropRect.set(newLeft, newTop, newRight, newBottom)
    }

    /**
     * Clamps [value] so a dragged edge cannot pass [min] or the opposite edge at [max].
     */
    private fun constrainMin(
        value: Float,
        min: Float,
        max: Float,
    ): Float = max(min, min(value, max))

    /**
     * Clamps [value] so a dragged edge cannot pass the opposite edge at [min] or the bound at [max].
     */
    private fun constrainMax(
        value: Float,
        min: Float,
        max: Float,
    ): Float = max(min, min(value, max))

    /**
     * Returns whether [x] and [y] lie within [slop] pixels of ([targetX], [targetY]).
     */
    private fun isNear(
        x: Float,
        y: Float,
        targetX: Float,
        targetY: Float,
        slop: Float,
    ): Boolean {
        val dx = x - targetX
        val dy = y - targetY
        return dx * dx + dy * dy <= slop * slop
    }
}

fun findHandle(
    x: Float,
    y: Float,
): Handle? {
    // Check corners first with larger touch zone (priority over edges)
    val corners =
        listOf(
            Triple(Handle.TOP_LEFT, cropRect.left, cropRect.top),
            Triple(Handle.TOP_RIGHT, cropRect.right, cropRect.top),
            Triple(Handle.BOTTOM_LEFT, cropRect.left, cropRect.bottom),
            Triple(Handle.BOTTOM_RIGHT, cropRect.right, cropRect.bottom),
        )
    val corner = corners.firstOrNull { (_, handleX, handleY) -> isNear(x, y, handleX, handleY, cornerTouchSlop) }

    // Then check edges with smaller touch zone
    val edges =
        listOf(
            Triple(Handle.TOP, cropRect.centerX(), cropRect.top),
            Triple(Handle.BOTTOM, cropRect.centerX(), cropRect.bottom),
            Triple(Handle.LEFT, cropRect.left, cropRect.centerY()),
            Triple(Handle.RIGHT, cropRect.right, cropRect.centerY()),
        )
    val edge =
        if (corner == null) {
            edges.firstOrNull { (_, handleX, handleY) -> isNear(x, y, handleX, handleY, edgeTouchSlop) }
        } else {
            null
        }

    // Check center last (for moving the entire crop area)
    return when {
        corner != null -> corner.first
        edge != null -> edge.first
        cropRect.contains(x, y) -> Handle.CENTER
        else -> null
    }
}

val edges =
