    if (placeList == null) {
        return baseMarkerList
    }

    var vectorDrawable: VectorDrawableCompat? = null
    try {
        vectorDrawable =
            VectorDrawableCompat.create(
                context.resources,
                R.drawable.ic_custom_map_marker_dark,
