override fun insert(
    uri: Uri,
    contentValues: ContentValues?,
): Uri? {
    val uriType = uriMatcher.match(uri)
    val id: Long? =
        when (uriType) {
            RECENT_SEARCHES ->
                contentValues?.let {
                    requireDb().insert(TABLE_NAME, SQLiteDatabase.CONFLICT_NONE, it)
                }

            else -> throw IllegalArgumentException("Unknown URI: $uri")
        }
    context?.contentResolver?.notifyChange(uri, null)
    return "$BASE_URI/$id".toUri()
}

override fun delete(
    uri: Uri,
    s: String?,
    strings: Array<String>?,
): Int {
    val rows: Int
    val uriType = uriMatcher.match(uri)
    when (uriType) {
        RECENT_SEARCHES_ID -> {
            rows =
                requireDb().delete(
                    TABLE_NAME,
                    "_id = ?",
                    arrayOf(uri.lastPathSegment),
                )
        }

        else -> throw IllegalArgumentException("Unknown URI - $uri")
    }
    context?.contentResolver?.notifyChange(uri, null)
    return rows
}

override fun bulkInsert(
    uri: Uri,
    values: Array<ContentValues>,
): Int {
    val uriType = uriMatcher.match(uri)
    val sqlDB = requireDb()
    sqlDB.beginTransaction()
    when (uriType) {
        RECENT_SEARCHES -> for (value in values) {
            sqlDB.insert(TABLE_NAME, SQLiteDatabase.CONFLICT_NONE, value)
        }

        else -> throw IllegalArgumentException("Unknown URI: $uri")
    }
    sqlDB.setTransactionSuccessful()
    sqlDB.endTransaction()
    context?.contentResolver?.notifyChange(uri, null)
    return values.size
}

override fun update(
    uri: Uri,
    contentValues: ContentValues?,
    selection: String?,
    selectionArgs: Array<String>?,
): Int {
    /*
    SQL Injection warnings: First, note that we're not exposing this to the
    outside world (exported="false"). Even then, we should make sure to sanitize
    all user input appropriately. Input that passes through ContentValues
    should be fine. So only issues are those that pass in via concating.

    In here, the only concat created argument is for id. It is cast to an int,
    and will error out otherwise.
     */
    val uriType = uriMatcher.match(uri)
    var rowsUpdated: Int = 0
    when (uriType) {
        RECENT_SEARCHES_ID -> {
            require(selection.isNullOrEmpty()) {
                "Parameter `selection` should be empty when updating an ID"
            }
            val id = uri.lastPathSegment!!.toInt()
            contentValues?.let {
                rowsUpdated =
                    requireDb().update(
                        TABLE_NAME,
                        SQLiteDatabase.CONFLICT_NONE,
                        it,
                        "$COLUMN_ID = ?",
                        arrayOf(id.toString()),
                    )
            }
        }

        else -> throw IllegalArgumentException("Unknown URI: $uri with type $uriType")
    }
    context?.contentResolver?.notifyChange(uri, null)
    return rowsUpdated
}

fun save(recentSearch: RecentSearch) {
    val db = clientProvider.get()
    try {
        val contentValues = toContentValues(recentSearch)
        if (recentSearch.contentUri == null) {
            recentSearch.contentUri = db.insert(BASE_URI, contentValues)
        } else {
            db.update(recentSearch.contentUri!!, contentValues, null, null)
        }
    } catch (e: RemoteException) {
        throw IllegalStateException(e)
    } finally {
        db.release()
    }
}

