    try {
        cursor =
            db.query(
                BASE_URI,
                ALL_FIELDS,
                "$COLUMN_NAME=?",
                arrayOf(name),
                null,
            )
        if (cursor != null && cursor.moveToFirst()) {
            return fromCursor(cursor)
        }
    } catch (e: RemoteException) {
        // This feels lazy, but to hell with checked exceptions. :)
        throw IllegalStateException(e)
    } finally {
        cursor?.close()
        db.release()
    }
    return null
}

