            .makeCoordinatesEdit(
                applicationContext,
                it,
                "0.0",
                "0.0",
                "0.0f",
            )?.subscribeOn(Schedulers.io())
            ?.observeOn(AndroidSchedulers.mainThread())
            ?.subscribe { _ ->
                Timber.d("Coordinates removed from the image")
            }?.let { it1 ->
