fun Throwable?.isFileDeletedOnCommons(): Boolean {
    var current = this
    var deleted = false
    while (current != null && !deleted) {
        deleted =
            current is FileDeletedOnCommonsException ||
            (current as? MwIOException)?.error?.code == "missingtitle"
        current = current.cause
    }
    return deleted
}

