internal fun MediaDetailFragment.launchZoomActivity(view: View) {
    if (media!!.imageUrl != null) {
        val ctx: Context = view.context
        val zoomableIntent = Intent(ctx, ZoomableActivity::class.java)
        zoomableIntent.setData(Uri.parse(media!!.imageUrl))
        zoomableIntent.putExtra(
            ZoomableActivity.ZoomableActivityConstants.ORIGIN,
            "MediaDetails",
        )

        val backgroundColor: Int = imageBackgroundColor
        if (backgroundColor != DEFAULT_IMAGE_BACKGROUND_COLOR) {
            zoomableIntent.putExtra(
                ZoomableActivity.ZoomableActivityConstants.PHOTO_BACKGROUND_COLOR,
                backgroundColor,
            )
        }

        ctx.startActivity(
            zoomableIntent,
        )
    }
}

internal fun MediaDetailFragment.setupImageView(media: Media? = this.media) {
    val imageBackgroundColor: Int = imageBackgroundColor
    if (imageBackgroundColor != DEFAULT_IMAGE_BACKGROUND_COLOR) {
        binding.mediaDetailImageView.setBackgroundColor(imageBackgroundColor)
    }

    binding.mediaDetailImageView.hierarchy.setPlaceholderImage(R.drawable.image_placeholder)
    binding.mediaDetailImageView.hierarchy.setFailureImage(R.drawable.image_placeholder)
    binding.mediaDetailImageProgressBar.visibility = View.VISIBLE

    val fullImageUrl =
        if (media?.mediaType == MediaType.VIDEO ||
            media?.mediaType == MediaType.AUDIO
        ) {
            media.thumbUrl
        } else {
            media?.imageUrl
        }
    val controller: DraweeController =
        Fresco
            .newDraweeControllerBuilder()
            .setLowResImageRequest(ImageRequest.fromUri(media?.thumbUrl))
            .setRetainImageOnFailure(true)
            .setImageRequest(ImageRequest.fromUri(fullImageUrl))
            .setControllerListener(aspectRatioListener)
            .setOldController(binding.mediaDetailImageView.controller)
            .build()
    binding.mediaDetailImageView.controller = controller
}

internal fun MediaDetailFragment.setupMediaView(media: Media) {
    // A thumbnail is always shown initially because audio and video have thumbnails.
    setupImageView(media)
    configureFullscreenButton(media.mediaType)

    when (media.mediaType) {
        MediaType.VIDEO,
        MediaType.AUDIO,
        -> showMediaPoster(playButton = true)
        MediaType.IMAGE,
        MediaType.OTHER,
        -> Unit
    }
}

internal fun MediaDetailFragment.onMediaClicked() {
    val media = media ?: return

    when (media.mediaType) {
        MediaType.VIDEO,
        MediaType.AUDIO,
        -> prepareMedia()
        MediaType.IMAGE -> launchZoomActivity(binding.mediaDetailImageView)
        MediaType.OTHER -> Unit
    }
}

internal fun MediaDetailFragment.revealMediaDetailWithoutImage(allowRetry: Boolean = true) {
    val currentBinding = this.currentBinding
    val scrollView = currentBinding?.mediaDetailScrollView
    if (currentBinding != null && scrollView != null && scrollView.isAttachedToWindow) {
        val scrollWidth = scrollView.width
        if (scrollWidth <= 0 && allowRetry) {
            scrollView.post { revealMediaDetailWithoutImage(allowRetry = false) }
        } else if (scrollWidth > 0) {
            val height = resources.getDimensionPixelSize(R.dimen.dimen_250)
            val params = currentBinding.mediaDetailMediaContainer.layoutParams
            val spacerParams = currentBinding.mediaDetailImageViewSpacer.layoutParams
            params.width = scrollWidth
            params.height = height
            spacerParams.height = height
            currentBinding.mediaDetailMediaContainer.layoutParams = params
            currentBinding.mediaDetailImageViewSpacer.layoutParams = spacerParams
            scrollView.visibility = View.VISIBLE
        }
    }
}

internal fun MediaDetailFragment.onImageBackgroundChanged(color: Int) {
    val currentColor: Int = imageBackgroundColor
    if (currentColor == color) {
        return
    }

    binding.mediaDetailImageView.setBackgroundColor(color)
    imageBackgroundColorPref.edit().putInt(IMAGE_BACKGROUND_COLOR_KEY, color).apply()
}

interface MediaDetailInterface {
    /**
     * Fetches entity using file name
     *
     * @param filename name of the file to be used for fetching captions
     */
    @GET("w/api.php?action=wbgetentities&props=labels&format=json&languagefallback=1&sites=commonswiki")
    fun fetchEntitiesByFileName(
        @Query("languages") language: String?,
        @Query("titles") filename: String?,
    ): Observable<Entities>

    /**
     * Gets labels for Depictions using Entity Id from MediaWikiAPI
     * @param entityId  EntityId (Ex: Q81566) of the depict entity
     */
    @GET("/w/api.php?format=json&action=wbgetentities&props=labels&languagefallback=1")
    fun getEntity(
        @Query("ids") entityId: String?,
    ): Single<Entities>

    /**
     * Fetches caption using wikibaseIdentifier
     *
     * @param wikibaseIdentifier pageId for the media
     */
    @GET("/w/api.php?action=wbgetentities&props=labels&format=json&languagefallback=1&sites=commonswiki")
    fun getEntityForImage(
        @Query("languages") language: String?,
        @Query("ids") wikibaseIdentifier: String?,
    ): Observable<Entities>

    /**
     * Fetches current wikitext
     * @param title file name
     * @return Single<MwQueryResponse>
     </MwQueryResponse> */
    @GET(
        WikidataConstants.MW_API_PREFIX +
            "action=query&prop=revisions&rvprop=content|timestamp&rvlimit=1&converttitles=",
    )
    fun getWikiText(
        @Query("titles") title: String?,
    ): Single<MwQueryResponse>
}

internal fun MediaDetailFragment.fetchFileUsages(fileName: String) {
    if (viewModel.commonsContainerState.value == MediaDetailViewModel.FileUsagesContainerState.Initial) {
        viewModel.loadFileUsagesCommons(fileName)
    }

    if (viewModel.globalContainerState.value == MediaDetailViewModel.FileUsagesContainerState.Initial) {
        viewModel.loadGlobalFileUsages(fileName)
    }
}

internal fun MediaDetailFragment.getContributionsFragmentParent(): ContributionsFragment? {
    var fragment: Fragment? = this

    while (fragment != null && fragment !is ContributionsFragment) {
        fragment = fragment.parentFragment
    }

    if (fragment == null) {
        return null
    }

    return fragment as ContributionsFragment
}

internal fun MediaDetailFragment.displayMediaDetails() {
    if (mediaDetailPlayer.player == null) {
        setupMediaView(media!!)
    }
    setTextFields(media!!)
    viewDisposables.addAll(
        mediaDataExtractor
            .refresh(media!!)
            .subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe(
                { media: Media -> onMediaRefreshed(media) },
                { t: Throwable? ->
                    if (t.isFileDeletedOnCommons()) {
                        onFileDeletedFromCommons()
                    } else {
                        Timber.e(t)
                    }
                },
            ),
        mediaDataExtractor
            .getCurrentWikiText(
                Objects.requireNonNull(media?.filename!!),
            ).subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe(
                { s: String? -> updateCategoryList(s!!) },
                { t: Throwable? -> Timber.e(t) },
            ),
        mediaDataExtractor
            .checkDeletionRequestExists(media!!)
            .subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe(
                { deletionPageExists: Boolean -> onDeletionPageExists(deletionPageExists) },
                { t: Throwable? -> Timber.e(t) },
            ),
        mediaDataExtractor
            .fetchDiscussion(media!!)
            .subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe(
                { discussion: String -> onDiscussionLoaded(discussion) },
                { t: Throwable? -> Timber.e(t) },
            ),
    )
}

internal fun MediaDetailFragment.onMediaRefreshed(media: Media) {
    media.categories = this.media!!.categories
    this.media = media
    setTextFields(media)
    if (mediaDetailPlayer.player == null) {
        setupMediaView(media)
    }
    viewDisposables.addAll(
        mediaDataExtractor
            .fetchDepictionIdsAndLabels(media)
            .subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe(
                { idAndCaptions: List<IdAndLabels> -> onDepictionsLoaded(idAndCaptions) },
                { t: Throwable? -> Timber.e(t) },
            ),
    )
}

internal fun MediaDetailFragment.onDiscussionLoaded(discussion: String) {
    binding.mediaDetailDisc.text = prettyDiscussion(discussion.trim { it <= ' ' })
}

internal fun MediaDetailFragment.onDepictionsLoaded(idAndCaptions: List<IdAndLabels>) {
    binding.depictsLayout.visibility = View.VISIBLE
    binding.depictionsEditButton.visibility = View.VISIBLE
    buildDepictionList(idAndCaptions)
}

internal fun MediaDetailFragment.onFileDeletedFromCommons() {
    val currentMedia = media
    if (currentBinding != null && currentMedia != null) {
        val alreadyShown = fileWasDeletedFromCommons
        fileWasDeletedFromCommons = true
        revealMediaDetailWithoutImage()
        binding.deletedFileBanner.visibility = View.VISIBLE
        binding.nominateDeletion.visibility = View.GONE
        binding.nominatedDeletionBanner.visibility = View.GONE
        val filename = currentMedia.filename
        if (!alreadyShown && !filename.isNullOrEmpty()) {
            contributionsRepository
                .markCompletedContributionDeleted(filename)
                .subscribeOn(Schedulers.io())
                .subscribe(
                    {
                        // No action needed after successful deletion
                    },
                    { t: Throwable -> Timber.e(t, "Failed to mark contribution deleted") },
                )
            if (isAdded) {
                DeletedFileActivity.start(requireContext(), filename)
            }
        }
    }
}

class MediaDetailMenuHandler
    @Inject
    constructor(
        private val bookmarkDao: BookmarkPicturesDao,
        private val sessionManager: SessionManager,
        private val okHttpJsonApiClient: OkHttpJsonApiClient,
    ) {
        private val compositeDisposable = CompositeDisposable()

        /**
         * Set the media as the device's wallpaper if the imageUrl is not null
         * Fails silently if setting the wallpaper fails
         * @param activity
         * @param media
         */
        fun setWallpaper(
            activity: Activity,
            media: Media,
        ) {
            if (media.imageUrl == null || media.imageUrl!!.isEmpty()) {
                Timber.d("Media URL not present")
                return
            }
            setWallpaperFromImageUrl(activity, media.imageUrl!!.toUri())
        }

        /**
         * Set the media as user's leaderboard avatar
         * @param activity
         * @param media
         */
        fun setAvatar(
            activity: Activity,
            media: Media,
        ) {
            if (media.imageUrl == null || media.imageUrl!!.isEmpty()) {
                Timber.d("Media URL not present")
                return
            }
            setAvatarFromImageUrl(
                activity,
                media.imageUrl!!,
                sessionManager.currentAccount!!.name,
                okHttpJsonApiClient,
                compositeDisposable,
            )
        }

        /**
         * Decide wether or not we should display the background color menu items
         * We display them if the image is transparent
         * @param getBitmap
         * @param menu
         */
        fun handleBackgroundColorMenuItems(
            getBitmap: Callable<Bitmap>,
            menu: Menu,
        ) {
            Observable
                .fromCallable(
                    getBitmap,
                ).subscribeOn(Schedulers.newThread())
                .observeOn(AndroidSchedulers.mainThread())
                .subscribe(
                    Consumer { image: Bitmap ->
                        if (image.hasAlpha()) {
                            menu
                                .findItem(R.id.menu_view_set_white_background)
                                .setVisible(true)
                                .setEnabled(true)
                            menu
                                .findItem(R.id.menu_view_set_black_background)
                                .setVisible(true)
                                .setEnabled(true)
                        }
                    },
                )
        }

        /**
         * Updates the bookmark state and icon for the given menu item.
         *
         * @param item the bookmark menu item to update
         * @param bookmark the current bookmark entity
         * @param currentItem the current pager position
         * @param removedItems list of positions that have been unbookmarked in this session
         */
        fun updateBookmarkState(
            item: MenuItem,
            bookmark: Bookmark?,
            currentItem: Int,
            removedItems: ArrayList<Int>,
        ) {
            val isBookmarked = bookmarkDao.findBookmark(bookmark)
            if (isBookmarked) {
                if (removedItems.contains(currentItem)) {
                    removedItems.remove(currentItem)
                }
            } else {
                if (!removedItems.contains(currentItem)) {
                    removedItems.add(currentItem)
                }
            }

            item.setIcon(
                if (isBookmarked) {
                    R.drawable.menu_ic_round_star_filled_24px
                } else {
                    R.drawable.menu_ic_round_star_border_24px
                },
            )
        }
    }

