class MediaDetailPlayer(
    private val context: Context,
    private val httpClient: OkHttpClient,
    private val onError: () -> Unit,
) {
    var player: ExoPlayer? = null
        private set

    var sources: List<MediaDerivative> = emptyList()
        private set

    var timedTextTracks: List<TimedTextTrack> = emptyList()
        private set

    var selected: MediaDerivative? = null
        private set

    private var resumeSource: MediaDerivative? = null
    private var resumePosition: Long = 0

    fun setSources(
        sources: List<MediaDerivative>,
        timedTextTracks: List<TimedTextTrack>,
    ) {
        this.sources = sources
        this.timedTextTracks = timedTextTracks
    }

    /**
     * Returns the source to play, preferring the one interrupted by an error.
     */
    fun preferredSource(maxResolution: Int): MediaDerivative? =
        preferredMediaPlaybackSource(sources, maxResolution, resumeSource)

    /**
     * Plays the source in the given view, creating the player if needed.
     *
     * The current position is kept when switching between sources.
     */
    fun play(
        source: MediaDerivative,
        playerView: PlayerView,
    ) {
        val previousSource = selected
        val position = player?.currentPosition ?: resumePosition
        selected = source
        resumeSource = null
        resumePosition = 0

        val player = player ?: createPlayer().also { player = it }

        val url = source.src()
        if (previousSource?.src() != url) {
            player.setMediaItem(mediaItem(url))
            player.prepare()
            player.seekTo(position)
        }

        playerView.player = player
        player.play()
    }

    fun resume() {
        player?.play()
    }

    fun pause() {
        player?.pause()
    }

    /**
     * Remembers the selected source and position so playback can resume
     * after the player is released.
     */
    fun saveResumeState() {
        if (selected != null) {
            resumeSource = selected
            resumePosition = player?.currentPosition ?: 0
        }
    }

    /**
     * Releases the player and forgets the sources.
     */
    fun release() {
        player?.release()
        player = null
        sources = emptyList()
        timedTextTracks = emptyList()
        selected = null
    }

    @OptIn(UnstableApi::class)
    private fun createPlayer(): ExoPlayer =
        ExoPlayer
            .Builder(context)
            .setMediaSourceFactory(DefaultMediaSourceFactory(OkHttpDataSource.Factory(httpClient)))
            .setLoadControl(
                DefaultLoadControl
                    .Builder()
                    .setBufferDurationsMs(
                        MIN_BUFFER_MS,
                        MAX_BUFFER_MS,
                        DefaultLoadControl.DEFAULT_BUFFER_FOR_PLAYBACK_MS,
                        DefaultLoadControl.DEFAULT_BUFFER_FOR_PLAYBACK_AFTER_REBUFFER_MS,
                    ).build(),
            ).build()
            .also {
                it.addListener(
                    object : Player.Listener {
                        override fun onPlayerError(error: PlaybackException) {
                            onError()
                        }
                    },
                )
            }

    private fun mediaItem(mediaUrl: String): MediaItem =
        MediaItem
            .Builder()
            .setUri(mediaUrl)
            .setSubtitleConfigurations(
                timedTextTracks.map { timedTextTrack ->
                    MediaItem.SubtitleConfiguration
                        .Builder(timedTextTrack.src().toUri())
                        .setMimeType(MimeTypes.TEXT_VTT)
                        .setLanguage(timedTextTrack.language())
                        .setLabel(timedTextTrack.label())
                        .build()
                },
            ).build()
}

fun play(
    source: MediaDerivative,
    playerView: PlayerView,
) {
    val previousSource = selected
    val position = player?.currentPosition ?: resumePosition
    selected = source
    resumeSource = null
    resumePosition = 0

    val player = player ?: createPlayer().also { player = it }

    val url = source.src()
    if (previousSource?.src() != url) {
        player.setMediaItem(mediaItem(url))
        player.prepare()
        player.seekTo(position)
    }

    playerView.player = player
    player.play()
}

fun saveResumeState() {
    if (selected != null) {
        resumeSource = selected
        resumePosition = player?.currentPosition ?: 0
    }
}

class MediaDetailViewModel(
    private val applicationContext: Context,
    private val okHttpJsonApiClient: OkHttpJsonApiClient,
) : ViewModel() {
    private val _commonsContainerState =
        MutableStateFlow<FileUsagesContainerState>(FileUsagesContainerState.Initial)
    val commonsContainerState = _commonsContainerState.asStateFlow()

    private val _globalContainerState =
        MutableStateFlow<FileUsagesContainerState>(FileUsagesContainerState.Initial)
    val globalContainerState = _globalContainerState.asStateFlow()

    fun loadFileUsagesCommons(fileName: String) {
        viewModelScope.launch {
            _commonsContainerState.update { FileUsagesContainerState.Loading }

            val result =
                runCatching {
                    okHttpJsonApiClient
                        .getFileUsagesOnCommons(fileName, 10)
                        ?.query
                        ?.pages
                        ?.firstOrNull()
                        ?.fileUsage
                        ?.map { it.toUiModel() }
                }

            if (result.isFailure) {
                Timber.e(result.exceptionOrNull(), javaClass.simpleName)
                _commonsContainerState.update {
                    FileUsagesContainerState.Error(
                        errorMessage =
                            applicationContext.getString(
                                R.string.error_while_loading,
                            ),
                    )
                }
                return@launch
            }

            _commonsContainerState.update { FileUsagesContainerState.Success(data = result.getOrNull()) }
        }
    }

    fun loadGlobalFileUsages(fileName: String) {
        viewModelScope.launch {
            _globalContainerState.update { FileUsagesContainerState.Loading }

            val result =
                runCatching {
                    okHttpJsonApiClient
                        .getGlobalFileUsages(fileName, 10)
                        ?.query
                        ?.pages
                        ?.firstOrNull()
                        ?.fileUsage
                        ?.map { it.toUiModel() }
                }

            if (result.isFailure) {
                Timber.e(result.exceptionOrNull(), javaClass.simpleName)
                _globalContainerState.update {
                    FileUsagesContainerState.Error(
                        errorMessage =
                            applicationContext.getString(
                                R.string.error_while_loading,
                            ),
                    )
                }
                return@launch
            }

            _globalContainerState.update { FileUsagesContainerState.Success(data = result.getOrNull()) }
        }
    }

    sealed class FileUsagesContainerState {
        object Initial : FileUsagesContainerState()

        object Loading : FileUsagesContainerState()

        data class Success(
            val data: List<FileUsagesUiModel>?,
        ) : FileUsagesContainerState()

        data class Error(
            val errorMessage: String,
        ) : FileUsagesContainerState()
    }

    class MediaDetailViewModelProviderFactory
        @Inject
        constructor(
            private val okHttpJsonApiClient: OkHttpJsonApiClient,
            private val applicationContext: Context,
        ) : ViewModelProvider.Factory {
            override fun <T : ViewModel> create(modelClass: Class<T>): T {
                if (modelClass.isAssignableFrom(MediaDetailViewModel::class.java)) {
                    @Suppress("UNCHECKED_CAST")
                    return MediaDetailViewModel(applicationContext, okHttpJsonApiClient) as T
                }
                throw IllegalArgumentException("Unknown ViewModel class")
            }
        }
}

