@Composable
fun LogcatReaderTheme(
  darkTheme: Boolean = isSystemInDarkTheme(),
  content: @Composable () -> Unit
) {

  val context = LocalContext.current
  val appThemeSetting by rememberStringSharedPreference(
    key = SettingsPrefKeys.Appearance.KEY_THEME,
    default = SettingsPrefKeys.Appearance.Default.THEME,
  )

  val dynamicColor by rememberBooleanSharedPreference(
    key = SettingsPrefKeys.Appearance.KEY_DYNAMIC_COLOR,
    default = SettingsPrefKeys.Appearance.Default.DYNAMIC_COLOR
  )

  val colorScheme = when (appThemeSetting) {
    Theme.AUTO -> {
      when {
        dynamicColor && isDynamicThemeAvailable() -> {
          val context = LocalContext.current
          if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context)
        }
        darkTheme -> darkScheme
        else -> lightScheme
      }
    }
    Theme.DARK -> if (dynamicColor && isDynamicThemeAvailable()) {
      dynamicDarkColorScheme(context)
    } else {
      darkScheme
    }
    else -> if (dynamicColor && isDynamicThemeAvailable()) {
      dynamicLightColorScheme(context)
    } else {
      lightScheme
    }
  }

  val view = LocalView.current
  val window = LocalActivity.current?.window
  if (window != null) {
    LaunchedEffect(view, window, appThemeSetting, darkTheme, dynamicColor) {
      val isLight = when (appThemeSetting) {
        Theme.LIGHT -> true
        Theme.DARK -> false
        else -> !darkTheme
      }
      WindowInsetsControllerCompat(window, view).run {
        isAppearanceLightStatusBars = if (dynamicColor) {
          isLight
        } else {
          // Dark status bar colors work nicer with non-dynamic app theme (even in light mode).
          false
        }
        isAppearanceLightNavigationBars = isLight
      }
    }
  }

  MaterialTheme(
    colorScheme = colorScheme,
    shapes = Shapes,
    typography = AppTypography,
    content = content,
  )
}

