@JvmStatic
fun startActivity(context:Context, intent:Intent, callback:((resultCode:Int, data:Intent?) -> Unit)?) {
    startActivity(context, intent, callback, null)
}

@JvmStatic
fun startActivity(context:Context, intent:Intent, callback:((resultCode:Int, data:Intent?) -> Unit)?, options: Bundle?) {
    val current = System.currentTimeMillis()
    val last = lastTime
    lastTime = current
    // 防暴击：两次启动间隔必须大于1秒。
    if (current - last < 1000) {
        return
    }

    if (context !is Activity || callback == null) {
        context.startActivity(intent)
    } else {
        // 自动生成有效的requestCode进行使用。
        val requestCode = codeGenerator.nextInt(0x0000FFFF)
        if (options == null || Build.VERSION.SDK_INT < 16) {
            context.startActivityForResult(intent, requestCode)
        } else {
            context.startActivityForResult(intent, requestCode, options)
        }

        // 保存回调缓存
        if (container.containsKey(context)) {
            container[context]?.put(requestCode, callback)
        } else {
            container[context] = mutableMapOf(Pair(requestCode, callback))
        }
    }
}

fun put(key:String, value:Any?):EasyBundle {
    if (TextUtils.isEmpty(key) || value == null) {
        return this
    }

    var store = true
    // 根据value的类型，选择合适的api进行存储
    @Suppress("UNCHECKED_CAST")
    when (value) {
        is Int -> bundle.putInt(key, value)
        is Long -> bundle.putLong(key, value)
        is CharSequence -> bundle.putCharSequence(key, value)
        is String -> bundle.putString(key, value)
        is Float -> bundle.putFloat(key, value)
        is Double -> bundle.putDouble(key, value)
        is Char -> bundle.putChar(key, value)
        is Short -> bundle.putShort(key, value)
        is Boolean -> bundle.putBoolean(key, value)
        is Parcelable -> bundle.putParcelable(key, value)
        is SparseArray<*> -> bundle.putSparseParcelableArray(key, value as SparseArray<out Parcelable>)
        is Array<*> -> when {
            value.isArrayOf<CharSequence>() -> bundle.putCharSequenceArray(key, value as Array<out CharSequence>)
            value.isArrayOf<String>() -> bundle.putStringArray(key, value as Array<out String>?)
            value.isArrayOf<Parcelable>() -> bundle.putParcelableArray(key, value as Array<out Parcelable>?)
            else -> store = false
        }
        is Size -> bundle.putSize(key, value)
        is SizeF -> bundle.putSizeF(key, value)
        is IntArray -> bundle.putIntArray(key, value)
        is LongArray -> bundle.putLongArray(key, value)
        is FloatArray -> bundle.putFloatArray(key, value)
        is DoubleArray -> bundle.putDoubleArray(key, value)
        is CharArray -> bundle.putCharArray(key, value)
        is ShortArray -> bundle.putShortArray(key, value)
        is BooleanArray -> bundle.putBooleanArray(key, value)
        is IBinder -> bundle.putBinder(key, value)
        is Serializable -> when (value) {
            is Collection<*>, is Map<*, *> -> store = false
            else -> bundle.putSerializable(key, value)
        }
        else -> store = false
    }

    if (store.not()) {
        bundle.putString(key, toJSON(value))
    }

    return this
}

