class EasyToast private constructor(private val builder:Builder) {

    private val context: Context = EasyAndroid.getApplicationContext()
    private var toast:Toast? = null
    private var tv:TextView? = null
    private var container:View? = null

    fun show(resId:Int) {
        show(context.getString(resId))
    }

    fun show(message:String?, vararg any: Any) {
        if (TextUtils.isEmpty(message)) {
            return
        }

        var result = message as String
        if (any.isNotEmpty()) {
            result = String.format(message, any)
        }

        if (Looper.myLooper() == Looper.getMainLooper()) {
            showInternal(result)
        } else {
            mainHandler.post { showInternal(result) }
        }
    }

    /** 获取Toast的View进行使用，只支持自定义样式的Toast，若为系统默认Toast样式，则返回null*/
    fun getView():View? {
        if (container == null && builder.isDefault.not()) {
            createToastIfNeeded()
        }
        return container
    }

    private fun showInternal(message: String) {
        createToastIfNeeded()

        if (builder.isDefault) {
            toast?.setText(message)
            toast?.show()
        } else {
            tv?.text = message
            toast?.show()
        }
    }

    @SuppressLint("ShowToast")
    private fun createToastIfNeeded() {
        if (toast == null) {
            if (builder.isDefault) {
                toast = Toast.makeText(context, "", builder.duration)
            } else {
                container = builder.layout?:LayoutInflater.from(context).inflate(builder.layoutId, null)
                tv = container?.findViewById(builder.tvId)
                toast = Toast(context)
                toast?.view = container
                toast?.duration = builder.duration
            }

            if (builder.gravity != 0) {
                toast?.setGravity(builder.gravity, builder.offsetX, builder.offsetY)
            }
        }
    }

    companion object {

        private val mainHandler = Handler(Looper.getMainLooper())
        /**
         * 默认提供的Toast实例，在首次使用时进行加载。
         */
        @JvmStatic
        val DEFAULT: EasyToast by lazy { return@lazy newBuilder().build() }

        @JvmStatic
        fun newBuilder():Builder {
            return Builder(isDefault = true)
        }
        @JvmStatic
        fun newBuilder(layoutId: Int, tvId: Int):Builder {
            return Builder(isDefault = false, layoutId = layoutId, tvId = tvId)
        }
        @JvmStatic
        fun newBuilder(layout:View, tvId: Int):Builder {
            assert(layout.parent == null)
            return Builder(isDefault = false, layout = layout, tvId = tvId)
        }
    }

    class Builder internal constructor(internal var isDefault: Boolean,
                           internal var layout:View? = null,
                           internal var layoutId: Int = 0,
                           internal var tvId: Int = 0) {

        internal var duration:Int = Toast.LENGTH_SHORT
        internal var gravity:Int = 0
        internal var offsetX:Int = 0
        internal var offsetY:Int = 0

        fun setGravity(gravity: Int, offsetX: Int, offsetY: Int): Builder {
            this.gravity = gravity
            this.offsetX = offsetX
            this.offsetY = offsetY
            return this
        }

        fun setDuration(duration:Int): Builder {
            this.duration = duration
            return this
        }

        fun build():EasyToast {
            return EasyToast(this)
        }
    }
}

class MVPDispatcher{

    private val presenters:MutableList<MVPPresenter<*>> = mutableListOf()

    // ==== 添加与移除Presenter ========
    /**
     * 添加新的Presenter到容器中。只允许添加已绑定过View后的。否则将毫无意义！
     */
    fun <V:MVPView> addPresenter(presenter:MVPPresenter<V>) {
        if (presenter.isViewAttached() && !presenters.contains(presenter)) {
            presenters.add(presenter)
        }
    }

    /**
     * 移除制定的Presenter实例。并将其与View解绑。
     */
    fun <V:MVPView> removePresenter(presenter:MVPPresenter<V>) {
        if (presenters.contains(presenter)) {
            presenters.remove(presenter)
            if (presenter.isViewAttached()) {
                presenter.detach()
            }
        }
    }

    fun dispatchOnCreate(bundle:Bundle?) {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onCreate(bundle)
            }
        }
    }

    fun dispatchOnStart() {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onStart()
            }
        }
    }

    fun dispatchOnResume() {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onResume()
            }
        }
    }

    fun dispatchOnPause() {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onPause()
            }
        }
    }

    fun dispatchOnStop() {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onStop()
            }
        }
    }

    fun dispatchOnRestart() {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onRestart()
            }
        }
    }

    fun dispatchOnDestroy() {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onDestroy()
            }
            removePresenter(it)
        }
    }

    fun dispatchOnActivityResult(requestCode:Int, resultCode:Int, data: Intent?) {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onActivityResult(requestCode, resultCode, data)
            }
        }
    }

    fun dispatchOnSaveInstanceState(outState: Bundle?) {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onSaveInstanceState(outState)
            }
        }
    }

    fun dispatchOnRestoreInstanceState(savedInstanceState: Bundle?) {
        presenters.forEach {
            if (it.isViewAttached()) {
                it.onRestoreInstanceState(savedInstanceState)
            }
        }
    }
}

/**
 * 添加新的Presenter到容器中。只允许添加已绑定过View后的。否则将毫无意义！
 */
fun <V:MVPView> addPresenter(presenter:MVPPresenter<V>) {
    if (presenter.isViewAttached() && !presenters.contains(presenter)) {
        presenters.add(presenter)
    }
}

object SafeDialogHandle {

    private val mainHandler = Handler(Looper.getMainLooper())

    fun safeShowDialog(dialog: Dialog?) {
        if (Looper.myLooper() == Looper.getMainLooper()) {
            safeShowDialogOnMainThread(dialog)
            return
        }

        mainHandler.post { safeShowDialogOnMainThread(dialog) }
    }

    private fun safeShowDialogOnMainThread(dialog: Dialog?) {
        if (dialog == null || dialog.isShowing) {
            return
        }
        val bindAct = getActivity(dialog)

        if (bindAct == null || bindAct.isFinishing) {
            Log.d("Dialog shown failed:", "The Dialog bind's Activity was recycled or finished!")
            return
        }

        dialog.show()
    }

    private fun getActivity(dialog: Dialog): Activity? {
        var bindAct: Activity? = null
        var context = dialog.context
        do {
            if (context is Activity) {
                bindAct = context
                break
            } else if (context is ContextThemeWrapper) {
                context = context.baseContext
            } else {
                break
            }
        } while (true)
        return bindAct
    }

    fun safeDismissDialog(dialog: Dialog?) {
        if (Looper.myLooper() == Looper.getMainLooper()) {
            safeDismissDialogOnMainThread(dialog)
            return
        }

        mainHandler.post { safeDismissDialogOnMainThread(dialog) }
    }

    private fun safeDismissDialogOnMainThread(dialog: Dialog?) {
        if (dialog == null || !dialog.isShowing) {
            return
        }

        val bindAct = getActivity(dialog)
        if (bindAct != null && !bindAct.isFinishing) {
            dialog.dismiss()
        }
    }
}

