internal fun checkRCMaxValue(maxValue: Double, data: List<Bars>) {
    require(maxValue >= (data.maxOfOrNull { it.values.maxOfOrNull { it.value } ?: 0.0 } ?: 0.0)) {
        "Chart data must be at most $maxValue (Specified Max Value)"
    }
}

internal fun calculateValue(minValue: Double, maxValue: Double, total: Float, offset:Float): Double {
    val percentage = offset / total
    val range = maxValue - minValue
    val value = minValue + percentage * range
    return value
}

@Composable
internal fun ImplementRCAnimation(
    data:List<Bars>,
    animationMode: AnimationMode,
    spec: (Bars.Data)->AnimationSpec<Float>,
    delay:Long,
    before:()->Unit
) {
    LaunchedEffect(data) {
        before()
        delay(delay)
        data.flatMap { it.values }.filter { it.value != 0.0 }.forEachIndexed { index, data ->
            val animate: suspend () -> Unit = {
                data.animator.animateTo(
                    1f,
                    animationSpec = spec(data)
                )
            }
            when (animationMode) {
                is AnimationMode.OneByOne -> {
                    animate()
                }

                is AnimationMode.Together -> {
                    launch {
                        delay(animationMode.delayBuilder(index))
                        animate()
                    }
                }

                is AnimationMode.None -> {
                    data.animator.snapTo(1f)
                }
            }
        }
    }
}

