class DuckDetectorModuleBoundariesPlugin : Plugin<Project> {
    override fun apply(target: Project) {
        val policyText = target.providers
            .fileContents(target.rootProject.layout.projectDirectory.file(ModuleBoundaryPolicy.RELATIVE_PATH))
            .asText
        if (target == target.rootProject) {
            val policy = loadPolicy(policyText)
            val modules = target.subprojects.filter { it.buildFile.exists() }.map { it.path }.toSet()
            report(target, ModuleBoundaryValidator.validatePolicy(policy) +
                ModuleBoundaryValidator.validateMembership(policy, modules))
            return
        }
        target.afterEvaluate {
            val policy = loadPolicy(policyText)
            report(this, ModuleBoundaryValidator.validateProject(policy, collectFacts()))
        }
    }

    private fun loadPolicy(policyText: Provider<String>): ModuleBoundaryPolicy {
        val text = policyText.orNull
            ?: throw GradleException("Module boundary policy is missing: ${ModuleBoundaryPolicy.RELATIVE_PATH}")
        return try {
            ModuleBoundaryPolicy.parse(text)
        } catch (error: ModuleBoundaryPolicyException) {
            throw GradleException("Module boundary policy is malformed: ${error.message}", error)
        }
    }

    private fun report(project: Project, errors: List<String>) {
        if (errors.isEmpty()) {
            return
        }
        throw GradleException(
            buildString {
                appendLine("Module boundary violations in ${project.path} (${ModuleBoundaryPolicy.RELATIVE_PATH}):")
                errors.forEach { appendLine("  - $it") }
            },
        )
    }

    private fun Project.collectFacts(): ProjectFacts {
        val kind = when {
            pluginManager.hasPlugin("com.android.application") -> ModuleKind.ANDROID_APPLICATION
            pluginManager.hasPlugin("com.android.library") -> ModuleKind.ANDROID_LIBRARY
            pluginManager.hasPlugin("com.android.fused-library") -> ModuleKind.ANDROID_FUSED_LIBRARY
            pluginManager.hasPlugin("org.jetbrains.kotlin.jvm") -> ModuleKind.JVM
            else -> null
        }
        val projectDependencies = sortedMapOf<String, MutableSet<String>>()
        val externalDependencies = sortedMapOf<String, MutableSet<String>>()
        // External artifacts only matter where they reach the module's own code; tool classpaths such
        // as androidLintTool legitimately carry Android artifacts into pure JVM modules.
        val codeConfigurations = CODE_CLASSPATHS
            .mapNotNull { configurations.findByName(it) }
            .flatMap { it.hierarchy }
            .mapTo(mutableSetOf()) { it.name }
        configurations.forEach { configuration ->
            configuration.dependencies.forEach { dependency ->
                when (dependency) {
                    // AGP wires test variants to the tested variant through a dependency on the
                    // same project; that is not an edge between modules.
                    is ProjectDependency -> if (dependency.path != path) {
                        projectDependencies.getOrPut(configuration.name, ::sortedSetOf) += dependency.path
                    }

                    is ExternalModuleDependency -> if (configuration.name in codeConfigurations) {
                        externalDependencies.getOrPut(configuration.name, ::sortedSetOf) +=
                            "${dependency.group}:${dependency.name}"
                    }
                }
            }
        }
        return ProjectFacts(
            path = path,
            appliedKind = kind,
            appliesCompose = pluginManager.hasPlugin(COMPOSE_COMPILER_PLUGIN),
            projectDependencies = projectDependencies,
            externalDependencies = externalDependencies,
        )
    }

    private companion object {
        const val COMPOSE_COMPILER_PLUGIN = "org.jetbrains.kotlin.plugin.compose"

        val CODE_CLASSPATHS = listOf(
            "compileClasspath",
            "runtimeClasspath",
            "testCompileClasspath",
            "testRuntimeClasspath",
        )
    }
}

is ProjectDependency -> if (dependency.path != path) {
    projectDependencies.getOrPut(configuration.name, ::sortedSetOf) += dependency.path
}

fun classify(path: String): ModuleRule? {
    members[path]?.let { member -> return ModuleRule(path, member.kind, member.ui, layer = null) }
    val modulePath = ModulePath(path)
    val layers = groupLayers[modulePath.group] ?: return null
    if (modulePath.depth != LAYERED_DEPTH) {
        return null
    }
    val rule = layers[modulePath.layer] ?: return null
    return ModuleRule(path, rule.kind, rule.ui, layer = rule)
}

private fun allowanceErrors(
    policy: ModuleBoundaryPolicy,
    source: ModuleRule,
    target: ModuleRule,
    configuration: String,
): List<String> {
    val layer = source.layer
    if (layer == null) {
        val allowed = policy.members.getValue(source.path).allowedProjectDependencies
        return if (allowed.any { globToRegex(it).matches(target.path) }) {
            emptyList()
        } else {
            listOf(
                "${source.path} depends on ${target.path} through '$configuration', " +
                    "which the boundary policy does not allow",
            )
        }
    }
    val from = ModulePath(source.path)
    val to = ModulePath(target.path)
    if (from.group == to.group && from.unit == to.unit) {
        return if (to.layer in layer.mayDependOn) {
            emptyList()
        } else {
            listOf(
                "${source.path} may not depend on ${target.path}: '${from.layer}' layers may only " +
                    "depend on ${layer.mayDependOn.sorted()} of their own unit",
            )
        }
    }
    if (from.group == to.group) {
        // Direction and isolation report edges between units of the same group.
        return emptyList()
    }
    return if (layer.mayUse.any { globToRegex(it).matches(target.path) }) {
        emptyList()
    } else {
        listOf(
            "${source.path} may not depend on ${target.path}: '${from.layer}' layers of ${from.group} " +
                "may only use ${layer.mayUse.sorted()} outside their unit",
        )
    }
}

private fun edgeErrors(
    policy: ModuleBoundaryPolicy,
    source: ModuleRule,
    target: ModuleRule,
    directionIndex: Map<String, Int>,
): List<String> {
    val errors = mutableListOf<String>()
    if (target.path == policy.compositionRoot) {
        errors += "${source.path} may not depend on the composition root ${target.path}"
        return errors
    }
    val from = ModulePath(source.path)
    val to = ModulePath(target.path)
    val sourceIndex = if (source.path == policy.compositionRoot) -1 else directionIndex[from.group]
    val destinationIndex = directionIndex[to.group]
    if (sourceIndex != null && destinationIndex != null && destinationIndex < sourceIndex) {
        errors += "${source.path} may not depend on ${target.path}: dependencies point from " +
            policy.dependencyDirection.joinToString(" to ")
    }
    if (from.group == to.group && from.group in policy.isolatedGroups && from.unit != to.unit) {
        errors += "${source.path} may not depend on ${target.path}: units of ${from.group} are isolated from each other"
    }
    if (source.kind == ModuleKind.JVM && target.kind != ModuleKind.JVM) {
        errors += "${source.path} is a pure JVM module and may not depend on ${target.kind.id} ${target.path}"
    }
    if (!source.ui && target.ui) {
        errors += "${source.path} is not a UI module and may not depend on the UI module ${target.path}"
    }
    return errors
}

private suspend fun <T : Any> performRemoteCall(
    context: Context,
    onConnected: (HelperProbeProxy) -> T,
    onNullBinder: () -> T,
    onError: (String) -> T,
): T {
    repeat(BIND_ATTEMPTS) {
        bindOnce(context, onConnected, onNullBinder, onError)?.let { result -> return result }
    }
    return onError("The system stopped the helper service before it connected, on both attempts.")
}

private suspend fun <T : Any> bindOnce(
    context: Context,
    onConnected: (HelperProbeProxy) -> T,
    onNullBinder: () -> T,
    onError: (String) -> T,
): T? = suspendCancellableCoroutine { continuation ->
    val bindAttemptFinished = AtomicBoolean(false)
    val cleanupRequested = AtomicBoolean(false)
    val unbindAttempted = AtomicBoolean(false)
    val completionAttempted = AtomicBoolean(false)
    val connected = AtomicBoolean(false)
    lateinit var connection: ServiceConnection

    fun requestCleanup() {
        cleanupRequested.set(true)
        if (bindAttemptFinished.get() && unbindAttempted.compareAndSet(false, true)) {
            runCatching { context.unbindService(connection) }
        }
    }

    fun finish(result: T?) {
        requestCleanup()
        if (completionAttempted.compareAndSet(false, true)) {
            continuation.resume(result)
        }
    }

    connection = object : ServiceConnection {
        override fun onServiceConnected(
            name: ComponentName?,
            service: IBinder?,
        ) {
            connected.set(true)
            if (service == null) {
                finish(onNullBinder())
                return
            }
            try {
                val proxy = HelperProbeProxy(service)
                finish(onConnected(proxy))
            } catch (throwable: Throwable) {
                finish(onError(throwable.message ?: "Binder call failed."))
            }
        }

        override fun onNullBinding(name: ComponentName?) {
            finish(onNullBinder())
        }

        override fun onBindingDied(name: ComponentName?) {
            finish(
                if (connected.get()) {
                    onError("The helper service binding died before it answered.")
                } else {
                    null
                },
            )
        }

        override fun onServiceDisconnected(name: ComponentName?) = Unit
    }

    continuation.invokeOnCancellation {
        requestCleanup()
    }
    if (!continuation.isActive) {
        return@suspendCancellableCoroutine
    }

    val intent = Intent(context, serviceClass)
    // AUTO_CREATE keeps the helper alive for this snapshot; finish/cancellation unbind it so
    // a failed Binder call cannot leave an isolated process retained.
    // onServiceConnected below makes a blocking Binder call, so it must not run on the
    // main thread's executor - that previously froze the UI (and could trigger an ANR)
    // for as long as the remote process took to answer.
    val bound = runCatching {
        if (expectedProfile == HelperProcessProfile.ISOLATED &&
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.O
        ) {
            context.bindIsolatedService(
                intent,
                Context.BIND_AUTO_CREATE,
                ISOLATED_INSTANCE_NAME,
                REMOTE_CALLBACK_EXECUTOR,
                connection,
            )
        } else {
            context.bindService(intent, Context.BIND_AUTO_CREATE, REMOTE_CALLBACK_EXECUTOR, connection)
        }
    }.getOrDefault(false)

    // ActivityManager may publish an already-running service before bindService() returns.
    // The executor callback can therefore request cleanup before the bind attempt finishes.
    bindAttemptFinished.set(true)
    if (cleanupRequested.get()) {
        requestCleanup()
    }

    if (!bound) {
        finish(onError("The dedicated virtualization probe process could not be bound."))
        return@suspendCancellableCoroutine
    }
}

bindAttemptFinished.set(true)
if (cleanupRequested.get()) {
    requestCleanup()
}

val allowed = profile != HelperProcessProfile.ISOLATED || Process.isIsolated()
return if (!allowed) {
    null
}

