public object InstalledPackageVisibilityPolicy {

    public fun evaluate(
        environment: PackageVisibilityEnvironment,
        callerPackageObserved: Boolean,
    ): InstalledPackageVisibility {
        // A successful PackageManager inventory must include the caller. Missing it means the
        // observed response no longer satisfies the platform baseline, so absence claims are not
        // defensible even if the manifest requests broad visibility.
        if (!callerPackageObserved) {
            return InstalledPackageVisibility.UNKNOWN
        }
        if (environment.deviceSdk < ANDROID_11_API_LEVEL ||
            environment.targetSdk < ANDROID_11_API_LEVEL
        ) {
            return InstalledPackageVisibility.FULL
        }
        return if (environment.queryAllPackagesRequested) {
            InstalledPackageVisibility.FULL
        } else {
            InstalledPackageVisibility.RESTRICTED
        }
    }
}

internal class ScanSharedCollection<T : Any> {
    private val mutex = Mutex()
    private var latest: Collected<T>? = null

    suspend fun collect(scan: ScanEpoch, collect: suspend () -> T): T = mutex.withLock {
        latest?.takeIf { it.scanId == scan.id }?.let { return@withLock it.value }
        val value = collect()
        latest = Collected(scan.id, value)
        value
    }

    private class Collected<T>(val scanId: Long, val value: T)
}

internal data class SelinuxAppZygoteGenerationKey(
    val preloadPid: Int,
    val appUid: Int,
    val startedNanos: Long,
    val apkPath: String,
    val splitPaths: List<String>,
    val versionCode: Long,
    val payloadSchemaVersion: Int,
    val buildRevision: String,
) {
    fun storageKey(): String {
        val fields = listOf(
            preloadPid.toString(),
            appUid.toString(),
            startedNanos.toString(),
            apkPath,
            splitPaths.size.toString(),
            *splitPaths.toTypedArray(),
            versionCode.toString(),
            payloadSchemaVersion.toString(),
            buildRevision,
        )
        val canonical = buildString {
            fields.forEach { append(it.length).append(':').append(it) }
        }
        val digest = MessageDigest.getInstance("SHA-256").digest(canonical.toByteArray(Charsets.UTF_8))
        val hex = "0123456789abcdef"
        return buildString(digest.size * 2) {
            digest.forEach { byte ->
                val value = byte.toInt() and 0xff
                append(hex[value ushr 4])
                append(hex[value and 0x0f])
            }
        }
    }
}

internal interface SelinuxAppZygoteGenerationStore {
    fun check(key: SelinuxAppZygoteGenerationKey): GenerationFenceCheck
    fun commitAccepted(key: SelinuxAppZygoteGenerationKey): Boolean
}

private fun SelinuxAvcLookupSnapshot.consistent(): Boolean {
    // Legacy 128-pair preload payloads stay readable but are never timing-positive.
    val cleanChild = childEnd == SelinuxAvcLookupChildEnd.EXITED && childExitStatus == 0 && childSignal == 0 &&
        unexpectedPayload == SelinuxAvcLookupPayload.NONE && !identityChanged && pairs in setOf(128, PAIRS) &&
        aSlower <= pairs && positiveBlocks + negativeBlocks + zeroBlocks <= pairs / 32
    return when (state) {
        SelinuxAvcLookupState.COLLECTED -> cleanChild && step == SelinuxAvcLookupStep.FINISHED && errno == 0 &&
            rounds == ROUNDS && writesPerBatch == WRITES_PER_BATCH &&
            batchesA.size == ROUNDS && batchesB.size == ROUNDS &&
            cpu >= 0 && cpuRow in 0 until cpuRows && cpuRows == possibleCpus
        SelinuxAvcLookupState.TIMING_ONLY -> cleanChild && step in COUNTING_STEPS && errno > 0
        else -> true
    }
}

internal class SelinuxAvcLookupProbe(
    private val collector: NativeSnapshotCollector = NativeSnapshotCollector.Default,
) {
    fun inspect(trace: (String) -> Unit = {}): SelinuxAvcLookupSnapshot {
        // JNI forks a lightweight safety-check child before touching the live carrier.
        // Running 33k AVC writes first perturbs the scheduler and invalidates PoC parity.
        trace("AVC lightweight parent timing preflight begin")
        val earlyParent = collector.collect(
            readPayload = ::nativeCollectParentTiming,
            parse = { it },
            unavailable = { "" },
        )
        trace("AVC disposable child begin")
        val child = collector.collect(
            readPayload = ::nativeCollectAvcLookup,
            parse = SelinuxAvcLookupPayloadCodec::decode,
            unavailable = { failure ->
                SelinuxAvcLookupSnapshot(
                    state = SelinuxAvcLookupState.UNAVAILABLE,
                    failureReason = failure.explain("App zygote AVC lookup experiment was unavailable"),
                )
            },
        )
        trace("AVC child returned state=${child.state} step=${child.step} errno=${child.errno} " +
            "end=${child.childEnd} exit=${child.childExitStatus} signal=${child.childSignal} " +
            "pid=${child.pid} cpu=${child.cpu} pairs=${child.pairs} migrations=${child.cpuMigrations} " +
            "medians=${child.timingMediansAvailable}")
        val result = withParentTiming(child, earlyParent)
        trace("AVC preload parent returned attempted=${result.parentTiming.attempted} " +
            "complete=${result.parentTiming.complete} errno=${result.parentTiming.error}")
        return result
    }

    internal fun withParentTiming(
        child: SelinuxAvcLookupSnapshot,
        parentPayload: String,
    ): SelinuxAvcLookupSnapshot {
        // This only attaches an existing payload; it never replays parent syscalls
        // after a failed child or loses a completed parent sample to optional counters.
        return child.copy(parentTiming = SelinuxAvcLookupPayloadCodec.decodeParent(parentPayload))
    }

    private external fun nativeCollectAvcLookup(): String
    private external fun nativeCollectParentTiming(): String
}

public enum class SelinuxAvcLookupState {
    NOT_COLLECTED, COLLECTED, TIMING_ONLY, PERMISSION_LIMITED, UNSUPPORTED, UNAVAILABLE, INCONCLUSIVE,
}

public enum class SelinuxAvcLookupPayload {
    NONE, A, B,
}

internal object SelinuxCarrierCodeIdentity {
    fun provenanceFailureReason(
        raw: String,
        codeAtBind: SelinuxCarrierExpectedCode?,
        codeAtReply: SelinuxCarrierExpectedCode?,
        nowNanos: Long,
    ): String? {
        val parsed = SelinuxContextValidityBridge().parse(raw)
        if (codeAtBind == null || codeAtReply == null) return "SELinux carrier APK identity unavailable."
        if (codeAtBind != codeAtReply) return "SELinux carrier APK changed during collection."
        val origin = SelinuxCarrierProvenanceCodec.read(raw)
        if (origin == null) return parsed.failureReason ?: "App Zygote preload provenance unavailable."
        return SelinuxCarrierProvenanceCodec.mismatch(origin, codeAtReply, nowNanos)
    }

    fun readExpectedCode(
        context: Context,
        serviceClass: Class<out Service>,
    ): SelinuxCarrierExpectedCode? = runCatching {
        val component = ComponentName(context, serviceClass)
        val info = context.packageManager.getServiceInfo(component, 0).applicationInfo
        val packageInfo = context.packageManager.getPackageInfo(context.packageName, 0)
        val appInfoWithMetadata = context.packageManager.getApplicationInfo(
            context.packageName,
            PackageManager.GET_META_DATA,
        )
        val metadata = appInfoWithMetadata.metaData
        val declaredVersion = metadata?.get(SelinuxCarrierBuildMetadata.VERSION_CODE_META_DATA)
            ?.toString()?.toLongOrNull() ?: 0L
        // SDK hosts do not necessarily embed Duck's manifest metadata. Only claim a version
        // match when the host explicitly supplies one, and verify that it agrees with PM.
        require(declaredVersion <= 0L || declaredVersion == packageInfo.longVersionCode) {
            "Manifest preload version does not match installed package version."
        }
        val buildRevision = metadata?.get(SelinuxCarrierBuildMetadata.BUILD_HASH_META_DATA)
            ?.toString()?.takeIf { it.isNotBlank() }
            ?: SelinuxCarrierBuildMetadata.UNKNOWN_BUILD_REVISION
        SelinuxCarrierExpectedCode(
            appUid = info.uid,
            apkPath = info.sourceDir.orEmpty(),
            splitPaths = info.splitSourceDirs?.toList().orEmpty(),
            versionCode = declaredVersion,
            payloadSchemaVersion = SelinuxCarrierBuildMetadata.CURRENT_PAYLOAD_SCHEMA_VERSION,
            buildRevision = buildRevision,
        )
    }.getOrNull()
}

require(declaredVersion <= 0L || declaredVersion == packageInfo.longVersionCode) {
    "Manifest preload version does not match installed package version."
}

public object SelinuxCarrierBuildMetadata {
    public const val VERSION_CODE_META_DATA: String = "com.eltavine.duckdetector.PRELOAD_VERSION_CODE"
    public const val BUILD_HASH_META_DATA: String = "com.eltavine.duckdetector.PRELOAD_BUILD_HASH"
    public const val UNKNOWN_BUILD_REVISION: String = "unknown"
    public const val CURRENT_PAYLOAD_SCHEMA_VERSION: Int = 1
}

internal object SelinuxContextValidityAugmentation {

    private const val POLICYLOAD_SEQNO_PRELOAD_NOTE =
        "zygotePreloadName is required: the policyload/access seqno oracle must run before the isolated child loses app_zygote SELinuxfs access."

    internal fun mergeCarrierSelfCheckSnapshot(
        nativeSnapshot: SelinuxContextValiditySnapshot,
        javaCarrierSnapshot: SelinuxContextValiditySnapshot,
    ): SelinuxContextValiditySnapshot {
        return nativeSnapshot.copy(
            available = nativeSnapshot.available || javaCarrierSnapshot.available,
            probeAttempted = nativeSnapshot.probeAttempted || javaCarrierSnapshot.available,
            carrierContext = javaCarrierSnapshot.carrierContext ?: nativeSnapshot.carrierContext,
            carrierMatchesExpected = if (javaCarrierSnapshot.carrierContext != null) {
                javaCarrierSnapshot.carrierMatchesExpected
            } else {
                nativeSnapshot.carrierMatchesExpected
            },
            selinuxEnabled = javaCarrierSnapshot.selinuxEnabled ?: nativeSnapshot.selinuxEnabled,
            selinuxEnforced = javaCarrierSnapshot.selinuxEnforced ?: nativeSnapshot.selinuxEnforced,
            pidContextMatchesCurrent = javaCarrierSnapshot.pidContextMatchesCurrent
                ?: nativeSnapshot.pidContextMatchesCurrent,
            procSelfContextMatchesCurrent = javaCarrierSnapshot.procSelfContextMatchesCurrent
                ?: nativeSnapshot.procSelfContextMatchesCurrent,
            dyntransitionCheckPassed = javaCarrierSnapshot.dyntransitionCheckPassed
                ?: nativeSnapshot.dyntransitionCheckPassed,
            failureReason = nativeSnapshot.failureReason ?: javaCarrierSnapshot.failureReason,
        )
    }

    internal fun augmentPreloadSnapshot(
        baseSnapshot: SelinuxContextValiditySnapshot,
        currentUid: Int,
        appUid: Int,
        isUserBuild: Boolean,
        accessCheckBlockReason: String?,
        inspectProcAttrCurrent: () -> List<SelinuxProcAttrCurrentResult>,
        inspectAvcLookup: () -> SelinuxAvcLookupSnapshot = { SelinuxAvcLookupSnapshot() },
        inspectPolicyloadSeqno: () -> SelinuxPolicyloadSeqnoResult,
        checkAccess: (String, String, String, String) -> Boolean?,
    ): SelinuxContextValiditySnapshot {
        val carrierGateFailureReason = SelinuxContextValidityCarrierService.procAttrCurrentGateFailureReason(
            snapshot = baseSnapshot,
            appUid = appUid,
            uid = currentUid,
        )
        val snapshotWithProcAttr = if (carrierGateFailureReason == null) {
            baseSnapshot.copy(
                procAttrCurrentProbeAttempted = true,
                procAttrCurrentResults = inspectProcAttrCurrent(),
                procAttrCurrentFailureReason = null,
            )
        } else {
            baseSnapshot.copy(
                procAttrCurrentProbeAttempted = false,
                procAttrCurrentResults = emptyList(),
                procAttrCurrentFailureReason = carrierGateFailureReason,
            )
        }

        val snapshotWithAvc = snapshotWithProcAttr.copy(
            avcLookup = carrierGateFailureReason?.let {
                SelinuxAvcLookupSnapshot(state = SelinuxAvcLookupState.UNSUPPORTED, failureReason = it)
            } ?: inspectAvcLookup(),
        )
        val snapshotWithPolicyloadSeqno = snapshotWithAvc.applyPolicyloadSeqnoResult(
            failureReason = carrierGateFailureReason,
            inspectPolicyloadSeqno = inspectPolicyloadSeqno,
        )

        // The first android.os.SELinux.checkSELinuxAccess makes libselinux map and read the status page.
        accessCheckBlockReason?.let { reason ->
            return snapshotWithPolicyloadSeqno.copy(
                javaDirtyPolicyAvailable = false,
                javaDirtyPolicyProbeAttempted = false,
                javaDirtyPolicyCarrierContext = snapshotWithPolicyloadSeqno.carrierContext,
                javaDirtyPolicyCarrierMatchesExpected = snapshotWithPolicyloadSeqno.carrierMatchesExpected,
                javaDirtyPolicyQueryMethod = DIRTY_POLICY_QUERY_METHOD,
                javaDirtyPolicyFailureReason = reason,
            )
        }
        return snapshotWithPolicyloadSeqno.applyJavaDirtyPolicyResults(
            isUserBuild = isUserBuild,
            checkAccess = checkAccess,
        )
    }

    private fun SelinuxContextValiditySnapshot.applyPolicyloadSeqnoResult(
        failureReason: String?,
        inspectPolicyloadSeqno: () -> SelinuxPolicyloadSeqnoResult,
    ): SelinuxContextValiditySnapshot {
        if (failureReason != null) {
            return copy(
                policyloadSeqnoAvailable = false,
                policyloadSeqnoProbeAttempted = false,
                policyloadSeqnoState = SelinuxPolicyloadSeqnoState.UNAVAILABLE.name,
                policyloadSeqnoCarrierContext = carrierContext,
                policyloadSeqnoFailureReason = failureReason,
                policyloadSeqnoNotes = listOf(POLICYLOAD_SEQNO_PRELOAD_NOTE),
            )
        }
        val result = inspectPolicyloadSeqno()
        return copy(
            policyloadSeqnoAvailable = result.available,
            policyloadSeqnoProbeAttempted = result.probeAttempted,
            policyloadSeqnoState = result.state.name,
            policyloadSeqnoCarrierContext = carrierContext,
            policyloadSeqnoStatusSequence = result.statusSequence,
            policyloadSeqnoStatusPolicyload = result.statusPolicyload,
            policyloadSeqnoAccessSeqno = result.accessSeqno,
            policyloadSeqnoProcessClass = result.processClass,
            policyloadSeqnoFailureReason = result.failureReason,
            policyloadSeqnoNotes = result.notes.ifEmpty { listOf(POLICYLOAD_SEQNO_PRELOAD_NOTE) },
        )
    }
}

@JvmStatic
public fun nativeCollectContextValiditySnapshot(allowAccessChecks: Boolean): String {
    return SelinuxContextValidityBridge().nativeCollectContextValiditySnapshotInternal(allowAccessChecks)
}

public open suspend fun collectSnapshot(scan: ScanEpoch): SelinuxContextValiditySnapshot {
    val appContext = context?.applicationContext ?: return carrierFailureSnapshot(
        "SELinux carrier service unavailable.",
    )
    val store = generationStore ?: return carrierFailureSnapshot(
        SelinuxAppZygoteRecovery.GENERATION_FENCE_UNAVAILABLE,
    )
    trace("request scan=${scan.id} package=${appContext.packageName} service=${serviceClass.name}")
    val snapshot = sharedCollection(serviceClass).collect(scan) {
        trace("shared collection miss scan=${scan.id}")
        boundedSingleAttempt(TOTAL_TIMEOUT_MS, onTimeout = {
            carrierFailureSnapshot("SELinux carrier probe timed out.")
        }) {
            val gate = AppZygoteStartGate.Default
            // Keep the admission lock from the first bind through recovery. Otherwise another
            // useAppZygote bind could cancel ActivityManager's delayed retirement between the
            // stale result and the point where recovery starts waiting for child death.
            gate.withExclusive {
                val first = gate.admitExclusive(
                    scanStartedAt = scan.startedMillis,
                    refused = {
                        trace("start gate refused scan=${scan.id}")
                        failedAttempt(SKIPPED_AFTER_FAILED_START)
                    },
                    stoppedBeforeConnecting = CarrierAttempt::stoppedBeforeConnecting,
                    attempt = {
                        boundedSingleAttempt(DETECTION_TIMEOUT_MS, onTimeout = {
                            failedAttempt("SELinux carrier probe timed out.")
                        }) { performRemoteSnapshotCollection(appContext, scan, store) }
                    },
                )
                val recovered = SelinuxAppZygoteRecovery.recover(
                    first = first,
                    reason = { it.snapshot.failureReason },
                    parentPid = CarrierAttempt::parentPid,
                    awaitRetirement = { pid ->
                        trace("waiting for tracked App Zygote children to die oldParentPid=$pid scan=${scan.id}")
                        val drained = gate.awaitNoActiveLeases(CARRIER_RETIREMENT_TIMEOUT_MS)
                        if (!drained) {
                            trace("carrier retirement timed out oldParentPid=$pid scan=${scan.id}")
                            false
                        } else {
                            // AOSP schedules App-Zygote death 5 seconds after the last child
                            // leaves. Keep all new binds blocked for that interval plus a guard;
                            // the replacement parent and preload timestamp are still verified.
                            val quietWindowMs = APP_ZYGOTE_KILL_DELAY_MS + RETIREMENT_GUARD_MS
                            trace("all tracked carrier children died oldParentPid=$pid; " +
                                "waiting quietWindowMs=$quietWindowMs scan=${scan.id}")
                            delay(quietWindowMs)
                            trace("retirement quiet window elapsed oldParentPid=$pid scan=${scan.id}")
                            true
                        }
                    },
                    retry = {
                        trace("retirement window complete; rebinding for a new preload scan=${scan.id}")
                        gate.admitExclusive(
                            scanStartedAt = scan.startedMillis,
                            refused = { failedAttempt(SKIPPED_AFTER_FAILED_START) },
                            stoppedBeforeConnecting = CarrierAttempt::stoppedBeforeConnecting,
                            attempt = {
                                boundedSingleAttempt(REBIND_TIMEOUT_MS, onTimeout = {
                                    failedAttempt("SELinux carrier recovery binding timed out.")
                                }) { performRemoteSnapshotCollection(appContext, scan, store) }
                            },
                        )
                    },
                    failure = { reason -> failedAttempt(reason) },
                )
                val acceptedKey = recovered.generationKey
                if (acceptedKey != null && !store.commitAccepted(acceptedKey)) {
                    trace("generation fence commit failed scan=${scan.id} " +
                        "preloadPid=${acceptedKey.preloadPid}")
                    carrierFailureSnapshot("App Zygote generation fence could not be persisted.")
                        .copy(appZygoteParentPid = recovered.parentPid)
                } else {
                    recovered.snapshot
                }
            }
        }
    }
    trace("return scan=${scan.id} available=${snapshot.available} carrier=${snapshot.carrierContext} " +
        "avc=${snapshot.avcLookup.state} pairs=${snapshot.avcLookup.pairs} failure=${snapshot.failureReason}")
    return snapshot
}

