public fun preload(
    appInfo: ApplicationInfo,
    trace: (step: String) -> Unit = {}

public fun preload(
    appInfo: ApplicationInfo,
    versionCode: Long,
    buildRevision: String,
    trace: (step: String) -> Unit = {}

var sidtab = SelinuxSidtabSnapshot()
var statusAbi = SelinuxStatusAbiSnapshot()
var procAttrResults: List<SelinuxProcAttrCurrentResult>? = null
var avcLookup = SelinuxAvcLookupSnapshot()
var dirtySepolicyRaw = SelinuxDirtySepolicyRawSnapshot()
val payload = try {
    beforeCollection()
    val currentUid = Os.getuid()
    // Before anything that lets libselinux map the status page: on a kernel that breaks that
    // node, the first access check kills this carrier.
    trace("selinux: status page probe")
    val statusPage = statusPageProbe.inspect()
    val accessCheckBlockReason = statusPage.accessCheckBlockReason
    // The conformance requests only mmap and mprotect the node in a disposable child and
    // never dereference a granted mapping, so they stay safe before the access checks.
    trace("selinux: status mmap ABI probe")
    statusAbi = statusAbiProbe.inspect()
    // Direct I/O, isolated from libselinux and from any identity change in its child.
    trace("selinux: SID-table experiment")
    sidtab = if (currentUid == appInfo.uid) sidtabProbe.inspect() else SelinuxSidtabSnapshot(
        collection = SelinuxSidtabCollection.UNSUPPORTED,
        failureReason = "Carrier UID does not match the application UID.",
    )
    val baseSnapshot = collectBaseSnapshot(currentUid, appInfo.uid, accessCheckBlockReason, trace)
        .copy(sidtab = sidtab, statusAbi = statusAbi)
    var dirtyPolicyTraced = false
    val snapshot = SelinuxContextValidityAugmentation.augmentPreloadSnapshot(
        baseSnapshot = baseSnapshot,
        currentUid = currentUid,
        appUid = appInfo.uid,
        isUserBuild = Build.TYPE == "user",
        accessCheckBlockReason = accessCheckBlockReason,
        inspectProcAttrCurrent = {
            trace("selinux: controlled proc attr current child")
            procAttrCurrentProbe.inspect().also { procAttrResults = it }
        },
        inspectAvcLookup = {
            trace("selinux: app zygote AVC lookup child")
            avcLookupProbe.inspect(trace).also {
                avcLookup = it
                trace("selinux: AVC lookup state=${it.state} step=${it.step} errno=${it.errno} rounds=${it.rounds}")
                val parent = it.parentTiming
                trace("selinux: attr timing child pid=${it.pid} cpu=${it.cpu} " +
                    "pairs=${it.pairs} migrated=${it.cpuMigrations} " +
                    "delta=${it.medianDeltaNs.takeIf { _ -> it.timingMediansAvailable } ?: "N/A"}; " +
                    "parent pid=${parent.pid} cpu=${parent.cpu} pairs=${parent.pairs} " +
                    "migrated=${parent.migrations} delta=${parent.medianDeltaNs ?: "N/A"} " +
                    "complete=${parent.complete} errno=${parent.error}")
            }
        },
        inspectPolicyloadSeqno = {
            trace("selinux: policyload seqno")
            policyloadSeqnoProbe.inspect(statusPage)
        },
        checkAccess = { source, target, targetClass, permission ->
            if (!dirtyPolicyTraced) {
                dirtyPolicyTraced = true
                trace("selinux: java dirty policy checks")
            }
            checkSelinuxAccess(source, target, targetClass, permission)
        },
    )
    trace("selinux: direct raw access rule replay")
    val withRaw = collectDirtySepolicyRawSafely(snapshot) {
        dirtySepolicyRawProbe.inspect(
            snapshot, Build.TYPE == "user",
            statusHeader = (statusPage as? SelinuxStatusPageResult.Intact)?.header,
        )
    }
    dirtySepolicyRaw = withRaw.dirtySepolicyRaw
    trace("selinux: raw access state=${dirtySepolicyRaw.state} transactions=${dirtySepolicyRaw.observations.size}")
    SelinuxContextValidityPayloadCodec.encode(withRaw)
}

fun contextNode(context: String): String {
    val fd = try {
        Os.open("/sys/fs/selinux/context", OsConstants.O_WRONLY or OsConstants.O_CLOEXEC, 0)
    } catch (error: ErrnoException) {
        return "UNAVAILABLE:open errno=${error.errno}"
    }
    return try {
        val bytes = context.toByteArray(Charsets.UTF_8)
        if (Os.write(fd, bytes, 0, bytes.size) == bytes.size) "VALID" else "UNAVAILABLE:write short_write"
    } catch (error: ErrnoException) {
        if (error.errno == OsConstants.EINVAL) "INVALID" else "UNAVAILABLE:write errno=${error.errno}"
    } finally {
        Os.close(fd)
    }
}

accessState = classZero(context, context)
if (accessState == "VALID" && classZeroControlsPassed) {
    verifiedBy = SelinuxRawContextSource.ACCESS_CLASS_ZERO
    "VALID"
}

public fun SelinuxDirtySepolicyRawSnapshot.sameEpochDecisionSplits(): List<String> {
    if (!controlsPassed) return emptyList()
    return observations.groupBy { it.query }.mapNotNull { (query, samples) ->
        if (samples.size != 2 || samples[0].outcome == samples[1].outcome ||
            samples.any { it.outcome != "ALLOWED" && it.outcome != "DENIED" }) return@mapNotNull null
        val first = samples[0].response?.let(SelinuxRawAccess::parse)
        val second = samples[1].response?.let(SelinuxRawAccess::parse)
        if (first != null && second != null && first.seqno == second.seqno &&
            (first.flags and 1u) == 0u && (second.flags and 1u) == 0u) query else null
    }
}

internal fun collectDirtySepolicyRawSafely(
    original: SelinuxContextValiditySnapshot,
    collect: () -> SelinuxDirtySepolicyRawSnapshot,
): SelinuxContextValiditySnapshot {
    val result = try {
        collect()
    } catch (error: Throwable) {
        val reason = "DirtySepolicy Raw replay failed: ${error.message?.takeIf(String::isNotBlank) ?: "unknown cause"}"
        SelinuxDirtySepolicyRawSnapshot(
            state = SelinuxDirtySepolicyRawState.UNAVAILABLE,
            failureReason = reason,
            compatibility = SelinuxDirtySepolicyCompatibilityResult(
                SelinuxDirtySepolicyCompatibilityVerdict.ERROR,
                listOf(reason),
            ),
        )
    }
    return original.copy(dirtySepolicyRaw = result)
}

public enum class SelinuxPolicyloadSeqnoState {
    CLEAN,
    SUSPICIOUS,
    INCONCLUSIVE,
    UNAVAILABLE,

    /** Reading the status page this oracle compares killed a disposable child; stock selinuxfs never does. */
    STATUS_PAGE_FAULTED,
}

internal object SelinuxProcAttrCurrentNativePayload {
    private val CONTROL_STATES = setOf(
        SelinuxProcAttrCurrentResult.OUTCOME_CONTROLS_PASSED,
        SelinuxProcAttrCurrentResult.OUTCOME_PERMISSION_LIMITED,
        SelinuxProcAttrCurrentResult.OUTCOME_UNSUPPORTED,
        SelinuxProcAttrCurrentResult.OUTCOME_UNAVAILABLE,
        SelinuxProcAttrCurrentResult.OUTCOME_INCONCLUSIVE,
    )
    private val TARGET_STATES = setOf(
        SelinuxProcAttrCurrentResult.OUTCOME_CONTEXT_RECOGNIZED,
        SelinuxProcAttrCurrentResult.OUTCOME_NORMAL_EINVAL,
        SelinuxProcAttrCurrentResult.OUTCOME_INCONCLUSIVE,
    )

    fun decode(raw: String): List<SelinuxProcAttrCurrentResult> {
        require(raw.length <= 32_768) { "Oversized context-write payload" }
        val lines = raw.lineSequence().filter(String::isNotEmpty).toList()
        require(lines.firstOrNull() == "SCHEMA=1") { "Unsupported context-write schema" }
        val results = lines.drop(1).map { line ->
            require(line.startsWith("RESULT=")) { "Unexpected context-write record" }
            requireNotNull(SelinuxProcAttrCurrentPayloadCodec.decode(line.removePrefix("RESULT=")))
        }
        val recordLimit = SelinuxProcAttrCurrentResult.TARGET_COUNT + 1
        require(results.size in 1..recordLimit && results.map { it.label }.distinct().size == results.size)
        val control = results.first()
        require(control.label == SelinuxProcAttrCurrentResult.CONTROL_LABEL && control.targetContext.isEmpty())
        require(control.outcomeClass in CONTROL_STATES)
        results.drop(1).forEach { result ->
            require(result.targetContext.isNotBlank())
            require(result.outcomeClass in TARGET_STATES)
        }
        if (control.outcomeClass == SelinuxProcAttrCurrentResult.OUTCOME_CONTROLS_PASSED) {
            require(results.size == recordLimit) { "Incomplete controlled context-write results" }
        } else {
            require(results.drop(1).all { it.outcomeClass == SelinuxProcAttrCurrentResult.OUTCOME_INCONCLUSIVE })
        }
        return results
    }
}

internal object SelinuxProcAttrCurrentPayloadCodec {

    fun encode(result: SelinuxProcAttrCurrentResult): String {
        return listOf(
            result.label,
            result.targetContext,
            result.outcomeClass,
            result.rawMessage,
        ).joinToString(FIELD_SEPARATOR, transform = NativePayloadCodec::encodeValue)
    }

    /** Returns `null` when [payload] is not exactly [COLUMN_COUNT] columns, meaning it is not ours. */
    fun decode(payload: String): SelinuxProcAttrCurrentResult? {
        val parts = payload.split(FIELD_SEPARATOR)
        if (parts.size != COLUMN_COUNT) {
            return null
        }
        return SelinuxProcAttrCurrentResult(
            label = NativePayloadCodec.decodeValue(parts[0]),
            targetContext = NativePayloadCodec.decodeValue(parts[1]),
            outcomeClass = NativePayloadCodec.decodeValue(parts[2]),
            rawMessage = NativePayloadCodec.decodeValue(parts[3]),
        )
    }

    private const val FIELD_SEPARATOR = "\t"

    private const val COLUMN_COUNT = 4
}

fun decode(payload: String): SelinuxProcAttrCurrentResult? {
    val parts = payload.split(FIELD_SEPARATOR)
    if (parts.size != COLUMN_COUNT) {
        return null
    }
    return SelinuxProcAttrCurrentResult(
        label = NativePayloadCodec.decodeValue(parts[0]),
        targetContext = NativePayloadCodec.decodeValue(parts[1]),
        outcomeClass = NativePayloadCodec.decodeValue(parts[2]),
        rawMessage = NativePayloadCodec.decodeValue(parts[3]),
    )
}

internal class SelinuxSidtabProbe(
    private val collector: NativeSnapshotCollector = NativeSnapshotCollector.Default,
) {
    fun inspect(): SelinuxSidtabSnapshot = collector.collect(
        readPayload = ::nativeCollectSidtab,
        parse = SelinuxSidtabPayloadCodec::decode,
        unavailable = { failure ->
            SelinuxSidtabSnapshot(
                collection = SelinuxSidtabCollection.UNAVAILABLE,
                failureReason = failure.explain("SID-table experiment was unavailable"),
            )
        },
    )

    private external fun nativeCollectSidtab(): String
}

