    SUCCESS(0), PERMISSION_DENIED(13), INVALID_ARGUMENT(22),
}

public enum class SelinuxSidtabCollection {
    NOT_COLLECTED, COMPLETE, UNSUPPORTED, PERMISSION_LIMITED, UNAVAILABLE, INCONCLUSIVE,
}

internal fun StringBuilder.appendStatusAbi(snapshot: SelinuxContextValiditySnapshot) {
    append("STATUS_ABI_ATTEMPTED=")
        .append(if (snapshot.statusAbi.attempted) '1' else '0')
        .append('\n')
    append("STATUS_ABI_STATE=")
        .append(NativePayloadCodec.encodeValue(snapshot.statusAbi.state.name))
        .append('\n')
    snapshot.statusAbi.violatedRequests.takeIf { it.isNotEmpty() }?.let { requests ->
        append("STATUS_ABI_VIOLATED=")
            .append(NativePayloadCodec.encodeValue(requests.joinToString(",") { it.name }))
            .append('\n')
    }
    snapshot.statusAbi.pageSize?.let {
        append("STATUS_ABI_PAGE_SIZE=").append(it).append('\n')
    }
    snapshot.statusAbi.failureReason?.takeIf { it.isNotEmpty() }?.let {
        append("STATUS_ABI_FAILURE_REASON=")
            .append(NativePayloadCodec.encodeValue(it))
            .append('\n')
    }
    snapshot.statusAbi.notes.forEach { note ->
        append("STATUS_ABI_NOTE=").append(NativePayloadCodec.encodeValue(note)).append('\n')
    }
}

private enum class Outcome {
    VIOLATION,
    NO_VIOLATION,
    UNAVAILABLE,
    INCONCLUSIVE,
}

public enum class SelinuxStatusAbiState {
    /** At least one request stock selinuxfs rejects was granted. */
    VIOLATION,

    /** Every nonconforming request was rejected, like stock selinuxfs. */
    NO_VIOLATION,

    /** The node could not be opened or the baseline mapping failed, so no request reached the handler. */
    UNAVAILABLE,

    /** No grant was reported, but the child could not run or finish the request set. */
    INCONCLUSIVE,
}

public enum class SelinuxStatusAbiRequestKind {
    TWO_PAGE_SHARED,
    OFFSET_SHARED,
    WRITABLE_PRIVATE,
    MPROTECT_WRITE,
}

public data class SelinuxStatusAbiSnapshot(
    val attempted: Boolean = false,
    val state: SelinuxStatusAbiState = SelinuxStatusAbiState.INCONCLUSIVE,
    /** The requests the kernel granted, present when [state] is [SelinuxStatusAbiState.VIOLATION]. */
    val violatedRequests: List<SelinuxStatusAbiRequestKind> = emptyList(),
    val pageSize: Long? = null,
    /** Also retained with VIOLATION when later child failure leaves other requests unevaluated. */
    val failureReason: String? = null,
    val notes: List<String> = emptyList(),
)

internal sealed interface SelinuxStatusPageResult {

    /** Whether a child was forked to read the page. */
    val attempted: Boolean

    val notes: List<String>

    /**
     * Why this process must not let libselinux map and read the page, or null when it may. The first
     * android.os.SELinux.checkSELinuxAccess does exactly that, so only a page that read back intact, or
     * one libselinux cannot map either and so never reads, is safe.
     */
    val accessCheckBlockReason: String?
        get() = when (this) {
            is Intact, is Unavailable -> null
            is Faulted ->
                "Skipped: reading /sys/fs/selinux/status killed a disposable child" +
                    signal?.let { " (signal $it)" }.orEmpty() +
                    ", and libselinux reads it on the first access check."

            is Inconclusive ->
                "Skipped: the status page probe was inconclusive ($reason), " +
                    "so libselinux was not allowed to read /sys/fs/selinux/status."
        }

    /** The page read back like stock selinuxfs. */
    data class Intact(
        val header: SelinuxStatusHeader,
        override val notes: List<String> = emptyList(),
    ) : SelinuxStatusPageResult {
        override val attempted: Boolean get() = true
    }

    /** The child mapped the page, and a signal ended it before it read the header back. */
    data class Faulted(
        val signal: Int?,
        override val notes: List<String> = emptyList(),
    ) : SelinuxStatusPageResult {
        override val attempted: Boolean get() = true
    }

    /** open or mmap failed, so libselinux falls back to netlink and never reads a mapping. */
    data class Unavailable(
        val reason: String,
        override val notes: List<String> = emptyList(),
    ) : SelinuxStatusPageResult {
        override val attempted: Boolean get() = true
    }

    /** The child could not run, ended before it mapped the page, or did not report. */
    data class Inconclusive(
        val reason: String,
        override val attempted: Boolean,
        override val notes: List<String> = emptyList(),
    ) : SelinuxStatusPageResult
}

data class Intact(
    val header: SelinuxStatusHeader,
    override val notes: List<String> = emptyList(),
) : SelinuxStatusPageResult {
    override val attempted: Boolean get() = true
}

data class Faulted(
    val signal: Int?,
    override val notes: List<String> = emptyList(),
) : SelinuxStatusPageResult {
    override val attempted: Boolean get() = true
}

data class Unavailable(
    val reason: String,
    override val notes: List<String> = emptyList(),
) : SelinuxStatusPageResult {
    override val attempted: Boolean get() = true
}

