        val swipeFlagsList = mutableListOf<DirectionFlag>()

        if (swipeFlagsValue and DirectionFlag.UP.value == DirectionFlag.UP.value)
            swipeFlagsList.add(DirectionFlag.UP)
        if (swipeFlagsValue and DirectionFlag.DOWN.value == DirectionFlag.DOWN.value)
            swipeFlagsList.add(DirectionFlag.DOWN)
        if (swipeFlagsValue and DirectionFlag.LEFT.value == DirectionFlag.LEFT.value)
            swipeFlagsList.add(DirectionFlag.LEFT)
        if (swipeFlagsValue and DirectionFlag.RIGHT.value == DirectionFlag.RIGHT.value)
            swipeFlagsList.add(DirectionFlag.RIGHT)

        return swipeFlagsList
    }

var dragListener: OnItemDragListener<*>? = null
    set(value) {
        if (value != field) {
            field = value

            // Pass down this listener to the adapter, which is where it will be used
            adapter?.setInternalDragListener(value)
        }
    }

var swipeListener: OnItemSwipeListener<*>? = null
    set(value) {
        if (value != field) {
            field = value

            // Pass down this listener to the adapter, which is where it will be used
            adapter?.setInternalSwipeListener(value)
        }
    }

var adapter: DragDropSwipeAdapter<*,*>? = null
    set(value) {
        if (value != null) {
            if (value != field) {
                field = value

                // Pass down all these variables to the new adapter to set it up
                value.setInternalDragListener(dragListener)
                value.setInternalSwipeListener(swipeListener)
                value.swipeAndDragHelper.orientation = orientation
                value.swipeAndDragHelper.disabledDragFlagsValue = disabledDragFlagsValue
                value.swipeAndDragHelper.disabledSwipeFlagsValue = disabledSwipeFlagsValue

                super.setAdapter(value)
            }
        } else throw IllegalArgumentException("A null adapter cannot be set.")
    }

override fun setAdapter(adapter: Adapter<*>?) {
    when (adapter) {
        !is DragDropSwipeAdapter<*,*>? ->
            throw TypeCastException("The adapter must be an extension of DragDropSwipeAdapter.")
        else -> this.adapter = adapter
    }
}

override fun setLayoutManager(layoutManager: LayoutManager?) {
    super.setLayoutManager(layoutManager)

    // If the orientation is undefined, we try to guess it
    if (orientation == null) {
        when (layoutManager) {

            is LinearLayoutManager -> orientation =
                    when (layoutManager.orientation) {
                        VERTICAL -> ListOrientation.VERTICAL_LIST_WITH_VERTICAL_DRAGGING
                        HORIZONTAL -> ListOrientation.HORIZONTAL_LIST_WITH_UNCONSTRAINED_DRAGGING
                        else -> orientation
            }

            is GridLayoutManager -> orientation =
                    when (layoutManager.orientation) {
                        VERTICAL -> ListOrientation.GRID_LIST_WITH_HORIZONTAL_SWIPING
                        HORIZONTAL -> ListOrientation.GRID_LIST_WITH_VERTICAL_SWIPING
                        else -> orientation
            }
        }
    }
}

fun disableDragDirection(dragDirectionToDisable: ListOrientation.DirectionFlag) {
    val flagValue = dragDirectionToDisable.value
    if (orientation?.dragDirectionFlags?.any { it.value and flagValue == flagValue } == true)
        disabledDragFlagsValue = disabledDragFlagsValue or flagValue
}

fun disableSwipeDirection(swipeDirectionToDisable: ListOrientation.DirectionFlag) {
    val flagValue = swipeDirectionToDisable.value
    if (orientation?.swipeDirectionFlags?.any { it.value and flagValue == flagValue } == true)
        disabledSwipeFlagsValue = disabledSwipeFlagsValue or flagValue
}

fun enableDragDirection(dragDirectionToAllow: ListOrientation.DirectionFlag) {
    val flagValue = dragDirectionToAllow.value
    if (orientation?.dragDirectionFlags?.any { it.value and flagValue == flagValue } == true) {
        val newValue = disabledDragFlagsValue xor flagValue
        disabledDragFlagsValue = if (newValue < disabledDragFlagsValue) newValue else disabledDragFlagsValue
    }
}

fun enableSwipeDirection(swipeDirectionToAllow: ListOrientation.DirectionFlag) {
    val flagValue = swipeDirectionToAllow.value
    if (orientation?.swipeDirectionFlags?.any { it.value and flagValue == flagValue } == true) {
        val newValue = disabledSwipeFlagsValue xor flagValue
        disabledSwipeFlagsValue = if (newValue < disabledSwipeFlagsValue) newValue else disabledSwipeFlagsValue
    }
}

open class ScrollAwareRecyclerView @JvmOverloads constructor(
        context: Context,
        attrs: AttributeSet? = null,
        defStyleAttr: Int = 0
) : RecyclerView(context, attrs, defStyleAttr) {

    /**
     * Listener for the scrolling events.
     */
    var scrollListener: OnListScrollListener? = null

    private val internalListScrollListener = object : RecyclerView.OnScrollListener() {
        override fun onScrollStateChanged(recyclerView: RecyclerView, newState: Int) {
            super.onScrollStateChanged(recyclerView, newState)

            when (newState) {
                SCROLL_STATE_IDLE ->
                    scrollListener?.onListScrollStateChanged(OnListScrollListener.ScrollState.IDLE)
                SCROLL_STATE_DRAGGING ->
                    scrollListener?.onListScrollStateChanged(OnListScrollListener.ScrollState.DRAGGING)
                SCROLL_STATE_SETTLING ->
                    scrollListener?.onListScrollStateChanged(OnListScrollListener.ScrollState.SETTLING)
            }
        }

        override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {
            super.onScrolled(recyclerView, dx, dy)

            when {
                dy > 0 ->
                    scrollListener?.onListScrolled(OnListScrollListener.ScrollDirection.DOWN, dy)
                dy < 0 ->
                    scrollListener?.onListScrolled(OnListScrollListener.ScrollDirection.UP, -dy)
                dx > 0 ->
                    scrollListener?.onListScrolled(OnListScrollListener.ScrollDirection.RIGHT, dx)
                dx < 0 ->
                    scrollListener?.onListScrolled(OnListScrollListener.ScrollDirection.LEFT, -dx)
            }
        }
    }

    init {
        super.addOnScrollListener(internalListScrollListener)
    }

    @Deprecated("Use the property scrollListener instead.", ReplaceWith("scrollListener"))
    override fun addOnScrollListener(listener: OnScrollListener) {
        throw UnsupportedOperationException(
                "Only the property scrollListener can be used to add a scroll listener here.")
    }
}

