private fun Cluster<T>.computeViewKeys(): Set<ViewKey<T>> = if (shouldRenderAsCluster(this)) {
    if (clusterContentState.value != null) {
        setOf(ViewKey.Cluster(this))
    } else {
        emptySet()
    }
}

private suspend fun collectInvalidationsAndRerender(key: ViewKey<T>, view: InvalidatingComposeView) {
    callbackFlow {
        // When invalidated, emit on the next frame
        var invalidated = false
        view.onInvalidate = {
            if (!invalidated) {
                launch {
                    awaitFrame()
                    trySend(Unit)
                    invalidated = false
                }
                invalidated = true
            }
        }
        view.doOnAttach {
            view.doOnDetach { close() }
        }
        awaitClose()
    }
        .collectLatest {
            when (key) {
                is ViewKey.Cluster -> {
                    getMarker(key.cluster)?.let { marker ->
                        marker.setIcon(renderViewToBitmapDescriptor(view))
                        applyClusterMarkerProperties(
                            marker = marker,
                            properties = view.properties,
                            defaultAnchor = clusterContentAnchorState.value,
                            defaultZIndex = clusterContentZIndexState.value,
                            defaultRotation = clusterContentRotationState.value,
                        )
                    }
                }

                is ViewKey.Item -> {
                    getMarker(key.item)?.let { marker ->
                        applyClusterItemMarkerProperties(
                            marker = marker,
                            icon = renderViewToBitmapDescriptor(view),
                            properties = view.properties,
                            defaultAnchor = clusterItemContentAnchorState.value,
                            defaultZIndex = clusterItemContentZIndexState.value,
                            defaultRotation = clusterItemContentRotationState.value,
                        )
                    }
                }
            }
        }
}

private class InvalidatingComposeView(
    context: Context,
    private val getRotationOverride: () -> Float,
    private val getAnchor: () -> Offset,
    private val getZIndex: () -> Float,
    private val content: @Composable () -> Unit,
) : AbstractComposeView(context) {

    val properties = ClusteringMarkerProperties()
    var onInvalidate: (() -> Unit)? = null

    @Composable
    override fun Content() {
        val rotation = getRotationOverride()
        val anchor = getAnchor()
        val zIndex = getZIndex()
        LaunchedEffect(
            properties.anchor,
            properties.zIndex,
            properties.rotation,
            properties.contentDescription,
            rotation,
            anchor,
            zIndex,
        ) {
            invalidate()
        }
        CompositionLocalProvider(
            LocalClusteringMarkerProperties provides properties,
        ) {
            content()
        }
    }

    override fun invalidate() {
        super.invalidate()
        onInvalidate?.invoke()
    }

    override fun onDescendantInvalidated(child: View, target: View) {
        super.onDescendantInvalidated(child, target)
        onInvalidate?.invoke()
    }
}

public class ClusteringMarkerProperties {
    public var anchor: Offset? by mutableStateOf(null)
        internal set
    public var zIndex: Float? by mutableStateOf(null)
        internal set
    public var rotation: Float? by mutableStateOf(null)
        internal set
    public var contentDescription: String? by mutableStateOf(null)
        internal set
}

