fun Int.toNumericString(): String {
    val chars = toString().toCharArray()
    chars.reverse()
    val builder = StringBuilder()
    chars.forEachIndexed { index, c ->
        if (index != 0 && index % 3 == 0 && c != '-') {
            builder.append(",")
        }
        builder.append(c)
    }
    return builder.reverse().toString()
}

