private fun withAlt(
    tag: String,
    alt: String
): String {
    val attribute = """alt="${escapeAttribute(alt)}""""
    return if (altPattern.containsMatchIn(tag)) {
        altPattern.replace(tag) { attribute }
    } else {
        "$tag $attribute"
    }
}

fun markImages(html: String): String =
