    val start = LocalDateTime(targetDate, minutesToLocalTime(block.startMinutes))
    val end = if (block.endMinutes >= MINUTES_PER_DAY) {
        LocalDateTime(targetDate.plus(1, DateTimeUnit.DAY), LocalTime(hour = 0, minute = 0))
    } else {
