override suspend fun hasPermission(): Boolean {
    val read = ContextCompat.checkSelfPermission(context, Manifest.permission.READ_CALENDAR)
    val write = ContextCompat.checkSelfPermission(context, Manifest.permission.WRITE_CALENDAR)
    return read == PackageManager.PERMISSION_GRANTED && write == PackageManager.PERMISSION_GRANTED
}

private fun readEventRow(cursor: Cursor, timeZone: TimeZone): KalendarSyncEvent {
    val allDay = cursor.getInt(cursor.getColumnIndex(CalendarContract.Events.ALL_DAY)) != 0
    val startMs = cursor.getLong(cursor.getColumnIndex(CalendarContract.Events.DTSTART))
    val endIdx = cursor.getColumnIndex(CalendarContract.Events.DTEND)
    val rule = cursor.getString(cursor.getColumnIndex(CalendarContract.Events.RRULE))
        ?.takeIf { it.isNotBlank() }
        ?.let { parseRRuleString(value = it, timeZone = timeZone) }
    val endMs = when {
        !cursor.isNull(endIdx) -> cursor.getLong(endIdx)
        rule != null -> durationEndMillis(
            startMs = startMs,
            durationValue = cursor.getString(cursor.getColumnIndex(CalendarContract.Events.DURATION)),
        )
        else -> null
    }
    val date = if (allDay) {
        allDayDateFromUtcMillis(startMs)
    } else {
        millisToLocalDate(startMs, timeZone)
    }
    val endDate = if (allDay) {
        endMs?.let {
            allDayInclusiveEndDate(
                startDate = date,
                endDateTime = Instant.fromEpochMilliseconds(it).toLocalDateTime(TimeZone.UTC),
            )
        }
    } else {
        endMs?.let { millisToLocalDate(it, timeZone) }?.takeIf { it > date }
    }
    val eventRowId = cursor.getLong(cursor.getColumnIndex(CalendarContract.Events._ID))
    return BasicKalendarSyncEvent(
        id = eventRowId.toString(),
        date = date,
        eventName = cursor.getString(cursor.getColumnIndex(CalendarContract.Events.TITLE)) ?: "",
        eventDescription = cursor.getString(cursor.getColumnIndex(CalendarContract.Events.DESCRIPTION))
            ?.takeIf { it.isNotBlank() },
        startTime = if (allDay) null else millisToLocalTime(startMs, timeZone),
        endTime = if (allDay || endMs == null) null else millisToLocalTime(endMs, timeZone),
        recurrenceRule = rule,
        endDate = endDate,
        exceptionDates = parseExdateColumn(
            raw = cursor.getString(cursor.getColumnIndex(CalendarContract.Events.EXDATE)),
            timeZone = timeZone,
        ),
        reminders = readReminders(eventRowId),
        attendees = readAttendees(eventRowId),
    )
}

private fun durationEndMillis(startMs: Long, durationValue: String?): Long? =
    durationValue
        ?.let { parseRecurrenceDurationSeconds(it) }

private fun readReminders(eventId: Long): List<KalendarReminder> {
    val reminders = mutableListOf<KalendarReminder>()
    context.contentResolver.query(
        CalendarContract.Reminders.CONTENT_URI,
        arrayOf(CalendarContract.Reminders.MINUTES),
        "${CalendarContract.Reminders.EVENT_ID} = ?",
        arrayOf(eventId.toString()),
        null,
    )?.use { cursor ->
        val minutesIdx = cursor.getColumnIndex(CalendarContract.Reminders.MINUTES)
        while (cursor.moveToNext()) {
            val minutes = cursor.getInt(minutesIdx)
            if (minutes >= 0) {
                reminders += KalendarReminder(minutesBefore = minutes)
            }
        }
    }
    return reminders
}

private fun readAttendees(eventId: Long): List<KalendarAttendee> {
    val attendees = mutableListOf<KalendarAttendee>()
    context.contentResolver.query(
        CalendarContract.Attendees.CONTENT_URI,
        arrayOf(CalendarContract.Attendees.ATTENDEE_NAME, CalendarContract.Attendees.ATTENDEE_EMAIL),
        "${CalendarContract.Attendees.EVENT_ID} = ?",
        arrayOf(eventId.toString()),
        null,
    )?.use { cursor ->
        val nameIdx = cursor.getColumnIndex(CalendarContract.Attendees.ATTENDEE_NAME)
        val emailIdx = cursor.getColumnIndex(CalendarContract.Attendees.ATTENDEE_EMAIL)
        while (cursor.moveToNext()) {
            val email = cursor.getString(emailIdx)?.takeIf { it.isNotBlank() }
            if (email != null) {
                attendees += KalendarAttendee(
                    email = email,
                    name = cursor.getString(nameIdx)?.takeIf { it.isNotBlank() },
                )
            }
        }
    }
    return attendees
}

private fun defaultCalendarId(): Long? {
    val projection = arrayOf(CalendarContract.Calendars._ID, CalendarContract.Calendars.IS_PRIMARY)
    val selection = "${CalendarContract.Calendars.VISIBLE} = 1 AND " +
        "${CalendarContract.Calendars.CALENDAR_ACCESS_LEVEL} >= ${CalendarContract.Calendars.CAL_ACCESS_CONTRIBUTOR}"
    return context.contentResolver.query(
        CalendarContract.Calendars.CONTENT_URI,
        projection,
        selection,
        null,
        "${CalendarContract.Calendars.IS_PRIMARY} DESC",
    )?.use { cursor ->
        if (cursor.moveToFirst()) {
            cursor.getLong(cursor.getColumnIndex(CalendarContract.Calendars._ID))
        } else {
            null
        }
    }
}

override fun equals(other: Any?): Boolean {
    if (this === other) return true
    if (other !is KalendarAttendee) return false
    return email == other.email && name == other.name
}

fun encode(events: List<KalendarSyncEvent>): String = buildString {
    appendLine("BEGIN:VCALENDAR")
    appendLine("VERSION:2.0")
    appendLine("PRODID:-//Kalendar//KalendarSync//EN")
    appendLine("CALSCALE:GREGORIAN")
    appendLine("METHOD:PUBLISH")
    for (event in events) {
        encodeEvent(event)
    }
    append("END:VCALENDAR")
}

private fun exdateLine(event: KalendarSyncEvent): String {
    if (event.isAllDay) {
        return "EXDATE;VALUE=DATE:${event.exceptionDates.joinToString(",") { it.toIcalDateString() }}"
    }
    val startTime = event.resolvedStartTime()
    val values = event.exceptionDates.joinToString(",") { exceptionDate ->
        LocalDateTime(date = exceptionDate, time = startTime).toIcalDateTime()
    }
    return "EXDATE:$values"
}

fun decode(icsContent: String): List<KalendarSyncEvent> {
    val events = mutableListOf<KalendarSyncEvent>()
    val lines = unfoldLines(icsContent)
    var inEvent = false
    var inAlarm = false
    var props = VEventProps()
    for (line in lines) {
        when {
            line == "BEGIN:VEVENT" -> {
                inEvent = true
                inAlarm = false
                props = VEventProps()
            }
            line == "BEGIN:VALARM" && inEvent -> inAlarm = true
            line == "END:VALARM" && inAlarm -> inAlarm = false
            inAlarm -> parseAlarmTriggerMinutes(line)?.let {
                props = props.copy(reminderMinutes = props.reminderMinutes + it)
            }
            line == "END:VEVENT" && inEvent -> {
                inEvent = false
                buildEventOrNull(props)?.let { events += it }
            }
            inEvent -> parseLine(line)?.let { (key, params, value) ->
                props = props.updated(key, params, value)
            }
        }
    }
    return events
}

private fun parseAlarmTriggerMinutes(line: String): Int? {
    val parsed = parseLine(line)
    if (parsed == null || parsed.first != "TRIGGER") {
        return null
    }
    val raw = parsed.third.trim()
    if (!raw.startsWith("-")) {
        return null
    }
    val seconds = parseRecurrenceDurationSeconds(raw.removePrefix("-")) ?: return null
    return (seconds / SECONDS_PER_MINUTE).toInt()
}

private fun parseAttendee(params: Set<String>, value: String): KalendarAttendee {
    val name = params.firstOrNull { it.startsWith("CN=") }
        ?.removePrefix("CN=")
        ?.let { icalUnescape(it) }
    return KalendarAttendee(email = value.removeMailtoPrefix(), name = name)
}

private fun unfoldLines(raw: String): List<String> {
    return raw.replace("\r\n ", "").replace("\r\n\t", "")
        .replace("\n ", "").replace("\n\t", "")
        .lines()
        .map { it.trim() }
        .filter { it.isNotEmpty() }
}

private fun parseLine(line: String): Triple<String, Set<String>, String>? {
    val colonIdx = line.indexOf(':')
    if (colonIdx < 0) return null
    val keyPart = line.substring(0, colonIdx)
    val value = line.substring(colonIdx + 1)
    val parts = keyPart.split(';')
    val key = parts.first()
    val params = parts.drop(1).toSet()
    return Triple(key, params, value)
}

private fun parseIcalTime(value: String): LocalTime? = runCatching {
    val timePart = value.substringAfter('T', "").trimEnd('Z')
    if (timePart.length < MONTH_END_IDX) return null
    LocalTime(
        timePart.substring(0, 2).toInt(),
        timePart.substring(2, YEAR_END_IDX).toInt(),
        timePart.substring(YEAR_END_IDX, MONTH_END_IDX).toInt(),
    )
}

internal fun recurrenceDurationString(event: KalendarSyncEvent): String {
    return if (event.isAllDay) {
        val days = event.endDate?.let { event.date.daysUntil(it) + 1 } ?: 1
        "P${days.coerceAtLeast(1)}D"
    } else {
        val start = event.startTime
        val end = event.endTime
        val seconds = if (start != null && end != null) {
            (end.toSecondOfDay() - start.toSecondOfDay()).toLong()
        } else {
            DEFAULT_TIMED_DURATION_SECONDS
        }
        "PT${if (seconds > 0) seconds else DEFAULT_TIMED_DURATION_SECONDS}S"
    }
}

private fun parseIcalUtcTimePart(value: String): LocalTime? {
    val timePart = value.substringAfter('T', "").trimEnd('Z')
    if (timePart.length < ICAL_TIME_LENGTH) {
        return null
    }
    return runCatching {
        LocalTime(
            hour = timePart.substring(0, TWO_DIGIT_WIDTH).toInt(),
            minute = timePart.substring(TWO_DIGIT_WIDTH, MINUTE_END_IDX).toInt(),
            second = timePart.substring(MINUTE_END_IDX, ICAL_TIME_LENGTH).toInt(),
        )
    }.getOrNull()
}

internal fun parseRecurrenceDurationSeconds(value: String): Long? {
    val match = DURATION_REGEX.matchEntire(value.trim()) ?: return null
    val components = match.groupValues.drop(1)
    if (components.all { it.isEmpty() }) {
        return null
    }
    val unitSeconds = listOf(SECONDS_PER_WEEK, SECONDS_PER_DAY, SECONDS_PER_HOUR, SECONDS_PER_MINUTE, 1L)
    return components.zip(unitSeconds) { component, unit -> (component.toLongOrNull() ?: 0L) * unit }.sum()
}

internal fun parseIcalDateString(value: String): LocalDate? = runCatching {
    val v = value.substringBefore('T').filter { it.isDigit() }
    if (v.length < ICAL_DATE_LENGTH) {
        return null
    }
    LocalDate(
        year = v.substring(0, YEAR_END_IDX).toInt(),
        month = v.substring(YEAR_END_IDX, MONTH_END_IDX).toInt(),
        day = v.substring(MONTH_END_IDX, ICAL_DATE_LENGTH).toInt(),
    )
}

override fun equals(other: Any?): Boolean {
    if (this === other) return true
    if (other !is KalendarSeriesChange) return false
    if (updatedSeries != other.updatedSeries) return false
    return newEvents == other.newEvents
}

private fun KalendarSyncEvent.rewriteAsOneOff(edited: KalendarSyncEvent?): KalendarSeriesChange =
    KalendarSeriesChange(
        updatedSeries = edited?.copyAsBasic(id = id, recurrenceRule = null, exceptionDates = emptyList()),
        newEvents = emptyList(),
    )

private fun splitBoundary(rule: KalendarRule, occurrenceDate: LocalDate): LocalDate {
    val dayBeforeSplit = occurrenceDate.minus(1, DateTimeUnit.DAY)
    return rule.until?.let { minOf(it, dayBeforeSplit) } ?: dayBeforeSplit
}

private fun KalendarSyncEvent.rewriteWholeSeries(
    occurrenceDate: LocalDate,
    edited: KalendarSyncEvent?,
): KalendarSeriesChange {
    if (edited == null) {
        return KalendarSeriesChange(updatedSeries = null, newEvents = emptyList())
    }
    val shiftDays = occurrenceDate.daysUntil(edited.date)
    val seriesStart = date.plus(shiftDays, DateTimeUnit.DAY)
    return KalendarSeriesChange(
        updatedSeries = edited.copyAsBasic(
            id = id,
            date = seriesStart,
            endDate = edited.endDate?.let { seriesStart.plus(edited.date.daysUntil(it), DateTimeUnit.DAY) },
            recurrenceRule = recurrenceRule,
            exceptionDates = exceptionDates.map { it.plus(shiftDays, DateTimeUnit.DAY) },
        ),
        newEvents = emptyList(),
    )
}

private fun LocalDate.plusPeriods(rule: KalendarRule, periods: Int): LocalDate {
    val steps = periods.toLong() * rule.interval
    return when (rule.frequency) {
        KalendarRecurrenceFrequency.DAILY -> plus(steps, DateTimeUnit.DAY)
        KalendarRecurrenceFrequency.WEEKLY -> plus(steps * DAYS_PER_WEEK, DateTimeUnit.DAY)
        KalendarRecurrenceFrequency.MONTHLY -> plus(steps, DateTimeUnit.MONTH)
        KalendarRecurrenceFrequency.YEARLY -> plus(steps, DateTimeUnit.YEAR)
    }
}

private fun KalendarRule.enumeratesDaily(): Boolean = when (frequency) {
    KalendarRecurrenceFrequency.DAILY -> false
    KalendarRecurrenceFrequency.WEEKLY -> byDay.isNotEmpty()
    KalendarRecurrenceFrequency.MONTHLY -> byDay.isNotEmpty() || byMonthDay.isNotEmpty()
    KalendarRecurrenceFrequency.YEARLY -> byMonth.isNotEmpty() || byDay.isNotEmpty() || byMonthDay.isNotEmpty()
}

private fun KalendarSyncEvent.copyWithDate(date: LocalDate): KalendarSyncEvent = copyAsBasic(
    id = null,
    date = date,
    endDate = endDate?.let { date.plus(daysBetween(this.date, it), DateTimeUnit.DAY) }

override fun equals(other: Any?): Boolean {
    if (this === other) return true
    return other is KalendarReminder && minutesBefore == other.minutesBefore
}

public enum class KalendarRecurrenceFrequency {
    /** Repeat every N days. */
    DAILY,

    /** Repeat every N weeks, optionally restricted to specific days via [KalendarRule.byDay]. */
    WEEKLY,

    /**
     * Repeat every N months, optionally restricted to specific days of the month via
     * [KalendarRule.byMonthDay].
     */
    MONTHLY,

    /**
     * Repeat every N years, optionally restricted to specific months via
     * [KalendarRule.byMonth].
     */
    YEARLY,
}

public enum class KalendarWeekDay {
    MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY
}

public sealed class KalendarSyncResult<out T> {

    /**
     * The operation completed successfully.
     *
     * @param data The value produced by the operation.
     *
     * This is deliberately a plain `class` with a hand-written [equals] and [hashCode] rather
     * than a `data class`, matching the rest of this module's public surface: a `data class`
     * compiles `copy` and `componentN` into the ABI, which then cannot gain a property without
     * breaking already compiled consumers.
     */
    public class Success<T>(public val data: T) : KalendarSyncResult<T>() {

        /** Two successes are equal when they carry equal values. */
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            return other is Success<*> && data == other.data
        }

        override fun hashCode(): Int = data?.hashCode() ?: 0

        override fun toString(): String = "Success(data=$data)"
    }

    /**
     * The required calendar permission was not granted by the user.
     *
     * On Android, direct the user to grant `READ_CALENDAR` / `WRITE_CALENDAR`
     * via `ActivityCompat.requestPermissions`.
     * On iOS, direct the user to Settings → Privacy → Calendars.
     */
    public data object PermissionDenied : KalendarSyncResult<Nothing>()

    /**
     * Device calendar access is not available on this platform
     * (e.g. Desktop JVM, Web/wasmJS).
     */
    public data object NotSupported : KalendarSyncResult<Nothing>()

    /**
     * The operation failed with an error.
     *
     * @param message A human-readable description of what went wrong.
     * @param cause The underlying exception, if available.
     *
     * This is deliberately a plain `class` with a hand-written [equals] and [hashCode] rather
     * than a `data class`, matching the rest of this module's public surface — see [Success].
     */
    public class Error(
        public val message: String,
        public val cause: Throwable? = null,
    ) : KalendarSyncResult<Nothing>() {

        /** Two errors are equal when both the message and the cause match. */
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            return other is Error && message == other.message && cause == other.cause
        }

        override fun hashCode(): Int = HASH_FACTOR * message.hashCode() + (cause?.hashCode() ?: 0)

        override fun toString(): String = "Error(message=$message, cause=$cause)"
    }
}

public class Success<T>(public val data: T) : KalendarSyncResult<T>() {

    /** Two successes are equal when they carry equal values. */
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        return other is Success<*> && data == other.data
    }

    override fun hashCode(): Int = data?.hashCode() ?: 0

    override fun toString(): String = "Success(data=$data)"
}

override fun equals(other: Any?): Boolean {
