    strings: KalendarStrings = KalendarStrings(),
): SemanticsMatcher =
    SemanticsMatcher("announces \"${strings.todaySuffix}

public fun hasKalendarEvents(
    strings: KalendarStrings = KalendarStrings(),
): SemanticsMatcher =
    SemanticsMatcher("announces \"${strings.hasEventsSuffix}

public fun advanceBy(duration: Duration) {
    instant += duration
}

public fun deliver(range: KalendarDateRange, events: List<E> = emptyList()) {
    gate(range).value = Result.success(events)
}

public fun deliverAll(events: List<E> = emptyList()) {
    requests.forEach { range -> deliver(range = range, events = events) }
}

public fun fail(range: KalendarDateRange, failure: Throwable) {
    gate(range).value = Result.failure(failure)
}

public fun failAll(failure: Throwable) {
    requests.forEach { range -> fail(range = range, failure = failure) }
}

class KalendarEventFixturesTest {

    private val august15 = LocalDate(2026, 8, 15)

    @Test
    fun plainEventCarriesItsDateAndNothingItWasNotGiven() {
        val event = kalendarEvent(date = august15)

        assertEquals(august15, event.date)
        assertEquals("Test event", event.eventName)
        assertNull(event.id)
        assertNull(event.startTime)
        assertNull(event.endTime)
        assertNull(event.endDate)
        assertNull(event.eventColor)
    }

    @Test
    fun timedEventEndsDurationAfterItStarts() {
        val event = timedKalendarEvent(date = august15, start = LocalTime(9, 0))

        assertEquals(LocalDateTime(2026, 8, 15, 9, 0), event.startTime)
        assertEquals(LocalDateTime(2026, 8, 15, 10, 0), event.endTime, "one hour by default")

        val short = timedKalendarEvent(date = august15, start = LocalTime(14, 0), duration = 30.minutes)
        assertEquals(LocalDateTime(2026, 8, 15, 14, 30), short.endTime)
    }

    @Test
    fun timedEventCrossingMidnightEndsOnTheNextDateButStaysSingleDay() {
        val event = timedKalendarEvent(date = august15, start = LocalTime(23, 30))

        assertEquals(LocalDateTime(2026, 8, 16, 0, 30), event.endTime)
        assertNull(event.endDate, "a timed event is not a span; multiDayKalendarEvent is")
    }

    @Test
    fun multiDayEventOccupiesItsWholeSpan() {
        val event = multiDayKalendarEvent(start = august15, end = LocalDate(2026, 8, 17), id = "conf")

        assertEquals(august15, event.date)
        assertEquals(LocalDate(2026, 8, 17), event.endDate)
        assertEquals("conf", event.id)
    }

    @Test
    fun multiDayEventRejectsAReversedSpan() {
        assertFailsWith<IllegalArgumentException> {
            multiDayKalendarEvent(start = august15, end = LocalDate(2026, 8, 14))
        }
    }

    @Test
    fun recurringEventsAreWeeklyByDefaultWithDistinctIds() {
        val standups = recurringKalendarEvents(start = LocalDate(2026, 8, 3), count = 4, name = "standup")

        assertEquals(
            listOf(
                LocalDate(2026, 8, 3),
                LocalDate(2026, 8, 10),
                LocalDate(2026, 8, 17),
                LocalDate(2026, 8, 24),
            ),
            standups.map { occurrence -> occurrence.date },
        )
        assertTrue(standups.all { occurrence -> occurrence.eventName == "standup" })
        assertEquals(
            listOf("standup-0", "standup-1", "standup-2", "standup-3"),
            standups.map { occurrence -> occurrence.id },
            "shared ids would be de-duplicated into one event by the loader",
        )
    }

    @Test
    fun recurringEventsFollowTheGivenStep() {
        val monthly = recurringKalendarEvents(
            start = LocalDate(2026, 1, 31),
            count = 3,
            every = DatePeriod(months = 1),
        )

        assertEquals(
            listOf(LocalDate(2026, 1, 31), LocalDate(2026, 2, 28), LocalDate(2026, 3, 31)),
            monthly.map { occurrence -> occurrence.date },
            "each occurrence steps from the start, so February's clamp does not drift the rest",
        )
    }

    @Test
    fun recurringEventsWithZeroCountAreEmptyAndNegativeIsRejected() {
        assertTrue(recurringKalendarEvents(start = august15, count = 0).isEmpty())
        assertFailsWith<IllegalArgumentException> {
            recurringKalendarEvents(start = august15, count = -1)
        }
    }
}

class KalendarTestClockTest {

    @Test
    fun fixedTimeSourcePinsTodayAndNow() {
        val source = fixedKalendarTimeSource(now = LocalDateTime(2026, 3, 10, 9, 0))

        assertEquals(LocalDate(2026, 3, 10), source.today())
        assertEquals(LocalDateTime(2026, 3, 10, 9, 0), source.now())
        assertEquals(LocalDate(2026, 3, 10), source.today(), "asking again moves nothing")
    }

    @Test
    fun fixedTimeSourceResolvesTheWallClockInTheGivenZone() {
        val tokyo = TimeZone.of("Asia/Tokyo")
        val source = fixedKalendarTimeSource(now = LocalDateTime(2026, 3, 10, 9, 0), timeZone = tokyo)

        assertEquals(LocalDate(2026, 3, 10), source.today())
        assertEquals(
            LocalDateTime(2026, 3, 10, 9, 0).toInstant(tokyo),
            source.clock.now(),
            "09:00 in Tokyo is the pinned instant, not 09:00 UTC",
        )
    }

    @Test
    fun advanceByCrossesMidnightAndTodayFollows() {
        val clock = KalendarTestClock(start = LocalDateTime(2026, 3, 10, 23, 59))
        val source = clock.asTimeSource()
        assertEquals(LocalDate(2026, 3, 10), source.today())

        clock.advanceBy(2.minutes)

        assertEquals(LocalDate(2026, 3, 11), source.today())
        assertEquals(LocalDateTime(2026, 3, 11, 0, 1), source.now())
    }

    @Test
    fun assigningTheInstantJumpsTheClockBackwardsToo() {
        val clock = KalendarTestClock(start = LocalDateTime(2026, 3, 10, 9, 0))
        val source = clock.asTimeSource()

        clock.instant = LocalDateTime(2025, 12, 31, 23, 0).toInstant(TimeZone.UTC)

        assertEquals(LocalDate(2025, 12, 31), source.today())
    }

    @Test
    fun oneClockBacksTwoZonesThatDisagreeAboutToday() {
        val clock = KalendarTestClock(start = LocalDateTime(2026, 1, 15, 23, 0))
        val utc = clock.asTimeSource()
        val tokyo = clock.asTimeSource(timeZone = TimeZone.of("Asia/Tokyo"))

        assertEquals(LocalDate(2026, 1, 15), utc.today())
        assertEquals(LocalDate(2026, 1, 16), tokyo.today(), "already tomorrow in Tokyo")
    }
}

@OptIn(ExperimentalCoroutinesApi::class)
class KalendarTestEventSourceTest {

    private val march = KalendarDateRange(start = LocalDate(2026, 3, 1), endInclusive = LocalDate(2026, 3, 31))
    private val april = KalendarDateRange(start = LocalDate(2026, 4, 1), endInclusive = LocalDate(2026, 4, 30))

    @Test
    fun staysSilentUntilTheTestDelivers() = runTest {
        val source = KalendarTestEventSource<BasicKalendarEvent>()
        val emissions = mutableListOf<List<BasicKalendarEvent>>()

        backgroundScope.launch { source.eventsIn(march).collect { events -> emissions += events } }
        runCurrent()
        assertTrue(emissions.isEmpty(), "asked is not answered")

        val standup = kalendarEvent(date = LocalDate(2026, 3, 15), id = "1")
        source.deliver(range = march, events = listOf(standup))
        runCurrent()

        assertEquals(listOf(listOf(standup)), emissions)
    }

    @Test
    fun recordsEveryCollectionInRequestOrder() = runTest {
        val source = KalendarTestEventSource<BasicKalendarEvent>()

        backgroundScope.launch { source.eventsIn(march).collect {} }
        backgroundScope.launch { source.eventsIn(april).collect {} }
        backgroundScope.launch { source.eventsIn(march).collect {} }
        runCurrent()

        assertEquals(listOf(march, april, march), source.requestedRanges, "a re-collection counts again")
    }

    @Test
    fun deliverAllAnswersEveryRequestedRangeAtOnce() = runTest {
        val source = KalendarTestEventSource<BasicKalendarEvent>()
        val answered = mutableListOf<KalendarDateRange>()

        backgroundScope.launch { source.eventsIn(march).collect { answered += march } }
        backgroundScope.launch { source.eventsIn(april).collect { answered += april } }
        runCurrent()
        source.deliverAll()
        runCurrent()

        assertEquals(setOf(march, april), answered.toSet())
    }

    @Test
    fun failMakesThatRangesFlowThrowTheGivenFailure() = runTest {
        val source = KalendarTestEventSource<BasicKalendarEvent>()
        val failure = IllegalStateException("offline")
        var caught: Throwable? = null

        backgroundScope.launch {
            try {
                source.eventsIn(march).collect {}
            } catch (thrown: IllegalStateException) {
                caught = thrown
            }
        }
        runCurrent()
        source.fail(range = march, failure = failure)
        runCurrent()

        assertSame(failure, caught, "the loader receives the exact failure the test scripted")
        assertTrue(source.cancelledRanges.isEmpty(), "a failure is not a cancellation")
    }

    @Test
    fun anAnswerPrimedBeforeTheRequestArrivesImmediately() = runTest {
        val source = KalendarTestEventSource<BasicKalendarEvent>()
        val standup = kalendarEvent(date = LocalDate(2026, 3, 15), id = "1")
        source.deliver(range = march, events = listOf(standup))
        val emissions = mutableListOf<List<BasicKalendarEvent>>()

        backgroundScope.launch { source.eventsIn(march).collect { events -> emissions += events } }
        runCurrent()

        assertEquals(listOf(listOf(standup)), emissions, "a pre-loaded source answers in the same turn")
    }

    @Test
    fun aSecondDifferentDeliveryReEmitsThroughTheStillCollectedFlow() = runTest {
        val source = KalendarTestEventSource<BasicKalendarEvent>()
        val emissions = mutableListOf<Int>()

        backgroundScope.launch { source.eventsIn(march).collect { events -> emissions += events.size } }
        runCurrent()
        source.deliver(range = march)
        runCurrent()
        source.deliver(range = march, events = listOf(kalendarEvent(date = LocalDate(2026, 3, 15), id = "1")))
        runCurrent()

        assertEquals(listOf(0, 1), emissions, "the source behaves like a query that re-emits on change")
    }

    @Test
    fun recordsACancelledCollectionAsCancelled() = runTest {
        val source = KalendarTestEventSource<BasicKalendarEvent>()

        val collection = backgroundScope.launch { source.eventsIn(march).collect {} }
        runCurrent()
        assertTrue(source.cancelledRanges.isEmpty())

        collection.cancelAndJoin()

        assertEquals(listOf(march), source.cancelledRanges)
    }
}

class KalendarSemanticsMatchersUiTest {

    @get:Rule
    val rule = createComposeRule()

    private val august15 = LocalDate(2026, 8, 15)

    @Test
    fun findsADayCellByItsDateAndOnlyItsDate() {
        rule.setContent {
            KalendarMonth(selectedDate = august15)
        }

        rule.onKalendarDay(august15).assertExists()
        rule.onKalendarDay(LocalDate(2026, 1, 15)).assertDoesNotExist()
    }

    @Test
    fun stockSelectionAssertionsComposeWithTheFinder() {
        rule.setContent {
            KalendarMonth(selectedDate = august15)
        }

        rule.onKalendarDay(august15).assertIsSelected()
        rule.onKalendarDay(LocalDate(2026, 8, 16)).assertIsNotSelected()
    }

    @Test
    fun aDisabledDateReadsAsNotEnabled() {
        rule.setContent {
            KalendarMonth(
                selectedDate = august15,
                config = KalendarViewConfig(disabledDates = { date -> date == LocalDate(2026, 8, 20) }),
            )
        }

        rule.onKalendarDay(LocalDate(2026, 8, 20)).assertIsNotEnabled()
    }

    @Test
    fun todayAndHasEventsMatchTheSuffixedDescriptionsTheLibraryPublishes() {
        rule.setContent {
            ProvideKalendarTimeSource(fixedKalendarTimeSource(now = LocalDateTime(2026, 8, 15, 9, 0))) {
                KalendarMonth(
                    selectedDate = august15,
                    events = listOf(kalendarEvent(date = august15, id = "1")),
                )
            }
        }

        // Both suffixes are appended to this cell's description, and the finder still matches it.
        rule.onKalendarDay(august15)
            .assert(isKalendarToday())
            .assert(hasKalendarEvents())
        // SemanticsMatcher has no negation, so "the 16th is neither" is an absence assertion.
        val august16 = LocalDate(2026, 8, 16)
        rule.onNode(hasKalendarDay(august16) and isKalendarToday()).assertDoesNotExist()
        rule.onNode(hasKalendarDay(august16) and hasKalendarEvents()).assertDoesNotExist()
    }

    @Test
    fun clickingThroughTheFinderReportsTheDate() {
        var clicked: LocalDate? = null
        rule.setContent {
            KalendarMonth(
                selectedDate = august15,
                onDateClick = { date, _ -> clicked = date },
            )
        }

        rule.onKalendarDay(LocalDate(2026, 8, 21)).performClick()

        rule.runOnIdle { assertEquals(LocalDate(2026, 8, 21), clicked) }
    }

    @Test
    fun customStringsMatchWhenTheTestPassesTheSameStrings() {
        val german = KalendarStrings(
            todaySuffix = ", heute",
            dayAccessibilityLabel = { date, monthName -> "${date.day}. $monthName ${date.year}" },
        )
        rule.setContent {
            ProvideKalendarTimeSource(fixedKalendarTimeSource(now = LocalDateTime(2026, 8, 15, 9, 0))) {
                KalendarTheme(strings = german) {
                    KalendarMonth(selectedDate = august15)
                }
            }
        }

        rule.onKalendarDay(august15, strings = german).assert(isKalendarToday(strings = german))
        rule.onKalendarDay(august15).assertDoesNotExist()
    }
}

