@Composable
private fun <E : KalendarEvent> ScheduleBlockLayout(
    blocks: List<KalendarScheduleBlock>,
    hourHeight: Dp,
    onEventClick: (E) -> Unit,
    date: LocalDate,
    window: KalendarHourWindow,
    columnDates: List<LocalDate>? = null,
    snapMinutes: Int = DEFAULT_SCHEDULE_SNAP_MINUTES,
    onEventTimeChange: ((event: E, newStart: LocalDateTime, newEnd: LocalDateTime) -> Unit)? = null,
    eventContent: @Composable (KalendarScheduleEventScope<E>) -> Unit,
) {
    // Remembered so the identity is stable: an inline adapter would be a fresh parameter every
    // recomposition and would stop every block below from ever skipping.
    val blockClick = remember(onEventClick) { blockEventClickAdapter(onEventClick) }
    KalendarBlockLayout(
        blocks = blocks,
        hourHeight = hourHeight,
        window = window,
        snapMinutes = snapMinutes,
        horizontalShift = ScheduleDayAxis(date = date, columnDates = columnDates),
        onEventClick = blockClick,
        onRelease = onEventTimeChange?.let { handler -> scheduleReleaseHandler(handler) },
        eventContent = { block, isDragging, targetDate ->
            val scope = remember(block, isDragging, targetDate) {
                scheduleEventScope<E>(block = block, date = targetDate, isDragging = isDragging)
            }
            eventContent(scope)
        },
    )
}

private fun <E : KalendarEvent> scheduleReleaseHandler(
    handler: (event: E, newStart: LocalDateTime, newEnd: LocalDateTime) -> Unit,
): (KalendarScheduleBlock, LocalDate) -> Unit = { block, targetDate ->
    val (newStart, newEnd) = dragReleaseTimes(block = block, targetDate = targetDate)
    handler(asCalendarEvent(block.event), newStart, newEnd)
}

@Composable
private fun ScheduleCreateLayer(
    blocks: List<KalendarScheduleBlock>,
    date: LocalDate,
    hourHeight: Dp,
    snapMinutes: Int,
    window: KalendarHourWindow,
    onEventCreate: ((start: LocalDateTime, end: LocalDateTime) -> Unit)?,
) {
    if (onEventCreate == null) {
        return
    }
    var dragState by remember { mutableStateOf<CreateDragState?>(null) }
    val minutePx = with(LocalDensity.current) { hourHeight.toPx() } / MINUTES_PER_HOUR

    val latestBlocks = rememberUpdatedState(blocks)
    val latestDate = rememberUpdatedState(date)
    val latestSnapMinutes = rememberUpdatedState(snapMinutes)
    val latestMinutePx = rememberUpdatedState(minutePx)
    val latestWindow = rememberUpdatedState(window)
    val latestOnEventCreate = rememberUpdatedState(onEventCreate)

    fun rangeOf(state: CreateDragState): KalendarScheduleCreateRange = scheduleCreateRange(
        anchorPx = state.anchorPx,
        currentPx = state.currentPx,
        minutePx = latestMinutePx.value,
        snapMinutes = latestSnapMinutes.value,
        window = latestWindow.value,
    )

    Box(
        modifier = Modifier.fillMaxSize().pointerInput(Unit) {
            detectDragGesturesAfterLongPress(
                onDragStart = { offset ->
                    val onBlock = scheduleBlockAt(
                        blocks = latestBlocks.value,
                        xPx = offset.x,
                        yPx = offset.y,
                        widthPx = size.width,
                        minutePx = latestMinutePx.value,
                        window = latestWindow.value,
                    ) != null
                    dragState = if (onBlock) {
                        null
                    } else {
                        CreateDragState(anchorPx = offset.y, currentPx = offset.y)
                    }
                },
                onDragEnd = {
                    dragState?.let { state ->
                        val (start, end) = scheduleCreateTimes(
                            range = rangeOf(state),
                            date = latestDate.value,
                        )
                        latestOnEventCreate.value(start, end)
                    }
                    dragState = null
                },
                onDragCancel = {
                    dragState = null
                },
                onDrag = { change, dragAmount ->
                    dragState?.let { state ->
                        change.consume()
                        dragState = state.copy(currentPx = state.currentPx + dragAmount.y)
                    }
                },
            )
        },
    ) {
        dragState?.let { state ->
            ScheduleCreatePreview(
                range = rangeOf(state),
                hourHeight = hourHeight,
                minutePx = minutePx,
                window = window,
            )
        }
    }
}

