@Composable
public fun rememberKalendarTimelineState(
    initialDate: LocalDate = rememberInitialKalendarDate(),
    startDayOfWeek: DayOfWeek = DayOfWeek.MONDAY,
    minDate: LocalDate? = null,
    maxDate: LocalDate? = null,
    timeSource: KalendarTimeSource = rememberKalendarTimeSource(),
): KalendarTimelineState {
    val pager = remember(initialDate, startDayOfWeek, minDate, maxDate) {
        KalendarPager.bounded(
            unit = KalendarPageUnit.Month,
            initialDate = initialDate,
            startDayOfWeek = startDayOfWeek,
            minDate = minDate,
            maxDate = maxDate,
        )
    }
    val lazyListState = rememberLazyListState(initialFirstVisibleItemIndex = pager.initialPage)

    val state = remember(lazyListState, pager) {
        KalendarTimelineState(
            lazyListState = lazyListState,
            pager = pager,
            timeSource = timeSource,
        )
    }
    SideEffect { state.updateTimeSource(timeSource) }
    return state
}

public suspend fun animateScrollTo(date: LocalDate) {
    pagerState.animateScrollToPage(pager.pageOf(date))
}

public suspend fun animateScrollToToday() {
    animateScrollTo(timeSource.today())
}

public suspend fun animateToPreviousPage() {
    pagerState.animateScrollToPage(pager.coercePage(pagerState.currentPage - 1))
}

public suspend fun animateToNextPage() {
    pagerState.animateScrollToPage(pager.coercePage(pagerState.currentPage + 1))
}

@Composable
private fun rememberKalendarPagedState(
    unit: KalendarPageUnit,
    initialDate: LocalDate,
    startDayOfWeek: DayOfWeek,
    minDate: LocalDate?,
    maxDate: LocalDate?,
    timeSource: KalendarTimeSource,
): KalendarViewState {
    val pager = remember(unit, initialDate, startDayOfWeek, minDate, maxDate) {
        KalendarPager.endless(
            unit = unit,
            initialDate = initialDate,
            startDayOfWeek = startDayOfWeek,
            minDate = minDate,
            maxDate = maxDate,
        )
    }
    val pagerState = rememberPagerState(
        initialPage = pager.initialPage,
        pageCount = { pager.pageCount },
    )
    val state = remember(pagerState, pager) {
        KalendarViewState(pagerState = pagerState, pager = pager, timeSource = timeSource)
    }
    // Applied after composition succeeds, so a pass that is thrown away cannot leave the state
    // pointing at a clock the caller never committed to.
    SideEffect { state.updateTimeSource(timeSource) }
    return state
}

@Immutable
public class KalendarShapes(
    public val dayCell: Shape,
    public val eventIndicator: Shape,
    public val eventBlock: Shape,
    public val popup: Shape,
    public val agendaCard: Shape,
) {

    /** Returns a duplicate of these shapes with only the ones passed here replaced. */
    public fun copy(
        dayCell: Shape = this.dayCell,
        eventIndicator: Shape = this.eventIndicator,
        eventBlock: Shape = this.eventBlock,
        popup: Shape = this.popup,
        agendaCard: Shape = this.agendaCard,
    ): KalendarShapes = KalendarShapes(
        dayCell = dayCell,
        eventIndicator = eventIndicator,
        eventBlock = eventBlock,
        popup = popup,
        agendaCard = agendaCard,
    )

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is KalendarShapes) return false
        if (dayCell != other.dayCell) return false
        if (eventIndicator != other.eventIndicator) return false
        if (eventBlock != other.eventBlock) return false
        if (popup != other.popup) return false
        if (agendaCard != other.agendaCard) return false
        return true
    }

    override fun hashCode(): Int {
        var result = dayCell.hashCode()
        result = 31 * result + eventIndicator.hashCode()
        result = 31 * result + eventBlock.hashCode()
        result = 31 * result + popup.hashCode()
        result = 31 * result + agendaCard.hashCode()
        return result
    }

    override fun toString(): String = "KalendarShapes(" +
        "dayCell=$dayCell, " +
        "eventIndicator=$eventIndicator, " +
        "eventBlock=$eventBlock, " +
        "popup=$popup, " +
        "agendaCard=$agendaCard" +
        ")"
}

