    }

    @Test
    fun saver_roundTrip_restoresSelection() {
        val original = KalendarSelectionState(KalendarSelectionMode.Multiple, emptySet())
        original.onDateClick(LocalDate(2026, 8, 12))
        original.onDateClick(LocalDate(2026, 8, 15))

        val restored = saveAndRestore(original, KalendarSelectionMode.Multiple)
        assertEquals(original.selectedDates, restored.selectedDates)
    }

    @Test
    fun saver_roundTrip_restoresPendingRangeStart() {
        val original = KalendarSelectionState(KalendarSelectionMode.Range, emptySet())
        original.onDateClick(LocalDate(2026, 8, 12))

        val restored = saveAndRestore(original, KalendarSelectionMode.Range)
        restored.onDateClick(LocalDate(2026, 8, 15))
        assertEquals(
            setOf(
                LocalDate(2026, 8, 12),
                LocalDate(2026, 8, 13),
                LocalDate(2026, 8, 14),
                LocalDate(2026, 8, 15),
            ),
            restored.selectedDates,
        )
    }

    private fun saveAndRestore(
        state: KalendarSelectionState,
        mode: KalendarSelectionMode,
    ): KalendarSelectionState {
        val saver = KalendarSelectionState.saver(mode)
        val saved = with(saver) { androidx.compose.runtime.saveable.SaverScope { true }.save(state) }
        checkNotNull(saved) { "saver produced null" }
        return checkNotNull(saver.restore(saved))
    }
}

class KalendarAgendaItemKeyTest {

    @get:Rule
    val rule = createComposeRule()

    @Suppress("MagicNumber")
    private val day = LocalDate(2026, 3, 10)

    /**
     * Regression: an event carrying `id = "1"` beside an id-less event sitting at index 1 produced
     * the same list key, because a null id fell back to the index in the very space the ids live
     * in. A `LazyColumn` throws on a duplicate key, so the whole agenda crashed rather than
     * degrading.
     *
     * The mix is ordinary rather than exotic — events synced from a device arrive with ids, locally
     * drafted ones do not — so any consumer doing both on one day hit it.
     */
    @Test
    fun agenda_dayMixingIdentifiedAndUnidentifiedEvents_rendersBoth() {
        rule.setContent {
            KalendarAgenda(
                events = listOf(
                    BasicKalendarEvent(
                        date = day,
                        eventName = "Synced, has an id",
                        startTime = LocalDateTime(2026, 3, 10, 9, 0),
                        id = "1",
                    ),
                    BasicKalendarEvent(
                        date = day,
                        eventName = "Local draft, no id",
                        startTime = LocalDateTime(2026, 3, 10, 11, 0),
                    ),
                ),
            )
        }
        rule.waitForIdle()

        rule.onNodeWithText("Synced, has an id").assertExists()
        rule.onNodeWithText("Local draft, no id").assertExists()
    }

    /** The same collision one step along: an id of "2" against an id-less event at index 2. */
    @Test
    fun agenda_identifierMatchingALaterIndex_stillRendersEveryEvent() {
        rule.setContent {
            KalendarAgenda(
                events = listOf(
                    BasicKalendarEvent(
                        date = day,
                        eventName = "First",
                        startTime = LocalDateTime(2026, 3, 10, 8, 0),
                    ),
                    BasicKalendarEvent(
                        date = day,
                        eventName = "Second",
                        startTime = LocalDateTime(2026, 3, 10, 9, 0),
                    ),
                    BasicKalendarEvent(
                        date = day,
                        eventName = "Third, id collides with index two",
                        startTime = LocalDateTime(2026, 3, 10, 10, 0),
                        id = "2",
                    ),
                ),
            )
        }
        rule.waitForIdle()

        rule.onNodeWithText("First").assertExists()
        rule.onNodeWithText("Second").assertExists()
        rule.onNodeWithText("Third, id collides with index two").assertExists()
    }
}

