class EnglishAppRule : ExternalResource() {

    private val device = UiDevice.getInstance(InstrumentationRegistry.getInstrumentation())
    private var previous: String? = null

    override fun before() {
        val current = device.executeShellCommand("cmd locale get-app-locales $PACKAGE_NAME")
        previous = APP_LOCALES.find(current)?.groupValues?.get(1)?.replace(" ", "")
        setAppLocales("en")
    }

    override fun after() {
        previous?.let { setAppLocales(it) }
    }

    private fun setAppLocales(locales: String) {
        val flag = if (locales.isEmpty()) "" else " --locales $locales"
        device.executeShellCommand("cmd locale set-app-locales $PACKAGE_NAME$flag")
    }

    private companion object {
        // "Locales for com.dede.android_eggs for user 0 are [en]"
        val APP_LOCALES = Regex("""\[(.*)]""")
    }
}

fun UiDevice.acceptWelcomeIfNeeded() {
    val deadline = SystemClock.uptimeMillis() + UI_TIMEOUT
    while (SystemClock.uptimeMillis() < deadline) {
        val agree = findObject(By.text(TEXT_AGREE))
        if (agree != null) {
            agree.click()
            waitForIdle()
            return
        }
        if (hasObject(By.desc(DESC_SETTINGS))) {
            return
        }
        SystemClock.sleep(POLL_INTERVAL)
    }
}

fun UiDevice.waitForHome(): Boolean {
    return wait(Until.hasObject(By.desc(DESC_SETTINGS)), UI_TIMEOUT) ?: false
}

fun UiDevice.startApp() {
    val resolved = executeShellCommand(
        "cmd package resolve-activity --brief -a android.intent.action.MAIN " +
                "-c android.intent.category.LAUNCHER $PACKAGE_NAME"
    )
    val component = resolved.lineSequence().map { it.trim() }.lastOrNull { "/" in it }
    checkNotNull(component) { "The app has no launcher activity: $resolved" }
    val output = executeShellCommand("am start -W -n $component")
    check("Error" !in output) { "Could not start the app: $output" }
}

fun UiDevice.resumedActivity(): String? {
    val component = RESUMED_ACTIVITY.find(executeShellCommand("dumpsys activity activities"))
        ?.groupValues?.get(1) ?: return null
    val (pkg, cls) = component.split('/', limit = 2).takeIf { it.size == 2 } ?: return component
    // The system abbreviates classes of the app's own package to ".Foo"
    return if (cls.startsWith('.')) "$pkg/$pkg$cls" else component
}

fun UiDevice.awaitResumedActivity(expected: String, timeout: Long = UI_TIMEOUT): String? {
    val deadline = SystemClock.uptimeMillis() + timeout
    var actual = resumedActivity()
    while (actual != expected && SystemClock.uptimeMillis() < deadline) {
        SystemClock.sleep(POLL_INTERVAL)
        actual = resumedActivity()
    }
    return actual
}

@RunWith(AndroidJUnit4::class)
class SmokeTest {

    @get:Rule
    val english = EnglishAppRule()

    private val device = UiDevice.getInstance(InstrumentationRegistry.getInstrumentation())

    @Before
    fun setUp() {
        // While generating a Baseline Profile the plugin also runs the tests of this module that
        // use no rule; the smoke test only makes sense on the minified build.
        val rules = InstrumentationRegistry.getArguments().getString(ENABLED_RULES).orEmpty()
        assumeFalse(rules.contains("baselineprofile", ignoreCase = true))

        device.wakeUp()
        device.executeShellCommand("am force-stop $PACKAGE_NAME")
        device.startApp()
        device.acceptWelcomeIfNeeded()
    }

    @Test
    fun homeSearchAndSettingsWork() {
        assertTrue("The home screen did not render", device.waitForHome())
        assertTrue("The egg list was not scrollable", device.scrollEggList())
        assertTrue("The search bar did not open", device.searchEggs("android"))
        assertTrue("The settings drawer did not open", device.browseSettings())
        assertNoCrash("home, search and settings")
    }

    @Test
    fun everyEggOpensItsActivity() {
        // An egg newer than the device's own release may not run there.
        EGGS.filter { it.apiLevel <= Build.VERSION.SDK_INT }.forEach { egg ->
            device.clearCrashLog()
            device.startEgg(egg.apiLevel)
            assertEquals(
                "Deep link api/${egg.apiLevel} opened another Activity",
                egg.activity,
                device.awaitResumedActivity(egg.activity),
            )
            assertNoCrash("api/${egg.apiLevel}")
            device.pressBack()
            device.pressBack()
        }
    }

    private fun assertNoCrash(step: String) {
        val log = device.crashLog()
        assertFalse("The app crashed during $step:\n$log", "Process: $PACKAGE_NAME" in log)
    }
}

