internal sealed interface JsonElement {
    class Object(
        private val data: Map<String, JsonElement>
    ) : Map<String, JsonElement> by data, JsonElement

    class Array(
        private val data: List<JsonElement>
    ) : List<JsonElement> by data, JsonElement {
        val stringArray: List<String> = data.mapNotNull { it.stringPrimitive }
    }

    class StringPrimitive(val value: String) : JsonElement

    val stringPrimitive: String? get() = (this as? StringPrimitive)?.value
    val array: Array? get() = this as? Array
}

internal fun getLanguageLocale(supportedLocales: SupportedLocales): SupportedLocale? {
    val currentCache: CachedLocale? = cachedLocale
    val userLanguages: Array<out String> = getUserLanguages()

    if (currentCache != null && currentCache.usedLanguages.contentEquals(userLanguages)) {
        return currentCache.locale?.let(supportedLocales::getForLocale)
    }

    val foundLocale = findMatchingLocale(supportedLocales, userLanguages)
    cachedLocale = CachedLocale(userLanguages, foundLocale?.locale)
    return foundLocale
}

internal fun findMatchingLocale(supportedLocales: SupportedLocales, locale: String?): SupportedLocale? {
    return if (locale == null) {
        getLanguageLocale(supportedLocales)
    } else {
        findMatchingLocale(
            supportedLocales,
            arrayOf(locale)
        )
    }
}

private fun findMatchingLocale(
    supportedLocales: SupportedLocales,
    userLanguages: Array<out String> = getUserLanguages()
): SupportedLocale? {
    return userLanguages
        .asSequence()
        .map { localeString ->
            val parsedLocale = parseBcpLocale(localeString)

            val potentialLanguages =
                supportedLocales.getLocalesForLanguage(parsedLocale.primaryLanguageTag)

            val mostMatchingLocale = potentialLanguages
                .map { potentialLanguage ->
                    potentialLanguage to calculateMatchingScore(
                        parsedLocale,
                        potentialLanguage
                    )
                }
                .filter { (_, score) -> score != -1 }
                .maxByOrNull { (_, score) -> score }
                ?.first

            mostMatchingLocale
        }
        .firstOrNull()
}

