                        override fun onRenderFail(view: View?, errorMsg: String?, errorCode: Int) {
                            listener.onAdRenderFail(adProviderType, adObject)
                        }
                    })

                    adObject.setDislikeCallback(activity, object : TTAdDislike.DislikeInteractionCallback {
