                addLog("开屏广告点了跳过或者倒计时结束， $providerType")
                "onAdDismissed: $providerType".logi(tag)
                actionHome(0)
            }
        })
        //回调中的 providerType 是广告商类型
    }

    /**
     * 展示开屏广告
     */
    private fun showSplashAd() {
        //展示广告并返回是否展示成功
        val showAdIsSuccess = adHelperSplashHybrid.showAd(adContainer)
        //如果没有展示成功就直接跳走
        if (!showAdIsSuccess) {
            actionHome(1000)
        }
    }

