        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_splash_pro)

        btnLoad.setOnClickListener {
            //开始请求开屏广告
            requestSplashAd()
        }

        btnShow.setOnClickListener {
            //展示广告
            showSplashAd()
        }

    }

    /**
     * 请求开屏广告
     */
    private fun requestSplashAd() {

        /**
         * 设置 开屏广告 自定义跳过按钮
         * TogetherAd 提供了两个简单的实例模板，同时只能设置一个,如果设置多个后面的生效
