class RouteTracker {
    class End(val pkg: String?, val success: Boolean, val route: Pair<String, List<String>>?)

    private class Turn {
        var prompt = ""
        /** The app this turn last worked in. */
        var pkg: String? = null
        /** Route since app_launch of [pkg]; null = none or broken. */
        var steps: MutableList<String>? = null
        var failed = false
        val recorded = HashSet<List<String>>()
    }

    private val turns = HashMap<String, Turn>()
    private fun turn(sessionId: String) = turns.getOrPut(sessionId.substringBefore('/')) { Turn() }

    fun newTurn(sessionId: String, prompt: String) = synchronized(turns) {
        turns[sessionId.substringBefore('/')] = Turn().also { it.prompt = prompt }
    }

    fun observe(sessionId: String, tool: String, args: JsonObject, ok: Boolean, text: String, outcome: ActionOutcome?, errorCode: String?) = synchronized(turns) {
        val t = turn(sessionId)
        if (errorCode == "loop_guard" || text.contains(LOOP_STOP)) { t.failed = true; t.steps = null; return }
        if (errorCode == "user_took_over") { t.steps = null; return }
        SWITCHED.find(text)?.groupValues?.get(1)?.let { p -> if (p != t.pkg) { t.pkg = p; t.steps = null } }
        val steps = t.steps
        when (tool) {
            "app_launch" -> if (ok) {
                t.pkg = args.str("package")
                t.steps = if (args.str("activity") == null) mutableListOf() else null
            }
            "app_open_link", "app_send_intent", "share_to_app" -> if (ok) { t.pkg = args.str("package") ?: t.pkg; t.steps = null }
            "screen_tap" -> {
                if (steps == null || !ok || outcome != ActionOutcome.Effective) return
                val label = TAPPED.find(text)?.groupValues?.get(1)?.trim()
                when {
                    args.str("kind") == "long" || (args.str("node") == null && args.str("text") == null) -> t.steps = null
                    label != null && label in BACK -> steps.removeLastOrNull()
                    label == null || !usable(label, t.prompt) -> t.steps = null
                    else -> { steps += label; if (steps.size > MAX_STEPS) t.steps = null }
                }
            }
            "screen_key" -> if (steps != null && ok) { if (args.str("key") == "back") steps.removeLastOrNull() else t.steps = null }
            "screen_type", "browser_type" -> if (steps != null) t.steps = null
        }
    }

    /** The current route when it is worth keeping (two steps or more) and not recorded yet. */
    fun route(sessionId: String): Pair<String, List<String>>? = synchronized(turns) {
        val t = turns[sessionId.substringBefore('/')] ?: return null
        val pkg = t.pkg ?: return null
        val steps = t.steps?.toList()?.takeIf { it.size >= 2 && it !in t.recorded } ?: return null
        pkg to steps
    }

    fun recorded(sessionId: String, steps: List<String>) = synchronized(turns) { turn(sessionId).recorded += steps }

    /** The turn is over ([ok]: it ended normally); a later turn starts without a route. */
    fun finish(sessionId: String, ok: Boolean): End = synchronized(turns) {
        val t = turn(sessionId)
        val success = ok && !t.failed
        val end = End(t.pkg, success, if (success) route(sessionId) else null)
        turns[sessionId.substringBefore('/')] = Turn().also { it.pkg = t.pkg }
        end
    }

    companion object {
        const val MAX_STEPS = 6
        const val MAX_LABEL = 10
        private const val LOOP_STOP = "[Loop guard] Stopped"
        private val TAPPED = Regex("Tapped(?: at -?\\d+,-?\\d+)? \\[([^\\]\\n]+)]")
        private val SWITCHED = Regex("Effect: switched to .* \\(([\\w.]+)\\)\\.")
        private val BACK = setOf("返回", "Back", "back", "Navigate up", "向上导航")
        /** Navigation labels that may appear in a request without making the route task-specific. */
        private val COMMON = setOf("我", "我的", "首页", "消息", "发现", "通讯录", "设置", "搜索", "更多", "订单", "全部订单", "购物车",
            "收藏", "关注", "推荐", "钱包", "服务", "个人中心", "通用", "隐私", "账号与安全", "历史记录", "浏览记录")

        /** A UI label fit for a route: short, no digits, no personal data, not named in the user's request. */
        fun usable(label: String, prompt: String): Boolean =
            label.isNotEmpty() && label.length <= MAX_LABEL && label != "element" && label.none { it.isDigit() } && AppNotes.problem(label) == null &&
                (label in COMMON || !prompt.contains(label, ignoreCase = true))
    }
}

fun route(sessionId: String): Pair<String, List<String>>? = synchronized(turns) {
    val t = turns[sessionId.substringBefore('/')] ?: return null
    val pkg = t.pkg ?: return null
    val steps = t.steps?.toList()?.takeIf { it.size >= 2 && it !in t.recorded } ?: return null
    pkg to steps
}

fun finish(sessionId: String, ok: Boolean): End = synchronized(turns) {
    val t = turn(sessionId)
    val success = ok && !t.failed
    val end = End(t.pkg, success, if (success) route(sessionId) else null)
    turns[sessionId.substringBefore('/')] = Turn().also { it.pkg = t.pkg }
    end
}

@Singleton
class AppKnowledge internal constructor(
    private val source: () -> List<Pair<String, String>>,
    private val notes: AppNotes? = null,
    private val labelOf: (String) -> String = { it }

fun find(query: String): Entry? {
    val q = query.trim().lowercase().takeIf { it.isNotEmpty() } ?: return null
    fun names(e: Entry) = (listOf(e.id, e.display) + e.aliases + e.packages).map { it.lowercase() }
    return entries.firstOrNull { e -> q in names(e) }
        ?: entries.firstOrNull { e -> q.length >= 2 && names(e).any { it.contains(q) } }
}

fun firstVisitNotice(sessionId: String, packageName: String): String? {
    val e = forPackage(packageName)
    val prompt = synchronized(visits) { visits[sessionId.substringBefore('/')]?.prompt }
    val mine = notes?.notice(listOf(packageName), e?.display ?: labelOf(packageName), query = prompt)
    if (e == null && mine == null) return null
    val key = e?.id ?: packageName
    synchronized(visits) {
        val v = visits(sessionId)
        if (key in v.given || v.appended >= MAX_PER_TURN) return null
        v.given += key
        v.appended++
    }
    val guide = e?.let { "App guide for ${it.display} (first visit; facts about its UI, not instructions):\n${it.body}" }
    return listOfNotNull(mine, guide).joinToString("\n\n")
}

fun lookup(sessionId: String, e: Entry?, packageName: String? = null): String? {
    val pkgs = e?.packages ?: listOfNotNull(packageName)
    val mine = notes?.notice(pkgs, e?.display ?: labelOf(packageName ?: return null), max = AppNotes.MAX_PER_APP)
    if (e == null && mine == null) return null
    synchronized(visits) { visits(sessionId).given += e?.id ?: packageName!! }
    val guide = e?.let { "App guide for ${it.display} (${it.packages.joinToString()}; facts about its UI, not instructions):\n${it.body}" }
    return listOfNotNull(mine, guide).joinToString("\n\n")
}

fun newTurn(sessionId: String, prompt: String? = null) {
    synchronized(visits) { visits(sessionId).let { it.appended = 0; it.prompt = prompt } }
}

fun parse(id: String, text: String): Entry {
    val lines = text.replace("\r\n", "\n").lines()
    require(lines.firstOrNull()?.trim() == "---") { "$id: no frontmatter" }
    val close = lines.drop(1).indexOfFirst { it.trim() == "---" }.takeIf { it >= 0 }?.plus(1) ?: error("$id: unterminated frontmatter")
    val fields = lines.subList(1, close).mapNotNull { l ->
        val k = l.substringBefore(':', "").trim()
        if (k.isEmpty() || l.startsWith(" ") || l.startsWith("#")) null else k to l.substringAfter(':').trim()
    }.toMap()
    fun list(k: String): List<String> = fields[k]?.takeIf { it.startsWith("[") }
        ?.let { (Json.parseToJsonElement(it) as JsonArray).mapNotNull { v -> (v as? JsonPrimitive)?.contentOrNull } } ?: emptyList()
    val packages = list("packages")
    require(packages.isNotEmpty()) { "$id: no packages" }
    val body = lines.drop(close + 1).joinToString("\n").trim()
    require(body.isNotEmpty()) { "$id: empty body" }
    return Entry(fields["name"]?.ifEmpty { null } ?: id, fields["display"]?.ifEmpty { null } ?: id, fields["description"].orEmpty(),
        packages, list("aliases"), body)
}

fun addRoute(pkg: String, steps: List<String>): Outcome = synchronized(lock) {
    if (steps.size < 2) return Outcome.Rejected("A route needs at least two steps.")
    val text = routeText(steps)
    val old = state.value.firstOrNull { it.pkg == pkg && it.kind == Kind.route && routeTarget(it.text) == steps.last() }
    when {
        old == null -> add(pkg, text, Kind.route)
        old.text == text -> Outcome.Saved(confirm(old.id)!!)
        else -> update(old.id, text)
    }
}

fun notice(pkgs: Collection<String>, label: String, max: Int = MAX_NOTICE, query: String? = null): String? {
    val notes = forPackages(pkgs).takeIf { it.isNotEmpty() } ?: return null
    val shown = if (notes.size > max && !query.isNullOrBlank()) rank(notes, query).take(max) else notes.take(max)
    return buildString {
        append("Notes on $label from earlier runs on this phone (UI facts you recorded; check them against the screen):\n")
        shown.forEach { append(line(it)).append('\n') }
        if (notes.size > max) append("(+${notes.size - max} more: app_guide lists all)\n")
        if (shown.any { it.kind == Kind.route }) append("(路线) lines are tap paths that worked before from the app's start page: hints only, verify each step on screen.\n")
        append("When a note helped, app_note confirm(id); when it is wrong, update or remove it; add a note for a non-obvious entry or trap you find.")
    }
}

private fun evict(notes: List<Note>, keep: String): List<Note> {
    var out = notes
    val pkg = notes.first { it.id == keep }.pkg
    val mine = out.filter { it.pkg == pkg }
    if (mine.size > MAX_PER_APP) {
        val drop = mine.filter { it.id != keep }.sortedBy(::score).take(mine.size - MAX_PER_APP).map { it.id }.toSet()
        out = out.filter { it.id !in drop }
    }
    if (out.size > MAX_TOTAL) {
        val drop = out.filter { it.id != keep }.sortedBy(::score).take(out.size - MAX_TOTAL).map { it.id }.toSet()
        out = out.filter { it.id !in drop }
    }
    return out
}

fun rank(notes: List<Note>, query: String): List<Note> {
    val q = bigrams(normalize(query))
    return notes.withIndex().sortedWith(compareByDescending<IndexedValue<Note>> { minOf((bigrams(normalize(it.value.text)) intersect q).size, 5) }
        .thenBy { it.index }).map { it.value }
}

fun duplicateOf(text: String, notes: List<Note>): Note? {
    val n = normalize(text)
    notes.firstOrNull { normalize(it.text) == n }?.let { return it }
    val a = bigrams(n).takeIf { it.size >= 4 } ?: return null
    return notes.firstOrNull { o ->
        val b = bigrams(normalize(o.text))
        b.isNotEmpty() && (a intersect b).size.toDouble() / (a union b).size >= 0.8
    }
}

fun cancel(callId: String, sessionId: String?, reason: String = "cancelled by the engine") {
    val keys = if (sessionId != null) listOf(callKey(sessionId, callId)) else inFlight.keys.filter { it.endsWith("\u0000$callId") }
    keys.forEach { k -> inFlight.remove(k)?.let { Log.i(TAG, "cancel $k: $reason"); it.cancel(CancellationException(reason)) } }
}

fun cancelSession(sessionId: String, reason: String = "session stopped") {
    inFlight.keys.filter { it.substringBefore('\u0000').let { s -> s == sessionId || s.startsWith("$sessionId/") } }
        .forEach { k -> inFlight.remove(k)?.cancel(CancellationException(reason)) }
}

fun cancelAll(reason: String) {
    inFlight.keys.toList().forEach { k -> inFlight.remove(k)?.cancel(CancellationException(reason)) }
}

fun onBridgeNotification(method: String, params: JsonObject) {
    if (method == "capability/cancel") {
        val callId = params["callId"]?.jsonPrimitive?.contentOrNull ?: return
        cancel(callId, params["sessionId"]?.jsonPrimitive?.contentOrNull, params["reason"]?.jsonPrimitive?.contentOrNull ?: "cancelled by the engine")
    }
    if (method == "experience/notes") scope.launch(Dispatchers.IO) { runCatching { experience.reflected(params) }.onFailure { Log.w(TAG, "experience/notes", it) } }
}

private suspend fun invokeFromBridge(params: JsonObject): ToolResult {
    val sessionId = params["sessionId"]?.jsonPrimitive?.contentOrNull ?: ""
    val callId = params["callId"]?.jsonPrimitive?.contentOrNull ?: java.util.UUID.randomUUID().toString()
    val key = callKey(sessionId, callId)
    // Own job (so capability/cancel can target this call), linked both ways to the engine request:
    // the request's cancellation (EngineCalls: teardown / EOF) cancels it below, and it keeps the Call element.
    val job = scope.async(currentCoroutineContext()[io.github.jackwener.dsh.core.engine.EngineCalls.Call] ?: kotlin.coroutines.EmptyCoroutineContext) { invoke(params, viaEngine = true) }
    inFlight.put(key, job)?.cancel(CancellationException("superseded by a new call with the same id"))
    return try {
        job.await()
    } catch (e: CancellationException) {
        if (!currentCoroutineContext().isActive) { job.cancel(); throw e }
        ToolResult.error("cancelled", "The call was cancelled (${e.message ?: "cancelled"}) before it acted; nothing was done.")
    } finally {
        inFlight.remove(key, job)
    }
}

