object OutwardAction {
    private val WORDS = listOf("发送", "提交", "发布", "发表", "评论", "打招呼", "投递", "关注", "回复", "立即沟通", "send", "submit", "post", "reply", "comment", "follow")
    private val NOT = Regex("^(已|取消|查看)|验证码")
    private const val MAX_CHARS = 10

    fun matches(label: String?): Boolean {
        val l = label?.trim()?.lowercase()?.takeIf { it.isNotEmpty() && it.length <= MAX_CHARS } ?: return false
        if (NOT.containsMatchIn(l)) return false
        return WORDS.any { w -> if (w[0].code < 0x80) l == w || l.startsWith("$w ") || l.endsWith(" $w") else w in l }
    }
}

@Singleton
class ScreenOcr @Inject constructor() {
    private val recognizer by lazy { TextRecognition.getClient(ChineseTextRecognizerOptions.Builder().build()) }

    /** Lines top to bottom, then left to right. [bitmap] is in screen pixels. */
    suspend fun read(bitmap: Bitmap): List<OcrLine> {
        val image = InputImage.fromBitmap(bitmap, 0)
        val result = suspendCancellableCoroutine { cont ->
            recognizer.process(image)
                .addOnSuccessListener { if (cont.isActive) cont.resume(it) }
                .addOnFailureListener { if (cont.isActive) cont.resumeWithException(it) }
        }
        return result.textBlocks.flatMap { it.lines }.mapNotNull { l ->
            val box = l.boundingBox ?: return@mapNotNull null
            l.text.trim().takeIf { it.isNotEmpty() }?.let { OcrLine(it, box.centerX(), box.centerY()) }
        }.sortedWith(compareBy({ it.y / ROW_PX }, { it.x }))
    }

    companion object {
        /** Lines whose centres are this close vertically count as one row when sorting. */
        private const val ROW_PX = 24

        /** Fewer readable elements than this: the tree is not enough, recognize the screenshot too. */
        const val SPARSE = 4

        fun render(lines: List<OcrLine>): String = lines.withIndex().joinToString("") { (i, l) -> "[t${i + 1}] \"${l.text}\" @${l.x},${l.y}\n" }
    }
}

suspend fun read(bitmap: Bitmap): List<OcrLine> {
    val image = InputImage.fromBitmap(bitmap, 0)
    val result = suspendCancellableCoroutine { cont ->
        recognizer.process(image)
            .addOnSuccessListener { if (cont.isActive) cont.resume(it) }
            .addOnFailureListener { if (cont.isActive) cont.resumeWithException(it) }
    }
    return result.textBlocks.flatMap { it.lines }.mapNotNull { l ->
        val box = l.boundingBox ?: return@mapNotNull null
        l.text.trim().takeIf { it.isNotEmpty() }?.let { OcrLine(it, box.centerX(), box.centerY()) }
    }.sortedWith(compareBy({ it.y / ROW_PX }, { it.x }))
}

enum class ShellUse {
    None,
    /** Uses Shizuku when ready, otherwise a non-shell path (system panel, intent, accessibility). */
    Fallback,
    /** Only works through Shizuku. */
    Required,
}

@Singleton
class ShellGate @Inject constructor(val shell: ShizukuShell, private val sessions: Lazy<SessionStore>) {
    val access: ShellAccess get() = shell.access

    /**
     * True when the shell can be used now (possibly after the user set Shizuku up from the card).
     * [optional] callers have a fallback, so they only ask a user who already has Shizuku installed
     * (e.g. it stopped after a reboot); someone who never installed it is not interrupted.
     * A 不用了 is remembered for the session: later calls go straight to their fallback.
     */
    suspend fun acquire(call: CallContext, toolName: String, optional: Boolean): Boolean {
        val s = access.refresh()
        if (s.ready) return true
        if (call.unattended || call.sessionId.isEmpty() || access.isDeclined(call.sessionId)) return false
        if (optional && (s == ShellState.NotInstalled || s is ShellState.Unsupported)) return false
        val answered = call.waitFor("set up Shizuku") { coroutineScope {
            val ready = async { access.state.first { it.ready }; true }
            val asked = async { sessions.get().requestPermission(call.sessionId, toolName, SHIZUKU_WHAT) }
            select { ready.onAwait { it }; asked.onAwait { it } }.also { ready.cancel(); asked.cancel() }
        } }
        if (access.refresh().ready) return true
        if (!answered) access.decline(call.sessionId)
        return false
    }

    /** Model-facing result for a shell-only step that cannot run. */
    fun unavailable(call: CallContext): ToolResult {
        val reason = access.state.value.reason
        return ToolResult.error("shizuku_unavailable", when {
            call.unattended -> "This step needs Shizuku (shell access), but $reason. Automations cannot ask the user to set it up; skip this step or report it."
            else -> "This needs Shizuku (shell access), but $reason and the user chose not to set it up now. Do not call Shizuku-only tools again " +
                "in this session; do it another way (system intents, settings panels, screen tools) or tell the user it can be enabled in DSH → Settings → Phone."
        })
    }

    companion object {
        /** Appended to model-facing descriptions. Never includes live state (see CapabilityHub.listed). */
        fun staticNote(use: ShellUse, fallback: String?): String = when (use) {
            ShellUse.None -> ""
            ShellUse.Fallback -> " [Uses Shizuku (shell access) when it is ready; otherwise it will ${fallback ?: "use a non-shell fallback"}. The result says which path ran.]"
            ShellUse.Required -> " [Needs Shizuku (shell access). If it is not ready, the call shows the user a Shizuku setup card; if it returns shizuku_unavailable, don't call Shizuku-only tools again this session.]"
        }
    }
}

fun unavailable(call: CallContext): ToolResult {
    val reason = access.state.value.reason
    return ToolResult.error("shizuku_unavailable", when {
        call.unattended -> "This step needs Shizuku (shell access), but $reason. Automations cannot ask the user to set it up; skip this step or report it."
        else -> "This needs Shizuku (shell access), but $reason and the user chose not to set it up now. Do not call Shizuku-only tools again " +
            "in this session; do it another way (system intents, settings panels, screen tools) or tell the user it can be enabled in DSH → Settings → Phone."
    })
}

fun staticNote(use: ShellUse, fallback: String?): String = when (use) {
    ShellUse.None -> ""
    ShellUse.Fallback -> " [Uses Shizuku (shell access) when it is ready; otherwise it will ${fallback ?: "use a non-shell fallback"}. The result says which path ran.]"
    ShellUse.Required -> " [Needs Shizuku (shell access). If it is not ready, the call shows the user a Shizuku setup card; if it returns shizuku_unavailable, don't call Shizuku-only tools again this session.]"
}

object ShotStore {
    private fun dir(context: Context, sessionId: String) = File(context.filesDir, "shots/${sessionId.replace('/', '_')}")

    fun save(context: Context, sessionId: String, callId: String, images: List<Content.Image>) {
        if (sessionId.isEmpty() || callId.isEmpty() || images.isEmpty()) return
        val d = dir(context, sessionId).apply { mkdirs() }
        images.forEachIndexed { i, img ->
            val ext = img.mimeType.substringAfter('/').ifBlank { "png" }
            runCatching { File(d, "${safe(callId)}_$i.$ext").writeBytes(Base64.decode(img.base64, Base64.DEFAULT)) }
        }
    }

    fun files(context: Context, sessionId: String, callId: String): List<File> {
        val prefix = safe(callId) + "_"
        return dir(context, sessionId).listFiles { f -> f.name.startsWith(prefix) }?.sortedBy { it.name } ?: emptyList()
    }

    fun deleteSession(context: Context, sessionId: String) { dir(context, sessionId).deleteRecursively() }

    private fun safe(s: String) = s.replace(Regex("[^A-Za-z0-9_.-]"), "_")
}

suspend fun type(svc: DshAccessibilityService, target: AccessibilityNodeInfo?, text: String, append: Boolean, displayId: Int = Display.DEFAULT_DISPLAY): Typed? {
    // The input connection, the keyboard and `ime set` belong to the user's focused field: on the
    // agent screen only paths bound to the target node (or to that display) are safe.
    val main = displayId == Display.DEFAULT_DISPLAY
    val before = target?.let(::shownText)
    val full = if (append) (before.orEmpty() + text) else text
    fun done(method: String) = Typed(method, readBack(target))
    fun changed(): Boolean {
        if (target == null || target.isPassword) return false
        target.refresh()
        return shownText(target) != before
    }
    if (target != null && target.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, Bundle().apply {
            putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE, full)
        })) {
        if (verify(target, text)) return done("set_text")
        if (changed()) return done("set_text (partial: the field reformatted the text; check it)")
    }

    target?.let { focus(it) }
    if (main && svc.commitViaA11yInput(text, replace = !append)) {
        if (verify(target, text, trustWithoutNode = true)) return done("a11y_input" + unverified(target))
        if (changed()) return done("a11y_input (partial: the field reformatted the text; check it)")
    }
    if (main && DshInputMethodService.isCurrent(context) && DshInputMethodService.instance?.commit(text, replace = !append) == true) {
        if (verify(target, text, trustWithoutNode = true)) return done("dsh_ime" + unverified(target))
        if (changed()) return done("dsh_ime (partial: the field reformatted the text; check it)")
    }

    if (shizuku.available) {
        if (text.all { it.code in 0x20..0x7e }) {
            if (!append && target != null) clear(target)
            if (shizuku.exec((if (main) "input text " else "input -d $displayId text ") + shellQuote(text.replace(" ", "%s"))).code == 0) {
                if (verify(target, text, trustWithoutNode = true)) return done("shizuku_input" + unverified(target))
                if (changed()) return done("shizuku_input (partial: the field reformatted the text; check it)")
            }
        } else if (main && viaImeSwitch(text, !append)) {
            if (verify(target, text, trustWithoutNode = true)) return done("shizuku_ime" + unverified(target))
            if (changed()) return done("shizuku_ime (partial: the field reformatted the text; check it)")
        }
    }

    if (target != null) {
        val cm = context.getSystemService(ClipboardManager::class.java)
        val saved = runCatching { cm.primaryClip }.getOrNull()
        cm.setPrimaryClip(ClipData.newPlainText("dsh", text))
        if (!append) clear(target)
        val ok = target.performAction(AccessibilityNodeInfo.ACTION_PASTE) && (verify(target, text) || changed())
        // Give the user's clipboard back (paste is synchronous for the target app by now).
        runCatching { if (saved != null) cm.setPrimaryClip(saved) else if (android.os.Build.VERSION.SDK_INT >= 28) cm.clearPrimaryClip() }
        if (ok) return done("paste")
    }
    return null
}

private suspend fun viaImeSwitch(text: String, replace: Boolean): Boolean {
    val ours = DshInputMethodService.id(context)
    val previous = DshInputMethodService.currentId(context)
    if (shizuku.exec("ime enable $ours && ime set $ours").code != 0) return false
    try {
        repeat(20) {
            DshInputMethodService.instance?.let { if (it.commit(text, replace)) return true }
            delay(100)
        }
        return false
    } finally {
        if (previous != null && previous != ours) shizuku.exec("ime set ${shellQuote(previous)}")
    }
}

private suspend fun verify(n: AccessibilityNodeInfo?, expected: String, trustWithoutNode: Boolean = false): Boolean {
    if (n == null) return trustWithoutNode
    if (n.isPassword) return true
    // Editors update their text asynchronously; poll for ~600 ms before calling it a failure.
    repeat(4) {
        delay(150)
        n.refresh()
        val now = n.text?.toString()
        if (now != null && (now.contains(expected) || now.replace(Regex("\\s"), "").contains(expected.replace(Regex("\\s"), "")))) return true
    }
    return false
}

