fun hasAllFilesAccess(context: Context): Boolean =
    if (android.os.Build.VERSION.SDK_INT >= 30) Environment.isExternalStorageManager()
    else context.checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE) == android.content.pm.PackageManager.PERMISSION_GRANTED

object Images {
    const val MAX = 1280
    const val MIME = "image/jpeg"

    class Encoded(val bytes: ByteArray, val width: Int, val height: Int)

    /**
     * Decodes any format the platform supports (JPEG, PNG, WebP, GIF, HEIC/HEIF, AVIF on newer
     * Android), applies EXIF rotation, and subsamples while decoding so huge camera photos are cheap.
     * Returns null when the file cannot be decoded (SVG, corrupt, unsupported).
     */
    fun downscale(file: File): Encoded? = runCatching {
        val bmp = ImageDecoder.decodeBitmap(ImageDecoder.createSource(file)) { decoder, info, _ ->
            val w = info.size.width; val h = info.size.height
            val scale = MAX.toFloat() / maxOf(w, h)
            if (scale < 1f) decoder.setTargetSize(maxOf(1, (w * scale).toInt()), maxOf(1, (h * scale).toInt()))
            decoder.allocator = ImageDecoder.ALLOCATOR_SOFTWARE
            decoder.isMutableRequired = false
        }
        encode(bmp)
    }.getOrNull()

    fun encode(bitmap: Bitmap): Encoded {
        val scale = MAX.toFloat() / maxOf(bitmap.width, bitmap.height)
        val b = if (scale < 1f) Bitmap.createScaledBitmap(bitmap, maxOf(1, (bitmap.width * scale).toInt()), maxOf(1, (bitmap.height * scale).toInt()), true) else bitmap
        val bytes = ByteArrayOutputStream().also { b.compress(Bitmap.CompressFormat.JPEG, 80, it) }.toByteArray()
        return Encoded(bytes, b.width, b.height)
    }
}

fun downscale(file: File): Encoded? = runCatching {
    val bmp = ImageDecoder.decodeBitmap(ImageDecoder.createSource(file)) { decoder, info, _ ->
        val w = info.size.width; val h = info.size.height
        val scale = MAX.toFloat() / maxOf(w, h)
        if (scale < 1f) decoder.setTargetSize(maxOf(1, (w * scale).toInt()), maxOf(1, (h * scale).toInt()))
        decoder.allocator = ImageDecoder.ALLOCATOR_SOFTWARE
        decoder.isMutableRequired = false
    }
    encode(bmp)
}

private fun resolve(query: String): String? {
    val q = query.trim().takeIf { it.isNotEmpty() } ?: return null
    if (installed(q)) return q
    knowledge.find(q)?.let { e -> e.packages.firstOrNull(::installed)?.let { return it } }
    val apps = pm.queryIntentActivities(Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER), 0)
        .map { it.activityInfo.applicationInfo }.distinctBy { it.packageName }
        .map { pm.getApplicationLabel(it).toString() to it.packageName }
    return apps.firstOrNull { it.first.equals(q, true) }?.second
        ?: apps.filter { q.length >= 2 && it.first.contains(q, true) }.minByOrNull { it.first.length }?.second
}

private suspend fun find(key: String): StatusBarNotification {
    val sbn = listener().activeNotifications.firstOrNull { it.key == key }
        ?: throw InvalidArgsException("No current notification with key $key (it may have been dismissed); call notification_list again")
    if (sbn.packageName in blocked()) throw InvalidArgsException("The user blocked reading ${sbn.packageName} notifications (DSH settings → Notifications)")
    return sbn
}

private fun describe(sbn: StatusBarNotification): String {
    val n = sbn.notification
    val e = n.extras
    val title = e.getCharSequence(Notification.EXTRA_TITLE) ?: e.getCharSequence(Notification.EXTRA_CONVERSATION_TITLE) ?: ""
    val messages = runCatching { NotificationCompat.MessagingStyle.extractMessagingStyleFromNotification(n)?.messages }.getOrNull()
        ?.takeLast(5)?.joinToString(" | ") { m -> "${m.person?.name ?: ""}${if (m.person?.name != null) ": " else ""}${m.text}" }
    val text = messages?.takeIf { it.isNotBlank() }
        ?: (e.getCharSequence(Notification.EXTRA_BIG_TEXT) ?: e.getCharSequence(Notification.EXTRA_TEXT) ?: "").toString()
    val actions = n.actions.orEmpty().mapNotNull { a ->
        a.title?.toString()?.let { t -> if (a.remoteInputs?.isNotEmpty() == true) "$t(reply)" else t }
    }
    return "[${sbn.packageName}] $title: ${text.take(400)}" +
        (if (actions.isNotEmpty()) "  actions=${actions.joinToString("/")}" else "") +
        (if (!sbn.isClearable) "  (ongoing)" else "")
}

internal object PrivateStorage {
    /** A storage volume root as the app may spell it, then Android/data|obb (shared storage is case-insensitive). */
    private val DIR = Regex(
        "^(?:/storage/emulated/\\d+|/storage/self/primary|/storage/[0-9a-f]{4}-[0-9a-f]{4}|/sdcard|/mnt/sdcard|/mnt/user/\\d+/primary)" +
            "/android/(?:data|obb)(/.*)?$",
        RegexOption.IGNORE_CASE,
    )

    /** [path] (canonical) is Android/data or Android/obb or inside them. */
    fun isPrivate(path: String): Boolean = DIR.matches(path.trimEnd('/').ifEmpty { "/" })

    /** Android/data or Android/obb itself: never deleted or moved as a whole. */
    fun isScopeRoot(path: String): Boolean = DIR.matchEntire(path.trimEnd('/'))?.groupValues?.get(1).isNullOrEmpty() && isPrivate(path)

    /** Whether [path] must go through the shell user on Android [sdk]. */
    fun needsShell(path: String, sdk: Int): Boolean = sdk >= 30 && isPrivate(path)

    const val NEEDS_SHIZUKU = "Android/data and Android/obb are closed to apps on Android 11 and newer; DSH can reach them only through Shizuku " +
        "(shell access), and %s. Ask the user to turn Shizuku on (访问 Android/data 需要 Shizuku：去 设置 → 手机权限 → Shizuku 打开; " +
        "DSH → Settings → Phone permissions → Shizuku), then try again."

    fun needsShizuku(reason: String) = NEEDS_SHIZUKU.format(reason)
}

private class View {
    val ids = StableIds()
    /** The last read sent to the model: the base of the next diff. */
    @Volatile var shown: Frame? = null
    @Volatile var reads = 0
    @Volatile var ocr: List<OcrLine> = emptyList()
    @Volatile var lastPackage: String? = null
}

