data class EngineRoute(val provider: String, val model: String, val effort: String) {
    val isDeepSeek: Boolean get() = provider.startsWith("deepseek-")
}

suspend fun sessionRoute(m: SessionModel): EngineRoute {
    val st = settings.current()
    return SessionModels.route(m, st, engineReasoning ?: st.reasoningCatalog, deepSeekRoute(secrets.read() != null))
}

private fun providerKeys(st: io.github.jackwener.dsh.core.data.Settings): Map<String, String> {
    val enabled = st.providers.filter { it.enabled }
    val keys = enabled.filter { it.hasKey }.mapNotNull { p -> secrets.read(p.secretName)?.let { p.keyEnv to it } }
    val headers = enabled.flatMap { p -> p.headers.filter { it.secret }.mapNotNull { h -> secrets.read(p.headerSecretName(h.name))?.let { p.headerEnv(h.name) to it } } }
    return (keys + headers).toMap() + io.github.jackwener.dsh.core.extensions.ExtensionsEngineInputs.env(st.pluginRegistry, st.pluginRegistryCustom, st.mcpServers, secrets::read)
}

private fun profileFingerprint(st: io.github.jackwener.dsh.core.data.Settings, hasKey: Boolean): String {
    val md = java.security.MessageDigest.getInstance("SHA-256")
    md.update(profilePatch(st, hasKey).toByteArray())
    providerKeys(st).toSortedMap().forEach { (k, v) -> md.update("$k=$v\n".toByteArray()) }
    return md.digest().joinToString("") { "%02x".format(it) }
}

suspend fun sdk(route: EngineRoute?): JsonRpcPeer = mutex.withLock {
    val st = settings.current()
    val hasKey = secrets.read() != null
    val peer = sdk?.takeIf { _state.value == EngineState.Ready }?.let { peer ->
        val want = wantedRoute(st, hasKey)
        when {
            sessions.get().hasEngineRuns() -> peer
            // The device time zone changed since start: a new process picks it up (when idle, like a route change).
            TimeZone.getDefault().id != startedTz -> { Log.i(TAG, "time zone changed: restarting engine"); shutdownLocked(); null }
            // The app language changed (设置 → 语言, or the system's per-app language): same, when idle.
            Locale.getDefault().toLanguageTag() != startedLocale -> { Log.i(TAG, "language changed: restarting engine"); shutdownLocked(); null }
            // Providers / keys / web search changed: only a new process reads them.
            profileFingerprint(st, hasKey) != activeFingerprint -> { Log.i(TAG, "model providers changed: restarting engine"); shutdownLocked(); null }
            want == activeRoute -> peer
            // This process already failed that route with the same configuration: report it (below) without churning.
            want == failedRoute?.first -> peer
            !sessionsOpened -> runCatching { initialize(peer, want); peer }.getOrElse {
                Log.w(TAG, "re-initialize failed; restarting", it); shutdownLocked(); null
            }
            else -> { Log.i(TAG, "route changed: restarting engine"); shutdownLocked(); null }
        }
    } ?: startLocked(st, hasKey)
    val want = wantedRoute(st, hasKey)
    val deepSeek = route?.isDeepSeek ?: st.choice.isDeepSeek
    // The default route failed `initialize` (the engine runs on DeepSeek): prompts that need it say why.
    val unavailable = if (route == null) want != activeRoute && !deepSeek else route == failedRoute?.first
    if (unavailable && !sessions.get().hasEngineRuns()) {
        val target = route ?: want
        throw RouteUnavailableException("${st.providers.firstOrNull { it.id == target.provider }?.name ?: target.provider} / ${target.model}: ${failedRoute?.second ?: "unavailable"}")
    }
    if (deepSeek && !hasKey && !account.get().signedIn) throw NoCredentialsException()
    peer
}

val unavailable = if (route == null) want != activeRoute && !deepSeek else route == failedRoute?.first
if (unavailable && !sessions.get().hasEngineRuns()) {
    val target = route ?: want
    throw RouteUnavailableException("${st.providers.firstOrNull { it.id == target.provider }?.name ?: target.provider} / ${target.model}: ${failedRoute?.second ?: "unavailable"}")
}

suspend fun control(): JsonRpcPeer = mutex.withLock {
    sdk?.takeIf { _state.value == EngineState.Ready } ?: startLocked(settings.current(), secrets.read() != null)
}

private suspend fun refreshReasoning(peer: JsonRpcPeer, st: io.github.jackwener.dsh.core.data.Settings) {
    val routes = st.providers.filter { it.enabled && it.models.isNotEmpty() && it.baseUrl.isNotBlank() }.flatMap { p -> p.models.map { p to it } }
    if (routes.isEmpty()) return
    val result = runCatching {
        withTimeout(30_000) {
            peer.request("android/models/reasoning", buildJsonObject {
                putJsonArray("models") { routes.forEach { (p, m) -> addJsonObject { put("provider", p.id); put("model", m) } } }
            })
        }
    }.onFailure { Log.w(TAG, "android/models/reasoning unavailable", it) }.getOrNull() ?: return
    val catalog = ReasoningLevels.parse(result) { provider, model -> st.providers.firstOrNull { it.id == provider }?.limits?.get(model)?.reasoning }
    engineReasoning = catalog
    runCatching { settings.setReasoningCatalog(catalog) }.onFailure { Log.w(TAG, "could not store reasoning levels", it) }
}

fun scheduleIdleShutdown() {
    idleJob?.cancel()
    idleJob = scope.launch {
        delay(IDLE_MS)
        if (!EngineKeepAlive.mayStopWhenIdle(settings.current().engineKeepAlive, sessions.get().hasRunning(), account.get().busy)) return@launch
        stop()
    }
}

fun keepAlive(restored: Boolean = false) {
    scope.launch {
        val s = _state.value
        if (s != EngineState.Stopped && s !is EngineState.Failed) return@launch
        if (!settings.current().engineKeepAlive || restarts.open) {
            // Under the lock: a start in progress must not lose its service.
            if (restored) mutex.withLock { if (_state.value == EngineState.Stopped && connection == null) context.stopService(Intent(context, EngineService::class.java)) }
            return@launch
        }
        Log.i(TAG, "keep-alive: starting the engine")
        runCatching { control() }.onFailure { Log.w(TAG, "keep-alive start failed", it) }
    }
}

suspend fun setKeepAlive(on: Boolean) {
    settings.setEngineKeepAlive(on)
    if (on) { idleJob?.cancel(); keepAlive() } else if (_state.value == EngineState.Ready) scheduleIdleShutdown()
}

private suspend fun shutdownLocked() {
    val dying = death
    expectedExit = generation
    runCatching { withTimeout(3_000) { sdk?.request("shutdown") } }
    teardown(generation)
    if (dying != null && withTimeoutOrNull(5_000) { dying.await() } == null) killEngineProcess()
}

private fun killEngineProcess() {
    val am = context.getSystemService(android.app.ActivityManager::class.java)
    am.runningAppProcesses?.filter { it.processName == context.packageName + ":engine" }?.forEach {
        Log.w(TAG, "killing engine process ${it.pid}")
        android.os.Process.killProcess(it.pid)
    }
}

private fun onEngineGone(gen: Int) {
    val peer: JsonRpcPeer
    val retryInMs: Long?
    synchronized(this) {
        peer = sdk ?: return
        if (gen != generation || gen == expectedExit) return
        Log.w(TAG, "engine gen $gen channel closed")
        teardown(gen)
        retryInMs = restarts.recordFailure()
    }
    scope.launch {
        // A binder-death signal can beat the pipe's EOF: let the dead channel's buffered tail
        // (events the process wrote before it died) reach SessionStore before the loss does.
        withTimeoutOrNull(2_000) { peer.closed.await() }
        sessions.get().onEngineLost(gen, retryInMs)
        // 引擎常驻: come back after the same backoff even when no conversation was running.
        if (retryInMs != null) scope.launch { delay(retryInMs); keepAlive() }
        delay(2_000) // let the system record the exit reason
        EngineDiagnostics.collectExitInfo(context)
    }
}

    context.startForegroundService(Intent(intent).putExtra(EngineKeepAlive.EXTRA_KEEP_ALIVE, keepAlive))
} catch (e: IllegalStateException) {
    // ForegroundServiceStartNotAllowedException (API 31+) extends IllegalStateException; older
    // releases throw a plain IllegalStateException for background starts.
    death = null
    throw EngineBackgroundStartException(e)
}

private fun writeProfilePatch(text: String) {
    val dir = File(context.filesDir, "dsh-home/android").apply { mkdirs() }
    val f = File(dir, "app-layer.patch.yml")
    if (f.exists() && f.readText() == text) return
    val tmp = File(dir, "app-layer.patch.yml.tmp")
    tmp.writeText(text)
    check(tmp.renameTo(f)) { "could not write ${f.path}" }
}

fun env(proxy: Proxy?): Map<String, String> {
    if (proxy == null || proxy.host.isBlank() || proxy.port !in 1..65535) return emptyMap()
    val host = proxy.host.trim().let { if (':' in it && !it.startsWith("[")) "[$it]" else it }
    val url = "http://$host:${proxy.port}"
    val exclusions = proxy.exclusions.flatMap { it.split(',', '|', ' ') }.map { it.trim() }.filter { it.isNotEmpty() }
    val noProxy = (exclusions + LOOPBACK.filter { l -> exclusions.none { it.equals(l, ignoreCase = true) } }).joinToString(",")
    // Both casings: undici reads the lowercase name first, so a stale lowercase value must not win.
    return linkedMapOf(
        "HTTP_PROXY" to url, "HTTPS_PROXY" to url, "NO_PROXY" to noProxy,
        "http_proxy" to url, "https_proxy" to url, "no_proxy" to noProxy,
        // Ignored by the engine itself under AT_SECURE (hence --use-env-proxy in argv); for Node children.
        "NODE_USE_ENV_PROXY" to "1",
    )
}

fun nodeArgv(engineDir: File, env: Bundle): List<String> {
    val options = mergeNodeOptions(env.getString("NODE_OPTIONS"), RUNTIME_NODE_OPTIONS).split(' ').filter { it.isNotBlank() }
    val preload = File(engineDir, PRELOAD).takeIf { it.exists() }?.let { listOf("--require", it.path) } ?: emptyList()
    return NODE_ARGV + options + (if (proxyApplied) listOf("--use-env-proxy") else emptyList()) + preload
}

private fun systemProxy(context: Context): EngineProxy.Proxy? = runCatching {
    val info = context.getSystemService(ConnectivityManager::class.java)?.defaultProxy
    if (info != null && info.pacFileUrl != null && info.pacFileUrl != Uri.EMPTY) {
        Log.i(TAG, "PAC proxy configured; not applied to the engine (requests go direct)")
        return null
    }
    if (info != null && !info.host.isNullOrBlank() && info.port > 0)
        return EngineProxy.Proxy(info.host, info.port, info.exclusionList.orEmpty().toList())
    val host = System.getProperty("https.proxyHost")?.takeIf { it.isNotBlank() } ?: System.getProperty("http.proxyHost")?.takeIf { it.isNotBlank() } ?: return null
    val port = (System.getProperty("https.proxyPort") ?: System.getProperty("http.proxyPort"))?.toIntOrNull() ?: 80
    EngineProxy.Proxy(host, port, EngineProxy.parseNonProxyHosts(System.getProperty("http.nonProxyHosts")))
}

fun mergeNodeOptions(base: String?, extra: List<String>): String {
    val out = LinkedHashMap<String, String>()
    (base.orEmpty().split(' ').filter { it.isNotBlank() } + extra).forEach { out[it.substringBefore('=')] = it }
    return out.values.joinToString(" ")
}

class EngineService : Service() {
    @Volatile private var started = false

    override fun onCreate() {
        super.onCreate()
        val n: Notification = NotificationCompat.Builder(this, Notifications.CHANNEL_ENGINE)
            .setSmallIcon(R.drawable.ic_stat_dsh)
            .setContentTitle(getString(R.string.engine_running))
            .setOngoing(true)
            .setSilent(true)
            // Without a content intent a tap did nothing (#39): open the running conversation.
            .setContentIntent(Notifications.openRunning(this))
            .build()
        // Background-start denials surface in EngineManager.bind(); never crash the process here.
        runCatching { startForeground(Notifications.ID_ENGINE, n, ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE) }
            .onFailure { Log.w(TAG, "startForeground refused", it) }
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        // A null intent is Android re-creating a 引擎常驻 (sticky) service after its process was killed:
        // the process has no Node yet, so ask :main (cold-starting it if needed) to start the engine again.
        if (intent == null) {
            Log.i(TAG, "re-created by the system; asking the app to restore the engine")
            runCatching { sendBroadcast(Intent(this, BootReceiver::class.java).setAction(EngineKeepAlive.ACTION_RESTORE)) }
                .onFailure { Log.w(TAG, "restore broadcast failed", it) }
            return START_STICKY
        }
        return EngineKeepAlive.startMode(intent.getBooleanExtra(EngineKeepAlive.EXTRA_KEEP_ALIVE, false))
    }

    private val binder = object : IEngineService.Stub() {
        override fun isRunning() = started

        override fun start(env: Bundle): Bundle = synchronized(this) {
            check(!started) { "engine already started in this process" }
            started = true
            val engineDir = EngineInstaller.install(this@EngineService)
            val stdin = ParcelFileDescriptor.createPipe()   // [read, write]
            val stdout = ParcelFileDescriptor.createPipe()
            val nodeSide = FileDescriptor()
            val appSide = FileDescriptor()
            Os.socketpair(OsConstants.AF_UNIX, OsConstants.SOCK_STREAM, 0, nodeSide, appSide)
            // Keep the Node side open for the lifetime of the process (detached = never auto-closed).
            val bridgeFd = ParcelFileDescriptor.dup(nodeSide).detachFd().also { Os.close(nodeSide) }
            val stderrFile = EngineDiagnostics.rotateLogs(this@EngineService)
            val stderr = ParcelFileDescriptor.open(stderrFile,
                ParcelFileDescriptor.MODE_CREATE or ParcelFileDescriptor.MODE_WRITE_ONLY or ParcelFileDescriptor.MODE_TRUNCATE)

            EngineRuntimeEnv.apply(this@EngineService, env)
            Os.setenv("DSH_BRIDGE_FD", bridgeFd.toString(), true)
            File(env.getString("TMPDIR") ?: cacheDir.path).mkdirs()
            File(env.getString("HOME") ?: filesDir.path).mkdirs()

            // argv[0] ("node") is prepended by libdshengine.
            // Entry: dsh's CLI for profile android plus crash/safe-mode bookkeeping and the app-layer overlay (PLUGINS-CONTRACT §1).
            val args = (EngineRuntimeEnv.nodeArgv(engineDir, env) + listOf(File(engineDir, "node_modules/@dsh-android/bundle-android/main.mjs").path)).toTypedArray()
            val inRead = stdin[0].detachFd()
            val outWrite = stdout[1].detachFd()
            val errWrite = stderr.detachFd()
            Thread(null, {
                val code = runCatching { NodeRuntime.nativeStart(args, inRead, outWrite, errWrite) }
                    .onFailure { Log.e(TAG, "node crashed", it) }.getOrDefault(-1)
                Log.i(TAG, "node exited with $code")
                if (code == 0) EngineDiagnostics.markCleanExit(this@EngineService, Process.myPid())
                stopSelf()
                Process.killProcess(Process.myPid())
            }, "node-main", 16L * 1024 * 1024).start()
            Bundle().apply {
                putParcelable("sdk_in", stdin[1])
                putParcelable("sdk_out", stdout[0])
                putParcelable("bridge", ParcelFileDescriptor.dup(appSide).also { Os.close(appSide) })
            }
        }
    }

    override fun onBind(intent: Intent?): IBinder = binder

    private companion object { const val TAG = "EngineService" }
}

