fun set(activity: Activity, tag: String?) {
    if (Build.VERSION.SDK_INT >= 33) {
        activity.getSystemService(LocaleManager::class.java)?.applicationLocales = if (tag == null) LocaleList.getEmptyLocaleList() else LocaleList.forLanguageTags(tag)
        return
    }
    store(activity, tag)
    applyToProcess(activity.applicationContext)
    activity.recreate()
}

@SuppressLint("AppBundleLocaleChanges")
internal fun legacyWrap(base: Context): Context {
    val locale = stored(base)?.let(Locale::forLanguageTag) ?: return base
    Locale.setDefault(locale)
    val cfg = Configuration(base.resources.configuration).apply { setLocales(LocaleList(locale)) }
    return base.createConfigurationContext(cfg)
}

@SuppressLint("AppBundleLocaleChanges")
fun applyToProcess(app: Context) {
    val tag = stored(app)
    if (Build.VERSION.SDK_INT >= 33) {
        if (tag != null) {
            app.getSystemService(LocaleManager::class.java)?.let { lm -> if (lm.applicationLocales.isEmpty) lm.applicationLocales = LocaleList.forLanguageTags(tag) }
            store(app, null)
        }
        return
    }
    val locale = tag?.let(Locale::forLanguageTag) ?: android.content.res.Resources.getSystem().configuration.locales[0]
    Locale.setDefault(locale)
    val res = app.resources
    if (res.configuration.locales[0] == locale) return
    val cfg = Configuration(res.configuration).apply { setLocales(LocaleList(locale)) }
    @Suppress("DEPRECATION") res.updateConfiguration(cfg, res.displayMetrics)
}

fun openExternal(context: Context, url: String): Boolean {
    val uri = Uri.parse(url)
    if (uri.scheme != "http" && uri.scheme != "https") return false
    val intent = Intent(Intent.ACTION_VIEW, uri).addCategory(Intent.CATEGORY_BROWSABLE).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
    return try { context.startActivity(intent); true } catch (e: ActivityNotFoundException) {
        Log.w("Browser", "no browser for $url", e); false
    }
}

fun openSignIn(context: Context, url: String, dark: Boolean, toolbar: Int): Boolean {
    val intent = signInIntent(context, url, dark, toolbar)
    return try { context.startActivity(intent); true } catch (e: ActivityNotFoundException) {
        Log.w("Browser", "sign-in browser unavailable (${intent.`package`})", e)
        intent.`package` != null && openExternal(context, url)
    } catch (e: SecurityException) {
        Log.w("Browser", "sign-in browser not allowed", e); openExternal(context, url)
    }
}

object Connectivity {
    fun online(context: Context): Boolean {
        val cm = context.getSystemService(ConnectivityManager::class.java) ?: return true
        return cm.getNetworkCapabilities(cm.activeNetwork)?.validated() == true
    }

    /** [online] now, then on every change of the default network; the callback is unregistered when collection ends. */
    fun onlineFlow(context: Context): Flow<Boolean> = callbackFlow {
        val cm = context.getSystemService(ConnectivityManager::class.java)
        val callback = object : ConnectivityManager.NetworkCallback() {
            override fun onCapabilitiesChanged(network: Network, caps: NetworkCapabilities) { trySend(caps.validated()) }
            override fun onLost(network: Network) { trySend(false) }
        }
        cm.registerDefaultNetworkCallback(callback)
        trySend(online(context))
        awaitClose { runCatching { cm.unregisterNetworkCallback(callback) } }
    }.distinctUntilChanged()

    private fun NetworkCapabilities.validated() =
        hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) && hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)
}

fun onlineFlow(context: Context): Flow<Boolean> = callbackFlow {
    val cm = context.getSystemService(ConnectivityManager::class.java)
    val callback = object : ConnectivityManager.NetworkCallback() {
        override fun onCapabilitiesChanged(network: Network, caps: NetworkCapabilities) { trySend(caps.validated()) }
        override fun onLost(network: Network) { trySend(false) }
    }
    cm.registerDefaultNetworkCallback(callback)
    trySend(online(context))
    awaitClose { runCatching { cm.unregisterNetworkCallback(callback) } }
}

fun trustedDenied(flags: Int, error: Throwable): Boolean {
    if (!trusted(flags) || error !is SecurityException) return false
    val msg = error.message.orEmpty()
    if (!msg.contains("ADD_TRUSTED_DISPLAY")) return false
    return !ownGroup(flags) || msg.contains("trusted virtual display", ignoreCase = true)
}

internal class TrustedDenial(private val file: File?, private val key: Key) {
    data class Key(val sdk: Int, val fingerprint: String, val bootId: String) {
        fun line(reason: String) = "$sdk\t${fingerprint.clean()}\t${bootId.clean()}\t${reason.clean()}\n"
        private fun String.clean() = replace(Regex("[\\t\\r\\n]"), " ")
    }

    @Volatile private var reason: String? = load()

    /** Why trusted displays are refused here (the remembered error), or null when not known to be. */
    fun reason(): String? = reason

    fun remember(reason: String) {
        this.reason = reason
        runCatching { file?.writeText(key.line(reason)) }
    }

    private fun load(): String? = runCatching {
        val p = file?.takeIf { it.exists() }?.readText()?.trimEnd('\n')?.split('\t') ?: return null
        if (p.size < 4) return null
        val now = key.line("").split('\t')
        if (p[0] != now[0] || p[1] != now[1] || p[2] != now[2]) return null
        p[3].ifBlank { null }
    }.getOrNull()

    companion object {
        /** This boot's id (/proc/sys/kernel/random/boot_id), else the boot time to the minute. */
        fun bootId(): String = runCatching { File("/proc/sys/kernel/random/boot_id").readText().trim() }.getOrNull()?.takeIf { it.isNotEmpty() }
            ?: ((System.currentTimeMillis() - android.os.SystemClock.elapsedRealtime()) / 60_000).toString()
    }
}

@SuppressLint("MissingPermission")
object Locator {
    private const val FIX_TIMEOUT_MS = 20_000L
    private const val FRESH_MS = 2 * 60_000L

    private fun hasPlayServices(context: Context) = runCatching {
        GoogleApiAvailability.getInstance().isGooglePlayServicesAvailable(context) == ConnectionResult.SUCCESS
    }.getOrDefault(false)

    suspend fun current(context: Context, precise: Boolean): Location? = withTimeoutOrNull(FIX_TIMEOUT_MS) {
        if (hasPlayServices(context)) runCatching { fused(context, precise) }.getOrNull()?.let { return@withTimeoutOrNull it }
        platform(context, precise)
    } ?: lastKnown(context)

    private suspend fun fused(context: Context, precise: Boolean): Location? = suspendCancellableCoroutine { cont ->
        val cts = CancellationTokenSource()
        LocationServices.getFusedLocationProviderClient(context)
            .getCurrentLocation(if (precise) Priority.PRIORITY_HIGH_ACCURACY else Priority.PRIORITY_BALANCED_POWER_ACCURACY, cts.token)
            .addOnSuccessListener { if (cont.isActive) cont.resume(it) }
            .addOnFailureListener { if (cont.isActive) cont.resume(null) }
            .addOnCanceledListener { if (cont.isActive) cont.resume(null) }
        cont.invokeOnCancellation { cts.cancel() }
    }

    private suspend fun platform(context: Context, precise: Boolean): Location? {
        val lm = context.getSystemService(LocationManager::class.java)
        val enabled = lm.getProviders(true)
        val provider = when {
            precise && LocationManager.GPS_PROVIDER in enabled -> LocationManager.GPS_PROVIDER
            LocationManager.NETWORK_PROVIDER in enabled -> LocationManager.NETWORK_PROVIDER
            Build.VERSION.SDK_INT >= 31 && LocationManager.FUSED_PROVIDER in enabled -> LocationManager.FUSED_PROVIDER
            enabled.isNotEmpty() -> enabled.first()
            else -> return null
        }
        return suspendCancellableCoroutine { cont ->
            if (Build.VERSION.SDK_INT >= 30) {
                val signal = CancellationSignal()
                lm.getCurrentLocation(provider, signal, context.mainExecutor) { if (cont.isActive) cont.resume(it) }
                cont.invokeOnCancellation { signal.cancel() }
            } else {
                val listener = object : LocationListener {
                    override fun onLocationChanged(l: Location) { if (cont.isActive) cont.resume(l) }
                    @Deprecated("Deprecated in Java") override fun onStatusChanged(p: String?, s: Int, b: android.os.Bundle?) {}
                    override fun onProviderEnabled(p: String) {}
                    override fun onProviderDisabled(p: String) {}
                }
                @Suppress("DEPRECATION") lm.requestSingleUpdate(provider, listener, Looper.getMainLooper())
                cont.invokeOnCancellation { lm.removeUpdates(listener) }
            }
        }
    }

    private fun lastKnown(context: Context): Location? {
        val lm = context.getSystemService(LocationManager::class.java)
        return runCatching { lm.getProviders(true).mapNotNull { lm.getLastKnownLocation(it) }.maxByOrNull { it.time } }.getOrNull()
            ?.takeIf { System.currentTimeMillis() - it.time < FRESH_MS * 15 } // shown with its age; drop anything older than 30 min
    }

    /** Street address from the system geocoder, or null (absent on many devices / no network). */
    suspend fun address(context: Context, lat: Double, lng: Double): String? {
        if (!Geocoder.isPresent()) return null
        val g = Geocoder(context)
        return withTimeoutOrNull(5_000) {
            if (Build.VERSION.SDK_INT >= 33) suspendCancellableCoroutine<String?> { cont ->
                g.getFromLocation(lat, lng, 1, object : Geocoder.GeocodeListener {
                    override fun onGeocode(list: MutableList<android.location.Address>) { if (cont.isActive) cont.resume(list.firstOrNull()?.let(::line)) }
                    override fun onError(message: String?) { if (cont.isActive) cont.resume(null) }
                })
            } else runCatching {
                runInterruptible(Dispatchers.IO) { @Suppress("DEPRECATION") g.getFromLocation(lat, lng, 1)?.firstOrNull()?.let(::line) }
            }.getOrNull()
        }
    }

    private fun line(a: android.location.Address): String =
        (0..a.maxAddressLineIndex).mapNotNull { a.getAddressLine(it) }.joinToString(", ").ifEmpty {
            listOfNotNull(a.thoroughfare, a.subLocality, a.locality, a.adminArea, a.countryName).joinToString(", ")
        }
}

suspend fun address(context: Context, lat: Double, lng: Double): String? {
    if (!Geocoder.isPresent()) return null
    val g = Geocoder(context)
    return withTimeoutOrNull(5_000) {
        if (Build.VERSION.SDK_INT >= 33) suspendCancellableCoroutine<String?> { cont ->
            g.getFromLocation(lat, lng, 1, object : Geocoder.GeocodeListener {
                override fun onGeocode(list: MutableList<android.location.Address>) { if (cont.isActive) cont.resume(list.firstOrNull()?.let(::line)) }
                override fun onError(message: String?) { if (cont.isActive) cont.resume(null) }
            })
        } else runCatching {
            runInterruptible(Dispatchers.IO) { @Suppress("DEPRECATION") g.getFromLocation(lat, lng, 1)?.firstOrNull()?.let(::line) }
        }.getOrNull()
    }
}

