    val max = rawMax.coerceIn(MIN_MAX_TOKENS, cap)
    return EffectiveLimits(ctx, ctxSrc, max, maxSrc, minOf(COMPACTION_HEADROOM.toLong(), ctx / 8).toInt())
}

