    val normalized = spec?.let(::validate)
    rules.upsert(e.copy(
        specJson = normalized?.let { RpcJson.encodeToString(RuleSpec.serializer(), it) } ?: e.specJson,
        enabled = enabled ?: e.enabled,
    ))
