private fun syncGeofences(allIds: List<Long>, fences: List<Pair<Long, Trigger.Geofence>>) {
    val canLocate = context.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED
    if (playServicesGeofencing) {
        val client = LocationServices.getGeofencingClient(context)
        client.removeGeofences(gmsGeofenceIntent).addOnCompleteListener {
            if (!canLocate || fences.isEmpty()) return@addOnCompleteListener
            val request = GeofencingRequest.Builder().setInitialTrigger(0).apply {
                fences.forEach { (id, g) ->
                    addGeofence(Geofence.Builder().setRequestId(id.toString()).setCircularRegion(g.lat, g.lng, g.radiusM)
                        .setExpirationDuration(Geofence.NEVER_EXPIRE)
                        .setTransitionTypes(Geofence.GEOFENCE_TRANSITION_ENTER or Geofence.GEOFENCE_TRANSITION_EXIT).build())
                }
            }.build()
            @Suppress("MissingPermission")
            runCatching { client.addGeofences(request, gmsGeofenceIntent).addOnFailureListener { Log.w(TAG, "geofences not registered", it) } }
                .onFailure { Log.w(TAG, "geofences not registered", it) }
        }
        return
    }
    val lm = context.getSystemService(LocationManager::class.java)
    allIds.forEach { id -> runCatching { lm.removeProximityAlert(geofenceIntent(id)) } }
    if (!canLocate) return
    @Suppress("MissingPermission")
    fences.forEach { (id, g) -> runCatching { lm.addProximityAlert(g.lat, g.lng, g.radiusM, -1, geofenceIntent(id)) } }
}

@AndroidEntryPoint
class TriggerReceiver : BroadcastReceiver() {
    @Inject lateinit var hub: TriggerHub

    override fun onReceive(context: Context, intent: Intent) {
        val jobs = runCatching {
            when (intent.action) {
                ACTION_TIME -> listOf(hub.onEvent(DeviceEvent.Time(intent.getLongExtra("ruleId", -1))))
                ACTION_GEOFENCE -> listOf(hub.onEvent(DeviceEvent.Geofence(intent.getLongExtra("ruleId", -1),
                    intent.getBooleanExtra(LocationManager.KEY_PROXIMITY_ENTERING, true))))
                ACTION_GEOFENCE_GMS -> {
                    val ev = GeofencingEvent.fromIntent(intent)
                    if (ev == null || ev.hasError()) emptyList() else {
                        val entering = ev.geofenceTransition == Geofence.GEOFENCE_TRANSITION_ENTER
                        ev.triggeringGeofences.orEmpty().mapNotNull { g -> g.requestId.toLongOrNull()?.let { hub.onEvent(DeviceEvent.Geofence(it, entering)) } }
                    }
                }
                else -> emptyList()
            }
        }.getOrElse { android.util.Log.e("TriggerReceiver", "dispatch failed", it); emptyList() }
        if (jobs.isEmpty()) return
        // Keep the (possibly alarm-cold-started) process alive until the next alarm is scheduled and
        // the runs are launched; aggressive ROMs kill a bare cached process right after onReceive.
        val pending = goAsync()
        CoroutineScope(Dispatchers.Default).launch {
            try { withTimeoutOrNull(9_000) { jobs.joinAll() } } finally { pending.finish() }
        }
    }

    companion object {
        const val ACTION_TIME = "io.github.jackwener.dsh.TRIGGER_TIME"
        const val ACTION_GEOFENCE = "io.github.jackwener.dsh.TRIGGER_GEOFENCE"
        const val ACTION_GEOFENCE_GMS = "io.github.jackwener.dsh.TRIGGER_GEOFENCE_GMS"
    }
}

