private fun record(r: CheckResult) {
    val lc = LastCheck(System.currentTimeMillis(), r)
    _lastCheck.value = lc
    val (kind, a, b) = when (r) {
        CheckResult.UpToDate -> Triple("uptodate", "", "")
        is CheckResult.Found -> Triple("found", r.versionName, "")
        is CheckResult.Unsupported -> Triple("unsupported", r.versionName, r.minSdk.toString())
        is CheckResult.Skipped -> Triple("skipped", r.versionName, "")
        is CheckResult.Failed -> Triple("failed", r.detail.take(300), "")
    }
    prefs.edit().putLong(KEY_LAST_AT, lc.at).putString(KEY_LAST_KIND, kind).putString(KEY_LAST_A, a).putString(KEY_LAST_B, b).apply()
}

object UpdatePolicy {
    const val DAY_MS = 24 * 3600_000L

    /** [enabled] = 自动检查更新; at most one attempt (successful or not) per day. A clock set back counts as due. */
    fun autoCheckDue(enabled: Boolean, lastAttempt: Long, now: Long): Boolean = enabled && (lastAttempt <= 0 || now - lastAttempt >= DAY_MS || now < lastAttempt)

    /** 稍后 hides the prompt for a day; the update stays in 设置 → 关于. */
    fun promptDue(snoozedAt: Long, now: Long): Boolean = snoozedAt <= 0 || now - snoozedAt >= DAY_MS || now < snoozedAt
}

interface UpdateNet {
    /** GET [url] as text (size-capped); throws on a non-2xx status or a network failure. */
    fun text(url: String): String
    /**
     * GET [url] from byte [from] (a `Range` request when > 0). Returns where the body actually
     * starts ([rangeStart]); throws [RangeNotSatisfiable] for 416, IOException otherwise.
     */
    fun open(url: String, from: Long): RangeBody
}

fun rangeStart(code: Int, contentRange: String?, from: Long): Long? = when (code) {
    200 -> 0L
    206 -> Regex("""^bytes (\d+)-\d+/(\d+|\*)$""").find(contentRange?.trim().orEmpty())?.groupValues?.get(1)?.toLongOrNull()?.takeIf { it == from }
    else -> null
}

class HttpUpdateNet(private val userAgent: String, private val connectMs: Int = 15_000, private val readMs: Int = 30_000) : UpdateNet {
    private fun connect(url: String, configure: HttpURLConnection.() -> Unit = {}): HttpURLConnection {
        val c = URL(url).openConnection() as HttpURLConnection
        c.connectTimeout = connectMs; c.readTimeout = readMs; c.instanceFollowRedirects = true
        c.setRequestProperty("User-Agent", userAgent)
        c.configure()
        return c
    }

    override fun text(url: String): String {
        val c = connect(url) { setRequestProperty("Accept", "application/json"); setRequestProperty("Cache-Control", "no-cache") }
        try {
            val code = c.responseCode
            if (code !in 200..299) throw IOException("HTTP $code")
            if (c.url.protocol != "https") throw IOException("redirected off https")
            val bytes = c.inputStream.use { it.readNBytesCompat(MAX_MANIFEST) }
            return bytes.toString(Charsets.UTF_8)
        } finally { c.disconnect() }
    }

    override fun open(url: String, from: Long): RangeBody {
        val c = connect(url) {
            setRequestProperty("Accept-Encoding", "identity")
            if (from > 0) setRequestProperty("Range", "bytes=$from-")
        }
        try {
            val code = c.responseCode
            if (code == 416) throw RangeNotSatisfiable()
            if (c.url.protocol != "https") throw IOException("redirected off https")
            val range = c.getHeaderField("Content-Range")
            val start = rangeStart(code, range, from) ?: throw IOException("HTTP $code${range?.let { " ($it)" } ?: ""}")
            return RangeBody(start, totalLength(code, range, c.contentLengthLong), c.inputStream) { c.disconnect() }
        } catch (t: Throwable) { c.disconnect(); throw t }
    }

    companion object { const val MAX_MANIFEST = 256 * 1024 }
}

suspend fun download(apk: UpdateManifest.Apk, dir: File, onProgress: (Long, Long) -> Unit): File {
    dir.mkdirs()
    val done = finalFile(dir, apk)
    if (done.isFile && done.length() == apk.size && Sha256.of(done) == apk.sha256) return done
    done.delete()
    // Leftovers of other releases.
    dir.listFiles()?.forEach { if (it.name != partFile(dir, apk).name) it.delete() }
    val part = partFile(dir, apk)
    val failures = mutableListOf<Pair<String, Throwable>>()
    for (url in apk.urls) {
        var attempt = 0
        while (true) {
            currentCoroutineContext().ensureActive()
            try {
                fetchInto(url, apk, part, onProgress)
                if (Sha256.of(part) != apk.sha256) { part.delete(); throw DigestMismatch(url) }
                if (!part.renameTo(done)) throw IOException("cannot move the download into place")
                return done
            } catch (e: CancellationException) { throw e }
            catch (e: DigestMismatch) { failures += url to e; break } // a retry would fetch the same bytes: next URL
            catch (e: Throwable) {
                if (++attempt > retries) { failures += url to e; break }
                delay(backoffMs(attempt - 1))
            }
        }
    }
    throw AllSourcesFailed(failures)
}

private suspend fun copy(body: RangeBody, apk: UpdateManifest.Apk, part: File, had: Long, onProgress: (Long, Long) -> Unit): Long {
    var have = had
    body.total?.let { t -> if (t != apk.size) throw IOException("server reports $t bytes, manifest says ${apk.size}") }
    val append = body.start > 0
    if (!append) have = 0
    FileOutputStream(part, append).use { out ->
        val buf = ByteArray(1 shl 16)
        val ctx = currentCoroutineContext()
        while (true) {
            ctx.ensureActive()
            val n = body.stream.read(buf); if (n < 0) break
            if (have + n > apk.size) throw IOException("more data than the manifest's ${apk.size} bytes")
            out.write(buf, 0, n); have += n
            onProgress(have, apk.size)
        }
        out.fd.sync()
    }
    return have
}

    val signerSha256: String,
    /** Release notes (Markdown) by language (`zh`, `en`). */
    val notes: Map<String, String>,
    val publishedAt: String?,
    /** The raw text, kept so a found update survives a process restart without a new fetch. */
    val raw: String,
) {
    data class Apk(val name: String, val size: Long, val sha256: String, val urls: List<String>)

    /** Notes in the UI language ([lang] `zh` / `en` …), else English, else any. */
    fun notesFor(lang: String): String? = notes[lang] ?: notes["en"] ?: notes.values.firstOrNull()

    class Invalid(val path: String, reason: String) : Exception("$path: $reason")

    companion object {
        const val FORMAT = 1L
        private const val REPO = "jackwener/DSH-Android"

        /**
         * Where `update.json` is fetched from, in order (first valid one wins, the next starts a few
         * seconds after the previous: UpdateFetch.firstSuccess). The release asset is the source of
         * truth; the repository copy covers networks where github.com is slow or blocked (the same
         * jsDelivr CDNs the engine falls back to, js/packages/plugin-extensions/fetch-sources.js).
         */
        val SOURCES = listOf(
            "https://github.com/$REPO/releases/latest/download/update.json",
            "https://raw.githubusercontent.com/$REPO/main/update/latest.json",
            "https://cdn.jsdelivr.net/gh/$REPO@main/update/latest.json",
            "https://fastly.jsdelivr.net/gh/$REPO@main/update/latest.json",
            "https://gcore.jsdelivr.net/gh/$REPO@main/update/latest.json",
            "https://testingcf.jsdelivr.net/gh/$REPO@main/update/latest.json",
        )
        const val RELEASES_PAGE = "https://github.com/$REPO/releases/latest"

        private val HEX64 = Regex("^[0-9a-f]{64}$")
        private val json = Json { ignoreUnknownKeys = true }

        /** Parses and validates; [packageName]: when the manifest names a package it must be this one. */
        fun parse(text: String, packageName: String? = null): UpdateManifest {
            val root = runCatching { json.parseToJsonElement(text) }.getOrNull() as? JsonObject ?: throw Invalid("$", "not a JSON object")
            if (root.long("format") != FORMAT) throw Invalid("$.format", "must be $FORMAT")
            root.str("packageName")?.let { if (packageName != null && it != packageName) throw Invalid("$.packageName", "is $it, not $packageName") }
            val code = root.long("versionCode")?.takeIf { it > 0 } ?: throw Invalid("$.versionCode", "must be a positive integer")
            val name = root.str("versionName")?.takeIf { it.isNotBlank() } ?: throw Invalid("$.versionName", "required")
            val minSdk = root.long("minSdk")?.takeIf { it in 1..1000 }?.toInt() ?: throw Invalid("$.minSdk", "must be an API level")
            val apk = root["apk"] as? JsonObject ?: throw Invalid("$.apk", "must be an object")
            val size = apk.long("size")?.takeIf { it > 0 } ?: throw Invalid("$.apk.size", "must be a positive integer")
            val sha = hex64(apk.str("sha256"), "$.apk.sha256")
            val urls = (apk["urls"] as? JsonArray)?.mapIndexed { i, u ->
                val s = (u as? JsonPrimitive)?.takeIf { it.isString }?.content
                val uri = s?.let { runCatching { URI(it) }.getOrNull() }
                if (uri?.scheme != "https" || uri.host.isNullOrEmpty() || uri.userInfo != null) throw Invalid("$.apk.urls[$i]", "must be an https URL")
                s
            } ?: throw Invalid("$.apk.urls", "must be an array")
            if (urls.isEmpty()) throw Invalid("$.apk.urls", "must not be empty")
            val apkName = apk.str("name")?.takeIf { it.isNotBlank() } ?: "DSH-Android-$name.apk"
            val signer = hex64(root.str("signerSha256"), "$.signerSha256")
            val notes = when (val n = root["notes"]) {
                null -> emptyMap()
                is JsonPrimitive -> n.contentOrNull?.takeIf { n.isString && it.isNotBlank() }?.let { mapOf("en" to it) } ?: throw Invalid("$.notes", "must be text")
                is JsonObject -> n.mapNotNull { (k, v) -> (v as? JsonPrimitive)?.takeIf { it.isString }?.content?.takeIf { it.isNotBlank() }?.let { k to it } }.toMap()
                else -> throw Invalid("$.notes", "must be an object of texts")
            }
            return UpdateManifest(code, name, minSdk, Apk(apkName, size, sha, urls), signer, notes, root.str("publishedAt"), text)
        }

        /** 64 hex digits; colons (keytool / apksigner style) and case are normalized away. */
        private fun hex64(s: String?, path: String): String =
            s?.replace(":", "")?.lowercase()?.takeIf { HEX64.matches(it) } ?: throw Invalid(path, "must be a SHA-256 hex digest")

        private fun JsonObject.str(k: String) = (this[k] as? JsonPrimitive)?.takeIf { it.isString }?.content
        private fun JsonObject.long(k: String) = (this[k] as? JsonPrimitive)?.takeIf { !it.isString }?.longOrNull
    }
}

fun parse(text: String, packageName: String? = null): UpdateManifest {
    val root = runCatching { json.parseToJsonElement(text) }.getOrNull() as? JsonObject ?: throw Invalid("$", "not a JSON object")
