            MenuDivider()
            MenuSectionTitle(stringResource(R.string.effort))
            Effort.entries.forEach { e -> MenuItem(e.label, { modelOpen = false; onEffort(e) }, null, stringResource(effortDesc(e)), selected = e == effort) }
