    val copyName = existing?.let { stringResource(R.string.mode_copy_name, ModeUi.name(it)) } ?: ""
    val duplicate: (SessionMode) -> Unit = { m ->
        val id = SessionModes.newCustomId(s.allModes.map { it.id })
