  @XmlRes open fun getPreferenceXmlResId(): Int = R.xml.pref_cyanea

  /**
   * Sets whether to reserve the space of all Preference views. If set to false, all padding will be removed.
   *
   * By default, if the action bar is displaying home as up then padding will be added to the preference.
   */
  open val iconSpaceReserved = false
//    get() = (activity as? AppCompatActivity)?.supportActionBar?.displayOptions?.and(ActionBar.DISPLAY_HOME_AS_UP) != 0

  override fun onCreatePreferences(savedInstanceState: Bundle?, rootKey: String?) {
    setPreferencesFromResource(getPreferenceXmlResId(), rootKey)

    prefThemePicker = findPreference(PREF_THEME_PICKER)
    prefColorPrimary = findPreference(PREF_COLOR_PRIMARY)
    prefColorAccent = findPreference(PREF_COLOR_ACCENT)
    prefColorBackground = findPreference(PREF_COLOR_BACKGROUND)
    prefColorNavBar = findPreference(PREF_COLOR_NAV_BAR)

    prefColorPrimary.saveValue(cyanea.primary)
    prefColorAccent.saveValue(cyanea.accent)
    prefColorBackground.saveValue(cyanea.backgroundColor)

    prefThemePicker.onPreferenceClickListener = this
    prefColorPrimary.onPreferenceChangeListener = this
    prefColorAccent.onPreferenceChangeListener = this
    prefColorBackground.onPreferenceChangeListener = this
    prefColorNavBar.onPreferenceChangeListener = this

    setupNavBarPref()
  }

  override fun onPreferenceClick(preference: Preference): Boolean {
    return when (preference) {
      prefThemePicker -> {
        activity?.run {
          if (this is CyaneaThemePickerLauncher) {
            launchThemePicker()
          } else {
            startActivity(Intent(this, CyaneaThemePickerActivity::class.java))
          }
        }
        true
      }
      else -> false
    }
  }

  override fun onPreferenceChange(preference: Preference, newValue: Any?): Boolean {
    fun editTheme(action: (editor: Cyanea.Editor) -> Unit) {
      cyanea.edit {
        action(this)
      }.recreate(requireActivity(), smooth = true)
    }

    when (preference) {
      prefColorPrimary -> editTheme { it.primary(newValue as Int) }
      prefColorAccent -> editTheme { it.accent(newValue as Int) }
      prefColorBackground -> editTheme { it.background(newValue as Int) }
      prefColorNavBar -> editTheme { it.shouldTintNavBar(newValue as Boolean) }
      else -> return false
    }

    return true
  }

  override fun onCreateAdapter(preferenceScreen: PreferenceScreen): RecyclerView.Adapter<*> {
    return object : PreferenceGroupAdapter(preferenceScreen) {
      @SuppressLint("RestrictedApi")
      override fun onBindViewHolder(holder: PreferenceViewHolder, position: Int) {
        super.onBindViewHolder(holder, position)
        if (iconSpaceReserved) return
        // See: https://stackoverflow.com/a/51568782/1048340
        val preference = getItem(position)
        if (preference is PreferenceCategory) {
          setZeroPaddingToLayoutChildren(holder.itemView)
        } else {
          holder.itemView.findViewById<View>(R.id.icon_frame)?.let { iconFrame ->
            iconFrame.visibility = if (preference?.icon == null) View.GONE else View.VISIBLE
          }
        }
      }
    }
  }

  // See: https://stackoverflow.com/a/51568782/1048340
  private fun setZeroPaddingToLayoutChildren(view: View) {
    if (view !is ViewGroup) return
    for (i in 0 until view.childCount) {
      setZeroPaddingToLayoutChildren(view.getChildAt(i))
      if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
        view.setPaddingRelative(0, view.paddingTop, view.paddingEnd, view.paddingBottom)
      } else {
        view.setPadding(0, view.paddingTop, view.paddingRight, view.paddingBottom)
      }
    }
  }

  private fun setupNavBarPref() {
    ColorUtils.isDarkColor(cyanea.primary, 0.75).let { isDarkEnough ->
      prefColorNavBar.isEnabled = isDarkEnough || VERSION.SDK_INT >= VERSION_CODES.O
    }
    val isColored = if (VERSION.SDK_INT >= VERSION_CODES.LOLLIPOP) {
      activity?.window?.navigationBarColor == cyanea.primary
    } else {
      false
    }
    prefColorNavBar.isChecked = cyanea.shouldTintNavBar || isColored
    val sysBarConfig = SystemBarTint(requireActivity()).sysBarConfig
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.KITKAT || !sysBarConfig.hasNavigationBar) {
      findPreference<PreferenceCategory>(PREF_CATEGORY).run {
        removePreference(prefColorNavBar)
      }
    }
  }

  private inline fun <reified T : Preference> findPreference(key: String): T =
    super.findPreference<T>(key) as T

  companion object {
    private const val PREF_CATEGORY = "cyanea_preference_category"
    private const val PREF_THEME_PICKER = "pref_theme_picker"
    private const val PREF_COLOR_PRIMARY = "pref_color_primary"
    private const val PREF_COLOR_ACCENT = "pref_color_accent"
    private const val PREF_COLOR_BACKGROUND = "pref_color_background"
    private const val PREF_COLOR_NAV_BAR = "pref_color_navigation_bar"

    fun newInstance() = CyaneaSettingsFragment()
  }
}

interface CyaneaThemePickerLauncher {

  /**
   * Launch a theme picker for Cyanea
   */
  fun launchThemePicker()
}

fun apply(cyanea: Cyanea) = cyanea.edit {
  baseTheme(baseTheme)
  primary(primary)
  primaryDark(primaryDark)
  primaryLight(primaryLight)
  accent(accent)
  accentDark(accentDark)
  accentLight(accentLight)
  background(background)
  when (baseTheme) {
    LIGHT -> {
      backgroundLightDarker(backgroundDark)
      backgroundLightLighter(backgroundLight)
    }
    DARK -> {
      backgroundDarkDarker(backgroundDark)
      backgroundDarkLighter(backgroundLight)
    }
  }
  menuIconColor(menuIconColor)
  subMenuIconColor(subMenuIconColor)
  navigationBar(navigationBarColor)
  shouldTintStatusBar(shouldTintStatusBar)
  shouldTintNavBar(shouldTintNavBar)
}

fun from(json: String): List<CyaneaTheme> {
  val themes = mutableListOf<CyaneaTheme>()
  val array = JSONArray(json)
  for (i in 0 until array.length()) {
    try {
      (array.get(i) as? JSONObject)?.let {
        themes.add(newInstance(it))
      }
    } catch (e: Exception) {
      Cyanea.log(TAG, "Error reading theme #${i + 1}", e)
    }
  }
  return themes
}

fun newInstance(json: JSONObject): CyaneaTheme {
  // Get the theme name
  val themeName = json.optString(THEME_NAME)

  // Get the primary colors
  val primary = ColorUtils.parseColor(json.getString(PRIMARY_COLOR))
  val primaryDark = if (json.has(PRIMARY_DARK_COLOR)) {
    ColorUtils.parseColor(json.getString(PRIMARY_DARK_COLOR))
  } else {
    ColorUtils.darker(primary)
  }
  val primaryLight = if (json.has(PRIMARY_LIGHT_COLOR)) {
    ColorUtils.parseColor(json.getString(PRIMARY_LIGHT_COLOR))
  } else {
    ColorUtils.parseColor(json.getString(PRIMARY_LIGHT_COLOR))
  }

  // Get the accent colors
  val accent = ColorUtils.parseColor(json.getString(ACCENT_COLOR))
  val accentDark = if (json.has(ACCENT_DARK_COLOR)) {
    ColorUtils.parseColor(json.getString(ACCENT_DARK_COLOR))
  } else {
    ColorUtils.darker(accent)
  }
  val accentLight = if (json.has(ACCENT_LIGHT_COLOR)) {
    ColorUtils.parseColor(json.getString(ACCENT_LIGHT_COLOR))
  } else {
    ColorUtils.lighter(accent)
  }

  // Get the background colors
  val background = ColorUtils.parseColor(json.getString(BACKGROUND_COLOR))
  val backgroundDarker = if (json.has(BACKGROUND_DARK_COLOR)) {
    ColorUtils.parseColor(json.getString(BACKGROUND_DARK_COLOR))
  } else {
    ColorUtils.darker(background)
  }
  val backgroundLighter = if (json.has(BACKGROUND_LIGHT_COLOR)) {
    ColorUtils.parseColor(json.getString(BACKGROUND_LIGHT_COLOR))
  } else {
    ColorUtils.lighter(background)
  }

  // Get the base theme
  val baseTheme = if (json.has(BASE_THEME)) {
    if (json.getString(BASE_THEME) == DARK.name) DARK else LIGHT
  } else {
    if (ColorUtils.isDarkColor(background)) DARK else LIGHT
  }

  // Get the menu item colors
  val menuIconColor = if (json.has(MENU_ICON_COLOR)) {
    ColorUtils.parseColor(json.getString(MENU_ICON_COLOR))
  } else {
    @Suppress("DEPRECATION")
    Cyanea.res.getColor(
      if (ColorUtils.isDarkColor(primary, 0.75)) {
        R.color.cyanea_menu_icon_light
      } else {
        R.color.cyanea_menu_icon_dark
      }
    )
  }
  val subMenuIconColor = if (json.has(SUB_MENU_ICON_COLOR)) {
    ColorUtils.parseColor(json.getString(SUB_MENU_ICON_COLOR))
  } else {
    @Suppress("DEPRECATION")
    Cyanea.res.getColor(
      if (baseTheme == LIGHT) R.color.cyanea_sub_menu_icon_dark else R.color.cyanea_sub_menu_icon_light
    )
  }

  // Get the navigation bar colors
  val navigationBarColor = if (json.has(NAVIGATION_BAR_COLOR)) {
    ColorUtils.parseColor(json.getString(NAVIGATION_BAR_COLOR))
  } else {
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O || ColorUtils.isDarkColor(primary, 0.75)) {
      primary
    } else {
      Color.BLACK
    }
  }

  // Get the tinting flags
  val shouldTintStatusBar = if (json.has(SHOULD_TINT_STATUSBAR)) {
    json.getBoolean(SHOULD_TINT_STATUSBAR)
  } else {
    Cyanea.res.getBoolean(R.bool.should_tint_status_bar)
  }
  val shouldTintNavBar = if (json.has(SHOULD_TINT_NAVBAR)) {
    json.getBoolean(SHOULD_TINT_NAVBAR)
  } else {
    Cyanea.res.getBoolean(R.bool.should_tint_nav_bar)
  }

  return CyaneaTheme(
    themeName,
    baseTheme,
    primary,
    primaryDark,
    primaryLight,
    accent,
    accentDark,
    accentLight,
    background,
    backgroundDarker,
    backgroundLighter,
    menuIconColor,
    subMenuIconColor,
    navigationBarColor,
    shouldTintStatusBar,
    shouldTintNavBar
  )
}

