class CyaneaThemePickerAdapter(private val themes: List<CyaneaTheme>, private val cyanea: Cyanea) : BaseAdapter() {

  override fun getView(position: Int, convertView: View?, parent: ViewGroup): View {
    val holder: ViewHolder

    holder = if (convertView == null) {
      val inflater = LayoutInflater.from(parent.context)
      val view = inflater.inflate(R.layout.cyanea_item_theme, parent, false)
      ViewHolder(view)
    } else {
      convertView.tag as ViewHolder
    }

    val theme = themes[position]

    holder.find<FrameLayout>(R.id.preview).setBackgroundColor(theme.background)
    holder.find<LinearLayout>(R.id.action_bar_panel).setBackgroundColor(theme.primary)

    val fab = holder.find<FloatingActionButton>(R.id.fab_add)
    // Bug: when using the accent color, the last selected item's FAB is the same color as the newly selected FAB.
    // For now, slightly adjust the color.
    val fabMainColor = ColorUtils.lighter(theme.accent, 0.01f)
    fab.backgroundTintList = ColorStateList.valueOf(fabMainColor)
    fab.supportBackgroundTintList = ColorStateList.valueOf(fabMainColor)
    fab.rippleColor = theme.accentDark

    val title = holder.find<TextView>(R.id.title)
    title.text = theme.themeName

    if (theme.isMatchingColorScheme(cyanea)) {
      title.setBackgroundColor(ContextCompat.getColor(parent.context, R.color.cyanea_theme_selected_color))
      title.setCompoundDrawablesWithIntrinsicBounds(0, 0, R.drawable.cyanea_check, 0)
    } else {
      title.setBackgroundColor(ContextCompat.getColor(parent.context, R.color.cyanea_theme_title_bg_color))
      title.setCompoundDrawablesWithIntrinsicBounds(0, 0, 0, 0)
    }

    val isDark = ColorUtils.isDarkColor(theme.primary, 0.75)
    val menuIconColor = if (isDark) Color.WHITE else Color.BLACK
    val drawable = DrawerArrowDrawable(parent.context)
    drawable.color = menuIconColor

    val drawer = holder.find<ImageView>(R.id.material_drawer_drawable)
    val overflow = holder.find<ImageView>(R.id.action_overflow)
    drawer.setImageDrawable(drawable)
    overflow.setColorFilter(menuIconColor, PorterDuff.Mode.SRC_ATOP)

    return holder.itemView
  }

  override fun getItem(position: Int): CyaneaTheme = themes[position]

  override fun getItemId(position: Int): Long = position.toLong()

  override fun getCount(): Int = themes.size

  private class ViewHolder(val itemView: View) {

    private val views = SparseArray<View>()

    init {
      itemView.tag = this
    }

    fun <T : View> find(@IdRes id: Int): T {
      views[id]?.let {
        @Suppress("UNCHECKED_CAST")
        return it as T
      } ?: run {
        val view = itemView.findViewById<T>(id)
        views.put(id, view)
        return view
      }
    }
  }
}

open class CyaneaThemePickerFragment : CyaneaFragment(), OnItemClickListener {

  open val themesJsonAssetPath get() = "themes/cyanea_themes.json"

  private lateinit var gridView: GridView

  override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
    return inflater.inflate(R.layout.cyanea_theme_picker, container, false)
  }

  override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
    super.onViewCreated(view, savedInstanceState)
    gridView = view.findViewById(R.id.gridView)
    val themes = CyaneaTheme.from(requireActivity().assets, themesJsonAssetPath)
    gridView.adapter = CyaneaThemePickerAdapter(themes, cyanea)
    gridView.onItemClickListener = this
    scrollToCurrentTheme(themes)
  }

  override fun onItemClick(parent: AdapterView<*>?, view: View?, position: Int, id: Long) {
    val theme = (gridView.adapter as CyaneaThemePickerAdapter).getItem(position)
    val themeName = theme.themeName
    Cyanea.log(TAG, "Clicked $themeName")
    theme.apply(cyanea).recreate(requireActivity(), smooth = true)
  }

  private fun scrollToCurrentTheme(themes: List<CyaneaTheme>) {
    var selectedTheme = -1
    run {
      themes.forEachIndexed { index, theme ->
        if (theme.isMatchingColorScheme(cyanea)) {
          selectedTheme = index
          return@run
        }
      }
    }
    if (selectedTheme != -1) {
      gridView.post {
        if (selectedTheme < gridView.firstVisiblePosition || selectedTheme > gridView.lastVisiblePosition) {
          gridView.setSelection(selectedTheme)
        }
      }
    }
  }

  companion object {
    private const val TAG = "ThemePickerFragment"

    fun newInstance() = CyaneaThemePickerFragment()
  }
}

@Throws(CyaneaTintException::class)
fun tint(drawable: Drawable?) {
  if (drawable is GradientDrawable) {
    tint(drawable)
  } else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP && drawable is RippleDrawable) {
    tint(drawable)
  } else if (drawable is LayerDrawable) {
    tint(drawable)
  } else if (drawable is DrawableContainer) {
    tint(drawable)
  } else if (drawable is NinePatchDrawable) {
    tint(drawable)
  } else if (drawable is ColorDrawable) {
    tint(drawable)
  }
}

fun tint(colorStateList: ColorStateList?): ColorStateList? {
  return colorStateList?.let { csl ->
    fun updateColors(colors: IntArray): Boolean {
      var changed = false
      for (i in colors.indices) {
        this.colors[colors[i]]?.let { color ->
          if (color != colors[i]) {
            colors[i] = color
            changed = true
          }
        } ?: run {
          val stripAlpha = ColorUtils.stripAlpha(colors[i])
          this.colors[stripAlpha]?.run {
            val color = Color.argb(Color.alpha(colors[i]), Color.red(this), Color.green(this), Color.blue(this))
            colors[i] = color
            changed = true
          }
        }
      }
      return changed
    }

    try {
      var changed = false
      if (Build.VERSION.SDK_INT <= Build.VERSION_CODES.KITKAT) {
        Reflection.getFieldValue<IntArray?>(csl, "mColors")?.let { colors ->
          changed = updateColors(colors)
        }
      } else {
        Reflection.invoke<IntArray?>(csl, "getColors")?.let { colors ->
          changed = updateColors(colors)
        }
      }
      if (changed && Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
        Reflection.invoke<Any?>(csl, "onColorsChanged")
      }
    } catch (e: Exception) {
      Cyanea.log(TAG, "Error tinting ColorStateList", e)
    }
    csl
  }
}

@JvmOverloads
fun tint(view: View, recursive: Boolean = true) {
  try {
    var klass: Class<*>? = view.javaClass
    do {
      klass?.declaredFields?.forEach { field ->
        if (Modifier.isStatic(field.modifiers)) return@forEach
        if (field.type == ColorStateList::class.java) {
          get<ColorStateList>(field, view)?.let { csl ->
            tint(csl)
          }
        } else if (field.type == Drawable::class.java) {
          get<Drawable>(field, view)?.let { drawable ->
            tint(drawable)
          }
        }
      }
      klass = klass?.superclass
    } while (klass != null)
  } catch (e: Exception) {
    Cyanea.log(TAG, "Error tinting view: $view", e)
  }
  if (recursive && view is ViewGroup) {
    for (i in 0 until view.childCount) {
      view.getChildAt(i)?.let { v ->
        tint(v, recursive)
      }
    }
  }
}

@Suppress("DEPRECATION")
internal fun setup(original: Resources, resources: CyaneaResources) {
