    for (i in 0 until menu.size()) {
      val menuItem = menu.getItem(i)
      if (isInOverflow(menuItem)) {
        colorMenuItem(menuItem, subIconColor, subIconAlpha)
      }
      colorSubMenus(menuItem, subIconColor, subIconAlpha)
    }

