@JvmStatic
@ColorInt
fun adjustAlpha(@ColorInt color: Int, @FloatRange(from = 0.0, to = 1.0) factor: Float): Int {
  val alpha = Math.round(Color.alpha(color) * factor)
  val red = Color.red(color)
  val green = Color.green(color)
  val blue = Color.blue(color)
  return Color.argb(alpha, red, green, blue)
}

@JvmStatic
@ColorInt
fun parseColor(colorString: String): Int {
  try {
    if (colorString.startsWith("#")) {
      return parseColor(colorString.substring(1))
    }

    val length = colorString.length
    val a: Int
    var r: Int
    val g: Int
    var b = 0

    when {
      length == 0 -> {
        r = 0
        a = 255
        g = 0
      }
      length <= 2 -> {
        a = 255
        r = 0
        b = Integer.parseInt(colorString, 16)
        g = 0
      }
      length == 3 -> {
        a = 255
        r = Integer.parseInt(colorString.substring(0, 1), 16)
        g = Integer.parseInt(colorString.substring(1, 2), 16)
        b = Integer.parseInt(colorString.substring(2, 3), 16)
      }
      length == 4 -> {
        a = 255
        r = Integer.parseInt(colorString.substring(0, 2), 16)
        g = r
        r = 0
        b = Integer.parseInt(colorString.substring(2, 4), 16)
      }
      length == 5 -> {
        a = 255
        r = Integer.parseInt(colorString.substring(0, 1), 16)
        g = Integer.parseInt(colorString.substring(1, 3), 16)
        b = Integer.parseInt(colorString.substring(3, 5), 16)
      }
      length == 6 -> {
        a = 255
        r = Integer.parseInt(colorString.substring(0, 2), 16)
        g = Integer.parseInt(colorString.substring(2, 4), 16)
        b = Integer.parseInt(colorString.substring(4, 6), 16)
      }
      length == 7 -> {
        a = Integer.parseInt(colorString.substring(0, 1), 16)
        r = Integer.parseInt(colorString.substring(1, 3), 16)
        g = Integer.parseInt(colorString.substring(3, 5), 16)
        b = Integer.parseInt(colorString.substring(5, 7), 16)
      }
      length == 8 -> {
        a = Integer.parseInt(colorString.substring(0, 2), 16)
        r = Integer.parseInt(colorString.substring(2, 4), 16)
        g = Integer.parseInt(colorString.substring(4, 6), 16)
        b = Integer.parseInt(colorString.substring(6, 8), 16)
      }
      else -> {
        b = -1
        g = -1
        r = -1
        a = -1
      }
    }
    return Color.argb(a, r, g, b)
  } catch (e: NumberFormatException) {
    return Color.parseColor(colorString)
  }
}

class Reflection private constructor() {

  init {
    throw AssertionError("no instances")
  }

  companion object {

    private val CACHE = mutableMapOf<String, AccessibleObject>()

    /**
     * Dynamically invoke a method.
     *
     * @param obj
     *     The object or class to get the method from.
     * @param name
     *     The name of the method to invoke.
     * @param types
     *     the parameter types of the requested method.
     * @param args
     *     the arguments to the method
     * @param <T>
     *     the method's return type
     * @return the result of dynamically invoking this method.
     */
    @JvmStatic
    fun <T> invoke(
      obj: Any?,
      name: String,
      types: Array<Class<*>> = emptyArray(),
      vararg args: Any
    ): T? {
      try {
        val method = getMethod(obj, name, *types)
        method?.let {
          @Suppress("UNCHECKED_CAST")
          return method.invoke(obj, *args) as? T
        }
      } catch (e: Exception) {
        e.printStackTrace()
      }
      return null
    }

    /**
     * Get the value from a field in an object/class.
     *
     * @param obj
     *     the object or class
     * @param name
     *     the name of the field
     * @param <T>
     *     The field's type
     * @return the value of the field in the specified object.
     */
    @JvmStatic
    fun <T> getFieldValue(obj: Any?, name: String): T? {
      val field = getField(obj, name)
      field?.let {
        if (!field.isAccessible) field.isAccessible = true
        try {
          @Suppress("UNCHECKED_CAST")
          return field.get(obj) as? T
        } catch (e: IllegalAccessException) {
          e.printStackTrace()
        }
      }
      return null
    }

    /**
     * Set the field value to the specified value.
     *
     * @param field
     *     the field
     * @param obj
     *     the object whose field should be modified
     * @param value
     *     the new value for the field of `obj` being modified
     * @return `true` if the field was set successfully.
     */
    @JvmStatic
    fun setFieldValue(field: Field, obj: Any?, value: Any?): Boolean {
      if (!field.isAccessible) {
        field.isAccessible = true
      }
      try {
        if (Modifier.isFinal(field.modifiers)) {
          val modifiersField = Field::class.java.getDeclaredField("modifiers")
          modifiersField.isAccessible = true
          modifiersField.setInt(field, field.modifiers and Modifier.FINAL.inv())
        }
        field.set(obj, value)
        return true
      } catch (e: IllegalAccessException) {
        e.printStackTrace()
      }
      return false
    }

    /**
     * Get a method from a class
     *
     * @param obj
     *     the object or class.
     * @param name
     *     the requested method's name
     * @param types
     *     the parameter types of the requested method.
     * @return a [Method] object which represents the method matching the specified name and parameter types
     */
    @JvmStatic
    fun getMethod(obj: Any?, name: String, vararg types: Class<*>): Method? {
      if (obj == null) return null

      val key = cacheKey(obj, name, *types)
      var method: Method? = CACHE[key] as? Method
      if (method != null) return method

      var klass: Class<*>? = obj as? Class<*> ?: obj.javaClass

      while (klass != null) {
        try {
          method = klass.getDeclaredMethod(name, *types).also { it.isAccessible = true }
          break
        } catch (ignored: NoSuchMethodException) {
        }
        klass = klass.superclass
      }

      method?.let { CACHE.put(key, method) }

      return method
    }

    /**
     * Get a field from a class.
     *
     * @param obj
     *     the object or class
     * @param name
     *     the name of the field
     * @return a [Field] object for the field with the given name which is declared in the class.
     */
    @JvmStatic
    fun getField(obj: Any?, name: String): Field? {
      if (obj == null) return null

      val key = cacheKey(obj, name)
      var field: Field? = CACHE[key] as? Field
      if (field != null) return field

      var klass: Class<*>? = obj as? Class<*> ?: obj.javaClass

      do {
        try {
          field = klass?.getDeclaredField(name)
          if (field != null) {
            field.isAccessible = true
          }
        } catch (ignored: NoSuchFieldException) {
        }
        if (field == null) {
          klass = klass?.superclass
        }
      } while (field == null && klass != null)

      field?.let { CACHE.put(key, it) }

      return field
    }

    private fun cacheKey(obj: Any, name: String, vararg types: Class<*>): String {
      val klass = obj as? Class<*> ?: obj::class.java
      val key = StringBuilder(klass.name)
      key.append('#')
      key.append(name)
      if (types.isNotEmpty()) {
        var separator = ""
        key.append('(')
        types.forEach {
          key.append(separator)
          key.append(it.name)
          separator = ", "
        }
        key.append(')')
      }
      return key.toString()
    }
  }
}

