open class HttpException(
    statusCode: Int, message: String
) : RuntimeException("Http $statusCode: $message")

class HttpManager @JvmOverloads constructor(
    private val timeoutMillis: Int = Constants.TIME_OUT_MILLIS
) : IHttpManager {

    @Volatile
    private var isCancel = false

    override fun download(
        url: String,
        filepath: String,
        headers: Map<String, String>?
    ): Flow<DownloadState> {
        return flow {
            isCancel = false
            emit(DownloadState.Start(url))
            startDownload(url, filepath, headers)
        }.catch {
            LogX.w(it)
            emit(DownloadState.Error(it))
        }.flowOn(Dispatchers.IO)
    }

    private suspend fun FlowCollector<DownloadState>.startDownload(
        url: String,
        filepath: String,
        headers: Map<String, String>?,
    ) {

        val connection = (URL(url).openConnection() as HttpURLConnection).apply {
            requestMethod = "GET"
            setRequestProperty("Accept-Encoding", "identity")

            readTimeout = timeoutMillis
            connectTimeout = timeoutMillis

            headers?.forEach { (key, value) ->
                setRequestProperty(key, value)
            }
        }

        LogX.d("Content-Type: ${connection.contentType}")

        when (val responseCode = connection.responseCode) {

            HttpURLConnection.HTTP_OK -> {

                val length = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
                    connection.contentLengthLong
                } else {
                    connection.contentLength.toLong()
                }
                val outputFile = File(filepath)
                try {
                    connection.inputStream.use { inputStream ->
                        FileOutputStream(outputFile).use { outputStream ->
                            val buffer = ByteArray(8192)
                            var progress = 0L
                            while (true) {
                                val bytesRead = inputStream.read(buffer)
                                if (bytesRead == -1 || isCancel) break

                                outputStream.write(buffer, 0, bytesRead)
                                progress += bytesRead

                                emit(DownloadState.Progress(progress, length))
                            }
                            outputStream.flush()

                            check(progress > 0 || length > 0) {
                                "Invalid download state: progress=$progress, contentLength=$length"
                            }
                        }
                    }

                    if (isCancel) {
                        emit(DownloadState.Cancel)
                    } else {
                        emit(DownloadState.Success(outputFile))
                    }
                } finally {
                    connection.disconnect()
                }
            }

            HttpURLConnection.HTTP_MULT_CHOICE,
            HttpURLConnection.HTTP_MOVED_PERM,
            HttpURLConnection.HTTP_MOVED_TEMP,
            HttpURLConnection.HTTP_SEE_OTHER,
            Constants.HTTP_TEMP_REDIRECT,
            Constants.HTTP_PERM_REDIRECT -> {
                // 重定向
                val redirectUrl = connection.getHeaderField("Location")
                LogX.d("Redirect url: $redirectUrl")

                connection.disconnect()

                download(redirectUrl, filepath, headers)
            }

            else -> {
                throw HttpException(responseCode, connection.responseMessage ?: "HTTP Error.")
            }
        }
    }

    override fun cancel() {
        isCancel = true
    }

    companion object {

        private val INSTANCE by lazy {
            HttpManager()
        }

        /**
         * 获取实例
         */
        @JvmStatic
        fun getInstance(): HttpManager {
            return INSTANCE
        }
    }
}

class OkHttpManager(private val okHttpClient: OkHttpClient) : IHttpManager {

    @JvmOverloads
    constructor(timeoutMillis: Int = Constants.TIME_OUT_MILLIS) : this(
        okHttpClient = OkHttpClient.Builder()
            .readTimeout(timeoutMillis.toLong(), TimeUnit.MILLISECONDS)
            .connectTimeout(timeoutMillis.toLong(), TimeUnit.MILLISECONDS)
            .sslSocketFactory(
                SSLSocketFactoryUtils.createSSLSocketFactory(),
                SSLSocketFactoryUtils.createTrustAllX509TrustManager()
            )
            .hostnameVerifier(SSLSocketFactoryUtils.createAllowAllHostnameVerifier())
            .build()
    )

    @Volatile
    private var isCancel = false

    override fun download(
        url: String,
        filepath: String,
        headers: Map<String, String>?
    ): Flow<DownloadState> {
        return flow {
            isCancel = false
            emit(DownloadState.Start(url))
            startDownload(url, filepath, headers)
        }.catch {
            LogX.w(it)
            emit(DownloadState.Error(it))
        }.flowOn(Dispatchers.IO)
    }

    private suspend fun FlowCollector<DownloadState>.startDownload(
        url: String,
        filepath: String,
        headers: Map<String, String>?,
    ) {
        val builder: Request.Builder = Request.Builder()
            .url(url)
            .addHeader("Accept-Encoding", "identity")
            .get()

        headers?.forEach {
            builder.addHeader(it.key, it.value)
        }

        val call = okHttpClient.newCall(builder.build())
        val response = call.execute()

        LogX.d("Content-Type: ${response.headers["Content-Type"]}")

        if (response.isSuccessful) {
            try {
                val body = response.body ?: throw IllegalStateException("Response body is null.")

                val length = body.contentLength()
                val outputFile = File(filepath)

                body.byteStream().use { inputStream ->
                    FileOutputStream(outputFile).use { outputStream ->
                        val buffer = ByteArray(8192)
                        var progress = 0L
                        while (true) {
                            val bytesRead = inputStream.read(buffer)
                            if (bytesRead == -1 || isCancel) break

                            outputStream.write(buffer, 0, bytesRead)
                            progress += bytesRead

                            emit(DownloadState.Progress(progress, length))
                        }
                        outputStream.flush()

                        check(progress > 0 || length > 0) {
                            "Invalid download state: progress=$progress, contentLength=$length"
                        }
                    }
                }

                if (isCancel) {
                    emit(DownloadState.Cancel)
                } else {
                    emit(DownloadState.Success(outputFile))
                }
            } finally {
                response.closeQuietly()
            }
        } else {
            throw HttpException(response.code, response.message)
        }
    }

    override fun cancel() {
        isCancel = true
    }

    companion object {

        private val INSTANCE by lazy {
            OkHttpManager()
        }

        /**
         * 获取实例
         */
        @JvmStatic
        fun getInstance(): OkHttpManager {
            return INSTANCE
        }
    }
}

