            )
        }

    val androidViewModifier = if (onClick != null && !isTextSelectable) {
        Modifier
            .clickable { onClick() }
            .then(modifier)
    } else {
        modifier
    }

    // Create a stable key based on markdown content hash for proper LazyColumn recycling
    val contentKey = remember(markdown) {
