                            TextViewCompat.setAutoSizeTextTypeUniformWithConfiguration(
                                this,
                                config.autoSizeMinTextSize,
                                config.autoSizeMaxTextSize,
                                config.autoSizeStepGranularity,
                                config.unit
                            )
                        }
                    }
                }
            },
            update = { textView ->
