@DisableCachingByDefault(because = "Explicit maintainer operation inspects the current proposed Git revision")
abstract class CandidateMcuUpstreamLock : DefaultTask() {
    @get:Internal
    abstract val upstreamDirectory: DirectoryProperty

    @get:OutputFile
    abstract val candidateFile: RegularFileProperty

    @get:Inject
    protected abstract val execOperations: ExecOperations

    init {
        outputs.upToDateWhen { false }
    }

    @TaskAction
    fun candidate() {
        val upstream = upstreamDirectory.get().asFile
        val git = McuGit(execOperations)
        if (git.run(upstream, "status", "--porcelain", "--untracked-files=all").isNotEmpty()) {
            throw GradleException("Candidate MCU input must be clean before recording hashes")
        }

        val sources = upstream.toPath().resolve("kotlin")
        val candidate = linkedMapOf<String, Any>(
            "schemaVersion" to McuLockSchema.SCHEMA_VERSION,
            "policyVersion" to McuLockSchema.POLICY_VERSION,
            "upstreamRevision" to git.run(upstream, "rev-parse", "HEAD"),
            "licenseSha256" to McuUpstreamLock.hash(upstream.toPath().resolve("LICENSE")),
        )

        val hashes = linkedMapOf<String, String>()
        for (path in McuUpstreamLock.kotlinSourcePaths(sources)) {
            hashes[path] = McuUpstreamLock.hash(sources.resolve(path))
        }

        if (hashes.isEmpty()) {
            throw GradleException("Candidate has no Kotlin source tree")
        }

        candidate["files"] = hashes

        val output = candidateFile.get().asFile.toPath()
        Files.createDirectories(output.parent)
        Files.writeString(output, JsonOutput.prettyPrint(JsonOutput.toJson(candidate)) + "\n")
        logger.lifecycle(
            "Wrote candidate only: {}. Review source, rules and parity before replacing the tracked lock.",
            output,
        )
    }
}

@CacheableTask
abstract class GenerateMcuSources : JavaExec() {
    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val sourceDirectory: DirectoryProperty

    @get:InputFile
    @get:PathSensitive(PathSensitivity.NONE)
    abstract val lockFile: RegularFileProperty

    @get:InputFile
    @get:PathSensitive(PathSensitivity.NONE)
    abstract val licenseFile: RegularFileProperty

    @get:OutputDirectory
    abstract val outputDirectory: DirectoryProperty

    @get:OutputFile
    abstract val reportFile: RegularFileProperty

    @get:Input
    abstract val mode: Property<String>

    @get:Input
    abstract val parserVersion: Property<String>

    private var unexpectedFiles: Boolean? = null

    init {
        mainClass.set("com.materialkolor.transformer.MainKt")
        mode.convention("library")
        maxHeapSize = "512m"
        outputs.upToDateWhen { task -> !(task as GenerateMcuSources).hasUnexpectedFiles() }
        outputs.doNotCacheIf("Unexpected files in the exclusively owned generated tree") { task ->
            (task as GenerateMcuSources).hasUnexpectedFiles()
        }
    }

    /**
     * Whether the generated tree holds anything the reviewed lock does not account for.
     *
     * Gradle asks both the up-to-date check and the cacheability check, so the answer is read
     * once per task instance instead of reparsing the lock and re-walking the tree each time.
     */
    private fun hasUnexpectedFiles(): Boolean {
        unexpectedFiles?.let { cached -> return cached }

        val actual = TreeSet(McuUpstreamLock.allPaths(outputDirectory.get().asFile.toPath()))
        actual.removeAll(McuUpstreamLock(lockFile.get().asFile).files.keys)

        val result = actual.isNotEmpty()
        unexpectedFiles = result

        return result
    }

    @TaskAction
    override fun exec() {
        args = listOf(
            sourceDirectory.get().asFile.absolutePath,
            outputDirectory.get().asFile.absolutePath,
            reportFile.get().asFile.absolutePath,
            lockFile.get().asFile.absolutePath,
            mode.get(),
            parserVersion.get(),
        )

        super.exec()
    }
}

private fun hasUnexpectedFiles(): Boolean {
    unexpectedFiles?.let { cached -> return cached }

    val actual = TreeSet(McuUpstreamLock.allPaths(outputDirectory.get().asFile.toPath()))
    actual.removeAll(McuUpstreamLock(lockFile.get().asFile).files.keys)

    val result = actual.isNotEmpty()
    unexpectedFiles = result

    return result
}

internal object McuLockSchema {
    /**
     * Layout of the lock file itself. Bump together with SourceLock.kt.
     */
    const val SCHEMA_VERSION = 1

    /**
     * Transformation policy the lock was reviewed against. Bump together with SourceLock.kt.
     */
    const val POLICY_VERSION = 1

    /**
     * Upstream revisions are recorded as full lowercase Git object names.
     */
    const val REVISION_PATTERN = "[0-9a-f]{40}"

    /**
     * Content digests are recorded as lowercase SHA-256 hex.
     */
    const val HASH_PATTERN = "[0-9a-f]{64}"

    /**
     * Locked sources are Kotlin files one directory below the upstream Kotlin tree.
     */
    const val SOURCE_PATH_PATTERN = """[a-z]+/[A-Za-z][A-Za-z0-9]*\.kt"""
}

internal class McuUpstreamLock(file: File) {
    val revision: String
    val licenseHash: String
    val files: Map<String, String>

    init {
        val json = JsonSlurper().parse(file, "UTF-8") as Map<*, *>
        if (json["schemaVersion"] != McuLockSchema.SCHEMA_VERSION ||
            json["policyVersion"] != McuLockSchema.POLICY_VERSION
        ) {
            throw GradleException("Unsupported MCU lock schema or transformation policy: $file")
        }

        revision = string(json["upstreamRevision"], McuLockSchema.REVISION_PATTERN, "revision", file)
        licenseHash = string(json["licenseSha256"], McuLockSchema.HASH_PATTERN, "license hash", file)
        files = inventory(json["files"], file)
    }

    fun verify(source: Path) {
        val actual = kotlinSourcePaths(source)
        if (actual != files.keys) {
            val missing = TreeSet(files.keys).apply { removeAll(actual) }
            val added = TreeSet(actual).apply { removeAll(files.keys) }
            throw GradleException("MCU source inventory drift; missing=$missing, added=$added")
        }

        for ((path, expected) in files) {
            if (hash(source.resolve(path)) != expected) {
                throw GradleException(
                    "MCU source hash changed: $path; review the upstream pin and lock together",
                )
            }
        }

        if (hash(source.parent.resolve("LICENSE")) != licenseHash) {
            throw GradleException("MCU upstream LICENSE changed; review its lock hash")
        }
    }

    companion object {
        private fun string(value: Any?, pattern: String, field: String, file: File): String {
            if (value !is String || !value.matches(Regex(pattern))) {
                throw GradleException("Malformed MCU source lock $field: $file")
            }

            return value
        }

        private fun inventory(value: Any?, file: File): Map<String, String> {
            if (value !is Map<*, *> || value.isEmpty()) {
                throw GradleException("Malformed MCU source lock inventory: $file")
            }

            for ((path, hash) in value) {
                if (path !is String || !path.matches(Regex(McuLockSchema.SOURCE_PATH_PATTERN))) {
                    throw GradleException("Unsafe MCU lock path: $path")
                }
                string(hash, McuLockSchema.HASH_PATTERN, "hash for $path", file)
            }

            @Suppress("UNCHECKED_CAST")
            return value as Map<String, String>
        }

        /**
         * Every Kotlin source under [root], as slash-separated paths relative to it.
         */
        fun kotlinSourcePaths(root: Path): Set<String> = relativePaths(root) { path ->
            path.toString().endsWith(".kt")
        }

        /**
         * Every regular file under [root], as slash-separated paths relative to it.
         */
        fun allPaths(root: Path): Set<String> = relativePaths(root) { true }

        private fun relativePaths(root: Path, include: (Path) -> Boolean): Set<String> {
            if (!Files.isDirectory(root)) {
                return emptySet()
            }
            Files.walk(root).use { stream ->
                return stream.iterator().asSequence()
                    .filter { path -> Files.isRegularFile(path) && include(path) }
                    .map { path -> root.relativize(path).toString().replace(File.separatorChar, '/') }
                    .toCollection(TreeSet())
            }
        }

        fun hash(path: Path): String = hash(Files.readAllBytes(path))

        fun hash(content: ByteArray): String =
            HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(content))
    }
}

fun kotlinSourcePaths(root: Path): Set<String> = relativePaths(root) { path ->
    path.toString().endsWith(".kt")
}

@DisableCachingByDefault(because = "Comparing two locally generated trees is cheaper than a cache round trip")
abstract class VerifyMcuParserAgreement : DefaultTask() {
    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val primaryDirectory: DirectoryProperty

    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val alternateDirectory: DirectoryProperty

    @TaskAction
    fun verify() {
        val primaryRoot = primaryDirectory.get().asFile.toPath()
        val alternateRoot = alternateDirectory.get().asFile.toPath()

        val primaryPaths = TreeSet(McuUpstreamLock.allPaths(primaryRoot))
        val alternatePaths = TreeSet(McuUpstreamLock.allPaths(alternateRoot))
        if (primaryPaths != alternatePaths) {
            throw GradleException(
                "MCU parser disagreement in the generated file inventory. " +
                    "Pinned parser only: ${primaryPaths - alternatePaths}. " +
                    "Alternate parser only: ${alternatePaths - primaryPaths}.",
            )
        }

        val divergent = primaryPaths.filter { path ->
            Files.mismatch(primaryRoot.resolve(path), alternateRoot.resolve(path)) >= 0
        }

        if (divergent.isNotEmpty()) {
            throw GradleException(
                "MCU parser disagreement. The pinned and alternate front ends generated different " +
                    "text for ${divergent.size} file(s), so the output depends on the parser " +
                    "version instead of the reviewed rules alone: $divergent",
            )
        }
    }
}

