fun announce(message: String) {
    val region = install()
    pendingFrame?.let { frame -> window.cancelAnimationFrame(frame) }
    region.textContent = ""
    pendingFrame =
        window.requestAnimationFrame { _ ->
            pendingFrame = null
            region.textContent = message
