internal class CodeWriter {
    private val lines = mutableListOf<List<Token>>()
    private var depth = 0

    val result: List<List<Token>>
        get() = lines.toList()

    fun blankLine() {
        lines.add(emptyList())
    }

    fun line(tokens: List<Token>) {
        if (tokens.isEmpty()) {
            blankLine()
        } else {
            lines += if (depth == 0) tokens else listOf(plainToken(INDENT.repeat(depth))) + tokens
        }
    }

    fun indented(body: () -> Unit) {
        depth++
        body()
        depth--
    }

    fun fits(tokens: List<Token>): Boolean = depth * INDENT.length + tokens.sumOf { it.text.length } <= MAX_LINE_LENGTH

    /**
     * Writes [value] between [prefix] and [suffix], on one line when it fits and nothing inside it
     * insists on breaking.
     */
    fun expression(
        value: Expression,
        prefix: List<Token> = emptyList(),
        suffix: List<Token> = emptyList(),
    ) {
        val flat = prefix + value.tokens + suffix
        val shape = value.shape
        if (shape == null || (!value.breaksOnItsOwn && fits(flat))) {
            line(flat)
            return
        }

        when (shape) {
            is CallShape -> call(shape, flat, prefix, suffix)
            is LambdaShape -> lambda(shape, prefix, suffix)
            is IfElseShape -> ifElse(shape, prefix, suffix)
            is WhenShape -> whenBlock(shape, prefix, suffix)
            is JoinedShape -> expression(shape.inner, prefix + shape.head, shape.tail + suffix)
        }
    }

    /**
     * A call past the column limit.
     *
     * Without a trailing lambda the arguments go one per line. With one, the lambda breaks first and
     * the arguments stay on the opening line for as long as they fit there.
     */
    private fun call(
        shape: CallShape,
        flat: List<Token>,
        prefix: List<Token>,
        suffix: List<Token>,
    ) {
        val trailing = shape.trailing
        if (trailing == null) {
            if (shape.arguments.isEmpty()) {
                line(flat)
            } else {
                line(prefix + shape.callee + punctuationToken("("))
                arguments(shape.arguments)
                line(listOf(punctuationToken(")")) + suffix)
            }
            return
        }

        val opening = prefix + shape.callee + shape.flatArguments + spaceToken
        if (shape.arguments.isEmpty() || (!shape.argumentsBreak && fits(opening + trailing.open))) {
            lambda(trailing, opening, suffix)
        } else {
            line(prefix + shape.callee + punctuationToken("("))
            arguments(shape.arguments)
            lambda(trailing, listOf(punctuationToken(")"), spaceToken), suffix)
        }
    }

    private fun arguments(arguments: List<RenderedArgument>) {
        indented {
            arguments.forEach { argument ->
                expression(argument.value, argument.prefix, listOf(punctuationToken(",")))
            }
        }
    }

    /**
     * A lambda with its statements below the opening brace, or `{}` when there are none.
     */
    private fun lambda(
        shape: LambdaShape,
        prefix: List<Token>,
        suffix: List<Token>,
    ) {
        if (shape.isEmpty) {
            line(prefix + shape.tokens + suffix)
            return
        }

        line(prefix + shape.open)
        indented { shape.body.render(this) }
        line(listOf(punctuationToken("}")) + suffix)
    }

    private fun ifElse(
        shape: IfElseShape,
        prefix: List<Token>,
        suffix: List<Token>,
    ) {
        line(prefix + shape.open)
        indented { expression(shape.whenTrue) }
        elseBranch(shape.whenFalse, suffix)
    }

    /**
     * The `else` side of a broken if, following an `else if` chain down to its last branch.
     */
    private fun elseBranch(
        value: Expression,
        suffix: List<Token>,
    ) {
        val closing = listOf(punctuationToken("}"), spaceToken, keywordToken("else"), spaceToken)
        val chained = value.shape
        if (chained is IfElseShape) {
            line(closing + chained.open)
            indented { expression(chained.whenTrue) }
            elseBranch(chained.whenFalse, suffix)
        } else {
            line(closing + punctuationToken("{"))
            indented { expression(value) }
            line(listOf(punctuationToken("}")) + suffix)
        }
    }

    private fun whenBlock(
        shape: WhenShape,
        prefix: List<Token>,
        suffix: List<Token>,
    ) {
        val arrow = listOf(spaceToken, punctuationToken("->"), spaceToken)
        line(prefix + shape.open)
        indented {
            shape.branches.forEach { branch -> expression(branch.value, branch.condition.tokens + arrow) }
            shape.otherwise?.let { otherwise -> expression(otherwise, listOf(keywordToken("else")) + arrow) }
        }
        line(listOf(punctuationToken("}")) + suffix)
    }
}

fun expression(
    value: Expression,
    prefix: List<Token> = emptyList(),
    suffix: List<Token> = emptyList(),
) {
    val flat = prefix + value.tokens + suffix
    val shape = value.shape
    if (shape == null || (!value.breaksOnItsOwn && fits(flat))) {
        line(flat)
        return
    }

    when (shape) {
        is CallShape -> call(shape, flat, prefix, suffix)
        is LambdaShape -> lambda(shape, prefix, suffix)
        is IfElseShape -> ifElse(shape, prefix, suffix)
        is WhenShape -> whenBlock(shape, prefix, suffix)
        is JoinedShape -> expression(shape.inner, prefix + shape.head, shape.tail + suffix)
    }
}

private fun call(
    shape: CallShape,
    flat: List<Token>,
    prefix: List<Token>,
    suffix: List<Token>,
) {
    val trailing = shape.trailing
    if (trailing == null) {
        if (shape.arguments.isEmpty()) {
            line(flat)
        } else {
            line(prefix + shape.callee + punctuationToken("("))
            arguments(shape.arguments)
            line(listOf(punctuationToken(")")) + suffix)
        }
        return
    }

    val opening = prefix + shape.callee + shape.flatArguments + spaceToken
    if (shape.arguments.isEmpty() || (!shape.argumentsBreak && fits(opening + trailing.open))) {
        lambda(trailing, opening, suffix)
    } else {
        line(prefix + shape.callee + punctuationToken("("))
        arguments(shape.arguments)
        lambda(trailing, listOf(punctuationToken(")"), spaceToken), suffix)
    }
}

private fun lambda(
    shape: LambdaShape,
    prefix: List<Token>,
    suffix: List<Token>,
) {
    if (shape.isEmpty) {
        line(prefix + shape.tokens + suffix)
        return
    }

    line(prefix + shape.open)
    indented { shape.body.render(this) }
    line(listOf(punctuationToken("}")) + suffix)
}

private fun elseBranch(
    value: Expression,
    suffix: List<Token>,
) {
    val closing = listOf(punctuationToken("}"), spaceToken, keywordToken("else"), spaceToken)
    val chained = value.shape
    if (chained is IfElseShape) {
        line(closing + chained.open)
        indented { expression(chained.whenTrue) }
        elseBranch(chained.whenFalse, suffix)
    } else {
        line(closing + punctuationToken("{"))
        indented { expression(value) }
        line(listOf(punctuationToken("}")) + suffix)
    }
}

public fun ifElse(
    condition: Expression,
    whenTrue: Expression,
    whenFalse: Expression,
): Expression {
    require(!condition.breaksOnItsOwn) { "The condition of an if has to fit on one line" }
    val shape = IfElseShape(condition, whenTrue, whenFalse)

    return Expression(
        tokens = buildList {
            addAll(shape.keyword)
            addAll(whenTrue.tokens)
            add(spaceToken)
            add(keywordToken("else"))
            add(spaceToken)
            addAll(whenFalse.tokens)
        },
        symbols = condition.symbols + whenTrue.symbols + whenFalse.symbols,
        shape = shape,
        breaksOnItsOwn = whenTrue.breaksOnItsOwn ||
            whenFalse.breaksOnItsOwn ||
            whenTrue.shape is IfElseShape ||
            whenFalse.shape is IfElseShape,
    )
}

public fun whenExpression(
    subject: Expression? = null,
    build: WhenScope.() -> Unit,
): Expression {
    require(subject?.breaksOnItsOwn != true) { "The subject of a when has to fit on one line" }
    val scope = WhenScope().apply(build)
    val branches = scope.branches.toList()
    val otherwise = scope.otherwise
    require(branches.isNotEmpty() || otherwise != null) { "A when needs at least one branch" }
    val shape = WhenShape(subject, branches, otherwise)

    return Expression(
        tokens = shape.open + punctuationToken("}"),
        symbols = subject?.symbols.orEmpty() +
            branches.flatMap { it.condition.symbols + it.value.symbols } +
            otherwise?.symbols.orEmpty(),
        shape = shape,
        breaksOnItsOwn = true,
    )
}

@CodegenDsl
public class WhenScope internal constructor() {
    internal val branches: MutableList<WhenBranch> = mutableListOf()
    internal var otherwise: Expression? = null

    /**
     * `condition -> value`.
     */
    public fun branch(
        condition: Expression,
        value: Expression,
    ) {
        require(!condition.breaksOnItsOwn) { "A when condition has to fit on one line" }
        branches += WhenBranch(condition, value)
    }

    /**
     * The `else ->` branch, which is written last wherever it was added.
     */
    public fun otherwise(value: Expression) {
        require(otherwise == null) { "A when has one else branch" }
        otherwise = value
    }

    /**
     * A call used as a branch value, offered here for the same reason [ArgumentsScope.call] is.
     */
    public fun call(
        symbol: Symbol,
        multiline: Boolean = false,
        build: ArgumentsScope.() -> Unit = {},
    ): Expression = buildCall(listOf(functionToken(symbol.simpleName)), listOf(symbol), multiline, build)

    /**
     * The same, for a function that is already in scope.
     */
    public fun call(
        name: String,
        multiline: Boolean = false,
        build: ArgumentsScope.() -> Unit = {},
    ): Expression = buildCall(listOf(functionToken(name)), emptyList(), multiline, build)
}

public fun branch(
    condition: Expression,
    value: Expression,
) {
    require(!condition.breaksOnItsOwn) { "A when condition has to fit on one line" }
    branches += WhenBranch(condition, value)
}

public fun otherwise(value: Expression) {
    require(otherwise == null) { "A when has one else branch" }
    otherwise = value
}

public fun call(
    symbol: Symbol,
    multiline: Boolean = false,
    build: ArgumentsScope.() -> Unit = {}

public fun call(
    name: String,
    multiline: Boolean = false,
    build: ArgumentsScope.() -> Unit = {}

public fun infix(
    left: Expression,
    name: String,
    right: Expression,
): Expression {
    require(!left.breaksOnItsOwn) { "The left side of an infix call has to fit on one line" }
    val head = left.tokens + listOf(spaceToken, functionToken(name), spaceToken)

    return Expression(
        tokens = head + right.tokens,
        symbols = left.symbols + right.symbols,
        shape = right.shape?.let { JoinedShape(head, right, emptyList()) },
        breaksOnItsOwn = right.breaksOnItsOwn,
    )
}

public fun classLiteral(symbol: Symbol): Expression =
    Expression(
        tokens = listOf(typeToken(symbol.simpleName), punctuationToken("::"), keywordToken("class")),
        symbols = listOf(symbol),
    )

public fun Expression.index(key: Expression): Expression {
    require(!breaksOnItsOwn) { "The receiver of an index has to fit on one line" }
    require(!key.breaksOnItsOwn) { "The key of an index has to fit on one line" }

    return Expression(
        tokens = tokens + punctuationToken("[") + key.tokens + punctuationToken("]"),
        symbols = symbols + key.symbols,
    )
}

