                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                '\b' -> append("\\b")
                else -> if (character.code < 0x20 || character.code == 0x7F) {
                    append("\\u")
                    for (shift in 12 downTo 0 step 4) {
                        append(HEX_DIGITS[(character.code ushr shift) and 0xF])
                    }
                } else {
                    append(character)
                }
            }
        }
    }

