@Immutable
@JvmInline
@Serializable(with = ArgbSerializer::class)
public value class Argb private constructor(
    public val value: Int,
) {
    /**
     * The red channel, 0 to 255.
     */
    public val red: Int
        get() = (value shr 16) and CHANNEL_MASK

    /**
     * The green channel, 0 to 255.
     */
    public val green: Int
        get() = (value shr 8) and CHANNEL_MASK

    /**
     * The blue channel, 0 to 255.
     */
    public val blue: Int
        get() = value and CHANNEL_MASK

    /**
     * The color as `#RRGGBB` in uppercase, the form share links and exported code use.
     *
     * The alpha byte is left out because it is always `0xFF`.
     */
    public fun toHex(): String = "#${red.toHexByte()}${green.toHexByte()}${blue.toHexByte()}"

    override fun toString(): String = toHex()

    public companion object {
        /**
         * Pack [value] as an opaque color, filling in the alpha byte.
         *
         * Every color is built here. The constructor takes its argument as given, and it wins the
         * name `Argb(...)` inside the class body and inside this companion, so write [invoke] by
         * name in those two places. Everywhere else, top level code in this file included, which
         * is where [ArgbSerializer] sits, `Argb(...)` already resolves to this function.
         */
        public operator fun invoke(value: Int): Argb = Argb(value or OPAQUE_ALPHA)

        /**
         * Read a color written as `#RRGGBB` or `#AARRGGBB`, with or without the leading `#`.
         *
         * The alpha byte of an eight digit color is read and then thrown away, the same way the
         * constructor treats it.
         *
         * @throws[IllegalArgumentException] when [hex] is not six or eight hex digits.
         */
        public fun fromHex(hex: String): Argb {
            val digits = hex.removePrefix("#")
            require(digits.length == 6 || digits.length == 8) { "Expected #RRGGBB or #AARRGGBB, got \"$hex\"" }
            return invoke(digits.toLong(radix = 16).toInt())
        }
    }
}

public fun fromHex(hex: String): Argb {
    val digits = hex.removePrefix("#")
    require(digits.length == 6 || digits.length == 8) { "Expected #RRGGBB or #AARRGGBB, got \"$hex\"" }
    return invoke(digits.toLong(radix = 16).toInt())
}

public object ArgbSerializer : KSerializer<Argb> {
    override val descriptor: SerialDescriptor =
        PrimitiveSerialDescriptor("com.materialkolor.builder.domain.color.Argb", PrimitiveKind.STRING)

    override fun serialize(
        encoder: Encoder,
        value: Argb,
    ) {
        encoder.encodeString(value.toHex())
    }

    override fun deserialize(decoder: Decoder): Argb = Argb.fromHex(decoder.decodeString())
}

public enum class ColorFormat {
    /**
     * Red as `#FF0000`.
     */
    Hex,

    /**
     * Red as `rgb(255 0 0)`, each channel from 0 to 255.
     */
    Rgb,

    /**
     * Red as `hsl(0 100% 50%)`, the hue in degrees, then saturation and lightness as percentages.
     */
    Hsl,

    /**
     * Red as about `oklch(0.62796 0.25768 29.234)`, lightness from 0 to 1, then chroma, then the hue in degrees.
     */
    Oklch,
}

public fun ColorFormat.textOf(color: Argb): String {
    val channels = channelsOf(color)
    return when (this) {
        ColorFormat.Hex -> {
            color.toHex()
        }
        ColorFormat.Rgb -> {
            "rgb(${channels.joinToString(" ") { channel -> channel.toDecimalText(0) }})"
        }
        ColorFormat.Hsl -> {
            val (hue, saturation, lightness) = channels.map { channel -> channel.toDecimalText(HslDecimals) }
            "hsl($hue $saturation% $lightness%)"
        }
        ColorFormat.Oklch -> {
            val lightness = channels[0].toDecimalText(OklchLightnessDecimals)
            val chroma = channels[1].toDecimalText(OklchChromaDecimals)
            val hue = channels[2].toDecimalText(OklchHueDecimals)
            "oklch($lightness $chroma $hue)"
        }
    }
}

internal fun srgbToHsl(rgb: Rgb): Hsl {
    val brightest = max(rgb.red, max(rgb.green, rgb.blue))
    val dimmest = min(rgb.red, min(rgb.green, rgb.blue))
    val lightness = (brightest + dimmest) / 2
    val spread = brightest - dimmest
    if (spread == 0.0) return Hsl(hue = 0.0, saturation = 0.0, lightness = lightness)
    val sixths = when (brightest) {
        rgb.red -> (rgb.green - rgb.blue) / spread + if (rgb.green < rgb.blue) 6 else 0
        rgb.green -> (rgb.blue - rgb.red) / spread + 2
        else -> (rgb.red - rgb.green) / spread + 4
    }
    val saturation = (brightest - lightness) / min(lightness, 1 - lightness)
    return Hsl(hue = sixths * DegreesPerSixth, saturation = saturation, lightness = lightness)
}

@Immutable
public sealed interface ParseResult {
    /**
     * The text is a color.
     *
     * @property[argb] The color, always opaque.
     * @property[notes] What had to change for the color to fit, empty when it was read exactly as written.
     */
    @Immutable
    public data class Ok(
        public val argb: Argb,
        public val notes: Set<ParseNote> = emptySet(),
    ) : ParseResult

    /**
     * The text is not a color, so the seed stays as it was.
     *
     * @property[reason] What went wrong, for the error under the field.
     */
    @Immutable
    public data class Invalid(
        public val reason: InvalidReason,
    ) : ParseResult
}

public enum class ParseNote {
    /**
     * The text asked for some transparency, and a seed is always opaque.
     */
    AlphaDropped,

    /**
     * A value was out of range, or an `oklch()` color was outside sRGB, and was pulled back inside.
     */
    Clamped,
}

public enum class InvalidReason {
    /**
     * There is no text, or only whitespace.
     */
    Empty,

    /**
     * Hex with the wrong number of digits, or with something in it that is not a hex digit.
     */
    BadHex,

    /**
     * A function the field knows, such as `rgb()`, with the wrong number or kind of values, or left unclosed.
     */
    BadArguments,

    /**
     * Something written like a function that the field does not know, such as `hwb()`.
     */
    UnknownFunction,

    /**
     * A word that is not one of the CSS named colors.
     */
    UnknownName,

    /**
     * Text that does not look like any of the accepted forms.
     */
    Unrecognized,
}

private fun parseComposeLiteral(body: String): ParseResult =
    if (body.startsWith("0x")) {
        parseHex(body.substring(2), allowShort = false)
    }

private class Arguments(
    val channels: List<String>,
    val alpha: String?,
)

private fun splitArguments(body: String): Arguments? {
    if (',' in body) {
        if ('/' in body) return null
        val parts = body.split(',').map { it.trim() }
        if (parts.any { part -> part.isEmpty() || ' ' in part }) return null
        return when (parts.size) {
            3 -> Arguments(channels = parts, alpha = null)
            4 -> Arguments(channels = parts.take(3), alpha = parts[3])
            else -> null
        }
    }
    val halves = body.split('/')
    if (halves.size > 2) return null
    val channels = halves[0].split(' ').filter { it.isNotEmpty() }
    val alpha = halves.getOrNull(1)?.trim()
    if (channels.size != 3 || alpha?.let { it.isEmpty() || ' ' in it } == true) return null
    return Arguments(channels, alpha)
}

private fun alphaOf(token: String?): Double? {
    if (token == null) return 1.0
    return Quantity.of(token)?.scaled(percentOf = 1.0)?.coerceIn(0.0, 1.0)
}

private class Quantity(
    val value: Double,
    val unit: QuantityUnit,
) {
    /**
     * The value as a plain number, where 100% stands for [percentOf]. Angles are not plain numbers.
     */
    fun scaled(percentOf: Double): Double? =
        when (unit) {
            QuantityUnit.None -> value
            QuantityUnit.Percent -> value * percentOf / 100
            QuantityUnit.Degrees, QuantityUnit.Radians, QuantityUnit.Gradians, QuantityUnit.Turns -> null
        }

    companion object {
        fun of(token: String): Quantity? {
            val match = QuantityPattern.matchEntire(token) ?: return null
            val number = match.groupValues[1].removePrefix("+").toDoubleOrNull() ?: return null
            if (!number.isFinite()) return null
            val unit =
                when (match.groupValues[2]) {
                    "" -> QuantityUnit.None
                    "%" -> QuantityUnit.Percent
                    "deg" -> QuantityUnit.Degrees
                    "rad" -> QuantityUnit.Radians
                    "grad" -> QuantityUnit.Gradians
                    "turn" -> QuantityUnit.Turns
                    else -> return null
                }
            return Quantity(number, unit)
        }
    }
}

fun scaled(percentOf: Double): Double? =
    when (unit) {
        QuantityUnit.None -> value
        QuantityUnit.Percent -> value * percentOf / 100
        QuantityUnit.Degrees, QuantityUnit.Radians, QuantityUnit.Gradians, QuantityUnit.Turns -> null
    }

internal class NamedColor(
    val argb: Argb,
    val name: String,
) {
    val oklab: Oklab = argb.toOklab()
}

internal data class Oklab(
    val l: Double,
    val a: Double,
    val b: Double,
) {
    /**
     * The squared distance to [other], which is enough to find the nearest of several colors.
     */
    fun distanceSquaredTo(other: Oklab): Double {
        val dl = l - other.l
        val da = a - other.a
        val db = b - other.b
        return dl * dl + da * da + db * db
    }

    fun toOklch(): Oklch {
        val hue = atan2(b, a) * DegreesPerRadian
        return Oklch(l = l, c = hypot(a, b), h = if (hue < 0) hue + FullTurn else hue)
    }
}

fun distanceSquaredTo(other: Oklab): Double {
    val dl = l - other.l
    val da = a - other.a
    val db = b - other.b
    return dl * dl + da * da + db * db
}

internal data class Oklch(
    val l: Double,
    val c: Double,
    val h: Double,
) {
    fun toOklab(): Oklab {
        val radians = h / DegreesPerRadian
        return Oklab(l = l, a = c * cos(radians), b = c * sin(radians))
    }
}

internal object ColorSpaces {
    /**
     * Undo the sRGB transfer curve for one channel.
     */
    fun srgbToLinear(channel: Double): Double =
        if (channel <= 0.04045) channel / 12.92 else ((channel + 0.055) / 1.055).pow(2.4)

    /**
     * Apply the sRGB transfer curve to one channel, mirrored around zero so a negative channel stays negative
     * and can still be told apart from an in gamut one.
     */
    fun linearToSrgb(channel: Double): Double =
        when {
            channel < 0 -> -linearToSrgb(-channel)
            channel <= 0.0031308 -> channel * 12.92
            else -> 1.055 * channel.pow(1 / 2.4) - 0.055
        }

    fun linearToOklab(rgb: Rgb): Oklab {
        val l = cbrt(0.4122214708 * rgb.red + 0.5363325363 * rgb.green + 0.0514459929 * rgb.blue)
        val m = cbrt(0.2119034982 * rgb.red + 0.6806995451 * rgb.green + 0.1073969566 * rgb.blue)
        val s = cbrt(0.0883024619 * rgb.red + 0.2817188376 * rgb.green + 0.6299787005 * rgb.blue)
        return Oklab(
            l = 0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
            a = 1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
            b = 0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s,
        )
    }

    fun oklabToLinear(lab: Oklab): Rgb {
        val l = (lab.l + 0.3963377774 * lab.a + 0.2158037573 * lab.b).pow(3)
        val m = (lab.l - 0.1055613458 * lab.a - 0.0638541728 * lab.b).pow(3)
        val s = (lab.l - 0.0894841775 * lab.a - 1.2914855480 * lab.b).pow(3)
        return Rgb(
            red = 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
            green = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
            blue = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s,
        )
    }

    /**
     * Turn HSL into gamma encoded sRGB with the CSS Color 4 formula.
     *
     * @param[hue] Degrees, 0 up to 360.
     * @param[saturation] 0.0 to 1.0.
     * @param[lightness] 0.0 to 1.0.
     */
    fun hslToSrgb(
        hue: Double,
        saturation: Double,
        lightness: Double,
    ): Rgb {
        val spread = saturation * min(lightness, 1 - lightness)

        fun channel(offset: Int): Double {
            val k = (offset + hue / 30) % 12
            return lightness - spread * max(-1.0, min(min(k - 3, 9 - k), 1.0))
        }

        return Rgb(red = channel(0), green = channel(8), blue = channel(4))
    }

    /**
     * Bring an OKLCH color inside sRGB without moving its lightness or hue.
     *
     * A color that does not fit loses chroma, found by a binary search, until it does. That is the idea behind the
     * CSS Color 4 gamut mapping, kept simple. Clipping each channel on its own would be cheaper but can turn a
     * saturated green yellow, and the hue is the part of a seed people care about most.
     *
     * [color] should have a lightness from 0.0 to 1.0. At chroma zero every such lightness is a grey that fits.
     */
    fun oklchToArgb(color: Oklch): GamutMapped {
        val exact = oklchToSrgb(color)
        if (exact.fitsEightBits()) return GamutMapped(srgbToArgb(exact), clamped = false)
        var fits = 0.0
        var overflows = min(color.c, MaxSearchChroma)
        repeat(GamutSearchSteps) {
            val chroma = (fits + overflows) / 2
            if (oklchToSrgb(color.copy(c = chroma)).fitsEightBits()) fits = chroma else overflows = chroma
        }
        return GamutMapped(srgbToArgb(oklchToSrgb(color.copy(c = fits))), clamped = true)
    }

    /**
     * Round gamma encoded channels to eight bits, clipping whatever rounding error is left.
     */
    fun srgbToArgb(rgb: Rgb): Argb {
        val red = rgb.red.toByteChannel()
        val green = rgb.green.toByteChannel()
        val blue = rgb.blue.toByteChannel()
        return Argb((red shl 16) or (green shl 8) or blue)
    }

    private fun oklchToSrgb(color: Oklch): Rgb {
        val linear = oklabToLinear(color.toOklab())
        return Rgb(linearToSrgb(linear.red), linearToSrgb(linear.green), linearToSrgb(linear.blue))
    }

    /**
     * True when clipping would not change any channel once it is rounded to eight bits.
     */
    private fun Rgb.fitsEightBits(): Boolean = red.fitsEightBits() && green.fitsEightBits() && blue.fitsEightBits()

    private fun Double.fitsEightBits(): Boolean = this * ChannelMax >= -0.5 && this * ChannelMax < ChannelMax + 0.5

    private fun Double.toByteChannel(): Int = (this * ChannelMax).roundToInt().coerceIn(0, ChannelMax.toInt())
}

fun linearToSrgb(channel: Double): Double =
    when {
        channel < 0 -> -linearToSrgb(-channel)
        channel <= 0.0031308 -> channel * 12.92
        else -> 1.055 * channel.pow(1 / 2.4) - 0.055
    }

fun hslToSrgb(
    hue: Double,
    saturation: Double,
    lightness: Double,
): Rgb {
    val spread = saturation * min(lightness, 1 - lightness)

    fun channel(offset: Int): Double {
        val k = (offset + hue / 30) % 12
        return lightness - spread * max(-1.0, min(min(k - 3, 9 - k), 1.0))
    }

    return Rgb(red = channel(0), green = channel(8), blue = channel(4))
}

fun srgbToArgb(rgb: Rgb): Argb {
    val red = rgb.red.toByteChannel()
    val green = rgb.green.toByteChannel()
    val blue = rgb.blue.toByteChannel()
    return Argb((red shl 16) or (green shl 8) or blue)
}

internal fun Argb.toOklab(): Oklab {
    val srgb = toSrgb()
    return ColorSpaces.linearToOklab(
        Rgb(
            red = ColorSpaces.srgbToLinear(srgb.red),
            green = ColorSpaces.srgbToLinear(srgb.green),
            blue = ColorSpaces.srgbToLinear(srgb.blue),
        ),
    )
}

