public sealed interface DecodeOutcome<out T> {
    /**
     * The record read cleanly, after whatever migrations it needed.
     *
     * @property[value] The record, in the shape this builder writes.
     */
    public data class Ok<out T>(
        public val value: T,
    ) : DecodeOutcome<T>

    /**
     * The record could not be read. The store moves it aside and tells the user, it is never
     * deleted.
     *
     * @property[reason] Why the record could not be read.
     */
    public data class Quarantine(
        public val reason: QuarantineReason,
    ) : DecodeOutcome<Nothing>
}

public data class Ok<out T>(
    public val value: T,
) : DecodeOutcome<T>

public data class Quarantine(
    public val reason: QuarantineReason,
) : DecodeOutcome<Nothing>

public enum class QuarantineReason {
    /**
     * The text is not JSON, or not an envelope with a schema and data.
     */
    Unreadable,

    /**
     * A newer builder wrote it, in a schema this one has no steps for yet.
     */
    NewerSchema,

    /**
     * A migration step could not make sense of the data it was handed.
     */
    MigrationFailed,

    /**
     * The data went through every step and still does not fit the record.
     */
    WrongShape,
}

internal fun <T> encodeEnvelope(
    value: T,
    serializer: KSerializer<T>,
    migrations: Migrations,
): String {
    val envelope = Envelope(schema = migrations.current, data = PersistJson.encodeToJsonElement(serializer, value))
    return PersistJson.encodeToString(Envelope.serializer(), envelope)
}

private fun readEnvelope(text: String): Envelope? =
    try {
        PersistJson.decodeFromString(Envelope.serializer(), text)
    }

internal class Migrations(
    private val steps: List<MigrationStep>,
) {
    /**
     * The schema this builder writes.
     */
    val current: Int
        get() = steps.size

    /**
     * Runs every step from [schema] up to [current], leaving data that is already current alone.
     */
    fun migrate(
        schema: Int,
        data: JsonObject,
    ): JsonObject {
        require(schema in 0..current) { "Schema is 0 to $current, got $schema" }
        return steps.drop(schema).fold(data) { migrated, step -> step.migrate(migrated) }
    }

    companion object {
        /**
         * For a record that is still in its first shape.
         */
        val None: Migrations = Migrations(emptyList())
    }
}

fun migrate(
    schema: Int,
    data: JsonObject,
): JsonObject {
    require(schema in 0..current) { "Schema is 0 to $current, got $schema" }
    return steps.drop(schema).fold(data) { migrated, step -> step.migrate(migrated) }
}

