private fun Accent.harmonizeMoves(document: ThemeDocument): Boolean {
    val harmonized = seed.asColor().harmonize(document.seed.asColor()).asArgb()
    return harmonize && (harmonized.value and RGB_MASK) != (seed.value and RGB_MASK)
}

private fun <K> assertSameColors(
    expected: Map<K, Argb>,
    actual: Map<K, Argb>,
    adapter: String,
    document: ThemeDocument,
    isDark: Boolean,
) {
    assertEquals(expected.keys, actual.keys, "$adapter keys, dark $isDark")
    val differing = expected.filter { (key, color) -> actual[key] != color }
    if (differing.isNotEmpty()) {
        val lines = differing.map { (key, color) -> "$key wanted $color, got ${actual[key]}" }
        fail("$adapter, dark $isDark, in $document\n" + lines.joinToString("\n"))
    }
}

private fun assertPassesTheEngineArguments(
    target: ExportTarget,
    versions: ExportVersions = Versions,
) {
    for (document in documents.map { document -> document.on(target) }) {
        val context = "${target.dynamicName(versions)}, in $document"
        val written = DynamicExport.read(target, export(document, DynamicPrefs, versions), context).arguments
        val preview = themes.resolve(document)

        assertEquals(SchemeArguments.of(target, document, preview), written, context)
    }
}

private fun assertGivesThePreviewColors(
    target: ExportTarget,
    versions: ExportVersions = Versions,
) {
    for (document in documents.map { document -> document.on(target) }) {
        val context = "${target.dynamicName(versions)}, in $document"
        val written = DynamicExport.read(target, export(document, DynamicPrefs, versions), context)
        val preview = themes.resolve(document)

        for (isDark in listOf(false, true)) {
            val expected = dynamicColors(target, preview, isDark)
            val colors = written.colors(isDark)
            val differing = (expected.keys + colors.keys).filter { name -> expected[name] != colors[name] }

            if (differing.isNotEmpty()) {
                val lines = differing.map { name -> "$name wanted ${expected[name]}, wrote ${colors[name]}" }
                fail("$context, dark $isDark\n" + lines.joinToString("\n"))
            }
        }
    }
}

private fun frozenColors(
    target: ExportTarget,
    document: ThemeDocument,
): Map<String, Argb> =
    buildMap {
        for (variant in ContrastVariant.entries) {
            val preview = themes.resolve(document.atContrast(variant))
            val prefix = variant.prefix
            for (isDark in listOf(false, true)) {
                val mode = if (isDark) "Dark" else "Light"
                val lowerMode = mode.replaceFirstChar(Char::lowercaseChar)
                val scope = if (prefix.isEmpty()) lowerMode else "$prefix$mode"
                when (target) {
                    ExportTarget.Material3, ExportTarget.Material3Expressive, ExportTarget.Inklet -> {
                        preview.roleColors(isDark).forEach { (role, color) ->
                            put("${role.name.lowerFirst()}$mode${prefix.upperFirst()}", color)
                        }
                    }
                    ExportTarget.Unstyled -> {
                        preview.roleColors(isDark).forEach { (role, color) ->
                            put("${scope}Colors/${role.name.lowerFirst()}", color)
                        }
                    }
                    ExportTarget.Custom -> {
                        preview.customSlots.mode(isDark).forEach { (slot, color) ->
                            put("${scope}ThemeColors/${slot.name.lowerFirst()}", color)
                        }
                    }
                    ExportTarget.Fluent -> {
                        if (variant == ContrastVariant.Standard) {
                            preview.fluentShades(isDark).byShade().forEach { (shade, color) ->
                                put("${mode}ThemeShades/$shade", color)
                            }
                        }
                    }
                }
                if (variant == ContrastVariant.Standard) putAll(accentColors(target, preview, isDark))
            }
        }
    }

private fun dynamicColors(
    target: ExportTarget,
    preview: ThemeResult,
    isDark: Boolean,
): Map<String, Argb> {
    val roles = preview.roleColors(isDark).mapKeys { (role, _) -> role.name.lowerFirst() }
    val families = preview.accents.families
        .flatMap { family ->
            val name = family.accent.name.lowerFirst()
            AccentPart.entries.map { part ->
                val key = when (target) {
                    ExportTarget.Unstyled -> "ThemeTokens.${part.unstyledToken(name)}"
                    else -> "$name/${part.property}"
                }
                key to family.mode(isDark).part(part)
            }
        }.toMap()
    return when (target) {
        ExportTarget.Material3, ExportTarget.Material3Expressive, ExportTarget.Inklet, ExportTarget.Unstyled -> {
            roles + families
        }
        ExportTarget.Fluent -> {
            preview.fluentShades(isDark).byShade()
        }
        ExportTarget.Custom -> {
            preview.customSlots.mode(isDark).mapKeys { (slot, _) -> slot.name.lowerFirst() } + families
        }
    }
}

private fun accentColors(
    target: ExportTarget,
    preview: ThemeResult,
    isDark: Boolean,
): Map<String, Argb> {
    val mode = if (isDark) "dark" else "light"
    return preview.accents.families
        .flatMap { family ->
            val name = family.accent.name.lowerFirst()
            AccentPart.entries.mapNotNull { part ->
                val color = family.mode(isDark).part(part)
                val path = when (target) {
                    ExportTarget.Material3, ExportTarget.Material3Expressive, ExportTarget.Inklet -> {
                        "extended${mode.upperFirst()}/$name/${part.property}"
                    }
                    ExportTarget.Unstyled -> {
                        "${mode}Colors/${part.unstyledToken(name)}"
                    }
                    ExportTarget.Custom -> {
                        "${mode}ThemeColors/$name/${part.property}"
                    }
                    ExportTarget.Fluent -> {
                        null
                    }
                }
                path?.let { key -> key to color }
            }
        }.toMap()
}

private fun ThemeDocument.on(target: ExportTarget): ThemeDocument {
    val library = when (target) {
        ExportTarget.Material3, ExportTarget.Material3Expressive -> Library.Material3
        ExportTarget.Inklet -> Library.Inklet
        ExportTarget.Unstyled -> Library.Unstyled
        ExportTarget.Fluent -> Library.Fluent
        ExportTarget.Custom -> Library.Custom
    }
    return copy(library = library, expressive = target == ExportTarget.Material3Expressive).forTarget(target)
}

private fun ThemeDocument.atContrast(variant: ContrastVariant): ThemeDocument =
    when (variant) {
        ContrastVariant.Standard -> this
        ContrastVariant.Medium -> copy(contrast = ContrastLevel.Medium)
        ContrastVariant.High -> copy(contrast = ContrastLevel.High)
    }

private val ContrastVariant.prefix: String
    get() = when (this) {
        ContrastVariant.Standard -> ""
        ContrastVariant.Medium -> "mediumContrast"
        ContrastVariant.High -> "highContrast"
    }

private fun ThemeResult.fluentShades(isDark: Boolean): FluentShadeValues {
    val shades = scheme(isDark).primaryPalette.toFluentShades()
    return FluentShadeValues(
        dark3 = shades.dark3.asArgb(),
        dark2 = shades.dark2.asArgb(),
        dark1 = shades.dark1.asArgb(),
        base = shades.base.asArgb(),
        light1 = shades.light1.asArgb(),
        light2 = shades.light2.asArgb(),
        light3 = shades.light3.asArgb(),
    )
}

private fun AccentPart.unstyledToken(accent: String): String =
    when (this) {
        AccentPart.Color -> accent
        AccentPart.OnColor -> "on${accent.upperFirst()}"
        AccentPart.Container -> "${accent}Container"
        AccentPart.OnContainer -> "on${accent.upperFirst()}Container"
    }

class ParityDocuments(
    seed: Int = 117,
) {
    private val random = Random(seed)

    // Seeded apart from random, so the two streams never replay each other at shifted positions.
    private val base = TestDocuments(seed = Random(seed xor BASE_SALT).nextInt())

    /**
     * [count] documents in a row.
     */
    fun documents(count: Int): List<ThemeDocument> = List(count) { index -> next(index) }

    /**
     * [count] documents whose only key color is a primary override, with no pins, AMOLED or custom
     * tones, so every adapter should give back the core scheme for the seed and that override.
     */
    fun primaryOverrides(count: Int): List<ThemeDocument> =
        documents(count).map { document ->
            document.copy(
                keyColors = KeyColors(primary = Argb(random.nextInt())),
                amoled = false,
                pins = emptyMap(),
                customTones = emptyMap(),
            )
        }

    private fun next(index: Int): ThemeDocument =
        base.next().copy(
            style = Style.entries[index % Style.entries.size],
            spec = SpecVersion.entries[index / Style.entries.size % SpecVersion.entries.size],
            accents = List(random.nextInt(0, 4)) { position -> nextAccent(position) },
            customTones = nextCustomTones(),
        )

    private fun nextAccent(position: Int): Accent =
        Accent(
            name = "accent$position",
            seed = Argb(random.nextInt()),
            harmonize = random.nextBoolean(),
            light = FamilyTones(color = nextTone(), container = nextTone()),
            dark = FamilyTones(color = nextTone(), container = nextTone()),
            threshold = OnColorThreshold.entries.random(random),
        )

    private fun nextCustomTones(): Map<CustomSlot, CustomTone> =
        CustomSlot.entries
            .shuffled(random)
            .take(random.nextInt(0, 5))
            .associateWith { nextCustomTone() }

    private fun nextCustomTone(): CustomTone =
        when (random.nextInt(3)) {
            0 -> CustomTone(light = nextTone())
            1 -> CustomTone(dark = nextTone())
            else -> CustomTone(light = nextTone(), dark = nextTone())
        }

    private fun nextTone(): Int = random.nextInt(0, 101)
}

fun colors(isDark: Boolean): Map<String, Argb> =
    when (target) {
        ExportTarget.Material3, ExportTarget.Material3Expressive, ExportTarget.Inklet -> {
            material3Roles(document, isDark).byName() + material3Pins(isDark) + families("ExtendedColors", isDark)
        }
        ExportTarget.Unstyled -> {
            unstyledRoles(document, isDark).byName() + unstyledValues(isDark)
        }
        ExportTarget.Fluent -> {
            if (call.function == "rememberFluentColors") {
                fluentShades(document, isDark).byShade()
            } else {
                inlineShades(isDark)
            }
        }
        ExportTarget.Custom -> {
            customColors(isDark)
        }
    }

private fun material3Pins(isDark: Boolean): Map<String, Argb> {
    val modify = call.arguments["modifyColorScheme"] ?: return emptyMap()
    val lambda = PinnedScheme.matchEntire(modify)?.takeIf { match -> match.groupValues[1] == match.groupValues[2] }
        ?: source.fail("modifyColorScheme = $modify is not a { scheme -> scheme.copy(...) }")
    val scheme = lambda.groupValues[1]
    val copy = modify.indexOf("$scheme.copy(") + "$scheme.copy".length
    return buildMap {
        argumentsAt(modify, copy).named().forEach { (property, value) ->
            roleNamed(property) ?: source.fail("modifyColorScheme sets $property, which is no role")
            val branch = branchOf(value, isDark)
            val pinned = ColorLiterals.literal(branch)
            when {
                pinned != null -> {
                    put(property, pinned)
                }
                branch != "$scheme.$property" -> {
                    source.fail("modifyColorScheme sets $property ${modeOf(isDark)} to $branch, no color")
                }
            }
        }
    }
}

private fun unstyledValues(isDark: Boolean): Map<String, Argb> {
    val darkBlock = source.text.indexOf(DARK_BLOCK).takeIf { index -> index >= 0 }
        ?: source.fail("The export never opens $DARK_BLOCK")
    val section = if (isDark) source.text.substring(darkBlock) else source.text.substring(0, darkBlock)
    if (call.function == "rememberDynamicLightDarkColors") {
        val values = if (isDark) "dark" else "light"
        if ("$COLORS_PROPERTY = $values\n" !in section) {
            source.fail("The ${modeOf(isDark)} values are not the $values half of rememberDynamicLightDarkColors")
        }
        return emptyMap()
    }
    val schemes = ThemeValues.findAll(section).map { match -> match.groupValues[1] }.toList()
    val scheme = schemes.singleOrNull()
        ?: source.fail("The ${modeOf(isDark)} values read toThemeValues() off $schemes, not one scheme")
    val schemeMode = source.assigned("rememberDynamicScheme")[scheme]?.named()?.get(IS_DARK)
    if (schemeMode != isDark.toString()) {
        source.fail("The ${modeOf(isDark)} values come off $scheme, which is built with isDark = $schemeMode")
    }

    val maps = MapOf.findAll(section).toList()
    if (maps.size > 1) source.fail("The ${modeOf(isDark)} values add ${maps.size} maps, where one was wanted")
    val entries = maps.singleOrNull()?.let { match -> argumentsAt(section, match.range.last) }.orEmpty()
    val evaluation = Evaluation(source, isDark, palettes())
    return entries.associate { entry ->
        val (owner, token, value) = TokenEntry.matchEntire(entry)?.destructured
            ?: source.fail("The ${modeOf(isDark)} values add $entry, which is no token entry")
        when (owner) {
            "MaterialKolorTokens" -> {
                roleNamed(token) ?: source.fail("The ${modeOf(isDark)} values pin $token, which is no role")
                token to source.color(value, "The ${modeOf(isDark)} values pin $token to $value")
            }
            "ThemeTokens" -> {
                "ThemeTokens.$token" to evaluation.color(value)
            }
            else -> {
                source.fail("The ${modeOf(isDark)} values add $entry, a token of no known object")
            }
        }
    }
}

private fun customColors(isDark: Boolean): Map<String, Argb> {
    requireThemeMode("rememberThemeColors")
    val scheme = referenceScheme(document, isDark)
    val schemeName = source.assigned("rememberDynamicScheme").keys.singleOrNull()
        ?: source.fail("The export holds no single rememberDynamicScheme in a val")
    val (kolorsName, kolorsArguments) = source.assigned("MaterialKolors").entries.singleOrNull()
        ?: source.fail("The export holds no single MaterialKolors in a val")
    if (kolorsArguments.firstOrNull() != schemeName) {
        source.fail("MaterialKolors($kolorsArguments) reads no $schemeName")
    }
    val amoled = kolorsArguments.named()["isAmoled"]?.toBooleanStrict() ?: false
    val names = palettes() + mapOf(schemeName to scheme, kolorsName to MaterialKolors(scheme, isAmoled = amoled))
    return values(source.callsOf("ThemeColors"), "ThemeColors", Evaluation(source, isDark, names))
}

private fun families(
    type: String,
    isDark: Boolean,
): Map<String, Argb> {
    val calls = source.callsOf(type)
    if (calls.isEmpty()) return emptyMap()
    requireThemeMode("rememberExtendedColors")
    return values(calls, type, Evaluation(source, isDark, palettes()))
}

private fun values(
    calls: List<List<String>>,
    type: String,
    evaluation: Evaluation,
): Map<String, Argb> {
    val arguments = calls.singleOrNull()?.named()
        ?: source.fail("The export builds $type ${calls.size} times, not once")
    return buildMap {
        arguments.forEach { (name, value) ->
            when (val result = evaluation.value(value)) {
                is Argb -> {
                    put(name, result)
                }
                is Map<*, *> -> {
                    result.forEach { (part, color) ->
                        val argb = color as? Argb ?: source.fail("$type gets $name/$part = $color, no color")
                        put("$name/$part", argb)
                    }
                }
                else -> {
                    source.fail("$type gets $name = $value, which comes to $result, not a color")
                }
            }
        }
    }
}

private fun inlineShades(isDark: Boolean): Map<String, Argb> {
    val colors = source.callsOf("Colors").singleOrNull()?.named()
        ?: source.fail("The export builds no single Colors(...)")
    val darkMode = colors["darkMode"]
    if (darkMode != IS_DARK) source.fail("Colors(...) passes darkMode = $darkMode, not isDark")
    val shades = colors["shades"]?.takeIf { value -> value.endsWith(".$TO_SHADES()") }
        ?: source.fail("Colors(...) passes shades = ${colors["shades"]}, not a palette's $TO_SHADES()")
    val schemeName = source.assigned("rememberDynamicScheme").keys.singleOrNull()
        ?: source.fail("The export holds no single rememberDynamicScheme in a val")
    val evaluation = Evaluation(source, isDark, mapOf(schemeName to referenceScheme(document, isDark)))
    return evaluation.shades(shades)
}

private fun palettes(): Map<String, TonalPalette> =
    source.assigned("rememberTonalPalette").mapValues { (name, arguments) ->
        val named = arguments.named()
        if (named.size != arguments.size || !named.keys.all { key -> key == "seed" || key == "harmonizeWith" }) {
            source.fail("$name = rememberTonalPalette($arguments) passes more than a seed and harmonizeWith")
        }
        val seed = named["seed"] ?: source.fail("$name passes no seed")
        tonalPalette(
            seed = source.color(seed, "$name passes seed = $seed"),
            harmonizeWith = named["harmonizeWith"]?.let { value ->
                source.color(value, "$name passes harmonizeWith = $value")
            },
        )
    }

private fun requireThemeMode(function: String) {
    source.callsOf(function).forEach { arguments ->
        val mode = arguments.named()[IS_DARK]
        if (mode != IS_DARK) source.fail("$function is called with isDark = $mode, not the theme's own isDark")
    }
}

fun read(
    target: ExportTarget,
    files: List<GeneratedFile>,
    context: String,
): DynamicExport {
    val source = ExportSource(files, context)
    val call = SchemeCall.read(target, source)
    return DynamicExport(target, source, call, SchemeArguments.read(target, source, call))
}

fun shades(expression: String): Map<String, Argb> {
    val palette = value(expression.substringBeforeLast('.')) as? TonalPalette
        ?: source.fail("$expression is not called on a palette")
    return helper(palette, expression.substringAfterLast('.').substringBefore('('), emptyMap())
        .mapValues { (shade, color) -> color as? Argb ?: source.fail("The shade $shade comes to $color, no color") }
}

private fun helper(
    palette: TonalPalette,
    function: String,
    arguments: Map<String, Any>,
): Map<String, Any> {
    val declaration = Regex("""\bfun TonalPalette\.$function\(""").find(source.text)
        ?: source.fail("The export calls $function on a palette but declares no fun TonalPalette.$function")
    val parametersClose = closingOf(source.text, declaration.range.last)
    val bodyOpen = source.text.indexOf('{', parametersClose)
    val body = source.text.substring(bodyOpen + 1, closingOf(source.text, bodyOpen))

    val scope = names.toMutableMap()
    val parameters = argumentsAt(source.text, declaration.range.last).map { parameter ->
        val (name, default) = Parameter.matchEntire(parameter)?.destructured
            ?: source.fail("$function declares $parameter, which the parity reader cannot read")
        scope[name] = arguments[name]
            ?: default.takeIf(String::isNotEmpty)?.let { value ->
                Evaluation(source, isDark, scope, palette).value(value)
            }
            ?: source.fail("A call to $function passes no $name, and it has no default")
        name
    }
    (arguments.keys - parameters.toSet()).takeIf(Set<String>::isNotEmpty)?.let { unknown ->
        source.fail("A call to $function passes $unknown, which it does not declare")
    }
    Local.findAll(body).forEach { match ->
        val (name, value) = match.destructured
        scope[name] = Evaluation(source, isDark, scope, palette).value(value.oneLine())
    }

    val returned = Returned.find(body) ?: source.fail("$function returns no constructor call")
    val type = returned.groupValues[1]
    val values = argumentsAt(body, returned.range.last)
    val evaluation = Evaluation(source, isDark, scope, palette)
    if (values.size == values.named().size) {
        return values.named().mapValues { (_, value) -> evaluation.value(value) }
    }

    val properties = declaredProperties(type)
    if (properties.size != values.size) source.fail("$function returns $type($values), which declares $properties")
    return properties.zip(values).associate { (property, value) -> property to evaluation.value(value) }
}

private fun declaredProperties(type: String): List<String> {
    val declaration = Regex("""\bclass $type\(""").find(source.text)
        ?: source.fail("The export returns $type positionally but does not declare it")
    return argumentsAt(source.text, declaration.range.last).map { property ->
        Property.matchEntire(property)?.groupValues?.get(1) ?: source.fail("$type declares $property")
    }
}

private fun openingOf(expression: String): Int {
    var depth = 0
    for (index in expression.indices.reversed()) {
        when (expression[index]) {
            ')', '}', ']' -> depth++
            '(', '{', '[' -> if (--depth == 0) return index
        }
    }
    error("Nothing opens the call in $expression")
}

internal fun ThemeDocument.pin(
    role: Role,
    isDark: Boolean,
): Argb? = pins[role]?.let { pin -> if (isDark) pin.dark else pin.light }

internal fun coreRoles(scheme: DynamicScheme): Map<Role, Argb> {
    val kolors = MaterialKolors(scheme)
    return Role.entries.associateWith { role -> kolors.roleColor(role).asArgb() }
}

internal fun unstyledRoles(
    document: ThemeDocument,
    isDark: Boolean,
): Map<Role, Argb> {
    val values = referenceScheme(document, isDark).toThemeValues()
    return Role.entries.associateWith { role ->
        document.pin(role, isDark) ?: values.getValue(role.unstyledToken()).asArgb()
    }
}

internal fun expressiveRoles(
    document: ThemeDocument,
    scheme: ColorScheme,
    isDark: Boolean,
): Map<Role, Argb> =
    Role.entries.associateWith { role -> document.pin(role, isDark) ?: scheme.roleColor(role).asArgb() }

internal fun customDynamicSlots(
    document: ThemeDocument,
    isDark: Boolean,
    contrastLevel: Double = document.contrastLevel,
): Map<CustomSlot, Argb> {
    val scheme = referenceScheme(document, isDark, contrastLevel)
    val kolors = MaterialKolors(scheme, isAmoled = document.amoled)
    return CustomSlot.entries.associateWith { slot ->
        val moved = document.customTones[slot]?.let { tone -> if (isDark) tone.dark else tone.light }
        when (val resolution = slot.resolution) {
            is SlotResolution.FromRole -> {
                document.pin(resolution.role, isDark) ?: kolors.roleColor(resolution.role).asArgb()
            }
            is SlotResolution.FromRamp -> {
                val tone = moved ?: if (isDark) resolution.dark else resolution.light
                scheme.ramp(resolution.ramp).toneColor(tone).asArgb()
            }
            is SlotResolution.OnRamp -> {
                val palette = scheme.ramp(resolution.ramp)
                val background = if (isDark) resolution.dark else resolution.light
                (moved?.let(palette::toneColor) ?: palette.onTone(background)).asArgb()
            }
        }
    }
}

internal fun tonalPalette(
    seed: Argb,
    harmonizeWith: Argb?,
): TonalPalette {
    val color = seed.asColor()
