internal class DropdownPositionProvider(
    private val gap: Int,
    private val alignEnd: Boolean = false,
    private val inset: Int = 0,
) : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset {
        val leftEdge = (layoutDirection == LayoutDirection.Ltr) != alignEnd
        val start = if (leftEdge) {
            anchorBounds.left - inset
        } else {
            anchorBounds.right - popupContentSize.width + inset
        }
        val x = start.coerceIn(0, max(0, windowSize.width - popupContentSize.width))
        val below = anchorBounds.bottom + gap - inset
        val y = if (below + popupContentSize.height <= windowSize.height) {
            below
        } else {
            max(0, anchorBounds.top - gap + inset - popupContentSize.height)
        }
        return IntOffset(x, y)
    }
}

fun sync(external: String) {
    if (external == committed) return
    committed = external
    committedText = external
    show(external)
}

fun commit(
    text: String,
    canonical: String,
) {
    committed = canonical
    committedText = text
}

fun settle(text: String) {
    committed = text
    committedText = text
    if (value.text != text) show(text)
}

fun revert(): Boolean {
    if (!dirty) return false
    committedText = committed
    show(committed)
    return true
}

@Composable
internal fun rememberFieldDraft(committed: String): FieldDraft {
    val draft = remember { FieldDraft(committed) }
    SideEffect { draft.sync(committed) }
    return draft
}

internal fun Modifier.fieldCommits(
    draft: FieldDraft,
    onCommit: () -> Unit,
    onRevert: () -> Unit,
    onSubmit: (() -> Unit)? = null,
): Modifier =
    onPreviewKeyEvent { event ->
        if (event.type != KeyEventType.KeyDown || draft.composing) return@onPreviewKeyEvent false
        when (event.key) {
            Key.Enter, Key.NumPadEnter -> {
                onCommit()
                onSubmit?.invoke()
                true
            }
            Key.Escape -> {
                draft.revert().also { reverted -> if (reverted) onRevert() }
            }
            else -> {
                false
            }
        }
    }

