public interface Parser {

  /**
   * Parse the {@code content} and return the parsed result.
   * @param fileExtension the file extension of the content, null means not 
   * provided
   * @param content the content
   * @return the parsed result
   */
  List<ParseResult> parse(String fileExtension, String content);
}

public class PrettifyParser implements Parser {

  /**
   * The prettify parser.
   */
  protected Prettify prettify;

  /**
   * Constructor.
   */
  public PrettifyParser() {
    prettify = new Prettify();
  }

  @Override
  public List<ParseResult> parse(String fileExtension, String content) {
    Job job = new Job(0, content);
    prettify.langHandlerForExtension(fileExtension, content).decorate(job);
    List<Object> decorations = job.getDecorations();


    List<ParseResult> returnList = new ArrayList<ParseResult>();

    // apply style according to the style list
    for (int i = 0, iEnd = decorations.size(); i < iEnd; i += 2) {
      int endPos = i + 2 < iEnd ? (Integer) decorations.get(i + 2) : content.length();
      int startPos = (Integer) decorations.get(i);
      returnList.add(new ParseResult(startPos, endPos - startPos, Arrays.asList(new String[]{(String) decorations.get(i + 1)})));
    }

    return returnList;
  }
}

public abstract class Lang {

  /**
   * Similar to those in JavaScript prettify.js.
   */
  protected List<List<Object>> shortcutStylePatterns;
  /**
   * Similar to those in JavaScript prettify.js.
   */
  protected List<List<Object>> fallthroughStylePatterns;
  /**
   * See {@link io.github.kbiakov.codeview.highlight.prettify.lang.LangCss} for example.
   */
  protected List<Lang> extendedLangs;

  /**
   * Constructor.
   */
  public Lang() {
    shortcutStylePatterns = new ArrayList<List<Object>>();
    fallthroughStylePatterns = new ArrayList<List<Object>>();
    extendedLangs = new ArrayList<Lang>();
  }

  /**
   * This method should be overridden by the child class.
   * This provide the file extensions list to help the parser to determine which 
   * {@link Lang} to use. See JavaScript prettify.js.
   * 
   * @return the list of file extensions
   */
  public static List<String> getFileExtensions() {
    return new ArrayList<String>();
  }

  public List<List<Object>> getShortcutStylePatterns() {
    List<List<Object>> returnList = new ArrayList<List<Object>>();
    for (List<Object> shortcutStylePattern : shortcutStylePatterns) {
      returnList.add(new ArrayList<Object>(shortcutStylePattern));
    }
    return returnList;
  }

  public void setShortcutStylePatterns(List<List<Object>> shortcutStylePatterns) {
    if (shortcutStylePatterns == null) {
      this.shortcutStylePatterns = new ArrayList<List<Object>>();
      return;
    }
    List<List<Object>> cloneList = new ArrayList<List<Object>>();
    for (List<Object> shortcutStylePattern : shortcutStylePatterns) {
      cloneList.add(new ArrayList<Object>(shortcutStylePattern));
    }
    this.shortcutStylePatterns = cloneList;
  }

  public List<List<Object>> getFallthroughStylePatterns() {
    List<List<Object>> returnList = new ArrayList<List<Object>>();
    for (List<Object> fallthroughStylePattern : fallthroughStylePatterns) {
      returnList.add(new ArrayList<Object>(fallthroughStylePattern));
    }
    return returnList;
  }

  public void setFallthroughStylePatterns(List<List<Object>> fallthroughStylePatterns) {
    if (fallthroughStylePatterns == null) {
      this.fallthroughStylePatterns = new ArrayList<List<Object>>();
      return;
    }
    List<List<Object>> cloneList = new ArrayList<List<Object>>();
    for (List<Object> fallthroughStylePattern : fallthroughStylePatterns) {
      cloneList.add(new ArrayList<Object>(fallthroughStylePattern));
    }
    this.fallthroughStylePatterns = cloneList;
  }

  /**
   * Get the extended languages list.
   * @return the list
   */
  public List<Lang> getExtendedLangs() {
    return new ArrayList<Lang>(extendedLangs);
  }

  /**
   * Set extended languages. Because we cannot register multiple languages 
   * within one {@link prettify.lang.Lang}, so it is used as an solution. See 
   * {@link prettify.lang.LangCss} for example.
   * 
   * @param extendedLangs the list of {@link prettify.lang.Lang}s
   */
  public void setExtendedLangs(List<Lang> extendedLangs) {
    this.extendedLangs = new ArrayList<Lang>(extendedLangs);
  }
}

public static List<String> getFileExtensions() {
  return new ArrayList<String>();
}

public List<Lang> getExtendedLangs() {
  return new ArrayList<Lang>(extendedLangs);
}

public void setExtendedLangs(List<Lang> extendedLangs) {
  this.extendedLangs = new ArrayList<Lang>(extendedLangs);
}

public class LangBasic extends Lang {

    public LangBasic() {
        List<List<Object>> _shortcutStylePatterns = new ArrayList<List<Object>>();
        List<List<Object>> _fallthroughStylePatterns = new ArrayList<List<Object>>();

        // "single-line-string"
        _shortcutStylePatterns.add(Arrays.asList(new Object[]{Prettify.PR_STRING, Pattern.compile("^(?:\"(?:[^\\\\\"\\r\\n]|\\\\.)*(?:\"|$))"), null, "\""}));
        // Whitespace
        _shortcutStylePatterns.add(Arrays.asList(new Object[]{Prettify.PR_PLAIN, Pattern.compile("^\\s+"), null, "\t\n\r " + Character.toString((char) 0xA0)}));

        // A line comment that starts with REM
        _fallthroughStylePatterns.add(Arrays.asList(new Object[]{Prettify.PR_COMMENT, Pattern.compile("^REM[^\\r\\n]*"), null}));
        _fallthroughStylePatterns.add(Arrays.asList(new Object[]{Prettify.PR_KEYWORD, Pattern.compile("^\\b(?:AND|CLOSE|CLR|CMD|CONT|DATA|DEF ?FN|DIM|END|FOR|GET|GOSUB|GOTO|IF|INPUT|LET|LIST|LOAD|NEW|NEXT|NOT|ON|OPEN|OR|POKE|PRINT|READ|RESTORE|RETURN|RUN|SAVE|STEP|STOP|SYS|THEN|TO|VERIFY|WAIT)\\b"), null}));
        _fallthroughStylePatterns.add(Arrays.asList(new Object[]{Prettify.PR_PLAIN, Pattern.compile("^[A-Z][A-Z0-9]?(?:\\$|%)?", Pattern.CASE_INSENSITIVE), null}));
        // Literals .0, 0, 0.0 0E13
        _fallthroughStylePatterns.add(Arrays.asList(new Object[]{Prettify.PR_LITERAL, Pattern.compile("^(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:e[+\\-]?\\d+)?", Pattern.CASE_INSENSITIVE), null, "0123456789"}));
        _fallthroughStylePatterns.add(Arrays.asList(new Object[]{Prettify.PR_PUNCTUATION, Pattern.compile("^.[^\\s\\w\\.$%\"]*"), null}));

        setShortcutStylePatterns(_shortcutStylePatterns);
        setFallthroughStylePatterns(_fallthroughStylePatterns);
    }

    public static List<String> getFileExtensions() {
        return Arrays.asList(new String[]{"basic", "cbm"});
    }
}

