fun advance(chunk: Long): RestoreProgress.Restoring? {
    copiedBytes += chunk
    currentFileBytes = (currentFileBytes + chunk).coerceAtMost(currentFileSize)

    val now = now()
    if (now - lastEmitAt < EMIT_INTERVAL_MILLIS) return null

    lastEmitAt = now
    return snapshot()
}

fun skipFile(photo: PhotoBackup): RestoreProgress.Restoring? {
    filesDone++
    completedBytes += photo.size

    val now = now()
    if (now - lastEmitAt < EMIT_INTERVAL_MILLIS) return null

    lastEmitAt = now
    return snapshot()
}

fun advanceSidecar(chunk: Long) {
    copiedBytes += chunk
}

private suspend fun readMetaData(uri: Uri): BackupMetaData? {
    val zipInputStream = io.zip.openZipInput(uri)
        ?: throw BackupValidationError.CannotOpenFile()

    zipInputStream.use { stream ->
        var entry = stream.nextEntry

        while (entry != null) {
            if (entry.name == BackupMetaData.FILE_NAME) {
                return readBackupMetadata(stream)
            }

            entry = stream.nextEntry
        }
    }

    return null
}

private fun containsBackupFiles(uri: Uri): Boolean {
    val zipInputStream = io.zip.openZipInput(uri)
        ?: throw BackupValidationError.CannotOpenFile()

    zipInputStream.use { stream ->
        var entry = stream.nextEntry

        while (entry != null) {
            val name = entry.name
            if (name.endsWith(PHOTOK_FILE_EXTENSION) ||
                name.endsWith(LEGACY_PHOTOK_FILE_EXTENSION)
            ) {
                return true
            }

            entry = stream.nextEntry
        }
    }

    return false
}

