private fun List<RestoreLogEntry>.append(
    currentFile: RestoreProgress.CurrentFile?,
): List<RestoreLogEntry> {
    currentFile ?: return this
    if (currentFile.index == lastOrNull()?.index) return this

    return (this + RestoreLogEntry(currentFile.index, currentFile.fileName))
        .takeLast(RESTORE_LOG_ROWS)
}

@Composable
fun RestoreLog(
    entries: List<RestoreLogEntry>,
    modifier: Modifier = Modifier,
) {
    Surface(
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.surfaceContainerLow,
        modifier = modifier,
    ) {
        Column(
            verticalArrangement = Arrangement.Bottom,
            modifier = Modifier
                .fillMaxWidth()
                .height(ROW_HEIGHT * RESTORE_LOG_ROWS + VERTICAL_PADDING * 2)
                .padding(horizontal = Dimens.spacingMedium, vertical = VERTICAL_PADDING)
                .graphicsLayer { compositingStrategy = CompositingStrategy.Offscreen }
                .drawWithContent {
                    drawContent()
                    drawRect(
                        brush = Brush.verticalGradient(
                            colors = listOf(Color.Transparent, Color.Black),
                            endY = size.height / 2,
                        ),
                        blendMode = BlendMode.DstIn,
                    )
                }
        ) {
            val rows = entries.takeLast(RESTORE_LOG_ROWS)

            rows.forEachIndexed { index, entry ->
                val newest = index == rows.lastIndex

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier
                        .height(ROW_HEIGHT)
                        .fillMaxWidth()
                        .alpha(ROW_ALPHA[rows.lastIndex - index])
                ) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier.width(6.dp)
                    ) {
                        if (newest) PulsingDot()
                    }

                    Text(
                        text = entry.fileName,
                        style = MaterialTheme.typography.bodySmall,
                        fontFamily = FontFamily.Monospace,
                        color = if (newest) {
                            MaterialTheme.colorScheme.onSurface
                        } else {
                            MaterialTheme.colorScheme.outline
                        },
                        maxLines = 1,
                        overflow = TextOverflow.MiddleEllipsis,
                    )
                }
            }
        }
    }
}

object BindingConverters {

    private val dateFormat: SimpleDateFormat = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.ROOT)
    private val decimalFormat = DecimalFormat("0")

    private const val GB_SUFFIX = " GB"
    private const val MB_SUFFIX = " MB"
    private const val KB_SUFFIX = " KB"
    private const val BYTES_SUFFIX = " Bytes"

    fun millisToFormattedDateConverter(millis: Long?): String? {
        millis ?: return "-"
        val date = Date(millis)
        return dateFormat.format(date)
    }

    fun formatByteSizeConverter(bytes: Long): String {
        val kiloBytes = bytes / 1024
        val megaBytes = kiloBytes / 1024
        val gigaBytes = megaBytes / 1024

        return when {
            gigaBytes >= 1 -> {
                decimalFormat.format(gigaBytes) + GB_SUFFIX
            }
            megaBytes >= 1 -> {
                decimalFormat.format(megaBytes) + MB_SUFFIX
            }
            kiloBytes >= 1 -> {
                decimalFormat.format(kiloBytes) + KB_SUFFIX
            }
            else -> {
                decimalFormat.format(bytes) + BYTES_SUFFIX
            }
        }
    }

    fun toStringConverter(obj: Any?) = obj.toString()

    fun upperCaseConverter(str: String?): String? = str?.uppercase()
}

