    )
}

class UnlockBiometricCipherPrompt @Inject constructor() {
    suspend operator fun invoke(
        activity: FragmentActivity,
        cipher: Cipher,
        title: String,
        subtitle: String,
        negativeButtonText: String,
        onAuthenticationFailed: () -> Unit = {},
    ): Result<Cipher> = suspendCoroutine { continuation ->
        var completed = false

        fun resume(result: Result<Cipher>) {
            if (!completed) {
                completed = true
                continuation.resume(result)
            }
        }

        lateinit var biometricPrompt: BiometricPrompt
        biometricPrompt = BiometricPrompt(
            activity,
            ContextCompat.getMainExecutor(activity),
            object : BiometricPrompt.AuthenticationCallback() {

                override fun onAuthenticationFailed() {
                    super.onAuthenticationFailed()
                    biometricPrompt.cancelAuthentication()
                    resume(Result.failure(BiometricAuthenticationFailedException()))
                }

                override fun onAuthenticationSucceeded(result: BiometricPrompt.AuthenticationResult) {
                    super.onAuthenticationSucceeded(result)
                    val cipher = result.cryptoObject?.cipher

                    if (cipher != null) {
                        resume(Result.success(cipher))
                    } else {
                        resume(Result.failure(IllegalStateException("Cipher is null")))
                    }
                }

                override fun onAuthenticationError(errorCode: Int, errString: CharSequence) {
                    super.onAuthenticationError(errorCode, errString)
                    val noErrorMessages = setOf(
                        BiometricPrompt.ERROR_NEGATIVE_BUTTON,
                        BiometricPrompt.ERROR_USER_CANCELED,
                    )

                    val error = if (noErrorMessages.contains(errorCode)) {
                        UserCanceledBiometricsException()
                    } else {
                        Exception(errString.toString())
                    }

                    resume(Result.failure(error))
                }
            }
        )

        val promptInfo = BiometricPrompt.PromptInfo.Builder()
            .setTitle(title)
            .setSubtitle(subtitle)
            .setNegativeButtonText(negativeButtonText)
            .setConfirmationRequired(true)
            .build()

        biometricPrompt.authenticate(promptInfo, BiometricPrompt.CryptoObject(cipher))
    }
}

