class CreateThumbnailsUseCase @Inject constructor(
    @ApplicationContext private val context: Context,
    private val imageStorage: ImageStorage,
    private val vaultFileStorage: VaultFileStorage,
    private val thumbnailGenerator: ThumbnailGenerator,
) {

    /**
     * @param photo The photo object for which the thumbnail is to be created.
     * @param data The data for the photo. May be ByteArray or system Uri
     */
    suspend operator fun invoke(photo: Photo, data: Any?): Result<Unit> =
        withContext(Dispatchers.IO) {

            val thumbnailResult = thumbnailGenerator.createFromImport(
                uuid = photo.uuid,
                data = data,
                isVideo = photo.type.isVideo,
            )

            // Video Preview
            val videoPreviewResult = if (photo.type.isVideo) {
                val videoPreviewRequest = ImageRequest.Builder(context)
                    .data(data)
                    .allowHardware(false)
                    .videoFramePercent(0.5)
                    .build()

                imageStorage.execAndWrite(
                    imageRequest = videoPreviewRequest,
                    outputStream = vaultFileStorage.openEncryptedOutput(photo.internalVideoPreviewFileName),
                    compressionPercent = 90,
                )
            } else {
                // Success if not a video
                Result.success(Unit)
            }

            if (thumbnailResult.isSuccess && videoPreviewResult.isSuccess) {
                Result.success(Unit)
            } else {
                Result.failure(
                    thumbnailResult.exceptionOrNull() ?: Exception("error creating thumbnail")
                )
            }
        }
}

@Singleton
class ThumbnailGenerator @Inject constructor(
    @ApplicationContext private val context: Context,
    @EncryptedImageLoader private val encryptedImageLoader: Lazy<ImageLoader>,
    private val imageLoader: ImageLoader,
    private val vaultCacheStorage: VaultCacheStorage,
) {

    private val locks = List(LOCK_STRIPES) { Mutex() }
    private val creationsFromVault = Semaphore(MAX_PARALLEL_CREATIONS_FROM_VAULT)
    private val failedUuids = ConcurrentHashMap.newKeySet<String>()

    /**
     * Creates the thumbnail of an imported photo from its encrypted original. Videos use their video preview.
     */
    suspend fun createFromVault(uuid: String, type: PhotoType): Result<CreatedThumbnail> =
        lockFor(uuid).withLock {
            if (vaultCacheStorage.encryptedFileExists(ThumbnailFiles.path(uuid))) {
                return@withLock Result.success(CreatedThumbnail.Existing)
            }

            if (uuid in failedUuids) {
                return@withLock Result.failure(IllegalStateException("Creating the thumbnail of $uuid failed before"))
            }

            creationsFromVault.withPermit {
                val sourceFileName = if (type.isVideo) {
                    internalVideoPreviewFileName(uuid)
                } else {
                    internalFileName(uuid)
                }

                val request = ImageRequest.Builder(context)
                    .data(
                        EncryptedImageRequestData.VaultFile(
                            internalFileName = sourceFileName,
                            mimeType = type.mimeType,
                        )
                    )
                    .thumbnailSize()
                    .memoryCachePolicy(CachePolicy.DISABLED)
                    .build()

                decode(encryptedImageLoader.get(), request).mapCatching { bitmap ->
                    write(uuid, bitmap)
                    CreatedThumbnail.New(bitmap)
                }.onFailure {
                    failedUuids += uuid
                }
            }
        }

    fun forgetFailures() {
        failedUuids.clear()
    }

    /**
     * Creates the thumbnail of a photo while importing it.
     *
     * @param data The data for the photo. May be ByteArray or system Uri
     */
    suspend fun createFromImport(uuid: String, data: Any?, isVideo: Boolean): Result<Unit> =
        lockFor(uuid).withLock {
            val request = ImageRequest.Builder(context)
                .data(data)
                .thumbnailSize()
                .apply { if (isVideo) videoFramePercent(0.5) }
                .build()

            decode(imageLoader, request).mapCatching { bitmap ->
                write(uuid, bitmap)
                bitmap.recycle()
            }
        }

    private fun lockFor(uuid: String): Mutex =
        locks[uuid.hashCode().mod(LOCK_STRIPES)]

    private fun ImageRequest.Builder.thumbnailSize() =
        size(THUMBNAIL_SIZE)
            .scale(Scale.FILL)
            .precision(Precision.EXACT)
            .allowHardware(false)

    private suspend fun decode(loader: ImageLoader, request: ImageRequest): Result<Bitmap> =
        when (val result = loader.execute(request)) {
            is SuccessResult -> runCatching { result.drawable.toBitmap() }
            is ErrorResult -> Result.failure(result.throwable)
        }

    private suspend fun write(uuid: String, bitmap: Bitmap) = withContext(Dispatchers.IO) {
        val tmpPath = ThumbnailFiles.tmpPath(uuid)
        val output = vaultCacheStorage.openEncryptedOutput(tmpPath)
            ?: error("Could not open $tmpPath")

        try {
            output.use { bitmap.compress(Bitmap.CompressFormat.JPEG, THUMBNAIL_QUALITY, it) }
        } catch (e: Exception) {
            vaultCacheStorage.deleteEncryptedFile(tmpPath)
            throw e
        }

        if (!vaultCacheStorage.renameEncryptedFile(tmpPath, ThumbnailFiles.path(uuid))) {
            vaultCacheStorage.deleteEncryptedFile(tmpPath)
            error("Could not rename $tmpPath")
        }
    }
}

suspend fun createFromVault(uuid: String, type: PhotoType): Result<CreatedThumbnail> =
    lockFor(uuid).withLock {
        if (vaultCacheStorage.encryptedFileExists(ThumbnailFiles.path(uuid))) {
            return@withLock Result.success(CreatedThumbnail.Existing)
        }

        if (uuid in failedUuids) {
            return@withLock Result.failure(IllegalStateException("Creating the thumbnail of $uuid failed before"))
        }

        creationsFromVault.withPermit {
            val sourceFileName = if (type.isVideo) {
                internalVideoPreviewFileName(uuid)
            } else {
                internalFileName(uuid)
            }

            val request = ImageRequest.Builder(context)
                .data(
                    EncryptedImageRequestData.VaultFile(
                        internalFileName = sourceFileName,
                        mimeType = type.mimeType,
                    )
                )
                .thumbnailSize()
                .memoryCachePolicy(CachePolicy.DISABLED)
                .build()

            decode(encryptedImageLoader.get(), request).mapCatching { bitmap ->
                write(uuid, bitmap)
                CreatedThumbnail.New(bitmap)
            }.onFailure {
                failedUuids += uuid
            }
        }
    }

suspend fun createFromImport(uuid: String, data: Any?, isVideo: Boolean): Result<Unit> =
    lockFor(uuid).withLock {
        val request = ImageRequest.Builder(context)
            .data(data)
            .thumbnailSize()
            .apply { if (isVideo) videoFramePercent(0.5) }
            .build()

        decode(imageLoader, request).mapCatching { bitmap ->
            write(uuid, bitmap)
            bitmap.recycle()
        }
    }

@Singleton
class ThumbnailMaintainer @Inject constructor(
    private val sessionRepository: SessionRepository,
    private val photoRepository: PhotoRepository,
    private val vaultCacheStorage: VaultCacheStorage,
    private val vaultFileStorage: VaultFileStorage,
    private val thumbnailGenerator: ThumbnailGenerator,
    private val legacyEncryptionMigrator: LegacyEncryptionMigrator,
    private val config: Config,
) {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    private val runRequests = Channel<Unit>(Channel.CONFLATED)

    fun start() {
        scope.launch {
            sessionRepository.observe().collectLatest { session ->
                thumbnailGenerator.forgetFailures()
                if (session == null) return@collectLatest

                delay(StartDelay)
                runRequests.tryReceive()
                run()

                for (request in runRequests) {
                    run()
                }
            }
        }
    }

    fun requestRun() {
        runRequests.trySend(Unit)
    }

    internal suspend fun run() {
        val start = System.currentTimeMillis()

        deleteOutdatedVersions()
        deleteFilesDirThumbnails()

        val photos = photoRepository.findAllPhotosByImportDateDesc()
        deleteDeadThumbnails(photos, start)
        deleteStaleTmpFiles(start)
        createMissingThumbnails(photos)
    }

    private fun deleteOutdatedVersions() {
        vaultCacheStorage.listFiles(ThumbnailFiles.DIR)
            .filter { "${ThumbnailFiles.DIR}/${it.name}" != ThumbnailFiles.CURRENT_DIR }
            .forEach {
                Timber.i("Deleting outdated thumbnails: ${it.name}")
                vaultCacheStorage.deleteDir("${ThumbnailFiles.DIR}/${it.name}")
            }
    }

    private fun deleteFilesDirThumbnails() {
        if (legacyEncryptionMigrator.migrationNeeded() || config.legacyCurrentlyMigrating) return

        vaultFileStorage.listFiles()
            .filter { it.endsWith("$PHOTOK_FILE_EXTENSION$THUMBNAIL_SUFFIX") }
            .forEach {
                Timber.i("Deleting files dir thumbnail: $it")
                vaultFileStorage.deleteEncryptedFile(it)
            }
    }

    /**
     * Files created after [runStart] are kept, because imports create the thumbnail before the photo is saved.
     */
    private fun deleteDeadThumbnails(photos: List<Photo>, runStart: Long) {
        val uuids = photos.map { it.uuid }.toSet()

        vaultCacheStorage.listFiles(ThumbnailFiles.CURRENT_DIR)
            .filter { ThumbnailFiles.uuidOf(it) !in uuids && it.lastModified() < runStart }
            .forEach {
                Timber.i("Deleting dead thumbnail: ${it.name}")
                vaultCacheStorage.deleteEncryptedFile(ThumbnailFiles.pathInCurrentDir(it))
            }
    }

    /**
     * Files created after [runStart] are kept, because they may still be written.
     */
    private fun deleteStaleTmpFiles(runStart: Long) {
        vaultCacheStorage.listFiles(ThumbnailFiles.CURRENT_DIR)
            .filter { ThumbnailFiles.isTmp(it) && it.lastModified() < runStart }
            .forEach {
                Timber.i("Deleting stale tmp thumbnail: ${it.name}")
                vaultCacheStorage.deleteEncryptedFile(ThumbnailFiles.pathInCurrentDir(it))
            }
    }

    private suspend fun createMissingThumbnails(photos: List<Photo>) {
        for (photo in photos) {
            thumbnailGenerator.createFromVault(photo.uuid, photo.type)
                .onSuccess { created ->
                    if (created is CreatedThumbnail.New) {
                        created.bitmap.recycle()
                    }
                }
                .onFailure {
                    Timber.w(it, "Could not create thumbnail for ${photo.uuid}")
                }
        }
    }
}

private fun deleteDeadThumbnails(photos: List<Photo>, runStart: Long) {
    val uuids = photos.map { it.uuid }.toSet()

    vaultCacheStorage.listFiles(ThumbnailFiles.CURRENT_DIR)
        .filter { ThumbnailFiles.uuidOf(it) !in uuids && it.lastModified() < runStart }
        .forEach {
            Timber.i("Deleting dead thumbnail: ${it.name}")
            vaultCacheStorage.deleteEncryptedFile(ThumbnailFiles.pathInCurrentDir(it))
        }
}

private fun deleteStaleTmpFiles(runStart: Long) {
    vaultCacheStorage.listFiles(ThumbnailFiles.CURRENT_DIR)
        .filter { ThumbnailFiles.isTmp(it) && it.lastModified() < runStart }
        .forEach {
            Timber.i("Deleting stale tmp thumbnail: ${it.name}")
            vaultCacheStorage.deleteEncryptedFile(ThumbnailFiles.pathInCurrentDir(it))
        }
}

suspend fun safeImportPhoto(sourceUri: Uri, importSource: ImportSource): String {
    val metaData = app.contentResolver.getMetadataFor(sourceUri)

    val type = PhotoType.fromMimeType(metaData.mimeType)
    if (type == PhotoType.UNDEFINED) return String.empty


    val inputStream = io.openFileInput(sourceUri)
    val photo = Photo(
        fileName = metaData.fileName ?: UUID.randomUUID().toString(),
        importedAt = System.currentTimeMillis(),
        lastModified = metaData.lastModified,
        type = type,
        size = metaData.size ?: 0,
    )

    val created = safeCreatePhoto(photo, inputStream, sourceUri)
    inputStream?.lazyClose()

    if (!created) {
        return String.empty
    }

    if (!config.deleteImportedFiles || importSource == ImportSource.Share) {
        return photo.uuid
    }

    val deleted = io.deleteFile(sourceUri)
    return if (deleted == true) photo.uuid else String.empty
}

suspend fun safeImportPhotoFile(file: File, fileName: String, type: PhotoType): String {
    val photo = Photo(
        fileName = fileName,
        importedAt = System.currentTimeMillis(),
        lastModified = file.lastModified(),
        type = type,
        size = file.length(),
    )

    val inputStream = try {
        file.inputStream()
    } catch (e: IOException) {
        Timber.e("Error opening file for import: $e")
        return String.empty
    }

    val created = safeCreatePhoto(photo, inputStream, file)
    inputStream.lazyClose()

    return if (created) photo.uuid else String.empty
}

private suspend fun safeCreatePhoto(
    photo: Photo,
    source: InputStream?,
    thumbnailSource: Any? = null
): Boolean {
    val fileLen = createPhotoFile(photo, source)
    var success = fileLen != -1L

    if (success) {
        photo.size = fileLen

        if (thumbnailSource != null) {
            createThumbnail(photo, thumbnailSource)
        }

        val photoId = insert(photo)
        success = photoId != -1L
    }

    if (!success) {
        deleteInternalPhotoData(photo)
    }

    return success
}

fun createPhotoFile(photo: Photo, source: InputStream?): Long {
    try {
        val encryptedDestination = vaultFileStorage.openEncryptedOutput(photo.internalFileName)

        source ?: return -1L
        encryptedDestination ?: return -1L

        val fileLen = source.copyTo(encryptedDestination)
        encryptedDestination.lazyClose()

        return fileLen
    } catch (e: IOException) {
        Timber.e("Error while writing file: $e")
        return -1L
    }
}

suspend fun safeDeletePhoto(photo: Photo): Boolean {
    val deletedElements = delete(photo)
    val success = deletedElements != -1

    if (success) {
        deleteInternalPhotoData(photo)
        albumDao.unlink(photo.uuid)
    }

    return success
}

fun deleteInternalPhotoData(photo: Photo): Boolean {
    vaultCacheStorage.deleteEncryptedFile(ThumbnailFiles.path(photo.uuid))

    return vaultFileStorage.deleteEncryptedFile(photo.internalFileName)
            && (!photo.type.isVideo || vaultFileStorage.deleteEncryptedFile(photo.internalVideoPreviewFileName))
}

suspend fun exportPhoto(photo: Photo, target: Uri): Boolean = withContext(Dispatchers.IO) {
    try {
        val inputStream =
            vaultFileStorage.openEncryptedInput(photo.internalFileName)
        inputStream ?: return@withContext false

        val outputStream = createExternalOutputStream(photo, target)
        outputStream ?: return@withContext false

        val wrote = suspendCancellableCoroutine { continuation ->
            val wrote = inputStream.copyTo(outputStream)
            continuation.resume(wrote)
        }

        outputStream.lazyClose()

        var deleted = true
        if (config.deleteExportedFiles) {
            deleted = safeDeletePhoto(photo)
        }

        wrote != -1L && deleted
    } catch (e: IOException) {
        Timber.d("Error exporting file: ${photo.fileName} $e")
        false
    }
}

