class EncryptedImageFetcher(
    private val vaultFileStorage: VaultFileStorage,
    private val requestData: EncryptedImageRequestData.VaultFile,
    private val options: Options,
    private val context: Context,
) : Fetcher {

    override suspend fun fetch(): FetchResult? = withContext(Dispatchers.IO) {
        val inputStream =
            vaultFileStorage.openEncryptedInput(requestData.internalFileName)
        inputStream ?: return@withContext null

        val mayBeAnimatedImage = when (requestData.mimeType) {
            PhotoType.GIF.mimeType -> true
            PhotoType.WEBP.mimeType -> true
            else -> false
        }

        if (mayBeAnimatedImage && requestData.playAnimation) {
            val drawable = decodeAnimatedImage(inputStream)
            DrawableResult(
                drawable = drawable,
                isSampled = true,
                dataSource = DataSource.MEMORY,
            )
        } else {
            SourceResult(
                source = ImageSource(
                    source = inputStream.inMemoryBufferedSource(),
                    context = context,
                ),
                mimeType = requestData.mimeType,
                DataSource.MEMORY,
            )
        }
    }

    private suspend fun InputStream.inMemoryBufferedSource(): BufferedSource {
        val rawBytes = this.use { it.readBytesSuspending() }
        val byteStream = ByteArrayInputStream(rawBytes)

        return byteStream.source().buffer()
    }

    private suspend fun decodeAnimatedImage(inputStream: InputStream) =
        if (Build.VERSION.SDK_INT >= VERSION_CODES.S) {
            val bytes = inputStream.use { it.readBytesSuspending() }
            val source = ImageDecoder.createSource(bytes)
            ImageDecoder.decodeDrawable(source) { decoder, info, _ ->
                decoder.setTargetSampleSize(sampleSizeFor(info.size))
            }
        } else {
            @Suppress("DEPRECATION")
            val movie = Movie.decodeStream(inputStream)
            MovieDrawable(movie)
        }

    private fun sampleSizeFor(sourceSize: android.util.Size): Int =
        DecodeUtils.calculateInSampleSize(
            srcWidth = sourceSize.width,
            srcHeight = sourceSize.height,
            dstWidth = options.size.width.pxOrElse { sourceSize.width },
            dstHeight = options.size.height.pxOrElse { sourceSize.height },
            scale = options.scale,
        )
}

override suspend fun execAndWrite(
    imageRequest: ImageRequest,
    outputStream: OutputStream?,
    compressionPercent: Int,
): Result<Unit> = withContext(Dispatchers.IO) {

    outputStream ?: return@withContext Result.failure(Exception("stream is null"))

    when (val imageResult = imageLoader.execute(imageRequest)) {
        is SuccessResult -> suspendCoroutine { continuation ->
            try {
                outputStream.use { out ->
                    val bitmap = imageResult.drawable.toBitmap()
                    bitmap.compress(Bitmap.CompressFormat.JPEG, compressionPercent, out)
                    bitmap.recycle()
                }

                continuation.resume(Result.success(Unit))
            } catch (e: Exception) {
                continuation.resume(Result.failure(e))
            }
        }
        is ErrorResult -> Result.failure(imageResult.throwable)
    }
}

class SessionBoundMemoryCacheInterceptor @Inject constructor(
    private val sessionRepository: SessionRepository,
    @EncryptedImageMemoryCache private val memoryCache: MemoryCache,
) : Interceptor {

    override suspend fun intercept(chain: Interceptor.Chain): ImageResult {
        val session = sessionRepository.get()
        val result = chain.proceed(chain.request)

        if (sessionRepository.get() === session) {
            return result
        }

        if (result is SuccessResult) {
            result.memoryCacheKey?.let { memoryCache.remove(it) }
        }

        return ErrorResult(
            drawable = null,
            request = chain.request,
            throwable = IllegalStateException("Session ended while loading"),
        )
    }
}

class ThumbnailFetcher(
    private val vaultCacheStorage: VaultCacheStorage,
    private val thumbnailGenerator: ThumbnailGenerator,
    private val requestData: EncryptedImageRequestData.Thumbnail,
    private val context: Context,
) : Fetcher {

    override suspend fun fetch(): FetchResult? = withContext(Dispatchers.IO) {
        val path = ThumbnailFiles.path(requestData.uuid)

        if (vaultCacheStorage.encryptedFileExists(path)) {
            val inputStream = vaultCacheStorage.openEncryptedInput(path)
            inputStream ?: return@withContext null

            val bytes = readDecodableBytes(inputStream)
            if (bytes != null) {
                return@withContext sourceResult(bytes)
            }

            Timber.w("Deleting unreadable thumbnail of ${requestData.uuid}")
            vaultCacheStorage.deleteEncryptedFile(path)
        }

        val created = thumbnailGenerator.createFromVault(requestData.uuid, requestData.type)
            .getOrElse {
                Timber.w(it, "Could not create thumbnail for ${requestData.uuid}")
                return@withContext null
            }

        when (created) {
            is CreatedThumbnail.New -> DrawableResult(
                drawable = created.bitmap.toDrawable(context.resources),
                isSampled = true,
                dataSource = DataSource.DISK,
            )

            is CreatedThumbnail.Existing -> {
                val inputStream = vaultCacheStorage.openEncryptedInput(path)
                inputStream ?: return@withContext null

                readDecodableBytes(inputStream)?.let { sourceResult(it) }
            }
        }
    }

    private suspend fun readDecodableBytes(inputStream: InputStream): ByteArray? {
        val bytes = try {
            inputStream.use { it.readBytesSuspending() }
        } catch (e: IOException) {
            Timber.w(e, "Could not read thumbnail of ${requestData.uuid}")
            return null
        }

        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)

        return bytes.takeIf { bounds.outWidth > 0 && bounds.outHeight > 0 }
    }

    private fun sourceResult(bytes: ByteArray) = SourceResult(
        source = ImageSource(
            source = ByteArrayInputStream(bytes).source().buffer(),
            context = context,
        ),
        mimeType = THUMBNAIL_MIME_TYPE,
        dataSource = DataSource.DISK,
    )
}

