abstract class BaseProcessBottomSheetDialogFragment<T> : BindableBottomSheetDialogFragment<DialogBottomSheetProcessBinding>(
    R.layout.dialog_bottom_sheet_process
) {
    @get:StringRes
    abstract val processingLabelTextResource: Int
    abstract val canAbort: Boolean
    open val itemSource: List<T>? = null

    /**
     * Abstract [BaseProcessViewModel].
     * Needs to be set in the child, handles processing.
     */
    abstract val viewModel: BaseProcessViewModel<T>

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        viewModel.processState = ProcessState.INITIALIZE

        activity?.window?.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)

        viewModel.addOnPropertyChange<ProcessState>(BR.processState) {
            val label: String = when (it) {
                ProcessState.INITIALIZE -> {
                    isCancelable = false
                    setStatusIcon(null)
                    binding.processCloseButton.hide()
                    binding.processAbortButton.show()
                    binding.processItemsProgressIndicatorLayout.hide()
                    binding.processPercentLayout.hide()
                    binding.processFailuresWarnMessage.vanish()
                    getString(R.string.process_initialize)
                }
                ProcessState.PROCESSING -> {
                    isCancelable = false
                    binding.processItemsProgressIndicatorLayout.show()
                    binding.processPercentLayout.show()
                    binding.processProcessingIndicator.show()
                    getString(processingLabelTextResource)
                }
                ProcessState.FINISHED -> {
                    onProcessingDone()
                    setStatusIcon(R.drawable.ic_check, android.R.color.holo_green_dark)
                    // auto dismiss
                    lifecycleScope.launch {
                        delay(1500)
                        runCatching { dismiss() } // May throw if already dismissed by user
                    }
                    getString(R.string.process_finished)
                }
                ProcessState.ABORTED -> {
                    onProcessingDone()
                    setStatusIcon(R.drawable.ic_close, android.R.color.holo_red_dark)
                    getString(R.string.process_aborted)
                }
            }
            binding.processLabel.text = label
        }

        prepareViewModel(itemSource)
        viewModel.runProcessing()
    }

    open fun onProcessingDone() {
        activity?.window?.clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)

        isCancelable = true
        binding.processCloseButton.show()
        binding.processAbortButton.hide()
        binding.processProcessingIndicator.hide()
        if (viewModel.failuresOccurred) {
            binding.processFailuresWarnMessage.show()
        }
    }

    /**
     * Called before viewModel starts processing.
     * Assign data and variables in implementations.
     */
    open fun prepareViewModel(items: List<T>?) {
        if (items != null) {
            viewModel.items = items
            viewModel.elementsToProcess = items.size
        }
    }

    private fun setStatusIcon(drawable: Int?, color: Int = 0) {
        if (drawable == null) {
            binding.processStatusImageView.setImageDrawable(null)
            return
        }

        binding.processStatusImageView.setImageDrawable(
            ContextCompat.getDrawable(
                requireContext(),
                drawable
            )
        )
        binding.processStatusImageView.setColorFilter(
            ContextCompat.getColor(
                requireContext(),
                color
            )
        )
    }

    override fun bind(binding: DialogBottomSheetProcessBinding) {
        super.bind(binding)
        binding.context = this
        binding.viewModel = viewModel
    }
}

open fun prepareViewModel(items: List<T>?) {
    if (items != null) {
        viewModel.items = items
        viewModel.elementsToProcess = items.size
    }
}

abstract class BaseProcessViewModel<T>(app: Application) : ObservableViewModel(app) {

    /**
     * List of [T].
     * Set by the fragment or loaded by the ViewModel in [preProcess].
     * Gets processed in [processLoop].
     */
    var items: List<T> = emptyList()

    /**
     * The processing state should be checked every time in [processLoop].
     */
    @get:Bindable
    var processState: ProcessState = ProcessState.INITIALIZE
        set(value) {
            field = value
            notifyChange(BR.processState, value)
        }

    @get:Bindable
    var progressPercent: Int = 0
        set(value) {
            field = value
            notifyChange(BR.progressPercent, value)
        }


    @get:Bindable
    var current: Int = 0
        set(value) {
            field = value
            notifyChange(BR.current, value)
        }

    /**
     * The number of elements to get processed.
     * Gets set automatically.
     */
    @get:Bindable
    var elementsToProcess = 0
        set(value) {
            field = value
            notifyChange(BR.elementsToProcess, value)
        }

    /**
     * Indicates if failures occurred.
     * Gets evaluated by base DialogFragment to show warning. Should be set in [processItem] if an elements fails.
     */
    var failuresOccurred = false

    /**
     * The job doing the actual work. Kept so a subclass that wants to stop mid-item can cancel
     * it. [cancel] does not touch it, so every subclass that does not opt in keeps the plain
     * flag based behaviour.
     */
    protected var processingJob: Job? = null
        private set

    /**
     * Runs [preProcess], [processLoop] and [postProcess].
     * launched in [viewModelScope].
     *
     * [postProcess] also runs when [viewModelScope] is canceled, so a subclass can always release
     * what [preProcess] opened.
     */
    fun runProcessing() = viewModelScope.launch(Dispatchers.IO) {
        val job = launch(start = CoroutineStart.LAZY) {
            preProcess()
            processLoop()
        }
        processingJob = job

        try {
            job.start()
            job.join()
        } finally {
            withContext(NonCancellable) { postProcess() }
        }
    }

    /**
     * Gets executed before [processLoop].
     */
    open suspend fun preProcess() {
        processState = ProcessState.PROCESSING
        updateProgress()
    }

    /**
     * Processing loop.
     * Calls [processItem].
     * Handles: Aborting and Updating progress.
     */
    private suspend fun processLoop() {
        for (item in items) {
            if (processState == ProcessState.ABORTED) {
                return
            }

            processItem(item)
            itemProcessed()
        }
    }

    /**
     * Template method. Gets called by [processLoop].
     * Should implement the processing of one item.
     */
    abstract suspend fun processItem(item: T)

    /**
     * Get executed after [processLoop].
     */
    open suspend fun postProcess() {
        if (processState != ProcessState.ABORTED) {
            processState = ProcessState.FINISHED
        }
    }

    /**
     * Updates the state to [ProcessState.ABORTED].
     */
    open fun cancel() {
        processState = ProcessState.ABORTED
    }

    /**
     * Update the progress.
     */
    private fun itemProcessed() {
        current++
        updateProgress()
    }

    private fun updateProgress() {
        if (elementsToProcess == 0) {
            return
        }

        progressPercent = (current * 100) / elementsToProcess
    }

    /**
     * Sets [failuresOccurred] to true
     */
    fun failuresOccurred() {
        failuresOccurred = true
    }
}

@get:Bindable
var processState: ProcessState = ProcessState.INITIALIZE
    set(value) {
        field = value
        notifyChange(BR.processState, value)
    }

@get:Bindable
var elementsToProcess = 0
    set(value) {
        field = value
        notifyChange(BR.elementsToProcess, value)
    }

fun runProcessing() = viewModelScope.launch(Dispatchers.IO) {
    val job = launch(start = CoroutineStart.LAZY) {
        preProcess()
        processLoop()
    }
    processingJob = job

    try {
        job.start()
        job.join()
    } finally {
        withContext(NonCancellable) { postProcess() }
    }
}

open suspend fun preProcess() {
    processState = ProcessState.PROCESSING
    updateProgress()
}

private suspend fun processLoop() {
    for (item in items) {
        if (processState == ProcessState.ABORTED) {
            return
        }

        processItem(item)
        itemProcessed()
    }
}

open suspend fun postProcess() {
    if (processState != ProcessState.ABORTED) {
        processState = ProcessState.FINISHED
    }
}

open fun cancel() {
    processState = ProcessState.ABORTED
}

private fun itemProcessed() {
    current++
    updateProgress()
}

fun failuresOccurred() {
    failuresOccurred = true
}

enum class ProcessState {
    INITIALIZE,
    PROCESSING,
    FINISHED,
    ABORTED
}

