private fun lockUntil(lockedUntil: Long) {
    _uiState.update { it.copy(lockedUntil = lockedUntil, loading = false) }

    lockoutJob?.cancel()
    lockoutJob = viewModelScope.launch {
        while (System.currentTimeMillis() < lockedUntil) {
            delay(1.seconds)
        }
        dismissLockout()
    }
}

private fun unlockWithPassword() {
    val password = _uiState.value.password
    _uiState.update { it.copy(loading = true, wrongPassword = false) }

    viewModelScope.launch(Dispatchers.IO) {
        try {
            vaultService.unlock(UnlockRequest.Password(password))
                .onSuccess { session ->
                    passwordAttemptsUseCase.onSuccessfulUnlock()
                    sessionRepository.set(session)

                    if (legacyEncryptionMigrator.migrationNeeded() || config.legacyCurrentlyMigrating) {
                        val legacySession = legacyEncryption.obtainSession(password)
                        legacyEncryptionMigrator.initialize(legacySession)

                        _uiState.update { it.copy(loading = false) }
                        navigationEventsChannel.trySend(UnlockNavigationEvent.StartLegacyMigration)
                    } else {
                        createMissingRecoveryPhrase(session)
                        vaultService.upgradePasswordProtectionIfOutdated(password, session.vmk)

                        _uiState.update { it.copy(loading = false) }
                        sendUnlockedEvent()
                    }
                }
                .onFailure {
                    viewModelScope.launch {
                        intruderWarningCaptureService.captureWrongPasswordAttempt()
                            .onFailure { error ->
                                Timber.e(error, "Failed to capture intruder warning")
                            }
                    }

                    when (val result = passwordAttemptsUseCase.onFailedAttempt()) {
                        is PasswordAttemptsResult.Locked -> lockUntil(result.lockedUntil)
                        PasswordAttemptsResult.None -> _uiState.update {
                            it.copy(loading = false, wrongPassword = true)
                        }

                        PasswordAttemptsResult.Erased -> {
                            viewModelScope.launch {
                                eraseVaultDataUseCase()
                            }
                            _uiState.update { it.copy(loading = false, wrongPassword = true) }
                        }
                    }
                }
        } catch (e: Exception) {
            Timber.e(e)
            _uiState.update { it.copy(loading = false) }
            navigationEventsChannel.trySend(UnlockNavigationEvent.ShowError)
        }
    }
}

enum class EncryptionVersionByte(val value: Byte) {
    One(0x01),
    Two(0x02);

    val headerSize: Int
        get() = when (this) {
            EncryptionVersionByte.One -> 1 + SALT_SIZE + IV_SIZE
            EncryptionVersionByte.Two -> 1 + IV_SIZE
        }

    companion object {
        fun fromValue(value: Byte): EncryptionVersionByte {
            return entries.find { it.value == value } ?: error("Unknown version byte: $value")
        }
    }
}

class VaultCacheStorage @Inject constructor(
    private val sessionRepository: SessionRepository,
    private val cryptoEngine: CryptoEngine,
    private val app: Application,
) : EncryptedStorage {
    override fun openEncryptedInput(fileName: String): CipherInputStream? = try {
        val session = requireNotNull(sessionRepository.get())
        val input = FileInputStream(cacheFile(fileName))
        cryptoEngine.createDecryptStream(input, session)
    } catch (e: Exception) {
        Timber.e(e)
        null
    }

    override fun openEncryptedOutput(fileName: String): CipherOutputStream? = try {
        val session = requireNotNull(sessionRepository.get())
        val file = cacheFile(fileName)
        file.parentFile?.mkdirs()
        cryptoEngine.createEncryptStream(FileOutputStream(file), session)
    } catch (e: Exception) {
        Timber.e(e)
        null
    }

    override fun deleteEncryptedFile(fileName: String): Boolean =
        cacheFile(fileName).delete()

    override fun encryptedFileExists(fileName: String): Boolean =
        cacheFile(fileName).exists()

    override fun renameEncryptedFile(currentFileName: String, newFileName: String): Boolean =
        cacheFile(currentFileName).renameTo(cacheFile(newFileName))

    fun listFiles(dir: String): List<File> =
        cacheFile(dir).listFiles()?.toList().orEmpty()

    fun deleteDir(dir: String): Boolean =
        cacheFile(dir).deleteRecursively()

    private fun cacheFile(fileName: String): File = File(app.cacheDir, fileName)
}

class VaultFileStorage @Inject constructor(
    private val sessionRepository: SessionRepository,
    private val cryptoEngine: CryptoEngine,
    private val app: Application,
) : EncryptedStorage {
    override fun openEncryptedInput(fileName: String): CipherInputStream? = try {
        val session = requireNotNull(sessionRepository.get())
        val input = app.openFileInput(fileName)
        cryptoEngine.createDecryptStream(input, session)
    } catch (e: Exception) {
        Timber.e(e)
        null
    }

    override fun openEncryptedOutput(fileName: String): CipherOutputStream? = try {
        val session = requireNotNull(sessionRepository.get())
        val output = app.openFileOutput(fileName, Context.MODE_PRIVATE)
        cryptoEngine.createEncryptStream(output, session)
    } catch (e: Exception) {
        Timber.e(e)
        null
    }

    override fun deleteEncryptedFile(fileName: String): Boolean {
        val success = app.deleteFile(fileName)
        if (!success) {
            Timber.e("Error deleting internal file: $fileName")
        }

        return success
    }

    override fun encryptedFileExists(fileName: String): Boolean =
        app.getFileStreamPath(fileName).exists()

    override fun renameEncryptedFile(currentFileName: String, newFileName: String): Boolean {
        val currentFile = app.getFileStreamPath(currentFileName)
        val newFile = app.getFileStreamPath(newFileName)
        return currentFile.renameTo(newFile)
    }

    fun listFiles(): List<String> =
        app.fileList().toList()

}

