@Override
public void surfaceDestroyed(SurfaceHolder holder) {
    Log.v("SDL", "surfaceDestroyed()");

    // Transition to pause, if needed
    SDLActivity.mNextNativeState = SDLActivity.NativeState.PAUSED;
