@Override
public void surfaceChanged(SurfaceHolder holder,
                           int format, int width, int height) {
    Log.v("SDL", "surfaceChanged()");

    if (SDLActivity.mSingleton == null) {
        return;
    }

    mWidth = width;
    mHeight = height;
    int nDeviceWidth = width;
    int nDeviceHeight = height;
    try
    {
        if (Build.VERSION.SDK_INT >= 17 /* Android 4.2 (JELLY_BEAN_MR1) */) {
            DisplayMetrics realMetrics = new DisplayMetrics();
            mDisplay.getRealMetrics( realMetrics );
            nDeviceWidth = realMetrics.widthPixels;
            nDeviceHeight = realMetrics.heightPixels;
        }
    } catch(Exception ignored) {
    }

    synchronized(SDLActivity.getContext()) {
        // In case we're waiting on a size change after going fullscreen, send a notification.
        SDLActivity.getContext().notifyAll();
    }

    Log.v("SDL", "Window size: " + width + "x" + height);
    Log.v("SDL", "Device size: " + nDeviceWidth + "x" + nDeviceHeight);
    SDLActivity.nativeSetScreenResolution(width, height, nDeviceWidth, nDeviceHeight, mDisplay.getRefreshRate());
    SDLActivity.onNativeResize();

    // Prevent a screen distortion glitch,
    // for instance when the device is in Landscape and a Portrait App is resumed.
    boolean skip = false;
    int requestedOrientation = SDLActivity.mSingleton.getRequestedOrientation();

    if (requestedOrientation == ActivityInfo.SCREEN_ORIENTATION_PORTRAIT || requestedOrientation == ActivityInfo.SCREEN_ORIENTATION_SENSOR_PORTRAIT) {
        if (mWidth > mHeight) {
           skip = true;
        }
    } else if (requestedOrientation == ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE || requestedOrientation == ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE) {
        if (mWidth < mHeight) {
           skip = true;
        }
    }

    // Special Patch for Square Resolution: Black Berry Passport
    if (skip) {
       double min = Math.min(mWidth, mHeight);
       double max = Math.max(mWidth, mHeight);

       if (max / min < 1.20) {
          Log.v("SDL", "Don't skip on such aspect-ratio. Could be a square resolution.");
          skip = false;
       }
    }

    // Don't skip in MultiWindow.
    if (skip) {
        if (Build.VERSION.SDK_INT >= 24 /* Android 7.0 (N) */) {
            if (SDLActivity.mSingleton.isInMultiWindowMode()) {
                Log.v("SDL", "Don't skip in Multi-Window");
                skip = false;
            }
        }
    }

    if (skip) {
       Log.v("SDL", "Skip .. Surface is not ready.");
       mIsSurfaceReady = false;
       return;
    }

    /* If the surface has been previously destroyed by onNativeSurfaceDestroyed, recreate it here */
    SDLActivity.onNativeSurfaceChanged();

    /* Surface is ready */
    mIsSurfaceReady = true;

    SDLActivity.mNextNativeState = SDLActivity.NativeState.RESUMED;
    SDLActivity.handleNativeState();
}

public boolean onCapturedPointerEvent(MotionEvent event)
{
    int action = event.getActionMasked();

    float x, y;
    switch (action) {
        case MotionEvent.ACTION_SCROLL:
            x = event.getAxisValue(MotionEvent.AXIS_HSCROLL, 0);
            y = event.getAxisValue(MotionEvent.AXIS_VSCROLL, 0);
            SDLActivity.onNativeMouse(0, action, x, y, false);
            return true;

        case MotionEvent.ACTION_HOVER_MOVE:
        case MotionEvent.ACTION_MOVE:
            x = event.getX(0);
            y = event.getY(0);
            SDLActivity.onNativeMouse(0, action, x, y, true);
            return true;

        case MotionEvent.ACTION_BUTTON_PRESS:
        case MotionEvent.ACTION_BUTTON_RELEASE:

            // Change our action value to what SDL's code expects.
            if (action == MotionEvent.ACTION_BUTTON_PRESS) {
                action = MotionEvent.ACTION_DOWN;
            } else { /* MotionEvent.ACTION_BUTTON_RELEASE */
                action = MotionEvent.ACTION_UP;
            }

            x = event.getX(0);
            y = event.getY(0);
            int button = event.getButtonState();

            SDLActivity.onNativeMouse(button, action, x, y, true);
            return true;
    }

    return false;
}

private class PartialMatchArrayAdapter extends ArrayAdapter {

    List<String> presets;
    List<String> suggestions = new ArrayList<>();

    Filter partialMatchFilter = new Filter() {
        @Override
        public CharSequence convertResultToString(Object resultValue) {
            return resultValue.toString().toLowerCase();
        }

        @Override
        protected FilterResults performFiltering(CharSequence constraint) {
            FilterResults results = new FilterResults();
            if (constraint != null) {
                suggestions.clear();
                String substring = constraint.toString().toLowerCase();
                for (String preset: presets) {
                    if (preset.toLowerCase().contains(substring)) {
                        suggestions.add(preset);
                    }
                }
                results.values = suggestions;
                results.count = suggestions.size();
            }
            return results;
        }

        @Override
        protected void publishResults(CharSequence constraint, FilterResults results) {
            if (results != null && results.count > 0) {
                List<String> filterList = (ArrayList<String>)results.values;
                clear();
                addAll(filterList);
                notifyDataSetChanged();
            }
        }
    };

    PartialMatchArrayAdapter(Context context, List<String> presets) {
        super(context, android.R.layout.simple_list_item_1);
        this.presets = presets;
    }

    @Override @NonNull
    public Filter getFilter() {
        return partialMatchFilter;
    }
}

