public interface HttpHandler {
    /**
     * Begin an HTTP request
     * @param url URL for the requested resource
     * @param cb Callback for handling request result
     * @return identifier associated with this network request, used to canceling the request
     */
    Object startRequest(@NonNull final String url, @NonNull final Callback cb);

    /**
     * Cancel an HTTP request
     * @param request an identifier for the request to be cancelled
     */
    void cancelRequest(final Object request);

    /**
     * {@code Callback}
     * Passes network responses from underlying implementation to be processed internally
     */
    interface Callback {
        /**
         * Network request failed response
         * @param e Exception representing the failed network request
         */
        void onFailure(@Nullable final IOException e);

        /**
         * Called when the HTTP response was successfully returned by the remote server
         * @param code Status code returned from the network response
         * @param body Data comprising the body of the network response
         */
        void onResponse(final int code, @Nullable final byte[] body);

        /**
         * Called when the request could not be executed due to cancellation
         */
        void onCancel();
    }
}

interface Callback {
    /**
     * Network request failed response
     * @param e Exception representing the failed network request
     */
    void onFailure(@Nullable final IOException e);

    /**
     * Called when the HTTP response was successfully returned by the remote server
     * @param code Status code returned from the network response
     * @param body Data comprising the body of the network response
     */
    void onResponse(final int code, @Nullable final byte[] body);

    /**
     * Called when the request could not be executed due to cancellation
     */
    void onCancel();
}

public class ConfigChooser implements GLSurfaceView.EGLConfigChooser {

    /**
     * Construct a {@code ConfigChooser} to match the given framebuffer parameters
     * @param r Red bits
     * @param g Green bits
     * @param b Blue bits
     * @param a Alpha bits
     * @param depth Depth bits
     * @param stencil Stencil bits
     */
    public ConfigChooser(final int r, final int g, final int b, final int a, final int depth, final int stencil) {
        mRedSize = r;
        mGreenSize = g;
        mBlueSize = b;
        mAlphaSize = a;
        mDepthSize = depth;
        mStencilSize = stencil;
    }

    /*
     * This EGL config specification is used to specify 2.0 rendering. We use a minimum size of 4 bits for red/green/blue, but
     * will perform actual matching in chooseConfig() below.
     */
    private static int EGL_OPENGL_ES2_BIT = 4;
    private static int[] s_configAttribs = {EGL10.EGL_RED_SIZE, 4, EGL10.EGL_GREEN_SIZE, 4, EGL10.EGL_BLUE_SIZE, 4,
        EGL10.EGL_RENDERABLE_TYPE, EGL_OPENGL_ES2_BIT, EGL10.EGL_NONE};

    @Override
    public EGLConfig chooseConfig(final EGL10 egl, final EGLDisplay display) {
        // Get the number of minimally matching EGL configurations
        final int[] num_config = new int[1];
        egl.eglChooseConfig(display, s_configAttribs, null, 0, num_config);

        final int numConfigs = num_config[0];
        if (numConfigs <= 0) {
            throw new IllegalArgumentException("No configs match configSpec");
        }

        // Allocate then read the array of minimally matching EGL configs
        final EGLConfig[] configs = new EGLConfig[numConfigs];
        egl.eglChooseConfig(display, s_configAttribs, configs, numConfigs, num_config);

        // Now return the "best" one
        return chooseConfig(egl, display, configs);
    }

    public EGLConfig chooseConfig(final EGL10 egl, final EGLDisplay display, final EGLConfig[] configs) {
        EGLConfig bestConfig = null;
        int bestDepth = 0;
        int bestStencil = 0;

        for (final EGLConfig config : configs) {
            final int d = findConfigAttrib(egl, display, config, EGL10.EGL_DEPTH_SIZE);
            final int s = findConfigAttrib(egl, display, config, EGL10.EGL_STENCIL_SIZE);

            // We need at least mDepthSize and mStencilSize bits
            if (d < mDepthSize || s < mStencilSize) { continue; }

            // We want an *exact* match for red/green/blue/alpha
            final int r = findConfigAttrib(egl, display, config, EGL10.EGL_RED_SIZE);
            final int g = findConfigAttrib(egl, display, config, EGL10.EGL_GREEN_SIZE);
            final int b = findConfigAttrib(egl, display, config, EGL10.EGL_BLUE_SIZE);
            final int a = findConfigAttrib(egl, display, config, EGL10.EGL_ALPHA_SIZE);

            if (r == mRedSize && g == mGreenSize && b == mBlueSize && a == mAlphaSize &&
                d >= bestDepth && s >= bestStencil) {

                bestConfig = config;
                bestDepth = d;
                bestStencil = s;
            }
        }
        return bestConfig;
    }

    private int findConfigAttrib(final EGL10 egl, final EGLDisplay display, final EGLConfig config, final int attribute) {
        if (egl.eglGetConfigAttrib(display, config, attribute, mValue)) {
            return mValue[0];
        }
        return 0;
    }

    // Subclasses can adjust these values:
    protected int mRedSize;
    protected int mGreenSize;
    protected int mBlueSize;
    protected int mAlphaSize;
    protected int mDepthSize;
    protected int mStencilSize;
    private int[] mValue = new int[1];
}

public ConfigChooser(final int r, final int g, final int b, final int a, final int depth, final int stencil) {
    mRedSize = r;
    mGreenSize = g;
    mBlueSize = b;
    mAlphaSize = a;
    mDepthSize = depth;
    mStencilSize = stencil;
}

