@Override
public GLViewHolder build(Context context) {
    GLSurfaceView view = new GLSurfaceView(context);

    view.setEGLContextClientVersion(2);
    view.setPreserveEGLContextOnPause(true);
    try {
        view.setEGLConfigChooser(new ConfigChooser(8, 8, 8, 0, 16, 8));
        return new GLSurfaceViewHolder(view);
    } catch(IllegalArgumentException e) {
        // TODO: print available configs to check whether we could support them
        Log.e(BuildConfig.TAG, "EGLConfig 8-8-8-0 not supported");
    }
    try {
        view.setEGLConfigChooser(new ConfigChooser(8, 8, 8, 8, 16, 8));
        return new GLSurfaceViewHolder(view);
    } catch(IllegalArgumentException e) {
        Log.e(BuildConfig.TAG, "EGLConfig 8-8-8-8 not supported");
    }
    try {
        view.setEGLConfigChooser(new ConfigChooser(5, 6, 5, 0, 16, 8));
        return new GLSurfaceViewHolder(view);
    } catch(IllegalArgumentException e) {
        Log.e(BuildConfig.TAG, "EGLConfig 5-6-5-0 not supported");
    }
    return null;
}

public interface GLViewHolder {

    enum RenderMode {
        RENDER_WHEN_DIRTY,
        RENDER_CONTINUOUSLY
    };

    /**
     * Set the renderer associated with this view. Also starts the thread that
     * will call the renderer, which in turn causes the rendering to start.
     * @param renderer the renderer to use to perform OpenGL drawing.
     */
    void setRenderer(GLSurfaceView.Renderer renderer);

    /**
     * Set the rendering mode. When {@link RenderMode} is
     * RENDER_CONTINUOUSLY, the renderer is called
     * repeatedly to re-render the scene. When {@link RenderMode}
     * is RENDER_WHEN_DIRTY, the renderer only rendered when the surface
     * is created, or when {@link #requestRender} is called. Defaults to RENDER_CONTINUOUSLY.
     * @param renderMode one of the {@link RenderMode} enums
     */
    void setRenderMode(RenderMode renderMode);

    /**
     * Get the current rendering mode.
     * @return the current rendering mode.
     */
    RenderMode getRenderMode();

    /**
     * Request that the renderer render a frame.
     */
    void requestRender();

    /**
     * Queue a runnable to be run on the GL rendering thread.
     * @param r the runnable to be run on the GL rendering thread.
     */
    void queueEvent(@NonNull final Runnable r);

    /**
     * Pause the rendering thread, optionally tearing down the EGL context
     * depending upon the value of preserveEGLContextOnPause.
     */
    void onPause();

    /**
     * Resumes the rendering thread, re-creating the OpenGL context if necessary.
     */
    void onResume();

    /**
     * Destroys the GL Thread associated with the GLViewHolder
     */
    void onDestroy();

    /**
     * Can be used by the client to get access to the underlying view to pass any view controls
     * @return gl view held by {@link GLViewHolder}
     */
    @NonNull
    View getView();

}

@UiThread
@Override
public void onSurfaceTextureAvailable(final SurfaceTexture surface, final int width, final int height) {
    synchronized (syncGLThread) {
        glThread.width = width;
        glThread.height = height;
        glThread.surfaceTexture = surface;
        glThread.requestRender = true;
        syncGLThread.notifyAll();
    }
}

@Override
public void setRenderer(@NonNull Renderer renderer) {
    if (eglConfigChooser == null) {
        eglConfigChooser = new ConfigChooser(8, 8, 8, 0, 16, 0);
    }
    this.renderer = renderer;
    textureView.setSurfaceTextureListener(this);
    glThread.start();
}

@Override
public void run() {
    setName("MapTextureGLThread " + getId());
    try {
        guardedRun();
    } catch (InterruptedException ignored) {
    } finally {
        eglHelper.cleanup();
        synchronized (syncGLThread) {
            this.exited = true;
            syncGLThread.notifyAll();
        }
    }
}

synchronized (syncGLThread) {
    while (true) {
        if (shouldExit) {
            return;
        }

        /*
         * Wait for a valid SurfaceTexture to be created from TextureView
         * No GL can happen before this!!
         */
        while (surfaceTexture == null) {
            syncGLThread.wait();
        }

        // grab an event to be processed by the gl thread
        if (!qEvents.isEmpty()) {
            event = qEvents.remove(0);
            break;
        }

        if (destroySurface) {
            eglHelper.destroySurface();
            destroySurface = false;
            break;
        }

        if (destroyContext) {
            eglHelper.destroyContext();
            destroyContext = false;
        }

        if (paused != pauseRequest) {
            pausing = pauseRequest;
            paused = pauseRequest;
        }

        // When pausing, release the EGL surface:
        if (pausing && eglHelper.eglSurface != EGL10.EGL_NO_SURFACE) {
            eglHelper.destroySurface();
            destroySurface = false;
        }

        // When pausing, optionally release the EGL Context:
        if (pausing && eglHelper.eglContext != EGL10.EGL_NO_CONTEXT &&
                !preserveEGLContextOnPause) {
            eglHelper.destroyContext();
        }

        // Surface is available because of onSurfaceTextureAvailable call
        // thread is not paused
        // there is a request to render
        if (surfaceTexture != null && !paused &&
                (requestRender || (renderMode == RenderMode.RENDER_CONTINUOUSLY))) {
            w = width;
            h = height;
            if (eglHelper.eglContext == EGL10.EGL_NO_CONTEXT) {
                initGLContext = true;
                break;
            }
            if (eglHelper.eglSurface == EGL10.EGL_NO_SURFACE) {
                // surface must have been destroyed or not created at an earlier attempt
                initGLSurface = true;
                break;
            }
            // reset requestRender for subsequent render request to be set!
            requestRender = false;
            break;
        }
        syncGLThread.wait();
    }
}

synchronized (syncGLThread) {
    surfaceTexture = null;
    destroySurface = true;
}

private static class EGLHelper {
    static final int EGL_CONTEXT_CLIENT_VERSION = 0x3098;

    // Weak reference to the textureView for which this EGL context will be created!
    private final WeakReference<TextureView> textureViewWeakRef;

    private EGL10 egl;
    private EGLConfig eglConfig = null;
    private EGLDisplay eglDisplay = EGL10.EGL_NO_DISPLAY;
    private EGLContext eglContext = EGL10.EGL_NO_CONTEXT;
    private EGLSurface eglSurface = EGL10.EGL_NO_SURFACE;

    EGLHelper(WeakReference<TextureView> textureViewWeakRef) {
        this.textureViewWeakRef = textureViewWeakRef;
    }

    void setupEGL(GLSurfaceView.EGLConfigChooser eglConfigChooser, int eglContextClientVersion) {
        this.egl = (EGL10) EGLContext.getEGL();

        // get display
        this.eglDisplay = egl.eglGetDisplay(EGL10.EGL_DEFAULT_DISPLAY);
        if (eglDisplay == EGL10.EGL_NO_DISPLAY) {
            throwEglException("eglGetDisplay");
        }

        //init display
        int[] eglVersion = new int[2];
        if (!egl.eglInitialize(eglDisplay, eglVersion)) {
            throwEglException("eglInitialize");
        }

        //create egl context
        if (textureViewWeakRef == null) {
            eglDisplay = EGL10.EGL_NO_DISPLAY;
        } else if (eglContext == EGL10.EGL_NO_CONTEXT) {
            // Using the same config used for glSurfaceView eglConfigChooser
            eglConfig = eglConfigChooser.chooseConfig(egl, eglDisplay);
            // create opengl es 2.0 context
            int[] attr_list = {EGL_CONTEXT_CLIENT_VERSION, eglContextClientVersion, EGL10.EGL_NONE};
            eglContext = egl.eglCreateContext(eglDisplay, eglConfig, EGL10.EGL_NO_CONTEXT, attr_list);
        }

        if (eglDisplay == EGL10.EGL_NO_DISPLAY || eglContext == null || eglContext == EGL10.EGL_NO_CONTEXT) {
            eglContext = null;
            throwEglException("eglCreateContext");
        }
    }

    GL10 createGL() {
        return (GL10) eglContext.getGL();
    }

    boolean createSurface() {
        //make sure to destroy the previous surface
        destroySurface();

        // create egl surface to render onto using the surfaceTexture from our textureview
        TextureView textureView = textureViewWeakRef.get();
        if (textureView == null) {
            eglSurface = EGL10.EGL_NO_SURFACE;
        } else {
            eglSurface = egl.eglCreateWindowSurface(eglDisplay, eglConfig, textureView.getSurfaceTexture(), null);
        }

        if (eglSurface == null || eglSurface == EGL10.EGL_NO_SURFACE) {
            Log.e(BuildConfig.TAG, "eglCreateWindowSurface error: " + eglErrorToString(egl.eglGetError()));
            return false;
        }

        return makeCurrent();
    }

    boolean makeCurrent() {
        if (!egl.eglMakeCurrent(eglDisplay, eglSurface, eglSurface, eglContext)) {
            Log.w(BuildConfig.TAG, "eglMakeCurrent error: " + eglErrorToString(egl.eglGetError()));
            return false;
        }
        return true;
    }

    // swap buffers
    int swap() {
        if (!egl.eglSwapBuffers(eglDisplay, eglSurface)) {
            return egl.eglGetError();
        }
        return EGL10.EGL_SUCCESS;
    }

    // destroy surface
    private void destroySurface() {
        if (eglSurface != EGL10.EGL_NO_SURFACE && !egl.eglDestroySurface(eglDisplay, eglSurface)) {
            Log.w(BuildConfig.TAG, "eglDestroySurface error: " + eglErrorToString(egl.eglGetError()));
        }
        eglSurface = EGL10.EGL_NO_SURFACE;
    }

    // destroy context
    private void destroyContext() {
        if (eglContext != EGL10.EGL_NO_CONTEXT && !egl.eglDestroyContext(eglDisplay, eglContext)) {
            Log.w(BuildConfig.TAG, "eglDestroyContext error: " + eglErrorToString(egl.eglGetError()));
        }
        eglContext = EGL10.EGL_NO_CONTEXT;
    }

    // destroy display
    private void terminate() {
        if (eglDisplay != EGL10.EGL_NO_DISPLAY && !egl.eglTerminate(eglDisplay)) {
            Log.w(BuildConfig.TAG, "eglTerminate error: " + eglErrorToString(egl.eglGetError()));
        }
        eglDisplay = EGL10.EGL_NO_DISPLAY;
    }

    private void throwEglException(String fn) {
        String message = fn + " failed: " + eglErrorToString(egl.eglGetError());
        throw new RuntimeException(message);
    }

    private String eglErrorToString(int error) {
        switch (error) {
            case EGL10.EGL_SUCCESS:
                return "EGL_SUCCESS";
            case EGL10.EGL_NOT_INITIALIZED:
                return "EGL_NOT_INITIALIZED";
            case EGL10.EGL_BAD_ACCESS:
                return "EGL_BAD_ACCESS";
            case EGL10.EGL_BAD_ALLOC:
                return "EGL_BAD_ALLOC";
            case EGL10.EGL_BAD_ATTRIBUTE:
                return "EGL_BAD_ATTRIBUTE";
            case EGL10.EGL_BAD_CONFIG:
                return "EGL_BAD_CONFIG";
            case EGL10.EGL_BAD_CONTEXT:
                return "EGL_BAD_CONTEXT";
            case EGL10.EGL_BAD_CURRENT_SURFACE:
                return "EGL_BAD_CURRENT_SURFACE";
            case EGL10.EGL_BAD_DISPLAY:
                return "EGL_BAD_DISPLAY";
            case EGL10.EGL_BAD_MATCH:
                return "EGL_BAD_MATCH";
            case EGL10.EGL_BAD_NATIVE_PIXMAP:
                return "EGL_BAD_NATIVE_PIXMAP";
            case EGL10.EGL_BAD_NATIVE_WINDOW:
                return "EGL_BAD_NATIVE_WINDOW";
            case EGL10.EGL_BAD_PARAMETER:
                return "EGL_BAD_PARAMETER";
            case EGL10.EGL_BAD_SURFACE:
                return "EGL_BAD_SURFACE";
            case EGL11.EGL_CONTEXT_LOST:
                return "EGL10.EGL_CONTEXT_LOST";
            default:
                return "0x" + Integer.toHexString(error);
        }
    }

    void cleanup() {
        destroySurface();
        destroyContext();
        terminate();
    }
}

public TextureViewHolderFactory(boolean translucent) {
    this.translucent = translucent;
}

public TextureViewHolderFactory() {
    this(false);
}

@Override
@NonNull
public GLViewHolder build(Context context) {
    TextureView textureView = new TextureView(context);
    TextureViewHolder textureViewHolder = new TextureViewHolder(textureView);

    textureViewHolder.setEGLContextClientVersion(2);
    textureViewHolder.setPreserveEGLContextOnPause(true);

    int alphaBits = translucent ? 8 : 0;
    textureViewHolder.setEGLConfigChooser(new ConfigChooser(8, 8, 8, alphaBits, 16, 8));
    textureView.setOpaque(!translucent);

    return textureViewHolder;
