class UsbFileListAdapter(
        context: Context,
        /**
         *
         * @return the directory which is currently be shown.
         */
        val currentDir: UsbFile
) : ArrayAdapter<UsbFile>(context, R.layout.list_item) {
    /**
     * Class to compare [UsbFile]s. If the [UsbFile] is an directory
     * it is rated lower than an file, ie. directories come first when sorting.
     */
    private val comparator = Comparator<UsbFile> { lhs, rhs ->
        if (lhs.isDirectory && !rhs.isDirectory) {
            return@Comparator -1
        }
        if (rhs.isDirectory && !lhs.isDirectory) {
            1
        } else lhs.name.compareTo(rhs.name, ignoreCase = true)
    }
    private var files: List<UsbFile>
    private val inflater: LayoutInflater

    /**
     * Reads the contents of the directory and notifies that the View shall be
     * updated.
     *
     * @throws IOException
     * If reading contents of a directory fails.
     */
    @Throws(IOException::class)
    fun refresh() {
        files = Arrays.asList(*currentDir.listFiles())
        Collections.sort(files, comparator)
        notifyDataSetChanged()
    }

    override fun getCount(): Int {
        return files.size
    }

    override fun getView(position: Int, convertView: View?, parent: ViewGroup): View {
        val file = files[position]

        return (
                convertView ?: inflater.inflate(R.layout.list_item, parent, false)
                ).apply {
                    (findViewById<View>(R.id.name_text_view) as TextView).text =
                            file.name

                    (findViewById<View>(R.id.type_text_view) as TextView).setText(when {
                        file.isDirectory -> R.string.directory
                        else -> R.string.file
                    })
                }
    }

    override fun getItem(position: Int): UsbFile {
        return files[position]
    }

    /**
     * Constructs a new List Adapter to show [UsbFile]s.
     *
     * @param context
     * The context.
     * @param dir
     * The directory which shall be shown.
     * @throws IOException
     * If reading fails.
     */
    init {
        files = ArrayList()
        inflater = context.getSystemService(Context.LAYOUT_INFLATER_SERVICE) as LayoutInflater
        refresh()
    }
}

@Throws(IOException::class)
fun refresh() {
    files = Arrays.asList(*currentDir.listFiles())
    Collections.sort(files, comparator)
    notifyDataSetChanged()
}

class UsbFileHttpServer(private val rootFile: UsbFile, private val server: HttpServer) : UsbFileProvider {
    private val fileCache = LruCache<String, UsbFile>(100)

    val baseUrl: String
        get() {
            var hostname: String? = server.hostname
            if (hostname == null) {
                hostname = "localhost"
            }
            return "http://" + hostname + ":" + server.listeningPort + "/"
        }

    val isAlive: Boolean
        get() = server.isAlive

    init {
        server.usbFileProvider = this
    }

    @Throws(IOException::class)
    fun start() {
        server.start()
    }

    @Throws(IOException::class)
    fun stop() {
        server.stop()
        fileCache.evictAll()
    }

    @Throws(IOException::class)
    override fun determineFileToServe(uri: String): UsbFile {
        var fileToServe: UsbFile? = fileCache.get(uri)

        if (fileToServe == null) {
            Log.d(TAG, "Searching file on USB (URI: $uri)")
            if (!rootFile.isDirectory) {
                Log.d(TAG, "Serving root file")
                if ("/" != uri && "/" + rootFile.name != uri) {
                    Log.d(TAG, "Invalid request, respond with 404")
                    throw FileNotFoundException("Not found $uri")
                }


                fileToServe = rootFile
            } else {
                fileToServe = rootFile.search(uri.substring(1))
            }
        } else {
            Log.d(TAG, "Using lru cache for $uri")
        }


        if (fileToServe == null) {
            Log.d(TAG, "fileToServe == null")
            throw FileNotFoundException("Not found $uri")
        }

        if (fileToServe.isDirectory) {
            throw NotAFileException()
        }

        fileCache.put(uri, fileToServe)

        return fileToServe
    }

    companion object {

        private val TAG = UsbFileHttpServer::class.java.simpleName
    }
}

class UsbFileHttpServerService : Service() {

    var server: UsbFileHttpServer? = null

    val isServerRunning: Boolean
        get() = server?.isAlive ?: false

    inner class ServiceBinder : Binder() {
        val service: UsbFileHttpServerService
            get() = this@UsbFileHttpServerService
    }

    @Throws(IOException::class)
    @JvmOverloads
    fun startServer(file: UsbFile, server: HttpServer, notificationChannelId: String = "com.github.magnusja.libaums.http_service_channel", notificationName: CharSequence = "libaums_http") {
        startAsForeground(notificationChannelId, notificationName)

        this.server = UsbFileHttpServer(file, server)
        this.server?.start()
    }

    fun stopServer() {
        try {
            server?.stop()
        } catch (e: IOException) {
            Log.e(TAG, "exception stopping server", e)
        }

        stopForeground()
    }

    override fun onBind(intent: Intent): IBinder? {
        return ServiceBinder()
    }

    protected fun startAsForeground(notificationId: String, notificationName: CharSequence) {

        var channelId = ""
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            channelId = createNotificationChannel(notificationId, notificationName)
        }

        val notificationBuilder = NotificationCompat.Builder(this, channelId)
        val notification = notificationBuilder.setOngoing(true)
                .setCategory("service")
                .setContentTitle("Serving via HTTP")
                .build()
        startForeground(ONGOING_NOTIFICATION_ID, notification)
    }

    @RequiresApi(Build.VERSION_CODES.O)
    private fun createNotificationChannel(id: String, name: CharSequence): String {
        val chan = NotificationChannel(id,
                name, NotificationManager.IMPORTANCE_LOW)
        chan.lightColor = Color.BLUE
        chan.lockscreenVisibility = Notification.VISIBILITY_PRIVATE
        val service = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        service.createNotificationChannel(chan)

        return id
    }

    protected fun stopForeground() {
        stopForeground(true)
    }

    companion object {

        private val TAG = UsbFileHttpServerService::class.java.simpleName

        private const val ONGOING_NOTIFICATION_ID = 1
    }
}

class AsyncHttpServer(private val port: Int) : HttpServer, HttpServerRequestCallback {

    override lateinit var usbFileProvider: UsbFileProvider
    private val server = com.koushikdutta.async.http.server.AsyncHttpServer()
    override var isAlive = false
    override val hostname: String
        get() = ""
    override val listeningPort: Int
        get() = port

    init {

        server.get("/.*", this)
    }

    @Throws(IOException::class)
    override fun start() {
        server.listen(port)
        isAlive = true
    }

    @Throws(IOException::class)
    override fun stop() {
        server.stop()
        // force the server to stop even if there are ongoing connections
        AsyncServer.getDefault().stop()
        isAlive = false
    }

    override fun onRequest(request: AsyncHttpServerRequest, response: AsyncHttpServerResponse) {
        val uri: String
        try {
            uri = URLDecoder.decode(request.path, "utf-8")
        } catch (e: UnsupportedEncodingException) {
            Log.e(TAG, "could not decode URL", e)
            response.code(404)
            response.send(e.message)
            return
        }

        Log.d(TAG, "Uri: $uri")

        try {
            val fileToServe = usbFileProvider.determineFileToServe(uri)
            response.sendStream(UsbFileInputStream(fileToServe), fileToServe.length)
        } catch (e: FileNotFoundException) {
            response.code(404)
            response.send(e.message)
        } catch (e: NotAFileException) {
            response.code(400)
            response.send(e.message)
        } catch (e: IOException) {
            response.code(500)
            response.send(e.message)
        }

    }

    companion object {
        private val TAG = AsyncHttpServer::class.java.simpleName
    }
}

interface HttpServer {
    val isAlive: Boolean
    val hostname: String
    val listeningPort: Int
    var usbFileProvider: UsbFileProvider
    @Throws(IOException::class)
    fun start()

    @Throws(IOException::class)
    fun stop()
}

class NanoHttpdServer : HttpServer {

    override val isAlive: Boolean
        get() = httpServer.isAlive
    override val hostname: String
        get() = httpServer.hostname
    override val listeningPort: Int
        get() = httpServer.listeningPort

    private inner class NHttpServer : NanoHTTPD {

        constructor(port: Int) : super(port)
        constructor(hostname: String, port: Int) : super(hostname, port)

        override fun serve(session: IHTTPSession): Response {
            val uri: String
            try {
                uri = URLDecoder.decode(session.uri, "Unicode")
            } catch (e: UnsupportedEncodingException) {
                Log.e(TAG, "could not decode URL", e)

                return newFixedLengthResponse(Response.Status.BAD_REQUEST,
                        MIME_HTML, "Unable to decode URL")
            }

            Log.d(TAG, "Request: $uri")

            val headers = session.headers
            val range = headers["range"]


            return try {
                val fileToServe = usbFileProvider.determineFileToServe(uri)

                range?.let { serveRangeOfFile(fileToServe, it) }
                        ?: serveCompleteFile(fileToServe)
            } catch (e: FileNotFoundException) {
                newFixedLengthResponse(Response.Status.NOT_FOUND,
                        MIME_HTML, e.message)
            } catch (e: NotAFileException) {
                newFixedLengthResponse(Response.Status.BAD_REQUEST,
                        MIME_HTML, e.message)
            } catch (e: IOException) {
                newFixedLengthResponse(Response.Status.INTERNAL_ERROR,
                        MIME_HTML, e.message)
            }

        }

        private fun serveCompleteFile(file: UsbFile): Response {
            Log.d(TAG, "Serving complete file")

            val mimeType = getMimeTypeForFile(file.name)

            val res = newFixedLengthResponse(Response.Status.OK,
                    mimeType, createInputStream(file), file.length)
            res.addHeader("Accept-Ranges", "bytes")

            return res
        }

        @Throws(IOException::class)
        private fun serveRangeOfFile(file: UsbFile, range: String): Response {
            var newRange = range
            Log.d(TAG, "Serving range of file $newRange")

            val mimeType = getMimeTypeForFile(file.name)

            var start: Long = 0
            var end: Long = -1
            val length = file.length

            if (newRange.startsWith("bytes=")) {
                newRange = newRange.substring("bytes=".length)
                val minus = newRange.indexOf('-')
                try {
                    if (minus > 0) {
                        start = java.lang.Long.parseLong(newRange.substring(0, minus))
                        end = java.lang.Long.parseLong(newRange.substring(minus + 1))
                    }
                } catch (e: NumberFormatException) {
                    // ignore due to fallback values 0 and -1 -> length - 1
                }

            } else {
                return newFixedLengthResponse(Response.Status.BAD_REQUEST,
                        MIME_HTML, "Range header invalid")
            }

            if (start < 0 || end >= length) {
                return newFixedLengthResponse(Response.Status.RANGE_NOT_SATISFIABLE,
                        MIME_HTML, "Start < 0 or end >= actual length")
            }


            if (end < 0) {
                end = length - 1
            }

            var contentLength = end - start + 1
            if (contentLength < 0) {
                contentLength = 0
            }

            Log.d(TAG, "Serving file from $start to $end, Content-Length: $contentLength")

            val stream = createInputStream(file)
            stream.skip(start)

            val res = newFixedLengthResponse(Response.Status.PARTIAL_CONTENT,
                    mimeType, stream, contentLength)
            res.addHeader("Accept-Ranges", "bytes")
            res.addHeader("Content-Length", "" + contentLength)
            res.addHeader("Content-Range", "bytes $start-$end/$length")

            return res
        }

        private fun createInputStream(file: UsbFile): InputStream {
            return UsbFileInputStream(file)
        }
    }

    override lateinit var usbFileProvider: UsbFileProvider
    private var httpServer: NHttpServer

    constructor(port: Int) {
        httpServer = NHttpServer(port)
    }

    constructor(hostname: String, port: Int) {
        httpServer = NHttpServer(hostname, port)
    }

    override fun start() {
        httpServer.start()
    }

    override fun stop() {
        httpServer.stop()
    }

    companion object {
        private val TAG = NanoHttpdServer::class.java.simpleName
    }
}

public class JavaFsFileSystemCreator implements FileSystemCreator {

    private static final String TAG = JavaFsFileSystemCreator.class.getSimpleName();

    private static List<FileSystemType> fsTypes = new ArrayList<>();

    static {
        final Logger root = Logger.getRootLogger();
        final LogCatAppender logCatAppender = new LogCatAppender();
        root.addAppender(logCatAppender);

        fsTypes.add(new NTFSFileSystemType());
        fsTypes.add(new ExFatFileSystemType());

        fsTypes.add(new FatFileSystemType());
        fsTypes.add(new org.jnode.fs.fat.FatFileSystemType());

        fsTypes.add(new HfsPlusFileSystemType());
        fsTypes.add(new HfsWrapperFileSystemType());

        fsTypes.add(new Ext2FileSystemType());
        fsTypes.add(new XfsFileSystemType());

        fsTypes.add(new ISO9660FileSystemType());
    }


    @Override
    public FileSystem read(PartitionTableEntry entry, BlockDeviceDriver blockDevice) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(4096);
        blockDevice.read(0, buffer);

        FSBlockDeviceWrapper wrapper = new FSBlockDeviceWrapper(blockDevice, entry);

        for(FileSystemType type : fsTypes) {
            if(type.supports(wrapper.getPartitionTableEntry(), buffer.array(), wrapper)) {
                try {
                    return new FileSystemWrapper(type.create(new DeviceWrapper(blockDevice, entry), false));
                } catch (FileSystemException e) {
                    Log.e(TAG, "error creating fs with type " + type.getName(), e);
                }
            }
        }

        return null;
    }
}

