enum class Direction {
    /**
     * Means from device to host (Android).
     */
    IN,
    /**
     * Means from host (Android) to device.
     */
    OUT,
    /**
     * There is no data phase
     */
    NONE
}

open fun serialize(buffer: ByteBuffer) {
    buffer.apply {
        order(ByteOrder.LITTLE_ENDIAN)
        putInt(D_CBW_SIGNATURE)
        putInt(dCbwTag)
        putInt(dCbwDataTransferLength)
        put(bmCbwFlags)
        put(bCbwLun)
        put(bCbwcbLength)
    }
}

fun read(buffer: ByteBuffer) {
     buffer.order(ByteOrder.LITTLE_ENDIAN)

     this.apply {

        dCswSignature = buffer.int
        if (dCswSignature != D_CSW_SIGNATURE) {
            Log.e(TAG, "unexpected dCSWSignature $dCswSignature")
        }
        dCswTag = buffer.int
        dCswDataResidue = buffer.int
        bCswStatus = buffer.get()
     }
}

class ScsiInquiry(private val allocationLength: Byte, lun: Byte) : CommandBlockWrapper(allocationLength.toInt(), Direction.IN, lun, LENGTH) {

    override fun serialize(buffer: ByteBuffer) {
        super.serialize(buffer)
        buffer.apply {
            put(OPCODE)
            put(0.toByte())
            put(0.toByte())
            put(0.toByte())
            put(allocationLength)
        }
    }

    companion object {
        private const val LENGTH: Byte = 0x6
        private const val OPCODE: Byte = 0x12
    }

}

fun read(buffer: ByteBuffer): ScsiInquiryResponse {
    buffer.order(ByteOrder.LITTLE_ENDIAN)
    val b = buffer.get()

    return ScsiInquiryResponse().apply {
        peripheralQualifier = b and 0xe0.toByte()
        peripheralDeviceType = b and 0x1f.toByte()
        isRemovableMedia = buffer.get().toInt() == 0x80
        spcVersion = buffer.get()
        responseDataFormat = buffer.get() and 0x7.toByte()
    }
}

class ScsiRead10 : CommandBlockWrapper {

    private var blockAddress: Int = 0
    private var transferBytes: Int = 0
    private var blockSize: Int = 0
    private var transferBlocks: Short = 0

    /**
     * Constructs a new read command without any information.
     * Be sure to call [.init] before transfering command to device.
     */
    constructor(lun: Byte) : super(0, Direction.IN, lun, LENGTH)

    /**
     * Constructs a new read command with the given information.
     *
     * @param blockAddress
     * The logical block address the read should start.
