fun checkResponseForError() {
    when (senseKey.toInt()) {
        NO_SENSE, COMPLETED, RECOVERED_ERROR -> { } // success, nothing to do
        NOT_READY -> handleNotReady()
        MEDIUM_ERROR -> handleMediumError()
        HARDWARE_ERROR -> throw HardwareError(this)
        ILLEGAL_REQUEST -> throw IllegalCommand(this)
        UNIT_ATTENTION -> {
            // Non-exhaustively handle recoverable unit attention conditions
            if (additionalSenseCode.toInt() == RESET_OCCURRED ||
                additionalSenseCode.toInt() == COMMANDS_CLEARED) {
                throw NotReadyTryAgain(this)
            } else {
                throw UnitAttention(this)
            }
        }
        DATA_PROTECT -> throw DataProtect(this)
        BLANK_CHECK -> throw BlankCheck(this)
        COPY_ABORTED -> throw CopyAborted(this)
        ABORTED -> throw Aborted(this)
        VOLUME_OVERFLOW -> throw VolumeOverflow(this)
        MISCOMPARE -> throw Miscompare(this)
    }

    throw SenseException(this, "Sense exception: " + this.senseKey)
}

fun read(buffer: ByteBuffer): ScsiRequestSenseResponse {
    buffer.order(ByteOrder.BIG_ENDIAN)

    return ScsiRequestSenseResponse().apply {
        errorCode = buffer.get()
        segmentNumber = buffer.get()
        senseKey = buffer.get()
        information = buffer.int
        additionalSenseLength = buffer.get()
        commandSpecificInformation = buffer.int
        additionalSenseCode = buffer.get()
        additionalSenseCodeQualifier = buffer.get();


        informationValid = (errorCode.toInt() and 0x80) > 0
        errorCode = errorCode and 0x7F
        senseKey = senseKey and 0x0F
    }
}

abstract class AbstractUsbFile : UsbFile {

    override val absolutePath: String
        get() {
            if (isRoot) {
                return "/"
            }

            return parent?.let { parent ->
                if (parent.isRoot) {
                    "/$name"
                } else parent.absolutePath + UsbFile.separator + name
            }.orEmpty() // should never happen
        }

    @Throws(IOException::class)
    override fun search(path: String): UsbFile? {
        var path = path

        if (!isDirectory) {
            throw UnsupportedOperationException("This is a file!")
        }

        Log.d(TAG, "search file: $path")

        if (isRoot && path == UsbFile.separator) {
            return this
        }

        if (isRoot && path.startsWith(UsbFile.separator)) {
            path = path.substring(1)
        }
        if (path.endsWith(UsbFile.separator)) {
            path = path.substring(0, path.length - 1)
        }

        val index = path.indexOf(UsbFile.separator)

        if (index < 0) {
            Log.d(TAG, "search entry: $path")

            return searchThis(path)
        } else {
            val subPath = path.substring(index + 1)
            val dirName = path.substring(0, index)
            Log.d(TAG, "search recursively $subPath in $dirName")

            val file = searchThis(dirName)
            if (file != null && file.isDirectory) {
                Log.d(TAG, "found directory $dirName")
                return file.search(subPath)
            }
        }

        Log.d(TAG, "not found $path")

        return null
    }

    @Throws(IOException::class)
    private fun searchThis(name: String): UsbFile? {
        for (file in listFiles()) {
            if (file.name == name)
                return file
        }

        return null
    }

    override fun hashCode(): Int {
        return absolutePath.hashCode()
    }

    override fun toString(): String {
        return name
    }

    override fun equals(other: Any?): Boolean {
        // TODO add getFileSystem and check if file system is the same
        // TODO check reference
        return other is UsbFile && absolutePath == other.absolutePath
    }

    companion object {
        private val TAG = AbstractUsbFile::class.java.simpleName
    }
}

interface FileSystemCreator {
    @Throws(IOException::class)
    fun read(entry: PartitionTableEntry, blockDevice: BlockDeviceDriver): FileSystem?
}

object FileSystemFactory {
    private data class PrioritizedFileSystemCreator(val priority: Int, val count: Int, val creator: FileSystemCreator)

    private var count = 0
    private val fileSystems = TreeSet(
        compareBy<PrioritizedFileSystemCreator> { it.priority }.thenBy { it.count }
    )

    /**
     * The default priority of a creator registered with the file system.  Creators will be evaluated
     * in order from lowest priority number to highest priority number.  If two creators are
     * registered with the same priority then the one inserted first will be evaluated first.
     */
    const val DEFAULT_PRIORITY = 0

    /**
     * Set the timezone a file system should use to decode timestamps, if the file system only stores
     * local date and time and has no reference which zone these timestamp correspond to. (True for
     * FAT32, e.g.)
     * @param zone The timezone to use.
     */
    @JvmStatic
    var timeZone = TimeZone.getDefault()

    class UnsupportedFileSystemException : IOException()

    init {
        registerFileSystem(Fat32FileSystemCreator(), DEFAULT_PRIORITY + 1)
    }

    @Synchronized
    @Throws(IOException::class, FileSystemFactory.UnsupportedFileSystemException::class)
    fun createFileSystem(entry: PartitionTableEntry,
                         blockDevice: BlockDeviceDriver): FileSystem {
        fileSystems.forEach {
            val fs = it.creator.read(entry, blockDevice)
            if (fs != null) {
                return fs
            }
        }

        throw UnsupportedFileSystemException()
    }

    /**
     * Register a new file system at the default priority.
     * @param creator The creator which is able to check if a [BlockDeviceDriver] is holding
     * the correct type of file system and is able to instantiate a [FileSystem]
     * instance.
     */
    @Synchronized
    @JvmStatic
    fun registerFileSystem(creator: FileSystemCreator) {
        registerFileSystem(creator, DEFAULT_PRIORITY)
    }

    /**
     * Register a new file system with the given priority.
     * @param creator The creator which is able to check if a [BlockDeviceDriver] is holding
     * the correct type of file system and is able to instantiate a [FileSystem]
     * instance.
     *
     * @param priority The priority this file system creator has when attempting to
     * create a file system.
     */
    @Synchronized
    @JvmStatic
    fun registerFileSystem(creator: FileSystemCreator, priority: Int) {
        fileSystems.add(PrioritizedFileSystemCreator(priority, count++, creator))
    }


    /**
     * Removes all registered file systems.
     */
    @Synchronized
    @JvmStatic
    fun clearFileSystems() {
        fileSystems.clear()
    }

}

@Synchronized
@JvmStatic
fun registerFileSystem(creator: FileSystemCreator) {
    registerFileSystem(creator, DEFAULT_PRIORITY)
}

@Synchronized
@JvmStatic
fun registerFileSystem(creator: FileSystemCreator, priority: Int) {
    fileSystems.add(PrioritizedFileSystemCreator(priority, count++, creator))
}

@Synchronized
@JvmStatic
fun clearFileSystems() {
    fileSystems.clear()
}

class UsbFileInputStream(private val file: UsbFile) : InputStream() {
    private var currentByteOffset: Long = 0

    init {

        if (file.isDirectory) {
            throw UnsupportedOperationException("UsbFileInputStream cannot be created on directory!")
        }
    }

    @Throws(IOException::class)
    override fun available(): Int {
        Log.d(TAG, "available")
        // return 0, because we always block
        return 0
    }

    @Throws(IOException::class)
    override fun read(): Int {

        if (currentByteOffset >= file.length) {
            return -1
        }

        val buffer = ByteBuffer.allocate(512)
        buffer.limit(1)
        file.read(currentByteOffset, buffer)
        currentByteOffset++
        buffer.flip()
        return buffer.get().toInt()
    }

    @Throws(IOException::class)
    override fun close() {
        file.close()
    }

    @Throws(IOException::class)
    override fun read(buffer: ByteArray): Int {

        if (currentByteOffset >= file.length) {
            return -1
        }

        val length = file.length
        val toRead = Math.min(buffer.size.toLong(), length - currentByteOffset)

        val byteBuffer = ByteBuffer.wrap(buffer)
        byteBuffer.limit(toRead.toInt())

        file.read(currentByteOffset, byteBuffer)
        currentByteOffset += toRead

        return toRead.toInt()
    }

    @Throws(IOException::class)
    override fun read(buffer: ByteArray, byteOffset: Int, byteCount: Int): Int {

        if (currentByteOffset >= file.length) {
            return -1
        }

        val length = file.length
        val toRead = Math.min(byteCount.toLong(), length - currentByteOffset)

        val byteBuffer = ByteBuffer.wrap(buffer)
        byteBuffer.position(byteOffset)
        byteBuffer.limit(toRead.toInt() + byteOffset)

        file.read(currentByteOffset, byteBuffer)
        currentByteOffset += toRead

        return toRead.toInt()
    }

    @Throws(IOException::class)
    override fun skip(byteCount: Long): Long {
        val skippedBytes = Math.min(byteCount, file.length - currentByteOffset)
        currentByteOffset += skippedBytes
        return skippedBytes
    }

    companion object {

        private val TAG = UsbFileInputStream::class.java.simpleName
    }
}

class UsbFileOutputStream @JvmOverloads constructor(private val file: UsbFile, append: Boolean = false) : OutputStream() {
    private var currentByteOffset: Long = 0

    init {
        if (file.isDirectory) {
            throw UnsupportedOperationException("UsbFileOutputStream cannot be created on directory!")
        }

        if (append) {
            currentByteOffset = file.length
        }
    }

    @Throws(IOException::class)
    override fun write(oneByte: Int) {
        val byteBuffer = ByteBuffer.wrap(byteArrayOf(oneByte.toByte()))
        file.write(currentByteOffset, byteBuffer)

        currentByteOffset++
    }

    @Throws(IOException::class)
    override fun close() {
        file.length = currentByteOffset
        file.close()
    }

    @Throws(IOException::class)
    override fun flush() {
        file.flush()
    }

    @Throws(IOException::class)
    override fun write(buffer: ByteArray) {
        val byteBuffer = ByteBuffer.wrap(buffer)
        file.write(currentByteOffset, byteBuffer)

        currentByteOffset += buffer.size.toLong()
    }

    @Throws(IOException::class)
    override fun write(buffer: ByteArray, offset: Int, count: Int) {
        val byteBuffer = ByteBuffer.wrap(buffer)

        byteBuffer.position(offset)
        byteBuffer.limit(count + offset)

        file.write(currentByteOffset, byteBuffer)

        currentByteOffset += count.toLong()
    }
}

