when {
    remainingClusters > maxConsecutiveClusters -> {
        size = (clusterSize * maxConsecutiveClusters).toInt()
        numberOfClusters = maxConsecutiveClusters
        remainingClusters -= maxConsecutiveClusters
    }
    remainingClusters > 0 -> {
        size = (clusterSize * min(remainingClusters.toInt(), maxConsecutiveClusters)).toInt()
        numberOfClusters = min(remainingClusters.toInt(), maxConsecutiveClusters)
        remainingClusters -= numberOfClusters
    }
    else -> size = length
}

private fun getFileSystemOffset(cluster: Long, clusterOffset: Int): Long {
    return dataAreaOffset + clusterOffset.toLong() + (cluster - 2) * clusterSize
}

@Throws(IOException::class)
internal fun getChain(startCluster: Long): Array<Long> {

    if (startCluster == 0L) {
        // if the start cluster is 0, we have an empty file
        return arrayOf()
    }

    val cachedChain = cache[startCluster]
    if (cachedChain != null) {
        return cachedChain
    }

    val result = ArrayList<Long>()
    val bufferSize = blockDevice.blockSize * 2
    // for performance reasons we always read or write two times the block
    // size
    // this is esp. good for long cluster chains because it reduces of read
    // or writes
    // and mostly cluster chains are located consecutively in the FAT
    val buffer = ByteBuffer.allocate(bufferSize)
    buffer.order(ByteOrder.LITTLE_ENDIAN)

    var currentCluster = startCluster
    var offset: Long
    var offsetInBlock: Long
    var lastOffset: Long = -1

    do {
        result.add(currentCluster)
        offset = (fatOffset[0] + currentCluster * 4) / bufferSize * bufferSize
        offsetInBlock = (fatOffset[0] + currentCluster * 4) % bufferSize

        // if we have a new offset we are forced to read again
        if (lastOffset != offset) {
            buffer.clear()
            blockDevice.read(offset, buffer)
            lastOffset = offset
        }

        currentCluster = (buffer.getInt(offsetInBlock.toInt()) and 0x0FFFFFFF).toLong()
    } while (currentCluster < FAT32_EOF_CLUSTER)

    val arr = result.toTypedArray()
    cache[startCluster] = arr

    return arr
}

    }
    buffer.putInt(offsetInBlock.toInt(), FAT32_EOF_CLUSTER)
    buffer.clear()
    blockDevice.write(offset, buffer)
} else {
    // if we freed all clusters we have to write the last change of the
    // for loop above
    buffer.clear()
    blockDevice.write(lastOffset, buffer)
}

fun getFatOffset(fatNumber: Int): Long {
    return bytesPerSector * (reservedSectors + fatNumber * sectorsPerFat)
}

@Throws(IOException::class)
@JvmStatic
fun read(blockDevice: BlockDeviceDriver): Fat32FileSystem? {

    val buffer = ByteBuffer.allocate(512)
    blockDevice.read(0, buffer)
    buffer.flip()

    return if (buffer.get(82).toChar() != 'F' ||
            buffer.get(83).toChar() != 'A' ||
            buffer.get(84).toChar() != 'T' ||
            buffer.get(85).toChar() != '3' ||
            buffer.get(86).toChar() != '2' ||
            buffer.get(87).toChar() != ' ' ||
            buffer.get(88).toChar() != ' ' ||
            buffer.get(89).toChar() != ' ') {
        null
    } else Fat32FileSystem(blockDevice, buffer)

}

class Fat32FileSystemCreator : FileSystemCreator {

    @Throws(IOException::class)
    override fun read(entry: PartitionTableEntry, blockDevice: BlockDeviceDriver): FileSystem? {
        return Fat32FileSystem.read(blockDevice)
    }
}

@Throws(IOException::class)
private fun init() {
    if (!::chain.isInitialized) {
        chain = ClusterChain(entry!!.startCluster, blockDevice, fat, bootSector)
    }

    // entries is allocated here
    // an exception will be thrown if entries is used before the directory has been initialised
    // use of uninitialised entries can lead to data loss!
    if (entries == null) {
        entries = ArrayList()
    }

    // only read entries if we have no entries
    // otherwise newly created directories (. and ..) will read trash data
    if (entries!!.size == 0 && !hasBeenInited) {
        readEntries()
    }

    hasBeenInited = true
}

@Throws(IOException::class)
private fun readEntries() {
    val buffer = ByteBuffer.allocate(chain.length.toInt())
    chain.read(0, buffer)
    // we have to buffer all long filename entries to parse them later
    val list = ArrayList<FatDirectoryEntry>()
    buffer.flip()
    while (buffer.remaining() > 0) {
        val e = FatDirectoryEntry.read(buffer) ?: break

        if (e.isLfnEntry) {
            list.add(e)
            continue
        }

        if (e.isVolumeLabel) {
            if (!isRoot) {
                Log.w(TAG, "volume label in non root dir!")
            }
            volumeLabel = e.volumeLabel
            Log.d(TAG, "volume label: " + volumeLabel!!)
            continue
        }

        // we just skip deleted entries
        if (e.isDeleted) {
            list.clear()
            continue
        }

        val lfnEntry = FatLfnDirectoryEntry.read(e, list)
        addEntry(lfnEntry, e)
        list.clear()
    }
}

val list = ArrayList<FatDirectoryEntry>()
buffer.flip()
while (buffer.remaining() > 0) {
    val e = FatDirectoryEntry.read(buffer) ?: break

    if (e.isLfnEntry) {
        list.add(e)
        continue
    }

    if (e.isVolumeLabel) {
        if (!isRoot) {
            Log.w(TAG, "volume label in non root dir!")
        }
        volumeLabel = e.volumeLabel
        Log.d(TAG, "volume label: " + volumeLabel!!)
        continue
    }

    // we just skip deleted entries
    if (e.isDeleted) {
        list.clear()
        continue
    }

    val lfnEntry = FatLfnDirectoryEntry.read(e, list)
    addEntry(lfnEntry, e)
    list.clear()
}

private fun addEntry(lfnEntry: FatLfnDirectoryEntry, entry: FatDirectoryEntry) {
    entries!!.add(lfnEntry)
    lfnMap[lfnEntry.name.toLowerCase(Locale.getDefault())] = lfnEntry
    shortNameMap[entry.shortName!!] = entry
}

internal fun removeEntry(lfnEntry: FatLfnDirectoryEntry?) {
    entries!!.remove(lfnEntry)
    lfnMap.remove(lfnEntry!!.name.toLowerCase(Locale.getDefault()))
    shortNameMap.remove(lfnEntry.actualEntry.shortName)
}

@Throws(IOException::class)
internal fun renameEntry(lfnEntry: FatLfnDirectoryEntry?, newName: String) {
    if (lfnEntry!!.name == newName)
        return

    removeEntry(lfnEntry)
    lfnEntry.setName(newName,
            ShortNameGenerator.generateShortName(newName, shortNameMap.keys))
    addEntry(lfnEntry, lfnEntry.actualEntry)
    write()
}

@Throws(IOException::class)
internal fun write() {
    init()
    val writeVolumeLabel = isRoot && volumeLabel != null
    // first lookup the total entries needed
    var totalEntryCount = 0
    for (entry in entries!!) {
        totalEntryCount += entry.entryCount
    }

    if (writeVolumeLabel)
        totalEntryCount++

    val totalBytes = (totalEntryCount * FatDirectoryEntry.SIZE).toLong()
    chain.length = totalBytes

    val buffer = ByteBuffer.allocate(chain.length.toInt())
    buffer.order(ByteOrder.LITTLE_ENDIAN)

    if (writeVolumeLabel)
        FatDirectoryEntry.createVolumeLabel(volumeLabel!!).serialize(buffer)

    for (entry in entries!!) {
        entry.serialize(buffer)
    }

    if (totalBytes % bootSector.bytesPerCluster != 0L || totalBytes == 0L) {
        // add dummy entry filled with zeros to mark end of entries
        buffer.put(ByteArray(buffer.remaining()))
    }

    buffer.flip()
    chain.write(0, buffer)
}

var totalEntryCount = 0
for (entry in entries!!) {
    totalEntryCount += entry.entryCount
}

