class Partition(blockDevice: BlockDeviceDriver, entry: PartitionTableEntry) : ByteBlockDevice(blockDevice, entry.logicalBlockAddress) {

    /**
     * The logical block address where on the device this partition starts.
     */
    /**
     *
     * @return the file system on the partition which can be used to access
     * files and directories.
     */
    lateinit var fileSystem: FileSystem
        private set

    /**
     * This method returns the volume label of the file system / partition.
     * Calling this method is equivalent to calling
     * [FileSystem.getVolumeLabel].
     *
     * @return Returns the volume label of this partition.
     */
    val volumeLabel: String
        get() = fileSystem.volumeLabel

    companion object {

        private val TAG = Partition::class.java.simpleName

        /**
         * Creates a new partition with the information given.
         *
         * @param entry
         * The entry the partition shall represent.
         * @param blockDevice
         * The underlying block device. This block device must already been initialized, see
         * [BlockDeviceDriver.init].
         * @return The newly created Partition.
         * @throws IOException
         * If reading from the device fails.
         */
        @Throws(IOException::class)
        fun createPartition(entry: PartitionTableEntry, blockDevice: BlockDeviceDriver): Partition? {
            return try {
                val partition = Partition(blockDevice, entry)
                // TODO weird triangle relationship between partiton and fs??
                val fs = FileSystemFactory.createFileSystem(entry, partition)
                partition.fileSystem = fs
                partition
            } catch (e: FileSystemFactory.UnsupportedFileSystemException) {
                Log.w(TAG, "Unsupported fs on partition")
                null
            }

        }
    }
}

@Throws(IOException::class)
fun createPartition(entry: PartitionTableEntry, blockDevice: BlockDeviceDriver): Partition? {
    return try {
        val partition = Partition(blockDevice, entry)
        // TODO weird triangle relationship between partiton and fs??
        val fs = FileSystemFactory.createFileSystem(entry, partition)
        partition.fileSystem = fs
        partition
    } catch (e: FileSystemFactory.UnsupportedFileSystemException) {
        Log.w(TAG, "Unsupported fs on partition")
        null
    }

}

interface PartitionTable {
    /**
     *
     * @return The size in bytes the partition table occupies.
     */
    val size: Int

    /**
     *
     * @return A collection of [PartitionTableEntry]s located on the block
     * device.
     */
    val partitionTableEntries: List<PartitionTableEntry>
}

object PartitionTableFactory {
    private val TAG = PartitionTableFactory::class.java.simpleName

    private val partitionTables = ArrayList<PartitionTableCreator>()

    class UnsupportedPartitionTableException : IOException()

    interface PartitionTableCreator {
        @Throws(IOException::class)
        fun read(blockDevice: BlockDeviceDriver): PartitionTable?
    }

    init {
        registerPartitionTable(FileSystemPartitionTableCreator())
        registerPartitionTable(GPTCreator())
        registerPartitionTable(MasterBootRecordCreator())
    }

    /**
     * Creates a [PartitionTable] suitable for the given block device. The
     * partition table should be located at the logical block address zero of
     * the device.
     *
     * @param blockDevice
     * The block device where the partition table is located.
     * @return The newly created [PartitionTable].
     * @throws IOException
     * If reading from the device fails.
     */
    @Throws(IOException::class)
    fun createPartitionTable(blockDevice: BlockDeviceDriver): PartitionTable {
        for (creator in partitionTables) {
            val table = creator.read(blockDevice)
            if (table != null) {
                Log.d(TAG, "Found partition table ${creator::class.java.simpleName}")
                return table
            }
            Log.d(TAG, "${creator::class.java.simpleName} returned null")
        }

        throw UnsupportedPartitionTableException()
    }

    @Synchronized
    fun registerPartitionTable(creator: PartitionTableCreator) {
        partitionTables.add(creator)
    }
}

@Throws(IOException::class)
fun createPartitionTable(blockDevice: BlockDeviceDriver): PartitionTable {
    for (creator in partitionTables) {
        val table = creator.read(blockDevice)
        if (table != null) {
            Log.d(TAG, "Found partition table ${creator::class.java.simpleName}")
            return table
        }
        Log.d(TAG, "${creator::class.java.simpleName} returned null")
    }

    throw UnsupportedPartitionTableException()
}

class FileSystemPartitionTable(blockDevice: BlockDeviceDriver, fs: FileSystem) : PartitionTable {

    internal var entries: MutableList<PartitionTableEntry> = ArrayList()

    override val size: Int
        get() = 0

    override val partitionTableEntries: List<PartitionTableEntry>
        get() = entries

    init {
        Log.i(TAG, "Found a device without partition table, yay!")
        val totalNumberOfSectors = fs.capacity / blockDevice.blockSize
        if (fs.capacity % blockDevice.blockSize != 0L) {
            Log.w(TAG, "fs capacity is not multiple of block size")
        }
        entries.add(PartitionTableEntry(fs.type, 0, totalNumberOfSectors))
    }

    companion object {

        private val TAG = FileSystemPartitionTable::class.java.simpleName
    }
}

class FileSystemPartitionTableCreator : PartitionTableFactory.PartitionTableCreator {
    @Throws(IOException::class)
    override fun read(blockDevice: BlockDeviceDriver): PartitionTable? {
        return try {
            FileSystemPartitionTable(blockDevice,
                    FileSystemFactory.createFileSystem(PartitionTableEntry(0, 0, 0), ByteBlockDevice(blockDevice)))
        } catch (e: FileSystemFactory.UnsupportedFileSystemException) {
            null
        }

    }
}

class MasterBootRecord private constructor() : PartitionTable {

    private val partitions = ArrayList<PartitionTableEntry>()

    override val size: Int
        get() = 512

    override val partitionTableEntries: List<PartitionTableEntry>
        get() = partitions

    companion object {

        private val partitionTypes = object : HashMap<Int, Int>() {
            init {
                put(0x0b, PartitionTypes.FAT32)
                put(0x0c, PartitionTypes.FAT32)
                put(0x1b, PartitionTypes.FAT32)
                put(0x1c, PartitionTypes.FAT32)

                put(0x01, PartitionTypes.FAT12)

                put(0x04, PartitionTypes.FAT16)
                put(0x06, PartitionTypes.FAT16)
                put(0x0e, PartitionTypes.FAT16)

                put(0x83, PartitionTypes.LINUX_EXT)

                put(0x07, PartitionTypes.NTFS_EXFAT)

                put(0xaf, PartitionTypes.APPLE_HFS_HFS_PLUS)
            }
        }

        private val TAG = MasterBootRecord::class.java.simpleName
        private const val TABLE_OFFSET = 446
        private const val TABLE_ENTRY_SIZE = 16

        /**
         * Reads and parses the MBR located in the buffer.
         *
         * @param buffer
         * The data which shall be examined.
         * @return A new [.MasterBootRecord] or null if the data does not
         * seem to be a MBR.
         */
        @Throws(IOException::class)
        fun read(buffer: ByteBuffer): MasterBootRecord? {
            val result = MasterBootRecord()
            buffer.order(ByteOrder.LITTLE_ENDIAN)

            if (buffer.limit() < 512) {
                throw IOException("Size mismatch!")
            }

            // test if it is a valid master boot record
            if (buffer.get(510) != 0x55.toByte() || buffer.get(511) != 0xaa.toByte()) {
                Log.i(TAG, "not a valid mbr partition table!")
                return null
            }

            for (i in 0..3) {
                val offset = TABLE_OFFSET + i * TABLE_ENTRY_SIZE
                val partitionType = buffer.get(offset + 4)
                // unused partition
                if (partitionType.toInt() == 0)
                    continue
                if (partitionType.toInt() == 0x05 || partitionType.toInt() == 0x0f) {
                    Log.w(TAG, "extended partitions are currently unsupported!")
                    continue
                }

                var type = partitionTypes[partitionType.toInt() and 0xff]

                if (type == null) {
                    Log.d(TAG, "Unknown partition type$partitionType")
                    type = PartitionTypes.UNKNOWN
                }

                val entry = PartitionTableEntry(type,
                        buffer.getInt(offset + 8).toLong(), buffer.getInt(offset + 12).toLong())

                result.partitions.add(entry)
            }

            return result
        }
    }
}

@Throws(IOException::class)
fun read(buffer: ByteBuffer): MasterBootRecord? {
    val result = MasterBootRecord()
    buffer.order(ByteOrder.LITTLE_ENDIAN)

    if (buffer.limit() < 512) {
        throw IOException("Size mismatch!")
    }

    // test if it is a valid master boot record
    if (buffer.get(510) != 0x55.toByte() || buffer.get(511) != 0xaa.toByte()) {
        Log.i(TAG, "not a valid mbr partition table!")
        return null
    }

    for (i in 0..3) {
        val offset = TABLE_OFFSET + i * TABLE_ENTRY_SIZE
        val partitionType = buffer.get(offset + 4)
        // unused partition
        if (partitionType.toInt() == 0)
            continue
        if (partitionType.toInt() == 0x05 || partitionType.toInt() == 0x0f) {
            Log.w(TAG, "extended partitions are currently unsupported!")
            continue
        }

        var type = partitionTypes[partitionType.toInt() and 0xff]

        if (type == null) {
            Log.d(TAG, "Unknown partition type$partitionType")
            type = PartitionTypes.UNKNOWN
        }

        val entry = PartitionTableEntry(type,
                buffer.getInt(offset + 8).toLong(), buffer.getInt(offset + 12).toLong())

        result.partitions.add(entry)
    }

    return result
}

class MasterBootRecordCreator : PartitionTableFactory.PartitionTableCreator {
    @Throws(IOException::class)
    override fun read(blockDevice: BlockDeviceDriver): PartitionTable? {
        val buffer = ByteBuffer.allocate(Math.max(512, blockDevice.blockSize))
        blockDevice.read(0, buffer)
        return MasterBootRecord.read(buffer)
    }
}

internal class HoneyCombMr1Communication(
        usbManager: UsbManager,
        usbDevice: UsbDevice,
        usbInterface: UsbInterface,
        outEndpoint: UsbEndpoint,
        inEndpoint: UsbEndpoint
) : AndroidUsbCommunication(usbManager, usbDevice, usbInterface, outEndpoint, inEndpoint) {

    @Throws(IOException::class)
    override fun bulkOutTransfer(src: ByteBuffer): Int {
        require(!isClosed) { "device is closed" }

        val offset = src.position()

        if (offset == 0) {
            val result = deviceConnection!!.bulkTransfer(outEndpoint,
                    src.array(), src.remaining(), UsbCommunication.TRANSFER_TIMEOUT)

            if (result == -1) {
                throw IOException("Could not write to device, result == -1")
            }

            src.position(src.position() + result)
            return result
        }

        val tmpBuffer = ByteArray(src.remaining())
        System.arraycopy(src.array(), offset, tmpBuffer, 0, src.remaining())
        val result = deviceConnection!!.bulkTransfer(outEndpoint,
                tmpBuffer, src.remaining(), UsbCommunication.TRANSFER_TIMEOUT)

        if (result == -1) {
            throw IOException("Could not write to device, result == -1")
        }

        src.position(src.position() + result)
        return result
    }

    @Throws(IOException::class)
    override fun bulkInTransfer(dest: ByteBuffer): Int {
        require(!isClosed) { "device is closed" }

        val offset = dest.position()

        if (offset == 0) {
            val result = deviceConnection!!.bulkTransfer(inEndpoint,
                    dest.array(), dest.remaining(), UsbCommunication.TRANSFER_TIMEOUT)

            if (result == -1) {
                throw IOException("Could read from to device, result == -1")
            }

            dest.position(dest.position() + result)
            return result

        }

        val tmpBuffer = ByteArray(dest.remaining())
        val result = deviceConnection!!.bulkTransfer(inEndpoint, tmpBuffer, dest.remaining(), UsbCommunication.TRANSFER_TIMEOUT)

        if (result == -1) {
            throw IOException("Could not read from device, result == -1")
        }

        System.arraycopy(tmpBuffer, 0, dest.array(), offset, result)
        dest.position(dest.position() + result)
        return result
    }
}

@TargetApi(Build.VERSION_CODES.JELLY_BEAN_MR2)
internal class JellyBeanMr2Communication(
        usbManager: UsbManager,
        usbDevice: UsbDevice,
        usbInterface: UsbInterface,
        outEndpoint: UsbEndpoint,
        inEndpoint: UsbEndpoint
) : AndroidUsbCommunication(usbManager, usbDevice, usbInterface, outEndpoint, inEndpoint) {

    @Throws(IOException::class)
    override fun bulkOutTransfer(src: ByteBuffer): Int {
        require(!isClosed) { "device is closed" }

        val result = deviceConnection!!.bulkTransfer(outEndpoint,
                src.array(), src.position(), src.remaining(), UsbCommunication.TRANSFER_TIMEOUT)

        if (result == -1) {
            when (ErrNo.errno) {
                EPIPE -> throw PipeException()
                else -> throw IOException("Could not read from device, result == -1 errno " + ErrNo.errno + " " + ErrNo.errstr)
            }
        }

        src.position(src.position() + result)
        return result
    }

    @Throws(IOException::class)
    override fun bulkInTransfer(dest: ByteBuffer): Int {
        require(!isClosed) { "device is closed" }

        val result = deviceConnection!!.bulkTransfer(inEndpoint,
                dest.array(), dest.position(), dest.remaining(), UsbCommunication.TRANSFER_TIMEOUT)

        if (result == -1) {
            when (ErrNo.errno) {
                EPIPE -> throw PipeException()
                else -> throw IOException("Could not read from device, result == -1 errno " + ErrNo.errno + " " + ErrNo.errstr)
            }
        }

        dest.position(dest.position() + result)
        return result
    }
}

object UsbCommunicationFactory {
    class NoUsbCommunicationFound : IOException()

    private val TAG = UsbCommunicationFactory::class.java.simpleName

    private val communications = ArrayList<UsbCommunicationCreator>()

    @JvmStatic
    var underlyingUsbCommunication = UnderlyingUsbCommunication.DEVICE_CONNECTION_SYNC

    enum class UnderlyingUsbCommunication {
        USB_REQUEST_ASYNC,
        DEVICE_CONNECTION_SYNC,
        OTHER
    }

    @Synchronized
    @JvmStatic
    fun registerCommunication(creator: UsbCommunicationCreator) {
        communications.add(creator)
    }

    fun createUsbCommunication(
            usbManager: UsbManager,
            usbDevice: UsbDevice,
            usbInterface: UsbInterface,
            outEndpoint: UsbEndpoint,
            inEndpoint: UsbEndpoint
    ): UsbCommunication {
        when(underlyingUsbCommunication) {
            UnderlyingUsbCommunication.DEVICE_CONNECTION_SYNC ->
                return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR2) {
                    JellyBeanMr2Communication(usbManager, usbDevice, usbInterface, outEndpoint, inEndpoint)
                } else {
                    Log.i(TAG, "using workaround usb communication")
                    HoneyCombMr1Communication(usbManager, usbDevice, usbInterface, outEndpoint, inEndpoint)
                }

            UnderlyingUsbCommunication.USB_REQUEST_ASYNC ->
                return UsbRequestCommunication(usbManager, usbDevice, usbInterface, outEndpoint, inEndpoint)

            UnderlyingUsbCommunication.OTHER ->
                for(creator in communications) {
                    val communication = creator.create(usbManager, usbDevice, usbInterface, outEndpoint, inEndpoint)

                    if(communication != null) {
                        return communication
                    }
                }

        }
        throw NoUsbCommunicationFound()
    }
}

internal class UsbRequestCommunication(
        usbManager: UsbManager,
        usbDevice: UsbDevice,
        usbInterface: UsbInterface,
        outEndpoint: UsbEndpoint,
        inEndpoint: UsbEndpoint
) : AndroidUsbCommunication(usbManager, usbDevice, usbInterface, outEndpoint, inEndpoint) {

    private val outRequest = UsbRequest().apply { initialize(deviceConnection, outEndpoint) }
    private val inRequest = UsbRequest().apply { initialize(deviceConnection, inEndpoint) }
    private val workaroundBuffer = ByteBuffer.allocate(1024 * 32 * 4)


    @Throws(IOException::class)
    @RequiresApi(Build.VERSION_CODES.O)
    fun bulkOutTransferApiO(src: ByteBuffer): Int {
        val oldPosition = src.position();
        if (!outRequest.queue(src)) {
            throw IOException("Error queueing request.")
        }

        val request = deviceConnection!!.requestWait()
        if (request === outRequest) {
            return src.position() - oldPosition
        }

        throw IOException("requestWait failed! Request: $request")
    }


    @Throws(IOException::class)
    fun bulkOutTransferApiLesserO(src: ByteBuffer): Int {
        val length = src.remaining()
        val oldPosition = src.position()

        // workaround: UsbRequest.queue always reads at position 0 :/
        workaroundBuffer.clear()
        workaroundBuffer.put(src)

        if (!outRequest.queue(workaroundBuffer, length)) {
            throw IOException("Error queueing request.")
        }

        val request = deviceConnection!!.requestWait()
        if (request === outRequest) {
            src.position(oldPosition + workaroundBuffer.position())
            return workaroundBuffer.position()
        }

        throw IOException("requestWait failed! Request: $request")
    }


    @Synchronized
    @Throws(IOException::class)
    override fun bulkOutTransfer(src: ByteBuffer): Int {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            bulkOutTransferApiO(src)
        } else {
            bulkOutTransferApiLesserO(src)
        }
    }


    @Throws(IOException::class)
    fun bulkInTransferApiLesserO(dest: ByteBuffer): Int {
        val length = dest.remaining()

        // workaround: UsbRequest.queue always writes at position 0 :/
        workaroundBuffer.clear()
        workaroundBuffer.limit(length)

        if (!inRequest.queue(workaroundBuffer, length)) {
            throw IOException("Error queueing request.")
        }

        val request = deviceConnection!!.requestWait()
        if (request === inRequest) {
            workaroundBuffer.flip()
            dest.put(workaroundBuffer)
            return workaroundBuffer.limit()
        }

        throw IOException("requestWait failed! Request: $request")
    }

    @Throws(IOException::class)
    @RequiresApi(Build.VERSION_CODES.O)
    fun bulkInTransferApiO(dest: ByteBuffer): Int {
        val oldPosition = dest.position();
        if (!inRequest.queue(dest)) {
            throw IOException("Error queueing request.")
        }

        val request = deviceConnection!!.requestWait()
        if (request === inRequest) {
            return dest.position() - oldPosition
        }

        throw IOException("requestWait failed! Request: $request")
    }

    @Synchronized
    @Throws(IOException::class)
    override fun bulkInTransfer(dest: ByteBuffer): Int {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            bulkInTransferApiO(dest)
        } else {
            bulkInTransferApiLesserO(dest)
        }
    }
}

