internal val TestIdentifier.isDynamicTest: Boolean
    get() {
        val shortId = this.shortId
        return DYNAMIC_TEST_PREFIXES.any { shortId.startsWith(it) }
    }

internal object TestNameFormatter {
    fun format(identifier: TestIdentifier, legacyFormat: Boolean = false): String {
        // When requesting the legacy format of the formatter,
        // construct a technical version of its name for backwards compatibility
        // with the JUnit 4-based instrumentation of Android by stripping the brackets of
        // parameterized tests completely.
        // If this didn't happen, running them from the IDE will cause "No tests found" errors.
        // See AndroidX's TestRequestBuilder$MethodFilter for where this is cross-referenced in the
        // instrumentation!
        //
        // History:
        // - #199 & #207 (the original unearthing of this behavior)
        // - #317 (making an exception for dynamic tests)
        // - #339 (retain indices of parameterized methods to avoid premature filtering by JUnit 4's
        // test discovery)
        if (legacyFormat) {
            val reportName = identifier.legacyReportingName
            val paramStartIndex = reportName.indexOf('(')
            if (paramStartIndex > -1) {
                val result = reportName.substring(0, paramStartIndex)

                val paramEndIndex = reportName.lastIndexOf('[')

                return if (paramEndIndex > -1) {
                    // Retain suffix of parameterized methods (i.e. "[1]", "[2]" etc)
                    // so that they won't be filtered out by JUnit 4 on isolated method runs
                    result + reportName.substring(paramEndIndex)
                } else {
                    result
                }
            }
        }

        // Process the display name before handing it out,
        // maintaining compatibility with the expectations of Android's instrumentation:
        // - Cut off no-parameter brackets '()'
        // - Replace any other round brackets with square brackets (for parameterized tests)
        //   to ensure that logs are displayed in the test results window (ref. #350)
        return identifier.displayName
            .replace("()", "")
            .replace('(', '[')
            .replace(')', ']')
            .replace("\"", "")
    }
}

    result + reportName.substring(paramEndIndex)
} else {
    result
}

@RequiresApi(26)
@VisibleForTesting(otherwise = VisibleForTesting.PACKAGE_PRIVATE)
internal class AndroidJUnitFramework(
    private val testClass: Class<*>,
    params: JUnitFrameworkRunnerParams,
) : Runner() {
    private companion object {
        private val launcher = LauncherFactory.create()

        // Fallback for irrelevant classes passed to JUnit 4's RunnerBuilder
        // (no test tree will be created for those, avoiding any potentially dangerous
        // runtime lookups that can cause issues like `mannodermaus/android-junit-framework/413`)
        private val emptyDescription = Description.createSuiteDescription("<empty>")
    }

    private val testTree by lazy { generateTestTree(params) }

    override fun getDescription(): Description = testTree?.suiteDescription ?: emptyDescription

    override fun run(notifier: RunNotifier) {
        testTree?.let { tree ->
            Log.v(LOG_TAG, "run($testClass)")
            launcher.execute(
                tree.testPlan,
                AndroidJUnitPlatformRunnerListener(tree, tree.createNotifier(notifier)),
            )
        }
    }

    /* Private */

    private fun generateTestTree(
        params: JUnitFrameworkRunnerParams
    ): AndroidJUnitPlatformTestTree? {
        val selectors = params.createSelectors(testClass)
        val isIsolatedMethodRun = selectors.size == 1 && selectors.first() is MethodSelector
        val isUsingOrchestrator = params.isUsingOrchestrator
        val request = params.createDiscoveryRequest(selectors)

        // Validate if run can be executed
        if (isUsingOrchestrator && params.isParallelExecutionEnabled) {
            throw RuntimeException(
                """
                Running tests with the Android Test Orchestrator does not work with parallel tests,
                since some information must be retained across parallel test execution,
                and the isolated nature of the Android Test Orchestrator thwarts these efforts.
                Please disable either setting and try again.
                """
                    .trimIndent()
            )
        }

        val testPlan =
            try {
                launcher.discover(request)
            } catch (e: JUnitException) {
                // Each class in scope is given to the runner,
                // but some may fail to be loaded by the class loader
                // (e.g. when they are tailored to JVM work and reference sun.* classes
                // or anything else not present in the Android runtime).
                // Log those to console, but discard them from being considered at all
                e.printStackTrace()
                EmptyTestPlan
            }

        return if (testPlan.containsTests()) {
            AndroidJUnitPlatformTestTree(
                testPlan = testPlan,
                testClass = testClass,
                needLegacyFormat = isIsolatedMethodRun || isUsingOrchestrator,
                isParallelExecutionEnabled = params.isParallelExecutionEnabled,
            )
        } else {
            null
        }
    }

    private fun AndroidJUnitPlatformTestTree.createNotifier(nextNotifier: RunNotifier) =
        if (isParallelExecutionEnabled) {
            // Wrap the default notifier with a special handler for parallel test execution
            ParallelRunNotifier(nextNotifier)
        } else {
            nextNotifier
        }
}

    ParallelRunNotifier(nextNotifier)
} else {
    nextNotifier
}

@SuppressLint("NewApi")
internal class AndroidJUnitPlatformRunnerListener(
    private val testTree: AndroidJUnitPlatformTestTree,
    private val notifier: RunNotifier,
) : TestExecutionListener {

    override fun reportingEntryPublished(testIdentifier: TestIdentifier, entry: ReportEntry) {
        // No-op, but must be declared to avoid AbstractMethodError
    }

    override fun testPlanExecutionStarted(testPlan: TestPlan) {
        notifier.fireTestSuiteStarted(testTree.suiteDescription)
    }

    override fun executionStarted(testIdentifier: TestIdentifier) {
        val description = testTree.getDescription(testIdentifier)
        if (testIdentifier.isTest) {
            notifier.fireTestStarted(description)
        }
    }

    override fun dynamicTestRegistered(testIdentifier: TestIdentifier) {
        testTree.addDynamicDescription(testIdentifier, testIdentifier.parentId.get())
    }

    override fun executionSkipped(testIdentifier: TestIdentifier, reason: String) {
        when {
            testIdentifier.isTest -> fireTestIgnored(testIdentifier, reason)
            testIdentifier.isDynamicTest -> fireTestIgnored(testIdentifier, reason)
            testIdentifier.isContainer ->
                testTree.getChildren(testIdentifier).forEach { childIdentifier ->
                    // Only report leaf tests as skipped
                    if (childIdentifier.isTest || childIdentifier.isDynamicTest) {
                        fireTestIgnored(childIdentifier, reason)
                    }
                }
        }
    }

    private fun fireTestIgnored(testIdentifier: TestIdentifier, reason: String) {
        val description = testTree.getDescription(testIdentifier)
        notifier.fireTestIgnored(description)
        Log.w(LOG_TAG, testTree.getTestName(testIdentifier) + " is ignored. " + reason)
    }

    override fun executionFinished(
        testIdentifier: TestIdentifier,
        testExecutionResult: TestExecutionResult,
    ) {
        val description = testTree.getDescription(testIdentifier)
        val status = testExecutionResult.status

        if (testIdentifier.isTest) {
            if (status == TestExecutionResult.Status.ABORTED) {
                notifier.fireTestAssumptionFailed(toFailure(testExecutionResult, description))
            } else if (status == TestExecutionResult.Status.FAILED) {
                notifier.fireTestFailure(toFailure(testExecutionResult, description))
            }

            notifier.fireTestFinished(description)
        }
    }

    override fun testPlanExecutionFinished(testPlan: TestPlan) {
        notifier.fireTestSuiteFinished(testTree.suiteDescription)
    }

    private fun toFailure(
        testExecutionResult: TestExecutionResult,
        description: Description,
    ): Failure = Failure(description, testExecutionResult.throwable.orElse(null))
}

fun getTestName(identifier: TestIdentifier): String =
    when {
        identifier.isDynamicTest ->
            if (needLegacyFormat) {
                // In isolated method runs, there is no need to compose
                // dynamic test names from multiple pieces, as the
                // Android Instrumentation only looks at the raw method name
                // anyway and all information about parameter types is lost
                identifier.format(true)
            } else {
                // Collect all dynamic tests' IDs from this identifier,
                // all the way up to the first non-dynamic test.
                // Collect the name of all these into a list, then finally
                // compose the final name from this list. Note that, because we
                // move upwards the test plan, the elements must be reversed
                // before the final name can be composed.
                val nameComponents = mutableListOf<String>()
                var currentNode: TestIdentifier? = identifier
                while (currentNode != null && currentNode.isDynamicTest) {
                    nameComponents.add(currentNode.format(false))
                    currentNode = modifiedTestPlan.getRealParent(currentNode).orElse(null)
                }
                nameComponents.reverse()

                // Android's Unified Test Platform (AGP 7.0+) is using literal test names
                // to create files when capturing Logcat output during execution.
                // Ergo, make sure that only legal characters are being used in the test names
                // (ref. https://github.com/mannodermaus/android-junit5/issues/263)
                nameComponents.joinToString(" - ")
            }

        identifier.isContainer -> getTechnicalName(identifier)

        else -> identifier.format(needLegacyFormat)
    }

    identifier.format(true)
} else {
    // Collect all dynamic tests' IDs from this identifier,
    // all the way up to the first non-dynamic test.
    // Collect the name of all these into a list, then finally
    // compose the final name from this list. Note that, because we
    // move upwards the test plan, the elements must be reversed
    // before the final name can be composed.
    val nameComponents = mutableListOf<String>()
    var currentNode: TestIdentifier? = identifier
    while (currentNode != null && currentNode.isDynamicTest) {
        nameComponents.add(currentNode.format(false))
        currentNode = modifiedTestPlan.getRealParent(currentNode).orElse(null)
    }
    nameComponents.reverse()

    // Android's Unified Test Platform (AGP 7.0+) is using literal test names
    // to create files when capturing Logcat output during execution.
    // Ergo, make sure that only legal characters are being used in the test names
    // (ref. https://github.com/mannodermaus/android-junit5/issues/263)
    nameComponents.joinToString(" - ")
}

