    configurations
        .filter { it.name.startsWith("testAgp") }
        .forEach { configuration ->
            val strippedName = configuration.name.substring(4).lowercase(Locale.ROOT)
            val prunedFile =
                File(defaultDirectory, "pruned-plugin-metadata-$strippedName.properties")
            outputs.file(prunedFile)

            doLast {
                prunedFile.writer().use { writer ->
                    // 1) Use output classes from the plugin itself
                    // 2) Use resources from the plugin (i.e. plugin IDs etc.)
                    // 3) Use AGP-specific dependencies
                    val classesDirs =
                        layout.buildDirectory
                            .dir("classes")
                            .get()
                            .asFile
                            .listFiles()
                            ?.filter { it.isDirectory }
                            ?.map { File(it, "main") }
                            ?.filter {
                                it.exists() && it.isDirectory && it.list()?.isEmpty() == false
                            } ?: emptyList()
                    val resourcesDirs =
                        layout.buildDirectory.dir("resources").get().asFile.listFiles()?.filter {
                            it.isDirectory
                        } ?: emptyList()

                    writer.write("implementation-classpath=")
                    writer.write(
                        (classesDirs + resourcesDirs + configuration).joinToString(
                            separator = "\\:"
                        )
                    )
                }
            }
        }
}

