class PluginSpecProjectCreator(private val environment: TestEnvironment) {

    fun newRootProject(): Project {
        // Pre-configure a "local.properties" file
        // containing the required location of the Android SDK
        val rootProject = ProjectBuilder.builder().build()

        rootProject.file("local.properties").writer().use {
            it.write("sdk.dir=${environment.androidSdkFolder.absolutePath}")
        }

        return rootProject
    }

    fun newProject(parent: Project, name: String? = null) = Builder(parent, name)

    inner class Builder(parent: Project, name: String?) {

        private var projectType = Type.Unset
        private var appId = "com.example.android"
        private var applyJUnit5Plugin: ((AndroidJUnitPlatformExtension) -> Unit)? = {}
        private var applyJacocoPlugin = false
        private var applyKotlinPlugin = false

        private val project =
            ProjectBuilder.builder().withParent(parent).run {
                if (name != null) {
                    this.withName(name)
                }

                build()
            }

        fun asAndroidApplication() = setProjectTypeIfUnsetTo(Type.Application)

        fun asAndroidDynamicFeature() = setProjectTypeIfUnsetTo(Type.DynamicFeature)

        fun asAndroidLibrary() = setProjectTypeIfUnsetTo(Type.Library)

        fun applyJUnit5Plugin(
            state: Boolean = true,
            configuration: ((AndroidJUnitPlatformExtension) -> Unit)? = null,
        ) = apply {
            this.applyJUnit5Plugin =
                if (state) {
                    configuration ?: {}
                } else {
                    null
                }
        }

        fun applyJacocoPlugin(state: Boolean = true) = apply { this.applyJacocoPlugin = state }

        fun applyKotlinPlugin(state: Boolean = true) = apply { this.applyKotlinPlugin = state }

        fun build(): Project {
            // Write out required Android file structure
            project.file(".").mkdir()
            project.file("src/main").mkdirs()

            val manifestFile = project.file("src/main/AndroidManifest.xml")
            if (!manifestFile.exists()) {
                manifestFile.writeText("<manifest/>")
            }

            // Apply required plugins
            projectType.pluginId?.let { project.applyPlugin(it) }

            if (applyJacocoPlugin) {
                project.applyPlugin("jacoco")
            }

            if (applyKotlinPlugin) {
                project.applyPlugin("kotlin-android")
            }

            if (applyJUnit5Plugin != null) {
                project.applyPlugin("de.mannodermaus.android-junit5")
            }

            // Add default configuration
            try {
                with(project.android) {
                    compileSdk = environment.compileSdkVersion
                    namespace = appId

                    if (projectType == Type.Application) {
                        project.androidApp.defaultConfig.apply {
                            applicationId = appId
                            minSdk = environment.minSdkVersion
                            targetSdk = environment.targetSdkVersion
                            versionCode = 1
                            versionName = "1.0"
                        }
                    }
                }
            } catch (_: UnknownDomainObjectException) {
                // Expected when the Android plugin is not applied to a project;
                // swallow this particular error
            }

            // Configure JUnit 5 with custom configuration clause, if any
            try {
                applyJUnit5Plugin?.invoke(project.junitPlatform)
            } catch (_: UnknownDomainObjectException) {
                // Expected when the JUnit 5 plugin is not applied to a project;
                // swallow this particular error
            }

            return project
        }

        fun buildAndEvaluate(): Project {
            val project = build()
            project.evaluate()
            return project
        }

        /* Private */

        private fun setProjectTypeIfUnsetTo(type: Type) = apply {
            if (projectType != Type.Unset) {
                throw IllegalArgumentException("Project type already set to $projectType")
            }

            this.projectType = type
        }
    }
}

class SemanticVersion(version: String) : Comparable<SemanticVersion> {
    val stableValue: Int = version.extractStableValue()
    val suffixValue: Int = version.extractSuffixValue()

    override fun compareTo(other: SemanticVersion): Int {
        val result = this.stableValue.compareTo(other.stableValue)
        return if (result == 0) {
            this.suffixValue.compareTo(other.suffixValue)
        } else {
            result
        }
    }
}

    dynamicColor: Boolean = true,
    content: @Composable () -> Unit
) {
    val colorScheme = when {
        dynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> {
            val context = LocalContext.current
            if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context)
        }
        darkTheme -> DarkColorScheme
        else -> LightColorScheme
    }
    val view = LocalView.current
    if (!view.isInEditMode) {
        SideEffect {
            (view.context as Activity).window.statusBarColor = colorScheme.primary.toArgb()
            ViewCompat.getWindowInsetsController(view)?.isAppearanceLightStatusBars = darkTheme
        }
    }

    MaterialTheme(
        colorScheme = colorScheme,
        typography = Typography,
        content = content
    )
}

