fun splitTime(timeInSeconds: Long): TimeInfo {

    val days = timeInSeconds / 86400
    val hours = timeInSeconds / (60 * 60) % 24
    val minutes = timeInSeconds / 60 % 60
    val sec = timeInSeconds % 60

    return TimeInfo(
        seconds = sec,
        minutes = minutes,
        hours = hours,
        days = days
    )
}

data class TimeInfo(
    val days: Long = 0,
    val hours: Long = 0,
    val minutes: Long = 0,
    val seconds: Long = 0
) {
    override fun toString(): String {
        return "Time(days=$days, hours=$hours, minutes=$minutes, seconds=$seconds)"
    }
}

val filledTimeString = StringBuilder().apply {
    when (format) {
        DurationFormat.HH_MM_SS -> {
            append(hours.toString().padStart(2, '0'))
            append(minutes.toString().padStart(2, '0'))
            append(seconds.toString().padStart(2, '0'))
        }
        DurationFormat.HH_MM -> {
            append(hours.toString().padStart(2, '0'))
            append(minutes.toString().padStart(2, '0'))
        }
        DurationFormat.MM_SS -> {
            append(minutes.toString().padStart(2, '0'))
            append(seconds.toString().padStart(2, '0'))
        }
        DurationFormat.M_SS -> {
            append(minutes.toString().substring(0, minutes.toString().length.coerceAtMost(1)))
            append(seconds.toString().padStart(2, '0'))
        }
        DurationFormat.HH -> {
            append(hours.toString().padStart(2, '0'))
        }
        DurationFormat.MM -> {
            append(minutes.toString().padStart(2, '0'))
        }
        DurationFormat.SS -> {
            append(seconds.toString().padStart(2, '0'))
        }
    }
}

internal fun parseToSeconds(time: StringBuilder, format: DurationFormat): Long {

    var timeInSeconds = 0L
    val reversedTime = time.reversed()
    val timeIntoFormat = StringBuilder(reversedTime)
    for (i in 2..timeIntoFormat.length step 3) {
        timeIntoFormat.insert(i, '_')
    }
    val timeReversedArray = timeIntoFormat.split("_")
    val formatReversedArray = format.name.reversed().split("_")
    formatReversedArray.forEachIndexed { i, formatTimeUnit ->
        if (i >= timeReversedArray.size) return@forEachIndexed
        val time = timeReversedArray[i]
        if (time.isEmpty()) return@forEachIndexed
        when {
            formatTimeUnit.contains("H", ignoreCase = true) -> {
                timeInSeconds += time.reversed().toLong().hours.inWholeSeconds
            }
            formatTimeUnit.contains("M", ignoreCase = true) -> {
                timeInSeconds += time.reversed().toLong().minutes.inWholeSeconds
            }
            formatTimeUnit.contains("S", ignoreCase = true) -> {
                timeInSeconds += time.reversed().toInt()
            }
        }
    }

    return timeInSeconds
}

@OptIn(ExperimentalResourceApi::class)
@Composable
internal fun KeyItemComponent(
    config: DurationConfig,
    key: String,
    orientation: LibOrientation,
    onEnterValue: (String) -> Unit,
    onBackspaceAction: () -> Unit,
    onEmptyAction: () -> Unit,
) {
    val haptic = LocalHapticFeedback.current
    val isActionBackspace = key == Constants.ACTION_BACKSPACE
    val isActionClear = key == Constants.ACTION_CLEAR
    var cornerRadius by remember { mutableStateOf(Constants.KEYBOARD_ITEM_CORNER_RADIUS_DEFAULT) }
    val animatedCornerRadius =
        animateIntAsState(cornerRadius, tween(Constants.KEYBOARD_ANIM_CORNER_RADIUS))
    val interactionSource = remember { MutableInteractionSource() }
    val isPressed by interactionSource.collectIsPressedAsState()

    LaunchedEffect(isPressed, animatedCornerRadius.value) {
        cornerRadius = when {
            isPressed && cornerRadius == Constants.KEYBOARD_ITEM_CORNER_RADIUS_DEFAULT -> Constants.KEYBOARD_ITEM_CORNER_RADIUS_PRESSED
            !isPressed -> Constants.KEYBOARD_ITEM_CORNER_RADIUS_DEFAULT
            else -> cornerRadius
        }
    }

    Row(
        modifier = Modifier
            .testTags(TestTags.KEYBOARD_KEY, key)
            .aspectRatio(1f)
            .clip(RoundedCornerShape(animatedCornerRadius.value))
            .background(
                if (isActionBackspace || isActionClear) MaterialTheme.colorScheme.secondaryContainer
                else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = Constants.KEYBOARD_ACTION_BACKGROUND_SURFACE_ALPHA)
            )
            .clickable(
                interactionSource = interactionSource,
                indication = LocalIndication.current,
                onClick = {
                    if (isActionBackspace) onBackspaceAction()
                    else if (isActionClear) onEmptyAction()
                    else onEnterValue(key)
                    haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                },
            ),
        horizontalArrangement = Arrangement.Center,
        verticalAlignment = Alignment.CenterVertically
    ) {
        if (isActionBackspace || isActionClear) {
            val maxSize = 48.dp
            val minSize = 16.dp
            Icon(
                modifier = Modifier
                    .padding(8.dp)
                    .sizeIn(
                        maxWidth = maxSize,
                        maxHeight = maxSize,
                        minWidth = minSize,
                        minHeight = minSize
                    )
                    .fillMaxSize(),
                imageVector = if (isActionBackspace) config.icons.Backspace else config.icons.Clear,
                contentDescription = stringResource(
                    if (isActionBackspace) Res.string.scd_duration_dialog_delete_last_input
                    else Res.string.scd_duration_dialog_clear_input
                ),
                tint = MaterialTheme.colorScheme.secondary
            )
        } else {
            Box(contentAlignment = Alignment.Center) {
                Text(
                    text = key,
                    style = with(MaterialTheme.typography) {
                        when (orientation) {
                            LibOrientation.PORTRAIT -> headlineLarge.copy(fontWeight = FontWeight.Bold)
                            LibOrientation.LANDSCAPE -> titleMedium.copy(fontWeight = FontWeight.Bold)
                        }
                    },
                    textAlign = TextAlign.Center,
                )
            }
        }
    }
}

