    selection: EmojiSelection,
    config: EmojiConfig
): EmojiState = rememberSaveable(
    inputs = arrayOf(selection, config),
    saver = EmojiState.Saver(selection, config),
    init = { EmojiState(selection, config) }

@ExperimentalMaterial3Api
@Composable
fun EmojiView(
    useCaseState: UseCaseState,
    selection: EmojiSelection,
    config: EmojiConfig = EmojiConfig(),
    header: Header? = null,
) {
    DisposableEffect(Unit) {
        EmojiInstaller.installProvider(config.emojiProvider)
        onDispose { EmojiInstaller.destroyProvider() }
    }

    val coroutine = rememberCoroutineScope()
    val emojiState = rememberEmojiState(selection, config)
    StateHandler(useCaseState, emojiState)

    val processSelection: (Emoji) -> Unit = { emoji ->
        emojiState.processSelection(emoji)
        BaseBehaviors.autoFinish(
            selection = selection,
            coroutine = coroutine,
            onSelection = emojiState::onFinish,
            onFinished = useCaseState::finish,
            onDisableInput = emojiState::disableInput
        )
    }

    val headerState = rememberLazyListState()
    LaunchedEffect(emojiState.selectedCategory) {
        headerState.animateScrollToItem(emojiState.selectedCategory)
    }

    FrameBase(
        header = header,
        config = config,
        layout = {
            EmojiHeaderComponent(
                config = config,
                categories = emojiState.categories,
                categoryIcons = Constants.getCategorySymbols(config),
                selectedCategory = emojiState.selectedCategory,
                headerState = headerState,
                onChangeCategory = emojiState::selectCategory
            )

            LazyVerticalGrid(
                modifier = Modifier
                    .dynamicContentWrapOrMaxHeight(this)
                    .padding(top = 16.dp),
                contentPadding = PaddingValues(
                    bottom = if (selection.withButtonView) 0.dp else 16.dp,
                ),
                horizontalArrangement = Arrangement.spacedBy(2.dp),
                verticalArrangement = Arrangement.spacedBy(2.dp),
                columns = GridCells.Fixed(emojiState.categories.size)
            ) {
                items(emojiState.categoryEmojis, key = { it.unicode }) { emoji ->
                    EmojiItemComponent(
                        emoji = emoji,
                        selectedEmoji = emojiState.selectedEmoji,
                        onClick = processSelection,
                    )
                }
            }
        },
        buttonsVisible = selection.withButtonView
    ) { orientation ->
        ButtonsComponent(
            orientation = orientation,
            onPositiveValid = emojiState.valid,
            selection = selection,
            onNegative = { selection.onNegativeClick?.invoke() },
            onPositive = emojiState::onFinish,
            state = useCaseState,
        )
    }
}

enum class EmojiCategoryAppearance {

    /**
     * Categories are displays with icons.
     */
    SYMBOL,

    /**
     * Categories are displayed with their name.
     */
    TEXT
}

enum class EmojiProvider {
    GOOGLE,
    IOS,
    FACEBOOK,
    TWITTER
}

internal object EmojiInstaller {

    private var initiated = false

    /**
     * Installs an emoji provider.
     * @param emojiProvider The emoji provider that will be installed.
     */
    @Synchronized
    fun installProvider(emojiProvider: EmojiProvider) {
        if (!initiated) {
            when (emojiProvider) {
                EmojiProvider.GOOGLE -> EmojiManager.install(GoogleEmojiProvider())
                EmojiProvider.IOS -> EmojiManager.install(IosEmojiProvider())
                EmojiProvider.FACEBOOK -> EmojiManager.install(FacebookEmojiProvider())
                EmojiProvider.TWITTER -> EmojiManager.install(TwitterEmojiProvider())
            }
            initiated = true
        }
    }

    /**
     * The emoji provider will be destroyed.
     */
    fun destroyProvider() {
        EmojiManager.destroy()
        initiated = false
    }
}

@Synchronized
fun installProvider(emojiProvider: EmojiProvider) {
    if (!initiated) {
        when (emojiProvider) {
            EmojiProvider.GOOGLE -> EmojiManager.install(GoogleEmojiProvider())
            EmojiProvider.IOS -> EmojiManager.install(IosEmojiProvider())
            EmojiProvider.FACEBOOK -> EmojiManager.install(FacebookEmojiProvider())
            EmojiProvider.TWITTER -> EmojiManager.install(TwitterEmojiProvider())
        }
        initiated = true
    }
}

fun destroyProvider() {
    EmojiManager.destroy()
    initiated = false
}

