@OptIn(ExperimentalResourceApi::class)
@Composable
internal fun OptionBoundsComponent(
    selection: OptionSelection,
    selectedOptions: List<Option>
) {
    val selectedAmount = selectedOptions.size
    when {
        selection is OptionSelection.Multiple
                && (selection.minChoices != null
                || selection.maxChoices != null) -> {
            Row(
                modifier = Modifier
                    .padding(horizontal = 24.dp)
                    .padding(bottom = 16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {

                selection.minChoices?.let { minChoices ->
                    if (selectedAmount < minChoices) {
                        Text(
                            text = stringResource(Res.string.scd_option_dialog_min_choices, minChoices),
                            style = MaterialTheme.typography.labelLarge
                        )
                    }
                }
                selection.maxChoices?.let { maxChoices ->
                    if (selectedAmount > maxChoices) {
                        Text(
                            text = stringResource(Res.string.scd_option_dialog_max_choices, maxChoices),
                            style = MaterialTheme.typography.labelLarge
                        )
                    }
                    Spacer(modifier = Modifier.weight(1f))
                    Text(
                        text = buildAnnotatedString {
                            withStyle(
                                MaterialTheme.typography.headlineSmall.copy(
                                    letterSpacing = 0.5.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.primary
                                ).toSpanStyle()
                            ) {
                                append(selectedAmount.toString())
                            }
                            append("/")
                            append(maxChoices.toString())
                        },
                        style = MaterialTheme.typography.labelLarge.copy(letterSpacing = 0.5.sp)
                    )
                }
            }
        }
        else -> Unit
    }
}

@Composable
fun OptionComponent(
    modifier: Modifier,
    config: OptionConfig,
    options: List<Option>,
    inputDisabled: Boolean,
    onOptionChange: (Option) -> Unit,
) {

    val verticalDirectionModifier = modifier
        .fillMaxWidth()
        .padding(horizontal = 24.dp)

    val columnsLimits = config.gridColumns
    val columns = if (options.size < columnsLimits) options.size else columnsLimits

    val onClick: (Option) -> Unit = { option ->
        val newOption = option.copy(selected = !option.selected).apply {
            position = option.position
        }
        onOptionChange(newOption)
    }

    val size = remember { mutableStateOf<Size?>(null) }

    when (config.mode) {
        DisplayMode.GRID_HORIZONTAL -> {
            LazyRow(
                contentPadding = PaddingValues(horizontal = 24.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(options) { option ->
                    OptionItemComponent(
                        config = config,
                        option = option,
                        inputDisabled = inputDisabled,
                        onClick = onClick,
                        size = size,
                    )
                }
            }
        }
        DisplayMode.GRID_VERTICAL -> {
            LazyVerticalGrid(
                modifier = verticalDirectionModifier,
                columns = GridCells.Fixed(columns),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(options) { option ->
                    OptionItemComponent(
                        config = config,
                        option = option,
                        inputDisabled = inputDisabled,
                        onClick = onClick,
                        size = size,
                    )
                }
            }
        }
        DisplayMode.LIST -> {
            LazyColumn(
                modifier = verticalDirectionModifier,
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(options) { option ->
                    OptionItemComponent(
                        config = config,
                        option = option,
                        inputDisabled = inputDisabled,
                        onClick = onClick,
                        grid = false
                    )
                }
            }
        }
    }
}

