internal class RatingState(
    val selection: RatingSelection,
    val config: RatingConfig = RatingConfig(),
    stateData: RatingStateData? = null,
) : BaseTypeState() {

    var rating: Int? by mutableStateOf(stateData?.rating ?: config.ratingOptionsSelected)
    var feedback by mutableStateOf(stateData?.feedback)

    var ratingValid by mutableStateOf(isRatingValid())
    var feedbackValid by mutableStateOf(isFeedbackValid())

    private fun checkValid() {
        ratingValid = isRatingValid()
        feedbackValid = isFeedbackValid()
    }

    fun updateRating(newRating: Int) {
        rating = if (rating == newRating) {
            max(newRating - 1, 0)
        } else {
            newRating
        }
        checkValid()
    }

    fun updateFeedback(newFeedback: String) {
        feedback = newFeedback
        checkValid()
    }

    private fun isRatingValid(): Boolean = if (config.ratingZeroValid) {
        true
    } else {
        rating != null && (rating ?: 0) > 0
    }

    private fun isFeedbackValid(): Boolean =
        if (config.feedbackOptional) true
        else !feedback.isNullOrBlank()

    fun onFinish() {
        selection.onSelectRating(rating ?: 0, feedback)
    }

    override fun reset() {
        rating = null
        feedback = null
    }

    companion object {

        /**
         * [Saver] implementation.
         * @param selection The selection configuration for the dialog view.
         * @param config The general configuration for the dialog view.
         */
        fun Saver(
            selection: RatingSelection,
            config: RatingConfig
        ): Saver<RatingState, *> = Saver(
            save = { state -> RatingStateData(state.rating, state.feedback) },
            restore = { data -> RatingState(selection, config, data) }
        )
    }

    /**
     * Data class that stores the rating info of the current state
     * and can be used by the [Saver] to save and restore the state.
     */
    @Serializable
    data class RatingStateData(
        val rating: Int?,
        val feedback: String?,
    ) : JvmSerializable
}

@Composable
internal fun rememberRatingState(
    selection: RatingSelection,
    config: RatingConfig,
): RatingState = rememberSaveable(
    inputs = arrayOf(selection, config),
    saver = RatingState.Saver(selection, config),
    init = { RatingState(selection, config) }

@ExperimentalMaterial3Api
@Composable
fun RatingView(
    useCaseState: UseCaseState,
    selection: RatingSelection,
    config: RatingConfig,
    header: Header? = null,
    body: RatingBody,
) {
    val ratingState = rememberRatingState(selection, config)
    StateHandler(useCaseState, ratingState)
    val coroutine = rememberCoroutineScope()
    val onSelectRating: (Int) -> Unit = {
        ratingState.updateRating(it)
        if (!config.withFeedback) {
            BaseBehaviors.autoFinish(
                selection = selection,
                coroutine = coroutine,
                onSelection = ratingState::onFinish,
                onFinished = useCaseState::finish,
                onDisableInput = ratingState::disableInput
            )
        }
    }
    FrameBase(
        header = header,
        layout = {
            RatingBodyComponent(
                config = config,
                body = body
            )
            Spacer(modifier = Modifier.height(24.dp))
            RatingComponent(
                config = config,
                rating = ratingState.rating,
                feedback = ratingState.feedback,
                feedbackError = !ratingState.feedbackValid,
                onSelectRating = onSelectRating,
                onUpdateFeedback = ratingState::updateFeedback,
            )
        },
        buttonsVisible = selection.withButtonView
    ) { orientation ->
        ButtonsComponent(
            orientation = orientation,
            selection = selection,
            onPositiveValid = ratingState.ratingValid && ratingState.feedbackValid,
            onNegative = { selection.onNegativeClick?.invoke() },
            onPositive = ratingState::onFinish,
            state = useCaseState,
        )
    }
}

