        ) : super(
            value = value,
            showProgressPercentage = showProgressPercentage,
            customProgressIndicator = customProgressIndicator
        )
    }

    /**
     * Circular progress indicator.
     */
    class Circular : ProgressIndicator {

        /**
         * Indeterminate circular progress indicator.
