fun View.fadeIn(
    alpha: Float = ANIM_ALPHA_MAX,
    duration: Long = ANIM_DURATION_300,
    listener: (() -> Unit)? = null,
) {

    animate().alpha(alpha)
        .setDuration(duration)
        .setInterpolator(AccelerateDecelerateInterpolator())
        .withEndAction { listener?.invoke() }
        .start()
}

