        val handleWidth = dimensionOfAttrs(ctx, R.attr.sheetsHandleWidth) ?: 28.getDp()
        val handleHeight = dimensionOfAttrs(ctx, R.attr.sheetsHandleHeight) ?: 4.getDp()

        addView(ImageView(ctx).apply {
