private fun save() {

    if (multipleChoices) {
        val selectedOptions =
            options.filterIndexed { index, _ -> optionsSelected.contains(index) }
                .toMutableList()
        listenerMultiple?.invoke(this, optionsSelected, selectedOptions)
    } else {
        optionsSelected.firstOrNull()?.let { index ->
            listener?.invoke(index, options[index])
        }
    }
    dismiss()
}

