fun AnnotatedString.Builder.appendAutoLink(
    content: String,
    node: ASTNode,
    annotatorSettings: AnnotatorSettings,
) {
    val targetNode = node.children.firstOrNull {
        it.type.name == MarkdownElementTypes.AUTOLINK.name
    } ?: node
    val destination = targetNode.getUnescapedTextInNode(content)

    annotatorSettings.referenceLinkHandler?.store(destination, destination)
    withLink(LinkAnnotation.Url(destination, annotatorSettings.linkTextSpanStyle, linkInteractionListener = annotatorSettings.linkInteractionListener)) {
        append(destination)
    }
}

private fun AnnotatedString.Builder.appendEmailAutoLink(
    content: String,
    node: ASTNode,
    annotatorSettings: AnnotatorSettings,
) {
    val email = node.getUnescapedTextInNode(content)
    val destination = "mailto:$email"

    annotatorSettings.referenceLinkHandler?.store(email, destination)
    withLink(LinkAnnotation.Url(destination, annotatorSettings.linkTextSpanStyle, linkInteractionListener = annotatorSettings.linkInteractionListener)) {
        append(email)
    }
}

@Composable
fun LazyMarkdownSuccess(
    state: State.Success,
    components: MarkdownComponents,
    modifier: Modifier = Modifier,
    contentPadding: PaddingValues = PaddingValues(0.dp),
) {
    // Extract nodes for rendering
    val nodes = remember(state.node) { state.node.children }

    LazyColumn(
        modifier = modifier,
        contentPadding = contentPadding,
    ) {
        items(
            items = nodes,
            // Use the node's start offset as a key for stable item identity
            key = { node -> node.startOffset },
            // contentType lets the lazy layout reuse compositions across items
            // of the same markdown element type (e.g. paragraph after paragraph).
            contentType = { node -> node.type }
        ) { node ->
            MarkdownElement(node, components, state.content)
        }
    }
}

@Composable
fun LazyMarkdownSuccess(
    streamingMarkdownState: StreamingMarkdownState,
    snapshot: StreamingMarkdownState.Snapshot,
    components: MarkdownComponents,
    modifier: Modifier = Modifier,
    contentPadding: PaddingValues = PaddingValues(0.dp),
) {
    val content = streamingMarkdownState.content
    val nodes = remember(snapshot) { snapshot.stableAst + snapshot.unstableAstTail }

    LazyColumn(
        modifier = modifier,
        contentPadding = contentPadding,
    ) {
        items(
            items = nodes,
            key = { node -> node.startOffset },
            contentType = { node -> node.type }
        ) { node ->
            MarkdownElementInternal(node, components, content)
        }
    }
}

