@Composable
fun MarkdownAlert(
    content: String,
    node: ASTNode,
    type: MarkdownAlertType,
    title: String = type.title,
    icon: ImageVector? = LocalMarkdownAlertIcons.current.iconFor(type),
    accent: Color = LocalMarkdownColors.current.alert.colorFor(type),
    style: TextStyle = LocalMarkdownTypography.current.alertTitle,
) {
    val dimens = LocalMarkdownDimens.current.alert
    val padding = LocalMarkdownPadding.current.alert
    val markdownComponents = LocalMarkdownComponents.current
    val a11yLabels = LocalMarkdownA11yLabels.current
    val bar = padding.bar
    val barThickness = dimens.barThickness

    Column(
        modifier = Modifier
            .semantics { contentDescription = a11yLabels.alert(title) }
            .drawBehind {
                val x = bar.calculateStartPadding(LayoutDirection.Ltr).toPx()
                drawLine(
                    color = accent,
                    strokeWidth = barThickness.toPx(),
                    start = Offset(x, bar.calculateTopPadding().toPx()),
                    end = Offset(x, size.height - bar.calculateBottomPadding().toPx()),
                )
            }
            .padding(padding.container)
    ) {
        Column(modifier = Modifier.padding(padding.content)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                if (icon != null) {
                    Image(
                        painter = rememberVectorPainter(icon),
                        contentDescription = null,
                        colorFilter = ColorFilter.tint(accent),
                        modifier = Modifier.size(dimens.iconSize),
                    )
                    Spacer(Modifier.width(padding.iconSpacing))
                }
                MarkdownBasicText(
                    text = title,
                    style = style,
                    color = if (style.color.isSpecified) style.color else accent,
                )
            }

            Spacer(Modifier.height(padding.titleSpacing))

            // The parser leaves the `> ` markers in the tree: a leading BLOCK_QUOTE *token*, and an
            // `EOL WHITE_SPACE` pair before every continuation line. Dropping those, plus everything up
            // to and including ALERT_TITLE, leaves exactly the alert's block content. Blocks are always
            // separated by a blank line, so a uniform gap between them is enough. Note the marker token
            // shares its name with `MarkdownElementTypes.BLOCK_QUOTE` — a nested quote — which renders.
            var pastTitle = false
            var seenContent = false
            node.children.forEach { child ->
                when {
                    !pastTitle -> if (child.type == GFMTokenTypes.ALERT_TITLE) pastTitle = true
                    child.type == EOL || child.type == WHITE_SPACE || child.type == BLOCK_QUOTE -> Unit
                    else -> {
                        if (seenContent) Spacer(Modifier.height(padding.titleSpacing))
                        seenContent = true
                        // Stable key by source offset gives each child its own slot and
                        // keeps recompositions isolated when a sibling changes.
                        key(child.startOffset) {
                            MarkdownElement(
                                node = child,
                                components = markdownComponents,
                                content = content,
                                includeSpacer = false,
                            )
                        }
                    }
                }
            }
        }
    }
}

key(child.startOffset) {
    MarkdownElement(
        node = child,
        components = markdownComponents,
        content = content,
        includeSpacer = false,
    )
}

key(child.startOffset) {
    if (child.type == MarkdownElementTypes.BLOCK_QUOTE) {
        // if block quote is nested, and comes after non block quote, add padding
        if (!priorNestedQuote && index != 0) Spacer(Modifier.height(blockQuoteText.calculateBottomPadding()))
        MarkdownBlockQuote(content = content, node = child, style = style)
        priorNestedQuote = true
    } else if (child.type == EOL) {
        Spacer(Modifier.height(blockQuoteEmptyLineHeight))
    } else {
        // if first item either completely, or after a nested quote, add top padding
        if (index == 0 || priorNestedQuote) Spacer(Modifier.height(blockQuoteText.calculateTopPadding()))
        priorNestedQuote = false
        MarkdownElement(
            node = child,
            components = markdownComponents,
            content = content,
            includeSpacer = false
        )
        // if last item, add bottom padding
        if (index == node.children.lastIndex) Spacer(Modifier.height(blockQuoteText.calculateBottomPadding()))
    }
}

@Composable
fun ImageAltTooltip(alt: String?, content: @Composable () -> Unit) {
    val config = LocalMarkdownAnnotator.current.config
    if (!config.showImageAltTooltip || alt.isNullOrBlank()) {
        content()
        return
    }

    val interactionSource = remember { MutableInteractionSource() }
    val isHovered by interactionSource.collectIsHoveredAsState()
    val transitionState = remember { MutableTransitionState(false) }

    LaunchedEffect(isHovered, config.imageAltTooltipHoverDelayMs) {
        if (isHovered) {
            delay(config.imageAltTooltipHoverDelayMs)
            transitionState.targetState = true
        } else {
            transitionState.targetState = false
        }
    }

    // Keep the popup mounted while either the target is visible or the
    // exit animation is still running, so fadeOut can play before unmount.
    val mounted = transitionState.currentState || transitionState.targetState

    Box(modifier = Modifier.hoverable(interactionSource)) {
        content()
        if (mounted) {
            Popup(popupPositionProvider = AnchorBelowPositionProvider) {
                AnimatedVisibility(
                    visibleState = transitionState,
                    enter = fadeIn(),
                    exit = fadeOut(),
                ) {
                    Box(
                        modifier = Modifier
                            .background(Color(0xCC000000), RoundedCornerShape(4.dp))
                            .padding(horizontal = 8.dp, vertical = 4.dp),
                    ) {
                        BasicText(
                            text = alt,
                            style = TextStyle(color = Color.White, fontSize = 12.sp),
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun MarkdownListItem(
    content: String,
    child: ASTNode,
    node: ASTNode,
    index: Int,
    listNumber: Int,
    depth: Int,
    markdownComponents: MarkdownComponents,
    markdownTypography: MarkdownTypography,
    padding: MarkdownPadding,
    markerModifier: RowScope.() -> Modifier,
    listModifier: RowScope.() -> Modifier,
    bullet: @Composable (index: Int, listNumber: Int, child: ASTNode?) -> Unit,
) {
    val checkboxNode = child.children.getOrNull(1)?.takeIf { it.type == CHECK_BOX }
    val listIndicator = when (node.type) {
        ORDERED_LIST -> child.findChildOfType(LIST_NUMBER)
        UNORDERED_LIST -> child.findChildOfType(LIST_BULLET)
        else -> null
    }

    Row(
        modifier = Modifier
            // Group marker + content as one traversal unit but preserve per-link a11y nodes inside.
            .semantics { isTraversalGroup = true }
            .fillMaxWidth()
            .padding(top = padding.listItemTop, bottom = padding.listItemBottom)
    ) {
        // Render marker symbol (checkbox or bullet)
        Box(modifier = markerModifier()) {
            if (checkboxNode != null) {
                val model = MarkdownComponentModel(
                    content = content,
                    node = checkboxNode,
                    typography = markdownTypography,
                    extra = persistentMapOf(MARKDOWN_LIST_DEPTH_KEY to depth + 1)
                )
                markdownComponents.checkbox.invoke(model)
            } else {
                bullet(index, listNumber, listIndicator)
            }
        }

        // Render list item content
        Column(modifier = listModifier()) {
            child.children.forEach { nestedChild ->
                MarkdownNestedListItem(
                    nestedChild = nestedChild,
                    content = content,
                    depth = depth,
                    markdownComponents = markdownComponents,
                    markdownTypography = markdownTypography
                )
            }
        }
    }
}

