protected fun ChannelFuture.closeOnWriteFailure(ctx: ChannelHandlerContext): ChannelFuture {
  val self = this

  val listener =
      closeOnWriteFailureListener
          ?: ChannelFutureListener { future ->
            if (!future.isSuccess) {
              Timber.e(future.cause()) {
                "(${getChannelId()}) Write failed, close"
