public fun requireLifecycle(): SubscriberLifecycle = requireNotNull(LocalSubscriberLifecycle.current) {
    "Subscriber lifecycle was required but not found. " +
        "Please either provide a lifecycle using LocalSubscriberLifecycle, pass the lifecycle manually, " +
        "or use DefaultLifecycle to fall back to system lifecycle."
}

internal tailrec fun chunkedLog(
    message: String,
    maxLength: Int = MaxLogcatMessageLength,
    minLength: Int = MinLogcatMessageLength,
    delegate: (String) -> Unit
) {
    // String to be logged is longer than the max...
    if (message.length > maxLength) {
        var msgSubstring = message.substring(0, maxLength)
        var msgSubstringEndIndex = maxLength

        // Try to find a substring break at a newline char.
        msgSubstring.lastIndexOf('\n').let { lastIndex ->
            if (lastIndex >= minLength) {
                msgSubstring = msgSubstring.substring(0, lastIndex)
                // skip over new line char
                msgSubstringEndIndex = lastIndex + 1
            }
        }

        // Log the substring.
        delegate(msgSubstring)

        // Recursively log the remainder.
        chunkedLog(message.substring(msgSubstringEndIndex), maxLength, minLength, delegate)
    } else {
        delegate(message)
    } // String to be logged is shorter than the max...
}

msgSubstring.lastIndexOf('\n').let { lastIndex ->
    if (lastIndex >= minLength) {
        msgSubstring = msgSubstring.substring(0, lastIndex)
        // skip over new line char
        msgSubstringEndIndex = lastIndex + 1
    }
}

    chunkedLog(message.substring(msgSubstringEndIndex), maxLength, minLength, delegate)
} else {
    delegate(message)
}

public fun interface ActionConsumer<in A : MVIAction> {

    /**
     * Consume a one-time side-effect emitted by [Provider].
     *
     * This function is called each time an [MVIAction] arrives, only once.
     * It may send intents under a promise that no loops will occur.
     * This function will behave differently based on [ActionShareBehavior] chosen for the store.
     * It may drop old intents, wait for buffer to be cleared, or throw an exception.
     */
    public fun consume(action: A)
}

public interface ActionProvider<out A : MVIAction> {

