public class TimeTravel<S : MVIState, I : MVIIntent, A : MVIAction>(
    maxStates: Int = DefaultHistorySize,
    maxIntents: Int = DefaultHistorySize,
    maxActions: Int = DefaultHistorySize,
    maxExceptions: Int = DefaultHistorySize,
) {
    private val lock = reentrantLock()

    public constructor(maxHistorySize: Int = DefaultHistorySize) : this(
        maxHistorySize, maxHistorySize, maxHistorySize, maxHistorySize
    )
    private val _states = CappedMutableList<S>(maxStates)

    /**
     * States emitted by the store, capped at max value provided at creation time
     * The last value is the most recent.
     */
    public val states: List<S> get() = _states
    private val _intents = CappedMutableList<I>(maxIntents)

    /**
     * Intents processed by the store, capped at the value provided at creation time.
     * The last value is the most recent.
     */
    public val intents: List<I> get() = _intents
    private val _actions = CappedMutableList<A>(maxActions)

    /**
     *  Actions sent by the store, capped at the value provided at creation time.
     * The last value is the most recent.
     */
    public val actions: List<A> get() = _actions
    private val _exceptions = CappedMutableList<Exception>(maxExceptions)

    /**
     * Last exceptions caught by store, capped at the value provided at creation time.
     * The last value is the most recent.
     */
    public val exceptions: Collection<Exception> get() = _exceptions
    private var _subscriptions: Int by atomic(0)

    /**
     * Number of subscription events of the store. Never decreases.
     * The last value is the most recent.
     */
    public val subscriptions: Int get() = _subscriptions
    private var _starts: Int by atomic(0)

    /**
     * Number of times the store was launched. Never decreases.
     */
    public val starts: Int get() = _starts
    private var _stops: Int by atomic(0)

    /**
     * Number of the times the store was stopped. Never decreases.
     */
    public val stops: Int get() = _stops
    private var _unsubscriptions: Int by atomic(0)

    /**
     * Number of times the store has been unsubscribed from. Never decreases.
     */
    public val unsubscriptions: Int get() = _unsubscriptions

    /**
     * Reset all values of this plugin and start from scratch.
     */
    @IgnorableReturnValue
    public fun reset(): Unit = lock.withLock {
        _states.clear()
        _intents.clear()
        _actions.clear()
        _exceptions.clear()
        _subscriptions = 0
        _unsubscriptions = 0
        _starts = 0
        _stops = 0
    }
    internal fun asPlugin(name: String) = plugin {
        this.name = name
        onState { _: S, new: S -> new.also { lock.withLock { _states.add(new) } } }
        onIntent { intent: I -> intent.also { lock.withLock { _intents.add(it) } } }
        onAction { action: A -> action.also { lock.withLock { _actions.add(it) } } }
        onException { e: Exception -> e.also { lock.withLock { _exceptions.add(it) } } }
        onStart { _starts += 1 }
        onSubscribe { _subscriptions += 1 }
        onUnsubscribe { _unsubscriptions += 1 }
        onStop { _stops += 1 }
    }

    @Suppress("UndocumentedPublicClass")
    public companion object {

        /**
         * The default max size for time travel holders
         */
        public const val DefaultHistorySize: Int = 64

        /**
         * Default time travel plugin name. Hardcoded to prevent multiple plugins from being installed.
         */
        public const val Name: String = "TimeTravelPlugin"
    }
}

public fun <S : MVIState, I : MVIIntent, A : MVIAction> StoreBuilder<S, I, A>.timeTravel(
    historySize: Int = TimeTravel.DefaultHistorySize,
    name: String = TimeTravel.Name,
): TimeTravel<S, I, A> = TimeTravel<S, I, A>(historySize).also { install(timeTravelPlugin(it, name = name)) }

public class UndoRedo(
    private val maxQueueSize: Int,
) {

    init {
        require(maxQueueSize > 0) { "Queue size less than 1 is not allowed, you provided: $maxQueueSize" }
    }
    private val _queue by atomic<CappedMutableList<Event>>(CappedMutableList(maxQueueSize))
    private val _index = MutableStateFlow(-1)
    private val lock = Mutex()

    /**
     * Current index of the queue.
     *
     * Larger value means newer, but not larger than [maxQueueSize].
     * When the index is equal to -1, the undo queue is empty.
     * An index of 0 means that there is one event to undo.
     */
    public val index: StateFlow<Int> = _index.asStateFlow()

    /**
     * Current state of the [Queue].
     * For synchronous / initial queue value access, see [canUndo], [canRedo], [queueSize]
     */
    public val queue: Flow<Queue> = _index.asStateFlow().map { i -> Queue(i, canUndo, canRedo) }

    /**
     * Whether the event queue is empty. Does not take [Queue.index] into account
     */
    public val isQueueEmpty: Boolean get() = _queue.isEmpty()

    /**
     * The current queue size of the plugin.
     * This queue size does **not** consider current index and allows to get the total amount of events stored
     */
    public val queueSize: Int get() = _queue.size

    /**
     * Whether the plugin can [undo] at this moment.
     */
    public val canUndo: Boolean get() = !isQueueEmpty && _index.value >= 0

    /**
     * Whether the plugin can [redo] at this moment.
     */
    public val canRedo: Boolean get() = !isQueueEmpty && _index.value < _queue.lastIndex

    /**
     * Add a given [undo] and [redo] to the queue.
     * If [doImmediately] is true, then [redo] will be executed **before** the queue is modified!
     * **You cannot call [UndoRedo.undo] or [UndoRedo.redo] in [redo] or [undo]!**
     */
    public suspend operator fun invoke(
        doImmediately: Boolean = true,
        redo: suspend () -> Unit,
        undo: suspend () -> Unit,
    ): Int = lock.withLock {
        with(_queue) {
            if (doImmediately) redo()
            val range = _index.value.coerceAtLeast(0) + 1..lastIndex
            if (!range.isEmpty()) removeAll(slice(range).toSet())
            add(Event(redo, undo))
            lastIndex.also { _index.value = it }
        }
    }

    /**
     * Add the [intent] to the queue with specified [undo] and **immediately** execute the [intent].
     * **You cannot call [UndoRedo.undo] or [UndoRedo.redo] in [intent] or [undo]!**
     */
    public suspend operator fun <I : MVIIntent> IntentReceiver<I>.invoke(
        intent: I,
        undo: suspend () -> Unit,
    ): Int = invoke(redo = { intent(intent) }, undo = undo, doImmediately = true)

    /**
     * Undo the event at current [_index].
     * **You cannot undo and redo while another undo/redo is running!**
     */
    @IgnorableReturnValue
    public suspend fun undo(require: Boolean = false): Int = lock.withLock {
        if (!canUndo) {
            require(!require) { "Tried to undo action #${_index.value} but nothing was in the queue" }
            -1
        } else {
            val i = _index.value.coerceIn(_queue.indices)
            _queue[i].undo()
            (i - 1).also { _index.value = it }
        }
    }

    /**
     * Redo the event at current [_index].
     * **You cannot undo and redo while another undo/redo is running!**
     */
    @IgnorableReturnValue
    public suspend fun redo(require: Boolean = false): Int = lock.withLock {
        if (!canRedo) {
            require(!require) { "Tried to redo but queue already at the last index of ${_queue.lastIndex}" }
            _queue.lastIndex
        } else {
            val i = _index.value.coerceIn(_queue.indices)
            _queue[i].redo()
            (i + 1).also { _index.value = it }
        }
    }

    /**
     * Clear the queue of events and reset [_index] to -1
     */
    @IgnorableReturnValue
    public fun reset(): Unit = _index.update {
        _queue.clear()
        -1
    }
    internal fun <S : MVIState, I : MVIIntent, A : MVIAction> asPlugin(
        name: String?,
        resetOnException: Boolean,
    ): StorePlugin<S, I, A> = plugin {
        this.name = name
        // reset because pipeline context captured in Events is no longer running
        onStop { reset() }
        if (resetOnException) onException { it.also { reset() } }
    }

    /**
     * An event happened in the [UndoRedo].
     */
    internal data class Event internal constructor(
        internal val redo: suspend () -> Unit,
        internal val undo: suspend () -> Unit,
    ) {
        override fun toString(): String = "UndoRedoPlugin.Event"
    }

    /**
     * Undo/redo queue representation
     *
     * @param index Current index of the queue.
     * Larger value means newer, but not larger than [maxQueueSize].
     * When the index is equal to -1, the undo queue is empty.
     * An index of 0 means that there is one event to undo.
     * @param canUndo whether there are actions to undo
     * @param canRedo whether there are actions to redo
     * @see _queue
     */
    public data class Queue(
        val index: Int,
        val canUndo: Boolean,
        val canRedo: Boolean,
    )
}

public suspend operator fun invoke(
    doImmediately: Boolean = true,
    redo: suspend () -> Unit,
    undo: suspend () -> Unit,
): Int = lock.withLock {
    with(_queue) {
        if (doImmediately) redo()
        val range = _index.value.coerceAtLeast(0) + 1..lastIndex
        if (!range.isEmpty()) removeAll(slice(range).toSet())
        add(Event(redo, undo))
        lastIndex.also { _index.value = it }
    }
}

