enum class LaunchMethod {
    /** `su -> am start`. Requires a rooted device. */
    ROOT,

    /**
     * Swaps the secure "assistant" setting to the target and triggers assist so the system launches
     * it. Requires Shizuku (to inject the assist key) and `WRITE_SECURE_SETTINGS` (for the swap).
     */
    SHIZUKU,
}

sealed interface LaunchResult {

    /** The activity was started successfully. */
    data object Success : LaunchResult

    /**
     * The mechanism is not usable right now (root/Shizuku unavailable, permission missing, ...).
     * The caller is expected to route the user to the matching onboarding screen.
     */
    data object Unavailable : LaunchResult

    /** The launch was attempted but failed. [messageRes] describes the failure to the user. */
    data class Error(@param:StringRes val messageRes: Int) : LaunchResult
}

interface LaunchStrategy {

    val method: LaunchMethod

    /**
     * Whether this mechanism can currently perform a launch: e.g. root is granted, the Shizuku
     * service is running and authorized, or WRITE_SECURE_SETTINGS has been granted. Runs off the
     * main thread (may do binder / process IO).
     */
    suspend fun isAvailable(context: Context): Boolean

    /** Attempts to launch [component]. Callers should check [isAvailable] first. */
    suspend fun launch(context: Context, component: ComponentName): LaunchResult
}

class LaunchStrategyFactory(
    private val strategies: Map<LaunchMethod, LaunchStrategy>,
) {

    fun get(method: LaunchMethod): LaunchStrategy =
        strategies.getValue(method)

    /**
     * Picks the mechanism to use for a non-exported activity: root if available, otherwise Shizuku.
     * Returns null when neither is usable (the caller should show onboarding).
     */
    suspend fun resolveAvailable(context: Context): LaunchStrategy? =
        ORDER.firstNotNullOfOrNull { method ->
            strategies[method]?.takeIf { it.isAvailable(context) }
        }

    private companion object {
        val ORDER = listOf(LaunchMethod.ROOT, LaunchMethod.SHIZUKU)
    }
}

suspend fun resolveAvailable(context: Context): LaunchStrategy? =
    ORDER.firstNotNullOfOrNull { method ->
        strategies[method]?.takeIf { it.isAvailable(context) }
    }

class RootLaunchStrategy(
    private val appPreferences: AppPreferences,
) : LaunchStrategy {

    override val method = LaunchMethod.ROOT

    override suspend fun isAvailable(context: Context): Boolean = withContext(Dispatchers.IO) {
        RootUtils.isSuAvailable(appPreferences.suExecutable)
    }

    override suspend fun launch(context: Context, component: ComponentName): LaunchResult =
        withContext(Dispatchers.IO) {
            val suExecutable = appPreferences.suExecutable
            if (!RootUtils.isSuAvailable(suExecutable)) {
                return@withContext LaunchResult.Unavailable
            }
            try {
                val command =
                    "am start -n ${component.packageName}/${component.normalizeClassName()}"
                Timber.d("Execute: \"$command\"")
                val result = RootUtils.execute(suExecutable, command)
                Timber.d("Result: \"$result\"")
                LaunchResult.Success
            } catch (e: Exception) {
                Timber.e(e)
                LaunchResult.Error(R.string.starting_activity_root_error)
            }
        }

    private fun ComponentName.normalizeClassName(): String =
        if (className.contains("$")) className.replace("$", "\\$") else className
}

fun restorePendingBackup(context: Context, appPreferences: AppPreferences) {
    val backup = appPreferences.assistantBackup ?: return
    if (context.checkSelfPermission(Manifest.permission.WRITE_SECURE_SETTINGS) !=
        PackageManager.PERMISSION_GRANTED
    ) {
        return
    }
    try {
        val resolver = context.contentResolver
        Settings.Secure.putString(resolver, KEY_ASSISTANT, backup.assistant)
        Settings.Secure.putString(resolver, KEY_VOICE_INTERACTION, backup.voiceInteraction)
        Timber.d("Restored assistant backup")
    } catch (e: Exception) {
        Timber.e(e, "Failed to restore assistant backup")
    } finally {
        appPreferences.assistantBackup = null
    }
}

fun isServiceRunning(): Boolean = try {
    Shizuku.pingBinder() && !Shizuku.isPreV11()
