fun initialize(activityModel: ActivityModel? = null, launchParams: LaunchParams? = null) {
    if (isInitialized) return
    isInitialized = true

    if (launchParams != null) {
        _launchParamsState.value = launchParams
        return
    }
    _launchParamsState.update {
        it.copy(
            packageName = activityModel?.packageName,
            className = activityModel?.className,
        )
    }
}

fun launch(saveToHistory: Boolean) {
    val params = _launchParamsState.value
    if (saveToHistory) {
        addToHistory()
    }
    if (params.useRoot) {
        launchAsRoot(params)
    } else {
        val intent = LaunchParamsToIntentConverter(params).convert()
        val error = activityLauncher.launchIntent(intent)
        if (error != null) {
            _events.trySend(LaunchEvent.LaunchError(error))
        }
    }
}

sealed interface AnalyzerItem {

    /**
     * Group header, e.g. "Extras". A [collapsible] section can be folded away by tapping it and
     * starts folded, for groups that are long enough to bury everything below them.
     */
    data class Section(
        val title: String,
        val collapsible: Boolean = false,
    ) : AnalyzerItem

    /**
     * Labelled value. [type] is the runtime type of the value when it is worth showing, e.g. the
     * class of an extra.
     */
    data class Field(
        val label: String,
        val value: String,
        val type: String? = null,
    ) : AnalyzerItem

    /** Standalone value that needs no label, e.g. a single category or flag. */
    data class Value(val value: String) : AnalyzerItem
}

fun List<AnalyzerItem>.foldSections(collapsed: Set<String>): List<AnalyzerItem> {
    val result = ArrayList<AnalyzerItem>(size)
    var hidden = false
    for (item in this) {
        if (item is AnalyzerItem.Section) {
            hidden = item.title in collapsed
            result.add(item)
        } else if (!hidden) {
            result.add(item)
        }
    }
    return result
}

fun List<AnalyzerItem>.rowCountsPerSection(): Map<String, Int> {
    val counts = mutableMapOf<String, Int>()
    var title: String? = null
    for (item in this) {
        if (item is AnalyzerItem.Section) {
            title = item.title
            counts[title] = 0
        } else if (title != null) {
            counts[title] = counts.getValue(title) + 1
        }
    }
    return counts
}

private fun MutableList<AnalyzerItem>.addHandlers(intent: Intent) {
    if (intent.action == null && intent.data == null && intent.type == null) return
    val probe = Intent(intent.action).apply {
        setDataAndType(intent.data, intent.type)
        intent.categories?.forEach { addCategory(it) }
    }
    val packageManager = context.packageManager
    val resolved = try {
        packageManager.queryIntentActivities(probe, PackageManager.MATCH_DEFAULT_ONLY)
    } catch (e: Exception) {
        Timber.w(e, "Failed to resolve the intent")
        return
    }
    if (resolved.isEmpty()) return
    // a common intent resolves to dozens of activities, too many to sit open by default
    section(R.string.analyzer_section_handlers, collapsible = true)
    for (info in resolved) {
        val activityInfo = info.activityInfo ?: continue
        val label = runCatching { info.loadLabel(packageManager).toString() }
            .getOrNull()
            ?.takeIf { it.isNotBlank() }
            ?: activityInfo.packageName
        add(
            AnalyzerItem.Field(
                label,
                ComponentName(activityInfo.packageName, activityInfo.name)
                    .flattenToShortString(),
            ),
        )
    }
}

