enum class OnboardingStep {
    INSTALL_SHIZUKU,
    GRANT_PERMISSION,
}

enum class StepStatus {
    LOCKED,
    ACTIVE,
    COMPLETE,
}

data class ShizukuOnboardingState(
    val shizukuInstalled: Boolean = false,
    val shizukuRunning: Boolean = false,
    val shizukuPermissionGranted: Boolean = false,
    val writeSettingsGranted: Boolean = false,
) {

    private val step1Complete: Boolean get() = shizukuRunning
    private val step2Complete: Boolean get() = step1Complete && shizukuPermissionGranted

    /** True once both visible steps are done (the write-settings grant may still be in flight). */
    val isShizukuReady: Boolean get() = step2Complete

    /** True once Shizuku is set up and the WRITE_SECURE_SETTINGS grant has gone through. */
    val isComplete: Boolean get() = step2Complete && writeSettingsGranted

    val currentStep: OnboardingStep
        get() = if (!step1Complete) OnboardingStep.INSTALL_SHIZUKU else OnboardingStep.GRANT_PERMISSION

    fun statusOf(step: OnboardingStep): StepStatus {
        val complete = when (step) {
            OnboardingStep.INSTALL_SHIZUKU -> step1Complete
            OnboardingStep.GRANT_PERMISSION -> step2Complete
        }
        return when {
            complete -> StepStatus.COMPLETE
            step == currentStep -> StepStatus.ACTIVE
            else -> StepStatus.LOCKED
        }
    }
}

fun refresh() {
    _state.value = readState()
    autoGrantWriteSettingsIfReady()
}

private fun autoGrantWriteSettingsIfReady() {
    val state = _state.value
    if (!state.isShizukuReady || state.writeSettingsGranted || autoGranting) return
    autoGranting = true
    viewModelScope.launch {
        val granted = checker.grantWriteSecureSettings()
        autoGranting = false
        if (granted) {
            // Trust the grant even if checkSelfPermission has not refreshed its cache yet.
            _state.value = _state.value.copy(writeSettingsGranted = true)
        }
        // On failure the state is left as-is; the next refresh() retries.
    }
}

interface ShizukuSetupChecker {

    fun isShizukuInstalled(): Boolean
    fun isShizukuRunning(): Boolean
    fun isShizukuPermissionGranted(): Boolean
    fun isWriteSecureSettingsGranted(): Boolean

    /** Shows the Shizuku authorization prompt; [onResult] is invoked on the main thread. */
    fun requestShizukuPermission(onResult: (granted: Boolean) -> Unit)

    /** Grants WRITE_SECURE_SETTINGS to this app via Shizuku (`pm grant`). Returns success. */
    suspend fun grantWriteSecureSettings(): Boolean
}

