fun getResponse(query: String): String {
    verifyHandle()
    usedJinjaTemplate = startCompletion(nativePtr, query)
    var piece = completionLoop(nativePtr)
    var response = ""
    while (piece != "[EOG]") {
        response += piece
        piece = completionLoop(nativePtr)
    }
    stopCompletion(nativePtr)
    return response
}

