@Serializable
sealed interface Route {

  /**
   * The menu home screen with demo scenario selection.
   */
  @Serializable
  data object MenuHome : Route

  /**
   * The grid list screen showing Disney images in a 2-column grid with blur.
   */
  @Serializable
  data object GridList : Route

  /**
   * The radius selection list screen with Disney thumbnails.
   */
  @Serializable
  data object RadiusItems : Route

  /**
   * The blur detail screen for a specific radius with animated blur effect.
   *
   * @param radius The blur radius to demonstrate.
   */
  @Serializable
  data class RadiusDetail(val radius: Int) : Route

  /**
   * The grid screen with a blurred app bar overlay.
   */
  @Serializable
  data object BlurAppBarGrid : Route

  /**
   * The interactive slider screen for real-time blur radius adjustment.
   */
  @Serializable
  data object InteractiveSlider : Route

  /**
   * The progressive blur demo screen showcasing different progressive blur types.
   */
  @Serializable
  data object ProgressiveBlur : Route

  /**
   * The liquid glass demo screen showcasing the interactive glass lens effect.
   */
  @Serializable
  data object LiquidGlass : Route

  /**
   * Reproduction of issue #112: backdrop blur (`Modifier.cloudy(sky)`) on a bottom navigation
   * bar over a scrolling list, with `Modifier.sky` on the outer container.
   */
  @Serializable
  data object Issue112BottomNav : Route

  /**
   * The gyro lighting test screen — isolates the tilt-driven specular highlight.
   */
  @Serializable
  data object GyroLight : Route

  /**
   * The transform lighting test screen — the target's own 3D rotation drives the specular
   * highlight (deterministic, sensor-free; runs on Desktop and Web).
   */
  @Serializable
  data object TransformLight : Route

  /**
   * The blur lighting test screen — a moving liquid-glass specular pool rides the blurred
   * backdrop of a cloudy(sky=…) surface (deterministic, sensor-free).
   */
  @Serializable
  data object BlurLight : Route

  /**
   * The open shader-effect test screen — applies a shader pipeline from [com.skydoves.cloudy.MirageShaders]
   * to a poster with a single `Modifier.mirage { }` block and toggles between the specular / chromatic
   * looks.
   */
  @Serializable
  data object Mirage : Route

  /**
   * The backdrop mirage test screen — a card grades the `Sky` backdrop behind it via
   * `Modifier.mirage(sky = …) { filter(…) }`, the mirage counterpart of `Modifier.cloudy(sky)`.
   */
  @Serializable
  data object MirageSky : Route
}

