private fun gradientBitmap(w: Int, h: Int): Bitmap {
  val pixels = IntArray(w * h)
  var i = 0
  for (y in 0 until h) {
    for (x in 0 until w) {
      val r = (x * 255) / w
      val g = (y * 255) / h
      val b = ((x + y) * 255) / (w + h)
      pixels[i++] = Color.rgb(r, g, b)
    }
  }
  return Bitmap.createBitmap(pixels, w, h, Bitmap.Config.ARGB_8888)
}

