private fun gradientContent(w: Int, h: Int): Bitmap {
  val pixels = IntArray(w * h)
  var i = 0
  for (y in 0 until h) {
    for (x in 0 until w) {
      val r = x * 255 / (w - 1)
      val g = y * 255 / (h - 1)
      pixels[i++] = Color.argb(255, r, g, 255 - r)
    }
  }
  return Bitmap.createBitmap(pixels, w, h, Bitmap.Config.ARGB_8888)
}

@OptIn(ExperimentalMirage::class)
private fun bindSchemaDefaults(sink: UniformSink, compiled: CompiledProgram) {
  for (entry in compiled.schema.entries) {
    when (val d = entry.default) {
      is ComposeColor -> sink.color(entry.name, d)
      is Float -> sink.float(entry.name, d)
      is Offset -> sink.float2(entry.name, d.x, d.y)
      is Size -> sink.float2(entry.name, d.width, d.height)
      is FloatArray -> sink.floatArray(entry.name, d)
      is Int -> sink.int(entry.name, d)
      else -> {} // textures / null: unused by these optics
    }
  }
}

private fun frameLens(sink: UniformSink, w: Int, h: Int) {
  sink.float2("lensCenter", w / 2f, h / 2f)
  sink.float2("lensSize", w.toFloat(), h.toFloat())
  sink.float("cornerRadius", 0f)
}

private fun assertSurvivesFrames(samplingNode: @Composable (Sky) -> Unit) {
  composeTestRule.setContent {
    val sky = rememberSky()
    var moved by remember { mutableStateOf(false) }
    // Drive a real position change so the backdrop is re-captured over multiple frames (the recorder
    // only re-records when its draw re-runs; moving a descendant repaints the sky subtree).
    val dx by animateDpAsState(if (moved) 24.dp else 0.dp, label = "offset")
    // Kick the animation off the very first frame.
    androidx.compose.runtime.LaunchedEffect(Unit) { moved = true }

    Box(
      modifier = Modifier
        .testTag("root")
        .size(240.dp)
        .sky(sky),
      contentAlignment = Alignment.Center,
    ) {
      Box(
        modifier = Modifier
          .size(240.dp)
          .background(Brush.verticalGradient(listOf(Color(0xFF222244), Color(0xFFEEAA33)))),
      )
      Box(modifier = Modifier.offset(x = dx)) {
        samplingNode(sky)
      }
    }
  }

  // The default clock auto-advances, so waitForIdle pumps every animation frame — each of which
  // re-records the backdrop. A cyclic RenderNode graph would overflow the RenderThread stack during
  // one of those prepareTree passes; reaching the assertion means the guard held.
  composeTestRule.waitForIdle()

  composeTestRule.onNodeWithTag("root").assertExists()
}

