@Composable
private fun rememberReduceMotionState(context: Context): MutableState<Boolean> {
  val state = remember { mutableStateOf(isReduceMotionEnabled(context)) }
  DisposableEffect(context) {
    val resolver = context.contentResolver
    val uri = Settings.Global.getUriFor(Settings.Global.ANIMATOR_DURATION_SCALE)
    val observer = object : ContentObserver(Handler(Looper.getMainLooper())) {
      override fun onChange(selfChange: Boolean) {
        state.value = isReduceMotionEnabled(context)
      }
    }
    resolver.registerContentObserver(uri, false, observer)
    onDispose { resolver.unregisterContentObserver(observer) }
  }
  return state
}

private fun isReduceMotionEnabled(context: Context): Boolean = Settings.Global.getFloat(
  context.contentResolver,
  Settings.Global.ANIMATOR_DURATION_SCALE,
  1f,
) == 0f

internal interface SensorRegistrar {
  /** True when a usable motion sensor exists. When false the provider stays frozen at base. */
  val hasSensor: Boolean

  /** Registers [listener] to receive events on the sensor thread. No-op when [hasSensor] is false. */
  fun register(listener: SensorEventListener)

  /** Unregisters [listener]. Idempotent. */
  fun unregister(listener: SensorEventListener)

  /** Tears down the sensor thread (safe drain). Called once from [TiltLightProvider.shutdown]. */
  fun quit()
}

private class RealSensorRegistrar(private val sensorManager: SensorManager, hz: Int) :
  SensorRegistrar {
  private val periodUs = 1_000_000 / hz // sensor rate hint (not honored exactly; we re-throttle)

  // Pick ONE sensor for the whole lifetime so there is no scale jump from runtime switching.
  private val sensor: Sensor? =
    sensorManager.getDefaultSensor(Sensor.TYPE_GRAVITY)
      ?: sensorManager.getDefaultSensor(Sensor.TYPE_GAME_ROTATION_VECTOR)
      ?: sensorManager.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR)
      ?: sensorManager.getDefaultSensor(Sensor.TYPE_ACCELEROMETER)

  private val thread = HandlerThread("cloudy-tilt").apply { start() }
  private val sensorHandler = Handler(thread.looper)

  override val hasSensor: Boolean get() = sensor != null

  override fun register(listener: SensorEventListener) {
    val s = sensor ?: return
    sensorManager.registerListener(listener, s, periodUs, sensorHandler)
  }

  override fun unregister(listener: SensorEventListener) {
    sensorManager.unregisterListener(listener)
  }

  override fun quit() {
    thread.quitSafely()
  }
}

internal class TiltLightProvider(
  private val registrar: SensorRegistrar,
  private val currentRotation: () -> Int,
  private val base: Offset,
  private val tiltGain: Float,
  hz: Int,
  private val mainHandler: Handler,
  private val onLight: (Offset) -> Unit,
) : SensorEventListener {

  private val minEmitNs = 1_000_000_000L / hz
  private val alpha = 0.2f
  private val epsilon = 0.003f // ~0.17° on a unit vector, below sensor noise floor

  // Confined to the main thread.
  private var started = false

  // Display rotation cached on the main thread (Display access is a main-thread contract); read on
  // the sensor thread as a plain @Volatile int. Refreshed in start().
  @Volatile
  private var displayRotation = Surface.ROTATION_0

  // Confined to the sensor HandlerThread (touched only in onSensorChanged).
  private var smooth = base
  private var lastEmitNs = 0L
  private var lastSent = base
  private val rotM = FloatArray(9)
  private val gFilt = FloatArray(3)

  @Volatile
  private var alive = true

  // Guards against a post queued before stop() running after it and overwriting the frozen base.
  // @Volatile: written on main (start/stop), read on the sensor thread and main.
  @Volatile
  private var generation = 0

  fun start() {
    if (!registrar.hasSensor) return // no sensor → stay frozen at base
    if (started) return
    started = true
    generation++ // invalidate any in-flight post from a prior registration
    // Cache display rotation on the main thread; the sensor thread reads the @Volatile copy.
    displayRotation = currentRotation()
    registrar.register(this)
  }

  fun stop() {
    if (!started) return
    started = false
    generation++ // invalidate any in-flight mainHandler posts (stale emissions)
    registrar.unregister(this)
  }

  fun shutdown() {
    if (!alive) return // idempotent: quit the sensor thread exactly once
    stop()
    alive = false
    registrar.quit()
  }

  override fun onSensorChanged(event: SensorEvent) {
    if (!alive) return
    val raw: Offset = when (event.sensor.type) {
      Sensor.TYPE_GRAVITY -> {
        val (gx, gy) = remapGravityToScreen(event.values[0], event.values[1])
        gravityToLight(gx, gy, base, tiltGain)
      }

      Sensor.TYPE_GAME_ROTATION_VECTOR,
      Sensor.TYPE_ROTATION_VECTOR,
      -> {
        // Gravity direction ≈ negated 3rd row of the world→device rotation matrix.
        SensorManager.getRotationMatrixFromVector(rotM, event.values)
        val (gx, gy) = remapGravityToScreen(-rotM[2] * 9.81f, -rotM[5] * 9.81f)
        gravityToLight(gx, gy, base, tiltGain)
      }

      Sensor.TYPE_ACCELEROMETER -> {
        // Low-pass to extract gravity from raw acceleration.
        gFilt[0] += alpha * (event.values[0] - gFilt[0])
        gFilt[1] += alpha * (event.values[1] - gFilt[1])
        val (gx, gy) = remapGravityToScreen(gFilt[0], gFilt[1])
        gravityToLight(gx, gy, base, tiltGain)
      }

      else -> return
    }

    smooth = emaStep(smooth, raw, alpha)
    val now = System.nanoTime()
    if (now - lastEmitNs < minEmitNs) return // 30 Hz emit throttle
    val outVal = normalizeOr(smooth, base)
    if ((outVal - lastSent).getDistance() < epsilon) return // ε-gate
    smooth = outVal // snap EMA onto the emitted unit vector so a still phone truly stops emitting
    lastEmitNs = now
    lastSent = outVal
    val g = generation // the post drops itself if start()/stop() bumped it before it ran
    mainHandler.post { if (alive && started && g == generation) onLight(outVal) }
  }

  override fun onAccuracyChanged(sensor: Sensor?, accuracy: Int) = Unit

  /**
   * Rotates in-plane gravity (device axes) into screen-space, accounting for display rotation.
   * Reads the [displayRotation] cached on the main thread (never touches Display from this sensor
   * thread).
   */
  private fun remapGravityToScreen(gx: Float, gy: Float): Pair<Float, Float> =
    when (displayRotation) {
      Surface.ROTATION_90 -> -gy to gx
      Surface.ROTATION_180 -> -gx to -gy
      Surface.ROTATION_270 -> gy to -gx
      else -> gx to gy // ROTATION_0
    }
}

private fun remapGravityToScreen(gx: Float, gy: Float): Pair<Float, Float> =
  when (displayRotation) {
    Surface.ROTATION_90 -> -gy to gx
    Surface.ROTATION_180 -> -gx to -gy
    Surface.ROTATION_270 -> gy to -gx
    else -> gx to gy // ROTATION_0
  }

@Composable
private fun Modifier.liquidGlassImpl(
  lensCenter: Offset,
  lensSize: Size,
  cornerRadius: Float,
  refraction: Float,
  curve: Float,
  dispersion: Float,
  saturation: Float,
  contrast: Float,
  tint: Color,
  edge: Float,
  light: LiquidGlassLight,
  tuning: GlowTuning,
  enabled: Boolean,
): Modifier {
  require(lensSize.width > 0f) { "lensSize.width must be > 0, but was ${lensSize.width}" }
  require(lensSize.height > 0f) { "lensSize.height must be > 0, but was ${lensSize.height}" }
  require(cornerRadius >= 0f) { "cornerRadius must be >= 0, but was $cornerRadius" }
  require(refraction >= 0f) { "refraction must be >= 0, but was $refraction" }
  require(curve >= 0f) { "curve must be >= 0, but was $curve" }
  require(dispersion >= 0f) { "dispersion must be >= 0, but was $dispersion" }
  require(saturation >= 0f) { "saturation must be >= 0, but was $saturation" }
  require(contrast >= 0f) { "contrast must be >= 0, but was $contrast" }
  require(edge >= 0f) { "edge must be >= 0, but was $edge" }

  if (!enabled) {
    return this
  }

  if (LocalInspectionMode.current) {
    return this
  }

  // RuntimeShader requires API 33+.
  return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
    liquidGlassApi33(
      lensCenter = lensCenter,
      lensSize = lensSize,
      cornerRadius = cornerRadius,
      refraction = refraction,
      curve = curve,
      dispersion = dispersion,
      saturation = saturation,
      contrast = contrast,
      tint = tint,
      edge = edge,
      light = light,
      tuning = tuning,
    )
  } else {
    // Fallback (< API 33): no shader, so light/glow tuning is not forwarded (no specular uniforms).
    liquidGlassFallback(
      lensCenter = lensCenter,
      lensSize = lensSize,
      cornerRadius = cornerRadius,
      saturation = saturation,
      contrast = contrast,
      tint = tint,
      edge = edge,
    )
  }
}

@Composable
private fun Modifier.liquidGlassFallback(
  lensCenter: Offset,
  lensSize: Size,
  cornerRadius: Float,
  saturation: Float,
  contrast: Float,
  tint: Color,
  edge: Float,
): Modifier = this.drawWithContent {
  drawContent()

  val halfWidth = lensSize.width / 2f
  val halfHeight = lensSize.height / 2f
  val lensLeft = lensCenter.x - halfWidth
  val lensTop = lensCenter.y - halfHeight
  val clampedCornerRadius = cornerRadius.coerceAtMost(minOf(halfWidth, halfHeight))

  val lensPath = Path().apply {
    addRoundRect(
      RoundRect(
        left = lensLeft,
        top = lensTop,
        right = lensLeft + lensSize.width,
        bottom = lensTop + lensSize.height,
        cornerRadius = CornerRadius(clampedCornerRadius, clampedCornerRadius),
      ),
    )
  }

  if (saturation != 1f || contrast != 1f) {
    clipPath(lensPath) {
      // Approximation only: without a shader we can't re-render content through a color filter, so
      // simulate it with an overlay. Absolute deviation from 1.0 handles over/under in both cases.
      val saturationDelta = kotlin.math.abs(1f - saturation).coerceIn(0f, 1f)
      val contrastDelta = kotlin.math.abs(1f - contrast).coerceIn(0f, 1f)
      val overlayAlpha = 0.3f * (saturationDelta + contrastDelta)
      if (overlayAlpha > 0f) {
        drawRect(
          color = Color.Gray.copy(alpha = overlayAlpha.coerceIn(0f, 0.5f)),
          topLeft = Offset(lensLeft, lensTop),
          size = lensSize,
        )
      }
    }
  }

  if (tint != Color.Transparent && tint.alpha > 0f) {
    clipPath(lensPath) {
      drawRect(
        color = tint,
        topLeft = Offset(lensLeft, lensTop),
        size = lensSize,
      )
    }
  }

  if (edge > 0f) {
    val strokeWidth = edge * 20f // scale edge value to a reasonable stroke width
    val edgeColor = Color.White.copy(alpha = (edge * 0.5f).coerceIn(0f, 0.8f))

    drawPath(
      path = lensPath,
      color = edgeColor,
      style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeWidth),
    )
  }
}

val saturationDelta = kotlin.math.abs(1f - saturation).coerceIn(0f, 1f)
val contrastDelta = kotlin.math.abs(1f - contrast).coerceIn(0f, 1f)
val overlayAlpha = 0.3f * (saturationDelta + contrastDelta)
if (overlayAlpha > 0f) {
  drawRect(
    color = Color.Gray.copy(alpha = overlayAlpha.coerceIn(0f, 0.5f)),
    topLeft = Offset(lensLeft, lensTop),
    size = lensSize,
  )
}

@Immutable
public actual class PlatformBitmap(
  /**
   * The underlying Android bitmap.
   */
  public val bitmap: Bitmap,
) {

  public actual val width: Int
    get() = bitmap.width

  public actual val height: Int
    get() = bitmap.height

  public actual val isRecyclable: Boolean
    get() = !bitmap.isRecycled && bitmap.isMutable
}

public actual fun PlatformBitmap.createCompatible(): PlatformBitmap = PlatformBitmap(
  Bitmap.createBitmap(width, height, bitmap.config ?: Bitmap.Config.ARGB_8888),
)

public actual fun PlatformBitmap.dispose() {
  if (!bitmap.isRecycled) {
    bitmap.recycle()
  }
}

fun ContentDrawScope.draw(
  node: EffectNode,
  layer: GraphicsLayer,
  radius: Int,
  offset: Offset,
  contentVersion: Long,
  progressive: CloudyProgressive,
) {
  val width = size.width.toInt()
  val height = size.height.toInt()
  if (width <= 0 || height <= 0) return

  // Refresh the snapshot when the backdrop content changed (or on the first draw). On the GPU tier
  // (always API 31+, so GraphicsLayer's snapshot impl is the synchronous Picture-based LayerSnapshotV28)
  // the capture completes inline this frame — no posted main-loop hop, no version lag, so the blur
  // tracks the content on the same frame the recorder re-captured it. A posted coroutine only ever
  // ran because toImageBitmap() is declared `suspend`; on this path it never actually suspends, and
  // the hop was pure latency that let a fast fling stay a frame (or more) behind the content.
  // captureInline falls back to the coalesced async path only if the snapshot impl unexpectedly
  // suspends (it does not on API 31+).
  val captureScale = captureScaleFor(radius, progressive)
  if (contentVersion != cachedContentVersion || captureScale != snapshotScale) {
    captureInline(node, layer, contentVersion, captureScale)
  }

  val bitmap = snapshot
  if (bitmap == null) {
    // Cold start: no snapshot yet. Draw nothing (transparent); the blur appears when the first
    // capture lands. Matches the CPU path's cold-start behavior.
    lastState = CloudyState.Loading
    return
  }

  // Sample the node region out of the snapshot, clamped so an edge node stays in bounds. The
  // snapshot may be downscaled, so the node's sky-space offset/size are converted to snapshot
  // pixels first; `dstSize` below stays the node size, which scales the region back up. At
  // scale 1 (`snapshotScale == 1`) every term here is the identity of the full-resolution math.
  val s = snapshotScale
  val wantW = (width + s - 1) / s
  val wantH = (height + s - 1) / s
  val srcW = wantW.coerceAtMost(bitmap.width).coerceAtLeast(1)
  val srcH = wantH.coerceAtMost(bitmap.height).coerceAtLeast(1)
  val srcX = (offset.x.toInt() / s).coerceIn(0, (bitmap.width - srcW).coerceAtLeast(0))
  val srcY = (offset.y.toInt() / s).coerceIn(0, (bitmap.height - srcH).coerceAtLeast(0))

  // radius 0 is passthrough (no blur): draw the sampled bitmap region straight into the node. Still a
  // bitmap draw (drawImage), never `drawLayer(sky.backgroundLayer)`, so it stays acyclic / capture-safe.
  if (radius <= 0) {
    drawImage(
      image = bitmap,
      srcOffset = IntOffset(srcX, srcY),
      srcSize = IntSize(srcW, srcH),
      dstOffset = IntOffset.Zero,
      dstSize = IntSize(width, height),
    )
    lastState = CloudyState.Success.Applied
    return
  }

  val blurLayer =
    blurLayer ?: node.graphicsContext().createGraphicsLayer().also { blurLayer = it }
  val blurRadius = radius.toFloat()

  // Progressive (gradient) blur on API 33+ (RuntimeShader): the effect is a RuntimeShader that mixes
  // the SHARP sampled region with its BLURRED self by a per-row fade factor, matching the CPU path's
  // premultiplied-alpha mask (BackgroundBlur.cpp applyProgressiveMask). API 31-32 has no RuntimeShader,
  // so it falls through to the uniform blur below (already warned once by BlurStrategy).
  val effect =
    resolveBlurEffect(bitmap, srcX, srcY, width, height, blurRadius, progressive)

  // Record the sampled bitmap region (pixels, NOT drawLayer) into the blur layer, then apply the blur
  // RenderEffect and draw it. No RenderNode back-edge → acyclic → capture-safe.
  blurLayer.record(IntSize(width, height)) {
    drawImage(
      image = bitmap,
      srcOffset = IntOffset(srcX, srcY),
      srcSize = IntSize(srcW, srcH),
      dstOffset = IntOffset.Zero,
      dstSize = IntSize(width, height),
    )
  }
  if (blurLayer.renderEffect != effect) {
    blurLayer.renderEffect = effect
  }
  drawLayer(blurLayer)
  lastState = CloudyState.Success.Applied
}

blurLayer.record(IntSize(width, height)) {
  drawImage(
    image = bitmap,
    srcOffset = IntOffset(srcX, srcY),
    srcSize = IntSize(srcW, srcH),
    dstOffset = IntOffset.Zero,
    dstSize = IntSize(width, height),
  )
}

private fun resolveBlurEffect(
  bitmap: ImageBitmap,
  srcX: Int,
  srcY: Int,
  width: Int,
  height: Int,
  blurRadius: Float,
  progressive: CloudyProgressive,
): ComposeRenderEffect {
  val useProgressive = progressive != CloudyProgressive.None &&
    Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU
  if (!useProgressive) {
    if (cachedBlurEffect == null || cachedBlurRadius != blurRadius ||
      cachedProgressiveKey != null
    ) {
      cachedBlurEffect = RenderEffect
        .createBlurEffect(blurRadius, blurRadius, Shader.TileMode.CLAMP)
        .asComposeRenderEffect()
      cachedBlurRadius = blurRadius
      cachedProgressiveKey = null
    }
    return cachedBlurEffect!!
  }
  return progressiveEffect(bitmap, srcX, srcY, width, height, blurRadius, progressive)
}

