  TileMode.Repeated -> Shader.TileMode.REPEAT
  TileMode.Mirror -> Shader.TileMode.MIRROR
  TileMode.Decal -> Shader.TileMode.DECAL
  else -> Shader.TileMode.CLAMP
}

enum class ProgressiveDirection(val value: Int) {
  NONE(0),
  TOP_TO_BOTTOM(1),
  BOTTOM_TO_TOP(2),
  EDGES(3),
}

internal fun backgroundBlur(
  srcBitmap: Bitmap,
  dstBitmap: Bitmap,
  cropX: Int,
  cropY: Int,
  radius: Int,
  scale: Float = 0.25f,
  progressiveDirection: ProgressiveDirection = ProgressiveDirection.NONE,
  fadeStart: Float = 0f,
  fadeEnd: Float = 1f,
): Boolean {
  validateBitmap("backgroundBlur", srcBitmap, alphaAllowed = false)
  validateBitmap("backgroundBlur", dstBitmap, alphaAllowed = false)

  require(radius in 1..25) {
    "$EXTERNAL_NAME backgroundBlur. The radius should be between 1 and 25. $radius provided."
  }
  require(scale > 0f && scale <= 1f) {
    "$EXTERNAL_NAME backgroundBlur. The scale should be greater than 0 and at most 1. $scale provided."
  }
  require(fadeStart in 0f..1f && fadeEnd in 0f..1f) {
    "$EXTERNAL_NAME backgroundBlur. fadeStart and fadeEnd must be in the range [0, 1]. " +
      "fadeStart=$fadeStart, fadeEnd=$fadeEnd provided."
  }
  require(cropX >= 0 && cropY >= 0) {
    "$EXTERNAL_NAME backgroundBlur. Crop offsets must be non-negative."
  }
  require(cropX + dstBitmap.width <= srcBitmap.width) {
    "$EXTERNAL_NAME backgroundBlur. Crop region exceeds source width."
  }
  require(cropY + dstBitmap.height <= srcBitmap.height) {
    "$EXTERNAL_NAME backgroundBlur. Crop region exceeds source height."
  }

  return nativeBackgroundBlur(
    nativeHandle,
    srcBitmap,
    dstBitmap,
    cropX,
    cropY,
    radius,
    scale,
    progressiveDirection.value,
    fadeStart,
    fadeEnd,
  )
}

internal fun shutdown() {
  destroyNative(nativeHandle)
  nativeHandle = 0
}

internal data class Range2d(val startX: Int, val endX: Int, val startY: Int, val endY: Int) {
  constructor() : this(0, 0, 0, 0)
}

internal class Rgba3dArray(val values: ByteArray, val sizeX: Int, val sizeY: Int, val sizeZ: Int) {
  init {
    require(values.size >= sizeX * sizeY * sizeZ * 4)
  }

  operator fun get(x: Int, y: Int, z: Int): ByteArray {
    val index = indexOfVector(x, y, z)
    return ByteArray(4) { values[index + it] }
  }

  operator fun set(x: Int, y: Int, z: Int, value: ByteArray) {
    require(value.size == 4)
    val index = indexOfVector(x, y, z)
    for (i in 0..3) {
      values[index + i] = value[i]
    }
  }

  /**
   * Calculates the starting index in the underlying byte array for the RGBA vector at the specified (x, y, z) coordinates.
   *
   * @param x The x-coordinate within the 3D array.
   * @param y The y-coordinate within the 3D array.
   * @param z The z-coordinate within the 3D array.
   * @return The index of the first byte of the RGBA vector at the given coordinates.
   * @throws IllegalArgumentException if any coordinate is out of bounds.
   */
  private fun indexOfVector(x: Int, y: Int, z: Int): Int {
    require(x in 0 until sizeX)
    require(y in 0 until sizeY)
    require(z in 0 until sizeZ)
    return ((z * sizeY + y) * sizeX + x) * 4
  }
}

private fun indexOfVector(x: Int, y: Int, z: Int): Int {
  require(x in 0 until sizeX)
  require(y in 0 until sizeY)
  require(z in 0 until sizeZ)
  return ((z * sizeY + y) * sizeX + x) * 4
}

internal fun validateBitmap(function: String, inputBitmap: Bitmap, alphaAllowed: Boolean = true) {
  if (alphaAllowed) {
    require(
      inputBitmap.config == Bitmap.Config.ARGB_8888 || inputBitmap.config == Bitmap.Config.ALPHA_8,
    ) {
      "$EXTERNAL_NAME. $function supports only ARGB_8888 and ALPHA_8 bitmaps. " +
        "${inputBitmap.config} provided."
    }
  } else {
    require(inputBitmap.config == Bitmap.Config.ARGB_8888) {
      "$EXTERNAL_NAME. $function supports only ARGB_8888. " + "${inputBitmap.config} provided."
    }
  }
  require(inputBitmap.width * vectorSize(inputBitmap) == inputBitmap.rowBytes) {
    "$EXTERNAL_NAME $function. Only bitmaps with rowSize equal to the width * vectorSize are " +
      "currently supported. Provided were rowBytes=${inputBitmap.rowBytes}, " +
      "width={${inputBitmap.width}, and vectorSize=${
        vectorSize(
          inputBitmap,
        )
      }."
  }

internal fun validateRestriction(
  tag: String,
  sizeX: Int,
  sizeY: Int,
  restriction: Range2d? = null,
) {
  if (restriction == null) return
  require(restriction.startX < sizeX && restriction.endX <= sizeX) {
    "$EXTERNAL_NAME $tag. sizeX should be greater than restriction.startX and greater " +
      "or equal to restriction.endX. $sizeX, ${restriction.startX}, " +
      "and ${restriction.endX} were provided respectively."
  }
  require(restriction.startY < sizeY && restriction.endY <= sizeY) {
    "$EXTERNAL_NAME $tag. sizeY should be greater than restriction.startY and greater " +
      "or equal to restriction.endY. $sizeY, ${restriction.startY}, " +
      "and ${restriction.endY} were provided respectively."
  }
  require(restriction.startX < restriction.endX) {
    "$EXTERNAL_NAME $tag. Restriction startX should be less than endX. " +
      "${restriction.startX} and ${restriction.endX} were provided respectively."
  }
  require(restriction.startY < restriction.endY) {
    "$EXTERNAL_NAME $tag. Restriction startY should be less than endY. " +
      "${restriction.startY} and ${restriction.endY} were provided respectively."
  }
}

internal fun vectorSize(bitmap: Bitmap): Int = when (bitmap.config) {
  Bitmap.Config.ARGB_8888 -> 4

  Bitmap.Config.ALPHA_8 -> 1

  else -> throw IllegalArgumentException(
    "$EXTERNAL_NAME. Only ARGB_8888 and ALPHA_8 Bitmap are supported.",
  )
}

internal fun CoroutineScope.iterativeBlur(
  androidBitmap: Bitmap,
  outputBitmap: Bitmap,
  radius: Int,
): Deferred<Bitmap?> = async {
  val iterate = radius / 25
  val remainder = radius % 25

  var bitmap: Bitmap? = if (remainder == 0) {
    androidBitmap
  } else {
    RenderScriptToolkit.blur(
      inputBitmap = androidBitmap,
      outputBitmap = outputBitmap,
      radius = remainder,
    )
  }

  repeat(iterate) {
    bitmap = RenderScriptToolkit.blur(
      inputBitmap = bitmap,
      outputBitmap = outputBitmap,
      radius = 25,
    )
  }

  bitmap
}

internal fun gravityToLight(gx: Float, gy: Float, base: Offset, tiltGain: Float): Offset {
  val b = normalizeOr(base, Offset(-1f, -1f))
  // ~9.81 m/s²; divide so a full 90° tilt maps to ~tiltGain of displacement.
  val nx = (-gx) / 9.81f
  val ny = (-gy) / 9.81f
  return Offset(b.x + tiltGain * nx, b.y + tiltGain * ny)
}

internal fun normalizeOr(o: Offset, fallback: Offset): Offset {
  val len = sqrt(o.x * o.x + o.y * o.y)
  return if (len < 1e-4f) fallback else Offset(o.x / len, o.y / len)
}

public object LiquidGlassDefaults {
  /** Default lens size in pixels. */
  public val LENS_SIZE: Size = Size(350f, 350f)

  /** Default corner radius for the lens shape. */
  public const val CORNER_RADIUS: Float = 50f

  /** Default refraction strength. Controls how much the background distorts. */
  public const val REFRACTION: Float = 0.25f

  /** Default curve strength. Controls how strongly the lens curves at center vs edges. */
  public const val CURVE: Float = 0.25f

  /** Default dispersion (chromatic aberration) strength. */
  public const val DISPERSION: Float = 0.0f

  /** Default saturation. 1.0 = normal, <1.0 = desaturated, >1.0 = oversaturated. */
  public const val SATURATION: Float = 1.0f

  /** Default contrast. 1.0 = normal, <1.0 = less contrast, >1.0 = more contrast. */
  public const val CONTRAST: Float = 1.0f

  /** Default tint color (transparent = no tint). */
  public val TINT: Color = Color.Transparent

  /** Default edge lighting width. 0.0 = no edge, higher = wider edge lighting. */
  public const val EDGE: Float = 0.2f

  /**
   * Default specular light direction (screen-space, y-down). Unnormalized; the shader applies
   * `normalize(lightDir)`. Reproduces the old fixed light's direction, but the highlight is a new
   * multi-term specular model, so the visuals differ from pre-1.x.
   */
  public val LIGHT_DIR: Offset = Offset(-1f, -1f)

  /**
   * Default fixed light — reuses the pre-motion light direction. Singleton; do not reassign.
   */
  public val Light: LiquidGlassLight = LiquidGlassLight(LIGHT_DIR)

  /**
   * Default specular glint intensity (peak brightness) for the new multi-term specular model.
   * Screen-blended, so it stays `<= 1.0`.
   */
  public const val GLOW_INTENSITY: Float = 0.7f

  /**
   * Default specular glint sharpness (lobe power) for the new multi-term specular model —
   * one tight glint.
   */
  public const val GLOW_SHARPNESS: Float = 10.0f

  /**
   * Default glow for the new specular model. Singleton; do not reassign.
   */
  public val Glow: LiquidGlassGlow = LiquidGlassGlow(GLOW_INTENSITY, GLOW_SHARPNESS)

  /**
   * A glow that disables the specular glint (zero intensity). Singleton; do not reassign.
   * Sharpness is a harmless `1.0` since the highlight is scaled to zero regardless.
   */
  public val NoGlow: LiquidGlassGlow = LiquidGlassGlow(0f, 1f)

  /** Minimum Android API level required for the full liquid glass effect. */
  public const val MIN_ANDROID_API_FULL: Int = 33

  /** Minimum Android API level for fallback support. */
  public const val MIN_ANDROID_API_FALLBACK: Int = 23
}

float boxRoundedSDF(float2 p, float2 halfDim, float r) {
    float2 d = abs(p) - halfDim + float2(r);
    float exterior = length(max(d, 0.0));
    float interior = min(max(d.x, d.y), 0.0);
    return exterior + interior - r;
}

float2 lensNormalDirection(float2 p, float2 halfDim, float r) {
    float2 d = abs(p) - halfDim + float2(r);
    float2 s = float2(p.x >= 0.0 ? 1.0 : -1.0, p.y >= 0.0 ? 1.0 : -1.0);

    if (max(d.x, d.y) > 0.0) {
        return s * normalize(max(d, 0.0));
    }
    return d.x > d.y ? float2(s.x, 0.0) : float2(0.0, s.y);
}

float toBrightness(half3 c) {
    return dot(c, half3(0.2126, 0.7152, 0.0722));
}

half3 processColor(half3 src, float vibrancy, float intensity, float4 overlay) {
    float mono = toBrightness(src);
    half3 vibrant = half3(clamp(mix(half3(mono), src, vibrancy), 0.0, 1.0));
    half3 adjusted = half3(clamp((vibrant - 0.5) * intensity + 0.5, 0.0, 1.0));
    return mix(adjusted, half3(overlay.rgb), overlay.a);
}

@ExperimentalMirage
public sealed interface MirageClock {
  /**
   * Default. Spins a frame loop only if some stage's compiled kernel references `mirageTime`
   * (statically detected by the compiler via [CompiledProgram.usesTime]
   * [com.skydoves.cloudy.internal.CompiledProgram]). The value fed to the shader is seconds since the
   * node attached, wrapped at 3600s so a long-running session never grows the argument large enough
   * to decay float32 `sin()` precision.
   *
   * RequiresOptIn does not propagate to nested members, so each carries the marker explicitly to stay
   * out of the stable ABI dumps.
   */
  @ExperimentalMirage
  public data object Auto : MirageClock

  /** Freezes time at whatever value the clock last held; no frame loop runs. */
  @ExperimentalMirage
  public data object Paused : MirageClock

  /**
   * Supplies a constant `mirageTime` and runs no frame loop, so the pipeline is fully deterministic —
   * the intended clock for screenshot tests of animated shaders.
   */
  @ExperimentalMirage
  public data class Fixed(val seconds: Float) : MirageClock
}

@ExperimentalMirage
public interface MirageScope {
  /**
   * Declares a content-transforming stage (a [ColorizeShader] / [CompositeShader] / raw filter). The
   * content pixels feed the shader and its output replaces them. Declared filters apply in the order
   * they are added: `content -> f1 -> f2 -> … -> screen`.
   *
   * @param shader the filter shader to run.
   * @param params optional per-draw uniform block, run against a params instance the node mints once
   *   and reuses (no per-draw allocation). `null` leaves every uniform at its declared default.
   */
  public fun <P : MirageParams> filter(shader: FilterShader<P>, params: (P.() -> Unit)? = null)

  /**
   * Declares an overlay stage (a [GeneratorShader]) drawn over the content without sampling it. Overlay
   * output is composited over all filter results, in declared order, under [blendMode].
   *
   * @param shader the generator shader to run.
   * @param blendMode how the overlay composites over the content. Default: [BlendMode.SrcOver].
   * @param params optional per-draw uniform block; see [filter].
   */
  public fun <P : MirageParams> overlay(
    shader: GeneratorShader<P>,
    blendMode: BlendMode = BlendMode.SrcOver,
    params: (P.() -> Unit)? = null,
  )
}

protected fun uniform3(default: FloatArray): UniformProvider<UVec3> {
  require(default.size == 3) { "uniform3 default must have size 3, was ${default.size}" }
  return registerHandle("float3", default) { UVec3(it, default.copyOf()) }
}

protected fun uniform4(default: FloatArray): UniformProvider<UVec4> {
  require(default.size == 4) { "uniform4 default must have size 4, was ${default.size}" }
  return registerHandle("float4", default) { UVec4(it, default.copyOf()) }
}

protected fun texture(
  default: ImageBitmap? = null,
  tileMode: TileMode = TileMode.Clamp,
): UniformProvider<UTexture> =
  registerHandle("shader", default, isTexture = true) { UTexture(it, default, tileMode) }

@ExperimentalMirage
public class UniformProvider<H : Any> internal constructor(
  private val register: (name: String) -> H,
) : PropertyDelegateProvider<MirageParams, ReadOnlyProperty<MirageParams, H>> {

