internal fun isColorGradeReproducible(compiled: CompiledProgram): Boolean {
  if (compiled.category != ShaderCategory.Colorize) return false
  val e = compiled.schema.entries
  return e.any { it.name == NAME_SHADOW && it.isColor } &&
    e.any { it.name == NAME_HIGHLIGHT && it.isColor } &&
    e.any { it.name == NAME_AMOUNT && !it.isColor }
}

internal fun duotoneMatrix(shadow: Color, highlight: Color, amount: Float): FloatArray {
  val s = floatArrayOf(shadow.red, shadow.green, shadow.blue)
  val h = floatArrayOf(highlight.red, highlight.green, highlight.blue)

  // Row-major 4x5. Start at zero; fill each RGB row, alpha passthrough.
  val m = FloatArray(20)
  for (c in 0 until 3) {
    val delta = amount * (h[c] - s[c]) // coefficient on the luminance dot
    val row = c * 5
    m[row + 0] = delta * LUMA[0]
    m[row + 1] = delta * LUMA[1]
    m[row + 2] = delta * LUMA[2]
    m[row + c] += (1f - amount) // passthrough term on this channel's own input
    // android.graphics.ColorMatrix applies the offset column in 0..255 units.
    m[row + 4] = amount * s[c] * 255f
  }
  // Alpha row: pass alpha through unchanged.
  m[15 + 3] = 1f

  return m
}

fun compile(shader: MirageShader<*>, dialect: Dialect): CompiledProgram {
  val schema = schemaOf(shader.paramsFactory)
  val category = categoryOf(shader)
  val kernel = kernelOf(shader, dialect)

  // Every reference/token scan runs against comment-stripped code, never the raw text: a token that
  // only appears in a comment (e.g. a "// ...fwidth..." note, or a "#" in prose) must not trip lint
  // or force a spurious standard-uniform declaration. The emitted source keeps the original kernel
  // (comments intact) - only the analysis is comment-blind.
  val code = stripComments(kernel)

  // Standard-uniform references are static scans over comment-stripped code in every path (raw
  // included). Each gates two things in lockstep: whether the uniform is declared in the emitted
  // source, and whether the node binds it. Android's RuntimeShader rejects a write to an undeclared
  // uniform, so these must agree exactly. (usesTime additionally drives redraw scheduling, so a false
  // positive here is not just a spurious declaration — it leaves an unwanted per-frame invalidation
  // loop running. A whole-identifier match, not a substring one, is what keeps an unrelated name like
  // `mirageTimeScale` from tripping it.)
  val usesResolution = referencesIdentifier(code, STD_RESOLUTION)
  val usesTime = referencesIdentifier(code, STD_TIME)
  val usesDensity = referencesIdentifier(code, STD_DENSITY)

  // A raw shader owns its full source (uniform declarations included) and is treated as Composite,
  // so it always samples content. Emit it verbatim: no preamble, no generated declarations, no wrap.
  if (isRaw(shader)) {
    return CompiledProgram(
      source = kernel,
      schema = schema,
      usesContent = true,
      usesResolution = usesResolution,
      usesTime = usesTime,
      usesDensity = usesDensity,
      category = ShaderCategory.Composite,
      isRaw = true,
    )
  }

  lintCode(code, category)

  val usesContent = category != ShaderCategory.Generate
  val source = assemble(
    kernel,
    schema,
    category,
    dialect,
    usesResolution,
    usesTime,
    usesDensity,
    usesContent,
  )

  return CompiledProgram(
    source = source,
    schema = schema,
    usesContent = usesContent,
    usesResolution = usesResolution,
    usesTime = usesTime,
    usesDensity = usesDensity,
    category = category,
  )
}

private fun referencesIdentifier(code: String, name: String): Boolean {
  var from = 0
  while (true) {
    val at = code.indexOf(name, from)
    if (at == -1) return false
    val before = at - 1
    val after = at + name.length
    val boundaryBefore = before < 0 || !code[before].isIdentifierChar()
    val boundaryAfter = after >= code.length || !code[after].isIdentifierChar()
    if (boundaryBefore && boundaryAfter) return true
    from = at + 1
  }
}

 * Strips `//` line comments and `/* */` block comments from shader source so the analysis scans
 * only live code. A minimal single-pass state machine - shader source has no string literals, so
 * there is no in-string false comment to guard against.
 */
private fun stripComments(source: String): String = buildString(source.length) {
  var i = 0
  while (i < source.length) {
    val c = source[i]
    val next = if (i + 1 < source.length) source[i + 1] else '\u0000'
    when {
      c == '/' && next == '/' -> {
        i += 2
        while (i < source.length && source[i] != '\n') i++
      }

      c == '/' && next == '*' -> {
        i += 2
        while (i + 1 < source.length && !(source[i] == '*' && source[i + 1] == '/')) i++
        i += 2 // skip the closing */
      }

      else -> {
        append(c)
        i++
      }
    }
  }
}

append(kernel)
if (category == ShaderCategory.Colorize) {
