private fun declarationOf(entry: UniformEntry): String = when {
  entry.isColor -> "layout(color) uniform float4 ${entry.name};"
  entry.isTexture -> "uniform shader ${entry.name};"
  else -> "uniform ${entry.glslType} ${entry.name};"
}

private fun categoryOf(shader: MirageShader<*>): ShaderCategory = when (shader) {
  is FilterShader<*> -> shader.category
  is GeneratorShader<*> -> ShaderCategory.Generate
}

private fun kernelOf(shader: MirageShader<*>, dialect: Dialect): String = when (shader) {
  is FilterShader<*> -> if (dialect == Dialect.Sksl) shader.sksl else shader.agsl
  is GeneratorShader<*> -> if (dialect == Dialect.Sksl) shader.sksl else shader.agsl
}

layer.renderEffect = null
layer.colorFilter = null
when (val application = cached.backend.filterApplication()) {
  // API 33+ AGSL / every skiko target: a content-bound render effect.
  is FilterApplication.Effect -> layer.renderEffect = application.renderEffect

  // API 23-28 ColorGrade: an affine color filter applied in the layer paint (no RenderEffect).
  is FilterApplication.ColorFilter -> layer.colorFilter = application.colorFilter

  // Blit (API 29-32 GLES) never reaches the synchronous chain: the backdrop node routes it to the
  // async GLES runner and self-lit nodes filter it out (rendersInPlace). A Blit here is a wiring
  // bug — it would silently pass through, which is the self-lit no-op gap this guards against.
  is FilterApplication.Blit ->
    error("Blit filter reached the synchronous chain; it must run via MirageGlesBackdrop")
}

fun release(context: GraphicsContext) {
  if (filterLayers.isEmpty()) return
  for (i in filterLayers.indices) {
    filterLayers[i]?.let { context.releaseGraphicsLayer(it) }
    filterLayers[i] = null
  }
  filterLayers = arrayOfNulls(0)
}

fun translate(agslSource: String): String {
  var s = agslSource

  // 1. Drop AGSL's own uniform declarations that GLES expresses differently; we re-emit them.
  //    `uniform shader content;` -> handled by CONTENT_HELPER; strip the AGSL line.
  s = s.replace("uniform shader content;", "")
  //    `layout(color) uniform float4 NAME;` -> `uniform vec4 NAME;`
  s = LAYOUT_COLOR_RE.replace(s) { "uniform vec4 ${it.groupValues[1]};" }
  //    The standard resolution uniform is provided by CONTENT_HELPER's `uResolution`; the kernel
  //    names it `mirageResolution`, so alias rather than double-declare.
  s = s.replace("uniform float2 mirageResolution;", "")

  // 2. content.eval(EXPR) -> sampleContent(EXPR). Do this before the type-token pass so the rename is
  //    on the AGSL spelling.
  s = s.replace("content.eval(", "sampleContent(")

  // 3. Mechanical type-token rewrites: half*/float2..4 -> float/vec*. Word-boundary matched so a
  //    substring like `halfDim` (an identifier) is never touched.
  s = rewriteTypeTokens(s)

  // 4. Entry point: `vec4 main(vec2 xy) { BODY }` (after step 3 half4->vec4, float2->vec2) becomes
  //    `void main(){ vec2 xy = <flipped fragCoord>; BODY-with-returns-as-_fragColor }`.
  s = rewriteEntryPoint(s)

  // 5. Alias mirageResolution to the helper's uResolution (kernels read `mirageResolution`).
  val resolutionAlias =
    if (s.contains("mirageResolution")) "#define mirageResolution uResolution\n" else ""

  return buildString {
    append(HEADER)
    append(CONTENT_HELPER)
    append(resolutionAlias)
    append("out vec4 _fragColor;\n")
    append(s)
  }
}

private fun rewriteTypeTokens(src: String): String {
  var s = src
  for ((from, to) in TYPE_TOKENS) {
    s = Regex("\\b$from\\b").replace(s, to)
  }
  return s
}

  val match = ENTRY_RE.find(src) ?: return src
  val argName = match.groupValues[1]
  val bodyStart = match.range.last + 1 // just after the '{'

  val head = src.substring(0, match.range.first)
  val body = src.substring(bodyStart)

  val newEntry = buildString {
    append("void main() {\n")
    // Y-flip: gl_FragCoord is bottom-left; kernels assume top-left.
    append("  vec2 $argName = vec2(gl_FragCoord.x, uResolution.y - gl_FragCoord.y);\n")
    append(rewriteReturns(body))
  }
  return head + newEntry
}

