private fun contentShaderAt(size: Int): Shader = RuntimeEffect.makeForShader(
  """
  half4 main(float2 xy) {
    float2 uv = xy / float2($size.0, $size.0);
    return half4(half(uv.x), half(uv.y), half(1.0 - uv.x), 1.0);
