@Composable
internal fun isEdgeToEdgeEnabled(): Boolean {
  val view = LocalView.current
  return isEdgeToEdgeEnabled(view)
}

internal fun isEdgeToEdgeEnabled(view: View): Boolean {
  // On Android 15 (API 35) and higher, edge-to-edge is enforced for apps targeting SDK 35+
  if (Build.VERSION.SDK_INT >= 35) {
    return true
  }

  // On earlier versions, check if decorFitsSystemWindows is set to false
  val window = findWindow(view) ?: return false
  return !isDecorFitsSystemWindows(window)
}

private fun findWindow(view: View): Window? {
  return view.context.findWindow()
}

private fun isDecorFitsSystemWindows(window: Window): Boolean {
  return if (Build.VERSION.SDK_INT >= 30) {
    window.decorView.fitsSystemWindows
  } else {
    // On older APIs, check using ViewCompat
    ViewCompat.getFitsSystemWindows(window.decorView)
  }
}

private fun android.content.Context.findWindow(): Window? {
  var context = this
  while (context is android.content.ContextWrapper) {
    if (context is android.app.Activity) {
      return context.window
    }
    context = context.baseContext
  }
  return null
}

@Composable
@InternalFlexibleApi
public actual fun FlexibleBottomSheetPopup(
  onDismissRequest: () -> Unit,
  windowInsets: WindowInsets,
  sheetState: FlexibleSheetState,
  handlesBackGesture: Boolean,
  content: @Composable BoxScope.() -> Unit,
) {
  val view = LocalView.current
  val id = rememberSaveable { UUID.randomUUID() }
  val parentComposition = rememberCompositionContext()
  val currentContent by rememberUpdatedState(content)
  val isEdgeToEdge = isEdgeToEdgeEnabled(view)
  val onBackPressedDispatcherOwner = view.findViewTreeOnBackPressedDispatcherOwner()

  val flexibleBottomSheetWindow = remember {
    FlexibleBottomSheetWindow(
      onDismissRequest = onDismissRequest,
      composeView = view,
      sheetState = sheetState,
      isEdgeToEdge = isEdgeToEdge,
      onBackPressedDispatcherOwner = onBackPressedDispatcherOwner,
      saveId = id,
    ).apply {
      setCustomContent(
        parent = parentComposition,
        content = {
          // Registered on the host activity's dispatcher, for presses that arrive while the
          // activity holds focus rather than this panel. Disabled whenever the sheet would not act,
          // otherwise a hidden sheet keeps intercepting the activity's back press.
          BackHandler(
            enabled = handlesBackGesture &&
              sheetState.currentValue != FlexibleSheetValue.Hidden,
          ) {
            onDismissRequest()
          }
          Box(
            Modifier
              .semantics { this.popup() }
              .then(
                if (sheetState.containSystemBars || isEdgeToEdge) {
                  Modifier
                } else {
                  Modifier.windowInsetsPadding(windowInsets)
                },
              )
              .imePadding(),
          ) {
            currentContent()
          }
        },
      )
    }
  }

  // A hidden sheet is still composed and its window still owns the screen and the input focus, so
  // without this it keeps swallowing touches, key events and IME requests meant for the content
  // behind it (#15). SideEffect rather than LaunchedEffect: the latter is dispatched and would
  // apply the flags a frame late, leaving a re-opening sheet untouchable on its first frame.
  val isSheetInteractive = sheetState.targetValue != FlexibleSheetValue.Hidden ||
    sheetState.currentValue != FlexibleSheetValue.Hidden

  SideEffect {
    flexibleBottomSheetWindow.updateParentComposition(parentComposition)
    flexibleBottomSheetWindow.updateDismissRequest(onDismissRequest)
    flexibleBottomSheetWindow.setSheetInteractive(isSheetInteractive)
    flexibleBottomSheetWindow.setBackGestureHandled(handlesBackGesture)
  }

  DisposableEffect(flexibleBottomSheetWindow) {
    flexibleBottomSheetWindow.show()
    onDispose {
      flexibleBottomSheetWindow.disposeComposition()
      flexibleBottomSheetWindow.dismiss()
    }
  }
}

BackHandler(
  enabled = handlesBackGesture &&
    sheetState.currentValue != FlexibleSheetValue.Hidden,
) {
  onDismissRequest()
}

fun updateDismissRequest(onDismissRequest: () -> Unit) {
  this.onDismissRequest = onDismissRequest
}

fun setSheetInteractive(interactive: Boolean) {
  if (isSheetInteractive == interactive) return
  isSheetInteractive = interactive

  // Before [show] the params it builds pick the flag up anyway. Not `isAttachedToWindow`: the
  // view only attaches on the first traversal after `addView`, which can land after this runs,
  // and skipping the update then desyncs the flags permanently.
  if (!isAddedToWindowManager) return

  windowManager.updateViewLayout(this, getWindowParams())
  if (interactive) {
    requestFocus()
  }
}

fun setBackGestureHandled(handled: Boolean) {
  if (handlesBackGesture == handled) return
  handlesBackGesture = handled
  if (!isAddedToWindowManager) return

  syncOnBackInvokedCallback()
}

flags = if (isEdgeToEdge || (sheetState.containSystemBars && !sheetState.isModal)) {
  flags or WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS
}

@Composable
@InternalFlexibleApi
public fun FlexibleSheetContainer(
  onDismissRequest: () -> Unit,
  windowInsets: WindowInsets,
  sheetState: FlexibleSheetState,
  handlesBackGesture: Boolean,
  content: @Composable BoxScope.() -> Unit,
) {
  when (sheetState.sheetHost) {
    FlexibleSheetHost.Window -> FlexibleBottomSheetPopup(
      onDismissRequest = onDismissRequest,
      windowInsets = windowInsets,
      sheetState = sheetState,
      handlesBackGesture = handlesBackGesture,
      content = content,
    )

    FlexibleSheetHost.Inline -> InlineFlexibleSheetContainer(
      onDismissRequest = onDismissRequest,
      windowInsets = windowInsets,
      sheetState = sheetState,
      handlesBackGesture = handlesBackGesture,
      content = content,
    )
  }
}

@Immutable
public data class FlexibleSheetSize(
  public val fullyExpanded: Float = 1.0f,
  public val intermediatelyExpanded: Float = 0.5f,
  public val slightlyExpanded: Float = 0.25f,
) {
  /**
   * Returns true if any of the size values use wrap content mode.
   */
  public val hasWrapContent: Boolean
    get() = fullyExpanded.isWrapContent() ||
      intermediatelyExpanded.isWrapContent() ||
      slightlyExpanded.isWrapContent()

  public companion object {
    /**
     * Special value indicating that the sheet should wrap its content height.
     * When used, the sheet will size itself to fit its content, up to the screen height.
     */
    public const val WrapContent: Float = -1f
  }
}

@InternalFlexibleApi
public fun Float.resolveSheetSize(screenHeight: Float, contentHeight: Float): Float {
  if (!this.isWrapContent()) return this

  // Placeholder until the content is measured, so the anchor still exists. Guarding screenHeight
  // matters as much as contentHeight: the division would otherwise yield NaN, which no downstream
  // comparison catches and which the swipeable would turn into an arbitrary target.
  if (contentHeight <= 0f || screenHeight <= 0f) return 0.01f

  return min(contentHeight, screenHeight) / screenHeight
}

@InternalFlexibleApi
public fun Modifier.removeMinHeightConstraint(): Modifier = this.layout { measurable, constraints ->
  val adjustedConstraints = constraints.copy(minHeight = 0)
  val placeable = measurable.measure(adjustedConstraints)
  layout(placeable.width, placeable.height) {
    placeable.place(0, 0)
  }
}

