public fun requireOffset(): Float = checkNotNull(offset) {
  "The offset was read before being initialized. Did you access the offset in a phase " +
    "before layout, like effects or composition?"
}

/*@FloatRange(from = 0f, to = 1f)*/
public val progress: Float by derivedStateOf {
  val a = anchors[currentValue] ?: 0f
  val b = anchors[targetValue] ?: 0f
  val distance = abs(b - a)
  if (distance > 1e-6f) {
    val progress = (this.requireOffset() - a) / (b - a)
    // If we are very close to 0f or 1f, we round to the closest
    if (progress < 1e-6f) 0f else if (progress > 1 - 1e-6f) 1f else progress
  } else {
    1f
  }
}

internal fun updateAnchors(newAnchors: Map<T, Float>): Boolean {
  val previousAnchorsEmpty = anchors.isEmpty()
  anchors = newAnchors
  val initialValueHasAnchor = if (previousAnchorsEmpty) {
    val initialValue = currentValue
    val initialValueAnchor = anchors[initialValue]
    val initialValueHasAnchor = initialValueAnchor != null
    if (initialValueHasAnchor) trySnapTo(initialValue)
    initialValueHasAnchor
  } else {
    true
  }
  return !initialValueHasAnchor || !previousAnchorsEmpty
}

public suspend fun snapTo(targetValue: T) {
  swipe { snap(targetValue) }
}

public suspend fun animateTo(
  targetValue: T,
  velocity: Float = lastVelocity,
  animSpec: AnimationSpec<Float>,
) {
  if (isInitialized && isAnimationRunning) return

  val targetOffset = anchors[targetValue]
  if (targetOffset != null) {
    try {
      swipe {
        animationTarget = targetValue
        var prev = offset ?: 0f
        animate(prev, targetOffset, velocity, animSpec) { value, velocity ->
          // Our onDrag coerces the value within the bounds, but an animation may
          // overshoot, for example a spring animation or an overshooting interpolator
          // We respect the user's intention and allow the overshoot, but still use
          // DraggableState's drag for its mutex.
          offset = value
          prev = value
          lastVelocity = velocity
        }
        lastVelocity = 0f
      }
    } finally {
      animationTarget = null
      val endOffset = requireOffset()
      val endState = anchors
        .entries
        .firstOrNull { (_, anchorOffset) -> abs(anchorOffset - endOffset) < 0.5f }
        ?.key
      this.currentValue = endState ?: currentValue
    }
  } else {
    currentValue = targetValue
  }
}

public suspend fun settle(velocity: Float) {
  val previousValue = this.currentValue
  val targetValue = computeTarget(
    offset = requireOffset(),
    currentValue = previousValue,
    velocity = velocity,
  )
  if (confirmValueChange(targetValue)) {
    val settlingAnimation = if (previousValue != targetValue) {
      animationSpec
    } else {
      tween()
    }
    animateTo(targetValue, velocity, settlingAnimation)
  } else {
    // If the user vetoed the state change, rollback to the previous state.
    animateTo(previousValue, velocity, animationSpec)
  }
}

public fun dispatchRawDelta(delta: Float): Float {
  val currentDragPosition = offset ?: 0f
  val potentiallyConsumed = currentDragPosition + delta
  val clamped = potentiallyConsumed.coerceIn(minOffset, maxOffset)
  val deltaToConsume = clamped - currentDragPosition
  if (abs(deltaToConsume) >= 0) {
    offset = ((offset ?: 0f) + deltaToConsume).coerceIn(minOffset, maxOffset)
  }
  return deltaToConsume
}

public fun <T : Any> Saver(
  animationSpec: AnimationSpec<Float>,
  confirmValueChange: (T) -> Boolean,
  positionalThreshold: Density.(distance: Float) -> Float,
  velocityThreshold: Dp,
): Saver<SwipeableV2State<T>, T> = Saver(
  save = { it.currentValue }

@Composable
internal fun <T : Any> rememberSwipeableV2State(
  initialValue: T,
  animationSpec: AnimationSpec<Float> = SwipeableV2Defaults.AnimationSpec,
  confirmValueChange: (newValue: T) -> Boolean = { true }

internal fun fixedPositionalThreshold(threshold: Dp): Density.(distance: Float) -> Float = {
  threshold.toPx()
}

internal fun fractionalPositionalThreshold(
  fraction: Float,
): Density.(distance: Float) -> Float = { distance -> distance * fraction }

@Stable
@InternalFlexibleApi
public object SwipeableV2Defaults {
  /**
   * The default animation used by [SwipeableV2State].
   */
  public val AnimationSpec: AnimationSpec<Float> = SpringSpec()

  /**
   * The default velocity threshold (1.8 dp per millisecond) used by [rememberSwipeableV2State].
   */
  public val VelocityThreshold: Dp = 125.dp

  /**
   * The default positional threshold (56 dp) used by [rememberSwipeableV2State]
   */
  public val PositionalThreshold: Density.(totalDistance: Float) -> Float =
    fixedPositionalThreshold(56.dp)

  /**
   * A [AnchorChangeHandler] implementation that attempts to reconcile an in-progress animation
   * by re-targeting it if necessary or finding the closest new anchor.
   * If the previous anchor is not in the new set of anchors, this implementation will snap to the
   * closest anchor.
   *
   * Consider implementing a custom handler for more complex components like sheets.
   * The [animate] and [snap] lambdas hoist the animation and snap logic. Usually these will just
   * delegate to [SwipeableV2State].
   *
   * @param state The [SwipeableV2State] the change handler will read from
   * @param animate A lambda that gets invoked to start an animation to a new target
   * @param snap A lambda that gets invoked to snap to a new target
   */
  internal fun <T> reconcileAnimationOnAnchorChangeHandler(
    state: SwipeableV2State<T>,
    animate: (target: T, velocity: Float) -> Unit,
    snap: (target: T) -> Unit,
  ) = AnchorChangeHandler { previousTarget, previousAnchors, newAnchors ->
    val previousTargetOffset = previousAnchors[previousTarget]
    val newTargetOffset = newAnchors[previousTarget]
    if (previousTargetOffset != newTargetOffset) {
      if (newTargetOffset != null) {
        animate(previousTarget, state.lastVelocity)
      } else {
        snap(newAnchors.closestAnchor(offset = state.requireOffset()))
      }
    }
  }
}

public fun interface AnchorChangeHandler<T> {

  /**
   * Callback that is invoked when the anchors have changed, after the [SwipeableV2State] has been
   * updated with them. Use this hook to re-launch animations or interrupt them if needed.
   *
   * @param previousTargetValue The target value before the anchors were updated
   * @param previousAnchors The previously set anchors
   * @param newAnchors The newly set anchors
   */
  public fun onAnchorsChanged(
    previousTargetValue: T,
    previousAnchors: Map<T, Float>,
    newAnchors: Map<T, Float>,
  )
}

class FlexibleSheetAnchorTest {

  private val screenHeight = 2000f

  private fun nonModalAnchors(
    measuredSheetHeight: Int,
    flexibleSheetSize: FlexibleSheetSize,
    skipIntermediatelyExpanded: Boolean = false,
    skipSlightlyExpanded: Boolean = false,
  ): Map<FlexibleSheetValue, Float?> = FlexibleSheetValue.entries.associateWith { value ->
    calculateFlexibleSheetAnchor(
      value = value,
      isModal = false,
      measuredSheetHeight = measuredSheetHeight,
      sheetFullHeight = screenHeight * flexibleSheetSize.fullyExpanded,
      sheetConstraintHeight = screenHeight,
      screenMaxHeight = screenHeight,
      flexibleSheetSize = flexibleSheetSize,
      contentHeight = 0f,
      skipIntermediatelyExpanded = skipIntermediatelyExpanded,
      skipSlightlyExpanded = skipSlightlyExpanded,
    )
  }

  @Test
  fun `non-modal fully expanded anchor is the top of the sheet travel`() {
    val anchors = nonModalAnchors(
      measuredSheetHeight = 200,
      flexibleSheetSize = FlexibleSheetSize(
        fullyExpanded = 1.0f,
        intermediatelyExpanded = 0.5f,
        slightlyExpanded = 0.1f,
      ),
    )

    assertEquals(0f, anchors[FlexibleSheetValue.FullyExpanded])
  }

  @Test
  fun `non-modal anchors do not move when the sheet container grows on drag`() {
    val size = FlexibleSheetSize(
      fullyExpanded = 1.0f,
      intermediatelyExpanded = 0.5f,
      slightlyExpanded = 0.1f,
    )

    // Idle at the slightly expanded state: the container is only as tall as the visible sheet.
    val whileIdle = nonModalAnchors(measuredSheetHeight = 200, flexibleSheetSize = size)
    // A drag starts and the container grows to the fully expanded height.
    val whileDragging = nonModalAnchors(measuredSheetHeight = 2000, flexibleSheetSize = size)

    // Regression for #68: anchors that change mid-gesture make the anchor change handler re-target
    // the sheet, which is seen as the sheet jumping down and animating back.
    assertEquals(whileIdle, whileDragging)
  }

  @Test
  fun `non-modal fully expanded anchor never collides with the slightly expanded anchor`() {
    val anchors = nonModalAnchors(
      measuredSheetHeight = 200,
      flexibleSheetSize = FlexibleSheetSize(
        fullyExpanded = 1.0f,
        intermediatelyExpanded = 0.5f,
        slightlyExpanded = 0.1f,
      ),
    )

    assertNotEquals(
      anchors[FlexibleSheetValue.FullyExpanded],
      anchors[FlexibleSheetValue.SlightlyExpanded],
    )
  }

  @Test
  fun `non-modal anchors are ordered from fully expanded to hidden`() {
    val anchors = nonModalAnchors(
      measuredSheetHeight = 2000,
      flexibleSheetSize = FlexibleSheetSize(
        fullyExpanded = 1.0f,
        intermediatelyExpanded = 0.5f,
        slightlyExpanded = 0.1f,
      ),
    )

    val fully = anchors.getValue(FlexibleSheetValue.FullyExpanded)!!
    val intermediately = anchors.getValue(FlexibleSheetValue.IntermediatelyExpanded)!!
    val slightly = anchors.getValue(FlexibleSheetValue.SlightlyExpanded)!!
    val hidden = anchors.getValue(FlexibleSheetValue.Hidden)!!

    assertEquals(listOf(0f, 1000f, 1800f, 2000f), listOf(fully, intermediately, slightly, hidden))
  }

  @Test
  fun `non-modal anchors are not published before the first layout pass`() {
    val anchors = nonModalAnchors(
      measuredSheetHeight = 0,
      flexibleSheetSize = FlexibleSheetSize(fullyExpanded = 1.0f),
    )

    assertNull(anchors[FlexibleSheetValue.FullyExpanded])
  }

  @Test
  fun `non-modal skipped states have no anchor`() {
    val anchors = nonModalAnchors(
      measuredSheetHeight = 2000,
      flexibleSheetSize = FlexibleSheetSize(fullyExpanded = 1.0f),
      skipIntermediatelyExpanded = true,
      skipSlightlyExpanded = true,
    )

    assertNull(anchors[FlexibleSheetValue.IntermediatelyExpanded])
    assertNull(anchors[FlexibleSheetValue.SlightlyExpanded])
    assertEquals(0f, anchors[FlexibleSheetValue.FullyExpanded])
  }

  @Test
  fun `non-modal fully expanded anchor is stable for a partially expanded sheet`() {
    val size = FlexibleSheetSize(
      fullyExpanded = 0.5f,
      intermediatelyExpanded = 0.3f,
      slightlyExpanded = 0.1f,
    )

    val whileIdle = nonModalAnchors(measuredSheetHeight = 200, flexibleSheetSize = size)
    val whileDragging = nonModalAnchors(measuredSheetHeight = 1000, flexibleSheetSize = size)

    assertEquals(whileIdle, whileDragging)
    assertEquals(0f, whileIdle[FlexibleSheetValue.FullyExpanded])
    // sheetFullHeight (1000) - slightly expanded height (200)
    assertEquals(800f, whileIdle[FlexibleSheetValue.SlightlyExpanded])
  }

  @Test
  fun `modal anchors are measured from the top of the screen`() {
    val size = FlexibleSheetSize(
      fullyExpanded = 1.0f,
      intermediatelyExpanded = 0.5f,
      slightlyExpanded = 0.1f,
    )
    val anchors = FlexibleSheetValue.entries.associateWith { value ->
      calculateFlexibleSheetAnchor(
        value = value,
        isModal = true,
        measuredSheetHeight = 2000,
        sheetFullHeight = screenHeight,
        sheetConstraintHeight = screenHeight,
        screenMaxHeight = screenHeight,
        flexibleSheetSize = size,
        contentHeight = 0f,
        skipIntermediatelyExpanded = false,
        skipSlightlyExpanded = false,
      )
    }

    assertEquals(0f, anchors[FlexibleSheetValue.FullyExpanded])
    assertEquals(1000f, anchors[FlexibleSheetValue.IntermediatelyExpanded])
    assertEquals(1800f, anchors[FlexibleSheetValue.SlightlyExpanded])
    assertEquals(2000f, anchors[FlexibleSheetValue.Hidden])
  }
}

class ScrimProgressTest {

  private val anchors = mapOf(
