fun sanitize(entries: List<ApkEntry>, ignoredFiles: List<String> = emptyList()): List<AppFile> {
    val buckets = listOf(
        NativeLibAssigningBucket(),
        DexFileBucket(),
        AndroidManifestBucket(),
        BundletoolBucket(),
        ResourcesArscBucket(),
        ResourceBucket(),
        TypeAssigningBucket(),
    )

    // Separate entries into their different sanitization bucket
    entries.filterNot { it.name in ignoredFiles }.forEach { entry ->
        val bucket = buckets.first { it.isApplicable(entry) }
        bucket.add(entry)
    }

    // Empty each bucket and merge the results
    return buckets.flatMap(SanitizationBucket::sanitize)
}

private abstract class SanitizationBucket {
    protected val entries = mutableListOf<ApkEntry>()

    /** Checks if a certain entry belongs to this bucket. */
    abstract fun isApplicable(entry: ApkEntry): Boolean

    /** Sanitizes and returns all gathered entries. */
    abstract fun sanitize(): List<AppFile>

    fun add(entry: ApkEntry) = entries.add(entry)

    protected fun mapNameToResourceType(entry: ApkEntry): ResourceType? {
        val resourceType: ResourceType? = when {
            entry.name.startsWith("/res/drawable") -> ResourceType.DRAWABLE
            entry.name.startsWith("/res/layout") -> ResourceType.LAYOUT
            entry.name.startsWith("/res/raw") -> ResourceType.RAW
            entry.name.startsWith("/res/values") -> ResourceType.VALUES
            entry.name.startsWith("/res/font") -> ResourceType.FONT
            entry.name.startsWith("/res/") -> ResourceType.OTHER
            else -> null
        }
        return resourceType
    }
}

private class AndroidManifestBucket : SanitizationBucket() {
    override fun isApplicable(entry: ApkEntry) = entry.name == "/AndroidManifest.xml"

    override fun sanitize(): List<AppFile> {
        val entry = entries.maxByOrNull(ApkEntry::installSize) ?: return emptyList()
        return listOf(AppFile("/AndroidManifest.xml", FileType.OTHER, entry.downloadSize, entry.installSize))
    }
}

private class BundletoolBucket : SanitizationBucket() {

    override fun isApplicable(entry: ApkEntry): Boolean {
        return entry.name == "/META-INF/MANIFEST.MF" || entry.name.matches(Regex("/res/xml/splits\\d+\\.xml"))
    }

    override fun sanitize() = emptyList<AppFile>()
}

private class ResourcesArscBucket : SanitizationBucket() {
    override fun isApplicable(entry: ApkEntry) = entry.name == "/resources.arsc"

    override fun sanitize(): List<AppFile> {
        if (entries.isEmpty()) return emptyList()

        val downloadSize = entries.sumOf(ApkEntry::downloadSize)
        val installSize = entries.sumOf(ApkEntry::installSize)
        return listOf(AppFile("/resources.arsc", FileType.OTHER, downloadSize, installSize))
    }
}

private inner class ResourceBucket : SanitizationBucket() {
    override fun isApplicable(entry: ApkEntry) = entry.name.startsWith("/res/")
    override fun sanitize() = entries.map(::sanitizeEntry)

    private fun sanitizeEntry(entry: ApkEntry): AppFile {
        val name = resourceNameSanitizer.sanitize(entry.name)
        val resourceType: ResourceType? = mapNameToResourceType(entry)
        return AppFile(name, FileType.RESOURCE, entry.downloadSize, entry.installSize, resourceType = resourceType)
    }
}

private class TypeAssigningBucket : SanitizationBucket() {
    override fun isApplicable(entry: ApkEntry) = true
    override fun sanitize() = entries.map(::sanitizeEntry)

    private fun sanitizeEntry(entry: ApkEntry): AppFile {
        val type = when {
            entry.name.startsWith("/res/") -> FileType.RESOURCE
            entry.name.startsWith("/assets/") -> FileType.ASSET
            entry.name.startsWith("/lib/") -> FileType.NATIVE_LIB
            else -> FileType.OTHER
        }
        val resourceType: ResourceType? = mapNameToResourceType(entry)
        return AppFile(entry.name, type, entry.downloadSize, entry.installSize, resourceType = resourceType)
    }
}

private class NativeLibAssigningBucket : SanitizationBucket() {

    private val metadataRegex = Regex("\\[section.*?\\]")
    override fun isApplicable(entry: ApkEntry) =
        entry is ApkEntry.NativeLibrary && entry.classes.isNotEmpty()

    override fun sanitize(): List<AppFile> {
        return entries.flatMap { entry ->
            sanitizeEntry(entry as ApkEntry.NativeLibrary)
        }
    }

    private fun sanitizeEntry(
        entry: ApkEntry.NativeLibrary,
    ): List<AppFile> {
        val totalClasses = entry.classes.sumOf(ApkEntry::installSize)
        return entry.classes.map { classEntry ->
            val fileName = if (isMetadataFile(classEntry.name)) {
                "${entry.name}/${classEntry.name}"
            } else {
                classEntry.name
            }
            AppFile(
                fileName,
                FileType.NATIVE_FILE,
                classEntry.downloadSize * entry.downloadSize / totalClasses,
                classEntry.installSize * entry.installSize / totalClasses
            )
        }
    }

    private fun isMetadataFile(name: String) = metadataRegex.matches(name)
}

fun attribute(files: List<AppFile>, dependencies: Dependencies): Map<DependencyComponent, List<AppFile>> {
    val components = mutableMapOf<DependencyComponent, MutableList<AppFile>>()
    val sortedDependenciesMap = sortStaticDependenciesMap()
    files.forEach { file ->
        val component = when (file.type) {
            FileType.CLASS -> getComponentForClass(file.name, dependencies)
            FileType.RESOURCE -> getComponentForResource(file.name, dependencies)
            FileType.ASSET -> getComponentForAsset(file.name, dependencies)
            FileType.NATIVE_LIB -> getComponentForNativeLib(file.name, dependencies)
            FileType.NATIVE_FILE -> getComponentFromStaticDependenciesMap(sortedDependenciesMap, file.name)
            FileType.OTHER -> getComponentForFile(file.name, dependencies)
        } ?: getComponentFromStaticDependenciesMap(sortedDependenciesMap, file.name) ?: defaultComponent

        components.getOrPut(component) { ArrayList() }.add(file)
    }
    return components
}

@Suppress("ReturnCount")
private fun getComponentForClass(name: String, dependencies: Dependencies): DependencyComponent? {
    if (dependencies[name]?.size == 1) {
        return dependencies.getValue(name).single()
    }

    // Attribute Dagger factories like the type they produce
    val daggerFactoryName = name.removeSuffix("_Factory")
    if (dependencies[daggerFactoryName]?.size == 1) {
        return dependencies.getValue(daggerFactoryName).single()
    }

    // Attribute Dagger modules like their abstract class/interface
    val daggerModuleName = name.substringBefore("_Provide")
    if (dependencies[daggerModuleName]?.size == 1) {
        return dependencies.getValue(daggerModuleName).single()
    }

    // Try to attribute lambdas based on their package
    if (name.contains(".-\$\$Lambda\$")) {
        val packageName = name.substringBefore(".-\$\$Lambda\$")
        val component = getComponentForPackage(packageName, dependencies)
        if (component != null) {
            return component
        }
    }

    // Attribute external synthetic classes based on their simple class name
    if (name.contains("\$\$ExternalSynthetic")) {
        val simpleClassName = name.substringBefore("\$\$ExternalSynthetic").substringAfterLast('.')
        val candidates = dependencies.filter { it.key.substringAfterLast('.') == simpleClassName }.values.flatten()
        val component = candidates.distinct().singleOrNull()
        if (component != null) {
            return component
        }
    }

    // If everything else fails, try matching based on package name
    val packageName = name.substringBeforeLast('.')
    return getComponentForPackage(packageName, dependencies)
}

val daggerFactoryName = name.removeSuffix("_Factory")
if (dependencies[daggerFactoryName]?.size == 1) {
    return dependencies.getValue(daggerFactoryName).single()
}

val daggerModuleName = name.substringBefore("_Provide")
if (dependencies[daggerModuleName]?.size == 1) {
    return dependencies.getValue(daggerModuleName).single()
}

private fun getComponentForAsset(name: String, dependencies: Dependencies): DependencyComponent? {
    val assetName = name.removePrefix("/assets")
    return dependencies[assetName]?.singleOrNull()
}

private fun getComponentForNativeLib(name: String, dependencies: Dependencies): DependencyComponent? {
    val nativeLibName = name.removePrefix("/lib")
    if (dependencies[nativeLibName]?.size == 1) {
        return dependencies.getValue(nativeLibName).single()
    }

    // Attribute LZMA-compressed files to their original source
    val lzmaName = nativeLibName.replace(".lzma.", ".")
    return dependencies[lzmaName]?.singleOrNull()
}

private fun getComponentForFile(name: String, dependencies: Dependencies): DependencyComponent? {
    return dependencies[name]?.singleOrNull()
}

private fun getComponentForPackage(name: String, dependencies: Dependencies): DependencyComponent? {
    val candidates = dependencies.filter { it.key.substringBeforeLast('.') == name }.values.flatten()
    return candidates.distinct().singleOrNull()
}

private fun parseBloatyOutputToApkEntry(command: String): List<ApkEntry.Default> {
    val rows = mutableListOf<ApkEntry.Default>()

    val outputLines = executeCommandAndGetOutput(command)

    for (line in outputLines) {
        val cols = line.split(",")
        if (cols.size == COLUMN_SIZE) {
            val size = cols.last().toLongOrNull() ?: continue
            val entry = ApkEntry.Default(
                cols.first().substringAfter("../.."),
                size,
                size
            )
            rows.add(entry)
        }
    }
    println("Parsed ${rows.count()} APK entries")
    return rows
}

class DefaultArtifactParser : ArtifactParser<ArtifactResult.DefaultArtifact> {

    override fun parseFile(artifact: ArtifactResult.DefaultArtifact): List<DependencyEntry> {
        val name =
            artifact.file.absolutePath.removePrefix(artifact.resolvedArtifactFile.absolutePath)
        return listOf(DependencyEntry.Default(name, artifact.component))
    }
}

class ClassArtifactParser : ArtifactParser<ArtifactResult.ClassArtifact> {
    override fun parseFile(artifact: ArtifactResult.ClassArtifact): List<DependencyEntry> {
        val name =
            artifact.file.absolutePath.removePrefix(artifact.resolvedArtifactFile.absolutePath)
        return listOf(DependencyEntry.Class(name, artifact.component))
    }
}

class JarArtifactParser : ArtifactParser<ArtifactResult.JarArtifact> {

    override fun parseFile(artifact: ArtifactResult.JarArtifact): List<DependencyEntry> {
        val component = artifact.component
        return JarFile(artifact.file).use { jarFile ->
            jarFile.entries().asSequence().filterNot(JarEntry::isDirectory).map { entry ->
                when {
                    isClassEntry(entry.name) -> DependencyEntry.Class(entry.name, component)
                    else -> DependencyEntry.Default(entry.name, component)
                }
            }.toList()
        }
    }

    private fun isClassEntry(entryName: String): Boolean {
        return entryName.endsWith(".class", ignoreCase = true)
    }
}

@KSerializable
sealed class DependencyEntry: Serializable {
    abstract val name: String
    abstract val component: String

    /** Default dependency entry. If an entry has no special type, it is considered to be a default entry. */
    @KSerializable
    data class Default(
        override val name: String,
        override val component: String,
    ) : DependencyEntry()

    /** Class file dependency entry. */
    @KSerializable
    data class Class(
        override val name: String,
        override val component: String,
    ) : DependencyEntry()

    companion object {
        private const val serialVersionUID = 1L
    }
}

class DependencyParser {

    /** Parses and returns the list of entries contained in all dependencies of the given [project]. */
    fun parse(entries: List<ArtifactResult>): List<DependencyEntry> {
        val result = mutableListOf<DependencyEntry>()

        val jarArtifactParser = JarArtifactParser()
        val defaultArtifactParser = DefaultArtifactParser()
        val classArtifactParser = ClassArtifactParser()
        entries.forEach {
            result += when (it) {
                is ArtifactResult.DefaultArtifact -> {
                    defaultArtifactParser.parseFile(it)
                }
                is ArtifactResult.ClassArtifact -> {
                    classArtifactParser.parseFile(it)
                }
                is ArtifactResult.JarArtifact -> {
                    jarArtifactParser.parseFile(it)
                }
            }
        }
        return result
    }
}

fun parse(entries: List<ArtifactResult>): List<DependencyEntry> {
    val result = mutableListOf<DependencyEntry>()

    val jarArtifactParser = JarArtifactParser()
    val defaultArtifactParser = DefaultArtifactParser()
    val classArtifactParser = ClassArtifactParser()
    entries.forEach {
        result += when (it) {
            is ArtifactResult.DefaultArtifact -> {
                defaultArtifactParser.parseFile(it)
            }
            is ArtifactResult.ClassArtifact -> {
                classArtifactParser.parseFile(it)
            }
            is ArtifactResult.JarArtifact -> {
                jarArtifactParser.parseFile(it)
            }
        }
    }
    return result
}

class DependencySanitizer(private val classNameSanitizer: ClassNameSanitizer) {

    /**
     * Sanitizes a list of dependency entries, to ease further processing. Sanitizing means cleaning up entry names and
     * associating entries with their components.
     *
     * @param entries List of raw entries parsed from dependencies
     * @return Map of file names to a list of all components which include this file
     */
    fun sanitize(entries: List<DependencyEntry>): Map<String, List<DependencyComponent>> {
        val map = mutableMapOf<String, MutableList<DependencyComponent>>()
        entries.map(::sanitizeEntry).forEach { entry ->
            val components = map.getOrPut(entry.name) { ArrayList() }
            val type = getComponentType(entry)
            components += DependencyComponent(entry.component, type)
        }
        return map
    }

    /** Cleans the component name and potentially sanitizes the name for a given [entry]. */
    private fun sanitizeEntry(entry: DependencyEntry): DependencyEntry {
        val component = entry.component.removePrefix("project ")
        return when(entry) {
            is DependencyEntry.Class -> {
                val name = classNameSanitizer.sanitize(entry.name)
                DependencyEntry.Class(name, component)
            }
            is DependencyEntry.Default -> {
                val name = entry.name.replace('\\', '/') // Convert Windows-style paths to UNIX-style paths
                DependencyEntry.Default(name, component)
            }
        }
    }

    private val versionRegex = Regex("^\\d+\\.\\d+\\.\\d.*")

    /**
     * Determines the correct component type for a given [entry].
     * Assuming that all external dependencies do have a version number in the format XX.XX.XX
     * */
    private fun getComponentType(entry: DependencyEntry): ComponentType = when {
        versionRegex.containsMatchIn(entry.component.substringAfterLast(":","")) -> ComponentType.EXTERNAL
        else -> ComponentType.INTERNAL
    }
}

fun sanitize(entries: List<DependencyEntry>): Map<String, List<DependencyComponent>> {
    val map = mutableMapOf<String, MutableList<DependencyComponent>>()
    entries.map(::sanitizeEntry).forEach { entry ->
        val components = map.getOrPut(entry.name) { ArrayList() }
        val type = getComponentType(entry)
        components += DependencyComponent(entry.component, type)
    }
    return map
}

private fun sanitizeEntry(entry: DependencyEntry): DependencyEntry {
    val component = entry.component.removePrefix("project ")
    return when(entry) {
        is DependencyEntry.Class -> {
            val name = classNameSanitizer.sanitize(entry.name)
            DependencyEntry.Class(name, component)
        }
        is DependencyEntry.Default -> {
            val name = entry.name.replace('\\', '/') // Convert Windows-style paths to UNIX-style paths
            DependencyEntry.Default(name, component)
        }
    }
}

private fun getComponentType(entry: DependencyEntry): ComponentType = when {
    versionRegex.containsMatchIn(entry.component.substringAfterLast(":","")) -> ComponentType.EXTERNAL
    else -> ComponentType.INTERNAL
}

