public interface WorkflowTracer {
  public fun beginSection(label: String): Unit

  public fun endSection(): Unit
}

@OptIn(ExperimentalContracts::class)
public inline fun <T> WorkflowTracer?.trace(label: String, block: () -> T): T {
  contract { callsInPlace(block, InvocationKind.EXACTLY_ONCE) }
  return if (this == null) {
    block()
  } else {
    beginSection(label)
    try {
      return block()
    } finally {
      endSection()
    }
  }
}

public inline fun <T> WorkflowTracer?.traceNoFinally(label: String, block: () -> T): T {
  this?.beginSection(label)
  val result = block()
  this?.endSection()
  return result
}

