internal class PickledTreesnapshot(internal val snapshot: TreeSnapshot) : Parcelable {
  override fun describeContents(): Int = 0

  override fun writeToParcel(dest: Parcel, flags: Int) =
    dest.writeByteArray(snapshot.toByteString().toByteArray())

  companion object CREATOR : Parcelable.Creator<PickledTreesnapshot> {
    override fun createFromParcel(parcel: Parcel): PickledTreesnapshot {
      val bytes = parcel.createByteArray()!!.toByteString()
      return PickledTreesnapshot(TreeSnapshot.parse(bytes))
    }

    override fun newArray(size: Int): Array<PickledTreesnapshot?> = arrayOfNulls(size)
  }
}

internal interface TreeSnapshotSaver {
  /**
   * Implemented by the object that is running a workflow session, to give on demand access to the
   * most recent [TreeSnapshot] as required for persistence.
   */
  interface HasTreeSnapshot {
    fun latestSnapshot(): TreeSnapshot?
  }

  /** Consumes and returns the saved [TreeSnapshot], or null if there wasn't one. */
  fun consumeSnapshot(): TreeSnapshot?

  fun registerSource(source: HasTreeSnapshot)

  companion object {
    fun fromSavedStateRegistry(savedStateRegistry: SavedStateRegistry) =
      object : TreeSnapshotSaver {
        override fun consumeSnapshot(): TreeSnapshot? {
          return if (VERSION.SDK_INT >= VERSION_CODES.TIRAMISU) {
            savedStateRegistry
              .consumeRestoredStateForKey(BUNDLE_KEY)
              ?.getParcelable(BUNDLE_KEY, PickledTreesnapshot::class.java)
              ?.snapshot
          } else {
            @Suppress("DEPRECATION")
            savedStateRegistry
              .consumeRestoredStateForKey(BUNDLE_KEY)
              ?.getParcelable<PickledTreesnapshot>(BUNDLE_KEY)
              ?.snapshot
          }
        }

        override fun registerSource(source: HasTreeSnapshot) {
          savedStateRegistry.registerSavedStateProvider(BUNDLE_KEY) {
            Bundle().apply {
              source.latestSnapshot()?.let { putParcelable(BUNDLE_KEY, PickledTreesnapshot(it)) }
            }
          }
        }
      }

    /**
     * Namespace key, used in two places:
     * - names our slot in the [SavedStateRegistry]
     * - and is also the key for the [PickledTreesnapshot] we write to the bundle
     */
    val BUNDLE_KEY = TreeSnapshotSaver::class.java.name
  }
}

interface HasTreeSnapshot {
  fun latestSnapshot(): TreeSnapshot?
}

internal actual class ThreadLocal<T>(private val initialValue: () -> T) :
  NSObject(), NSCopyingProtocol {

  private val threadDictionary
    get() = NSThread.currentThread().threadDictionary

  actual fun get(): T {
    @Suppress("UNCHECKED_CAST")
    return when (val stored = threadDictionary.objectForKey(aKey = this)) {
      null -> initialValue().also(::set)
      is NSNull -> null as T
      else -> stored as T
    }
  }

  actual fun set(value: T) {
    // setObject:forKey: throws NSInvalidArgumentException when passed nil.
    threadDictionary.setObject(value ?: NSNull(), forKey = this)
  }

  /**
   * [Docs](https://developer.apple.com/documentation/foundation/nscopying/copy(with:)) say [zone]
   * is unused.
   */
  @OptIn(ExperimentalForeignApi::class)
  override fun copyWithZone(zone: CPointer<NSZone>?): Any = this
}

