fun wrapDispatcherFrom(context: CoroutineContext): WorkStealingDispatcher {
  // If there's no dispatcher in the context then the coroutines runtime will fall back to
  // Dispatchers.Default anyway.
  val baseDispatcher = context[ContinuationInterceptor] ?: Dispatchers.Default
  return invoke(delegateInterceptor = baseDispatcher)
}

@OptIn(InternalCoroutinesApi::class)
private fun createMatchingDelayability(
  delegateInterceptor: ContinuationInterceptor,
  lock: Lock?,
  queue: LinkedHashSet<DelegateDispatchedContinuation>?,
): WorkStealingDispatcher {
  return if (delegateInterceptor is Delay) {
    DelayableWorkStealingDispatcher(
      delegate = delegateInterceptor,
      delay = delegateInterceptor,
      lock = lock,
      queue = queue,
    )
  } else {
    WorkStealingDispatcher(
      delegateInterceptor = delegateInterceptor,
      lock = lock,
      queue = queue,
    )
  }
}

final override fun limitedParallelism(parallelism: Int, name: String?): CoroutineDispatcher {
  if (delegateInterceptor !is CoroutineDispatcher) {
    throw UnsupportedOperationException(
      "limitedParallelism is not supported for WorkStealingDispatcher with " +
        "non-dispatcher delegate"
    )
  }

  val limitedDelegate = delegateInterceptor.limitedParallelism(parallelism)
  return createMatchingDelayability(
    delegateInterceptor = limitedDelegate,
    lock = lock,
    queue = queue,
  )
}

fun advanceUntilIdle() {
  do {
    val task = nextTask()
    task?.releaseAndRun()
  } while (task != null)
}

private fun nextTask(): DelegateDispatchedContinuation? {
  lock.withLock {
    val iterator = queue.iterator()
    if (iterator.hasNext()) {
      val task = iterator.next()
      iterator.remove()
      return task
    } else {
      return null
    }
  }
}

override fun resumeWith(result: Result<Unit>) {
  // Fastest path: If this continuation has already been ran by advancing, don't even bother
  // locking and checking the queue. Note that even if consumed is false, the task may have been
  // ran already, so we still need to check whether it's in the queue under lock.
  if (consumed) return

  // Fast path: If we're racing with another thread and consumed hasn't been set yet, then check
  // the queue under lock. The queue is the real source of truth.
  val unconsumedForSure = lock.withLock { queue.remove(this) }
  if (unconsumedForSure) {
    releaseAndRun()
  }
}

fun releaseAndRun() {
  // This flag must be set here, since this is the method that is called by advanceUntilIdle.
  consumed = true

  intercepted?.let {
    if (it !== this) {
      delegateInterceptor.releaseInterceptedContinuation(it)
    }
    intercepted = null
  }
  runnable.run()
}

internal class WorkflowChildNode<
  ChildPropsT,
  ChildOutputT,
  ParentPropsT,
  ParentStateT,
  ParentOutputT,
>(
  val workflow: Workflow<*, ChildOutputT, *>,
  private var handler: (ChildOutputT) -> WorkflowAction<ParentPropsT, ParentStateT, ParentOutputT>,
  val workflowNode: WorkflowNode<ChildPropsT, ChildOutputT, *>,
) : InlineListNode<WorkflowChildNode<*, *, *, *, *>> {
  override var nextListNode: WorkflowChildNode<*, *, *, *, *>? = null

  /** The [WorkflowNode]'s [WorkflowNodeId]. */
  val id
    get() = workflowNode.id

  /** Returns true if this child has the same type as [otherWorkflow] and key as [key]. */
  fun matches(
    otherWorkflow: Workflow<*, *, *>,
    key: String,
    workflowTracer: WorkflowTracer?,
  ): Boolean = workflowTracer.trace("matches") { id.matches(otherWorkflow, key) }

  /** Updates the handler function that will be invoked by [acceptChildOutput]. */
  fun <CO, CP, S, O> setHandler(newHandler: (CO) -> WorkflowAction<CP, S, O>) {
    @Suppress("UNCHECKED_CAST")
    handler =
      newHandler as (ChildOutputT) -> WorkflowAction<ParentPropsT, ParentStateT, ParentOutputT>
  }

  /** Wrapper around [WorkflowNode.render] that allows calling it with erased types. */
  fun <R> render(workflow: Workflow<*, *, *>, props: Any?): R {
    @Suppress("UNCHECKED_CAST")
    return workflowNode.render(
      workflow as Workflow<ChildPropsT, ChildOutputT, Nothing>,
      props as ChildPropsT,
    ) as R
  }

  /** Wrapper around [handler] that allows calling it with erased types. */
  @Suppress("UNCHECKED_CAST")
  fun acceptChildOutput(output: Any?): WorkflowAction<ParentPropsT, ParentStateT, ParentOutputT> =
    handler(output as ChildOutputT)
}

fun matches(
  otherWorkflow: Workflow<*, *, *>,
  key: String,
  workflowTracer: WorkflowTracer?,
): Boolean = workflowTracer.trace("matches") { id.matches(otherWorkflow, key) }

fun <CO, CP, S, O> setHandler(newHandler: (CO) -> WorkflowAction<CP, S, O>) {
  @Suppress("UNCHECKED_CAST")
  handler =
    newHandler as (ChildOutputT) -> WorkflowAction<ParentPropsT, ParentStateT, ParentOutputT>
}

fun <R> render(workflow: Workflow<*, *, *>, props: Any?): R {
  @Suppress("UNCHECKED_CAST")
  return workflowNode.render(
    workflow as Workflow<ChildPropsT, ChildOutputT, Nothing>,
    props as ChildPropsT,
  ) as R
}

