internal data class WorkflowNodeId(
  internal val identifier: WorkflowIdentifier,
  internal val name: String = "",
) {
  constructor(workflow: Workflow<*, *, *>, name: String = "") : this(workflow.identifier, name)

  private val debugString by
    lazy(NONE) {
      if (name.isBlank()) {
        identifier.toString()
      } else {
        "$identifier named $name"
      }
    }

  fun matches(otherWorkflow: Workflow<*, *, *>, otherName: String): Boolean =
    identifier == otherWorkflow.identifier && name == otherName

  internal fun toByteStringOrNull(): ByteString? {
    // If identifier is not snapshottable, neither are we.
    val identifierBytes = identifier.toByteStringOrNull() ?: return null
    return Buffer().let { sink ->
      sink.writeByteStringWithLength(identifierBytes)
      sink.writeUtf8WithLength(name)
      sink.readByteString()
    }
  }

  internal companion object {
    fun parse(bytes: ByteString): WorkflowNodeId =
      Buffer().let { source ->
        source.write(bytes)

        val identifierBytes = source.readByteStringWithLength()
        val identifier = WorkflowIdentifier.parse(identifierBytes)
        val name = source.readUtf8WithLength()
        return WorkflowNodeId(identifier, name)
      }
  }

  override fun toString() = debugString
}

fun nextRendering(): RenderingAndSnapshot<RenderingT> {
  return interceptor.onRenderAndSnapshot(
    renderProps = currentProps,
    proceed = { props ->
      val rendering = rootNode.render(workflow, props)
      val snapshot = rootNode.snapshot()
      RenderingAndSnapshot(rendering, snapshot)
    },
    session = rootNode.session,
  )
}

suspend fun awaitAndApplyAction(): ActionProcessingResult {
  // If waitForAction is true we block and wait until there is an action to process.
  return select {
    onPropsUpdated()
    // Have the workflow tree build the select to wait for an event/output from Worker.
    rootNode.registerTreeActionSelectors(this)
  }
}

