internal class WorkflowSnapshotState(props: Any?, onOutput: ((Any?) -> Unit)?, state: Any?) :
  StateObject {
  private var record = Record(props, onOutput, state)

  override val firstStateRecord: StateRecord
    get() = record

  override fun prependStateRecord(value: StateRecord) {
    record = value as Record
  }

  /** Returns the workflow's current state without notifying read observers. */
  fun peekState(): Any? = record.withCurrent { it.state }

  /**
   * Performs all the state update duties for a render pass:
   *
   * - Stores new props and output handlers.
   * - Calls the workflow's [onPropsChanged] method only if necessary, and updates the workflow's
   *   state if a new one is returned.
   * - Returns the latest state for the workflow to be used by the render method.
   * - Avoids calling `equals` on [newProps] and [newOnOutput] if [didPropsChange] and
   *   [didOnOutputChange] are not null.
   *
   * This should be called once every render pass.
   *
   * @param didPropsChange Optional flag that can be passed if the caller has already determined if
   *   the props are different from the last call (e.g. via Compose's mechanisms). If null, the
   *   props' `equals` method will be used. NB: If this is `false`, then [newProps] won't be saved
   *   even if it's different than the last props.
   * @param didOnOutputChange Optional flag that can be passed if the caller has already determined
   *   if the output handler is different from the last call. NB: If this is `false`, then
   *   [newOnOutput] won't be saved even if it's different than the last output handler.
   * @param onPropsChanged Handler invoked when props are different. Should call
   *   [com.squareup.workflow1.StatefulWorkflow.onPropsChanged].
   */
  inline fun updateAndGetState(
    newProps: Any?,
    noinline newOnOutput: ((Any?) -> Unit)?,
    didPropsChange: Boolean?,
    didOnOutputChange: Boolean?,
    onPropsChanged: (oldProps: Any?, oldState: Any?) -> Any?,
  ): Any? {
    var oldProps: Any? = null
    var oldOnOutput: ((Any?) -> Unit)? = null
    var oldState: Any? = null

    // Avoid recording a read since that would make the write below a backwards write, and
    // potentially trigger and infinite recomposition loop.
    record.withCurrent {
      oldProps = it.props
      oldOnOutput = it.onOutput
      oldState = it.state
    }

    var newState = oldState
    var stateChanged = false
    val propsChanged = didPropsChange == true || (didPropsChange == null && oldProps != newProps)
    if (propsChanged) {
      newState = onPropsChanged(oldProps, oldState)
      // Only call `equals` if the state may have changed.
      stateChanged = oldState != newState
    }

    // Only perform a state write if necessary. Note there is no additional cost to updating all
    // record fields if we have to update one, so we just write them all every time.
    if (
      propsChanged ||
        stateChanged ||
        (didOnOutputChange == true || (didOnOutputChange == null && oldOnOutput != newOnOutput))
    ) {
      record.writable(this) {
        props = newProps
        onOutput = newOnOutput
        state = newState
      }
    }

    // No need to report a read at all, since the only way the state can change (other than this
    // function) is via applyAction, which explicitly invalidates the RecomposeScope.

    return newState
  }

  /**
   * Applies a [WorkflowAction] to the workflow's state, writing the new state and invoking the
   * output handler if necessary.
   */
  inline fun applyAction(action: WorkflowAction<Any?, Any?, Any?>, onNewState: () -> Unit) {
    // TODO should this be done in a snapshot to ensure all the updates get to the workflow runtime
    //  at the same time?
    var oldState: Any? = null
    var lastProps: Any? = null
    var onOutput: ((Any?) -> Unit)? = null
    record.withCurrent {
      lastProps = it.props
      onOutput = it.onOutput
      oldState = it.state
    }
    val (newState, applied) = action.applyTo(lastProps, oldState)
    if (oldState != newState) {
      record.writable(this) { state = newState }
      onNewState()
    }

    // Propagate the output up the workflow tree. Propagation doesn't touch our state but still
    // should be part of the critical section: For an intermediate node, while it's propagating
    // an action from one part of its subtree, if another action comes in from a different part
    // of the subtree, the second action won't propagate until the first one is done. If we
    // moved this out of the lock, then the propagations of two actions from two subtrees could
    // be interleaved to their common ancestors.
    // WorkflowOutput is the box that tells "no output" apart from setOutput(null), so only unwrap
    // it after checking for its presence.
    onOutput?.let { onOutput -> applied.output?.let { onOutput(it.value) } }
  }

  internal class Record(var props: Any?, var onOutput: ((Any?) -> Unit)?, var state: Any?) :
    StateRecord() {
    override fun create(): StateRecord = Record(props, onOutput, state)

    override fun assign(value: StateRecord) {
      value as Record
      props = value.props
      onOutput = value.onOutput
      state = value.state
    }
  }
}

inline fun applyAction(action: WorkflowAction<Any?, Any?, Any?>, onNewState: () -> Unit) {
  // TODO should this be done in a snapshot to ensure all the updates get to the workflow runtime
  //  at the same time?
  var oldState: Any? = null
  var lastProps: Any? = null
  var onOutput: ((Any?) -> Unit)? = null
  record.withCurrent {
    lastProps = it.props
    onOutput = it.onOutput
    oldState = it.state
  }
  val (newState, applied) = action.applyTo(lastProps, oldState)
  if (oldState != newState) {
    record.writable(this) { state = newState }
    onNewState()
  }

  // Propagate the output up the workflow tree. Propagation doesn't touch our state but still
  // should be part of the critical section: For an intermediate node, while it's propagating
  // an action from one part of its subtree, if another action comes in from a different part
  // of the subtree, the second action won't propagate until the first one is done. If we
  // moved this out of the lock, then the propagations of two actions from two subtrees could
  // be interleaved to their common ancestors.
  // WorkflowOutput is the box that tells "no output" apart from setOutput(null), so only unwrap
  // it after checking for its presence.
  onOutput?.let { onOutput -> applied.output?.let { onOutput(it.value) } }
}

internal open class RecordingWorkflowInterceptor : SimpleLoggingWorkflowInterceptor() {

  private var events: List<String> = emptyList()

  override fun logBeforeMethod(
    name: String,
    session: WorkflowSession,
    vararg extras: Pair<String, Any?>,
  ) {
    events += "BEGIN|$name"
  }

  override fun logAfterMethod(
    name: String,
    session: WorkflowSession,
    vararg extras: Pair<String, Any?>,
  ) {
    events += "END|$name"
  }

  private fun consumeEvents(): List<String> = events.also { events = emptyList() }

  fun consumeEventNames(): List<String> = consumeEvents().map { it.substringBefore('(') }
}

enum class GarbageSnapshot {
  /** Zero bytes. */
  EMPTY {
    override fun corrupt(validBytes: ByteString): ByteString = ByteString.EMPTY
  },

  /** Bytes that were never a snapshot at all. */
  RANDOM {
    override fun corrupt(validBytes: ByteString): ByteString =
      Random(0).nextBytes(64).toByteString()
  },

  /** A real snapshot with its magic number stripped, like one written before formats existed. */
  MISSING_MAGIC {
    override fun corrupt(validBytes: ByteString): ByteString = validBytes.substring(1)
  };

  abstract fun corrupt(validBytes: ByteString): ByteString
}

enum class CorruptBody {
  /** A real snapshot that lost its second half. */
  TRUNCATED {
    override fun corrupt(validBytes: ByteString): ByteString =
      validBytes.substring(0, validBytes.size / 2)
  },

  /** The root snapshot's length prefix claims a negative size. */
  NEGATIVE_ROOT_LENGTH {
    override fun corrupt(validBytes: ByteString): ByteString =
      Buffer().write(validBytes.substring(0, 1)).writeInt(-1).readByteString()
  },

  /** The root snapshot's length prefix claims far more bytes than are present. */
  OVERSIZED_ROOT_LENGTH {
    override fun corrupt(validBytes: ByteString): ByteString =
      Buffer().write(validBytes.substring(0, 1)).writeInt(Int.MAX_VALUE).readByteString()
  };

  abstract fun corrupt(validBytes: ByteString): ByteString
}

private class StringStateWorkflow(
  private val initialStateSnapshots: MutableList<Snapshot?>,
  private val child: StringStateWorkflow? = null,
) : StatefulWorkflow<Unit, String, Nothing, StringStateRendering>() {

  override fun initialState(props: Unit, snapshot: Snapshot?): String {
    initialStateSnapshots += snapshot
    if (snapshot == null) return "initial state"
    return runCatching { snapshot.bytes.parse { it.readUtf8WithLength() } }
      .getOrElse { "undecodable snapshot: ${snapshot.bytes.hex()}" }
  }

  override fun render(
    renderProps: Unit,
    renderState: String,
    context: RenderContext<Unit, String, Nothing>,
  ): StringStateRendering =
    StringStateRendering(
      state = renderState,
      child = child?.let { context.renderChild(it) },
      update = context.eventHandler("update") { newState: String -> state = newState },
    )

  override fun snapshotState(state: String): Snapshot = Snapshot.write {
    it.writeUtf8WithLength(state)
  }
}

