private class Latch {
  private val condition = NSCondition()
  private var isOpen = false

  fun open() {
    condition.lock()
    isOpen = true
    condition.broadcast()
    condition.unlock()
  }

  fun await() {
    condition.lock()
    while (!isOpen) condition.wait()
    condition.unlock()
  }
}

