fun verifyTypesToLevel(levels: Int, type1: KType, type2: KType): Boolean {
  if (levels < 1) return true
  if (levels == 1) {
    // We are at the last level of verification, ignore any further generic type arguments.
    return type1.classifier?.equals(type2.classifier) == true
  } else {
    if (type1.arguments.size != type2.arguments.size) return false
    var acc = true
    type1.arguments.forEachIndexed { index, kTypeProjection1 ->
      val kTypeProjection2 = type2.arguments[index]
      if (kTypeProjection1.type == null || kTypeProjection2.type == null) return false
      acc =
        acc && verifyTypesToLevel(levels - 1, kTypeProjection1.type!!, kTypeProjection2.type!!)
    }
    return acc
  }
}

public fun <PropsT, StateT, OutputT, RenderingT> RenderTester<PropsT, StateT, OutputT, RenderingT>
  .expectSideEffect(key: String): RenderTester<PropsT, StateT, OutputT, RenderingT> =
  expectSideEffect("side effect with key \"$key\"", exactMatch = true) { it == key }

private fun Throwable.addSuppressedSafely(e: Throwable?) {
  if (e != null && e !== this) addSuppressed(e)
}

public fun rethrowingUncaughtExceptions(block: () -> Unit) {
  val oldHandler = Thread.getDefaultUncaughtExceptionHandler()
  val guard = UncaughtExceptionGuard()

  Thread.setDefaultUncaughtExceptionHandler { _, e -> guard.reportUncaught(e) }
  try {
    guard.runRethrowingUncaught(block)
  } finally {
    Thread.setDefaultUncaughtExceptionHandler(oldHandler)
  }
}

@OptIn(DelicateCoroutinesApi::class)
public fun <T> Worker<T>.test(
  timeoutMs: Long = DEFAULT_TIMEOUT_MS,
  block: suspend WorkerTester<T>.() -> Unit,
) {
  runTest {
    // Use a Turbine which consumes outputs/errors from an underlying channel.
    run().test(timeout = timeoutMs.toDuration(MILLISECONDS)) {
      val tester =
        object : WorkerTester<T> {
          override val testCoroutineScheduler: TestCoroutineScheduler = testScheduler

          override suspend fun nextOutput(): T = awaitItem()

          override fun assertNoOutput() {
            try {
              expectNoEvents()
            } catch (e: AssertionError) {
              throw AssertionError("Expected no output, completion, or error to have been emitted.")
            }
          }

          override suspend fun assertFinished() {
            try {
              withTimeoutOrNull(timeoutMs) { awaitComplete() } ?: throw AssertionError()
            } catch (e: AssertionError) {
              // Note there is some complicated logic here to build the message. The messages
              // predate
              // Turbine integration but we wanted to keep them stable, and so extract what's needed
              // from the Turbine AssertionErrors.
              val message = buildString {
                append("Expected Worker to be finished.")
                val outputStrings =
                  cancelAndConsumeRemainingEvents()
                    .filterIsInstance<Item<T>>()
                    .map { it.value.toString() }
                    .toMutableList()
                // Consumed and only reported in the exception.
                e.message
                  ?.substringAfter(delimiter = "Item(", missingDelimiterValue = "")
                  ?.substringBeforeLast(delimiter = ')', missingDelimiterValue = "")
                  ?.let {
                    if (it.isNotEmpty()) {
                      outputStrings.add(0, it)
                    }
                  }
                if (outputStrings.isNotEmpty()) {
                  append(" Emitted outputs: $outputStrings")
                }
              }
              throw AssertionError(message)
            }
          }

          override fun assertNotFinished() {
            if (asChannel().isClosedForReceive) {
              throw AssertionError("Expected Worker to not be finished.")
            }
          }

          override suspend fun getException(): Throwable =
            try {
              awaitError()
            } catch (e: Throwable) {
              e
            }

          override suspend fun cancelWorker() {
            cancelAndIgnoreRemainingEvents()
          }
        }

      tester.block()
      cancelAndIgnoreRemainingEvents()
    }
  }
}

