public sealed interface WorkflowRuntimeTeardown {
  /**
   * Cancel the workflow runtime and return without waiting for cancellation cleanup to complete.
   * This is the default `renderForTest` behavior.
   */
  public data object Cancel : WorkflowRuntimeTeardown

  /**
   * Cancel the workflow runtime and wait for cancellation cleanup to complete. Pass this to
   * `renderForTest` when a test needs to observe effects that happen during runtime cancellation.
   *
   * @param timeout The maximum time to wait for the runtime job to complete after cancellation.
   * @param drainSchedulerAfterCancel Whether to drain the test scheduler after cancelling the
   *   runtime, and again after the runtime job completes.
   */
  public data class CancelAndAwait(
    public val timeout: Duration = 1.seconds,
    public val drainSchedulerAfterCancel: Boolean = true,
  ) : WorkflowRuntimeTeardown
}

public data class CancelAndAwait(
  public val timeout: Duration = 1.seconds,
  public val drainSchedulerAfterCancel: Boolean = true,
) : WorkflowRuntimeTeardown

public fun <StateT> WorkflowTestParams<StateT>.createInterceptors(): List<WorkflowInterceptor> {
  val interceptors = mutableListOf<WorkflowInterceptor>()

  if (checkRenderIdempotence) {
    interceptors += RenderIdempotencyChecker
  }

  (startFrom as? StartFromState)?.let { startFrom ->
    interceptors +=
      object : WorkflowInterceptor {
        @Suppress("UNCHECKED_CAST")
        override fun <P, S> onInitialState(
          props: P,
          snapshot: Snapshot?,
          workflowScope: CoroutineScope,
          proceed: (P, Snapshot?, CoroutineScope) -> S,
          session: WorkflowSession,
        ): S {
          return if (session.parent == null) {
            startFrom.state as S
          } else {
            proceed(props, snapshot, workflowScope)
          }
        }
      }
  }

  return interceptors
}

public val hasRendering: Boolean
  @OptIn(DelicateCoroutinesApi::class)
  get() {
    if (autoAdvanceBeforeHasCheck) {
      advanceUntilSettled()
    }
    return !turbine.usedFirstRendering || !turbine.renderingChannel.isEmpty
  }

public val hasSnapshot: Boolean
  @OptIn(DelicateCoroutinesApi::class)
  get() {
    if (autoAdvanceBeforeHasCheck) {
      advanceUntilSettled()
    }
    return !turbine.usedFirstSnapshot || !turbine.snapshotChannel.isEmpty
  }

public val hasOutput: Boolean
  @OptIn(DelicateCoroutinesApi::class)
  get() {
    if (autoAdvanceBeforeHasCheck) {
      advanceUntilSettled()
    }
    return !turbine.outputChannel.isEmpty
  }

public suspend fun awaitNextRendering(
  timeoutMs: Long? = null,
  skipIntermediate: Boolean = true,
  advanceScheduler: Boolean = autoAdvanceBeforeAwait,
): RenderingT {
  val block: suspend () -> RenderingT = {
    var rendering = turbine.awaitNextRendering(advanceScheduler = advanceScheduler)
    @OptIn(DelicateCoroutinesApi::class)
    if (skipIntermediate) {
      while (!turbine.renderingChannel.isEmpty) {
        rendering = turbine.awaitNextRendering(advanceScheduler = advanceScheduler)
      }
    }
    rendering
  }
  return if (timeoutMs != null) withTimeout(timeoutMs) { block() } else block()
}

public suspend fun awaitNextSnapshot(
  timeoutMs: Long? = null,
  skipIntermediate: Boolean = true,
  advanceScheduler: Boolean = autoAdvanceBeforeAwait,
): TreeSnapshot {
  val block: suspend () -> TreeSnapshot = {
    var snapshot = turbine.awaitNextSnapshot(advanceScheduler = advanceScheduler)
    @OptIn(DelicateCoroutinesApi::class)
    if (skipIntermediate) {
      while (!turbine.snapshotChannel.isEmpty) {
        snapshot = turbine.awaitNextSnapshot(advanceScheduler = advanceScheduler)
      }
    }
    snapshot
  }
  return if (timeoutMs != null) withTimeout(timeoutMs) { block() } else block()
}

public suspend fun awaitNextOutput(
  timeoutMs: Long? = null,
  advanceScheduler: Boolean = autoAdvanceBeforeAwait,
): OutputT {
  return if (timeoutMs != null) {
    withTimeout(timeoutMs) { turbine.awaitNextOutput(advanceScheduler = advanceScheduler) }
  } else {
    turbine.awaitNextOutput(advanceScheduler = advanceScheduler)
  }
}

@Deprecated("Use renderForTest and WorkflowTurbine instead.")
@TestOnly
public fun <T, PropsT, StateT, OutputT, RenderingT> StatefulWorkflow<
  PropsT,
  StateT,
  OutputT,
  RenderingT,
>
  .launchForTestingWith(
  props: PropsT,
  testParams: WorkflowTestParams<StateT> = WorkflowTestParams(),
  context: CoroutineContext = EmptyCoroutineContext,
  block: suspend WorkflowTestRuntime<PropsT, OutputT, RenderingT>.() -> T,
): T {
  val propsFlow = MutableStateFlow(props)
  val schedulerContext =
    when (testParams.deprecatedLaunchSchedulerMode) {
      DeprecatedLaunchSchedulerMode.LEGACY_UNCONFINED -> UnconfinedTestDispatcher()
      DeprecatedLaunchSchedulerMode.VIRTUAL_TIME_STANDARD -> StandardTestDispatcher()
    }
  // Strip Job from the caller's context so it doesn't interfere with the runtime scope's
  // lifecycle management. Other context elements (names, coroutine names, etc.) are preserved.
  val safeContext = context.minusKey(Job)
  var result: T? = null
  renderForTest(
    props = propsFlow,
    testParams = testParams,
    coroutineContext = schedulerContext + safeContext,
  ) {
    val runtime =
      WorkflowTestRuntime(
        props = propsFlow,
        turbine = this,
        autoAdvanceBeforeAwait = testParams.autoAdvanceBeforeAwait,
        autoAdvanceBeforeHasCheck = testParams.autoAdvanceBeforeHasCheck,
      )
    result = runtime.block()
  }
  @Suppress("UNCHECKED_CAST")
  return result as T
}

var result: Any? = NoResult
runTest(context = coroutineContext, timeout = testTimeout.milliseconds) {
  // We use a sub-scope so that we can cancel the Workflow runtime when we are done with it so
  // that
  // tests don't all have to do that themselves.
  val workflowRuntimeScope = CoroutineScope(coroutineContext)
  val runtimeJob =
    workflowRuntimeScope.coroutineContext[Job] ?: error("Workflow runtime scope must have a Job")

  var testFailure: Throwable? = null
  try {
    val outputsChannel = Channel<OutputT>(Channel.UNLIMITED)

    val renderings =
      renderWorkflowIn(
        workflow = workflow,
        props = props,
        scope = workflowRuntimeScope,
        initialSnapshot = initialSnapshot,
        interceptors = interceptors,
        runtimeConfig = runtimeConfig,
        onOutput = { output ->
          outputsChannel.send(output)
          onOutput(output)
        },
      )

    if (testParams.autoAdvanceOnStartup) {
      // Advance the scheduler to start the runtime loop coroutine. With StandardTestDispatcher,
      // scope.launch {} dispatches but doesn't start the coroutine until the scheduler is
      // advanced.
      // This ensures the runtime loop is running and waiting for actions before the test begins.
      testScheduler.advanceUntilIdle()
    }

    val firstRendering = renderings.value.rendering
    val firstSnapshot = renderings.value.snapshot

    // Share the RenderingAndSnapshot flow so multiple subscribers can collect from it
    // Use workflowRuntimeScope so it's cancelled when the workflow is cancelled
    val sharedRenderings =
      renderings
        .drop(1)
        .shareIn(scope = workflowRuntimeScope, started = SharingStarted.Eagerly, replay = 0)

    // Use turbineScope to test multiple flows
    turbineScope {
      // Map the shared flow to extract renderings and snapshots separately
      val renderingTurbine =
        sharedRenderings
          .map { it.rendering }
          .testIn(backgroundScope, timeout = testTimeout.milliseconds, name = "renderings")
      val snapshotTurbine =
        sharedRenderings
          .map { it.snapshot }
          .testIn(backgroundScope, timeout = testTimeout.milliseconds, name = "snapshots")
      val outputTurbine =
        outputsChannel
          .receiveAsFlow()
          .testIn(backgroundScope, timeout = testTimeout.milliseconds, name = "outputs")

      try {
        val workflowTurbine =
          WorkflowTurbine(
            firstRendering = firstRendering,
            firstSnapshot = firstSnapshot,
            renderingTurbine = renderingTurbine,
            snapshotTurbine = snapshotTurbine,
            outputTurbine = outputTurbine,
            testScheduler = testScheduler,
            autoAdvanceBeforeAwait = testParams.autoAdvanceBeforeAwait,
          )
        result = workflowTurbine.testCase()
      } finally {
        renderingTurbine.cancelAndIgnoreRemainingEvents()
        snapshotTurbine.cancelAndIgnoreRemainingEvents()
        outputTurbine.cancelAndIgnoreRemainingEvents()
      }
    }
  } catch (t: Throwable) {
    testFailure = t
    throw t
  } finally {
    val teardownFailure =
      runCatching { runtimeJob.cancelForTest(teardown, testScheduler) }.exceptionOrNull()

    if (teardownFailure != null) {
      if (testFailure != null) {
        testFailure.addSuppressed(teardownFailure)
      } else {
        throw teardownFailure
      }
    }
  }
}

@OptIn(ExperimentalCoroutinesApi::class)
public fun <OutputT, RenderingT, T> Workflow<Unit, OutputT, RenderingT>.renderForTestForStartWith(
  coroutineContext: CoroutineContext = StandardTestDispatcher(),
  testParams: WorkflowTestParams<Nothing> = WorkflowTestParams(),
  interceptors: List<WorkflowInterceptor> = emptyList(),
  teardown: WorkflowRuntimeTeardown = WorkflowRuntimeTeardown.Cancel,
  onOutput: suspend (OutputT) -> Unit = {}

public class WorkflowTurbine<RenderingT, OutputT>(
  public val firstRendering: RenderingT,
  public val firstSnapshot: TreeSnapshot,
  private val renderingTurbine: ReceiveTurbine<RenderingT>,
  private val snapshotTurbine: ReceiveTurbine<TreeSnapshot>,
  private val outputTurbine: ReceiveTurbine<OutputT>,
  private val testScheduler: TestCoroutineScheduler? = null,
  private val autoAdvanceBeforeAwait: Boolean = true,
) {
  internal var usedFirstRendering = false
  internal var usedFirstSnapshot = false

  @OptIn(DelicateCoroutinesApi::class)
  internal val renderingChannel
    get() = renderingTurbine.asChannel()

  @OptIn(DelicateCoroutinesApi::class)
  internal val snapshotChannel
    get() = snapshotTurbine.asChannel()

  @OptIn(DelicateCoroutinesApi::class)
  internal val outputChannel
    get() = outputTurbine.asChannel()

  /**
   * Advances the [testScheduler] passed in for this [WorkflowTurbine].
   *
   * This may be called automatically by [awaitNextRendering], [awaitNextOutput], and
   * [awaitNextSnapshot] depending on each call's `advanceScheduler` argument. It is always used by
   * [skipRenderings]. You only need to call this explicitly when you want to process pending
   * actions without awaiting a rendering or output — for example, to assert on side effects
   * triggered by an action that doesn't change state or produce output.
   *
   * With a non-immediate dispatcher (like [StandardTestDispatcher]), this drains all pending
   * coroutines so the runtime processes queued actions. With an immediate dispatcher, this is
   * effectively a no-op.
   */
  public fun advanceUntilSettled() {
    testScheduler?.advanceUntilIdle()
  }

  /**
   * Suspend waiting for the next rendering to be produced by the Workflow runtime. Note this
   * includes the first (synchronously made) rendering.
   *
   * @param advanceScheduler If true, call [advanceUntilSettled] before waiting for the next item.
   * @return the rendering.
   */
  public suspend fun awaitNextRendering(
    advanceScheduler: Boolean = autoAdvanceBeforeAwait
  ): RenderingT {
    if (!usedFirstRendering) {
      usedFirstRendering = true
      return firstRendering
    }
    if (advanceScheduler) {
      advanceUntilSettled()
    }
    return renderingTurbine.awaitItem()
  }

  /**
   * Suspend waiting for the next output to be produced by the Workflow runtime.
   *
   * @param advanceScheduler If true, call [advanceUntilSettled] before waiting for the next item.
   * @return the output.
   */
  public suspend fun awaitNextOutput(advanceScheduler: Boolean = autoAdvanceBeforeAwait): OutputT {
    if (advanceScheduler) {
      advanceUntilSettled()
    }
    return outputTurbine.awaitItem()
  }

  /**
   * Suspend waiting for the next snapshot to be produced by the Workflow runtime. Note this
   * includes the first (synchronously made) snapshot.
   *
   * @param advanceScheduler If true, call [advanceUntilSettled] before waiting for the next item.
   * @return the snapshot.
   */
  public suspend fun awaitNextSnapshot(
    advanceScheduler: Boolean = autoAdvanceBeforeAwait
  ): TreeSnapshot {
    if (!usedFirstSnapshot) {
      usedFirstSnapshot = true
      return firstSnapshot
    }
    if (advanceScheduler) {
      advanceUntilSettled()
    }
    return snapshotTurbine.awaitItem()
  }

  public suspend fun skipRenderings(count: Int) {
    val skippedCount =
      if (!usedFirstRendering) {
        usedFirstRendering = true
        count - 1
      } else {
        count
      }

    if (skippedCount > 0) {
      advanceUntilSettled()
      renderingTurbine.skipItems(skippedCount)
    }
  }

  /**
   * Suspend waiting for the next rendering to be produced by the Workflow runtime that satisfies
   * the [predicate].
   *
   * @return the rendering.
   */
  public suspend fun awaitNextRenderingSatisfying(predicate: (RenderingT) -> Boolean): RenderingT {
    var rendering = awaitNextRendering()
    while (!predicate(rendering)) {
      rendering = awaitNextRendering()
    }
    return rendering
  }

  /**
   * Suspend waiting for the next rendering which satisfies [precondition], can successfully be
   * mapped using [map] and satisfies the [satisfying] predicate when called on the [T] rendering
   * after it has been mapped.
   *
   * @return the mapped rendering as [T]
   */
  public suspend fun <T> awaitNext(
    precondition: (RenderingT) -> Boolean = { true },
    map: (RenderingT) -> T,
    satisfying: T.() -> Boolean = { true },
  ): T =
    map(awaitNextRenderingSatisfying { precondition(it) && with(map(it)) { this.satisfying() } })

  public companion object {
    /** Default timeout to use while waiting for renderings. */
    public const val WORKFLOW_TEST_DEFAULT_TIMEOUT_MS: Long = 60_000L
  }
}

public suspend fun awaitNextRendering(
  advanceScheduler: Boolean = autoAdvanceBeforeAwait
): RenderingT {
  if (!usedFirstRendering) {
    usedFirstRendering = true
    return firstRendering
  }
  if (advanceScheduler) {
    advanceUntilSettled()
  }
  return renderingTurbine.awaitItem()
}

public suspend fun awaitNextOutput(advanceScheduler: Boolean = autoAdvanceBeforeAwait): OutputT {
  if (advanceScheduler) {
    advanceUntilSettled()
  }
  return outputTurbine.awaitItem()
}

public suspend fun awaitNextSnapshot(
  advanceScheduler: Boolean = autoAdvanceBeforeAwait
): TreeSnapshot {
  if (!usedFirstSnapshot) {
    usedFirstSnapshot = true
    return firstSnapshot
  }
  if (advanceScheduler) {
    advanceUntilSettled()
  }
  return snapshotTurbine.awaitItem()
}

public suspend fun awaitNextRenderingSatisfying(predicate: (RenderingT) -> Boolean): RenderingT {
  var rendering = awaitNextRendering()
  while (!predicate(rendering)) {
    rendering = awaitNextRendering()
  }
  return rendering
}

@Composable
internal fun TraceViewerWindow(modifier: Modifier = Modifier, traceMode: TraceMode) {
  var appWindowSize by remember { mutableStateOf(IntSize(0, 0)) }
  var selectedNode by remember { mutableStateOf<NodeUpdate?>(null) }
  var frameSize by remember { mutableIntStateOf(0) }
  var rawRenderPass by remember { mutableStateOf("") }
  var frameIndex by remember { mutableIntStateOf(if (traceMode is TraceMode.Live) -1 else 0) }
  val sandboxState = remember { SandboxState() }
  val nodeLocations = remember { mutableStateListOf<SnapshotStateMap<Node, Offset>>() }

  // Default to File mode, and can be toggled to be in Live mode.
  var active by remember { mutableStateOf(false) }
  // frameIndex is set to -1 when app is in Live Mode, so we increment it by one to avoid off-by-one
  // errors
  val frameInd = if (traceMode is TraceMode.Live) frameIndex + 1 else frameIndex

  LaunchedEffect(sandboxState) { snapshotFlow { frameIndex }.collect { sandboxState.reset() } }

  Box(modifier = modifier.onSizeChanged { appWindowSize = it }) {

    // Main content
    SandboxBackground(appWindowSize = appWindowSize, sandboxState = sandboxState) {
      // if there is not a file selected and trace mode is live, then don't render anything.
      val readyForFileTrace = TraceMode.validateFileMode(traceMode)
      val readyForLiveTrace = TraceMode.validateLiveMode(traceMode)

      if (readyForFileTrace || readyForLiveTrace) {
        active = true
        RenderTrace(
          traceSource = traceMode,
          frameInd = frameIndex,
          onFileParse = { frameSize += it },
          onNodeSelect = { selectedNode = it },
          onNewFrame = { frameIndex += 1 },
          onNewData = { rawRenderPass += "$it," },
          storeNodeLocation = { node, loc -> nodeLocations[frameInd] += (node to loc) },
        )
      }
    }

    Row(
      modifier = Modifier.align(Alignment.TopCenter).padding(top = 8.dp),
      horizontalArrangement = Arrangement.spacedBy(8.dp),
      verticalAlignment = Alignment.Top,
    ) {
      if (active) {
        // Frames that appear in composition may not happen sequentially, so when the current frame
        // locations is null, that means we've skipped frames and need to fill all the intermediate
        // ones. e.g. Frame 1 to Frame 10
        if (nodeLocations.getOrNull(frameInd) == null) {
          // frameSize has not been updated yet, so on the first frame, frameSize =
          // nodeLocations.size = 0,
          // and it will append a new map
          while (nodeLocations.size <= frameSize) {
            nodeLocations += mutableStateMapOf()
          }
        }

        val frameNodeLocations = nodeLocations[frameInd]
        SearchBox(
          nodes = frameNodeLocations.keys.toList(),
          onSearch = { name ->
            val node = frameNodeLocations.keys.first { it.name == name }
            val newX =
              (sandboxState.offset.x - frameNodeLocations.getValue(node).x +
                appWindowSize.width / 2)
            val newY =
              (sandboxState.offset.y - frameNodeLocations.getValue(node).y +
                appWindowSize.height / 2)
            sandboxState.offset = Offset(x = newX, y = newY)
          },
        )

        FrameNavigator(
          totalFrames = frameSize,
          currentIndex = frameIndex,
          onIndexChange = { frameIndex = it },
        )
      }
    }
    if (traceMode is TraceMode.Live) {
      FileDump(trace = rawRenderPass, modifier = Modifier.align(Alignment.BottomEnd).padding(16.dp))
    }
    key(selectedNode) {
      RightInfoPanel(selectedNode = selectedNode, modifier = Modifier.align(Alignment.TopEnd))
    }
  }
}

