fun main() {
  application {
    var openWindows by remember { mutableStateOf(setOf<TraceWindow>()) }
    var isLandingWindowOpen by remember { mutableStateOf(true) }

    // Main window - always visible
    if (isLandingWindowOpen) {
      Window(
        onCloseRequest = {
          if (openWindows.isEmpty()) {
            exitProcess(0)
          }
          isLandingWindowOpen = false
        },
        title = "Workflow Trace Viewer",
        state = rememberWindowState(),
      ) {
        LandingWindow(
          modifier = Modifier.fillMaxSize(),
          onFileSelected = { file -> openWindows = openWindows + TraceWindow.FileWindow(file) },
          onDeviceSelected = { device ->
            openWindows = openWindows + TraceWindow.DeviceWindow(device)
          },
        )
      }
    }

    // Additional windows for each opened trace
    for (window in openWindows) {
      Window(
        onCloseRequest = {
          openWindows = openWindows - window
          if (!isLandingWindowOpen && openWindows.isEmpty()) {
            exitProcess(0)
          }
        },
        title =
          when (window) {
            is TraceWindow.FileWindow -> window.file.name
            is TraceWindow.DeviceWindow -> "Live: ${window.device}"
          },
        state = rememberWindowState(),
      ) {
        when (window) {
          is TraceWindow.FileWindow -> {
            TraceViewerWindow(
              modifier = Modifier.fillMaxSize(),
              traceMode = TraceMode.File(window.file),
            )
          }
          is TraceWindow.DeviceWindow -> {
            TraceViewerWindow(
              modifier = Modifier.fillMaxSize(),
              traceMode = TraceMode.Live(window.device),
            )
          }
        }
      }
    }
  }
}

internal data class Node(
  val name: String,
  val id: String,
  val parent: String,
  val parentId: String,
  val props: String,
  val state: String,
  val rendering: String = "",
  @Transient val children: LinkedHashMap<String, Node> = LinkedHashMap(),
) {

  override fun toString(): String {
    return "Node(name='$name', parent='$parent', children=$children)"
  }

  override fun equals(other: Any?): Boolean {
    if (this === other) return true
    if (other !is Node) return false
    return this.id == other.id
  }

  override fun hashCode(): Int {
    return id.hashCode()
  }

  companion object {
    val nodeFields: List<String> = listOf("Props", "State")
  }
}

internal data class NodeUpdate(val current: Node, val past: Node?, val state: NodeState) {
  companion object {
    fun create(current: Node, past: Node?, isAffected: Boolean): NodeUpdate {
      val state =
        when {
          !isAffected -> NodeState.UNCHANGED
          past == null -> NodeState.NEW
          current.props != past.props -> NodeState.PROPS_CHANGED
          current.state != past.state -> NodeState.STATE_CHANGED
          else -> NodeState.RENDERED
        }

      return NodeUpdate(current, past, state)
    }
  }
}

