      Column(
        modifier = Modifier.fillMaxWidth().padding(6.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
      ) {
        DrawChildrenInGroups(
          children = children,
          previousFrameNode = previousFrameNode,
