          storeNodeLocation = storeNodeLocation,
        )
      }
    }
  }
}

@Composable
private fun AffectedChildrenGroup(
  children: List<Node>,
  previousFrameNode: Node?,
  affectedNodes: Set<Node>,
  expandedNodes: MutableMap<String, Boolean>,
