      NodeTooltip(
        nodeState = nodeUpdate.state,
        modifier = Modifier.align(Alignment.TopEnd).background(nodeUpdate.state.color),
      )
    }
  }
}

private fun listDevices(): List<String> {
  if (adb == null) return emptyList()
  val process = ProcessBuilder(adb, "devices", "-l").start()
  process.waitFor()
  // We drop the header "List of devices attached"
  val devices = process.inputStream.use { it.bufferedReader().readLines().drop(1).dropLast(1) }

  return devices.mapNotNull { device ->
    if (device.isBlank()) return@mapNotNull null
    val deviceId = device.split(' ').first()
    val deviceName = ProcessBuilder(adb, "-s", deviceId, "emu", "avd", "name").start()
    deviceName.waitFor()
    "$deviceId " +
      deviceName.inputStream.use { it.bufferedReader().readLines().firstOrNull() ?: "" }
  }
}

