@Composable
internal fun SandboxBackground(
  appWindowSize: IntSize,
  sandboxState: SandboxState,
  modifier: Modifier = Modifier,
  content: @Composable () -> Unit,
) {
  val zoomableState = rememberZoomableState()

  Box(
    modifier
      .fillMaxSize()
      .zoomable(state = zoomableState)
      .pointerInput(Unit) {
        // Panning capabilities: watches for drag gestures and applies the translation
        detectDragGestures { _, translation -> sandboxState.offset += translation }
      }
      .pointerInput(appWindowSize) {
        // Zooming capabilities: watches for any scroll events and immediately consumes changes.
        // - This is AI generated.
        awaitEachGesture {
          val event = awaitPointerEvent()
          if (event.type == PointerEventType.Scroll) {
            val pointerInput = event.changes.first()
            // Applies zoom factor based on the actual delta change rather than just the act of
            // scrolling
            // This helps to normalize mouse scrolling and touchpad scrolling, since touchpad will
            // fire a lot more scroll events.
            val factor = 1f + (-pointerInput.scrollDelta.y * 0.1f)
            val minWindowSize = 0.3f
            val maxWindowSize = 2f
            val oldScale = (zoomableState.contentScale as? FixedScale)?.value ?: 1.0f
            val newScale = (oldScale * factor).coerceIn(minWindowSize, maxWindowSize)

            zoomableState.contentScale = FixedScale(newScale)
            event.changes.forEach { it.consume() }
          }
        }
      }
  ) {
    Box(
      modifier =
        Modifier.wrapContentSize(unbounded = true, align = Alignment.Center).graphicsLayer {
          translationX = sandboxState.offset.x
          translationY = sandboxState.offset.y
        }
    ) {
      content()
    }
  }
}

internal suspend fun streamRenderPassesFromDevice(
  device: String,
  parseOnNewRenderPass: (String) -> Unit,
) {
  val renderPassChannel: Channel<String> = Channel(Channel.BUFFERED)
  coroutineScope {
    launch {
      try {
        pollSocket(device = device, onNewRenderPass = renderPassChannel::send)
      } finally {
        renderPassChannel.close()
      }
    }

    // Since channel implements ChannelIterator, we can for-loop through on the receiver end.
    for (renderPass in renderPassChannel) {
      parseOnNewRenderPass(renderPass)
    }
  }
}

private suspend fun pollSocket(device: String, onNewRenderPass: suspend (String) -> Unit) {
  withContext(Dispatchers.IO) {
    try {
      runForwardingPortThroughAdb(device) { port ->
        Socket("localhost", port).useWithCancellation { socket ->
          val reader = socket.getInputStream().bufferedReader()
          do {
            ensureActive()
            val input = reader.readLine()
            if (input != null) {
              onNewRenderPass(input)
            }
          } while (input != null)
        }
      }
    } catch (e: IOException) {
      // NoOp
    }
  }
}

private suspend fun Socket.useWithCancellation(block: suspend (Socket) -> Unit) {
  val socket = this
  coroutineScope {
    // This coroutine is responsible for forcibly closing the socket when the coroutine is
    // cancelled. This causes any code reading from the socket to throw a CancellationException.
    // We also need to explicitly cancel this coroutine if the block returns on its own, otherwise
    // the coroutineScope will never exit.
    val socketJob = launch { socket.use { awaitCancellation() } }

    block(socket)
    socketJob.cancel()
  }
}

@Suppress("BlockingMethodInNonBlockingContext")
private suspend inline fun runForwardingPortThroughAdb(device: String, block: (port: Int) -> Unit) {
  val process =
    ProcessBuilder("adb", "-s", device, "forward", "tcp:0", "localabstract:workflow-trace").start()

  // The adb forward command will output the port number it picks to connect.
  val forwardReturnCode = runInterruptible { process.waitFor() }
  if (forwardReturnCode != 0) {
    return
  }

  val port = process.inputStream.bufferedReader().readText().trim().toInt()

  try {
    block(port)
  } finally {
    // We don't care if this fails since there's nothing we can do then anyway. It just means
    // there's an extra forward left open, but that's not a big deal.
    runCatching { ProcessBuilder("adb", "forward", "--remove", "tcp:$port").start() }
  }
}

internal fun computeAnnotatedDiff(past: String, current: String): AnnotatedString {
  val diffGenerator =
    DiffRowGenerator.create()
      .showInlineDiffs(true)
      .inlineDiffByWord(true)
      .mergeOriginalRevised(true)
      .oldTag { _ -> "--" }
      .newTag { _ -> "++" }
      .build()

  val pastName = extractTypeName(past)
  val currentName = extractTypeName(current)
  val pastFields = getFieldsAsList(past)
  val currentFields = getFieldsAsList(current)
  val diffRows = diffGenerator.generateDiffRows(pastFields, currentFields)

  var existsDiff = false
  return buildAnnotatedString {
    // A full change in the type means all internal data will be changed, so it's easier to just
    // generalize and show the diff in the type's name
    if (pastName != currentName) {
      buildStringWithStyle(style = DiffStyles.DELETE, text = "$pastName(...)", builder = this)
      append(" → ")
      buildStringWithStyle(style = DiffStyles.INSERT, text = "$currentName(...)", builder = this)
      return@buildAnnotatedString
    }

    diffRows.forEach { row ->
      val tag = row.tag!!
      // The 'mergeOriginalRevised' flag changes the semantics of the data, but the API still
      // returns
      // the same components
      val fullDiff = row.oldLine

      /*
      Tag.INSERT and Tag.DELETE only happens when there is a difference in number of rows, i.e.:
        Tag(["a"],["a","b"]) == INSERT
      and
        Tag(["a","b"],["a"]) == DELETE
      but
        Tag([""],["a"]) == CHANGE
       */
      when (tag) {
        Tag.CHANGE -> {
          existsDiff = true
          parseChangedDiff(fullDiff).forEach { (style, text) ->
            buildStringWithStyle(style = style, text = text, builder = this)
          }
          append("\n\n")
        }

        Tag.INSERT -> {
          existsDiff = true
          buildStringWithStyle(
            text = fullDiff.replace("++", ""),
            style = DiffStyles.INSERT,
            builder = this,
          )
          append("\n\n")
        }

        Tag.DELETE -> {
          existsDiff = true
          buildStringWithStyle(
            text = fullDiff.replace("--", ""),
            style = DiffStyles.DELETE,
            builder = this,
          )
          append("\n\n")
        }

        Tag.EQUAL -> {
          // NoOp
        }
      }
    }

    if (!existsDiff) {
      buildStringWithStyle(style = DiffStyles.NO_CHANGE, text = "No Diff", builder = this)
    }
  }
}

private fun parseChangedDiff(fullDiff: String): List<Pair<SpanStyle, String>> {
  val operations = buildList {
    var i = 0
    while (i < fullDiff.length) {
      when {
        fullDiff.startsWith("--", i) -> {
          val end = fullDiff.indexOf("--", i + 2)
          if (end != -1) {
            val removed = fullDiff.substring(i + 2, end)
            add(DiffStyles.DELETE to removed)
            i = end + 2
          }
        }

        fullDiff.startsWith("++", i) -> {
          val end = fullDiff.indexOf("++", i + 2)
          if (end != -1) {
            val added = fullDiff.substring(i + 2, end)
            add(DiffStyles.INSERT to added)
            i = end + 2
          }
        }

        else -> {
          val nextTagStart =
            listOf(fullDiff.indexOf("--", i), fullDiff.indexOf("++", i))
              .filter { it >= 0 }
              .minOrNull() ?: fullDiff.length
          add(DiffStyles.UNCHANGED to fullDiff.substring(i, nextTagStart))
          i = nextTagStart
        }
      }
    }
  }

  return operations
}

private fun getFieldsAsList(field: String): List<String> {
  val fields = mutableListOf<String>()
  val currentField = StringBuilder()
  var depth = 0
  // We skip past the field's Type's name
  var i = field.indexOf('(') + 1

  while (i < field.length) {
    val char = field[i]
    when (char) {
      '(',
      '[',
      '{' -> {
        depth++
        currentField.append(char)
      }

      ')',
      ']',
      '}' -> {
        depth--
        currentField.append(char)
      }

      ',' -> {
        if (depth == 0) { // end of key=value pair
          fields += currentField.toString().trim()
          currentField.clear()
          i++ // skip space in between key value pairs, i.e. "key1=value1, key2=value2"
        } else { // nested list, so we ignore
          currentField.append(char)
        }
      }

      else -> currentField.append(char)
    }
    i++
  }

  // Just append whatever is left, since there are no trailing commas
  if (currentField.isNotBlank()) fields += currentField.toString().trim()
  return fields
}

internal suspend fun parseFileTrace(file: PlatformFile): ParseResult {
  val jsonString = file.readString()
  val workflowAdapter = createMoshiAdapter<List<Node>>()
  val parsedRenderPasses =
    try {
      workflowAdapter.fromJson(jsonString)
        ?: return ParseResult.Failure(
          IllegalArgumentException("Provided trace file is empty or malformed.")
        )
    } catch (e: Exception) {
      return ParseResult.Failure(e)
    }

  val parsedFrames = parsedRenderPasses.map { renderPass -> getFrameFromRenderPass(renderPass) }
  val frameTrees = mutableListOf<Node>()
  parsedFrames.fold(parsedFrames[0]) { tree, frame ->
    val mergedTree = mergeFrameIntoMainTree(frame, tree)
    frameTrees.add(mergedTree)
    mergedTree
  }
  return ParseResult.Success(
    trace = parsedFrames,
    trees = frameTrees,
    affectedNodes = parsedRenderPasses,
  )
}

internal fun parseLiveTrace(
  renderPass: String,
  adapter: JsonAdapter<List<Node>>,
  currentTree: Node? = null,
): ParseResult {
  val parsedRenderPass =
    try {
      adapter.fromJson(renderPass)
        ?: return ParseResult.Failure(
          IllegalArgumentException("Provided trace data is empty or malformed.")
        )
    } catch (e: Exception) {
      return ParseResult.Failure(e)
    }

  val parsedFrame = getFrameFromRenderPass(parsedRenderPass)

  // Merge Frame into full tree if we have an existing tree
  val mergedTree =
    if (currentTree == null) {
      parsedFrame
    } else {
      mergeFrameIntoMainTree(parsedFrame, currentTree)
    }

  // Since live tracing handles one frame at a time, we generalize and return listOf for each.
  return ParseResult.Success(
    trace = listOf(parsedFrame),
    trees = listOf(mergedTree),
    affectedNodes = listOf(parsedRenderPass),
  )
}

val mergedTree =
  if (currentTree == null) {
    parsedFrame
  }

internal inline fun <reified T> createMoshiAdapter(): JsonAdapter<List<T>> {
  val moshi = Moshi.Builder().add(KotlinJsonAdapterFactory()).build()
  val workflowList = Types.newParameterizedType(List::class.java, typeOf<T>().javaType)
  val adapter: JsonAdapter<List<T>> = moshi.adapter(workflowList)
  return adapter
}

private fun getFrameFromRenderPass(renderPass: List<Node>): Node {
  val childrenByParent: Map<String, List<Node>> = renderPass.groupBy { it.parentId }
  val root = childrenByParent[ROOT_ID]?.single()
  return buildTree(root!!, childrenByParent)
}

private fun buildTree(node: Node, childrenByParent: Map<String, List<Node>>): Node {
  val children = (childrenByParent[node.id] ?: emptyList()).map { buildTree(it, childrenByParent) }
  return Node(
    name = node.name,
    id = node.id,
    parent = node.parent,
    parentId = node.parentId,
    props = node.props,
    state = node.state,
    children = LinkedHashMap(children.associateBy { it.id }),
  )
}

internal fun mergeFrameIntoMainTree(frame: Node, main: Node): Node {
  require(frame.id == main.id)
  val updatedNode = frame.copy(children = main.children)

  return frame.children.values.fold(updatedNode) { mergedTree, frameChild ->
    val mainTreeChild = mergedTree.children[frameChild.id]
    if (mainTreeChild != null) {
      mergedTree.replaceChild(mergeFrameIntoMainTree(frameChild, mainTreeChild))
    } else {
      mergedTree.addChild(frameChild)
    }
  }
}

@Composable
internal fun RenderTrace(
  traceSource: TraceMode,
  frameInd: Int,
  onFileParse: (Int) -> Unit,
  onNodeSelect: (NodeUpdate) -> Unit,
  onNewFrame: () -> Unit,
  onNewData: (String) -> Unit,
  storeNodeLocation: (Node, Offset) -> Unit,
) {
  key(traceSource) {
    var isLoading by remember { mutableStateOf(true) }
    var error by remember { mutableStateOf<String?>(null) }
    val frames = remember { mutableStateListOf<Node>() }
    val fullTree = remember { mutableStateListOf<Node>() }
    val affectedNodes = remember { mutableStateListOf<Set<Node>>() }

    // Updates current state with the new data from trace source.
    fun addToStates(frame: List<Node>, tree: List<Node>, affected: List<Set<Node>>) {
      frames.addAll(frame)
      fullTree.addAll(tree)
      affectedNodes.addAll(affected)
      onFileParse(frame.size)
    }

    // Handles the result of parsing a trace, either from file or live. Live mode includes callback
    // for when a new frame is received.
    fun handleParseResult(
      parseResult: ParseResult,
      rawRenderPass: String? = null,
      onNewFrame: (() -> Unit)? = null,
    ) {
      when (parseResult) {
        is ParseResult.Failure -> {
          error = parseResult.error.toString()
        }

        is ParseResult.Success -> {
          addToStates(
            frame = parseResult.trace,
            tree = parseResult.trees,
            affected = parseResult.affectedNodes,
          )
          // Only increment the frame index and add the raw data during Live tracing mode.
          onNewFrame?.invoke()
          rawRenderPass?.let { onNewData(it) }
        }
      }
      isLoading = false
    }

    LaunchedEffect(traceSource) {
      when (traceSource) {
        is TraceMode.File -> {
          checkNotNull(traceSource.file) { "TraceMode.File should have a non-null file to parse." }
          val parseResult = parseFileTrace(traceSource.file)
          handleParseResult(parseResult)
        }

        is TraceMode.Live -> {
          checkNotNull(traceSource.device) { "TraceMode.Live requires a selected device" }
          val adapter: JsonAdapter<List<Node>> = createMoshiAdapter<Node>()
          streamRenderPassesFromDevice(traceSource.device) { rawRenderPass ->
            val currentTree = fullTree.lastOrNull()
            val parseResult = parseLiveTrace(rawRenderPass, adapter, currentTree)
            handleParseResult(parseResult, rawRenderPass, onNewFrame)
          }
          error = ERROR_MESSAGE
        }
      }
    }

    // This will only happen in the initial switch to Live Mode, where a socket error bubbled up and
    // the lambda call to parse the data was immediately cancelled, meaning handleParseResult was
    // never
    // called to set isLoading to false.
    if (isLoading && error != null) {
      Error("Device Connection Failed:\n$error")
      return
    }

    // This meant that there was an exception, but it was stored in ParseResult and read in
    // handleParseResult method. Since there is no parsed data, this likely means there was a moshi
    // parsing error.
    if (error != null && frames.isEmpty()) {
      Error("Malformed File:\n$error")
      return
    }

    if (!isLoading) {
      val previousFrame = if (frameInd > 0) fullTree[frameInd - 1] else null
      DrawTree(
        node = fullTree[frameInd],
        previousFrameNode = previousFrame,
        affectedNodes = affectedNodes[frameInd],
        expandedNodes = remember(frameInd) { mutableStateMapOf() },
        onNodeSelect = onNodeSelect,
        storeNodeLocation = storeNodeLocation,
      )

      // This error happens when there has already been previous data parsed, but some exception
      // bubbled
      // up again, meaning it has to be a socket closure in Live mode.
      error?.let { Error("Lost Connection:\n$error") }
    }
  }
}

fun addToStates(frame: List<Node>, tree: List<Node>, affected: List<Set<Node>>) {
  frames.addAll(frame)
  fullTree.addAll(tree)
  affectedNodes.addAll(affected)
  onFileParse(frame.size)
}

fun handleParseResult(
  parseResult: ParseResult,
  rawRenderPass: String? = null,
  onNewFrame: (() -> Unit)? = null,
) {
  when (parseResult) {
    is ParseResult.Failure -> {
      error = parseResult.error.toString()
    }

    is ParseResult.Success -> {
      addToStates(
        frame = parseResult.trace,
        tree = parseResult.trees,
        affected = parseResult.affectedNodes,
      )
      // Only increment the frame index and add the raw data during Live tracing mode.
      onNewFrame?.invoke()
      rawRenderPass?.let { onNewData(it) }
    }
  }
  isLoading = false
}

class WorkflowTrace(override val isTraceable: Boolean = false) : TraceInterface {

  override val isCurrentlyTracing: Boolean
    get() = Trace.isEnabled()

  override fun beginSection(label: String) {
    Trace.beginSection(label)
  }

  override fun endSection() {
    Trace.endSection()
  }

  override fun beginAsyncSection(name: String, cookie: Int) {
    Trace.beginAsyncSection(name, cookie)
  }

  override fun endAsyncSection(name: String, cookie: Int) {
    Trace.endAsyncSection(name, cookie)
  }

  override fun logSection(info: String) {
    trace(info) {}
  }
}

private fun SystemTraceState.resetTraceCountsIfNotTracing() {
  if (!trace.isCurrentlyTracing) {
    renderPassCount = 0
    renderPassTriggerCount = 0
    actionIndex = 0
    effectIndex = 0
  }
}

private fun infoSection(info: String) {
  trace.logSection(info)
}

override fun onWorkflowSessionStarted(workflowScope: CoroutineScope, session: WorkflowSession) {
  systemTraceState?.let {
    val sessionId = session.sessionId
    // We are tracing, so set up some initial components for this workflow.
    val shortName = "WKF$sessionId ${session.name}"
    val nameWithKey = "WKF$sessionId ${session.logName}"

    val parentPart =
      session.parent?.let { parentSession -> " parent:${parentSession.traceName}" } ?: ""
    val asyncSectionName = "$nameWithKey$parentPart"

    val atraceCookie = workflowRuntimeTraceContext.runtimeName.hashCode() * sessionId.toInt()
    it.workflowAsyncSections[sessionId] = NameAndCookie(asyncSectionName, atraceCookie)
    it.workflowShortNamesById[sessionId] = shortName

    trace.beginAsyncSection(asyncSectionName, atraceCookie)

    // Reason for render pass if we are the root.
    if (session.isRootWorkflow) {
      // This could be the first thing that happens after a trace has finished, so check if we
      // need
      // to reset it here.
      it.resetTraceCountsIfNotTracing()
      it.renderPassTriggerCount++
      trace.beginSection(
        "CREATE_RENDER${it.renderPassTriggerCount}, Runner:$workflowRuntimeTraceContext.runtimeName"
      )
      // These are both short, but CAUSE: is long in the regular case, so leave it as a separate
      // info section.
      infoSection("SUM:${it.renderPassTriggerCount}: Skipped:N, StateChange:Y")
      infoSection("CAUSE:${it.renderPassTriggerCount}: RootWFCreated:W($${session.name})")
    }
  }
}

  trace.endSection()
}
if (runtimeUpdate == RuntimeSettled) {
  // Build and add the summary!
  val summary = buildString {
    append("SUM${renderPassNumber()} ")
    append(configSnapshot.shortConfigAsString)
    append("StateChange:")
    if (currentActionHandlingChangedState) {
      append("Y, ")
    } else {
      append("N, ")
    }
  }
  infoSection(summary)
}

/** SECTION: [WorkflowInterceptor] override methods. * */
override fun <P, S> onInitialState(
  props: P,
  snapshot: Snapshot?,
  workflowScope: CoroutineScope,
  proceed: (P, Snapshot?, CoroutineScope) -> S,
  session: WorkflowSession,
): S {
  return trace(systemTraceLabel = { "InitialState ${session.traceName}" }) {
    proceed(props, snapshot, workflowScope)
  }
}

