  // action in the cascade to get a useful ref on which Worker's handler was firing. This is
  // because Workers use an underlying Workflow and an intermediate action, which is the
  // QueuedAction, in their implementation. So yes, we use an implementation detail here to
  // detect that. The issue still tracks upstreaming this into the library.
  val isWorkerQueuedAction = actionName.contains(Worker.WORKER_OUTPUT_ACTION_NAME)
  if (actionType is QueuedAction) {
    if (isSystemTraceable) {
      trace.beginSection(
        "MAYBE_RENDER${++systemTraceState!!.renderPassTriggerCount}:" +
          " $actionIndex," +
          " Runner:${workflowRuntimeTraceContext.runtimeName}"
      )
    }
  }
  val (_, actionApplied) =
    trace(
      systemTraceLabel = {
        val actionNameOrBlank = actionName.ifBlank { "" }
        val queuedApplyName =
          if (isWorkerQueuedAction) {
            "$workflowName(key=${actionNameOrBlank.workerKey()})"
          } else {
            actionNameOrBlank
          }
        if (actionType is CascadeAction) {
          "CascadeApply:$queuedApplyName," +
            " Cause:${workflowRuntimeTraceContext.renderIncomingCauses.lastOrNull()}"
        } else {
          "QueuedApply:$queuedApplyName"
        }
      }
    ) {
      delegateAction.applyTo(props, state).also { (newState, actionApplied) ->
        state = newState
        actionApplied.output?.let { setOutput(it.value) }
      }
    }

  if (isRoot || actionApplied.output == null) {
    // This action's application is ending a cascade, let's sum up what happened
    sumUpActionCascade()
  }
}

private inline fun <T> trace(
  crossinline systemTraceLabel: () -> String,
  crossinline block: () -> T,
): T {
  val systemTrace = isCurrentlySystemTracing
  if (systemTrace) {
    trace.beginSection(systemTraceLabel())
  }
  try {
    return block()
  } finally {
    if (systemTrace) {
      trace.endSection()
    }
  }
}

internal class ChainedWorkflowRuntimeTracer(private val tracers: List<WorkflowRuntimeTracer>) :
  WorkflowRuntimeTracer() {

  override fun onRootPropsChanged(session: WorkflowSession) {
    tracers.forEach { it.onRootPropsChanged(session) }
  }

  override fun attachRuntimeContext(workflowRuntimeTraceContext: RuntimeTraceContext) {
    tracers.forEach { it.attachRuntimeContext(workflowRuntimeTraceContext) }
  }

  override fun onWorkflowSessionStarted(workflowScope: CoroutineScope, session: WorkflowSession) {
    tracers.forEach { it.onWorkflowSessionStarted(workflowScope, session) }
  }

  override fun onWorkflowSessionStopped(sessionId: Long) {
    tracers.forEach { it.onWorkflowSessionStopped(sessionId) }
  }

  override fun onRuntimeUpdateEnhanced(
    runtimeUpdate: RuntimeUpdate,
    currentActionHandlingChangedState: Boolean,
    configSnapshot: ConfigSnapshot,
  ) {
    tracers.forEach {
      it.onRuntimeUpdateEnhanced(runtimeUpdate, currentActionHandlingChangedState, configSnapshot)
    }
  }

  override fun <P, S> onInitialState(
    props: P,
    snapshot: Snapshot?,
    workflowScope: CoroutineScope,
    proceed: (P, Snapshot?, CoroutineScope) -> S,
    session: WorkflowSession,
  ): S {
    val chainedProceed =
      tracers.foldRight(proceed) { workflowRuntimeTracer, proceedAcc ->
        { props, snapshot, workflowScope ->
          workflowRuntimeTracer.onInitialState(props, snapshot, workflowScope, proceedAcc, session)
        }
      }
    return chainedProceed(props, snapshot, workflowScope)
  }

  override fun <P, S> onPropsChanged(
    old: P,
    new: P,
    state: S,
    proceed: (P, P, S) -> S,
    session: WorkflowSession,
  ): S {
    val chainedProceed =
      tracers.foldRight(proceed) { workflowRuntimeTracer, proceedAcc ->
        { old, new, state ->
          workflowRuntimeTracer.onPropsChanged(old, new, state, proceedAcc, session)
        }
      }
    return chainedProceed(old, new, state)
  }

  override fun <P, R> onRenderAndSnapshot(
    renderProps: P,
    proceed: (P) -> RenderingAndSnapshot<R>,
    session: WorkflowSession,
  ): RenderingAndSnapshot<R> {
    val chainedProceed =
      tracers.foldRight(proceed) { workflowRuntimeTracer, proceedAcc ->
        { renderProps ->
          workflowRuntimeTracer.onRenderAndSnapshot(renderProps, proceedAcc, session)
        }
      }
    return chainedProceed(renderProps)
  }

  override fun <P, S, O, R> onRender(
    renderProps: P,
    renderState: S,
    context: BaseRenderContext<P, S, O>,
    proceed: (P, S, RenderContextInterceptor<P, S, O>?) -> R,
    session: WorkflowSession,
  ): R {
    val chainedProceed =
      tracers.foldRight(proceed) { workflowRuntimeTracer, proceedAcc ->
        { props, state, outerContextInterceptor ->
          workflowRuntimeTracer.onRender(
            props,
            state,
            context,
            proceed = { p, s, innerContextInterceptor: RenderContextInterceptor<P, S, O>? ->
              val contextInterceptor = outerContextInterceptor.wrap(innerContextInterceptor)
              proceedAcc(p, s, contextInterceptor)
            },
            session = session,
          )
        }
      }
    return chainedProceed(renderProps, renderState, null)
  }

  override fun onSnapshotStateWithChildren(
    proceed: () -> TreeSnapshot,
    session: WorkflowSession,
  ): TreeSnapshot {
    val chainedProceed =
      tracers.foldRight(proceed) { workflowRuntimeTracer, proceedAcc ->
        { workflowRuntimeTracer.onSnapshotStateWithChildren(proceedAcc, session) }
      }
    return chainedProceed()
  }

  override fun <S> onSnapshotState(
    state: S,
    proceed: (S) -> Snapshot?,
    session: WorkflowSession,
  ): Snapshot? {
    val chainedProceed =
      tracers.foldRight(proceed) { workflowRuntimeTracer, proceedAcc ->
        { state -> workflowRuntimeTracer.onSnapshotState(state, proceedAcc, session) }
      }
    return chainedProceed(state)
  }
}

