  super.onRuntimeUpdate(update)
}

public class WorkflowSessionInfo(public val name: String, public val key: String) {

  public constructor(
    session: WorkflowSession
  ) : this(
    name = session.identifier.toWfLoggingName(),
    // Keys can be long, ellipsize
    key = session.renderKey.wfEllipsizeEnd(MAX_KEY_LENGTH),
  )

  public val logName: String =
    if (key.isEmpty()) {
      name
    } else {
      "$name($key)"
    }

  public val traceName: String = logName.wfEllipsizeEnd(MAX_TRACE_NAME_LENGTH)

  companion object {

    /**
     * Reasonable limits so that we can get more concatenated info into trace section labels capped
     * at 127 chars.
     */
    const val MAX_KEY_LENGTH: Int = 15
    const val MAX_TRACE_NAME_LENGTH: Int = 50
  }
}

internal fun placeholderScreenComposableFactory(
  modifier: Modifier
): ScreenComposableFactory<Screen> = ScreenComposableFactory { rendering ->
  BasicText(
    modifier =
      modifier
        .clipToBounds()
        .drawBehind {
          drawIntoCanvas { canvas ->
            canvas.withSaveLayer(size.toRect(), Paint().apply { alpha = .2f }) {
              canvas.drawRect(size.toRect(), Paint().apply { color = Color.Gray })
              drawCrossHatch(color = Color.Red, strokeWidth = 2.dp, spaceWidth = 8.dp)
            }
          }
        }
        .padding(8.dp),
    text = rendering.toString(),
    style =
      TextStyle(
        textAlign = TextAlign.Center,
        color = Color.White,
        shadow = Shadow(blurRadius = 5f, color = Color.Black),
      ),
  )
}

@Composable
internal fun rememberPreviewViewEnvironment(
  placeholderModifier: Modifier,
  viewEnvironmentUpdater: ((ViewEnvironment) -> ViewEnvironment)? = null,
  mainFactory: ScreenComposableFactory<*>? = null,
): ViewEnvironment {
  val composableFactoryFinder =
    remember(mainFactory, placeholderModifier) {
      PreviewScreenComposableFactoryFinder(
        mainFactory,
        placeholderScreenComposableFactory(placeholderModifier),
      )
    }
  val screenFactoryFinder =
    remember(mainFactory, placeholderModifier) {
      PreviewScreenViewFactoryFinder(
        mainFactory?.asViewFactory(),
        placeholderScreenComposableFactory(placeholderModifier).asViewFactory(),
      )
    }
  return remember(composableFactoryFinder, viewEnvironmentUpdater) {
    (ViewEnvironment.EMPTY +
        (ScreenComposableFactoryFinder to composableFactoryFinder) +
        (ScreenViewFactoryFinder to screenFactoryFinder))
      .let { environment ->
        // Give the preview a chance to add its own elements to the ViewEnvironment.
        viewEnvironmentUpdater?.let { it(environment) } ?: environment
      }
  }
}

@Immutable
private class PreviewScreenComposableFactoryFinder<RenderingT : Screen>(
  private val mainFactory: ScreenComposableFactory<RenderingT>? = null,
  private val placeholderFactory: ScreenComposableFactory<Screen>,
) : ScreenComposableFactoryFinder {
  override fun <ScreenT : Screen> getComposableFactoryForRendering(
    environment: ViewEnvironment,
    rendering: ScreenT,
  ): ScreenComposableFactory<ScreenT> =
    // This `isInstance()` check is a bit sketchy b/c the real code insists on
    // the types being exactly the same, but this is the easiest way to keep
    // ComposeScreen, AndroidScreen working.
    if (mainFactory?.type?.isInstance(rendering) == true) {
      @Suppress("UNCHECKED_CAST")
      mainFactory as ScreenComposableFactory<ScreenT>
    } else {
      placeholderFactory
    }
}

@Immutable
private class PreviewScreenViewFactoryFinder<RenderingT : Screen>(
  private val mainFactory: ScreenViewFactory<RenderingT>? = null,
  private val placeholderFactory: ScreenViewFactory<Screen>,
) : ScreenViewFactoryFinder {
  override fun <ScreenT : Screen> getViewFactoryForRendering(
    environment: ViewEnvironment,
    rendering: ScreenT,
  ): ScreenViewFactory<ScreenT> =
    @Suppress("UNCHECKED_CAST")
    if (rendering::class == mainFactory?.type) {
      mainFactory as ScreenViewFactory<ScreenT>
    } else {
      placeholderFactory
    }
}

@Composable
public fun Screen.Preview(
  modifier: Modifier = Modifier,
  placeholderModifier: Modifier = Modifier,
  viewEnvironmentUpdater: ((ViewEnvironment) -> ViewEnvironment)? = null,
) {
  val factoryEnv = (viewEnvironmentUpdater?.invoke(ViewEnvironment.EMPTY) ?: ViewEnvironment.EMPTY)

  factoryEnv[ScreenComposableFactoryFinder]
    .getComposableFactoryForRendering(factoryEnv, this)
    ?.Preview(this, modifier, placeholderModifier, viewEnvironmentUpdater)
    ?.also {
      return
    }

  factoryEnv[ScreenViewFactoryFinder]
    .getViewFactoryForRendering(factoryEnv, this)
    ?.Preview(this, modifier, placeholderModifier, viewEnvironmentUpdater)
}

@Composable
public fun <RenderingT : Screen> ScreenComposableFactory<RenderingT>.Preview(
  rendering: RenderingT,
  modifier: Modifier = Modifier,
  placeholderModifier: Modifier = Modifier,
  viewEnvironmentUpdater: ((ViewEnvironment) -> ViewEnvironment)? = null,
) {
  val previewEnvironment =
    rememberPreviewViewEnvironment(placeholderModifier, viewEnvironmentUpdater, mainFactory = this)
  previewEnvironment.RootScreen(rendering, modifier)
}

@Composable
public fun <RenderingT : Screen> ScreenViewFactory<RenderingT>.Preview(
  rendering: RenderingT,
  modifier: Modifier = Modifier,
  placeholderModifier: Modifier = Modifier,
  viewEnvironmentUpdater: ((ViewEnvironment) -> ViewEnvironment)? = null,
) {
  asComposableFactory().Preview(rendering, modifier, placeholderModifier, viewEnvironmentUpdater)
}

@Composable
internal fun rememberChildLifecycleOwner(
  parentLifecycle: Lifecycle = LocalLifecycleOwner.current.lifecycle
): LifecycleOwner {
  val owner = remember { ComposeLifecycleOwner.installOn(initialParentLifecycle = parentLifecycle) }
  val lifecycleOwner =
    remember(parentLifecycle) { owner.apply { updateParentLifecycle(parentLifecycle) } }
  return lifecycleOwner
}

public inline fun ComposeScreen(crossinline content: @Composable () -> Unit): ComposeScreen =
  object : ComposeScreen {
    @Composable
    override fun Content() {
      content()
    }
  }

public fun ScreenComposableFactoryFinder.withCompositionRoot(
  root: CompositionRoot
): ScreenComposableFactoryFinder {
  return mapFactories { factory ->
    @Suppress("UNCHECKED_CAST")
    (factory as? ScreenComposableFactory<Screen>)?.let { composeFactory ->
      ScreenComposableFactory(composeFactory.type) { rendering ->
        WrappedWithRootIfNecessary(root) { composeFactory.Content(rendering) }
      }
    } ?: factory
  }
}

@VisibleForTesting(otherwise = PRIVATE)
@Composable
internal fun WrappedWithRootIfNecessary(root: CompositionRoot, content: @Composable () -> Unit) {
  if (LocalHasViewFactoryRootBeenApplied.current) {
    // The only way this local can have the value true is if, somewhere above this point in the
    // composition, the else case below was hit and wrapped us in the local. Since the root
    // wrapper will have already been applied, we can just compose content directly.
    content()
  } else {
    // If the local is false, this is the first time this function has appeared in the composition
    // so far. We provide a true value for the local for everything below us, so any recursive
    // calls to this function will hit the if case above and not re-apply the wrapper.
    CompositionLocalProvider(LocalHasViewFactoryRootBeenApplied provides true) { root(content) }
  }
}

  content()
} else {
  // If the local is false, this is the first time this function has appeared in the composition
  // so far. We provide a true value for the local for everything below us, so any recursive
  // calls to this function will hit the if case above and not re-apply the wrapper.
  CompositionLocalProvider(LocalHasViewFactoryRootBeenApplied provides true) { root(content) }
}

@VisibleForTesting(otherwise = VisibleForTesting.PRIVATE)
@Composable
internal fun <PropsT, OutputT : Any, RenderingT> renderAsState(
  workflow: Workflow<PropsT, OutputT, RenderingT>,
  scope: CoroutineScope,
  props: PropsT,
  interceptors: List<WorkflowInterceptor>,
  runtimeConfig: RuntimeConfig = RuntimeConfigOptions.DEFAULT_CONFIG,
  onOutput: suspend (OutputT) -> Unit,
  snapshotKey: String? = null,
): State<RenderingT> {
  val snapshotState = rememberTreeSnapshotState(snapshotKey)
  val updatedOnOutput by rememberUpdatedState(onOutput)

  // We can't use DisposableEffect because it won't run until the composition is successfully
  // committed, which will be after this function returns, and we need to run this immediately so we
  // get the rendering synchronously. The thread running this composition might also not be the
  // main thread or whatever thread the workflow context is configured to run on, but that should
  // be fine as long as the workflows are correctly performing side effects in effects and not their
  // render or related methods.
  // The WorkflowState object remembered here is a RememberObserver – it will automatically cancel
  // the workflow runtime when it leaves the composition or if the composition doesn't commit.
  // The remember is keyed on any values that we can't update the runtime with dynamically, and
  // therefore require completely restarting the runtime to take effect.
  val state =
    remember(workflow, scope, interceptors) {
      WorkflowRuntimeState<PropsT, OutputT, RenderingT>(
          workflowScope = scope,
          initialProps = props,
          snapshotState = snapshotState,
          runtimeConfig = runtimeConfig,
          onOutput = { updatedOnOutput(it) },
        )
        .apply { start(workflow, interceptors) }
    }

  // Use a side effect to update props so that it waits for the composition to commit.
  SideEffect { state.setProps(props) }

  return state.rendering
}

private class WorkflowRuntimeState<PropsT, OutputT : Any, RenderingT>(
  workflowScope: CoroutineScope,
  initialProps: PropsT,
  private val snapshotState: MutableState<TreeSnapshot?>,
  private val runtimeConfig: RuntimeConfig = RuntimeConfigOptions.DEFAULT_CONFIG,
  private val onOutput: suspend (OutputT) -> Unit,
) : RememberObserver {

  private lateinit var renderingState: MutableState<RenderingT>
  private val propsFlow = MutableStateFlow(initialProps)

  /**
   * The actual scope used to run the workflow. It has a child [Job] of the incoming scope so we can
   * cancel the runtime without cancelling the incoming scope.
   */
  private val workflowScope = workflowScope + Job(parent = workflowScope.coroutineContext[Job])

  /** Only valid after [start] returns. */
  val rendering: State<RenderingT>
    get() = renderingState

  fun start(
    workflow: Workflow<PropsT, OutputT, RenderingT>,
    interceptors: List<WorkflowInterceptor>,
  ) {
    val renderings =
      renderWorkflowIn(
        workflow = workflow,
        scope = workflowScope,
        props = propsFlow,
        // This is only the starting value, so don't make the caller observe it. Otherwise the
        // runtime's first snapshot write in the collector below can invalidate the caller.
        initialSnapshot = withoutReadObservation { snapshotState.value },
        interceptors = interceptors,
        runtimeConfig = runtimeConfig,
        onOutput = onOutput,
      )

    // Create the state only after starting the runtime, seeded with the initial rendering. Starting
    // the runtime may take nested snapshots of the current snapshot (the compose runtime runs its
    // own composition), which advances the current snapshot's ID. When this is called from
    // composition, writing to a state object created before that advance would be recorded as a
    // modification and invalidate the caller as soon as the composition is applied. If the caller
    // also restarts the runtime when it recomposes (e.g. it passes a new workflow instance each
    // time), that would recompose forever. Creating the state here means the collector's first,
    // equal write below is a no-op.
    renderingState = mutableStateOf(renderings.value.rendering)

    workflowScope.launch(start = UNDISPATCHED, context = Dispatchers.Unconfined) {
      // We collect the renderings in the workflowScope to participate in structured concurrency,
      // however we don't need to use its dispatcher – this collector is simply setting snapshot
      // state values, which is thread safe.
      // Also, if the scope uses a non-immediate dispatcher, the initial states won't get set until
      // the dispatcher dispatches the collection coroutine, but our contract requires them to be
      // set by the time this function returns and using the Unconfined dispatcher along with
      // launching this coroutine as CoroutineStart.UNDISPATCHED guarantees that.

      renderings.collect {
        renderingState.value = it.rendering
        snapshotState.value = it.snapshot
      }
    }
  }

  fun setProps(props: PropsT) {
    propsFlow.value = props
  }

  override fun onAbandoned() {
    workflowScope.cancel()
  }

  override fun onRemembered() {}

  override fun onForgotten() {
    workflowScope.cancel()
  }
}

public fun <ScreenT : Screen> ScreenT.toComposableFactory(
  environment: ViewEnvironment
): ScreenComposableFactory<ScreenT> {
  return environment[ScreenComposableFactoryFinder].requireComposableFactoryForRendering(
    environment,
    this,
  )
}

public fun <ScreenT : Screen> ScreenComposableFactory<ScreenT>.asViewFactory():
  ScreenViewFactory<ScreenT> {

  return object : ScreenViewFactory<ScreenT> {
    override val type = this@asViewFactory.type

    override fun buildView(
      initialRendering: ScreenT,
      initialEnvironment: ViewEnvironment,
      context: Context,
      container: ViewGroup?,
    ): ScreenViewHolder<ScreenT> {
      val view = ComposeView(context)
      return ScreenViewHolder(initialEnvironment, view) { newRendering, environment ->

        // Update the state whenever a new rendering is emitted.
        // This lambda will be executed synchronously before ScreenViewHolder.show returns.
        view.setContent {
          val onBackOrNull =
            remember(environment) {
              environment.map[OnBackPressedDispatcherOwnerKey] as? OnBackPressedDispatcherOwner
            }
          if (onBackOrNull == null) {
            CompositionLocalProvider(LocalWorkflowEnvironment provides environment) {
              Content(newRendering)
            }
          } else {
            CompositionLocalProvider(
              LocalWorkflowEnvironment provides environment,
              LocalOnBackPressedDispatcherOwner provides onBackOrNull,
            ) {
              Content(newRendering)
            }
          }
        }
      }
    }
  }
}

public fun <ScreenT : Screen> ScreenViewFactory<ScreenT>.asComposableFactory():
  ScreenComposableFactory<ScreenT> {
  return object : ScreenComposableFactory<ScreenT> {
    private val viewFactory = this@asComposableFactory

    override val type: KClass<in ScreenT>
      get() = viewFactory.type

    /**
     * This is effectively the logic of `WorkflowViewStub`, but translated into Compose idioms. This
     * approach has a few advantages:
     *
     * - Avoids extra custom views required to host `WorkflowViewStub` inside a Composition. Its
     *   trick of replacing itself in its parent doesn't play nicely with Compose.
     * - Allows us to pass the correct parent view for inflation (the root of the composition).
     * - Avoids `WorkflowViewStub` having to do its own lookup to find the correct
     *   [ScreenViewFactory], since we already have the correct one.
     * - Propagate the current `LifecycleOwner` from [LocalLifecycleOwner] by setting it as the
     *   [ViewTreeLifecycleOwner] on the view.
     * - Propagate the current [OnBackPressedDispatcherOwner] from either
     *   [LocalOnBackPressedDispatcherOwner] or the [viewEnvironment], both on the [AndroidView] via
     *   [setViewTreeOnBackPressedDispatcherOwner], and in the [ViewEnvironment] for use by any
     *   nested [WorkflowViewStub]
     *
     * Like `WorkflowViewStub`, this function uses the [viewFactory] to create and memoize a `View`
     * to display the [rendering], keeps it updated with the latest [rendering] and adds it to the
     * composition.
     */
    @Composable
    override fun Content(rendering: ScreenT) {
      val lifecycleOwner = LocalLifecycleOwner.current
      val renderingKey = Compatible.keyFor(rendering)
      val parentSavedStateRegistryOwner = LocalSavedStateRegistryOwner.current
      val savedStateRegistry =
        rememberViewFactorySavedStateRegistry(
          renderingKey = renderingKey,
          parent = parentSavedStateRegistryOwner,
        )
      val environment = LocalWorkflowEnvironment.current

      // Make sure any nested WorkflowViewStub will be able to propagate the
      // OnBackPressedDispatcherOwner, if we found one. No need to fail fast here.
      // It's only an issue if someone tries to use it, and the error message
      // at those call sites should be clear enough.
      val onBackOrNull = LocalOnBackPressedDispatcherOwner.current

      val envWithOnBack =
        remember(onBackOrNull, environment) {
          onBackOrNull?.let { environment + (OnBackPressedDispatcherOwnerKey to it) } ?: environment
        }

      AndroidView(
        factory = { context ->

          // We pass in a null container because the container isn't a View, it's a composable. The
          // compose machinery will generate an intermediate view that it ends up adding this to but
          // we don't have access to that.
          viewFactory.startShowing(rendering, envWithOnBack, context, container = null).let {
            viewHolder ->
            // Put the viewHolder in a tag so that we can find it in the update lambda, below.
            viewHolder.view.setTag(R.id.workflow_screen_view_holder, viewHolder)

            // Unfortunately AndroidView doesn't propagate these itself.
            viewHolder.view.setViewTreeLifecycleOwner(lifecycleOwner)
            savedStateRegistry.installOn(viewHolder.view)
            onBackOrNull?.let { viewHolder.view.setViewTreeOnBackPressedDispatcherOwner(it) }

            viewHolder.view
          }
        },
        // This function will be invoked every time this composable is recomposed, which means that
        // any time a new rendering or view environment are passed in we'll send them to the view.
        update = { view ->
          @Suppress("UNCHECKED_CAST")
          val viewHolder =
            view.getTag(R.id.workflow_screen_view_holder) as ScreenViewHolder<ScreenT>

          // Compose runs this block inside SnapshotStateObserver.observeReads, so every snapshot
          // state read that happens while we update the view is recorded against the window hosting
          // this composition -- including reads made by code that show() calls synchronously.
          //
          // That is a leak when showing a rendering tears a window down. Dropping an Overlay from a
          // BodyAndOverlaysScreen dismisses its Dialog from right here, and if that Dialog was
          // showing a composition, its AndroidComposeView reads its own viewTreeOwners while
          // detaching. viewTreeOwners is a derivedStateOf, and a recorded derived state read is
          // released only once this view stops reading it -- either on a later update of this
          // block, or when the view is detached. So the dismissed view, and through it the whole
          // Dialog window, can remain reachable from the process-wide snapshot observer list for
          // as long as we stay attached and this block does not run again.
          //
          // Nothing is lost by not observing: these views are updated by the workflow runtime
          // calling show(), not by snapshot state changing.
          //
          // That last part is a constraint on what may be read in here, so keep it in mind when
          // changing this block. Anything read inside withoutReadObservation is invisible to
          // Compose, so it will not re-run this block when it changes. rendering and envWithOnBack
          // are plain values, read before we get here. If either ever becomes snapshot state -- a
          // rememberUpdatedState, a MutableState, a derivedStateOf -- read it outside this lambda
          // into a local and pass the local in, or the view will silently stop being updated.
          Snapshot.withoutReadObservation { viewHolder.show(rendering, envWithOnBack) }
        },
      )
    }
  }
}

viewFactory.startShowing(rendering, envWithOnBack, context, container = null).let {
  viewHolder ->
  // Put the viewHolder in a tag so that we can find it in the update lambda, below.
  viewHolder.view.setTag(R.id.workflow_screen_view_holder, viewHolder)

  // Unfortunately AndroidView doesn't propagate these itself.
  viewHolder.view.setViewTreeLifecycleOwner(lifecycleOwner)
  savedStateRegistry.installOn(viewHolder.view)
  onBackOrNull?.let { viewHolder.view.setViewTreeOnBackPressedDispatcherOwner(it) }

  viewHolder.view
}

viewHolder.view.setViewTreeLifecycleOwner(lifecycleOwner)
savedStateRegistry.installOn(viewHolder.view)
onBackOrNull?.let { viewHolder.view.setViewTreeOnBackPressedDispatcherOwner(it) }

@Composable
private fun rememberViewFactorySavedStateRegistry(
  renderingKey: String,
  parent: SavedStateRegistryOwner,
): ViewFactorySavedStateRegistry {
  val parentKey = "$VIEW_FACTORY_SAVED_STATE_KEY_PREFIX:$renderingKey#$currentCompositeKeyHashCode"
  return remember(parent, parentKey) {
    ViewFactorySavedStateRegistry(childKey = renderingKey, parentKey = parentKey, parent = parent)
  }
}

private class ViewFactorySavedStateRegistry(
  private val childKey: String,
  parentKey: String,
  parent: SavedStateRegistryOwner,
) : RememberObserver {
  private val aggregator =
    WorkflowSavedStateRegistryAggregator().apply { attachToParentRegistry(parentKey, parent) }

  fun installOn(view: android.view.View) {
    aggregator.installChildRegistryOwnerOn(view, childKey, force = true)
  }

  override fun onRemembered() = Unit

  override fun onForgotten() {
    aggregator.detachFromParentRegistry()
  }

  override fun onAbandoned() {
    aggregator.detachFromParentRegistry()
  }
}

