public fun <ScreenT : Screen> ScreenViewHolder<ScreenT>.startShowing(
  initialRendering: ScreenT,
  initialEnvironment: ViewEnvironment,
  viewStarter: ViewStarter?,
) {
  val resolvedStarter = viewStarter ?: ViewStarter { _, doStart -> doStart() }

  var shown = false
  resolvedStarter.startView(view) {
    show(initialRendering, initialEnvironment)
    shown = true
  }
  check(shown) {
    "$viewStarter neglected to call the given doStart() function when showing $initialRendering"
  }
}

public fun interface ViewStarter {
  /** Called from [ScreenViewFactory.startShowing]. [doStart] must be invoked. */
  public fun startView(view: View, doStart: () -> Unit)
}

public fun <ScreenT : Screen> ScreenViewFactory<ScreenT>.startShowing(
  initialRendering: ScreenT,
  initialEnvironment: ViewEnvironment,
  contextForNewView: Context,
  container: ViewGroup? = null,
  viewStarter: ViewStarter? = null,
): ScreenViewHolder<ScreenT> {
  return buildView(initialRendering, initialEnvironment, contextForNewView, container).apply {
    startShowing(initialRendering, initialEnvironment, viewStarter)
  }
}

public interface ScreenViewHolder<in ScreenT : Screen> {
  /** The [View] managed by this holder, and updated via [runner] */
  public val view: View

  /** The [ViewEnvironment] that was provided the last time [view] was updated by [runner]. */
  public val environment: ViewEnvironment

  /**
   * The function that is run by [show] to update [view] with a new [Screen] rendering and
   * [ViewEnvironment].
   *
   * Prefer calling [show] to using this directly, to ensure that [screenOrNull] is maintained
   * correctly, and [showing] keeps working.
   */
  public val runner: ScreenViewRunner<ScreenT>

  public companion object {
    public operator fun <ScreenT : Screen> invoke(
      initialEnvironment: ViewEnvironment,
      view: View,
      viewRunner: ScreenViewRunner<ScreenT>,
    ): ScreenViewHolder<ScreenT> {
      return RealScreenViewHolder(initialEnvironment, view, viewRunner)
    }
  }
}

public fun ScreenViewHolder<*>.canShow(screen: Screen): Boolean {
  // The null case covers bootstrapping, during the first call to show()
  // from ScreenViewFactory.start().
  return view.screenOrNull?.let { compatible(it, screen) } ?: true
}

public fun <ScreenT : Screen> ScreenViewHolder<ScreenT>.show(
  screen: ScreenT,
  environment: ViewEnvironment,
) {
  // Why is this an extension rather than part of the interface?
  // When wrapping, we need to prevent recursive calls from clobbering
  // `screenOrNull` with the nested rendering type.
  view.screen = screen
  runner.showRendering(screen, environment)
}

public fun Parcelable.toSnapshot(): Snapshot {
  return Snapshot.write { bufferedSink ->
    val parcel = Parcel.obtain()
    parcel.writeParcelable(this, 0)
    val byteArray = parcel.marshall()
    bufferedSink.write(byteArray)
    parcel.recycle()
  }
}

