public class WorkflowLayout(context: Context, attributeSet: AttributeSet? = null) :
  FrameLayout(context, attributeSet) {
  init {
    if (id == NO_ID) id = R.id.workflow_layout
  }

  private val showing: WorkflowViewStub =
    WorkflowViewStub(context).also { rootStub ->
      rootStub.updatesVisibility = false
      rootStub.propagatesLayoutParams = false
      addView(rootStub)
    }

  private var restoredChildState: SparseArray<Parcelable>? = null

  /**
   * Calls [WorkflowViewStub.show] on the [WorkflowViewStub] that is the only child of this view.
   *
   * It's more common for a `Workflow`-based `Activity` or `Fragment` to use [take] than to call
   * this method directly. It is exposed to allow clients to make their own choices about how
   * exactly to consume a stream of renderings.
   */
  public fun show(rootScreen: Screen, environment: ViewEnvironment = ViewEnvironment.EMPTY) {
    showing.show(rootScreen, environment.withOnBackDispatcher())
    restoredChildState?.let { restoredState ->
      restoredChildState = null
      try {
        showing.actual.restoreHierarchyState(restoredState)
      } catch (e: Exception) {
        Log.w("Workflow", "WorkflowLayout failed to restore view state", e)
      }
    }
  }

  /**
   * This is the most common way to bootstrap a [Workflow][com.squareup.workflow1.Workflow] driven
   * UI. Collects [renderings] and calls [show] with each one.
   *
   * To configure a root [ViewEnvironment], use
   * [EnvironmentScreen][com.squareup.workflow1.ui.EnvironmentScreen] as your root rendering type,
   * perhaps via [withEnvironment][com.squareup.workflow1.ui.withEnvironment] or
   * [withRegistry][com.squareup.workflow1.ui.withRegistry].
   *
   * @param [lifecycle] the lifecycle that defines when and how this view should be updated.
   *   Typically this comes from `ComponentActivity.lifecycle` or `Fragment.lifecycle`.
   * @param [repeatOnLifecycle] the lifecycle state in which renderings should be actively updated.
   *   Defaults to STARTED, which is appropriate for Activity and Fragment.
   * @param [collectionContext] additional [CoroutineContext] we want for the coroutine that is
   *   launched to collect the renderings, can include a different dispatcher - but we verify that
   *   it is a main thread dispatcher since we are updating views here!
   * @return the [Job] started to collect [renderings], to give callers the option to
   *   [cancel][Job.cancel] collection -- e.g., before calling [take] again with a new [renderings]
   *   flow. In most cases the caller can ignore this, interacting with the [Job] is very unusual.
   */
  @OptIn(ExperimentalStdlibApi::class)
  public fun take(
    lifecycle: Lifecycle,
    renderings: Flow<Screen>,
    repeatOnLifecycle: State = STARTED,
    collectionContext: CoroutineContext = EmptyCoroutineContext,
  ): Job {
    // Just like
    // https://medium.com/androiddevelopers/a-safer-way-to-collect-flows-from-android-uis-23080b1f8bda
    return lifecycle.coroutineScope.launch {
      lifecycle.repeatOnLifecycle(repeatOnLifecycle) {
        withContext(collectionContext) {
          require(Looper.myLooper() == Looper.getMainLooper()) {
            "Collection dispatch must happen on the main thread!"
          }
          renderings.collect { show(it) }
        }
      }
    }
  }

  override fun onSaveInstanceState(): Parcelable {
    return SavedState(
      super.onSaveInstanceState()!!,
      SparseArray<Parcelable>().also { array -> showing.actual.saveHierarchyState(array) },
    )
  }

  override fun onRestoreInstanceState(state: Parcelable?) {
    (state as? SavedState)?.let {
      restoredChildState = it.childState
      super.onRestoreInstanceState(state.superState)
    } ?: super.onRestoreInstanceState(super.onSaveInstanceState())
    // ?: Some other class wrote state, but we're not allowed to skip the call to super.
    // Make a no-op call.
  }

  /**
   * Attempts to seed the [ViewEnvironment] with an [OnBackPressedDispatcherOwnerKey] value if one
   * wasn't set already. We're priming the pump that our
   * `ViewEnvironment.onBackPressedDispatcherOwner` call relies on.
   */
  private fun ViewEnvironment.withOnBackDispatcher(): ViewEnvironment {
    val envWithOnBack =
      if (map.containsKey(OnBackPressedDispatcherOwnerKey)) {
        this
      } else {
        this@WorkflowLayout.onBackPressedDispatcherOwnerOrNull()?.let {
          this@withOnBackDispatcher + (OnBackPressedDispatcherOwnerKey to it)
        } ?: this
      }
    return envWithOnBack
  }

  private class SavedState : BaseSavedState {
    constructor(superState: Parcelable?, childState: SparseArray<Parcelable>) : super(superState) {
      this.childState = childState
    }

    constructor(source: Parcel) : super(source) {
      this.childState =
        if (VERSION.SDK_INT >= 33) {
          source.readSparseArray(SavedState::class.java.classLoader, Parcelable::class.java)!!
        } else {
          @Suppress("DEPRECATION") source.readSparseArray(SavedState::class.java.classLoader)!!
        }
    }

    val childState: SparseArray<Parcelable>

    override fun writeToParcel(out: Parcel, flags: Int) {
      super.writeToParcel(out, flags)
      @Suppress("UNCHECKED_CAST") out.writeSparseArray(childState as SparseArray<Any>)
    }

    companion object CREATOR : Creator<SavedState> {
      override fun createFromParcel(source: Parcel): SavedState = SavedState(source)

      override fun newArray(size: Int): Array<SavedState?> = arrayOfNulls(size)
    }
  }
}

public fun show(rootScreen: Screen, environment: ViewEnvironment = ViewEnvironment.EMPTY) {
  showing.show(rootScreen, environment.withOnBackDispatcher())
  restoredChildState?.let { restoredState ->
    restoredChildState = null
    try {
      showing.actual.restoreHierarchyState(restoredState)
    } catch (e: Exception) {
      Log.w("Workflow", "WorkflowLayout failed to restore view state", e)
    }
  }
}

private fun ViewEnvironment.withOnBackDispatcher(): ViewEnvironment {
  val envWithOnBack =
    if (map.containsKey(OnBackPressedDispatcherOwnerKey)) {
      this
    } else {
      this@WorkflowLayout.onBackPressedDispatcherOwnerOrNull()?.let {
        this@withOnBackDispatcher + (OnBackPressedDispatcherOwnerKey to it)
      } ?: this
    }
  return envWithOnBack
}

