    crossinline filter: RealtimePostgresFilterBuilder.() -> Unit = {}

suspend inline fun <reified Data : Any> RealtimeChannel.postgresSingleDataFlow(
    schema: String = "public",
    table: String,
    primaryKey: PrimaryKey<Data>,
    crossinline filter: PostgrestFilterBuilder.() -> Unit
): Flow<Data> {
    val (key, initialData) = try {
        val result = supabaseClient.postgrest.from(schema, table).select {
            limit(1)
            single()
            filter(filter)
        }
        val data = result.decodeAs<Data>()
        primaryKey.producer(data) to data
    } catch (e: UnknownRestException) {
        error("Data matching filter and table name $table not found")
    }
    val changeFlow = postgresChangeFlow<PostgresAction>(schema) {
        this.table = table
        filter(primaryKey.columnName, FilterOperator.EQ, key)
    }
    return channelFlow {
        trySend(initialData)
        changeFlow.collect {
            when (it) {
                is PostgresAction.Insert -> {
                    val data = it.decodeRecord<Data>()
                    trySend(data)
                }

                is PostgresAction.Update -> {
                    val data = it.decodeRecord<Data>()
                    trySend(data)
                }

                is PostgresAction.Delete -> {
                    close()
                }

                else -> {}
            }
        }
    }
}

enum class RealtimeProtocolVersion(val value: String) {
    /**
     * Protocol 1.0.0 — JSON object text frames for all messages.
     */
    V1("1.0.0"),
    /**
     * Protocol 2.0.0 — JSON array text frames for non-broadcast messages,
     * binary frames for broadcast messages
     */
    V2("2.0.0")
}

sealed interface BroadcastPayload {

    /**
     * JSON-encoded payload via [value]
     */
    data class Json(val value: JsonElement): BroadcastPayload

    /**
     * Binary payload via [data]
     */
    class Binary(val data: ByteArray): BroadcastPayload

}

class RealtimeBroadcast(
    val topic: String,
    val event: String,
    val payload: BroadcastPayload
)

internal fun String.decodeV2Text(): RealtimeMessage {
    val array = Json.decodeFromString<JsonArray>(this)
    if(array.size < 5) error("Expected array with 5 elements, got ${array.size}")
    val joinRef = array[0].jsonPrimitive.contentOrNull
    val ref = array[1].jsonPrimitive.contentOrNull
    val topic = array[2].jsonPrimitive.contentOrNull ?: error("Expected string for topic at index 2")
    val event = array[3].jsonPrimitive.contentOrNull ?: error("Expected string for event at index 3")
    val payload = array.getOrNull(4)?.jsonObject ?: error("Expected object for payload at index 4")
    return RealtimeMessage(topic, event, payload, ref, joinRef)
}

data object RBroadcastEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        val event = message.payload["event"]?.jsonPrimitive?.content ?: ""
        channel.callbackManager.triggerBroadcast(RealtimeBroadcast(message.topic, event, BroadcastPayload.Json(message.payload["payload"]?.jsonObject ?: JsonObject(mutableMapOf()))))
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_BROADCAST
    }

}

data object RCloseEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        channel.realtime.removeChannel(channel)
        channel.logger.d { "Unsubscribed from channel ${message.topic}" }
        channel.updateStatus(RealtimeChannel.Status.UNSUBSCRIBED)
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_CLOSE
    }

}

data object RErrorEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        channel as RealtimeChannelImpl
        // Only rejoin if the join itself was rejected
        if(message.event == RealtimeChannel.CHANNEL_EVENT_REPLY && channel.status.value != RealtimeChannel.Status.SUBSCRIBING) {
            channel.logger.e { "Push to channel ${message.topic} failed: ${message.payload}" }
            return
        }
        val currentAttempt = channel.joinAttempt.incrementAndFetch()
        if(currentAttempt >= channel.realtime.config.maxAttempts) {
            channel.logger.e { "Failed to rejoin channel ${message.topic} after $currentAttempt attempts. Giving up. ${message.payload}" }
            channel.updateStatus(RealtimeChannel.Status.UNSUBSCRIBED)
            return
        }
        channel.logger.e { "Received an error in channel ${message.topic}. That could be as a result of an invalid access token. Trying to rejoin the channel...\n${message.payload}" }
        channel.scheduleRejoin()
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_ERROR ||
            message.event == RealtimeChannel.CHANNEL_EVENT_REPLY && message.payload["status"]?.jsonPrimitive?.content == "error"
    }

}

data object RPostgresChangesEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        val data = message.payload["data"]?.jsonObject ?: return
        val ids = message.payload["ids"]?.jsonArray?.mapNotNull { it.jsonPrimitive.intOrNull } ?: emptyList() //the ids of the matching postgres changes
        val postgresAction = supabaseJson.decodeFromJsonElement<PostgresActionData>(data)
        val action = when(data["type"]?.jsonPrimitive?.content ?: "") {
            "UPDATE" -> PostgresAction.Update(
                postgresAction.record ?: error("Received no record on update event"),
                postgresAction.oldRecord ?: error("Received no old record on update event"),
                postgresAction.columns,
                postgresAction.commitTimestamp,
                channel.supabaseClient.realtime.serializer
            )
            "DELETE" -> PostgresAction.Delete(
                postgresAction.oldRecord ?: error("Received no old record on delete event"),
                postgresAction.columns,
                postgresAction.commitTimestamp,
                channel.supabaseClient.realtime.serializer
            )
            "INSERT" -> PostgresAction.Insert(
                postgresAction.record ?: error("Received no record on update event"),
                postgresAction.columns,
                postgresAction.commitTimestamp,
                channel.supabaseClient.realtime.serializer
            )
            "SELECT" -> PostgresAction.Select(
                postgresAction.record ?: error("Received no record on update event"),
                postgresAction.columns,
                postgresAction.commitTimestamp,
                channel.supabaseClient.realtime.serializer
            )
            else -> error("Unknown event type ${message.event}")
        }
        channel.callbackManager.triggerPostgresChange(ids, action)
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_POSTGRES_CHANGES
    }

}

data object RPostgresServerChangesEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        val serverPostgresChanges = message.payload["response"]?.jsonObject?.get("postgres_changes")?.jsonArray?.let { Json.decodeFromJsonElement<List<PostgresJoinConfig>>(it) } ?: listOf() //server postgres changes
        channel.callbackManager.setServerChanges(serverPostgresChanges)
        if(channel.status.value != RealtimeChannel.Status.SUBSCRIBED) {
            channel.logger.d { "Joined channel ${message.topic}" }
            channel.updateStatus(RealtimeChannel.Status.SUBSCRIBED)
        }
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        val hasPostgresChanges = message.payload["response"]?.jsonObject?.containsKey(RealtimeChannel.CHANNEL_EVENT_POSTGRES_CHANGES) ?: false
        return message.event == RealtimeChannel.CHANNEL_EVENT_REPLY && hasPostgresChanges && !RErrorEvent.appliesTo(message)
    }

}

data object RPresenceDiffEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        val joins = message.payload["joins"]?.jsonObject?.decodeIfNotEmptyOrDefault(mapOf<String, Presence>()) ?: emptyMap()
        val leaves = message.payload["leaves"]?.jsonObject?.decodeIfNotEmptyOrDefault(mapOf<String, Presence>()) ?: emptyMap()
        channel.callbackManager.triggerPresenceDiff(joins, leaves)
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_PRESENCE_DIFF
    }

}

data object RPresenceStateEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        val joins = message.payload.decodeIfNotEmptyOrDefault(mapOf<String, Presence>())
        val leaves = channel.callbackManager.presenceState().filterKeys { it !in joins }
        channel.callbackManager.triggerPresenceDiff(joins, leaves)
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_PRESENCE_STATE
    }

}

data object RSystemEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        if(message.payload["status"]?.jsonPrimitive?.content == "ok") {
            channel.logger.d { "Subscribed to channel ${message.topic}" }
            channel.updateStatus(RealtimeChannel.Status.SUBSCRIBED)
        } else {
            // e.g. a refused postgres_changes subscription. Like realtime-js, the channel stays joined.
            channel.logger.e { "Received an error in channel ${message.topic}: ${message.payload}" }
        }
        val payload = supabaseJson.decodeFromJsonElement<RealtimeSystemPayload>(message.payload)
        channel.callbackManager.triggerSystem(payload)
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_SYSTEM && message.payload["status"]?.jsonPrimitive?.content in setOf("ok", "error") &&
            !RTokenExpiredEvent.appliesTo(message)
    }

}

data object RSystemReplyEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        channel.logger.d { "Received system reply: ${message.payload}." }
        if(channel.status.value == RealtimeChannel.Status.UNSUBSCRIBING) {
            channel.updateStatus(RealtimeChannel.Status.UNSUBSCRIBED)
            channel.logger.d { "Unsubscribed from channel ${message.topic}" }
        }
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_REPLY && message.payload["status"]?.jsonPrimitive?.content == "ok" &&
            !RPostgresServerChangesEvent.appliesTo(message)
    }

}

data object RTokenExpiredEvent : RealtimeEvent {

    override suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage) {
        channel.logger.w { "Received token expired event. This should not happen, please report this warning." }
    }

    override fun appliesTo(message: RealtimeMessage): Boolean {
        return message.event == RealtimeChannel.CHANNEL_EVENT_SYSTEM && message.payload["message"]?.jsonPrimitive?.content?.contains("access token has expired") ?: false
    }

}

internal sealed interface RealtimeEvent {

    /**
     * Handles the event.
     * @param channel The channel the event was received on.
     * @param message The message that was received.
     */
    suspend fun handle(channel: RealtimeChannel, message: RealtimeMessage)

    /**
     * Checks if the event applies to the message.
     */
    fun appliesTo(message: RealtimeMessage): Boolean

    companion object {

        internal val EVENTS = setOf( // Kotlin doesn't provide a way to get all objects of a sealed interface outside the JVM, so we have to list them manually
            RBroadcastEvent,
            RCloseEvent,
            RErrorEvent,
            RPostgresChangesEvent,
            RPostgresServerChangesEvent,
            RPresenceStateEvent,
            RPresenceDiffEvent,
            RSystemEvent,
            RTokenExpiredEvent,
            RSystemReplyEvent
        )

        /**
         * Resolves the event from a realtime message.
         * The events' conditions don't overlap, so their order doesn't matter.
         */
        fun resolveEvent(realtimeMessage: RealtimeMessage): RealtimeEvent? {
            return EVENTS.firstOrNull { it.appliesTo(realtimeMessage) }
        }

    }

}

fun resolveEvent(realtimeMessage: RealtimeMessage): RealtimeEvent? {
    return EVENTS.firstOrNull { it.appliesTo(realtimeMessage) }
}

