class KtorRealtimeWebsocket(
    private val ws: DefaultClientWebSocketSession,
): RealtimeWebsocket {

    override val hasIncomingMessages: Boolean get() = ws.isActive
    internal val ref = AtomicInt(0)

    override fun makeRef(): String {
        return ref.fetchAndIncrement().toString()
    }

    override suspend fun receive(): Frame {
        return ws.incoming.receive()
    }

    override suspend fun send(message: RealtimeMessage, vsn: RealtimeProtocolVersion) {
        when(vsn) {
            RealtimeProtocolVersion.V1 -> ws.sendSerialized(message)
            RealtimeProtocolVersion.V2 -> ws.send(message.encodeV2Text())
        }
    }

    override suspend fun send(data: ByteArray) {
        ws.send(data)
    }

    override fun disconnect() {
        ws.cancel()
    }

    override suspend fun blockUntilDisconnect() {
        ws.coroutineContext.job.join()
    }

}

class KtorRealtimeWebsocketFactory(
    private val httpClient: HttpClient,
    ): RealtimeWebsocketFactory {

    override suspend fun create(url: String): RealtimeWebsocket {
        val ws = httpClient.webSocketSession(url)
        return KtorRealtimeWebsocket(ws)
    }

}

@OptIn(ExperimentalSubclassOptIn::class)
@SubclassOptInRequired(SupabaseInternal::class)
interface RealtimeWebsocket {

    /**
     * Whether there are incoming messages that can be received.
     */
    val hasIncomingMessages: Boolean

    /**
     * Generates a new ref for a realtime message
     */
    fun makeRef(): String

    /**
     * Receive a frame from the websocket.
     */
    suspend fun receive(): Frame

    /**
     * Send a message to the websocket.
     * @param message The message to send
     * @param vsn Depending on the vsn, the message gets encoded differently
     */
    suspend fun send(message: RealtimeMessage, vsn: RealtimeProtocolVersion)

    /**
     * Sends a binary message to the websocket.
     */
    suspend fun send(data: ByteArray)

    /**
     * Block the current coroutine until the websocket is disconnected.
     */
    suspend fun blockUntilDisconnect()

    /**
     * Disconnect the websocket.
     */
    fun disconnect()

}

@OptIn(ExperimentalSubclassOptIn::class)
@SubclassOptInRequired(SupabaseInternal::class)
