@JvmInline
value class Fingerprint private constructor(val value: String) {

    /**
     * The source of the file upload
     */
    val source get() = value.substringBeforeLast(FINGERPRINT_SEPARATOR)

    /**
     * The size of the data
     */
    val size get() = value.substringAfterLast(FINGERPRINT_SEPARATOR).toLong()

    companion object {

        /**
         * The amount of parts a fingerprint consists of (separator is "[FINGERPRINT_SEPARATOR]")
         */
        const val FINGERPRINT_PARTS = 2

        /**
         * The separator between the parts of the fingerprint
         */
        const val FINGERPRINT_SEPARATOR = "::"

        /**
         * Creates a fingerprint from the [source] and the [size] of the file
         */
        operator fun invoke(source: String, size: Long) = Fingerprint("$source$FINGERPRINT_SEPARATOR$size")

        /**
         * Creates a fingerprint from the [value]. Returns null if the [value] is not a valid fingerprint
         */
        operator fun invoke(value: String): Fingerprint? {
            if(!value.contains(FINGERPRINT_SEPARATOR)) return null
            if(value.substringAfterLast(FINGERPRINT_SEPARATOR).toLongOrNull() == null) return null
            return Fingerprint(value)
        }

    }

}

operator fun invoke(value: String): Fingerprint? {
    if(!value.contains(FINGERPRINT_SEPARATOR)) return null
    if(value.substringAfterLast(FINGERPRINT_SEPARATOR).toLongOrNull() == null) return null
    return Fingerprint(value)
}

class MemoryResumableCache(
    private val map: MutableMap<String, String> = AtomicMutableMap(),
) : ResumableCache {

    override suspend fun set(fingerprint: Fingerprint, entry: ResumableCacheEntry) {
        map[fingerprint.value] = Json.encodeToString(entry)
    }

    override suspend fun get(fingerprint: Fingerprint): ResumableCacheEntry? {
        return map[fingerprint.value]?.let {
            Json.decodeFromString(it)
        }
    }

    override suspend fun remove(fingerprint: Fingerprint) {
        map.remove(fingerprint.value)
    }

    override suspend fun clear() {
        map.clear()
    }

    override suspend fun entries(): List<CachePair> {
        return map.mapNotNull { (key, entry) ->
            Fingerprint(key)?.let { it to Json.decodeFromString<ResumableCacheEntry>(entry) }
        }
    }

}

interface ResumableCache {

    /**
     * Stores the [entry] for the [fingerprint]. The fingerprint consists of the bucket id, the file path and the file size
     */
    suspend fun set(fingerprint: Fingerprint, entry: ResumableCacheEntry)

    /**
     * Returns the resumable cache entry for the [fingerprint] or null if no url was stored
     */
    suspend fun get(fingerprint: Fingerprint): ResumableCacheEntry?

    /**
     * Removes the entry for the [fingerprint]
     */
    suspend fun remove(fingerprint: Fingerprint)

    /**
     * Clears the cache
     */
    suspend fun clear()

    /**
     * Returns all entries in the cache
     */
    suspend fun entries(): List<CachePair>

}

sealed interface ResumableUpload {

    /**
     * The current upload progress as a [StateFlow]. The [UploadStatus] contains the total bytes sent and the total size of the upload. At the end of the upload, the [UploadStatus] will be [UploadStatus.Success].
     */
    val stateFlow: StateFlow<ResumableUploadState>

    /**
     * The upload fingerprint
     */
    val fingerprint: Fingerprint

    /**
     * Pauses this upload after the current chunk has been uploaded. Can be resumed using [startOrResumeUploading].
     * If the upload is already paused, this method does nothing.
     */
    suspend fun pause()

    /**
     * Cancels this upload and removes the upload url from the cache.
     */
    suspend fun cancel()

    /**
     * Starts or resumes this upload. Location url may be retrieved from the cache, so can start of after your program crashed or the network reconnected.
     */
    suspend fun startOrResumeUploading()

}

