@SupabaseInternal
class AtomicMutableList<E>(
    vararg elements: E
) : MutableList<E> {

    private val list = AtomicReference(persistentListOf(*elements))

    override val size: Int
        get() = list.load().size

    override fun clear() {
        list.updateIfChanged { if (it.isEmpty()) it else persistentListOf() }
    }

    override fun addAll(elements: Collection<E>): Boolean {
        if(elements.isEmpty()) return false
        return list.updateIfChanged { current ->
            current.addAll(elements)
        }
    }

    override fun addAll(index: Int, elements: Collection<E>): Boolean {
        if(elements.isEmpty()) return false
        return list.updateIfChanged { current ->
            current.addAll(index, elements)
        }
    }

    override fun add(index: Int, element: E) = list.update { current ->
        current.add(index, element)
    }

    override fun add(element: E): Boolean = list.updateIfChanged { current ->
        current.add(element)
    }

    override fun get(index: Int): E = list.load()[index]

    override fun isEmpty(): Boolean = list.load().isEmpty()

    override fun iterator(): MutableIterator<E> = list.load().toMutableList().iterator()

    override fun listIterator(): MutableListIterator<E> = list.load().toMutableList().listIterator()

    override fun listIterator(index: Int): MutableListIterator<E> = list.load().toMutableList().listIterator(index)

    override fun subList(fromIndex: Int, toIndex: Int): MutableList<E> =
        list.load().subList(fromIndex, toIndex).toMutableList()

    override fun set(index: Int, element: E): E {
        while (true) {
            val cur = list.load()
            checkElementIndex(index, cur.size)
            val old = cur[index]
            val next = cur.set(index, element)
            if (list.compareAndSet(cur, next)) return old
        }
    }

    override fun removeAt(index: Int): E {
        while (true) {
            val cur = list.load()
            checkElementIndex(index, cur.size)
            val old = cur[index]
            val next = cur.removeAt(index)
            if (list.compareAndSet(cur, next)) return old
        }
    }

    override fun retainAll(elements: Collection<E>): Boolean = list.updateIfChanged { current ->
        current.retainAll(elements)
    }

    override fun removeAll(elements: Collection<E>): Boolean {
        if(elements.isEmpty()) return false
        return list.updateIfChanged { current ->
            current.removeAll(elements)
        }
    }

    override fun remove(element: E): Boolean = list.updateIfChanged { current ->
        current.remove(element)
    }

    override fun lastIndexOf(element: E): Int = list.load().lastIndexOf(element)

    override fun indexOf(element: E): Int = list.load().indexOf(element)

    override fun containsAll(elements: Collection<E>): Boolean = list.load().containsAll(elements)

    override fun contains(element: E): Boolean = list.load().contains(element)

    /**
     * Copied from Kotlin [AbstractList] internal code.
     */
    private fun checkElementIndex(index: Int, size: Int) {
        if (index !in 0..<size) {
            throw IndexOutOfBoundsException("index: $index, size: $size")
        }
    }
}

private fun checkElementIndex(index: Int, size: Int) {
    if (index !in 0..<size) {
        throw IndexOutOfBoundsException("index: $index, size: $size")
    }
}

@SupabaseInternal
class AtomicMutableMap<K, V>(
    vararg pairs: Pair<K, V>
) : MutableMap<K, V> {

    private val ref = AtomicReference(persistentHashMapOf(*pairs))

    override val entries: MutableSet<MutableMap.MutableEntry<K, V>>
        get() = ref.load().toMutableMap().entries
    override val keys: MutableSet<K>
        get() = ref.load().toMutableMap().keys
    override val values: MutableCollection<V>
        get() = ref.load().toMutableMap().values

    override val size: Int get() = ref.load().size
    override fun isEmpty(): Boolean = ref.load().isEmpty()

    override fun get(key: K): V? = ref.load()[key]
    override fun containsKey(key: K): Boolean = ref.load().containsKey(key)
    override fun containsValue(value: V): Boolean = ref.load().containsValue(value)

    override fun clear() {
        ref.updateIfChanged { if (it.isEmpty()) it else persistentHashMapOf() }
    }

    override fun putAll(from: Map<out K, V>) {
        if (from.isEmpty()) return
        ref.updateIfChanged { it.putAll(from) }
    }

    override fun put(key: K, value: V): V? {
        while (true) {
            val cur = ref.load()
            val prev = cur[key]
            val next = cur.put(key, value)
            if (next === cur) return prev // same mapping/value, nothing changed
            if (ref.compareAndSet(cur, next)) return prev
        }
    }

    override fun remove(key: K): V? {
        while (true) {
            val cur = ref.load()
            val prev = cur[key] ?: run {
                // still try a no-op remove to confirm no change, but can return fast
                val next = cur.remove(key)
                if (next === cur) return null
                // If structure changed (rare), still CAS to be correct.
                if (ref.compareAndSet(cur, next)) return null
                continue
            }
            val next = cur.remove(key)
            if (ref.compareAndSet(cur, next)) return prev
        }
    }

}

internal class KermitLoggingProcessor(
    level: LogLevel,
) : SupabaseLoggingProcessor {

    private val logger: Logger = Logger(
        config = loggerConfigInit(platformLogWriter(), minSeverity = level.toSeverity())
    )

    override fun isEnabled(level: LogLevel): Boolean {
        return logger.config.minSeverity <= level.toSeverity()
    }

    override fun processLog(level: LogLevel, tag: String, throwable: Throwable?, message: String) {
        logger.processLog(level.toSeverity(), tag, throwable, message)
    }

    private fun LogLevel.toSeverity() = when (this) {
        LogLevel.DEBUG -> Severity.Debug
        LogLevel.INFO -> Severity.Info
        LogLevel.WARNING -> Severity.Warn
        LogLevel.ERROR -> Severity.Error
        LogLevel.NONE -> Severity.Assert
    }

}

