    val level: LogLevel,
    val tag: String,
    processorFactory: SupabaseLoggingProcessorFactory
) {

    val processor = processorFactory(level)

    /**
     * Log a message with the given [level] and [message]. An optional [throwable] can be provided.
     * @param level The log level
     * @param throwable An optional throwable
     * @param message The message to log
     */
    fun log(level: LogLevel, throwable: Throwable? = null, message: String) = processor.log(level, tag, throwable) {
        message
    }

    /**
     * Log a message with the given [level] and [message]. An optional [throwable] can be provided.
     * @param level The log level
     * @param throwable An optional throwable
     * @param message The message to log
     */
    inline fun log(level: LogLevel, throwable: Throwable? = null, message: () -> String) = processor.log(level, tag, throwable, message)

    /**
     * Creates a new logger with the new [tag], but with the same [processor]
     * @param tag The new tag
     */
    fun withTag(tag: String) = SupabaseLogger(level, tag, { _ -> processor })

    /**
     * Creates a new logger and appends [tag] to the current tag
     * @param tag The tag to append
     */
    fun appendTag(tag: String) = withTag(this.tag + tag)

}

fun log(level: LogLevel, throwable: Throwable? = null, message: String) = processor.log(level, tag, throwable) {
    message
}

inline fun SupabaseLogger.d(throwable: Throwable? = null, message: () -> String) {
    log(LogLevel.DEBUG, throwable, message)
}

inline fun SupabaseLogger.i(throwable: Throwable? = null, message: () -> String) {
    log(LogLevel.INFO, throwable, message)
}

inline fun SupabaseLogger.w(throwable: Throwable? = null, message: () -> String) {
    log(LogLevel.WARNING, throwable, message)
}

inline fun SupabaseLogger.e(throwable: Throwable? = null, message: () -> String) {
    log(LogLevel.ERROR, throwable, message)
}

inline fun SupabaseLoggingProcessor.log(level: LogLevel, tag: String, throwable: Throwable?, message: () -> String) {
    if(isEnabled(level)) {
        processLog(level, tag, throwable, message())
    }
}

@OptIn(SupabaseInternal::class)
class KtorSupabaseHttpClient @SupabaseInternal constructor(
    private val supabase: SupabaseClient
): SupabaseHttpClient() {

    val logger = supabase.logger.appendTag(" [Network]")
    private val supabaseKey = supabase.supabaseKey
    private val osInformation = supabase.config.osInformation

    private val networkConfig = supabase.config.networkConfig
    private val requestTimeout = networkConfig.requestTimeout
    private val engine = networkConfig.httpEngine
    private val modifiers = networkConfig.httpConfigOverrides

    override suspend fun getDefaultHeaders(): Headers {
        return io.ktor.http.headers {
            defaultHeaders()
        }
    }

    init {
        logger.d { "Creating KtorSupabaseHttpClient with request timeout $requestTimeout, HttpClientEngine: $engine" }
    }

    @SupabaseInternal
    val httpClient =
        if(engine != null) HttpClient(engine) { applyDefaultConfiguration(modifiers) }
        else HttpClient { applyDefaultConfiguration(modifiers) }

    override suspend fun request(url: String, builder: HttpRequestBuilder.() -> Unit): HttpResponse {
        val request = HttpRequestBuilder().apply {
            url(url)
            builder()
        }
        val endPoint = request.url.encodedPath
        logger.d { "Starting ${request.method.value} request to endpoint $endPoint" }
        val response = try {
            httpClient.request(url, builder)
        } catch(e: HttpRequestTimeoutException) {
            logger.d(e) { "${request.method.value} request to endpoint $endPoint timed out after $requestTimeout" }
            throw e
        } catch(e: CancellationException) {
            logger.d(e) { "${request.method.value} request to endpoint $endPoint was cancelled"}
            throw e
        } catch(e: Exception) {
            logger.d(e) { "${request.method.value} request to endpoint $endPoint failed with exception ${e.message}" }
            throw HttpRequestException(e.message ?: "", request)
        }
        val responseTime = (response.responseTime.timestamp - response.requestTime.timestamp).milliseconds
        logger.d { "${request.method.value} request to endpoint $endPoint successfully finished in $responseTime" }
        return response
    }

    override suspend fun prepareRequest(
        url: String,
        builder: HttpRequestBuilder.() -> Unit
    ): HttpStatement {
        val request = HttpRequestBuilder().apply {
            url(url)
            builder()
        }
        val response = try {
            httpClient.prepareRequest(url, builder)
        } catch(e: HttpRequestTimeoutException) {
            logger.d(e) { "Request timed out after $requestTimeout on url $url" }
            throw e
        } catch(e: CancellationException) {
            logger.d(e) { "Request was cancelled on url $url" }
            throw e
        } catch(e: Exception) {
            logger.d(e) { "Request failed with ${e.message} on url $url" }
            throw HttpRequestException(e.message ?: "", request)
        }
        return response
    }

    fun close() = httpClient.close()

    private fun HeadersBuilder.defaultHeaders() {
        if(supabaseKey.isNotBlank()) {
            append("apikey", supabaseKey)
        }
        val metadata = buildMap {
            osInformation?.let { os ->
                put("platform", os.name)
                os.version?.let { version ->
                    put("platform-version", version)
                }
            }
            put("runtime", "kotlin")
            put("runtime-version", KotlinVersion.CURRENT.toString())
        }
        append("X-Client-Info", "supabase-kt/${BuildConfig.PROJECT_VERSION}" + metadata.toList().joinToString("; ", prefix = "; ") { "${it.first}=${it.second}" })
    }

    private fun HttpClientConfig<*>.applyDefaultConfiguration(modifiers: List<HttpClientConfig<*>.() -> Unit>) {
        install(DefaultRequest) {
            headers {
                defaultHeaders()
            }
            port = HTTPS_PORT
        }
        install(ContentNegotiation) {
            json(supabaseJson)
        }
        install(HttpTimeout) {
            requestTimeoutMillis = requestTimeout.inWholeMilliseconds
        }
        modifiers.forEach { it.invoke(this) }
    }

}

abstract class SupabaseHttpClient {

    abstract suspend fun getDefaultHeaders(): Headers

    abstract suspend fun request(url: String, builder: HttpRequestBuilder.() -> Unit): HttpResponse

    abstract suspend fun prepareRequest(url: String, builder: HttpRequestBuilder.() -> Unit): HttpStatement

    suspend inline fun get(url: String, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Get
        builder()
    }

    suspend inline fun post(url: String, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Post
        builder()
    }

    suspend inline fun <reified T> post(url: String, body: T, contentType: ContentType = ContentType.Any, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Post
        builder()
        contentType(contentType)
        setBody(body)
    }

    suspend inline fun <reified T> postJson(url: String, body: T, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = post(url, body, ContentType.Application.Json, builder)

    suspend inline fun delete(url: String, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Delete
        builder()
    }

    suspend inline fun <reified T> delete(url: String, body: T, contentType: ContentType = ContentType.Any, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Delete
        builder()
        contentType(contentType)
        setBody(body)
    }

    suspend inline fun <reified T> deleteJson(url: String, body: T, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = delete(url, body, ContentType.Application.Json, builder)

    suspend inline fun patch(url: String, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Patch
        builder()
    }

    suspend inline fun <reified T> patch(url: String, body: T, contentType: ContentType = ContentType.Any, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Patch
        builder()
        contentType(contentType)
        setBody(body)
    }

    suspend inline fun <reified T> patchJson(url: String, body: T, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = patch(url, body, ContentType.Application.Json, builder)

    suspend inline fun put(url: String, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Put
        builder()
    }

    suspend inline fun <reified T> put(url: String, body: T, contentType: ContentType = ContentType.Any, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = request(url) {
        method = HttpMethod.Put
        builder()
        contentType(contentType)
        setBody(body)
    }

    suspend inline fun <reified T> putJson(url: String, body: T, crossinline builder: HttpRequestBuilder.() -> Unit = {}) = put(url, body, ContentType.Application.Json, builder)

}

