    line(image, c + 0.62 * r, c - 0.5 * r, c + 0.12 * r, c - 0.22 * r, 2.4, FEATURE)
    fillDisc(image, c - 0.34 * r, c - 0.05 * r, 0.13 * r, FEATURE)
    fillDisc(image, c + 0.34 * r, c - 0.05 * r, 0.13 * r, FEATURE)
    // A jagged grin: a zigzag of teeth across the lower face.
