@Register
fun perfMixedHotCold(): Int {
    val hot = maxOf(items.size / 10, 1)
    var transitions = 0
    repeat(run.frames) { cycle ->
        val touched = if (cycle == 0) items else items.subList(0, hot)
        for (item in touched) scratch.add(item)
        scratch.clear()
        GD.syncMemory()
        transitions += touched.size
    }
    return transitions
}

