fun RealT.isEqualApprox(to: RealT, epsilon: RealT = CMP_EPSILON): Boolean {
    // Check for exact equality first, required to handle "infinity" values.
    if (this == to) {
        return true
    }
    return abs(this - to) < epsilon
}

// Check for exact equality first, required to handle "infinity" values.
if (this == to) {
    return true
}

var tolerance: RealT = CMP_EPSILON * abs(this)
if (tolerance < CMP_EPSILON) {
    tolerance = CMP_EPSILON
}

fun roundValue(value: RealT): RealT {
    val truncated = truncate(value)
    return if (abs(value - truncated) >= 0.5) truncated + sign(value) else truncated
}

/**
 * Defines the targets for rpc calls
 *
 * See: [RpcMode.DISABLED], [RpcMode.ANY], [RpcMode.AUTHORITY] for configuration information
 */
enum class RpcMode {
    /**
     * Rpc capabilities are disabled for this function
     */
    DISABLED,

    /**
     * Rpc calls for this function are sent to any connected peer
     */
    ANY,

    /**
     * Rpc calls for this function are only sent to the authority instance the connected peers (either a server or the host)
     */
    AUTHORITY
}

enum class RpcMode {
    /**
     * Rpc capabilities are disabled for this function
     */
    DISABLED,

    /**
     * Rpc calls for this function are sent to any connected peer
     */
    ANY,

    /**
     * Rpc calls for this function are only sent to the authority instance the connected peers (either a server or the host)
     */
    AUTHORITY
}

enum class Sync {
    /**
     * Call both local and remote peer functions upon invocation of `rpc(my_function)`
     */
    SYNC,

    /**
     * Call only remote peer functions upon invocation of `rpc(my_function)`
     */
    NO_SYNC
}

private fun RpcMode.toEngineValue(): Int = when (this) {
    RpcMode.DISABLED -> 0
    RpcMode.ANY -> 1
    RpcMode.AUTHORITY -> 2
}

fun interface ProcessBody<T : KtObject> {
    fun invoke(instance: T, delta: Double)
}

class KtProcess<T : KtObject>(
    val name: String,
    private val body: ProcessBody<T>,
) {
    fun invoke(instance: T, delta: Double) {
        try {
            body.invoke(instance, delta)
        } catch (t: Throwable) {
            GodotLogging.error("Error calling JVM method $name of script $instance from Godot:\n" + t.stackTraceToString())
        }
    }
}

