fun getSupport(direction: Vector3): Vector3 {
    val support = Vector3(position)
    if (direction.x > 0.0f) {
        support.x += size.x
    }
    if (direction.y > 0.0f) {
        support.y += size.y
    }
    if (direction.z > 0.0f) {
        support.z += size.z
    }
    return support
}

