fun blend(over: Color): Color {
    val res = Color()
    val sa = 1.0 - over.a
    res.a = a * sa + over.a
    if (res.a == 0.0) {
        return Color(0.0, 0.0, 0.0, 0.0)
    } else {
        res.r = (r * a * sa + over.r * over.a) / res.a
        res.g = (g * a * sa + over.g * over.a) / res.a
        res.b = (b * a * sa + over.b * over.a) / res.a
    }
    return res
}

