operator fun times(matrix: Projection): Projection {
    val newMatrix = Projection()

    for (j in 0..3) {
        for (i in 0..3) {
            var ab: RealT = 0.0
            for (k in 0..3) {
                ab += this[k][i] * matrix[j][k]
            }
            newMatrix.setMatrixElement(j, i, ab)
        }
    }

    return newMatrix
}

