    return when {
        point.x < _position.x -> false
        point.y < _position.y -> false
        point.x >= (_position.x + _size.x) -> false
        point.y >= (_position.y + _size.y) -> false
        else -> true
    }
}

fun intersection(rect: Rect2): Rect2 {
