    val v = vector - _origin
    return Vector3(
        (_basis._x.x * v.x) + (_basis._y.x * v.y) + (_basis._z.x * v.z),
        (_basis._x.y * v.x) + (_basis._y.y * v.y) + (_basis._z.y * v.z),
        (_basis._x.z * v.x) + (_basis._y.z * v.y) + (_basis._z.z * v.z)
    )
}

