private fun buildReleaseReport(): LongArray {
    // Drain every wrapper the GC collected since the last sync, so the throttle knows the total amount of work.
    while (true) {
        deadBindings.add((Binding.queue.poll() ?: break) as RefCountedBinding)
    }

    // Worst case size: every previous candidate confirmed, plus as many new candidates as the throttle allows.
    val previousCandidateCount = previousReport[CANDIDATE_COUNT_INDEX].toInt()
    val newCandidateMax = Configuration.getNumberOfItemsToProcess(deadBindings.size)
    val reportSize = IDS_START_INDEX + previousCandidateCount + newCandidateMax
    if (currentReport.size < reportSize) {
        currentReport = LongArray(max(reportSize, currentReport.size * 2))
    }
    val report = currentReport

    // Confirmed ids first, candidates right after; the two ObjectDB walks are the only part needing the lock.
    var confirmedCount = 0
    var candidateCount = 0
    lock.withLock {
        confirmedCount = writeConfirmedIds(report, IDS_START_INDEX)
        candidateCount = writeCandidateIds(report, IDS_START_INDEX + confirmedCount, newCandidateMax)
    }
    report[CONFIRMED_COUNT_INDEX] = confirmedCount.toLong()
    report[CANDIDATE_COUNT_INDEX] = candidateCount.toLong()

    // This report becomes the previous one: its candidates are what the next sync confirms.
    currentReport = previousReport
    previousReport = report
    return report
}

val previousCandidateCount = previousReport[CANDIDATE_COUNT_INDEX].toInt()
val newCandidateMax = Configuration.getNumberOfItemsToProcess(deadBindings.size)
val reportSize = IDS_START_INDEX + previousCandidateCount + newCandidateMax
if (currentReport.size < reportSize) {
    currentReport = LongArray(max(reportSize, currentReport.size * 2))
}

private fun writeConfirmedIds(report: LongArray, firstIndex: Int): Int {
    var written = 0
    forEachPreviousCandidate { objectId ->
        if (ObjectDB[ObjectID(objectId)] == null) {
            report[firstIndex + written++] = objectId
        }
    }
    return written
}

private fun removeNativeCoreTypes() {
    // Pool all dead native cores first, so we can know the amount of work to do.
    while (true) {
        val ref = ((NativeCoreBinding.queue.poll() ?: break) as NativeCoreBinding)
        deadNativeCores.add(ref)
    }
    if (deadNativeCores.isEmpty()) return

    val numberToDecrement = Configuration.getNumberOfItemsToProcess(deadNativeCores.size)
    val pointerArray = LongArray(numberToDecrement)
    val variantTypeArray = IntArray(numberToDecrement)

    deadNativeCores
        .subList(0, numberToDecrement)
        .onEachIndexed { index, binding ->
            pointerArray[index] = binding.ptr
            variantTypeArray[index] = binding.variantType.id
            nativeCoreTypeMap.remove(binding.ptr)
        }.clear()

    unrefNativeCoreTypes(pointerArray, variantTypeArray)
}

private fun pageFor(index: Int): Array<Binding?> {
    val page = index ushr PAGE_BITS
    var directory = directory
    if (page >= directory.size) {
        var pages = directory.size
        while (pages <= page) pages *= 2
        directory = directory.copyOf(pages)
        this.directory = directory
    }
    return directory[page] ?: arrayOfNulls<Binding>(PAGE_SIZE).also { directory[page] = it }
}

private fun register(thread: Thread): Locals {
    directory[thread]?.let { return it }

    val locals = Locals(thread)
    while (true) {
        val seenVersion = version
        val slot = slotOf(thread.id, multiplier)
        val occupant = slots[slot]

        if (occupant == null || !occupant.thread.isAlive) {
            synchronized(lock) {
                if (version == seenVersion) {
                    directory[thread] = locals
                    slots[slot] = locals
                    version = seenVersion + 1
                    return locals
                }
            }
            continue
        }

        val live = ArrayList(directory.values).apply {
            retainAll { it.thread.isAlive }
            add(locals)
        }
        val found = findMultiplier(LongArray(live.size) { live[it].thread.id })

        synchronized(lock) {
            if (version == seenVersion) {
                directory[thread] = locals
                if (found != 0L) {
                    reindex(live, found)
                }
                version = seenVersion + 1
                return locals
            }
        }
    }
}

private fun reindex(live: List<Locals>, found: Long) {
    slots.fill(null)
    multiplier = found
    for (locals in live) {
        slots[slotOf(locals.thread.id, found)] = locals
    }
}

fun open(callerPtr: VoidPtr, callerId: Long, argumentCount: Int): Int {
    val base = top
    if (GodotJvmBuildConfig.DEBUG) {
        check(base + FRAME_SIZE <= buffer.capacity()) {
            "The value buffer is full: too many engine calls are running at once on this thread."
        }
    }
    buffer.position(base)
    buffer.putLong(callerPtr)
    buffer.putLong(callerId)
    buffer.putInt(argumentCount)
    return base
}

fun openSimple(callerPtr: VoidPtr, callerId: Long): Int {
    val base = top
    if (GodotJvmBuildConfig.DEBUG) {
        check(base + FRAME_SIZE <= buffer.capacity()) {
            "The value buffer is full: too many engine calls are running at once on this thread."
        }
    }
    buffer.position(base)
    buffer.putLong(callerPtr)
    buffer.putLong(callerId)
    top = base + CALLER_SIZE
    return base
}

