fun bernstein(points: List<PointF>, t: Double): PointF {
    val n = points.size - 1
    var x = 0.0
    var y = 0.0
    for (i in 0..n) {
        val b = binomial(n, i) * t.pow(i) * (1 - t).pow(n - i)
        x += b * points[i].x
        y += b * points[i].y
    }
    return PointF(x.toFloat(), y.toFloat())
}

