object PostBinder {

    fun bind(root: View, post: Post, goodView: GoodView) {
        val context = root.context
        root.findViewById<TextView>(R.id.post_avatar).text = post.author.take(1).uppercase()
        root.findViewById<TextView>(R.id.post_author).text = post.author
        root.findViewById<TextView>(R.id.post_time).text = post.time
        root.findViewById<TextView>(R.id.post_content).text = post.content
        root.findViewById<TextView>(R.id.post_tag).apply {
            text = post.tag
            visibility = if (post.tag == null) View.GONE else View.VISIBLE
        }

        val like = root.findViewById<TextView>(R.id.action_like)
        val star = root.findViewById<TextView>(R.id.action_star)
        val share = root.findViewById<TextView>(R.id.action_share)
        fun render() {
            like.text = post.likes.toString()
            like.setTextColor(context.colorOf(if (post.liked) R.color.accent_ink else R.color.text_sub))
            like.setStartIcon(icon(like, if (post.liked) R.drawable.ic_heart_fill else R.drawable.ic_heart,
                if (post.liked) R.color.accent_ink else R.color.text_sub))
            star.text = post.stars.toString()
            star.setTextColor(context.colorOf(if (post.starred) R.color.gold else R.color.text_sub))
            star.setStartIcon(icon(star, if (post.starred) R.drawable.ic_star_fill else R.drawable.ic_star,
                if (post.starred) R.color.gold else R.color.text_sub))
            share.text = post.shares.toString()
            share.setStartIcon(icon(share, R.drawable.ic_share, R.color.text_sub))
            like.contentDescription = context.getString(R.string.post_like) + " " + post.likes
            star.contentDescription = context.getString(R.string.post_star) + " " + post.stars
            share.contentDescription = context.getString(R.string.post_share) + " " + post.shares
        }

        like.setOnClickListener {
            post.liked = !post.liked
            post.likes += if (post.liked) 1 else -1
            render()
            Pop.text(goodView, it, if (post.liked) "+1" else "-1",
                context.colorOf(if (post.liked) R.color.accent_ink else R.color.text_dim))
            if (post.liked) it.pulse(1.12f)
        }
        star.setOnClickListener {
            post.starred = !post.starred
            post.stars += if (post.starred) 1 else -1
            render()
            Pop.text(goodView, it, context.getString(if (post.starred) R.string.pop_starred else R.string.pop_unstarred),
                context.colorOf(if (post.starred) R.color.gold else R.color.text_dim), 13)
            if (post.starred) it.pulse(1.12f)
        }
        share.setOnClickListener {
            post.shares++
            render()
            Pop.text(goodView, it, context.getString(R.string.pop_shared), context.colorOf(R.color.blue), 13)
        }
        render()
    }

    private fun icon(view: TextView, id: Int, color: Int) = view.context.tintedIcon(id, view.context.colorOf(color), 20f)
}

fun Context.tintedIcon(@DrawableRes id: Int, @ColorInt color: Int, sizeDp: Float): Drawable {
    val drawable = tinted(id, color)
    val size = dp(sizeDp)
    drawable.setBounds(0, 0, size, size)
    return drawable
}

object Pop {

    fun text(goodView: GoodView, anchor: View, text: String, @ColorInt color: Int, sizeDp: Int = 16) {
        goodView.reset()
        goodView.setTextInfo(text, color, sizeDp)
        goodView.show(anchor)
    }

    fun image(goodView: GoodView, anchor: View, image: Drawable) {
        goodView.reset()
        goodView.setImage(image)
        goodView.show(anchor)
    }
}

@RunWith(RobolectricTestRunner::class)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class GoodViewTest {

    private lateinit var activity: Activity
    private lateinit var root: FrameLayout
    private lateinit var anchor: View

    @Before
    fun setUp() {
        activity = Robolectric.buildActivity(Activity::class.java).setup().get()
        root = FrameLayout(activity)
        anchor = View(activity)
        root.addView(anchor, FrameLayout.LayoutParams(100, 100).apply {
            topMargin = 300
            leftMargin = 100
        })
        activity.setContentView(root)
        idle()
    }

    private fun idle() {
        shadowOf(Looper.getMainLooper()).idle()
    }

    private fun contentText(goodView: GoodView): TextView =
        (goodView.contentView as ViewGroup).getChildAt(0) as TextView

    // 守护用例：issue #4（长文本换行）在 Robolectric mdpi / xxhdpi 下均未复现，未修改宽度计算逻辑，待真机确认
    @Test
    @Config(qualifiers = "xxhdpi")
    fun longTextStaysOnOneLine() {
        val goodView = GoodView(activity)
        for (text in listOf("+1234567", "+9999999", "收藏成功", "点赞 +1", "+1")) {
            goodView.setText(text)
            goodView.show(anchor)
            idle()

            assertEquals(text, 1, contentText(goodView).lineCount)
            goodView.dismiss()
            idle()
        }
    }

    // 先显示文本再显示图片时，空文本仍按字号占一行高度，图片被纵向拉伸（issue #2）
    @Test
    fun imageIsNotStretchedAfterText() {
        val goodView = GoodView(activity)
        goodView.setTextInfo("收藏成功", Color.RED, 30)
        val drawable = ShapeDrawable().apply {
            intrinsicWidth = 40
            intrinsicHeight = 10
        }
        goodView.setImage(drawable)
        goodView.show(anchor)
        idle()

        val content = contentText(goodView)
        assertEquals(40, content.width)
        assertEquals(10, content.height)
    }

    // reset() 只重置了字段，界面上仍显示旧的文本和颜色
    @Test
    fun resetRestoresTextAndColor() {
        val goodView = GoodView(activity)
        goodView.setTextInfo("收藏成功", Color.RED, 30)
        goodView.reset()

        val content = contentText(goodView)
        assertEquals(IGoodView.TEXT, content.text.toString())
        assertEquals(IGoodView.TEXT_COLOR, content.currentTextColor)
    }

    // 守护用例：锚点 View 离开窗口（如页面关闭）后弹窗应随之关闭；Android 7.0+ 的 PopupWindow 已自行处理
    @Test
    fun dismissedWhenAnchorDetached() {
        val goodView = GoodView(activity)
        goodView.setText("+1")
        // 动画时长较长，避免动画结束后弹窗自行关闭，影响本用例判断
        goodView.setDuration(60_000)
        goodView.show(anchor)
        assertTrue(goodView.isShowing)

        root.removeView(anchor)
        idle()

        assertFalse(goodView.isShowing)
    }

    // 上一个弹窗动画未结束时在另一个按钮上展示新文本：旧实现直接忽略这次 show，弹窗停在旧按钮上，
    // 窗口也沿用旧文本的宽度，新文本被挤成多行（issue #4，真机复现）。
    // Robolectric 中 View 动画会在 idle 时立即结束并关闭弹窗，所以在第二次 show 后直接检查窗口参数
    @Test
    fun showWhileShowingMovesToNewAnchorAndResizes() {
        val anchor2 = View(activity)
        root.addView(anchor2, FrameLayout.LayoutParams(100, 100).apply {
            topMargin = 500
            leftMargin = 200
        })
        idle()

        val goodView = GoodView(activity)
        goodView.setText("+1")
        goodView.show(anchor)
        goodView.setTextInfo("收藏成功", Color.RED, 12)
        goodView.show(anchor2)

        assertTrue(goodView.isShowing)
        val lp = goodView.contentView.rootView.layoutParams as WindowManager.LayoutParams
        assertEquals(goodView.width, lp.width)
        val location = IntArray(2)
        anchor2.getLocationInWindow(location)
        assertEquals(location[0] + anchor2.width / 2 - goodView.width / 2, lp.x)
    }
}

