public class UsbCommunicationFactory {

    enum UnderlyingUsbCommunication {
        USB_REQUEST_ASYNC,
        DEVICE_CONNECTION_SYNC
    }

    private static final String TAG = UsbCommunicationFactory.class.getSimpleName();

    private static UnderlyingUsbCommunication underlyingUsbCommunication = UnderlyingUsbCommunication.DEVICE_CONNECTION_SYNC;

    public static UsbCommunication createUsbCommunication(UsbDeviceConnection deviceConnection, UsbEndpoint outEndpoint, UsbEndpoint inEndpoint) {
        UsbCommunication communication;

        if (underlyingUsbCommunication == UnderlyingUsbCommunication.DEVICE_CONNECTION_SYNC) {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR2) {
                communication = new JellyBeanMr2Communication(deviceConnection, outEndpoint, inEndpoint);
            } else {
                Log.i(TAG, "using workaround usb communication");
                communication = new HoneyCombMr1Communication(deviceConnection, outEndpoint, inEndpoint);
            }
        } else {
            communication = new UsbRequestCommunication(deviceConnection, outEndpoint, inEndpoint);
        }

        return communication;
    }

    public static void setUnderlyingUsbCommunication(UnderlyingUsbCommunication underlyingUsbCommunication) {
        UsbCommunicationFactory.underlyingUsbCommunication = underlyingUsbCommunication;
    }
}

public class LastFMCover extends AbstractWebCover {

    private static String KEY = "7fb78a81b20bee7cb6e8fad4cbcb3694";
    private static final String URL = "http://ws.audioscrobbler.com/2.0/";

    @Override
    public String[] getCoverUrl(String artist, String album, String path, String filename) throws Exception {

        String response;
        String request;
        String sizeAttribute = null;
        String imageUrl;
        XmlPullParserFactory factory;
        XmlPullParser xpp;
        int eventType;

        try {
            request = URL + "?method=album.getInfo&artist=" + artist + "&album=" + album + "&api_key=" + KEY;
            response = executeGetRequest(request);

            factory = XmlPullParserFactory.newInstance();
            factory.setNamespaceAware(true);
            xpp = factory.newPullParser();

            xpp.setInput(new StringReader(response));
            eventType = xpp.getEventType();

            while (eventType != XmlPullParser.END_DOCUMENT) {
                if (eventType == XmlPullParser.START_TAG) {
                    if (xpp.getName().equals("image")) {
                        sizeAttribute = xpp.getAttributeValue(null, "size");
                    }
                } else if (eventType == XmlPullParser.TEXT) {
                    if (sizeAttribute != null && sizeAttribute.equals("mega")) {
                        imageUrl = xpp.getText();
                        if (imageUrl != null && imageUrl.length() > 0) {
                            return new String[]{imageUrl};
                        }
                    }
                }
                eventType = xpp.next();
            }
        } catch (Exception e)

        {
            Log.e(LastFMCover.class.toString(), "Failed to get cover URL from LastFM :" + e);
        }

        return new String[0];
    }

    @Override

    public String getName() {
        return "LastFM";
    }
}

public class BitmapFileMatcher extends TypeSafeMatcher<File> implements Matcher<File> {

  //region Matcher impl

  @Override
  protected boolean matchesSafely(File item) {
    Bitmap bitmap = BitmapFactory.decodeFile(item.getAbsolutePath());

    boolean matches = bitmap != null && bitmap.getWidth() > 0 && bitmap.getHeight() > 0;

    if (bitmap != null) {
      bitmap.recycle();
    }

    return matches;
  }

  @Override
  public void describeTo(Description description) {
    description.appendText("The file is Bitmap");
  }

  @Override
  protected void describeMismatchSafely(File item, Description mismatchDescription) {
    mismatchDescription.appendText(" file ").appendText(item.getAbsolutePath());
    mismatchDescription.appendText(" was not decoded as Bitmap");
  }

  //endregion

  //region Methods

  public static Matcher<File> isBitmap() {
    return new BitmapFileMatcher();
  }

  //endregion
}

