public class BlackMagics {
    /*
     * 进度条上移
     * @param v
     * @param withLayer
     */
    public static ViewPropertyAnimator scrollUp(SmoothProgressBar progressBar) {
        final int offset = progressBar.getHeight();
        progressBar.setTranslationY(offset);
        progressBar.setAlpha(0.01f);
        return progressBar.animate()
                .translationY(0)
                .alpha(1)
                .setDuration(600)
                .setInterpolator(new FastOutSlowInInterpolator())
                .withLayer();
    }

    /*
    * 进度条下移
    * @param v
    * @param withLayer
    */
    public static ViewPropertyAnimator scrollDown(SmoothProgressBar progressBar) {
        final int offset = progressBar.getHeight();
        return progressBar.animate()
                .translationY(offset)
                .alpha(0.01f)
                .setDuration(600)
                .setInterpolator(new FastOutSlowInInterpolator())
                .withLayer();
    }
}

public class StateProxyBalancingTest {

    @Test
    public void associateThenDisassociateWithNoChanges() throws Exception {
        CutoutViewIndicator indicator = mock(CutoutViewIndicator.class);


        // Setup

        indicator.dataSetObserver = mock(DataSetObserver.class);
        indicator.stateProxy = new UnavailableProxy();
        ViewTreeObserver vtoMock = mock(ViewTreeObserver.class);

        when(indicator.getViewTreeObserver()).thenReturn(vtoMock);
        doCallRealMethod().when(indicator).setStateProxy(any(StateProxy.class));

        StateProxy proxyA = mock(StateProxy.class);
        when(proxyA.canObserve(any(DataSetObserver.class))).thenReturn(false);

        StateProxy proxyB = mock(StateProxy.class);
        when(proxyB.canObserve(any(DataSetObserver.class))).thenReturn(true);


        // The test

        indicator.setStateProxy(proxyA);

        verify(proxyA).canObserve(any(DataSetObserver.class));
        verify(proxyA, never()).associateWith(any(DataSetObserver.class));

        indicator.setStateProxy(proxyB);

        verify(proxyA, never()).disassociateFrom(any(DataSetObserver.class));

        verify(proxyB).canObserve(any(DataSetObserver.class));
        verify(proxyB).associateWith(any(DataSetObserver.class));
    }
}

public class TicwearDialogs {

    @NonNull
    public static AlertDialog permissionRequestDialog(@NonNull Context context,
                                                      @Nullable String message,
                                                      @Nullable final Runnable positiveAction) {
        return permissionRequestDialog(context, message, positiveAction, null);
    }

    @NonNull
    public static AlertDialog permissionRequestDialog(@NonNull Context context,
                                                      @Nullable String message,
                                                      @Nullable final Runnable positiveAction,
                                                      @Nullable final Runnable negativeAction) {
        return permissionRequestDialog(context, message, positiveAction, negativeAction, null);
    }

    @NonNull
    public static AlertDialog permissionRequestDialog(@NonNull Context context,
                                                      @Nullable String message,
                                                      @Nullable final Runnable positiveAction,
                                                      @Nullable final Runnable negativeAction,
                                                      @Nullable final Runnable cancelAction) {
        class ActionStatus {
            boolean hasAction = false;
        }

        final ActionStatus actionStatus = new ActionStatus();

        return new AlertDialog.Builder(context)
                .setMessage(message)
                .setPositiveButtonIcon(ticwear.design.R.drawable.tic_ic_btn_ok,
                        new DialogInterface.OnClickListener() {
                            @Override
                            public void onClick(DialogInterface dialog, int which) {
                                actionStatus.hasAction = true;
                                dialog.dismiss();
                                if (positiveAction != null) {
                                    positiveAction.run();
                                }
                            }
                        })
                .setNegativeButtonIcon(ticwear.design.R.drawable.tic_ic_btn_cancel,
                        new DialogInterface.OnClickListener() {
                            @Override
                            public void onClick(DialogInterface dialog, int which) {
                                actionStatus.hasAction = true;
                                dialog.dismiss();
                                if (negativeAction != null) {
                                    negativeAction.run();
                                }
                            }
                        })
                .setOnDismissListener(new OnDismissListener() {
                    @Override
                    public void onDismiss(DialogInterface dialogInterface) {
                        // If dismiss with no user action, we know the user has cancel the dialog.
                        if (!actionStatus.hasAction && cancelAction != null) {
                            cancelAction.run();
                        }
                    }
                })
                .setDelayConfirmAction(DialogInterface.BUTTON_POSITIVE, 5000)
                .create();
    }

}

