@SuppressLint("ClickableViewAccessibility")
override fun onDetachedFromWindow() {
    super.onDetachedFromWindow()
    unsubscribeProgress()
    unsubscribeStatus()
    unsubscribeReadImageHeader()
    subsamplingImageView?.setOnImageEventListener(null)
}

private fun observeStatus() {
    statusSubscription?.unsubscribe()

    val loader = page.chapter.pageLoader ?: return
    statusSubscription = loader.getPage(page)
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe { processStatus(it) }
}

private fun observeProgress() {
    progressSubscription?.unsubscribe()

    progressSubscription = Observable.interval(100, TimeUnit.MILLISECONDS)
            .map { page.progress }
            .distinctUntilChanged()
            .onBackpressureLatest()
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe { value -> progressBar.setProgress(value) }
}

private fun processStatus(status: Int) {
    when (status) {
        Page.QUEUE -> setQueued()
        Page.LOAD_PAGE -> setLoading()
        Page.DOWNLOAD_IMAGE -> {
            observeProgress()
            setDownloading()
        }
        Page.READY -> {
            setImage()
            unsubscribeProgress()
        }
        Page.ERROR -> {
            setError()
            unsubscribeProgress()
        }
    }
}

private fun unsubscribeStatus() {
    statusSubscription?.unsubscribe()
    statusSubscription = null
}

private fun unsubscribeProgress() {
    progressSubscription?.unsubscribe()
    progressSubscription = null
}

private fun unsubscribeReadImageHeader() {
    readImageHeaderSubscription?.unsubscribe()
    readImageHeaderSubscription = null
}

private fun setQueued() {
    progressBar.visible()
    retryButton?.gone()
    decodeErrorLayout?.gone()
}

private fun setLoading() {
    progressBar.visible()
    retryButton?.gone()
    decodeErrorLayout?.gone()
}

private fun setDownloading() {
    progressBar.visible()
    retryButton?.gone()
    decodeErrorLayout?.gone()
}

private fun setImage() {
    progressBar.visible()
    progressBar.completeAndFadeOut()
    retryButton?.gone()
    decodeErrorLayout?.gone()

    unsubscribeReadImageHeader()
    val streamFn = page.stream ?: return

    var openStream: InputStream? = null
    readImageHeaderSubscription = Observable
            .fromCallable {
                val stream = streamFn().buffered(16)
                openStream = stream

                ImageUtil.findImageType(stream) == ImageUtil.ImageType.GIF
            }
            .subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
            .doOnNext { isAnimated ->
                if (!isAnimated) {
                    initSubsamplingImageView().setImage(ImageSource.inputStream(openStream!!))
                } else {
                    val gifDrawable = GifDrawable(openStream!!)

                    // Some chapters have pages in GIF format for some reason
                    // There's just a one frame, so put it in the SSIV to display with the proper scaling
                    if(gifDrawable.numberOfFrames > 1) {
                        initImageView().setImageDrawable(gifDrawable)
                    }else{
                        initSubsamplingImageView().setImage(ImageSource.bitmap(gifDrawable.currentFrame))
                    }
                }
            }
            // Keep the Rx stream alive to close the input stream only when unsubscribed
            .flatMap { Observable.never<Unit>() }
            .doOnUnsubscribe { openStream?.close() }
            .subscribe({}, {})
}

private fun setError() {
    progressBar.gone()
    initRetryButton().visible()
}

private fun onImageDecoded() {
    progressBar.gone()
}

private fun onImageDecodeError() {
    progressBar.gone()
    initDecodeErrorLayout().visible()
}

