class TrampolineSchedulerRule : TestRule {
    private val scheduler by lazy { Schedulers.trampoline() }

    override fun apply(base: Statement?, description: Description?): Statement =
            object : Statement() {
                override fun evaluate() {
                    try {
                        RxJavaPlugins.setComputationSchedulerHandler { scheduler }
                        RxJavaPlugins.setIoSchedulerHandler { scheduler }
                        RxJavaPlugins.setNewThreadSchedulerHandler { scheduler }
                        RxJavaPlugins.setSingleSchedulerHandler { scheduler }
                        RxAndroidPlugins.setInitMainThreadSchedulerHandler { scheduler }
                        base?.evaluate()
                    } finally {
                        RxJavaPlugins.reset()
                        RxAndroidPlugins.reset()
                    }
                }
            }
}

@ThreadSafe
abstract class SymbolTableBuildService @VisibleForTesting internal constructor(cacheBuilderSpec: CacheBuilderSpec) :
    BuildService<BuildServiceParameters.None>, AutoCloseable {

    @Suppress("unused") // Called by Gradle
    @Inject
    constructor() : this(cacheBuilderSpec = SOFT_VALUES)

    fun loadClasspath(files: Iterable<File>): List<SymbolTable> {
        val stopwatch = Stopwatch.createStarted()
        logger.log(logLevel, "SymbolTableBuildService: loadClasspath started")
        getSymbolTablesCached(files).also { result ->
            logger.log(
                logLevel,
                "SymbolTableBuildService: loadClasspath took {} to return {} tables",
                stopwatch.elapsed(),
                result.size
            )
            return result
        }
    }

    protected val logger: Logger = Logging.getLogger(SymbolTableBuildService::class.java)

    private val logLevel: LogLevel =  LogLevel.DEBUG

    /**
     * We keep a soft reference to the strong interner used by symbol IO.
     *
     * This is to avoid having a very large number of soft references,
     * but still being able to drop symbols from the intern table under memory pressure.
     */
    private var symbolInternerReference: SoftReference<Interner<Symbol>>? = null

    private val symbolInterner: Interner<Symbol>
        @Synchronized
        get() {
            return symbolInternerReference?.get() ?: Interners.newStrongInterner<Symbol>().also {
                symbolInternerReference = SoftReference(it)
                // This will have happened if the original interner has been garbage collected.
                // When recreating it, intern the existing symbols to avoid additional memory use.
                for (symbolTable in symbolTableCache.asMap().values) {
                    for (symbol in symbolTable.symbols.values()) {
                        it.intern(symbol)
                    }
                }
            }
        }

    /** A key for symbol table lookup that uses the [BasicFileAttributes.fileKey] */
    private data class FileCacheKey(
        val file: Path,
        private val key: Any =
            Files.readAttributes(file, BasicFileAttributes::class.java).fileKey()
                ?: file.toUri().toString() // Fall back to using the file path as key.
    ) {
        // This uses a custom equals and hashcode implementation to avoid using the
        // Path object as part of the identity, but passing it in to allow symbols to be loaded.
        override fun equals(other: Any?): Boolean =
            other is FileCacheKey && this.key == other.key

        override fun hashCode(): Int = Objects.hash(key)
    }

    /** Cache of loaded files */
    private val symbolTableCache: LoadingCache<FileCacheKey, SymbolTable> =
        CacheBuilder.from(cacheBuilderSpec)
            .build(
                object : CacheLoader<FileCacheKey, SymbolTable>() {
                    override fun load(key: FileCacheKey): SymbolTable {
                        val result =
                            SymbolIo(symbolInterner).readSymbolListWithPackageName(key.file)
                        logger.log(
                            logLevel,
                            "SymbolTableBuildService: cache miss - loaded table '{}' from disk",
                            result.tablePackage
                        )
                        return result
                    }
                }
            )

    /**
     * Loads the given symbol tables using the cache.
     *
     * [SymbolTable]s will be returned from the in-memory cache if present, and only loaded from
     * disk if they are not already cached.
     * [Symbol] instances will be interned and shared across invocations.
     */
    private fun getSymbolTablesCached(files: Iterable<File>): List<SymbolTable> {
        return files.map { symbolTableCache.get(FileCacheKey(it.toPath())) }
    }

    @VisibleForTesting
    internal fun dropSymbolInterner() {
        symbolInternerReference?.clear()
    }

    @VisibleForTesting
    internal fun dropSymbolTables() {
        symbolTableCache.invalidateAll()
    }

    final override fun close() {
        dropSymbolInterner()
        dropSymbolTables()
    }

    class RegistrationAction(project: Project) :
        ServiceRegistrationAction<SymbolTableBuildService, BuildServiceParameters.None>(
            project,
            SymbolTableBuildService::class.java
        ) {
        override fun configure(parameters: BuildServiceParameters.None) {}
    }

    companion object {
        private val SOFT_VALUES = CacheBuilderSpec.parse("softValues")
    }
}

private data class FileCacheKey(
    val file: Path,
    private val key: Any =
        Files.readAttributes(file, BasicFileAttributes::class.java).fileKey()
            ?: file.toUri().toString() // Fall back to using the file path as key.
) {
    // This uses a custom equals and hashcode implementation to avoid using the
    // Path object as part of the identity, but passing it in to allow symbols to be loaded.
    override fun equals(other: Any?): Boolean =
        other is FileCacheKey && this.key == other.key

    override fun hashCode(): Int = Objects.hash(key)
}

private val symbolTableCache: LoadingCache<FileCacheKey, SymbolTable> =
    CacheBuilder.from(cacheBuilderSpec)
        .build(
            object : CacheLoader<FileCacheKey, SymbolTable>() {
                override fun load(key: FileCacheKey): SymbolTable {
                    val result =
                        SymbolIo(symbolInterner).readSymbolListWithPackageName(key.file)
                    logger.log(
                        logLevel,
                        "SymbolTableBuildService: cache miss - loaded table '{}' from disk",
                        result.tablePackage
                    )
                    return result
                }
            }

private fun getSymbolTablesCached(files: Iterable<File>): List<SymbolTable> {
    return files.map { symbolTableCache.get(FileCacheKey(it.toPath())) }
}

class AnimationToolbarAnalyticsManager
@VisibleForTesting
constructor(
  private val logger: Consumer<AndroidStudioEvent.Builder>,
  private val asynchronous: Boolean
) {
  constructor() : this(Consumer { eventBuilder -> UsageTracker.log(eventBuilder) }, true)

  companion object {
    private val EXECUTOR: ThreadPoolExecutor by lazy {
      ThreadPoolExecutor(0, 1, 1, TimeUnit.MINUTES, LinkedBlockingQueue(10))
    }
  }

  private val tracker: AnimationToolbarUsageTracker by lazy {
    val trackerImpl = AnimationToolbarUsageTrackerImpl(logger)
    if (asynchronous) AsyncTracker(EXECUTOR, trackerImpl) else trackerImpl
  }

  fun trackAction(type: AnimationToolbarType, action: AnimationToolbarAction) {
    val toolbarType =
      when (type) {
        AnimationToolbarType.LIMITED -> AnimationPreviewEvent.ToolbarType.LIMITED_ANIMATION
        AnimationToolbarType.UNLIMITED -> AnimationPreviewEvent.ToolbarType.UNLIMITED_ANIMATION
        AnimationToolbarType.ANIMATED_SELECTOR ->
          AnimationPreviewEvent.ToolbarType.ANIMATED_SELECTOR
      }

    val userAction =
      when (action) {
        AnimationToolbarAction.PLAY -> AnimationPreviewEvent.UserAction.PLAY
        AnimationToolbarAction.PAUSE -> AnimationPreviewEvent.UserAction.PAUSE
        AnimationToolbarAction.STOP -> AnimationPreviewEvent.UserAction.STOP
        AnimationToolbarAction.FRAME_FORWARD -> AnimationPreviewEvent.UserAction.FRAME_FORWARD
        AnimationToolbarAction.FRAME_BACKWARD -> AnimationPreviewEvent.UserAction.FRAME_BACKWARD
        AnimationToolbarAction.SELECT_ANIMATION -> AnimationPreviewEvent.UserAction.SELECT_ANIMATION
        AnimationToolbarAction.FRAME_CONTROL -> AnimationPreviewEvent.UserAction.FRAME_CONTROL
      }

    tracker.logToolbarEvent(toolbarType, userAction)
  }
}

class MediaPicker(private val activity: FragmentActivity) {

    init {
        AppContainer(activity.applicationContext)
    }

    private var _pickedMedia: MutableStateFlow<List<Media>> = MutableStateFlow(listOf())

    /**
     * A state flow to observe the picked media files.
     * Collect this flow to get the picked media files as list.
     */
    val pickedMedia: StateFlow<List<Media>> = _pickedMedia

    private var activityResultLauncher =
        activity.registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {
            parseResult(it)
        }

    private fun parseResult(result: ActivityResult?) {
        result?.let {
            when (it.resultCode) {
                Constants.RESULT_CODE_CAMERA, Constants.RESULT_CODE_GALLERY -> {
                    it.data?.extras?.parcelableArrayList<Media>(Constants.RESULT_KEY)
                        ?.let { images ->
                            _pickedMedia.value = images
                            Log.d(Constants.TAG, "parseResult: ${images.size}")
                        }
                }
                else -> {
                    _pickedMedia.value = listOf()
                    Log.d(Constants.TAG, "parseResult: came to else block")
                }
            }
        }
    }

    /**
     * Use this function to pick media files from gallery/camera or open a chooser dialog.
     * Pass Picker.CHOOSER to open a chooser dialog.
     *
     * @param picker pass one of the three enums. Picker.CHOOSER, Picker.CAMERA or Picker.GALLERY.
     * @param fileType pass one of the three enums. Type.IMAGE, Type.VIDEO or Type.MEDIA.
     * @param maxSelection An integer value that'll define the possible maximum number of selection.
     */
    fun pickMedia(picker: Picker, fileType: Type, maxSelection: Int = MAX_SELECTION) {
        _pickedMedia.value = listOf()
        if (picker == Picker.CHOOSER)
            showPickerPopUp(fileType, maxSelection)
        else
            launchPicker(picker, fileType, maxSelection)
    }

    private fun launchPicker(picker: Picker, fileType: Type, maxSelection: Int) {
        if (picker == Picker.CAMERA)
            activityResultLauncher.launch(
                Intent(activity, CameraActivity::class.java)
                    .putExtra(FILE_TYPE_KEY, fileType.name)
                    .putExtra(MAX_SELECTION_KEY, maxSelection)
            )
        else if (picker == Picker.GALLERY)
            activityResultLauncher.launch(
                Intent(activity, GalleryActivity::class.java)
                    .putExtra(FILE_TYPE_KEY, fileType.name)
                    .putExtra(MAX_SELECTION_KEY, maxSelection)
            )
    }

    private fun showPickerPopUp(fileType: Type, maxSelection: Int = MAX_SELECTION) {
        MediaPickerDialog { launchPicker(it, fileType, maxSelection) }
            .show(activity.supportFragmentManager, MediaPickerDialog.TAG)
    }
}

