private fun isEventAlreadyKnown(eventId: String?, roomId: String?): Boolean {
    if (null != eventId && null != roomId) {
        try {
            val sessions = Matrix.getInstance(applicationContext).sessions

            if (null != sessions && sessions.isNotEmpty()) {
                for (session in sessions) {
                    if (session.dataHandler.store?.isReady == true) {
                        session.dataHandler.store?.getEvent(eventId, roomId)?.let {
                            Log.e(
                                LOG_TAG,
                                "## isEventAlreadyKnown() : ignore the event " + eventId
                                        + " in room " + roomId + " because it is already known"
                            )
                            return true
                        }
                    }
                }
            }
        } catch (e: Exception) {
            Log.e(
                LOG_TAG,
                "## isEventAlreadyKnown() : failed to check if the event was already defined " + e.message,
                e
            )
        }

    }
    return false
}

private fun parseEvent(data: Map<String, String>?): Event? {
    // accept only event with room id.
    if (null == data || !data.containsKey("room_id") || !data.containsKey("event_id")) {
        return null
    }

    try {
        val event = Event()
        event.eventId = data["event_id"]
        event.sender = data["sender"]
        event.roomId = data["room_id"]
        event.setType(data["type"])
        event.originServerTs = System.currentTimeMillis()

        if (data.containsKey("content")) {
            event.updateContent(JsonParser().parse(data["content"]).asJsonObject)
        }

        return event
    } catch (e: Exception) {
        Log.e(LOG_TAG, "buildEvent fails " + e.localizedMessage, e)
    }

    return null
}

fun getDataColumn(uri: Uri, selection: String?, selectionArgs: Array<String>?): String? {
    val column = "_data"
    val projection = arrayOf(column)

    contentResolver.query(uri, projection, selection, selectionArgs, null).use { cursor ->
        if (cursor != null && cursor.moveToFirst()) {
            if (BuildConfig.DEBUG) {
                DatabaseUtils.dumpCursor(cursor)
            }

            val columnIndex = cursor.getColumnIndexOrThrow(column)
            return cursor.getString(columnIndex)
        }
    }
    return null
}

fun getPath(uri: Uri): String? {
    Timber.d("File - Authority: %s\n, Fragment: %s\n, Port: %s\n, Query: %s\n, Scheme: %s\n, Host: %s\n, Segments: %s"
            , uri.authority
            , uri.fragment
            , uri.port
            , uri.query
            , uri.scheme
            , uri.host
            , uri.pathSegments
    )

    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
        // DocumentProvider
        if (DocumentsContract.isDocumentUri(context, uri)) {
            // ExternalStorageProvider
            when {
                isExternalStorageDocument(uri) -> {
                    val docId = DocumentsContract.getDocumentId(uri)
                    val split = docId.split(":".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
                    val type = split[0]

                    return if ("primary".equals(type, ignoreCase = true)) {
                        Environment.getExternalStorageDirectory().toString() + "/" + split[1]
                    } else {
                        System.getenv("SECONDARY_STORAGE") + "/" + split[1]
                    }
                }
                isDownloadsDocument(uri) -> {

                    val id = DocumentsContract.getDocumentId(uri)
                    val contentUri = ContentUris.withAppendedId(
                            Uri.parse("content://downloads/public_downloads"), java.lang.Long.parseLong(id))

                    return getDataColumn(contentUri, null, null)
                }
                isMediaDocument(uri) -> {
                    val docId = DocumentsContract.getDocumentId(uri)
                    val split = docId.split(":".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
                    val type = split[0]

                    val contentUri = when (type) {
                        "image" -> MediaStore.Images.Media.EXTERNAL_CONTENT_URI
                        "video" -> MediaStore.Video.Media.EXTERNAL_CONTENT_URI
                        "audio" -> MediaStore.Audio.Media.EXTERNAL_CONTENT_URI
                        else -> {
                            throw RuntimeException("Unknown content type: $type")
                        }
                    }

                    val selection = "_id=?"
                    val selectionArgs = arrayOf(split[1])

                    return getDataColumn(contentUri, selection, selectionArgs)
                }
                isGoogleDriveUri(uri) -> {
                    context.showErrorMessage(R.string.msg_not_supported_on_google_drive)
                }
            }
        }
    }

    if ("content".equals(uri.scheme, ignoreCase = true)) {
        // Return the remote address
        return if (isGooglePhotosUri(uri)) {
            uri.lastPathSegment
        } else {
            getDataColumn(uri, null, null)
        }
    } else if ("file".equals(uri.scheme, ignoreCase = true)) {
        return uri.path
    }

    return null
}

