@ReadOnlyComposable
fun WalletTheme.buttonStyle(
  treatment: ButtonModel.Treatment,
  size: ButtonModel.Size,
  cornerRadius: Dp = 16.dp,
  enabled: Boolean,
): ButtonStyle {
  val textColor = textColor(treatment = treatment)
  val textStyle =
    buttonTextStyle(
      type =
        when (treatment) {
          Tertiary, TertiaryNoUnderline -> LabelType.Label2
          else -> LabelType.Label1
        },
      underline =
        treatment == Tertiary ||
          treatment == TertiaryPrimary ||
          treatment == TertiaryDestructive,
      textColor = textColor
    )
  val isTextButton =
    treatment == TertiaryDestructive ||
      treatment == Tertiary ||
      treatment == TertiaryNoUnderline
  return ButtonStyle(
    textStyle = textStyle,
    shape = RoundedCornerShape(cornerRadius),
    backgroundColor =
      if (enabled) {
        treatment.normalBackgroundColor()
      } else {
        treatment.disabledBackgroundColor()
      },
    iconColor = iconColor(treatment),
    iconSize = treatment.leadingIconSize,
    isTextButton = isTextButton,
    fillWidth = size == Footer,
    height =
      when (size) {
        Compact -> 32.dp
        Floating -> 64.dp
        Footer, Regular -> 52.dp
        FitContent -> null
      },
    minWidth =
      when (size) {
        Regular ->
          if (isTextButton) {
            0.dp
          } else {
            140.dp
          }
        else -> Dp.Unspecified
      },
    verticalPadding =
      when (size) {
        Compact -> 4.dp
        Floating -> 20.dp
        else -> 8.dp
      },
    horizontalPadding =
      if (isTextButton) {
        0.dp
      } else {
        when (size) {
          Regular, Footer, FitContent -> 16.dp
          Compact -> 12.dp
          Floating -> 22.dp
        }
      }
  )
}

