class HistoryOrderBasicsPagingSource(
    private val firestore: FirebaseFirestore,
    private val userId: String
) : PagingSource<Query, OrderBasicNetworkDto>() {

    private var initialPageQuery: Query? = null

    override suspend fun load(params: LoadParams<Query>): LoadResult<Query, OrderBasicNetworkDto> {
        return try {
            initialPageQuery = initialPageQuery ?: firestore.collection(ORDERS_BASIC_COLLECTION)
                .whereIn(
                    ORDER_STATE_FIELD,
                    listOf(ORDER_STATE_ARCHIVED, ORDER_STATE_DELIVERED)
                )
                .whereEqualTo(ORDER_USER_ID_FIELD, userId)
                //.orderBy(ORDER_STATE_FIELD, Query.Direction.DESCENDING) // show delivered items first
                .orderBy(ORDER_CREATED_AT_FIELD, Query.Direction.DESCENDING)
                .limit(params.loadSize.toLong())

            val currentPageQuery = params.key ?: initialPageQuery!!
            val currentPageData = currentPageQuery.get().await()

            val nextPageQuery = if (!currentPageData.isEmpty) {
                val lastVisibleItem = currentPageData.documents[currentPageData.size() - 1]
                initialPageQuery!!.startAfter(lastVisibleItem)
            } else {
                null
            }

            if (!currentPageData.isNetworkData()) {
                throw Exception("Network error.")
            }

            LoadResult.Page(
                data = currentPageData.toObjects(OrderBasicNetworkDto::class.java),
                prevKey = null,
                nextKey = nextPageQuery
            )
        } catch (e: Exception) {
            LoadResult.Error(e)
        }
    }

    override fun getRefreshKey(state: PagingState<Query, OrderBasicNetworkDto>): Query? = initialPageQuery
}

interface AdbServiceWrapper {
  /**
   * Executes a command using the ADB executable configured for the [Project]
   *
   * [args] List of argument to pass to ADB executable [stdin] String to pass as "stdin" to the ADB
   * executable, to be used if there is interaction required
   */
  @AnyThread suspend fun executeCommand(args: List<String>, stdin: String = ""): AdbCommandResult

  /**
   * Returns when the device corresponding to [pairingResult] is visible as a `connected` device to
   * the underlying ADB implementation.
   *
   * Throws a [AdbCommandException] in case the device does not show up as online within a
   * "reasonable" timeout (chosen by the implementation).
   */
  @AnyThread suspend fun waitForOnlineDevice(pairingResult: PairingResult): AdbOnlineDevice

  /** Retrieve ADB server-status */
  @AnyThread suspend fun getServerStatus(): ServerStatus
}

data class AdbOnlineDevice(val id: String, val properties: Map<String, String>) {
  val displayString: String
    get() {
      // TODO: Use DeviceNameRenderer class when it has moved out of android.core module
      val manufacturer = properties[IDevice.PROP_DEVICE_MANUFACTURER] ?: ""
      val model = properties[IDevice.PROP_DEVICE_MODEL] ?: id
      return if (model.startsWith(manufacturer, true)) model else "$manufacturer $model"
    }
}

@Database(entities = [UserEntity::class], version = 1)
abstract class UserDatabase : RoomDatabase() {

    abstract fun userDao(): UserDaoInterface

    companion object {
        @Volatile
        private var INSTANCE: UserDatabase? = null

        fun getDatabase(context: Context): UserDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    UserDatabase::class.java,
                    USER_DATABASE
                ).build()

                INSTANCE = instance
                instance
            }
        }
    }
}

