var needFixRoomQuery = false
fun Cursor.fixRoomQuery(context: Context): Cursor {
  if (Build.VERSION.SDK_INT >= 28 && needFixRoomQuery) {
    (this as? AbstractWindowedCursor)?.apply {
      CursorFixer.fixCursor(context)
      window = CursorWindow("CompatFixed", CursorFixer.fixedCursorWindowSize)
    }
  }
  needFixRoomQuery = false
  return this
}

