fun initialize(
  preferImmediatelyAvailableCredentials: Boolean,
  gClientId: String?,
  context: Context,
): Pair<CredentialManagerExceptions?, String> {
  return try {
    credentialManager = CredentialManager.create(context = context)
    this.preferImmediatelyAvailableCredentials = preferImmediatelyAvailableCredentials
    if (gClientId != null) {
      serverClientID = gClientId
    }
    Pair(null, "Initialization successful")
  } catch (e: Exception) {
    Log.d("CredentialManager", "${e.message}")
    val message = e.localizedMessage
    Pair(
      CredentialManagerExceptions(
        code = 101,
        message = "Initialization failure",
        details = message
      ), ""
    )
  }
}

suspend fun savePasswordCredentials(
  username: String,
  password: String,
  context: Context
): Pair<CredentialManagerExceptions?, String> {
  return try {
    credentialManager.createCredential(
      request = CreatePasswordRequest(
        id = username,
        password = <PASSWORD>,
        preferImmediatelyAvailableCredentials = preferImmediatelyAvailableCredentials
      ),
      context = context
    )
    Log.v("CredentialTest", "Credentials successfully added")
    Pair(null, "Credentials saved")
  } catch (e: CreateCredentialCancellationException) {
    Pair(
      CredentialManagerExceptions(
        code = 301,
        message = "Save credentials canceled",
        details = e.localizedMessage
      ), ""
    )
  } catch (e: CreateCredentialException) {
    Pair(
      e.localizedMessage?.let {
        CredentialManagerExceptions(
          code = 302,
          details = "Create credentials failed",
          message = it
        )
      }, ""
    )
  } catch (e: Exception) {
    Pair(
      CredentialManagerExceptions(
        code = 302,
        message = "Create credentials failed, ${e.message}",
        details = e.localizedMessage
      ), ""
    )
  }
}

/**
 * Fetches password, Google, or passkey credentials based on the provided options.
 *
 * @param context The context from which the credentials are fetched.
 * @param requestJson Optional JSON string required for passkey or Google credentials.
 * @param credentialMangerFetchOptions Object holding options to enable different types of credentials (passkey, Google, or password-based).
 * @return A Pair containing either an exception or the fetched credential response.
 */
suspend fun getPasswordCredentials(
  context: Context,
  requestJson: String?,
  credentialMangerFetchOptions: CredentialMangerFetchOptions
): Pair<CredentialManagerExceptions?, CredentialManagerResponse?> {
  return try {
    // Check if all fetch options are disabled
    if (!credentialMangerFetchOptions.isAnyOptionEnabled()) {
      return Pair(
        CredentialManagerExceptions(
          code = 206,
          message = "Credential fetch options are not enabled",
          details = "Enable at least one credential fetch option (passkey, Google, or password)."
        ), null
      )
    }

    // Validate serverClientID if Google sign-in is enabled
    if (credentialMangerFetchOptions.googleSignInEnabled && !this::serverClientID.isInitialized) {
      return Pair(
        CredentialManagerExceptions(
          code = 503,
          message = "Google client not initialized",
          details = "Ensure Google credentials are provided."
        ), null
      )
    }

    // Validate requestJson for Passkey or Google Sign-In
    if (credentialMangerFetchOptions.requiresRequestJson() && requestJson == null) {
      return Pair(
        CredentialManagerExceptions(
          code = 207,
          message = "RequestJson is required",
          details = "Provide requestJson for passkey or Google sign-in."
        ), null
      )
    }

    // Build the credential request based on enabled options
    val getCredRequest = buildCredentialRequest(
      requestJson = requestJson,
      credentialMangerFetchOptions = credentialMangerFetchOptions
    )

    // Fetch credentials using the credentialManager
    val credentialResponse = credentialManager.getCredential(
      request = getCredRequest,
      context = context
    )

    // Handle the fetched credentials and return the appropriate response
    val response = handleCredentialResponse(credentialResponse)
    Pair(null, response)

  } catch (e: GetCredentialCancellationException) {
    Pair(
      CredentialManagerExceptions(
        code = 201,
        message = "Login canceled",
        details = e.localizedMessage
      ), null
    )
  } catch (e: NoCredentialException) {
    Pair(
      CredentialManagerExceptions(
        code = 202,
        message = "No credentials found",
        details = e.localizedMessage
      ), null
    )
  } catch (e: GetCredentialException) {
    Pair(
      CredentialManagerExceptions(
        code = 204,
        message = "Login failed",
        details = e.localizedMessage
      ), null
    )
  } catch (e: Exception) {
    Pair(
      CredentialManagerExceptions(
        code = 204,
        message = "Login failed",
        details = e.localizedMessage
      ), null
    )
  }
}

