private fun CredentialMangerFetchOptions.isAnyOptionEnabled(): Boolean {
  return passKeyEnabled || googleSignInEnabled || passwordBasedCredentialsEnabled
}

private fun CredentialMangerFetchOptions.requiresRequestJson(): Boolean {
  return passKeyEnabled || googleSignInEnabled
}

private fun buildCredentialRequest(
  requestJson: String?,
  credentialMangerFetchOptions: CredentialMangerFetchOptions
): GetCredentialRequest {
  val requestBuilder = GetCredentialRequest.Builder()

  if (credentialMangerFetchOptions.passwordBasedCredentialsEnabled) {
    requestBuilder.addCredentialOption(GetPasswordOption())
  }

  if (credentialMangerFetchOptions.passKeyEnabled && requestJson != null) {
    requestBuilder.addCredentialOption(GetPublicKeyCredentialOption(requestJson))
  }

  if (credentialMangerFetchOptions.googleSignInEnabled && this::serverClientID.isInitialized) {
    val googleIdOption = GetGoogleIdOption.Builder()
      .setFilterByAuthorizedAccounts(false)
      .setNonce(System.currentTimeMillis().toString())
      .setServerClientId(serverClientID)
      .build()
    requestBuilder.addCredentialOption(googleIdOption)
  }

  return requestBuilder.build()
}

private fun handleCredentialResponse(credentialResponse: GetCredentialResponse): CredentialManagerResponse {
  return when (val credential = credentialResponse.credential) {
    is PasswordCredential -> {
      CredentialManagerResponse(
        type = CredentialType.PasswordCredentials,
        passwordCredentials = PasswordCredentials(username = credential.id, password = <PASSWORD>)
      )
    }
    is CustomCredential -> {
      if (credential.type == GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL) {
        try {
          val googleIdTokenCredential = GoogleIdTokenCredential.createFrom(credential.data)
          CredentialManagerResponse(
            type = CredentialType.GoogleCredentials,
            googleCredentials = googleIdTokenCredential
          )
        } catch (e: GoogleIdTokenParsingException) {
          throw Exception("Failed to parse Google credentials")
        }
      } else {
        throw NoCredentialException("No credentials found")
      }
    }
    is PublicKeyCredential -> {
      CredentialManagerResponse(
        type = CredentialType.PublicKeyCredentials,
        publicKeyCredentials = credential.authenticationResponseJson
      )
    }
    else -> {
      throw NoCredentialException("No credentials found")
    }
  }
}

suspend fun saveGoogleCredentials(useButtonFlow: Boolean, context: Context): Pair<CredentialManagerExceptions?, GoogleIdTokenCredential?> {
  if (!this::serverClientID.isInitialized) {
    return Pair(
      CredentialManagerExceptions(
        code = 503,
        message = "Google client is not initialized yet",
        details = "Check if Google credentials is provided"
      ), null
    )
  }

  val googleCredentialOption = if (useButtonFlow) {
    GetSignInWithGoogleOption.Builder(serverClientID)
      .setNonce(System.currentTimeMillis().toString())
      .build()
  } else {
    GetGoogleIdOption.Builder()
      .setFilterByAuthorizedAccounts(false)
      .setNonce(System.currentTimeMillis().toString())
      .setServerClientId(serverClientID)
      .build()
  }

  val request: GetCredentialRequest = GetCredentialRequest.Builder()
    .addCredentialOption(googleCredentialOption)
    .build()

  val result = credentialManager.getCredential(
    request = request,
    context = context,
  )


  when (val credential = result.credential) {
    is CustomCredential -> {
      if (credential.type == GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL) {
        return try {
          // Use googleIdTokenCredential and extract id to validate and
          // authenticate on your server.
          val googleIdTokenCredential = GoogleIdTokenCredential
            .createFrom(credential.data)
          Log.d("CredentialGoogleTest2",
            "Google credentials successfully added ${googleIdTokenCredential.id}")
          Pair(null, googleIdTokenCredential)
        } catch (e: GoogleIdTokenParsingException) {
          Pair(
            CredentialManagerExceptions(
              code = 501,
              message = "Received an invalid google id token response",
              details = e.localizedMessage,
            ), null
          )
        }
      }
    }
  }
  return Pair(
    CredentialManagerExceptions(
      code = 502,
      message = "Invalid request",
      details = null
    ), null
  )
}

suspend fun logout(): Pair<CredentialManagerExceptions?, String> {
  return try {
    credentialManager.clearCredentialState(
      ClearCredentialStateRequest()
    )
    Pair(null, "Logout successful")
  } catch (e: Exception) {
    Pair(
      CredentialManagerExceptions(
        code = 701,
        message = "Logout failed",
        details = e.localizedMessage
      ), ""
    )
  }
}

