private fun getBitmapFromURL(strURL: String): Bitmap? {
    try {
        val url = URL(strURL)
        val connection = url.openConnection() as HttpURLConnection
        connection.doInput = true
        connection.connect()
        val input = connection.inputStream
        return BitmapFactory.decodeStream(input)
    } catch (e: IOException) {
        e.printStackTrace()
    }
    return null
}

