class ConversationListAdapter(context: MessengerActivity, initialConversations: List<Conversation>,
                              val multiSelector: ConversationsMultiSelectDelegate?,
                              var swipeToDeleteListener: SwipeToDeleteListener,
                              private val conversationExpandedListener: ConversationExpandedListener)
    : SectionedRecyclerViewAdapter<ConversationViewHolder>(), IConversationListAdapter {

    private val dataProvider: ConversationAdapterDataProvider = ConversationAdapterDataProvider(this, context)
    private val itemBinder: ConversationItemBinder = ConversationItemBinder(context)
    private val headerBinder: ConversationSectionHeaderBinder = ConversationSectionHeaderBinder(this, dataProvider, context)

    override var conversations: MutableList<Conversation>
        get() = dataProvider.conversations
        set(convos) = dataProvider.generateSections(convos)

    override val sectionCounts: MutableList<SectionType>
        get() = dataProvider.sectionCounts

    init {
        this.conversations = initialConversations.toMutableList()
        if (this.multiSelector != null) this.multiSelector.setAdapter(this)

        shouldShowHeadersForEmptySections(showHeaderAboutTextingOnline())
    }

    override fun getSectionCount() = sectionCounts.size
    override fun getItemCount(section: Int) = sectionCounts[section].count

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ConversationViewHolder {
        val view = LayoutInflater.from(parent.context).inflate(if (viewType == SectionedRecyclerViewAdapter.VIEW_TYPE_HEADER)
            R.layout.conversation_list_header else R.layout.conversation_list_item,
                parent, false)

        return ConversationViewHolder(view, conversationExpandedListener, this)
    }

    override fun onViewRecycled(holder: ConversationViewHolder) {
        super.onViewRecycled(holder)
        try {
            Glide.with(holder.itemView.context).clear(holder.image!!)
        } catch (t: Throwable) { }
    }

    override fun onBindHeaderViewHolder(holder: ConversationViewHolder, section: Int) {
        if (sectionCounts[section].type == SectionType.CARD_ABOUT_ONLINE) {
            headerBinder.bindOnlinePromotion(holder)
        } else {
            headerBinder.bind(holder, section)
        }
    }

    override fun onBindViewHolder(holder: ConversationViewHolder, section: Int, relativePosition: Int,
                                  absolutePosition: Int) {
        if (absolutePosition >= dataProvider.conversations.size || absolutePosition < 0) {
            return
        }

        val conversation = dataProvider.conversations[absolutePosition]

        holder.conversation = conversation
        holder.absolutePosition = absolutePosition

        itemBinder.showText(holder, conversation)
        itemBinder.showTextStyle(holder, conversation)
        itemBinder.indicatePinned(holder, conversation)
        itemBinder.showDate(holder, conversation)
        itemBinder.showImageColor(holder, conversation)

        if (ContactUtils.shouldDisplayContactLetter(conversation)) {
            itemBinder.showContactLetter(holder, conversation)
        } else {
            itemBinder.showContactPlaceholderIcon(holder, conversation)
        }

        if (!conversation.imageUri.isNullOrEmpty()) {
            itemBinder.showImage(holder, conversation)
        }
    }

    override fun getCountForSection(sectionType: Int) = dataProvider.getCountForSection(sectionType)
    override fun findPositionForConversationId(id: Long) = dataProvider.findPositionForConversationId(id)
    override fun removeItem(position: Int, type: ReorderType) = dataProvider.removeItem(position, type)
    fun deleteItem(position: Int) = removeItem(position, ReorderType.DELETE)
    fun archiveItem(position: Int) = removeItem(position, ReorderType.ARCHIVE)
    fun findConversationForPosition(position: Int) = dataProvider.findConversationForPosition(position)
    fun showHeaderAboutTextingOnline() = Build.FINGERPRINT != "robolectric" && !Account.exists() &&
            Settings.showTextOnlineOnConversationList &&
            Math.abs(Settings.installTime - Date().time) > TimeUtils.MINUTE * 0
}

class UseCaseCamera(
    private val cameraGraph: CameraGraph,
    private val useCases: List<UseCase>,
    private val surfaceToStreamMap: Map<DeferrableSurface, StreamId>,
    private val cameraScope: CoroutineScope
) {
    private val debugId = useCaseCameraIds.incrementAndGet()

    private var _activeUseCases = setOf<UseCase>()

    var activeUseCases: Set<UseCase>
        get() = _activeUseCases
        set(value) {
            // Note: This may be called with the same set of values that was previously set. This
            // is used as a signal to indicate the properties of the UseCase may have changed.
            _activeUseCases = value
            updateUseCases()
        }

    init {
        debug { "Configured $this for $useCases" }
    }

    fun close() {
        debug { "Closing $this" }
        cameraGraph.close()
    }

    suspend fun enableTorchAsync(enabled: Boolean): Deferred<FrameNumber> {
        return cameraGraph.acquireSession().use {
            it.setTorch(
                when (enabled) {
                    true -> TorchState.ON
                    false -> TorchState.OFF
                }
            )
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    private fun updateUseCases() {
        val repeatingStreamIds = mutableSetOf<StreamId>()
        for (useCase in activeUseCases) {
            val repeatingCapture = useCase.sessionConfig?.repeatingCaptureConfig
            if (repeatingCapture != null) {
                for (deferrableSurface in repeatingCapture.surfaces) {
                    val streamId = surfaceToStreamMap[deferrableSurface]
                    if (streamId != null) {
                        repeatingStreamIds.add(streamId)
                    }
                }
            }
        }

        // TODO: This needs to aggregate the current parameters and pass them to the request.

        // In order to preserve ordering, this starts acquiring the session on the current thread,
        // and will only switch to the cameraScope threads if it needs to suspend. This is important
        // because access to the cameraGraph is well ordered, and if the coroutine suspends, it will
        // resume in the order it accessed the cameraGraph.
        cameraScope.launch(start = CoroutineStart.UNDISPATCHED) {
            cameraGraph.acquireSession().use {
                it.setRepeating(
                    Request(
                        streams = repeatingStreamIds.toList()
                    )
                )
            }
        }
    }

    override fun toString(): String = "UseCaseCamera-$debugId"

    @Module
    class Bindings {
        companion object {
            @UseCaseCameraScope
            @Provides
            fun provideCameraGraphController(
                cameraPipe: CameraPipe,
                useCases: java.util.ArrayList<UseCase>,
                cameraConfig: CameraConfig,
                callbackMap: CameraCallbackMap,
                coroutineScope: CoroutineScope,
            ): UseCaseCamera {
                val streamConfigs = mutableListOf<StreamConfig>()
                val useCaseMap = mutableMapOf<StreamConfig, UseCase>()

                // TODO: This may need to combine outputs that are (or will) share the same output
                //  imageReader or surface. Right now, each UseCase gets its own [StreamConfig]
                // TODO: useCases only have a single `attachedSurfaceResolution`, yet they have a
                //  list of deferrableSurfaces.
                for (useCase in useCases) {
                    val config = StreamConfig(
                        size = useCase.attachedSurfaceResolution!!,
                        format = StreamFormat(useCase.imageFormat),
                        camera = cameraConfig.cameraId,
                        type = StreamType.SURFACE,
                        deferrable = false
                    )
                    streamConfigs.add(config)
                    useCaseMap[config] = useCase
                }

                // Build up a config (using TEMPLATE_PREVIEW by default)
                val config = CameraGraph.Config(
                    camera = cameraConfig.cameraId,
                    streams = streamConfigs,
                    listeners = listOf(callbackMap),
                    template = RequestTemplate(CameraDevice.TEMPLATE_PREVIEW)
                )
                val graph = cameraPipe.create(config)

                val surfaceToStreamMap = mutableMapOf<DeferrableSurface, StreamId>()
                for ((streamConfig, useCase) in useCaseMap) {
                    val stream = graph.streams[streamConfig]
                    val useCaseSessionConfig = useCase.sessionConfig

                    // TODO: UseCases have inconsistent opinions about how surfaces are handled,
                    //  this code assumes only a single surface per UseCase.
                    val deferredSurfaces = useCaseSessionConfig?.surfaces
                    if (stream != null && deferredSurfaces != null && deferredSurfaces.size == 1) {
                        val deferredSurface = deferredSurfaces[0]
                        graph.setSurface(stream.id, deferredSurface.surface.get())
                        surfaceToStreamMap[deferredSurface] = stream.id
                    }
                }

                graph.start()
                return UseCaseCamera(graph, useCases, surfaceToStreamMap, coroutineScope)
            }
        }
    }
}

cameraScope.launch(start = CoroutineStart.UNDISPATCHED) {
    cameraGraph.acquireSession().use {
        it.setRepeating(
            Request(
                streams = repeatingStreamIds.toList()
            )
        )
    }
}

