open class GameGesture(context: Context?) : OnTouchListener {

    companion object {
        private const val SWIPE_THRESHOLD = 50
        private const val SWIPE_VELOCITY_THRESHOLD = 0
    }

    private var gestureDetector: GestureDetector? = null
    private var cxt: Context? = null

    init {
        gestureDetector = GestureDetector(context, GameGestureListener())
        cxt = context
    }

    override fun onTouch(v: View, event: MotionEvent): Boolean {
        return gestureDetector!!.onTouchEvent(event)
    }

    private inner class GameGestureListener : SimpleOnGestureListener() {

        override fun onDown(e: MotionEvent): Boolean {
            return true
        }

        override fun onFling(
            e1: MotionEvent,
            e2: MotionEvent,
            velocityX: Float,
            velocityY: Float
        ): Boolean {
            var result = false
            try {
                val diffY = e2.y - e1.y
                val diffX = e2.x - e1.x
                result = if (abs(diffX) > abs(diffY)) {
                    if (abs(diffX) > Companion.SWIPE_THRESHOLD && abs(velocityX) > Companion.SWIPE_VELOCITY_THRESHOLD) {
                        if (diffX > 0) {
                            onSwipeRight()
                        } else {
                            onSwipeLeft()
                        }
                    } else {
                        nichts()
                    }
                } else {
                    if (abs(diffY) > Companion.SWIPE_THRESHOLD && abs(velocityY) > Companion.SWIPE_VELOCITY_THRESHOLD) {
                        if (diffY > 0) {
                            onSwipeBottom()
                        } else {
                            onSwipeTop()
                        }
                    } else {
                        nichts()
                    }
                }
            } catch (exception: Exception) {
                exception.printStackTrace()
            }
            return result
        }

    }

    open fun onSwipeRight(): Boolean {
        return false
    }

    open fun onSwipeLeft(): Boolean {
        return false
    }

    open fun nichts(): Boolean {
        return false
    }

    open fun onSwipeTop(): Boolean {
        return false
    }

    open fun onSwipeBottom(): Boolean {
        return false
    }

}

fun setNotDisplayInNotch(activity: Activity) {
    runCatching {
        val window = activity.window
        val layoutParams = window.attributes
        val layoutParamsExCls = Class.forName("com.huawei.android.view.LayoutParamsEx")
        val con = layoutParamsExCls.getConstructor(WindowManager.LayoutParams::class.java)
        val layoutParamsExObj = con.newInstance(layoutParams)
        val method = layoutParamsExCls.getMethod("clearHwFlags", Int::class.javaPrimitiveType)
        method.invoke(layoutParamsExObj, FLAG_NOTCH_SUPPORT)
        window.windowManager.updateViewLayout(window.decorView, window.decorView.layoutParams)
    }.onFailure { it.printStackTrace() }
}

class ListsReorderDialogFragment : AppCompatDialogFragment() {

    private var binding: DialogListsReorderBinding? = null
    private lateinit var adapter: ListsAdapter

    override fun onCreateDialog(savedInstanceState: Bundle?): Dialog {
        val binding = DialogListsReorderBinding.inflate(layoutInflater)
        this.binding = binding

        val controller = DragSortController(
            binding.listViewListsReorder,
            R.id.dragGripViewItemList, DragSortController.ON_DOWN,
            DragSortController.CLICK_REMOVE
        )
        controller.isRemoveEnabled = false
        binding.listViewListsReorder.setFloatViewManager(controller)
        binding.listViewListsReorder.setOnTouchListener(controller)
        binding.listViewListsReorder.setDropListener { from: Int, to: Int -> reorderList(from, to) }

        adapter = ListsAdapter(activity)
        binding.listViewListsReorder.adapter = adapter

        LoaderManager.getInstance(this)
            .initLoader(ListsActivity.LISTS_REORDER_LOADER_ID, null, listsLoaderCallbacks)

        return MaterialAlertDialogBuilder(requireContext())
            .setView(binding.root)
            .setTitle(R.string.action_lists_reorder)
            .setNegativeButton(R.string.discard, null)
            .setPositiveButton(android.R.string.ok) { _: DialogInterface, _: Int ->
                saveListsOrder()
                dismiss()
            }
            .create()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        this.binding = null
    }

    private fun reorderList(from: Int, to: Int) {
        adapter.reorderList(from, to)
    }

    private fun saveListsOrder() {
        val count = adapter.count
        val listIdsInOrder: MutableList<String> = ArrayList(count)
        for (position in 0 until count) {
            val list = adapter.getItem(position)
            if (list != null && !list.id.isNullOrEmpty()) {
                listIdsInOrder.add(list.id)
            }
        }
        ListsTools.reorderLists(requireContext(), listIdsInOrder)
    }

    private val listsLoaderCallbacks: LoaderManager.LoaderCallbacks<List<OrderedList>> =
        object : LoaderManager.LoaderCallbacks<List<OrderedList>> {
            override fun onCreateLoader(id: Int, args: Bundle?): Loader<List<OrderedList>> {
                return OrderedListsLoader(activity)
            }

            override fun onLoadFinished(
                loader: Loader<List<OrderedList>>,
                data: List<OrderedList>
            ) {
                if (!isAdded) {
                    return
                }
                adapter.setData(data)
            }

            override fun onLoaderReset(loader: Loader<List<OrderedList>>) {
                adapter.setData(null)
            }
        }
}

class MediaType private constructor(
    private val mediaType: String,

    /**
     * Returns the high-level media type, such as "text", "image", "audio", "video", or "application".
     */
    @get:JvmName("type") val type: String,

    /**
     * Returns a specific media subtype, such as "plain" or "png", "mpeg", "mp4" or "xml".
     */
    @get:JvmName("subtype") val subtype: String,

    /** Alternating parameter names with their values, like `["charset', "utf-8"]`. */
    private val parameterNamesAndValues: Array<String>
) {

fun parameter(name: String): String? {
    for (i in parameterNamesAndValues.indices step 2) {
        if (parameterNamesAndValues[i].equals(name, ignoreCase = true)) {
            return parameterNamesAndValues[i + 1]
        }
    }
    return null
}

@JvmStatic
fun String.toMediaType(): MediaType {
    val typeSubtype = TYPE_SUBTYPE.matcher(this)
    require(typeSubtype.lookingAt()) { "No subtype found for: \"$this\"" }
    val type = typeSubtype.group(1).toLowerCase(Locale.US)
    val subtype = typeSubtype.group(2).toLowerCase(Locale.US)

    val parameterNamesAndValues = mutableListOf<String>()
    val parameter = PARAMETER.matcher(this)
    var s = typeSubtype.end()
    while (s < length) {
        parameter.region(s, length)
        require(parameter.lookingAt()) {
            "Parameter is not formatted correctly: \"${substring(s)}\" for: \"$this\""
        }

        val name = parameter.group(1)
        if (name == null) {
            s = parameter.end()
            continue
        }

        val token = parameter.group(2)
        val value = when {
            token == null -> {
                // Value is "double-quoted". That's valid and our regex group already strips the quotes.
                parameter.group(3)
            }
            token.startsWith("'") && token.endsWith("'") && token.length > 2 -> {
                // If the token is 'single-quoted' it's invalid! But we're lenient and strip the quotes.
                token.substring(1, token.length - 1)
            }
            else -> token
        }

        parameterNamesAndValues += name
        parameterNamesAndValues += value
        s = parameter.end()
    }

    return MediaType(this, type, subtype, parameterNamesAndValues.toTypedArray())
}

    parameter.group(3)
}
token.startsWith("'") && token.endsWith("'") && token.length > 2 -> {
    // If the token is 'single-quoted' it's invalid! But we're lenient and strip the quotes.
    token.substring(1, token.length - 1)
}

@JvmStatic
fun String.toMediaTypeOrNull(): MediaType? {
    return try {
        toMediaType()
    } catch (_: IllegalArgumentException) {
        null
    }
}

fun getSdkInfo(): List<SdkInfo> {
    val list = arrayListOf<SdkInfo>()
    list.add(SdkInfo("GrowingIO SDK信息", isHeader = true))
    val hasDepend = hasClass("com.growingio.android.sdk.collection.CoreInitialize")
    if (hasDepend) {
        val (_, sdkVersion, _) = GioPluginConfig.analyseDepend()
        list.tryAdd { SdkInfo("SDK版本", sdkVersion) }
        list.tryAdd { SdkInfo("ProjectId", CoreInitialize.coreAppState().projectId) }
        list.tryAdd { SdkInfo("URLScheme", CoreInitialize.config().getsGrowingScheme()) }
        list.tryAdd { SdkInfo("DataServerHost", NetworkConfig.getInstance().endPoint) }

        val sdkInfoStrArray = CoreInitialize.config().toString().split("\n")
        for (info in sdkInfoStrArray) {
            val infoKv = info.split(":")
            if (infoKv.size > 1) {
                getMappingInfo(infoKv[0], infoKv[1])?.let {
                    list.tryAdd { it }
                }
            }
        }
        list.tryAdd { SdkInfo("数据加密", "打开") }
        list.tryAdd { SdkInfo("登录账户", CoreInitialize.growingIOIPC().userId) }
        list.tryAdd {
            SdkInfo(
                "位置信息",
                "${CoreInitialize.coreAppState().latitude},${CoreInitialize.coreAppState().longitude}"
            )
        }


    } else {
        list.add(SdkInfo("SDK", "SDK未集成"))
    }

    return list
}

