internal class DslDiscovery(private val classLoader: ClassLoader) : Discovery {
    /*
     * Lazily memoize the results of the classpath scan.
     */
    private val scanResult by lazy { scan() }

    override fun discover(request: DiscoveryRequest): Flow<ExperimentDefinition> {
        return findExperiments()
            .map { cls ->
                val exp = cls.constructors[0].newInstance() as Experiment
                exp.toDefinition()
            }
            .filter(select(request.selectors))
            .filter(filter(request.filters))
            .asFlow()
    }

    /**
     * Find the classes on the classpath implementing the [Experiment] class.
     */
    private fun findExperiments(): Sequence<Class<out Experiment>> {
        return scanResult
            .getSubclasses(Experiment::class.java.name)
            .filter { !(it.isAbstract || it.isInterface) }
            .map { it.loadClass() }
            .filterIsInstance<Class<out Experiment>>()
            .asSequence()
    }

    /**
     * Create a predicate for filtering the experiments based on the specified [filters].
     */
    private fun filter(filters: List<DiscoveryFilter>): (ExperimentDefinition) -> Boolean = { def ->
        filters.isEmpty() || filters.all { it.test(def) }
    }

    /**
     * Create a predicate for selecting the experiments based on the specified [selectors].
     */
    private fun select(selectors: List<DiscoverySelector>): (ExperimentDefinition) -> Boolean = { def ->
        selectors.isEmpty() || selectors.any { it.test(def) }
    }

    /**
     * Scan the classpath using [ClassGraph].
     */
    private fun scan(): ScanResult {
        return ClassGraph()
            .addClassLoader(classLoader)
            .enableClassInfo()
            .enableExternalClasses()
            .ignoreClassVisibility()
            .rejectPackages(
                "java.*",
                "javax.*",
                "sun.*",
                "com.sun.*",
                "kotlin.*",
                "androidx.*",
                "org.jetbrains.kotlin.*",
                "org.junit.*"
            ).scan()
    }
}

private fun findExperiments(): Sequence<Class<out Experiment>> {
    return scanResult
        .getSubclasses(Experiment::class.java.name)
        .filter { !(it.isAbstract || it.isInterface) }
        .map { it.loadClass() }
        .filterIsInstance<Class<out Experiment>>()
        .asSequence()
}

private fun filter(filters: List<DiscoveryFilter>): (ExperimentDefinition) -> Boolean = { def ->
    filters.isEmpty() || filters.all { it.test(def) }
}

private fun select(selectors: List<DiscoverySelector>): (ExperimentDefinition) -> Boolean = { def ->
    selectors.isEmpty() || selectors.any { it.test(def) }
}

suspend fun Call.activityResultAwait(): ActivityResult {
    return suspendCancellableCoroutine { cot ->
        if (cot.isCompleted) {
            return@suspendCancellableCoroutine
        }
        val navigationDisposable: NavigationDisposable = navigateForResult(object : BiCallbackAdapter<ActivityResult>() {
            override fun onSuccess(result: RouterResult, activityResult: ActivityResult) {
                super.onSuccess(result, activityResult)
                if (!cot.isCompleted) {
                    cot.resume(activityResult) {}
                }
            }

            override fun onError(errorResult: RouterErrorResult) {
                super.onError(errorResult)
                if (!cot.isCompleted) {
                    cot.resumeWithException(errorResult.error)
                }
            }

            override fun onCancel(originalRequest: RouterRequest) {
                super.onCancel(originalRequest)
                if (!cot.isCompleted) {
                    cot.cancel()
                }
            }
        })
        cot.invokeOnCancellation {
            navigationDisposable.cancel()
        }
    }
}

suspend fun Call.intentAwait(): Intent {
    return activityResultAwait().apply {
        if (this.data == null) {
            throw ActivityResultException("the intent result data is null")
        }
    }.data!!
}

suspend fun Call.intentResultCodeMatchAwait(expectedResultCode: Int): Intent {
    return activityResultAwait().apply {
        if (this.data == null) {
            throw ActivityResultException("the intent result data is null")
        }
        if (expectedResultCode != this.resultCode) {
            throw ActivityResultException("the resultCode is not matching $expectedResultCode")
        }
    }.data!!
}

suspend fun Call.resultCodeAwait(): Int {
    return activityResultAwait().resultCode
}

suspend fun Call.resultCodeMatchAwait(expectedResultCode: Int) {
    activityResultAwait().let {
        if (expectedResultCode != it.resultCode) {
            throw ActivityResultException("the resultCode is not matching $expectedResultCode")
        }
    }
}

