            if (!destIsStation)
                camAnimTarget.postValue(CameraUpdateFactory.newLatLngBounds(latLngBoundBuilder.build(),
                        getApplication<Application>().resources.getDimension(R.dimen.camera_ab_pin_padding).toInt()))
