private inline fun <reified T> parseMapSafe(jsonMap: JSONObject?): Map<String, T> {
    val result = mutableMapOf<String, T>()

    if (jsonMap == null) {
        return result
    }

    try {
        for (key in jsonMap.keys()) {
            val messageJson = jsonMap.get(key).toString()

            Klaxon().converter(dateConverter)
                    .converter(uriConverter)
                    .parse<T>(messageJson)?.let { value -> result[key] = value }
        }
    } catch (e: Exception) {
        log(Log.WARN, "Cannot parse $jsonMap to ${T::class.java} because ${e.message}")
    }

    return result
}

private inline fun <reified T> parseArraySafe(jsonArray: JSONArray?): List<T> {
    val result = mutableListOf<T>()

    if (jsonArray == null) {
        return result
    }

    try {
        Klaxon().converter(dateConverter)
                .converter(uriConverter)
                .parseArray<T>(jsonArray.toString())?.let {
                    result.addAll(it);
                }

    } catch (e: Exception) {
        log(Log.WARN, "Cannot parse $jsonArray to ${T::class.java} because ${e.message}")
    }

    return result
}

private inline fun <reified T> parseSafe(json: JSONObject?): T? {
    if (json == null) {
        return null;
    }

    try {
        return Klaxon().converter(dateConverter)
                .converter(uriConverter)
                .parse<T>(json.toString())
    } catch (e: Exception) {
        log(Log.WARN, "Cannot parse $json to ${T::class.java} because ${e.message}")
    }

    return null
}

val newCells = ArrayList<Cell>()
if (!mPattern.isEmpty()) {
    val lastCell = mPattern[mPattern.size - 1]
    val dRow = cell.row - lastCell.row
    val dCol = cell.column - lastCell.column
    val rsign = if (dRow > 0) 1 else -1
    val csign = if (dCol > 0) 1 else -1

    if (dRow == 0) {
        for (i in 1 until Math.abs(dCol)) {
            newCells.add(Cell(lastCell.row, lastCell.column + i * csign))
        }
    } else if (dCol == 0) {
        for (i in 1 until Math.abs(dRow)) {
            newCells.add(Cell(lastCell.row + i * rsign,
                    lastCell.column))
        }
    } else if (Math.abs(dCol) == Math.abs(dRow)) {
        for (i in 1 until Math.abs(dRow)) {
            newCells.add(Cell(lastCell.row + i * rsign,
                    lastCell.column + i * csign))
        }
    }

}

val historySize = event.historySize
for (i in 0 until historySize + 1) {
    val x = if (i < historySize) {
        event.getHistoricalX(i)
    } else {
        event.x
    }

    val y = if (i < historySize) {
        event.getHistoricalY(i)
    } else {
        event.y
    }
    val patternSizePreHitDetect = mPattern.size
    var hitCell = detectAndAddHit(x, y)
    val patternSize = mPattern.size
    if (hitCell != null && patternSize == 1) {
        patternRule.patternInProgress = true
        notifyPatternStarted()
    }
    // note current x and y for rubber banding of in progress patterns
    val dx = Math.abs(x - inProgressX)
    val dy = Math.abs(y - inProgressY)
    if (dx + dy > squareWidth * 0.01f) {
        var oldX = inProgressX
        var oldY = inProgressY

        inProgressX = x
        inProgressY = y

        if (patternRule.patternInProgress && patternSize > 0) {
            val pattern = mPattern
            val radius = squareWidth * diameterFactor * 0.5f

            val lastCell = pattern[patternSize - 1]

            var startX = getCenterXForColumn(lastCell.column)
            var startY = getCenterYForRow(lastCell.row)

            var left: Float
            var top: Float
            var right: Float
            var bottom: Float

            val invalidateRect = invalidate

            if (startX < x) {
                left = startX
                right = x
            } else {
                left = x
                right = startX
            }

            if (startY < y) {
                top = startY
                bottom = y
            } else {
                top = y
                bottom = startY
            }

            // Invalidate between the pattern's last cell and the
            // current location
            invalidateRect.set((left - radius).toInt(),
                    (top - radius).toInt(), (right + radius).toInt(),
                    (bottom + radius).toInt())

            if (startX < oldX) {
                left = startX
                right = oldX
            } else {
                left = oldX
                right = startX
            }

            if (startY < oldY) {
                top = startY
                bottom = oldY
            } else {
                top = oldY
                bottom = startY
            }

            // Invalidate between the pattern's last cell and the
            // previous location
            invalidateRect.union((left - radius).toInt(),
                    (top - radius).toInt(), (right + radius).toInt(),
                    (bottom + radius).toInt())

            // Invalidate between the pattern's new cell and the
            // pattern's previous cell
            if (hitCell != null) {
                startX = getCenterXForColumn(hitCell.column)
                startY = getCenterYForRow(hitCell.row)

                if (patternSize >= 2) {
                    // (re-using hitcell for old cell)
                    hitCell = pattern[patternSize - 1
                            - (patternSize - patternSizePreHitDetect)]
                    oldX = getCenterXForColumn(hitCell.column)
                    oldY = getCenterYForRow(hitCell.row)

                    if (startX < oldX) {
                        left = startX
                        right = oldX
                    } else {
                        left = oldX
                        right = startX
                    }

                    if (startY < oldY) {
                        top = startY
                        bottom = oldY
                    } else {
                        top = oldY
                        bottom = startY
                    }
                } else {
                    right = startX
                    left = right
                    bottom = startY
                    top = bottom
                }

                val widthOffset = squareWidth / 2f
                val heightOffset = squareHeight / 2f

                invalidateRect.set((left - widthOffset).toInt(),
                        (top - heightOffset).toInt(),
                        (right + widthOffset).toInt(),
                        (bottom + heightOffset).toInt())
            }

            invalidate(invalidateRect)
        } else {
            invalidate()
        }
    }
}

