        val sb = StringBuilder()
        db = myDatabaseHelper.writableDatabase
        val cursor = db.query("Student", null, null, null, null, null, null)
        if (cursor.moveToFirst()) {
            do {
                val name = cursor.getString(cursor.getColumnIndex("name"))
