private fun drawCircleBorderAndHook(canvas: Canvas) {
    paint.style = Paint.Style.STROKE
    paint.alpha = 255

    path.reset()

    // Draw borders
    drawCircleBorder(canvas)
    // Draw hook
    drawHook()

    canvas.drawPath(path, paint)
}

private fun drawLeftHook() {
    if (animationProgress < 0.7f) {
        val progress = animationProgress.toRange(0f, 0.7f, 0f, 1f)
        val lineRadius = radius() * progress

        val endX: Float = (leftHookCircleX + lineRadius * 0.9f * Math.cos(Math.toRadians(-20.0))).toFloat()
        val endY: Float = (leftHookCircleY + lineRadius * Math.sin(Math.toRadians(-20.0)) * -1 + (hookOffsetY() * progress)).toFloat()

        // LeftHook: left half-segment
        path.lineTo(centerX() + endX, centerY() + endY)
    } else {
        val progress = animationProgress.toRange(0.7f, 1f, 0f, 0.5f)
        val lineRadius = radius() * (1 - progress)

        val endX: Float = (lineRadius * Math.cos(Math.toRadians(160.0))).toFloat()
        val endY: Float = (lineRadius * Math.sin(Math.toRadians(160.0)) * -1 + (hookOffsetY() * progress)).toFloat()

        // LeftHook: right half-segment
        path.moveTo((centerX() + hookCenterX).toFloat(), (centerY() + hookCenterY).toFloat())
        path.lineTo(centerX() + endX, centerY() + endY)
    }
}

    path.lineTo(centerX() + endX, centerY() + endY)
} else {
    val progress = animationProgress.toRange(0.7f, 1f, 0f, 0.5f)
    val lineRadius = radius() * (1 - progress)

    val endX: Float = (lineRadius * Math.cos(Math.toRadians(160.0))).toFloat()
    val endY: Float = (lineRadius * Math.sin(Math.toRadians(160.0)) * -1 + (hookOffsetY() * progress)).toFloat()

    // LeftHook: right half-segment
    path.moveTo((centerX() + hookCenterX).toFloat(), (centerY() + hookCenterY).toFloat())
    path.lineTo(centerX() + endX, centerY() + endY)
}

private fun drawRightHook() {
    if (animationProgress >= 0.7f) {
        val progress = animationProgress.toRange(0.7f, 1f, 0f, 0.75f)
        val lineRadius = radius() * progress

        val endX: Float = (lineRadius * Math.cos(Math.toRadians(45.0))).toFloat()
        val endY: Float = (lineRadius * Math.sin(Math.toRadians(45.0)) * -1 + hookOffsetY() * animationProgress).toFloat()

        // RightHook
        path.moveTo((centerX() + hookCenterX).toFloat(), (centerY() + hookCenterY).toFloat())
        path.lineTo(centerX() + endX, centerY() + endY)
    }
}

private fun startAnimation() {
    val endValue = if (checked) 1f else 0f
    val fraction = Math.abs(endValue - animationProgress)
    animator.setFloatValues(animationProgress, endValue)
    animator.duration = (duration * fraction).toLong()
    animator.addListener(object : AnimatorListenerAdapter() {
        override fun onAnimationCancel(animation: Animator?) {
            animation?.removeAllListeners()
        }

        override fun onAnimationEnd(animation: Animator?) {
            onChange(checked)
        }
    })
    animator.start()
}

private fun update(animation: ValueAnimator) {
    val fraction = animation.animatedValue as Float
    animationProgress = fraction
    if (useAnimatedColor()) {
        updateColorAnimation(animation.animatedFraction)
    }
    invalidate()
}

private fun updateColorAnimation(animatedFraction: Float) {
    if (!checked) colorAnimation = colorAnimationHsv.animateColor(colorFrom, colorTo, animatedFraction)
    else colorAnimation = colorAnimationHsv.animateColor(colorTo, colorFrom, animatedFraction)
}

class NetCore<Result> {
    companion object {
        val IO_EXCEPTION = "IO-EXCEPTION"
    }
    fun doGet(request: Requester<Result>, h: Handler, success: Result?.() -> Unit, failed: String.() -> Unit) {
        request.mUrl.let {
            if (!it.contains('?')) {
                request.mUrl += "?"
            }
            if (request.mUParam.isNotEmpty())
                request.mUrl += map2reqBody(request.mUParam)
        }
        getConnetion(request).apply {
            requestMethod = "GET"
            doOutput = false
            try {
                connect()
            } catch (ex: Exception) {
                ex.printStackTrace()
                h.post {
                    failed(IO_EXCEPTION)
                }
                return@apply
            }
            doNet(request.mType, request.mTypeToken, h, success, failed)
        }
    }

    fun doPost(request: Requester<Result>, h: Handler, success: Result?.() -> Unit, failed: String.() -> Unit) {
        getConnetion(request).apply {
            requestMethod = "POST"
            doOutput = true
            try {
                connect()
            } catch (ex: Exception) {
                ex.printStackTrace()
                h.post {
                    failed(IO_EXCEPTION)
                }
                return@apply
            }
            outputStream.apply {
                if (request.mBody.isNotEmpty())
                    write(map2reqBody(request.mBody).toByteArray())
                else if (request.mJsonBody.isNotEmpty())
                    write(request.mJsonBody.toByteArray())
                flush()
                close()
            }
            doNet(request.mType, request.mTypeToken, h, success, failed)
        }
    }

    fun map2reqBody(data: Map<String, String>) = data.map { "${it.key}=${it.value}" }.reduce { ori, add -> "$ori&$add" }

    private fun HttpURLConnection.doNet(type: Class<Result>?, typeToken: TypeToken<Result>?, h: Handler, success: Result?.() -> Unit, failed: String.() -> Unit) {
        val respCode = responseCode
        if (respCode != 200) {
//            ZInfoRecorder.e("http requester", "url: $url   response code: $respCode")
            h.post {
                FishNetException(respCode).getReasonMessage().failed()
            }
            return
        }
        try {
            val data = IS2Str(inputStream)
            h.post {
                val s = if (type == null) {
                    if (typeToken == null) {
                        null
                    } else {
                        Gson().fromJson<Result>(data, typeToken.type)
                    }
                } else if (type.name.equals("java.lang.String")) {
                    (data as? Result ?: null).success()
                    return@post
                } else Gson().fromJson<Result>(data, type)
                s.success()
            }
        } catch (ex: IOException) {
            ex.printStackTrace()
            h.post {
                "I/O错误".failed()
            }
        } catch (ex: TypeCastException) {
            ex.printStackTrace()
            h.post {
                "数据结构错误".failed()
            }
        }
    }

    private fun getConnetion(request: Requester<*>) = URL(request.mUrl.toString()).openConnection().apply {
        if (request.mSSLContext != null && this is HttpsURLConnection)
            sslSocketFactory = request.mSSLContext?.socketFactory
        connectTimeout = 3000
        readTimeout = 10000
        doInput = true
        useCaches = false
        setRequestProperty("Charset", "UTF-8")
        setRequestProperty("Connection", "Keep-Alive")
        setRequestProperty("Content-Type", if (request.mIsJsonBody) "application/json" else "application/x-www-form-urlencoded")
        request.mHeader.map { addRequestProperty(it.key, it.value) }
    } as HttpURLConnection

    private fun IS2Str(inputStream: InputStream): String {
        val reader = InputStreamReader(inputStream, "UTF-8")
        val buf = CharArray(1024)
        val sb = StringBuffer()
        var readCnt: Int
        try {
            do {
                readCnt = reader.read(buf)
                if (readCnt > 0)
                    sb.append(buf, 0, readCnt)
            } while (readCnt >= 0)
            return sb.toString()
        } catch (ex: Exception) {
            ex.printStackTrace()
            return ""
        } finally {
            try {
                reader.close()
            } catch (ex: Exception) {
                ex.printStackTrace()
            }
        }
    }
}

