@Composable
fun DropDownPref(
    key: String,
    title: String,
    modifier: Modifier = Modifier,
    summary: String? = null,
    defaultValue: String? = null,
    onValueChange: ((String) -> Unit)? = null,
    useSelectedAsSummary: Boolean = false,
    dropdownBackgroundColor: Color? = null,
    textColor: Color = MaterialTheme.colorScheme.onBackground,
    enabled: Boolean = true,
    entries: Map<String, String> = mapOf()
) {

    var expanded by rememberSaveable { mutableStateOf(false) }
    val selectionKey = stringPreferencesKey(key)
    val scope = rememberCoroutineScope()

    val datastore = LocalPrefsDataStore.current
    val prefs by remember { datastore.data }.collectAsState(initial = null)

    var value = defaultValue
    prefs?.get(selectionKey)?.also { value = it } // starting value if it exists in datastore

    fun edit(item: Map.Entry<String, String>) = run {
        scope.launch {
            try {
                datastore.edit { preferences ->
                    preferences[selectionKey] = item.key
                }
                expanded = false
                onValueChange?.invoke(item.key)
            } catch (e: Exception) {
                Log.e(
                    "DropDownPref",
                    "Could not write pref $key to database. ${e.printStackTrace()}"
                )
            }
        }
    }

    Column {
        TextPref(
            title = title,
            modifier = modifier,
            summary = when {
                useSelectedAsSummary && value != null -> entries[value]
                useSelectedAsSummary && value == null -> "Not Set"
                else -> summary
            },
            textColor = textColor,
            enabled = enabled,
            onClick = {
                expanded = true
            },
        )

        Box(
            modifier = Modifier
                .padding(start = 16.dp)
        ) {
            DropdownMenu(
                expanded = expanded,
                onDismissRequest = { expanded = false },
                modifier = if (dropdownBackgroundColor != null) Modifier.background(
                    dropdownBackgroundColor
                ) else Modifier
            ) {
                entries.forEach { item ->
                    DropdownMenuItem(
                        onClick = {
                            edit(item)
                        },
                        text = {
                            Text(
                                text = item.value,
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                    )
                }
            }
        }
    }
}

class GPSTracker(val context: Context): LocationListener {

    private val locationManager = context.getSystemService(Context.LOCATION_SERVICE) as LocationManager
    private var latitude: Double = 0.0
    private var longitude: Double = 0.0
    private var locationChangeListener: LocationChangeListener? = null

    fun startTrack(): GPSTracker{
        turnOnGPS()
        return this
    }

    fun addListener(locationChangeListener: LocationChangeListener){
        //this.locationChageListener = null
        this.locationChangeListener = locationChangeListener
    }

    fun stopTrack(){
        this.locationChangeListener = null
        turnOffGPS()
    }

    //gps permission
    @SuppressLint("MissingPermission")
    private fun turnOnGPS() {
        try {
            if (isGPSActivated()) {
                locationManager.requestLocationUpdates(
                    LocationManager.GPS_PROVIDER,
                    2000,
                    0f,
                    this
                )
                val criteria = Criteria()
                criteria.accuracy = Criteria.ACCURACY_FINE
                // BestProvider
                val provider = locationManager.getBestProvider(criteria, true) ?: ""
                // Getting last location available
                val location = locationManager.getLastKnownLocation(provider)
                if (location != null) {
                    latitude = location.latitude
                    longitude = location.longitude
                }
            }
        }catch (e: Exception) {
            e.printStackTrace()
        }
    }

    private fun turnOffGPS(){
        try {
            locationManager.removeUpdates(this)
        } catch (e: SecurityException) {
            Toast.makeText(context, "Error desactivando GPS $e",
                Toast.LENGTH_LONG).show()
        }
    }

    private fun isGPSActivated(): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP){
            if (ActivityCompat.checkSelfPermission(context,
                    Manifest.permission.ACCESS_FINE_LOCATION) !=
                PackageManager.PERMISSION_GRANTED) {

                // Should we show an explanation
                return if (ActivityCompat.shouldShowRequestPermissionRationale(
                        context as Activity,
                        Manifest.permission.ACCESS_FINE_LOCATION)){
                    ActivityCompat.requestPermissions(context,
                        arrayOf(Manifest.permission.ACCESS_FINE_LOCATION),
                        REQUEST_CODE_GPS)
                    false
                }else {
                    //No explanation needed, we can request the permissions.
                    ActivityCompat.requestPermissions(context,
                        arrayOf(Manifest.permission.ACCESS_FINE_LOCATION),
                        REQUEST_CODE_GPS)
                    false
                }
            }else {
                return true
            }
        }else {
            return true
        }
    }

    override fun onLocationChanged(p0: Location?) {
        p0?.let {
            latitude = it.latitude
            longitude = it.longitude
            locationChangeListener?.onChange(latitude, longitude)
        }
    }

    override fun onStatusChanged(p0: String?, p1: Int, p2: Bundle?) {}

    override fun onProviderEnabled(p0: String?) {}

    override fun onProviderDisabled(p0: String?) {}

